/*
 * Raspberry Pi 4 Model B - Soil Moisture Logger
 *
 * Hardware:
 *   - DFRobot Soil Moisture Sensor v2.0 (analog resistive) -> MCP3008 CH0
 *   - MCP3008 10-bit ADC on SPI0:
 *       CE0  -> GPIO8  (physical pin 24)
 *       MOSI -> GPIO10 (physical pin 19)
 *       MISO -> GPIO9  (physical pin 21)
 *       SCLK -> GPIO11 (physical pin 23)
 *   - VDD  -> 3.3 V, VREF -> 3.3 V, AGND/DGND -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o soil_logger soil_logger.c -lpigpio -lrt
 * Run:   sudo ./soil_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_BAUD       1000000    /* 1 MHz - well within MCP3008 spec */
#define SPI_FLAGS      0          /* Mode 0, active-low CE, 8-bit words */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define SAMPLE_PERIOD  1          /* seconds between readings */
#define MAX_SPI_RETRIES 3         /* retries per SPI transfer on error */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (3-byte transfer, Mode 0, MSB-first):
 *   Byte 0: 0x01                       (start bit)
 *   Byte 1: (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   Byte 2: 0x00                       (clock out remaining bits)
 *
 * Response:
 *   rx[0] = don't care
 *   rx[1] = [null bit, b9, b8] in its upper nibble
 *   rx[2] = b7..b0
 */
static int read_mcp3008(int handle, int channel, uint16_t *adc_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }
    if (adc_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01,
                   (char)((0x08 | channel) << 4),
                   0x00 };
    char rx[3] = { 0 };

    for (int attempt = 1; attempt <= MAX_SPI_RETRIES; ++attempt) {
        int ret = spiXfer(handle, tx, rx, 3);
        if (ret == 3) {
            *adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
            return 0;
        }
        fprintf(stderr,
                "Warning: SPI transfer failed (attempt %d/%d), pigpio error %d\n",
                attempt, MAX_SPI_RETRIES, ret);
        if (attempt < MAX_SPI_RETRIES) {
            usleep(10000); /* 10 ms back-off before retry */
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after %d retries\n", MAX_SPI_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers early ------------------------------ */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, Mode 0 ----------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Logger started.  SPI0 CE0 @ %d Hz, ADC CH0.\n",
           SPI_BAUD);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main sampling loop ----------------------------------------- */
    while (g_running) {
        uint16_t adc_value = 0;

        if (read_mcp3008(g_spi_handle, ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Error: failed to read ADC value\n");
        } else {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];

            if (localtime_r(&now, &tm_info) != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            } else {
                snprintf(ts, sizeof(ts), "UNKNOWN");
            }

            printf("[%s] ADC CH0: %u\n", ts, adc_value);
            fflush(stdout);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; ++i) {
            usleep(100000); /* 100 ms */
        }
    }

    /* --- Graceful cleanup ------------------------------------------- */
    printf("\nShutting down...\n");
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

