/*
 * Raspberry Pi 4 Model B — MLX91219 Hall-effect current sensor via ADS1115 ADC
 *
 * Wiring:
 *   ADS1115 ADDR  -> GND  (I2C address 0x48 on bus 1)
 *   ADS1115 SDA   -> GPIO2 (I2C bus 1 SDA)
 *   ADS1115 SCL   -> GPIO3 (I2C bus 1 SCL)
 *   ADS1115 AIN0  -> MLX91219 analog output
 *   ADS1115 GND   -> Pi GND
 *   ADS1115 VDD   -> Pi 3.3 V (or 5 V; use 3.3 V if your MLX91219 is 3.3 V tolerant)
 *
 * Build:  gcc -O2 -Wall -o current_monitor current_monitor.c -lpigpio -lrt
 * Run:    sudo ./current_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADS1115 constants (ADDR=0x48) ---- */
#define I2C_BUS          1
#define ADS1115_ADDR     0x48

#define ADS1115_REG_CONVERSION  0x00
#define ADS1115_REG_CONFIG      0x01

/* Config register bit fields (16-bit, big-endian on the bus) */
#define ADS1115_CFG_OS_BEGIN    (1u << 15)   /* Begin single conversion */
#define ADS1115_CFG_MUX_AIN0   (0x4000u)    /* AIN0 single-ended */
#define ADS1115_CFG_PGA_4_096V (0x0200u)    /* PGA = ±4.096 V */
#define ADS1115_CFG_MODE_SS    (0x0100u)    /* Single-shot mode */
#define ADS1115_CFG_DR_128SPS (0x0080u)    /* 128 samples per second */
#define ADS1115_CFG_CQUE_NONE (0x0003u)    /* Disable comparator */

#define ADS1115_CONFIG         (ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0 | \
                               ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_SS | \
                               ADS1115_CFG_DR_128SPS | ADS1115_CFG_CQUE_NONE)

/* ---- MLX91219 constants ---- */
#define MLX91219_SENSITIVITY_MV_PER_A  40.0f   /* 40 mV/A */
#define MLX91219_ZERO_CURRENT_OFFSET_MV 200.0f /* Mid-supply offset */

#define SAMPLE_PERIOD_US  500000u   /* 500 ms */
#define CONVERSION_WAIT_US 10000u   /* 10 ms (128 SPS -> ~7.8 ms) */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a 16-bit value to an ADS1115 register (big-endian on the bus).
 * Returns 0 on success, -1 on failure.
 */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteI2CBlockData(handle, reg, buf + 1, 2) < 0) {
        fprintf(stderr, "Error: i2cWriteI2CBlockData(reg=0x%02X) failed\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register (big-endian on the bus).
 * Returns 0 on success, -1 on failure.
 */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadI2CBlockData(reg=0x%02X) failed\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion and read the raw ADC count.
 * Returns 0 on success, -1 on failure.
 */
static int ads1115_read_raw(int handle, int16_t *raw_out)
{
    uint16_t config;
    uint16_t conv;

    /* Write config to start a single-shot conversion on AIN0 */
    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, ADS1115_CONFIG) < 0)
        return -1;

    /* Wait for conversion to complete (128 SPS -> ~7.8 ms; 10 ms is safe) */
    gpioDelay(CONVERSION_WAIT_US);

    /* Read the conversion result */
    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &conv) < 0)
        return -1;

    *raw_out = (int16_t)conv;
    return 0;
}

/*
 * Convert raw ADC count to current in amperes.
 * ADS1115 PGA ±4.096 V -> 1 bit = 125 µV.
 * MLX91219: 40 mV/A, mid-supply offset 200 mV.
 */
static float raw_to_current(int16_t raw)
{
    float voltage_mv = (raw * 125.0f) / 1000.0f;   /* 125 µV per count */
    float current_mv = voltage_mv - MLX91219_ZERO_CURRENT_OFFSET_MV;
    return current_mv / MLX91219_SENSITIVITY_MV;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX91219 current monitor started (ADS1115 @ 0x%02X, AIN0, 128 SPS).\n",
           ADS1115_ADDR);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t raw;

        if (ads1115_read_raw(g_i2c_handle, &raw) < 0) {
            fprintf(stderr, "Warning: ADC read failed; skipping sample.\n");
        } else {
            float current = raw_to_current(raw);
            printf("Current: %.3f A\n", current);
            fflush(stdout);
        }

        /* Sleep 500 ms, but wake early if a signal arrives */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

