#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

/* Configuration */
#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define LOG_FILE "fire_log.txt"
#define POLL_INTERVAL_US 100000
#define DEBOUNCE_US 50000
#define BUZZER_DURATION_US 2000000

/* ADS1115 config: single-shot, AIN0, ±4.096V, 128 SPS, continuous */
#define ADS1115_CONFIG_BASE 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG_DEFAULT (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE)

/* Temperature thresholds */
#define TEMP_THRESHOLD 60.0f
#define TEMP_MIN 20.0f
#define TEMP_MAX 80.0f

/* Global state */
static volatile int flame_event = 0;
static volatile uint32_t last_flame_tick = 0;
static volatile int running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

/* Function prototypes */
static int init_gpio(void);
static int init_i2c(void);
static int read_flame_sensor(void);
static int read_temperature(void);
static void log_event(const char *message);
static void fire_alarm(void);
static void flame_isr(int gpio, int level, uint32_t tick, void *userdata);
static void cleanup(void);
static void signal_handler(int sig);

/* Initialize pigpio and configure GPIO pins */
static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set flame sensor GPIO %d as input\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on flame sensor GPIO %d\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set buzzer GPIO %d as output\n", BUZZER_GPIO);
        return -1;
    }
    if (gpioWrite(BUZZER_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise buzzer GPIO %d to LOW\n", BUZZER_GPIO);
        return -1;
    }
    return 0;
}

/* Open I2C bus and configure ADS1115 for single-shot reads on AIN0 */
static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (pigpio error %d)\n",
                I2C_BUS, ADS1115_ADDR, i2c_handle);
        return -1;
    }

    /* Write config register to start a single-shot conversion on AIN0 */
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_DEFAULT >> 8) & 0xFF;
    config[2] = ADS1115_CONFIG_DEFAULT & 0xFF;
    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config register (pigpio error)\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Wait for conversion to complete (~8.5ms at 128 SPS) */
    gpioDelay(10000);
    return 0;
}

/* Read flame sensor: returns 1 if flame detected (LOW), 0 otherwise */
static int read_flame_sensor(void) {
    int level = gpioRead(FLAME_SENSOR_GPIO);
    if (level < 0) {
        fprintf(stderr, "Error: failed to read flame sensor GPIO %d\n", FLAME_SENSOR_GPIO);
        return 0;
    }
    return (level == 0) ? 1 : 0;
}

/* Read temperature from ADS1115 via I2C; returns 0 on success, -1 on error */
static int read_temperature(void) {
    char reg = ADS1115_REG_CONVERSION;
    char data[2];

    /* Point to conversion register */
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to set ADS1115 conversion register pointer\n");
        return -1;
    }

    /* Read 2 bytes (16-bit signed) */
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion data\n");
        return -1;
    }

    int16_t raw = (int16_t)(((uint8_t)data[0] << 8) | (uint8_t)data[1]);
    float voltage = (float)raw * 4.096f / 32768.0f;

    /* Map 0V-3.3V to 20C-80C */
    float temperature = (voltage / 3.3f) * (TEMP_MAX - TEMP_MIN) + TEMP_MIN;

    if (temperature > TEMP_THRESHOLD) {
        return 1;
    }
    return 0;
}

/* Log event with timestamp to file */
static void log_event(const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: log file not open\n");
        return;
    }
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

/* Activate buzzer for 2 seconds */
static void fire_alarm(void) {
    if (gpioWrite(BUZZER_GPIO, 1) != 0) {
        fprintf(stderr, "Warning: failed to activate buzzer\n");
        return;
    }
    gpioDelay(BUZZER_DURATION_US);
    if (gpioWrite(BUZZER_GPIO, 0) != 0) {
        fprintf(stderr, "Warning: failed to deactivate buzzer\n");
    }
}

/* ISR callback for flame sensor (falling edge) */
static void flame_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)level;
    (void)userdata;

    uint32_t elapsed = tick - last_flame_tick;
    if (elapsed < DEBOUNCE_US) {
        return;
    }
    last_flame_tick = tick;
    flame_event = 1;
}

/* Cleanup all resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    /* Initialize GPIO */
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    /* Initialize I2C and ADS1115 */
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    /* Register flame sensor ISR */
    if (gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, flame_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on flame sensor GPIO %d\n", FLAME_SENSOR_GPIO);
        cleanup();
        return 1;
    }

    log_event("System started");

    /* Main polling loop */
    while (running) {
        int flame = read_flame_sensor();
        int temp = read_temperature();

        if (flame) {
            log_event("Flame detected!");
        }

        if (temp == 1) {
            log_event("Temperature above threshold!");
        }

        if (flame && temp == 1) {
            log_event("Simultaneous flame and temperature event!");
            fire_alarm();
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("System shutting down");
    cleanup();
    return 0;
}

