#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define DEFAULT_SPI_DEVICE "/dev/spidev0.0"
#define DEFAULT_SPI_SPEED_HZ 1000000
#define DEFAULT_SPI_MODE 0
#define DEFAULT_SPI_BITS_PER_WORD 8
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_CURRENT_THRESHOLD 5.0
#define DEFAULT_SENSITIVITY 0.1
#define DEFAULT_LOG_FILE "current_log.txt"
#define DEFAULT_GPIO_CHIP_NAME "gpiochip4"
#define DEFAULT_GPIO_LINE 18
#define DEFAULT_SAMPLE_INTERVAL_SEC 1

#define ADC_MAX_VALUE 1023
#define ADC_VREF 3.3f

static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *fan_line = NULL;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_init(const char *device, uint32_t speed_hz, uint8_t mode, uint8_t bits_per_word) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_hz) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_adc(int fd, uint8_t channel) {
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)(0x80 | (channel << 4)), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = DEFAULT_SPI_SPEED_HZ,
        .bits_per_word = DEFAULT_SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

static float adc_to_current(int adc_value, float sensitivity) {
    float voltage = (float)adc_value * ADC_VREF / (float)(ADC_MAX_VALUE + 1);
    return voltage / sensitivity;
}

static void log_data(FILE *fp, float current, int fan_state) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Current: %.3f A, Fan: %s\n", timestamp, current, fan_state ? "ON" : "OFF");
    fflush(fp);
}

static void cleanup(void) {
    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_release(fan_line);
        fan_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(int argc, char *argv[]) {
    const char *spi_device = DEFAULT_SPI_DEVICE;
    uint32_t spi_speed_hz = DEFAULT_SPI_SPEED_HZ;
    uint8_t spi_mode = DEFAULT_SPI_MODE;
    uint8_t spi_bits_per_word = DEFAULT_SPI_BITS_PER_WORD;
    int adc_channel = DEFAULT_ADC_CHANNEL;
    float current_threshold = DEFAULT_CURRENT_THRESHOLD;
    float sensitivity = DEFAULT_SENSITIVITY;
    const char *log_file_name = DEFAULT_LOG_FILE;
    const char *gpio_chip_name = DEFAULT_GPIO_CHIP_NAME;
    int gpio_line = DEFAULT_GPIO_LINE;
    int sample_interval_sec = DEFAULT_SAMPLE_INTERVAL_SEC;

    int opt;
    while ((opt = getopt(argc, argv, "d:s:m:b:c:t:h")) != -1) {
        switch (opt) {
            case 'd':
                spi_device = optarg;
                break;
            case 's':
                spi_speed_hz = (uint32_t)strtol(optarg, NULL, 10);
                break;
            case 'm':
                spi_mode = (uint8_t)strtol(optarg, NULL, 10);
                break;
            case 'b':
                spi_bits_per_word = (uint8_t)strtol(optarg, NULL, 10);
                break;
            case 'c':
                adc_channel = (int)strtol(optarg, NULL, 10);
                break;
            case 't':
                current_threshold = strtof(optarg, NULL);
                break;
            case 'h':
                fprintf(stderr, "Usage: %s [-d spi_device] [-s spi_speed_hz] [-m spi_mode] [-b spi_bits_per_word] [-c adc_channel] [-t current_threshold] [-h]\n", argv[0]);
                return EXIT_SUCCESS;
            default:
                fprintf(stderr, "Usage: %s [-d spi_device] [-s spi_speed_hz] [-m spi_mode] [-b spi_bits_per_word] [-c adc_channel] [-t current_threshold] [-h]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    spi_fd = spi_init(spi_device, spi_speed_hz, spi_mode, spi_bits_per_word);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(log_file_name, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", log_file_name, strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    gpio_chip = gpiod_chip_open_by_name(gpio_chip_name);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", gpio_chip_name, strerror(errno));
        fclose(log_file);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    fan_line = gpiod_chip_get_line(gpio_chip, gpio_line);
    if (!fan_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", gpio_line, strerror(errno));
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(fan_line, "mlx91219_fan", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", gpio_line, strerror(errno));
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX91219 current monitor started. SPI: %s @ %u Hz, ADC ch %d, threshold %.2f A, sensitivity %.2f mV/A, log: %s\n",
           spi_device, spi_speed_hz, adc_channel, current_threshold, sensitivity, log_file_name);

    while (program_running) {
        int adc_value = read_adc(spi_fd, (uint8_t)adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, skipping sample\n");
            sleep(sample_interval_sec);
            continue;
        }

        if (adc_value == 0 || adc_value == ADC_MAX_VALUE) {
            fprintf(stderr, "Warning: ADC reading at rail (%d) - sensor absent or wiring fault\n", adc_value);
        }

        float current = adc_to_current(adc_value, sensitivity);
        int fan_state = (current > current_threshold) ? 1 : 0;

        if (gpiod_line_set_value(fan_line, fan_state) < 0) {
            fprintf(stderr, "Error setting fan GPIO: %s\n", strerror(errno));
        }

        log_data(log_file, current, fan_state);
        printf("Current: %.3f A, Fan: %s\n", current, fan_state ? "ON" : "OFF");

        sleep(sample_interval_sec);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

