#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define LOG_FILE "co_log.txt"
#define READ_INTERVAL 5
#define MAX_RETRIES 3

/* Calibration parameters (example values) */
#define CO_SENSITIVITY 0.01
#define CO_OFFSET 0.5
#define CO_LOGARITHMIC_SCALE 100.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_raw_co(int handle, int *raw_value) {
    char buf[2];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cReadDevice(handle, buf, 2);
        if (result == 2) {
            *raw_value = (buf[0] << 8) | buf[1];
            return 0;
        }
        fprintf(stderr, "I2C read failed (attempt %d/%d): %d\n", attempt + 1, MAX_RETRIES, result);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(100000); /* 100 ms backoff */
        }
    }
    return -1;
}

static double calculate_co_ppm(int raw_value) {
    double resistance = (double)raw_value;
    double co_ppm = CO_SENSITIVITY * resistance + CO_OFFSET;
    if (co_ppm < 0.0) co_ppm = 0.0;
    return co_ppm;
}

static int log_co_ppm(double ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s, CO: %.2f PPM\n", timestamp, ppm);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_value;
        if (read_raw_co(i2c_handle, &raw_value) != 0) {
            fprintf(stderr, "Failed to read CO sensor after %d attempts. Retrying in %d seconds.\n",
                    MAX_RETRIES, READ_INTERVAL);
            sleep(READ_INTERVAL);
            continue;
        }

        double ppm = calculate_co_ppm(raw_value);

        if (log_co_ppm(ppm) != 0) {
            fprintf(stderr, "Failed to log CO PPM value.\n");
        }

        printf("CO: %.2f PPM (raw: %d)\n", ppm, raw_value);

        sleep(READ_INTERVAL);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

