#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x48
#define ALERT_THRESHOLD 25.0
#define LOG_FILE "co_log.txt"
#define ALERT_LOG_FILE "alert_log.txt"
#define READ_INTERVAL_SEC 5

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float co_ppm;
    float no2_ppm;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
float calculate_co_ppm(unsigned int ox_value);
void log_data(sensor_data_t data);
void log_alert(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the MICS-4514
int read_sensor_data(sensor_data_t *data) {
    unsigned char buffer[4];
    int result = i2cReadDevice(i2c_handle, (char *)buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Combine the two 8-bit values into a 16-bit value
    unsigned int ox_value = (buffer[0] << 8) | buffer[1];
    unsigned int no2_value = (buffer[2] << 8) | buffer[3];

    data->co_ppm = calculate_co_ppm(ox_value);
    data->no2_ppm = (float)no2_value; // Assuming NO2 is directly proportional to the 16-bit value

    return 0;
}

// Calculate CO concentration in PPM
float calculate_co_ppm(unsigned int ox_value) {
    // Placeholder conversion formula (replace with actual calibration curve)
    // This is a simplified example; a real implementation would require calibration data
    return (float)ox_value * 0.1f;
}

// Log sensor data to a file
void log_data(sensor_data_t data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, CO: %.2f PPM, NO2: %.2f PPM\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            data.co_ppm, data.no2_ppm);

    fclose(fp);
}

// Log an alert to a file
void log_alert(float co_ppm) {
    FILE *fp = fopen(ALERT_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alert log file: %s\n", ALERT_LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, ALERT: CO level exceeded threshold! CO: %.2f PPM\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            co_ppm);

    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and termination
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);

            if (sensor_data.co_ppm > ALERT_THRESHOLD) {
                log_alert(sensor_data.co_ppm);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds.\n", READ_INTERVAL_SEC);
        }

        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

