#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0 (GPIO8)
#define SPI_SPEED 1000000   // 1 MHz
#define SPI_FLAGS 0         // Mode 0, active low CS
#define LED_GPIO 27
#define THRESHOLD 0.7
#define SAMPLE_INTERVAL_US 1000  // 1 ms
#define WINDOW_DURATION_US 100000 // 100 ms
#define NUM_SAMPLES 100
#define ADC_MAX 1023.0       // 10-bit ADC

// Global variables
static volatile int running = 1;
static int spi_handle = -1;

// Function prototypes
int read_mcp3008(int channel);
double calculate_rms(int *samples, int num_samples);
void log_data(double mic1_rms, double mic2_rms);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

// Read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format (3 bytes):
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel << 4
    // Byte 2: Don't care (0x00)
    char tx_buf[3] = {0x01, (char)(0x80 | (channel << 4)), 0x00};
    char rx_buf[3] = {0};

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | (rx_buf[2] & 0xFF);
    return adc_value;
}

// Calculate RMS value of an array of samples
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double sample = (double)samples[i];
        sum_of_squares += sample * sample;
    }
    return sqrt(sum_of_squares / num_samples);
}

// Log data to CSV file
void log_data(double mic1_rms, double mic2_rms) {
    FILE *fp = fopen("audio_events.csv", "a");
    if (fp == NULL) {
        perror("Error opening audio_events.csv");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.4f,%.4f\n", timestamp, mic1_rms, mic2_rms);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output and ensure it's off
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int samples1[NUM_SAMPLES];
        int samples2[NUM_SAMPLES];
        int valid_samples1 = 0;
        int valid_samples2 = 0;

        // Sample both microphones for the window duration
        for (int i = 0; i < NUM_SAMPLES && running; i++) {
            int val1 = read_mcp3008(0);  // Channel 0 for mic1
            int val2 = read_mcp3008(1);  // Channel 1 for mic2

            if (val1 >= 0) {
                samples1[valid_samples1++] = val1;
            }
            if (val2 >= 0) {
                samples2[valid_samples2++] = val2;
            }

            gpioDelay(SAMPLE_INTERVAL_US);
        }

        // Calculate RMS values
        double mic1_rms = 0.0;
        double mic2_rms = 0.0;

        if (valid_samples1 > 0) {
            mic1_rms = calculate_rms(samples1, valid_samples1);
        }
        if (valid_samples2 > 0) {
            mic2_rms = calculate_rms(samples2, valid_samples2);
        }

        // Check threshold and control LED
        if (mic1_rms > THRESHOLD || mic2_rms > THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
            gpioDelay(500000);  // 500 ms
            gpioWrite(LED_GPIO, 0);
        }

        // Log data
        log_data(mic1_rms, mic2_rms);

        printf("Mic1 RMS: %.4f, Mic2 RMS: %.4f\n", mic1_rms, mic2_rms);
    }

    // Cleanup
    cleanup();
    printf("Audio monitoring stopped.\n");
    return 0;
}

