#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TCS34725_I2C_ADDR 0x29
#define TCS34725_ENABLE   0x00
#define TCS34725_ATIME    0x01
#define TCS34725_ID       0x12
#define TCS34725_CONTROL  0x0F
#define TCS34725_CDATA    0x14
#define TCS34725_RDATA    0x16
#define TCS34725_GDATA    0x18
#define TCS34725_BDATA    0x1A

#define EXPECTED_ID 0x44
#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 1000000
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
    }
    return rc;
}

static int i2c_read_word(int handle, uint8_t reg) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read word failed (reg 0x%02X): %d\n", reg, rc);
    }
    return rc;
}

static int init_tcs34725(int handle) {
    int id = i2c_read_byte(handle, TCS34725_ID);
    if (id < 0) {
        fprintf(stderr, "Cannot read ID register\n");
        return -1;
    }
    if ((id & 0x0F) != EXPECTED_ID) {
        fprintf(stderr, "Unexpected ID register value 0x%02X (expected lower 4 bits 0x%02X)\n", id, EXPECTED_ID);
        return -1;
    }

    if (i2c_write_byte(handle, TCS34725_ATIME, 0xFF) < 0) return -1;
    if (i2c_write_byte(handle, TCS34725_CONTROL, 0x01) < 0) return -1;

    if (i2c_write_byte(handle, TCS34725_ENABLE, 0x01) < 0) return -1;
    gpioDelay(3000);
    if (i2c_write_byte(handle, TCS34725_ENABLE, 0x01 | 0x02) < 0) return -1;

    return 0;
}

static int read_color_data(int handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    *clear = (uint16_t)i2c_read_word(handle, TCS34725_CDATA);
    *red   = (uint16_t)i2c_read_word(handle, TCS34725_RDATA);
    *green = (uint16_t)i2c_read_word(handle, TCS34725_GDATA);
    *blue  = (uint16_t)i2c_read_word(handle, TCS34725_BDATA);
    return 0;
}

static int log_color_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%u,%u,%u,%u\n", ts, clear, red, green, blue) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, TCS34725_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_tcs34725(g_i2c_handle) != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    g_log_file = fopen("color_log.csv", "a");
    if (g_log_file == NULL) {
        perror("fopen(color_log.csv)");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,clear,red,green,blue\n");
        fflush(g_log_file);
    }

    int consecutive_errors = 0;

    while (g_running) {
        uint16_t clear, red, green, blue;
        if (read_color_data(g_i2c_handle, &clear, &red, &green, &blue) == 0) {
            consecutive_errors = 0;
            if (log_color_data(g_log_file, clear, red, green, blue) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read failed (%d consecutive)\n", consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Too many consecutive I2C errors; exiting\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (g_log_file != NULL) {
        fflush(g_log_file);
