#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023
#define ADC_VREF 3.3
#define SENSITIVITY 0.1
#define OFFSET 0.05
#define OVERCURRENT_THRESHOLD 10.0
#define MOTOR_SHUTDOWN_PIN 17
#define LOG_FILE "current_log.csv"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_SPI_RETRIES 3

static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *shutdown_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0
    };

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_SPI_RETRIES, strerror(errno));
        if (attempt < MAX_SPI_RETRIES - 1) {
            usleep(10000);
        }
    }
    return -1;
}

static float read_current(void) {
    int adc_value = read_mcp3008(ADC_CHANNEL);
    if (adc_value < 0) {
        fprintf(stderr, "Failed to read ADC value\n");
        return -1.0f;
    }

    float voltage = (float)adc_value / (float)ADC_MAX_VALUE * ADC_VREF;
    float current = (voltage - OFFSET) / SENSITIVITY;
    return current;
}

static void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file);
}

static void shutdown_motor(void) {
    if (shutdown_line) {
        gpiod_line_set_value(shutdown_line, 0);
        printf("Motor shutdown triggered\n");
    }
}

static void enable_motor(void) {
    if (shutdown_line) {
        gpiod_line_set_value(shutdown_line, 1);
        printf("Motor enabled\n");
    }
}

static void cleanup(void) {
    if (shutdown_line) {
        gpiod_line_set_value(shutdown_line, 1);
        gpiod_line_release(shutdown_line);
        shutdown_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
