#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define PRESSURE_REG   0x00
#define MAX_RETRIES    3
#define SAMPLE_PERIOD  1.0
#define LOG_FILE       "pressure_log.csv"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: pigpio error %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_pressure(uint16_t *raw_out)
{
    char buf[2];
    int  rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cReadI2CBlockData(g_i2c_handle, PRESSURE_REG, buf, 2);
        if (rc == 2) {
            *raw_out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "I2C read attempt %d/%d failed (reg 0x%02X): pigpio error %d\n",
                attempt + 1, MAX_RETRIES, PRESSURE_REG, rc);
        if (attempt < MAX_RETRIES - 1)
            time_sleep(0.1);
    }
    return -1;
}

static double convert_to_kpa(uint16_t raw)
{
    return ((double)raw / 65535.0) * 500.0;
}

static int log_data(double pressure_kpa)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.2f\n", ts, pressure_kpa) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
        fprintf(stderr, "Error writing CSV header\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error flushing header\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90817 pressure logger started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (g_running) {
        uint16_t raw = 0;
        if (read_pressure(&raw) == 0) {
            double pressure = convert_to_kpa(raw);
            if (log_data(pressure) != 0)
                fprintf(stderr, "Logging failed for reading %u\n", raw);
        } else {
            fprintf(stderr, "Failed to read pressure after %d attempts\n", MAX_RETRIES);
        }
        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

