#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define PRESSURE_THRESHOLD 105.0f
#define RETRY_COUNT 3
#define RETRY_DELAY_US 100000

/* ADS1115 registers */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

/* Config: single-shot, AIN0 vs GND, 128 SPS, ±6.144V, continuous */
#define ADS1115_CONFIG_BASE 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_6_144V 0x0200
#define ADS1115_CONFIG_MODE_CONT 0x0000
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ads1115_init(void) {
    uint16_t config = ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_6_144V | ADS1115_CONFIG_MODE_CONT |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;
    uint8_t buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(i2c_handle, (char *)buf, 3) < 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config\n");
        return -1;
    }
    return 0;
}

static int ads1115_read_raw(int16_t *raw) {
    uint8_t reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) < 0) {
        fprintf(stderr, "Error: Failed to set ADS1115 conversion register\n");
        return -1;
    }
    uint8_t buf[2];
    if (i2cReadDevice(i2c_handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion\n");
        return -1;
    }
    *raw = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static float raw_to_voltage(int16_t raw) {
    /* PGA ±6.144V => 1 bit = 125 uV */
    return (float)raw * 0.000125f;
}

static float voltage_to_pressure(float v) {
    /* 0V = 0 kPa, 5V = 400 kPa */
    return v * 80.0f;
}

static float voltage_to_temperature(float v) {
    /* Simplified NTC: 1V = 0°C, 2V = 100°C */
    if (v <= 0.0f) return -273.15f;
    return (v - 1.0f) * 100.0f;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ads1115_init() < 0) {
        fprintf(stderr, "Error: ADS1115 initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90834 Pressure Sensor Reader (ADS1115 ADC)\n");
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        int16_t raw = 0;
        int success = 0;

        for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
            if (ads1115_read_raw(&raw) == 0) {
                success = 1;
                break;
            }
            gpioDelay(RETRY_DELAY_US);
        }

        if (!success) {
            fprintf(stderr, "Error: Failed to read ADS1115 after %d attempts\n", RETRY_COUNT);
            gpioDelay(1000000);
            continue;
        }

        float voltage = raw_to_voltage(raw);
        float pressure = voltage_to_pressure(voltage);
        float temperature = voltage_to_temperature(voltage);

        printf("Pressure: %.2f kPa | Temperature: %.2f °C\n", pressure, temperature);

        if (pressure > PRESSURE_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

