#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* Configuration */
#define SPI_CHANNEL      0          /* MCP3008 on SPI0 CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX          1023       /* 10-bit ADC */
#define VREF             3.3        /* MCP3008 reference voltage */
#define SENSITIVITY      0.066      /* MLX91209: 66 mV/A */
#define ZERO_CURRENT_VCC 1.65       /* Vcc/2 at zero current */
#define CURRENT_THRESHOLD 10.0      /* Overcurrent threshold (A) */
#define SHUTDOWN_PIN     27         /* GPIO27 to trigger motor shutdown */
#define SAMPLE_PERIOD_US 100000     /* 100 ms */
#define LOG_FILE         "current_log.txt"

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read 10-bit value from MCP3008 (single-ended)                       */
/* Returns 0-1023 on success, -1 on error                              */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI protocol: 3 bytes
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel)
     *   Byte 2: 0x00  (clock out remaining bits)
     * Response: 10-bit result in rx[1] (low 2 bits) and rx[2] (8 bits)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value to current (A)                                    */
/* ------------------------------------------------------------------ */
static float adc_to_current(int adc_value)
{
    float voltage = (adc_value / (float)ADC_MAX) * VREF;
    return (voltage - ZERO_CURRENT_VCC) / SENSITIVITY;
}

/* ------------------------------------------------------------------ */
/* Log a reading with timestamp                                        */
/* ------------------------------------------------------------------ */
static void log_reading(float current)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];

    if (t == NULL) {
        strncpy(timestamp, "UNKNOWN", sizeof(timestamp));
        timestamp[sizeof(timestamp) - 1] = '\0';
    } else {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    }

    if (fprintf(log_file, "%s, Current: %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Log an overcurrent event                                           */
/* ------------------------------------------------------------------ */
static void log_overcurrent(float current)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];

    if (t == NULL) {
        strncpy(timestamp, "UNKNOWN", sizeof(timestamp));
        timestamp[sizeof(timestamp) - 1] = '\0';
    } else {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    }

    if (fprintf(log_file, "%s, OVERCURRENT: %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure shutdown pin is LOW before terminating */
    gpioWrite(SHUTDOWN_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure shutdown pin as output, initially LOW */
    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", SHUTDOWN_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(SHUTDOWN_PIN, 0);

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Motor current monitoring started. Press Ctrl+C to exit.\n");
    printf("Logging to '%s'. Threshold: %.1f A\n", LOG_FILE, CURRENT_THRESHOLD);

    /* Main sampling loop */
    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, retrying in 100 ms...\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float current = adc_to_current(adc_value);
        log_reading(current);

        if (current > CURRENT_THRESHOLD) {
            printf("OVERCURRENT: %.2f A exceeds threshold %.1f A\n",
                   current, CURRENT_THRESHOLD);
            log_overcurrent(current);

            /* Trigger motor shutdown */
            if (gpioWrite(SHUTDOWN_PIN, 1) < 0) {
                fprintf(stderr, "Failed to set shutdown pin HIGH\n");
            }
            printf("Motor shutdown triggered (GPIO %d HIGH).\n", SHUTDOWN_PIN);
            break;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

