    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; continuing\n");
        } else {
            float ppm = calculate_methane_ppm(adc_value);
            if (log_methane_level(ppm) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
            check_leak_alarm(ppm);
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

