#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000 // 1 second

// ADS1115 Registers
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

// ADS1115 Config: AIN0 single-ended, +/-4.096V, 128 SPS, continuous mode
#define ADS1115_CONFIG_BASE 0x8000 // OS bit (start conversion)
#define ADS1115_CONFIG_MUX_AIN0 0x4000 // AIN0 vs GND
#define ADS1115_CONFIG_PGA_4_096V 0x0200 // +/-4.096V
#define ADS1115_CONFIG_DR_128SPS 0x0080 // 128 SPS
#define ADS1115_CONFIG_MODE_CONT 0x0000 // Continuous conversion

// Sensor Calibration
#define V_OFFSET 0.5f // Volts at 0 kPa
#define SENSITIVITY 0.1f // Volts per kPa
#define MIN_PRESSURE 0.0f
#define MAX_PRESSURE 100.0f

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(void);
int read_ads1115(int16_t *raw_value);
float convert_to_pressure(int16_t raw_value);
int log_pressure(float pressure);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Initialize I2C communication with ADS1115
int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, ADS1115_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw 16-bit ADC value from ADS1115
int read_ads1115(int16_t *raw_value) {
    char config[3];
    char reg;
    char buf[2];
    int16_t val;

    // Write config to start continuous conversion on AIN0
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_MODE_CONT);
    if (i2cWriteDevice(i2c_handle, config, 2) < 0) {
        fprintf(stderr, "Error writing ADS1115 config\n");
        return -1;
    }

    // Wait for conversion to complete (128 SPS -> ~7.8ms, use 10ms for safety)
    gpioDelay(10000);

    // Read conversion register
    reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Error writing ADS1115 conversion register address\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion\n");
        return -1;
    }

    val = (buf[0] << 8) | buf[1];
    *raw_value = val;
    return 0;
}

// Convert raw ADC value to pressure in kPa
float convert_to_pressure(int16_t raw_value) {
    float voltage = (float)raw_value * 4.096f / 32768.0f; // 4.096V full scale
    float pressure = (voltage - V_OFFSET) / SENSITIVITY;
    return pressure;
}

// Log pressure reading to file with ISO-8601 timestamp
int log_pressure(float pressure) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1;
    }

    if (pressure >= MIN_PRESSURE && pressure <= MAX_PRESSURE) {
        fprintf(fp, "%s, %.2f kPa\n", timestamp, pressure);
        printf("%s, %.2f kPa\n", timestamp, pressure);
    } else {
        fprintf(stderr, "Error: Pressure reading %.2f kPa out of valid range [%.1f, %.1f]\n", pressure, MIN_PRESSURE, MAX_PRESSURE);
    }

    fclose(fp);
    return 0;
}

int main(void) {
    int16_t raw_value;
    float pressure;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Starting pressure monitoring. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (read_ads1115(&raw_value) == 0) {
            pressure = convert_to_pressure(raw_value);
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Error reading pressure data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

