#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"
#define EMAIL_RECIPIENT_NAME "Recipient Name"
#define EMAIL_SENDER "sender@example.com"
#define EMAIL_SENDER_NAME "Sender Name"
#define EMAIL_SUBJECT "Humidity Alert"
#define EMAIL_BODY "Subject: %s\nFrom: %s <%s>\nTo: %s <%s>\n\nHumidity: %.2f%%\nTemperature: %.2fC\n"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3208 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x00, 0x00, 0x00};
    unsigned char rx[3] = {0x00, 0x00, 0x00};

    tx[0] = 0x01;
    tx[1] = (0x08 | channel) << 4;
    tx[2] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx[1] & 0x0F) << 8) | rx[2];
    return adc_value;
}

float convert_adc_to_voltage(int adc_value) {
    return (float)adc_value * 5.0 / 4095.0;
}

float calculate_humidity(float voltage) {
    return (voltage - 0.824) / 0.0315 * 100.0;
}

float calculate_temperature(float voltage) {
