#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

/* Configuration */
#define SPI_CHANNEL 0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED 1000000      /* 1 MHz */
#define SPI_FLAGS 0             /* Mode 0, active-low CS handled by pigpio */
#define ADC_CHANNELS 3         /* X, Y, Z */
#define ADC_RESOLUTION 1024.0  /* 10-bit ADC */
#define ADC_VREF 3.3           /* MCP3008 Vref */
#define ADXL335_VREF 1.65      /* 0g point */
#define ADXL335_SENSITIVITY 0.3 /* 300 mV/g */
#define IMPACT_THRESHOLD 2.0   /* g */
#define SAMPLE_RATE 100        /* Hz */
#define LOG_FILE "impact_log.txt"

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a single-ended channel from MCP3008 via SPI */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    /* pigpio's spiXfer manages CS automatically on the channel */
    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* Convert ADC value to acceleration in g */
static double adc_to_g(int adc_value) {
    double voltage = (adc_value / ADC_RESOLUTION) * ADC_VREF;
    return (voltage - ADXL335_VREF) / ADXL335_SENSITIVITY;
}

/* Log a data line with timestamp */
static void log_data(int x, int y, int z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file);
}

/* Log an impact line with timestamp */
static void log_impact(int x, int y, int z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

