    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction failed");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADXL335 impact logger started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        int x = read_mcp3008(0);
        int y = read_mcp3008(1);
        int z = read_mcp3008(2);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(1000000 / SAMPLE_RATE);
            continue;
        }

        /* Validate ADC range (10-bit) */
        if (x < 0 || x >= ADC_RESOLUTION || y < 0 || y >= ADC_RESOLUTION || z < 0 || z >= ADC_RESOLUTION) {
            fprintf(stderr, "ADC value out of range: X=%d Y=%d Z=%d\n", x, y, z);
