#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* Si1172-A30-GMR I2C default 7-bit address */
#define SI1172_ADDR 0x49

/* Si1172 register addresses (command register 0xC0 is used for all commands) */
#define SI1172_REG_COMMAND 0xC0
#define SI1172_REG_FIFO_DATA 0xC1
#define SI1172_REG_FIFO_DATA2 0xC2
#define SI1172_REG_FIFO_DATA3 0xC3
#define SI1172_REG_FIFO_DATA4 0xC4

/* Si1172 command codes */
#define SI1172_CMD_RESET 0x01
#define SI1172_CMD_START 0x11
#define SI1172_CMD_STOP 0x12

/* Error flags */
#define ERROR_OK 0
#define ERROR_READ 1
#define ERROR_SENSOR 2

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a command to the Si1172 command register */
static int si1172_write_command(int handle, uint8_t cmd) {
    int rc = i2cWriteByteData(handle, SI1172_REG_COMMAND, cmd);
    if (rc < 0) {
        fprintf(stderr, "Error writing command 0x%02X to Si1172: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

/* Read a 16-bit big-endian value from two consecutive registers */
static int si1172_read_16bit(int handle, uint8_t reg_low, uint16_t *out) {
    int low = i2cReadByteData(handle, reg_low);
    if (low < 0) {
        fprintf(stderr, "Error reading low byte from reg 0x%02X: %d\n", reg_low, low);
        return -1;
    }
    int high = i2cReadByteData(handle, reg_low + 1);
    if (high < 0) {
        fprintf(stderr, "Error reading high byte from reg 0x%02X: %d\n", reg_low + 1, high);
        return -1;
    }
    *out = ((uint16_t)high << 8) | (uint16_t)low;
    return 0;
}

/* Read raw PPG samples from the Si1172 FIFO */
static int si1172_read_ppg(int handle, uint16_t *ir, uint16_t *red) {
    int rc;

    /* Trigger a measurement by writing the START command */
    rc = si1172_write_command(handle, SI1172_CMD_START);
    if (rc < 0) {
        return -1;
    }

    /* Wait for measurement to complete (poll the command register) */
    for (int i = 0; i < 100; i++) {
        gpioDelay(1000); /* 1 ms */
        int cmd = i2cReadByteData(handle, SI1172_REG_COMMAND);
        if (cmd < 0) {
            fprintf(stderr, "Error polling command register: %d\n", cmd);
            return -1;
        }
        if ((cmd & 0x0F) == 0) {
            break; /* measurement complete */
        }
    }

    /* Read 4 bytes from the FIFO data registers (IR, RED, unused, unused) */
    rc = si1172_read_16bit(handle, SI1172_REG_FIFO_DATA, ir);
    if (rc < 0) {
        return -1;
    }
    rc = si1172_read_16bit(handle, SI1172_REG_FIFO_DATA2, red);
    if (rc < 0) {
        return -1;
    }

    return 0;
}

/* Log data to the CSV file */
static void log_data(FILE *fp, time_t timestamp, int hr, int spo2, int error_flag) {
    fprintf(fp, "%ld,%d,%d,%d\n", (long)timestamp, hr, spo2, error_flag);
    fflush(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1172 address */
    g_i2c_handle = i2cOpen(1, SI1172_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n", SI1172_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    g_log_file = fopen("biometric_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,hr_bpm,spo2_pct,error_flag\n");
        fflush(g_log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not register SIGINT handler\n");
    }

    /* Reset the Si1172 sensor */
    if (si1172_write_command(g_i2c_handle, SI1172_CMD_RESET) < 0) {
        fprintf(stderr, "Warning: Si1172 reset failed; continuing anyway\n");
    }
    gpioDelay(10000); /* 10 ms settle time after reset */

    /* Main sampling loop */
    while (g_running) {
        time_t current_time = time(NULL);
        uint16_t ir_value = 0, red_value = 0;
        int error_flag = ERROR_OK;

        /* Read raw PPG samples */
        if (si1172_read_ppg(g_i2c_handle, &ir_value, &red_value) < 0) {
            error_flag = ERROR_READ;
            fprintf(stderr, "Error reading PPG data\n");
        }

        /* Log the data */
        log_data(g_log_file, current_time, (int)ir_value, (int)red_value, error_flag);

        /* Sleep for 1 second (pigpio uses microseconds) */
        gpioDelay(1000000);
    }

    /* Graceful cleanup */
    fprintf(stderr, "\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

