#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL_1 0
#define ADC_CHANNEL_2 1
#define NUM_SAMPLES 1000
#define GAIN 1.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx_buf[3] = {0};

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

int main(int argc, char *argv[]) {
    double gain = GAIN;
    if (argc > 1) {
        gain = atof(argv[1]);
        if (gain <= 0.0) {
            fprintf(stderr, "Gain must be a positive number.\n");
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Audio Sampling and Noise Cancellation\n");
    printf("Gain: %.2f\n", gain);
    printf("Press Ctrl+C to exit.\n");

    int16_t audio_data[NUM_SAMPLES];
    int16_t audio_data1[NUM_SAMPLES];
    int16_t audio_data2[NUM_SAMPLES];

    for (int i = 0; i < NUM_SAMPLES; i++) {
        if (!running) break;

        int adc_value1 = read_mcp3008(ADC_CHANNEL_1);
        int adc_value2 = read_mcp3008(ADC_CHANNEL_2);

        if (adc_value1 < 0 || adc_value2 < 0) {
            fprintf(stderr, "Error reading ADC values. Exiting.\n");
            break;
        }

        audio_data1[i] = (int16_t)adc_value1;
        audio_data2[i] = (int16_t)adc_value2;
        audio_data[i] = (int16_t)(audio_data1[i] - audio_data2[i] * gain);
    }

    printf("\nAudio Data (Gain: %.2f)\n", gain);
    for (int i = 0; i < NUM_SAMPLES; i++) {
        printf("%d\n", audio_data[i]);
    }

    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

