#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8

#define BUZZER_GPIO_LINE 18
#define BUZZER_CHIP "gpiochip4"

#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ambient_temp(void) {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s; using default 25.0 C\n", AMBIENT_TEMP_FILE);
        return 25.0;
    }
    char line[16];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Warning: failed to read %s; using default 25.0 C\n", AMBIENT_TEMP_FILE);
        fclose(fp);
        return 25.0;
    }
    fclose(fp);
    char *endptr;
    double temp = strtod(line, &endptr);
    if (endptr == line) {
        fprintf(stderr, "Warning: invalid temperature in %s; using default 25.0 C\n", AMBIENT_TEMP_FILE);
        return 25.0;
    }
    return temp;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((channel & 0x07) << 4) | 0x80,
        0x00
    };
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static double compensate_voltage(int adc_value, double ambient_temp) {
    double voltage = (adc_value / 1023.0) * 3.3;
    return voltage + (ambient_temp - 25.0) * 0.001;
}

static int log_data(int adc_value, double voltage, double compensated_voltage, double ambient_temp, int flame_detected) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_fp, "%s,%d,%.4f,%.4f,%.2f,%d\n",
            timestamp, adc_value, voltage, compensated_voltage, ambient_temp, flame_detected);
    fflush(log_fp);
    return 0;
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return 1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        cleanup();
        return 1;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        cleanup();
        return 1;
    }

    unsigned char bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name(BUZZER_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO_LINE);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "flame_sensor", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log file");
        cleanup();
        return 1;
    }

    double ambient_temp = read_ambient_temp();
    printf("Ambient temperature: %.2f C\n", ambient_temp);

    while (running) {
        int adc_value = -1;
        int retries = 0;
        while (retries < MAX_RETRIES && running) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0 && adc_value <= 1023) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                usleep(10000);
            }
        }

        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Error: SPI read failed after %d retries, skipping iteration\n", MAX_RETRIES);
            log_data(-1, -1.0, -1.0, ambient_temp, 0);
            gpiod_line_set_value(buzzer_line, 0);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        double voltage = (adc_value / 1023.0) * 3.3;
        double compensated_voltage = compensate_voltage(adc_value, ambient_temp);
        int flame_detected = (compensated_voltage > 1.0) ? 1 : 0;

        log_data(adc_value, voltage, compensated_voltage, ambient_temp, flame_detected);

        if (gpiod_line_set_value(buzzer_line, flame_detected) < 0) {
            perror("gpiod_line_set_value");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

