#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define LED_PIN     17
#define WATER_LEVEL_THRESHOLD_HIGH  75
#define WATER_LEVEL_THRESHOLD_LOW   70
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_US 5000000
#define SPI_RETRY_DELAY_US  100000

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_json_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)(0x80 | (channel << 4)),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, pigpio_error(ret));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calculate_percentage(int adc_value)
{
    if (adc_value < 0) return 0;
    if (adc_value > 1023) return 100;
    return (adc_value * 100) / 1023;
}

static void log_water_level(int percentage)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%03ldZ", ts.tv_nsec / 1000000);

    if (g_json_file) {
        fprintf(g_json_file, "  {\"timestamp\": \"%s\", \"water_level\": %d}\n",
                timestamp, percentage);
        fflush(g_json_file);
    }
    printf("%s, Water Level: %d%%\n", timestamp, percentage);
}

static void control_led(int percentage)
{
    static int led_state = 0;
    if (percentage > WATER_LEVEL_THRESHOLD_HIGH && !led_state) {
        if (gpioWrite(LED_PIN, 1) == 0) {
            led_state = 1;
            printf("LED ON (water level > %d%%)\n", WATER_LEVEL_THRESHOLD_HIGH);
        }
    } else if (percentage < WATER_LEVEL_THRESHOLD_LOW && led_state) {
        if (gpioWrite(LED_PIN, 0) == 0) {
            led_state = 0;
            printf("LED OFF (water level < %d%%)\n", WATER_LEVEL_THRESHOLD_LOW);
        }
    }
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();

    if (g_json_file) {
        fprintf(g_json_file, "]\n");
        fclose(g_json_file);
        g_json_file = NULL;
    }
