    if (file_size == 0) {
        fprintf(log_file, "Timestamp,FlowRate_LPM\n");
        fflush(log_file);
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float flow_rate = adc_to_flow(adc_value);
        if (flow_rate < 0.0f) {
            fprintf(stderr, "Invalid flow rate, skipping log entry\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (log_data(flow_rate) != 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

