#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_RAW 300
#define DEFAULT_MAX_RAW 700
#define DEFAULT_MOISTURE_THRESHOLD 30
#define DEFAULT_LOGGING_FREQUENCY 60
#define DEFAULT_EMAIL_RECIPIENT "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG "/etc/msmtprc"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static int spi_channel = DEFAULT_SPI_CHANNEL;
static int adc_channel = DEFAULT_ADC_CHANNEL;
static int min_raw = DEFAULT_MIN_RAW;
static int max_raw = DEFAULT_MAX_RAW;
static int moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
static int logging_frequency = DEFAULT_LOGGING_FREQUENCY;
static char *email_recipient = DEFAULT_EMAIL_RECIPIENT;
static char *msmtp_config = DEFAULT_MSMTP_CONFIG;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calibrate_moisture(int raw_value) {
    if (raw_value < min_raw) raw_value = min_raw;
    if (raw_value > max_raw) raw_value = max_raw;
    return (int)(((float)(raw_value - min_raw) / (max_raw - min_raw)) * 100.0f);
}

static void send_email_alert(int moisture_percent) {
    if (moisture_percent >= moisture_threshold) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    char body[256];
    snprintf(body, sizeof(body),
             "Subject: Plant Watering Alert\n\n"
             "Moisture level below threshold.\n"
             "Timestamp: %s\n"
             "Moisture: %d%%\n"
             "Threshold: %d%%\n",
             timestamp, moisture_percent, moisture_threshold);
    FILE *mail = popen("msmtp " + email_recipient, "w");
    if (!mail) {
        fprintf(stderr, "Error: Failed to open msmtp pipe\n");
        return;
    }
    fprintf(mail, "From: sender@example.com\n");
    fprintf(mail, "To: %s\n", email_recipient);
    fprintf(mail, "Subject: Plant Watering Alert\n");
    fprintf(mail, "\n");
    fprintf(mail, body);
    int status = pclose(mail);
    if (status == -1) {
        fprintf(stderr, "Error: pclose failed\n");
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", WEXITSTATUS(status));
    } else if (WIFSIGNALED(status)) {
        fprintf(stderr, "Error: msmtp killed by signal %d\n", WTERMSIG(status));
    }
}

static void log_data(int moisture_percent) {
    FILE *fp = fopen("plant_data.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error: Cannot open plant_data.txt for appending\n");
        return;
    }
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(fp, "%s, %d\n", timestamp, moisture_percent);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:a:m:M:t:f:r:c:")) != -1) {
        switch (opt) {
            case 's': spi_channel = atoi(optarg); break;
            case 'a': adc_channel = atoi(optarg); break;
            case 'm': min_raw = atoi(optarg); break;
            case 'M': max_raw = atoi(optarg); break;
            case 't': moisture_threshold = atoi(optarg); break;
            case 'f': logging_frequency = atoi(optarg); break;
            case 'r': email_recipient = optarg; break;
            case 'c': msmtp_config = optarg; break;
            default:
                fprintf(stderr, "Usage: %s [-s spi_channel] [-a adc_channel] [-m min_raw] [-M max_raw] [-t moisture_threshold] [-f logging_frequency] [-r email_recipient] [-c msmtp_config]\n", argv[0]);
                return 1;
        }
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    spi_handle = spiOpen(spi_channel, 500000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed on channel %d\n", spi_channel);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("Plant monitoring started. Logging every %d seconds.\n", logging_frequency);
    while (running) {
        int raw = read_mcp3008(adc_channel);
        if (raw < 0) {
            fprintf(stderr, "Error: Failed to read ADC channel %d, retrying next cycle\n", adc_channel);
        } else {
            int moisture = calibrate_moisture(raw);
            log_data(moisture);
            send_email_alert(moisture);
            printf("Raw: %d, Moisture: %d%%\n", raw, moisture);
        }
        sleep(logging_frequency);
    }
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("Plant monitoring stopped.\n");
    return 0;
}

