/*
 * Soil Moisture Monitor — Raspberry Pi 3 Model B+
 * Sensor : Keyes KY-036 (analog)  -> MCP3008 ADC channel 0
 * ADC    : MCP3008 on SPI0 CE0 (GPIO8), 1 MHz, SPI mode 0
 * Library: pigpio
 *
 * Build  : gcc -O2 -Wall -Wextra -o soil_moisture soil_moisture.c -lpigpio -lrt
 * Run    : ./soil_moisture [sample_interval_seconds]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 (GPIO8) */
#define SPI_BAUD       1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define LOG_FILE       "soil_moisture.log"
#define ADC_MAX        1023       /* 10-bit ADC */
#define SAMPLE_US      1000000    /* 1 second between samples */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low bits)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Moisture percentage (0 = bone dry, 1023 = fully submerged)          */
/* ------------------------------------------------------------------ */
static float calculate_moisture_percentage(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > ADC_MAX) adc_value = ADC_MAX;
    return ((float)adc_value / (float)ADC_MAX) * 100.0f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int adc_value, float moisture_pct)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s, ADC: %d, Moisture: %.2f%%\n",
                timestamp, adc_value, moisture_pct) < 0) {
        fprintf(stderr, "Error: fprintf to log failed\n");
    } else {
        fflush(fp);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int sample_interval = 1;   /* default 1 second */

    if (argc > 1) {
        sample_interval = atoi(argv[1]);
        if (sample_interval <= 0) {
            fprintf(stderr, "Error: sample_interval must be positive\n");
            return EXIT_FAILURE;
        }
    }

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error: cannot open log file");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    install_signal_handlers();

    printf("Soil Moisture Monitoring Started\n");
    printf("SPI channel %d, ADC channel %d, sample every %d s\n",
           SPI_CHANNEL, ADC_CHANNEL, sample_interval);
    printf("Press Ctrl+C to exit.\n");

    /* --- main loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Warning: ADC read failed; skipping sample\n");
        } else {
            float moisture_pct = calculate_moisture_percentage(adc_value);
            log_data(g_log_file, adc_value, moisture_pct);
            printf("ADC: %4d  Moisture: %5.2f%%\n", adc_value, moisture_pct);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < sample_interval * 10 && g_running; i++) {
            gpioDelay(100000);   /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

