#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define VREF 3.3
#define NUM_SENSORS 4
#define LOG_FILE "environmental_data.csv"
#define GPIO_CHIP "gpiochip4"
#define CS_LINE 8

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE);
    if (!cs_line) {
        perror("Failed to get CS line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        perror("Failed to request CS line as output");
        gpiod_chip_close(chip);
        chip = NULL;
        cs_line = NULL;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Failed to assert CS");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Failed to deassert CS");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_voltage(int adc_value) {
    return (adc_value / 1023.0f) * VREF;
}

static void log_data(float voltages[NUM_SENSORS]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s", timestamp);
    for (int i = 0; i < NUM_SENSORS; i++) {
        fprintf(log_file, ",%.3f", voltages[i]);
    }
    fprintf(log_file, "\n");
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return 1;
    }

    if (init_spi() < 0) {
        return 1;
    }

    if (init_gpio() < 0) {
        close(spi_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    fprintf(log_file, "Timestamp");
    for (int i = 0; i < NUM_SENSORS; i++) {
        fprintf(log_file, ",Sensor%d", i);
    }
    fprintf(log_file, "\n");
    fflush(log_file);

    while (running) {
        float voltages[NUM_SENSORS];
        int read_error = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc = read_mcp3008(i);
            if (adc < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                read_error = 1;
                voltages[i] = -1.0f;
            } else {
                voltages[i] = adc_to_voltage(adc);
            }
        }

        if (!read_error) {
            log_data(voltages);
        }

        sleep(1);
    }

    cleanup();
    return 0;
}

