#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define LOG_FILE "health_log.txt"

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_STATUS_2 0x01
#define REG_INTR_ENABLE_1 0x02
#define REG_FIFO_WR_PTR 0x04
#define REG_OVF_COUNTER 0x05
#define REG_FIFO_RD_PTR 0x06
#define REG_FIFO_DATA 0x07
#define REG_MODE_CONFIG 0x06
#define REG_SPO2_CONFIG 0x08
#define REG_LED1_PA 0x09
#define REG_LED2_PA 0x0A
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15
#define SPO2_THRESHOLD 95.0f
#define HR_THRESHOLD 100.0f

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    return i2cWriteDevice(i2c_handle, buf, 2);
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) < 0) return -1;
    char data[1];
    if (i2cReadDevice(i2c_handle, data, 1) != 1) return -1;
    *value = (uint8_t)data[0];
    return 0;
}

static int i2c_read_burst(uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) < 0) return -1;
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int init_max30102(void) {
    uint8_t part_id;
    if (i2c_read_reg(REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: Failed to read Part ID register.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Error: Unexpected Part ID 0x%02X (expected 0x%02X). Sensor not present?\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("MAX30102 detected (Part ID: 0x%02X).\n", part_id);

    if (i2c_write_reg(REG_MODE_CONFIG, 0x40) < 0) {
        fprintf(stderr, "Error: Failed to reset MAX30102.\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg(REG_INTR_ENABLE_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to clear interrupt enable.\n");
        return -1;
    }
    if (i2c_write_reg(REG_FIFO_WR_PTR, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to clear FIFO write pointer.\n");
        return -1;
    }
    if (i2c_write_reg(REG_OVF_COUNTER, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to clear overflow counter.\n");
        return -1;
    }
    if (i2c_write_reg(REG_FIFO_RD_PTR, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to clear FIFO read pointer.\n");
        return -1;
    }
    if (i2c_write_reg(REG_MODE_CONFIG, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to set SpO2 mode.\n");
        return -1;
    }
    if (i2c_write_reg(REG_SPO2_CONFIG, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to set SPO2 config.\n");
        return -1;
    }
    if (i2c_write_reg(REG_LED1_PA, 0x24) < 0) {
        fprintf(stderr, "Error: Failed to set LED1 amplitude.\n");
        return -1;
    }
    if (i2c_write_reg(REG_LED2_PA, 0x24) < 0) {
        fprintf(stderr, "Error: Failed to set LED2 amplitude.\n");
        return -1;
    }
    return 0;
}

static int read_fifo_data(uint32_t *red, uint32_t *ir) {
    uint8_t buf[6];
    if (i2c_read_burst(REG_FIFO_DATA, buf, 6) < 0) return -1;
    *red = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    *ir = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | buf[5];
    return 0;
}

static float calculate_spo2(uint32_t red, uint32_t ir) {
    if (ir == 0) return -1.0f;
    float ratio = (float)red / (float)ir;
    if (ratio < 0.1f) ratio = 0.1f;
    if (ratio > 3.0f) ratio = 3.0f;
    float spo2 = 110.0f - 25.0f * ratio;
    if (spo2 < 0.0f) spo2 = 0.0f;
    if (spo2 > 100.0f) spo2 = 100.0f;
    return spo2;
}

static float calculate_heart_rate(uint32_t *ir_buffer, int buffer_size) {
    if (buffer_size < 2) return -1.0f;
    int peak_index = 0;
    int max_peaks = 0;
    for (int i = 1; i < buffer_size - 1; i++) {
        if (ir_buffer[i] > ir_buffer[i - 1] && ir_buffer[i] > ir_buffer[i + 1]) {
            if (ir_buffer[i] > ir_buffer[peak_index]) {
                peak_index = i;
                max_peaks++;
            }
        }
    }
    if (max_peaks < 2) return -1.0f;
    float time_diff = (float)(peak_index * 1000) / 100.0f;
    return 60.0f / time_diff;
}

static void log_event(float spo2, float hr) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file %s.\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    fprintf(fp, "%s, SpO2: %.2f%%, HR: %.2f BPM\n", timestamp, spo2, hr);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X on bus %d.\n", MAX30102_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (init_max30102() < 0) {
        fprintf(stderr, "Error: MAX30102 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint32_t ir_buffer[100];
    int buffer_index = 0;
    int buffer_full = 0;

    while (!terminate) {
        uint32_t red, ir;
        if (read_fifo_data(&red, &ir) < 0) {
            fprintf(stderr, "Error: Failed to read FIFO data.\n");
            gpioDelay(100000);
            continue;
        }

        ir_buffer[buffer_index] = ir;
        buffer_index++;
        if (buffer_index >= 100) {
            buffer_index = 0;
            buffer_full = 1;
        }

        float spo2 = calculate_spo2(red, ir);
        float hr = -1.0f;
        if (buffer_full) {
            hr = calculate_heart_rate(ir_buffer, 100);
        }

        if (spo2 >= 0.0f && spo2 < SPO2_THRESHOLD) {
            log_event(spo2, hr);
        }
        if (hr >= 0.0f && hr > HR_THRESHOLD) {
            log_event(spo2, hr);
        }

        gpioDelay(100000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

