    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int control_buzzer(int state) {
    int ret = gpioWrite(BUZZER_GPIO, state);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to write GPIO %d (ret=%d)\n", BUZZER_GPIO, ret);
        return -1;
    }
    return 0;
}

