#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define RELAY_PIN      17
#define REED_PIN       27
#define LOG_FILE       "/var/log/door_events.log"
#define NUM_BASELINE   10
#define BASELINE_MS    50
#define POLL_MS        200
#define RELAY_MS       3000
#define THRESHOLD_PCT  80
#define ADC_MAX        32767.0f

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *reed_line = NULL;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = {reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF)};
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    struct i2c_msg msgs[2] = {
        { .addr = ADS1115_ADDR, .flags = 0, .len = 1, .buf = &reg },
        { .addr = ADS1115_ADDR, .flags = I2C_M_RD, .len = 2, .buf = buf }
    };
    struct i2c_rdwr_ioctl_data data = { .msgs = msgs, .nmsgs = 2 };
    if (ioctl(fd, I2C_RDWR, &data) < 0) return -1;
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_adc(int fd, uint16_t *raw) {
    if (i2c_write_reg16(fd, 0x00, 0x8000) < 0) return -1; /* config: single-shot, AIN0-GND, 4.096V, 128SPS */
    usleep(10000);
    uint16_t cfg;
    for (int i = 0; i < 10; i++) {
        if (i2c_read_reg16(fd, 0x00, &cfg) < 0) return -1;
        if (cfg & 0x8000) break;
        usleep(2000);
    }
    if (!(cfg & 0x8000)) return -1;
    uint16_t val;
    if (i2c_read_reg16(fd, 0x00, &val) < 0) return -1;
    *raw = val;
    return 0;
}

static int read_distance(void) {
    uint16_t raw;
    if (read_adc(i2c_fd, &raw) < 0) return -1;
    return (int)((raw / ADC_MAX) * 100.0f);
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (reed_line) gpiod_line_release(reed_line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
}

int main(void) {
    struct sigaction sa = { .sa_handler = handle_signal };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    reed_line = gpiod_chip_get_line(chip, REED_PIN);
    if (!relay_line || !reed_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(relay_line, "door_lock", 0) < 0 ||
        gpiod_line_request_input(reed_line, "door_reed") < 0) {
        perror("gpiod_line_request");
        cleanup();
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c");
        cleanup();
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return 1;
    }

    float sum = 0.0f;
    for (int i = 0; i < NUM_BASELINE; i++) {
        int d = read_distance();
        if (d < 0) {
            log_event("Baseline read failed; using 0");
            d = 0;
        }
        sum += d;
        usleep(BASELINE_MS * 1000);
    }
    float avg = sum / NUM_BASELINE;
    int threshold = (int)((THRESHOLD_PCT / 100.0f) * avg);
    printf("Baseline: %.1f, Threshold: %d\n", avg, threshold);

    while (running) {
        int dist = read_distance();
        if (dist < 0) {
            log_event("ADC read failed");
            usleep(POLL_MS * 1000);
            continue;
        }
        printf("Distance: %d\n", dist);
        if (dist < threshold) {
            log_event("Threshold breached");
            gpiod_line_set_value(relay_line, 1);
            log_event("Relay energized");
            usleep(RELAY_MS * 1000);
            gpiod_line_set_value(relay_line, 0);
            log_event("Relay de-energized");
            int reed = gpiod_line_get_value(reed_line);
            if (reed < 0) {
                log_event("Reed read failed");
            } else if (reed == 0) {
                log_event("Door opened");
            } else {
                log_event("Door not opened");
            }
        }
        usleep(POLL_MS * 1000);
    }
    cleanup();
    return 0;
}

