        return 1;
    }
    if (gpiod_line_request_output(relay_line, "door_lock", 0) < 0 ||
        gpiod_line_request_input(reed_line, "door_reed") < 0) {
        perror("gpiod_line_request");
        cleanup();
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c");
        cleanup();
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return 1;
    }

    float sum = 0.0f;
    for (int i = 0; i < NUM_BASELINE; i++) {
        int d = read_distance();
        if (d < 0) {
            log_event("Baseline read failed; using 0");
            d = 0;
        }
        sum += d;
        usleep(BASELINE_MS * 1000);
    }
    float avg = sum / NUM_BASELINE;
    int threshold = (int)((THRESHOLD_PCT / 100.0f) * avg);
    printf("Baseline: %.1f, Threshold: %d\n", avg, threshold);

    while (running) {
        int dist = read_distance();
        if (dist < 0) {
            log_event("ADC read failed");
            usleep(POLL_MS * 1000);
            continue;
        }
        printf("Distance: %d\n", dist);
        if (dist < threshold) {
            log_event("Threshold breached");
            gpiod_line_set_value(relay_line, 1);
            log_event("Relay energized");
            usleep(RELAY_MS * 1000);
            gpiod_line_set_value(relay_line, 0);
            log_event("Relay de-energized");
            int reed = gpiod_line_get_value(reed_line);
            if (reed < 0) {
                log_event("Reed read failed");
            } else if (reed == 0) {
                log_event("Door opened");
            } else {
                log_event("Door not opened");
            }
        }
        usleep(POLL_MS * 1000);
    }
    cleanup();
    return 0;
}

