#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0

#define CS0_LINE        8
#define CS1_LINE        7
#define CS2_LINE        25

#define NUM_SENSORS     3
#define LOG_INTERVAL_S  5
#define LOG_FILE        "soil_moisture_log.csv"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = len,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_mcp3008(int fd, struct gpiod_line *cs, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    if (gpiod_line_set_value(cs, 0) < 0) {
        fprintf(stderr, "Failed to assert CS line: %s\n", strerror(errno));
        return -1;
    }

    if (spi_transfer(fd, tx, rx, 3) < 0) {
        gpiod_line_set_value(cs, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS line: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_data(FILE *fp, int s1, int s2, int s3)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, s1, s2, s3) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_line *cs0 = gpiod_chip_get_line(chip, CS0_LINE);
    struct gpiod_line *cs1 = gpiod_chip_get_line(chip, CS1_LINE);
    struct gpiod_line *cs2 = gpiod_chip_get_line(chip, CS2_LINE);
    if (!cs0 || !cs1 || !cs2) {
        fprintf(stderr, "Failed to get CS lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(cs0, "mcp3008", 1) < 0 ||
        gpiod_line_request_output(cs1, "mcp3008", 1) < 0 ||
        gpiod_line_request_output(cs2, "mcp3008", 1) < 0) {
        fprintf(stderr, "Failed to request CS lines as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(spi_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n") < 0 ||
            fflush(fp) != 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            fclose(fp);
            close(spi_fd);
            gpiod_chip_close(chip);
            return 1;
        }
    }

    while (g_running) {
        int s1 = read_mcp3008(spi_fd, cs0, 0);
        int s2 = read_mcp3008(spi_fd, cs1, 0);
        int s3 = read_mcp3008(spi_fd, cs2, 0);

        if (log_data(fp, s1, s2, s3) < 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        for (int i = 0; i < LOG_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    fprintf(stderr, "\nShutting down...\n");
    fclose(fp);
    close(spi_fd);
    gpiod_chip_close(chip);
    return 0;
}

