#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define LOG_FILE "irrigation.log"
#define MAX_RETRIES 3

static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message("Invalid MCP3008 channel requested");
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            return adc_value;
        }
        char msg[128];
        snprintf(msg, sizeof(msg), "SPI transfer failed (attempt %d/%d), ret=%d", attempt + 1, MAX_RETRIES, ret);
        log_message(msg);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(100000); /* 100 ms backoff */
        }
    }
    log_message("SPI transfer failed after all retries");
    return -1;
}

static int map_adc_to_moisture(int adc_value) {
    if (adc_value < 0) return -1;
    if (adc_value < 200) return 100;
    if (adc_value > 800) return 0;
    return 100 - (int)(((float)(adc_value - 200) / 600.0f) * 100.0f);
}

static void control_pump(int on) {
    if (gpioWrite(PUMP_GPIO, on ? 1 : 0) < 0) {
        log_message("Failed to write pump GPIO");
    } else {
        char msg[64];
        snprintf(msg, sizeof(msg), "Pump %s", on ? "ON" : "OFF");
        log_message(msg);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(int argc, char *argv[]) {
    int threshold = 30;
    int duration = 10;
    int sleep_interval = 60;

    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't': threshold = atoi(optarg); break;
            case 'd': duration = atoi(optarg); break;
            case 's': sleep_interval = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (threshold < 0 || threshold > 100 || duration <= 0 || sleep_interval <= 0) {
        fprintf(stderr, "Invalid arguments. Threshold must be 0-100, duration > 0, sleep_interval > 0.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_pump(0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Irrigation system started");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_message("Failed to read soil moisture sensor");
        } else {
            int moisture = map_adc_to_moisture(adc_value);
            char msg[128];
            snprintf(msg, sizeof(msg), "Soil moisture: ADC=%d, Moisture=%d%%", adc_value, moisture);
            log_message(msg);

            if (moisture >= 0 && moisture < threshold) {
                control_pump(1);
                for (int i = 0; i < duration && running; i++) {
                    gpioDelay(1000000); /* 1 second */
                }
                control_pump(0);
            }
        }

        for (int i = 0; i < sleep_interval && running; i++) {
            gpioDelay(1000000);
        }
    }

    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    log_message("Irrigation system stopped");
    return EXIT_SUCCESS;
}

