#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48
#define CONTROL_BYTE   0x40  /* single-ended, AIN0, analog output disabled */
#define SAMPLE_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    int fd = -1;
    uint8_t buf[1];
    int rc;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    /* Acquire the PCF8591 device */
    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Write the control byte to configure the ADC */
    buf[0] = CONTROL_BYTE;
    rc = write(fd, buf, 1);
    if (rc != 1) {
        fprintf(stderr, "write control byte failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Discard the first conversion result (returns previous sample) */
    rc = read(fd, buf, 1);
    if (rc != 1) {
        fprintf(stderr, "discard read failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("PCF8591 AIN0 monitor started (I2C 0x%02X). Press Ctrl-C to stop.\n",
           PCF8591_ADDR);

    while (g_running) {
        /* Read the current sample */
        rc = read(fd, buf, 1);
        if (rc != 1) {
            fprintf(stderr, "read failed: %s\n", strerror(errno));
            break;
        }

        printf("AIN0: %d\n", buf[0]);
        fflush(stdout);

        usleep(SAMPLE_DELAY_US);
    }

    /* Clean shutdown */
    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

