#define THRESHOLD_GAUSS 500.0
#define GPIO_SHUTDOWN 27
#define BUFFER_SIZE 10
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */
#define ADC_CONV_TIMEOUT_US 100000  /* 100 ms */

/* Circular buffer */
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static CircularBuffer mag_buffer;

/* Function prototypes */
static int init_ads1115(void);
static int read_ads1115(int16_t *raw);
static float voltage_to_gauss(float voltage);
static void add_to_buffer(CircularBuffer *cb, float value);
static float calculate_average(CircularBuffer *cb);
static void shutdown_motor(void);
static void signal_handler(int sig);
static void cleanup(void);

/* Initialize ADS1115: single-shot, AIN0, PGA 4.096 V, 128 SPS, no comparator */
static int init_ads1115(void) {
    uint16_t config = ADS1115_CFG_BASE
                    | ADS1115_CFG_MUX_AIN0
                    | ADS1115_CFG_PGA_4_096V
                    | ADS1115_CFG_MODE_SINGLE
                    | ADS1115_CFG_DR_128SPS
                    | ADS1115_CFG_CQUE_NONE;

    char cfg_buf[3];
    cfg_buf[0] = ADS1115_REG_CFG;
    cfg_buf[1] = (config >> 8) & 0xFF;
    cfg_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, cfg_buf, 3) < 0) {
        syslog(LOG_ERR, "Failed to write ADS1115 config register");
        return -1;
    }
    return 0;
}

/* Read raw 16-bit ADC value from ADS1115 conversion register */
static int read_ads1115(int16_t *raw) {
    char reg = ADS1115_REG_CONV;
    char data[2];

    /* Point to conversion register */
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) {
        syslog(LOG_ERR, "Failed to set ADS1115 conversion register pointer");
        return -1;
    }

    /* Read 2 bytes (big-endian) */
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read ADS1115 conversion register");
        return -1;
    }

    *raw = (int16_t)(((uint16_t)data[0] << 8) | (uint8_t)data[1]);
    return 0;
}

/* Convert raw ADC value to voltage (4.096 V PGA) */
static float voltage_to_gauss(float voltage) {
    return (voltage - SS49E_ZERO_FIELD_V) / SS49E_SENSITIVITY * 1000.0;
}

/* Add value to circular buffer */
static void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

/* Calculate rolling average of buffer */
static float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / cb->count;
}

/* Drive GPIO27 HIGH to signal motor shutdown */
static void shutdown_motor(void) {
    gpioWrite(GPIO_SHUTDOWN, 1);
    syslog(LOG_WARNING, "Threshold exceeded! Motor shutdown triggered.");
}

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open syslog */
    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* Configure GPIO27 as output, initially LOW */
    if (gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", GPIO_SHUTDOWN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);

    /* Initialize circular buffer */
    mag_buffer.head = 0;
    mag_buffer.count = 0;

    /* Open I2C bus to ADS1115 */
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d at address 0x%02X", I2C_BUS, ADS1115_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize ADS1115 */
    if (init_ads1115() < 0) {
        syslog(LOG_ERR, "ADS1115 initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Hall sensor monitoring started (threshold %.1f Gauss)", THRESHOLD_GAUSS);

    /* Main sampling loop */
    while (running) {
        int16_t raw;
        if (read_ads1115(&raw) < 0) {
            syslog(LOG_ERR, "ADC read failed, skipping sample");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float voltage = (float)raw * (ADS1115_PGA_4_096V_SCALE / 32768.0);
        if (voltage < 0.0f || voltage > VCC) {
            syslog(LOG_ERR, "Invalid voltage reading: %.3f V (raw=%d)", voltage, raw);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float gauss = voltage_to_gauss(voltage);
        syslog(LOG_INFO, "Voltage: %.3f V, Magnetic Field: %.2f Gauss", voltage, gauss);

        add_to_buffer(&mag_buffer, gauss);
        float avg = calculate_average(&mag_buffer);

        if (avg > THRESHOLD_GAUSS) {
            shutdown_motor();
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down...");
    cleanup();
    return EXIT_SUCCESS;
}

