#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <getopt.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define SAMPLE_INTERVAL_US 100000
#define BLINK_DURATION_US 1000000
#define BLINK_HALF_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ads1115_init(int handle) {
    uint8_t config[3];
    config[0] = 0x01; /* Config register pointer */
    config[1] = 0xC3; /* MUX=AIN0, PGA=4.096V, MODE=single */
    config[2] = 0x83; /* DR=128SPS, COMP_DISABLE */
    if (i2cWriteDevice(handle, (char *)config, 3) < 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config.\n");
        return -1;
    }
    return 0;
}

static int ads1115_read(int handle, int16_t *raw) {
    uint8_t reg = 0x00; /* Conversion register pointer */
    if (i2cWriteDevice(handle, (char *)&reg, 1) < 0) {
        fprintf(stderr, "Error: Failed to set ADS1115 register pointer.\n");
        return -1;
    }
    uint8_t buf[2];
    if (i2cReadDevice(handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion.\n");
        return -1;
    }
    *raw = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static float raw_to_gauss(int16_t raw) {
    /* SS49E: 1.0 mV/Gauss, 3.3V supply -> 1.0 mV/Gauss = 0.001 V/Gauss */
    return (float)raw * 0.001f;
}

static void blink_led(int gpio, int duration_us) {
    if (gpioWrite(gpio, 1) < 0) return;
    gpioDelay(BLINK_HALF_US);
    if (gpioWrite(gpio, 0) < 0) return;
    gpioDelay(BLINK_HALF_US);
    if (duration_us > BLINK_HALF_US * 2) {
        blink_led(gpio, duration_us - BLINK_HALF_US * 2);
    }
}

int main(int argc, char *argv[]) {
    float threshold = 100.0f;
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Error: Threshold must be positive.\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X.\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ads1115_init(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring magnetic field (threshold: %.2f Gauss)...\n", threshold);

    while (running) {
        int16_t raw;
        if (ads1115_read(i2c_handle, &raw) < 0) {
            fprintf(stderr, "Warning: ADC read failed, retrying in 100 ms.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float gauss = raw_to_gauss(raw);
        printf("Magnetic Field: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            printf("Threshold exceeded! Blinking LED for 1 second.\n");
            blink_led(LED_GPIO, BLINK_DURATION_US);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

