    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_moisture(int adc_value) {
    if (adc_value < 0) return -1.0f;
    return 100.0f - ((float)adc_value / 1023.0f) * 100.0f;
}

static int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write relay GPIO %d", RELAY_GPIO);
        return -1;
    }
    syslog(LOG_INFO, "Relay set to %s", state ? "ON" : "OFF");
    return 0;
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        int rc = mosquitto_subscribe(m, NULL, MQTT_COMMAND_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Subscribe failed: %s", mosquitto_strerror(rc));
        }
    } else {
        syslog(LOG_ERR, "MQTT connect error: %s", mosquitto_strerror(result));
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *msg) {
    (void)m; (void)userdata;
    if (msg->payloadlen > 0) {
        char payload[16] = {0};
        int len = msg->payloadlen < (int)sizeof(payload) - 1 ? msg->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, msg->payload, len);
        payload[len] = '\0';
        if (strcmp(payload, "pump_on") == 0) {
            syslog(LOG_INFO, "Received pump_on command");
            control_relay(1);
        } else if (strcmp(payload, "pump_off") == 0) {
            syslog(LOG_INFO, "Received pump_off command");
            control_relay(0);
        } else {
            syslog(LOG_WARNING, "Unknown command: %s", payload);
        }
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m; (void)userdata;
    if (rc != 0) {
        syslog(LOG_ERR, "Unexpected MQTT disconnect: %s", mosquitto_strerror(rc));
    }
}

static void cleanup(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting soil moisture monitor");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio init failed");
        closelog();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %s", pigpio_error(spi_handle));
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set relay GPIO %d as output", RELAY_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "MQTT new failed");
        cleanup();
        return 1;
    }
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        cleanup();
        return 1;
    }
    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT loop start failed: %s", mosquitto_strerror(rc));
        cleanup();
        return 1;
    }

    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Entering main loop");
    int pump_state = 0;

    while (running) {
        int adc = read_mcp3008(MCP3008_CHANNEL);
        if (adc < 0) {
            syslog(LOG_ERR, "ADC read failed, skipping cycle");
            sleep(60);
            continue;
        }

        float moisture = adc_to_moisture(adc);
        if (moisture < 0.0f) {
            syslog(LOG_ERR, "Invalid ADC value: %d", adc);
            sleep(60);
            continue;
        }

        char payload[64];
        snprintf(payload, sizeof(payload), "%.2f", moisture);
        syslog(LOG_INFO, "Moisture: %s%%", payload);

        rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, (int)strlen(payload), payload, 0, false);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
        }

        if (moisture < MOISTURE_THRESHOLD && pump_state == 0) {
            if (control_relay(1) == 0) pump_state = 1;
        } else if (moisture > MOISTURE_HYSTERESIS && pump_state == 1) {
            if (control_relay(0) == 0) pump_state = 0;
        }

        sleep(60);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return 0;
}

