#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define VREF            3.3f
#define ADC_CHANNEL     0
#define SAMPLE_DELAY_MS 500

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int spi_init(int *fd_out)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

static int read_adc(int fd, uint8_t channel, uint16_t *value_out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       start bit
     *   tx[1] = (0x08 | channel) << 4       SGL/DIFF=1 (single-ended) + channel
     *   tx[2] = 0x00                       padding for clocking out low byte
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *value_out = ((uint16_t)(rx[1] & 0x03) << 8) | (uint16_t)rx[2];
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int spi_fd = -1;
    if (spi_init(&spi_fd) < 0) {
        return EXIT_FAILURE;
    }

    printf("MCP3008 ADC reader on %s (channel %u, VREF=%.1f V)\n",
           SPI_DEVICE, ADC_CHANNEL, VREF);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw = 0;
        if (read_adc(spi_fd, ADC_CHANNEL, &raw) < 0) {
            fprintf(stderr, "ADC read failed; continuing.\n");
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }

        float voltage = (float)raw * VREF / 1024.0f;
        printf("Raw: %4u  Voltage: %.2f V\n", raw, voltage);
        fflush(stdout);

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

