#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define VREF 3.3
#define NUM_CHANNELS 3
#define LOG_INTERVAL_SEC 5

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0f) * VREF;
}

static int log_data(float v0, float v1, float v2) {
    FILE *fp = fopen("sensor_data.csv", "a");
    if (!fp) {
        fprintf(stderr, "Error: Cannot open sensor_data.csv: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, v0, v1, v2) < 0) {
        fprintf(stderr, "Error: fprintf to CSV failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: fclose failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("MCP3008 ADC logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        int adc[NUM_CHANNELS];
        int read_failed = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            adc[i] = read_mcp3008(i);
            if (adc[i] < 0) {
                read_failed = 1;
                break;
            }
        }

        if (read_failed) {
            fprintf(stderr, "Error: ADC read failed, skipping log entry\n");
        } else {
            float v[NUM_CHANNELS];
            for (int i = 0; i < NUM_CHANNELS; i++) {
                v[i] = adc_to_voltage(adc[i]);
            }

            if (log_data(v[0], v[1], v[2]) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        }

        if (!terminate) {
            gpioSleep(PI_TIME_RELATIVE, LOG_INTERVAL_SEC, 0);
        }
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

