#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES_MODE_2 0x11
#define MCP3008_CHANNEL 0
#define LOG_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_bh1750(int i2c_fd, float *lux_out) {
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        return -1;
    }

    if (write(i2c_fd, (uint8_t[]){ BH1750_CONT_HIGH_RES_MODE_2 }, 1) != 1) {
        perror("Failed to write BH1750 command");
        return -1;
    }

    usleep(180000);

    uint8_t buf[2] = { 0 };
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read BH1750 data");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int log_data(FILE *fp, int sound_level, float light_level, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%d,%.2f,%d\n", timestamp, sound_level, light_level, error_code) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set up signal handlers");
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    uint8_t spi_mode = SPI_MODE_0;
    uint8_t spi_bits = 8;
    uint32_t spi_speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) < 0) {
        perror("Failed to configure SPI");
        close(spi_fd);
        return 1;
    }

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        close(spi_fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,sound_level_db,light_level_lux,error_code\n");
        fflush(fp);
    }

    printf("Starting data logging. Press Ctrl+C to stop.\n");

    while (running) {
        int sound_level = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        float light_level = 0.0f;
        int error_code = 0;

        if (sound_level < 0) {
            error_code = -1;
        } else {
            int adc_value = sound_level;
            float voltage = (float)adc_value * 3.3f / 1024.0f;
            float sound_db = 20.0f * log10f(voltage);
            if (sound_db < 0.0f) sound_db = 0.0f;
            if (sound_db > 120.0f) sound_db = 120.0f;
            printf("Sound Level: %.2f dB\n", sound_db);
        }

        if (read_bh1750(i2c_fd, &light_level) < 0) {
            error_code = -2;
        } else {
            printf("Light Level: %.2f lux\n", light_level);
        }

        if (log_data(fp, sound_level, light_level, error_code) < 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    fclose(fp);
    close(i2c_fd);
    close(spi_fd);
    return 0;
}

