#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define RELAY_GPIO 17
#define PROXIMITY_THRESHOLD 20
#define DEBOUNCE_DELAY_MS 1000
#define POLL_INTERVAL_MS 100
#define LOG_FILE "door_events.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, event);
    }
    fclose(fp);
    return 0;
}

static int read_mcp3008(int spi_fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_distance(int spi_fd) {
    int adc = read_mcp3008(spi_fd, 0);
    if (adc < 0) return -1;
    int distance = 10000 - (adc * 10000 / 1023);
    if (distance < 0) distance = 0;
    if (distance > 200) distance = 200;
    return distance;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI");
        return 1;
    }
    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI speed");
        close(spi_fd);
        return 1;
    }
    unsigned char mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI mode");
        close(spi_fd);
        return 1;
    }
    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI bits");
        close(spi_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        close(spi_fd);
        return 1;
    }
    struct gpiod_line *relay = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }
    if (gpiod_line_request_output(relay, "door-sensor", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    printf("Door sensor started. Press Ctrl+C to exit.\n");

    int relay_state = 0;
    struct timespec debounce_ts = {0, DEBOUNCE_DELAY_MS * 1000000L};

    while (running) {
        int distance = read_distance(spi_fd);
        if (distance < 0) {
            fprintf(stderr, "SPI read error, retrying...\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }
        printf("Distance: %d cm\n", distance);

        if (distance < PROXIMITY_THRESHOLD && !relay_state) {
            if (gpiod_line_set_value(relay, 1) < 0) {
                perror("relay on");
            } else {
                relay_state = 1;
                printf("Proximity detected, door opened.\n");
                log_event("Door opened");
            }
        } else if (distance >= PROXIMITY_THRESHOLD && relay_state) {
            if (gpiod_line_set_value(relay, 0) < 0) {
                perror("relay off");
            } else {
                relay_state = 0;
                printf("Proximity cleared, door closed.\n");
                log_event("Door closed");
            }
        }

        if (relay_state) {
            nanosleep(&debounce_ts, NULL);
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(relay, 0);
    gpiod_line_release(relay);
    gpiod_chip_close(chip);
    close(spi_fd);
    return 0;
}

