#define MAX_DISTANCE_CM 400.0

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int write_sysfs(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    if (write(fd, value, strlen(value)) < 0) {
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int read_sysfs(const char *path, char *buf, size_t len) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) return -1;
    if (read(fd, buf, len - 1) < 0) {
        close(fd);
        return -1;
    }
    buf[len - 1] = '\0';
    close(fd);
    return 0;
}

int gpio_export(int pin) {
    char buf[4];
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) return -1;
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_unexport(int pin) {
    char buf[4];
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) return -1;
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_set_direction(int pin, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    return write_sysfs(path, dir);
}

int gpio_set_value(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    return write_sysfs(path, value ? "1" : "0");
}

int gpio_get_value(int pin) {
    char path[64];
    char buf[4];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    return read_sysfs(path, buf, sizeof(buf)) ? atoi(buf) : -1;
}

int pwm_export(int pin) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/export");
    return write_sysfs(path, "0");
}

int pwm_unexport(int pin) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/unexport");
    return write_sysfs(path, "0");
}

int pwm_enable(int pin, int enable) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/enable", pin);
    return write_sysfs(path, enable ? "1" : "0");
}

int pwm_set_period(int pin, int period_ns) {
    char path[64];
    char buf[16];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/period", pin);
    snprintf(buf, sizeof(buf), "%d", period_ns);
    return write_sysfs(path, buf);
}

int pwm_set_duty_cycle(int pin, int duty_ns) {
    char path[64];
    char buf[16];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", pin);
    snprintf(buf, sizeof(buf), "%d", duty_ns);
    return write_sysfs(path, buf);
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) return -1;
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        close(fd);
        return -1;
    }
    close(fd);
    return ((rx[1] & 0x03) << 8) | rx[2];
}

float read_distance() {
    struct timespec start, end;
    int timeout = 0;
    while (gpio_set_value(TRIG_PIN, 1) < 0) usleep(1000);
    usleep(10);
    while (gpio_set_value(TRIG_PIN, 0) < 0) usleep(1000);
    while (gpio_get_value(ECHO_PIN) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) return -1.0;
        while (gpio_get_value(ECHO_PIN) == 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) return -1.0;
            if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_US) {
                timeout = 1;
                break;
            }
        }
        if (timeout) break;
    }
    if (timeout) return -1.0;
    while (gpio_get_value(ECHO_PIN) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) return -1.0;
        while (gpio_get_value(ECHO_PIN) == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) return -1.0;
            if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_US) {
                timeout = 1;
                break;
            }
        }
        if (timeout) break;
    }
    if (timeout) return -1.0;
    long long diff = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    return (float)diff / 58.0;
}

