#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 1000
#define SAMPLE_INTERVAL_S 5

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx[3] = {0};

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI read failed (attempt %d/%d): ret=%d\n", attempt + 1, MAX_RETRIES, ret);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

static int calculate_aqi(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        return -1;
    }
    return (adc_value * 500) / 1023;
}

static void control_fan(int aqi) {
    if (aqi > AQI_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1);
    } else {
        gpioWrite(FAN_GPIO, 0);
    }
}

static void log_data(int aqi) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, AQI: %d\n", timestamp, aqi);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value after retries. Re-initializing SPI.\n");
            spiClose(spi_handle);
            spi_handle = -1;
            gpioDelay(1000000);
            spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
            if (spi_handle < 0) {
                fprintf(stderr, "SPI re-open failed: %d\n", spi_handle);
                terminate = 1;
                break;
            }
            continue;
        }

        int aqi = calculate_aqi(adc_value);
        if (aqi < 0) {
            fprintf(stderr, "Invalid AQI calculation\n");
            continue;
        }

        control_fan(aqi);
        log_data(aqi);

        printf("AQI: %d\n", aqi);

        for (int i = 0; i < SAMPLE_INTERVAL_S && !terminate; i++) {
            gpioDelay(1000000);
        }
    }

    cleanup();
    return 0;
}

