#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <stdbool.h>

// Motor 1 GPIO pins
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2 GPIO pins
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000  // 1 MHz
#define SPI_MODE 0

// Potentiometer ADC channels
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// Speed limits
#define MIN_SPEED 50
#define MAX_SPEED 255

// Timing constants
#define ACCEL_TIME 1.0
#define HOLD_TIME 2.0
#define DECEL_TIME 1.0
#define PAUSE_TIME 5.0
#define STEP_DELAY 0.1

// Global flag for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_potentiometer(int channel);
double map_potentiometer_to_speed(int pot_value);
void set_motor_speed(int motor, int speed);
void move_motors(int pot1, int pot2);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Read a single-ended channel from the MCP3008 via SPI
int read_potentiometer(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command: start bit (1), single-ended mode (1), channel select (3 bits)
    // tx[0] = 0x01 (start bit)
    // tx[1] = (0x08 | channel) << 4 (single-ended + channel)
    // tx[2] = 0x00 (don't care)
    char tx_buf[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx_buf[3] = {0};

    int handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (handle < 0) {
        fprintf(stderr, "Error: Failed to open SPI channel %d\n", SPI_CHANNEL);
        return -1;
    }

    int result = spiXfer(handle, tx_buf, rx_buf, 3);
    spiClose(handle);

    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value: bits 9-2 from rx_buf[1], bits 1-0 from rx_buf[2]
    int adc_value = ((rx_buf[1] & 0x03) << 8) | (rx_buf[2] & 0xFF);
    return adc_value;
}

// Map potentiometer reading to speed factor using logarithmic mapping
// This provides finer control at low speeds
double map_potentiometer_to_speed(int pot_value) {
    if (pot_value < 0) pot_value = 0;
    if (pot_value > 1023) pot_value = 1023;

    // Logarithmic mapping: speed_factor = log10(pot_value + 1) / log10(1024)
    // This maps 0-1023 to 0-1, with a smooth transition at low speeds
    double speed_factor = log10((double)pot_value + 1.0) / log10(1024.0);
    if (speed_factor < 0.0) speed_factor = 0.0;
    if (speed_factor > 1.0) speed_factor = 1.0;

    // Scale to MIN_SPEED to MAX_SPEED
    int speed = (int)(MIN_SPEED + speed_factor * (MAX_SPEED - MIN_SPEED));
    if (speed < MIN_SPEED) speed = MIN_SPEED;
    if (speed > MAX_SPEED) speed = MAX_SPEED;
    return (double)speed;
}

// Set motor speed using pigpio PWM
void set_motor_speed(int motor, int speed) {
    if (motor == 1) {
        gpioPWM(MOTOR1_ENABLE, speed);
        gpioWrite(MOTOR1_DIRECTION, 1);  // Forward
    } else if (motor == 2) {
        gpioPWM(MOTOR2_ENABLE, speed);
        gpioWrite(MOTOR2_DIRECTION, 0);  // Backward
    } else {
        fprintf(stderr, "Error: Invalid motor number %d\n", motor);
    }
}

// Move both motors simultaneously based on potentiometer readings
void move_motors(int pot1, int pot2) {
    double speed1 = map_potentiometer_to_speed(pot1);
    double speed2 = map_potentiometer_to_speed(pot2);

    // Accelerate
    for (int i = MIN_SPEED; i <= MAX_SPEED; i++) {
        if (!program_running) break;
        set_motor_speed(1, i);
        set_motor_speed(2, i);
        time_sleep(0.01);
    }

    // Hold
    time_sleep(HOLD_TIME);

    // Decelerate
    for (int i = MAX_SPEED; i >= MIN_SPEED; i--) {
        if (!program_running) break;
        set_motor_speed(1, i);
        set_motor_speed(2, i);
        time_sleep(0.01);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR1_ENABLE, 255);
    gpioSetPWMrange(MOTOR2_ENABLE, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

