#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_GPIO 17
#define SOUND_THRESHOLD 10
#define CALIBRATION_TIME 5
#define DEBOUNCE_DELAY_MS 10
#define SAMPLE_DELAY_US 10000

static volatile int running = 1;
static int spi_handle = -1;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int calibrate_sound_level() {
    int sum = 0;
    int count = 0;
    time_t start_time = time(NULL);

    while (running && (time(NULL) - start_time) < CALIBRATION_TIME) {
        int level = read_mcp3008(0);
        if (level < 0) {
            fprintf(stderr, "Error reading ADC during calibration\n");
            return -1;
        }
        sum += level;
        count++;
        gpioDelay(SAMPLE_DELAY_US);
    }

    if (!running) return -1;
    if (count == 0) {
        fprintf(stderr, "No samples taken during calibration\n");
        return -1;
    }

    return (int)(sum / count);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    signal(SIGINT, signal_handler);

    int ambient_level = calibrate_sound_level();
    if (ambient_level < 0) {
        fprintf(stderr, "Calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    int threshold = ambient_level + (ambient_level * SOUND_THRESHOLD / 100);
    printf("Calibrated ambient level: %d, Threshold: %d\n", ambient_level, threshold);

    while (running) {
        int level = read_mcp3008(0);
        if (level < 0) {
            fprintf(stderr, "Error reading ADC\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        if (level > threshold) {
            static int led_state = 0;
            if (!led_state) {
                gpioWrite(LED_GPIO, 1);
                led_state = 1;
                gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            }
        } else {
            if (led_state) {
                gpioWrite(LED_GPIO, 0);
                led_state = 0;
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(LED_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

