// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0     // MCP3008 channel connected to AWM720P
#define VREF 3.3          // Reference voltage for MCP3008
#define ADC_MAX 1023      // 10-bit ADC
#define V_MIN 0.5         // Sensor output at 0 SLPM
#define V_MAX 4.5         // Sensor output at 200 SLPM
#define SLPM_MAX 200.0    // Maximum airflow
#define SAMPLE_INTERVAL_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_adc(int channel);
float voltage_to_airflow(float voltage);
void log_airflow(float airflow);
void log_error(const char *message);
void cleanup();
void signal_handler(int signal);

// Function to read from MCP3008 ADC via SPI
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        log_error("Invalid ADC channel");
        return -1;
    }

    // MCP3008 SPI command format: start bit (1), single-ended mode (1), channel select (3 bits)
    // tx[0] = 0x01 (start bit)
    // tx[1] = (0x08 | channel) << 4 (single-ended + channel)
    // tx[2] = 0x00 (don't care)
    char tx_buffer[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx_buffer[3] = {0};

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        log_error("SPI transfer failed");
        return -1;
    }

    // Extract 10-bit ADC value from rx_buffer[1] and rx_buffer[2]
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | (rx_buffer[2] & 0xFF);
    return adc_value;
}

// Function to convert voltage to airflow (SLPM)
float voltage_to_airflow(float voltage) {
    if (voltage < V_MIN) voltage = V_MIN;
    if (voltage > V_MAX) voltage = V_MAX;
    return ((voltage - V_MIN) / (V_MAX - V_MIN)) * SLPM_MAX;
}

// Function to log airflow data with timestamp
void log_airflow(float airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f SLPM\n", timestamp, airflow);
    fflush(log_file);
}

// Function to log error messages with timestamp
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

// Cleanup function to release resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("airflow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            log_error("ADC read failed");
        } else {
            // Convert ADC value to voltage
            float voltage = (float)adc_value / ADC_MAX * VREF;

            // Convert voltage to airflow
            float airflow = voltage_to_airflow(voltage);

            // Log airflow
            log_airflow(airflow);
        }

        // Wait for 100 milliseconds
        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup
    cleanup();

    return 0;
}

