#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define VREF 3.3
#define PPM_MULTIPLIER 1000.0
#define LOG_FILE "gas_log.txt"
#define RETRY_DELAY_MS 100

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static double adc_to_voltage(int adc_value) {
    return ((double)adc_value / 1023.0) * VREF;
}

static double voltage_to_ppm(double voltage) {
    return voltage * PPM_MULTIPLIER;
}

static int log_data(double voltage, double ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Voltage: %.3f V, PPM: %.2f\n", timestamp, voltage, ppm);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    printf("Propane leak detector started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, retrying in %d ms...\n", RETRY_DELAY_MS);
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        double voltage = adc_to_voltage(adc_value);
        double ppm = voltage_to_ppm(voltage);

        if (log_data(voltage, ppm) != 0) {
            fprintf(stderr, "Logging failed\n");
        }

        printf("Voltage: %.3f V, PPM: %.2f\n", voltage, ppm);

        gpioDelay(1000000);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return 0;
}

