double kalman_filter(double measurement, KalmanFilterState *state);
void signal_handler(int signal);
int initialize();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command: start bit (1), single-ended mode (1), channel select (3 bits)
    // Format: [0x01, (0x80 | (channel << 4)), 0x00]
    char tx_buf[3] = {0x01, (char)(0x80 | (channel << 4)), 0x00};
    char rx_buf[3] = {0};

    // Assert CS (active low)
    gpioWrite(MCP3008_CS_PIN, 0);

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);

    // De-assert CS
    gpioWrite(MCP3008_CS_PIN, 1);

    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | (rx_buf[2] & 0xFF);
    return adc_value;
}

// Kalman filter function
double kalman_filter(double measurement, KalmanFilterState *state) {
    double predicted_state = state->x;
    double predicted_covariance = state->P + Q;

    double kalman_gain = predicted_covariance / (predicted_covariance + R);

    state->x = predicted_state + kalman_gain * (measurement - predicted_state);
    state->P = (1.0 - kalman_gain) * predicted_covariance;

    return state->x;
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Configure CS pin as output and de-assert it
    gpioSetMode(MCP3008_CS_PIN, PI_OUTPUT);
    gpioWrite(MCP3008_CS_PIN, 1);

    // Open SPI channel (mode 0, 8 bits per word)
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    printf("ADXL335 Accelerometer Reading and Kalman Filtering\n");
    printf("Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC values from MCP3008
        int x_adc = read_mcp3008(0);
        int y_adc = read_mcp3008(1);
        int z_adc = read_mcp3008(2);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error: Failed to read ADC values. Retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        // Convert ADC values to voltage
        double x_voltage = (double)x_adc / 1023.0 * 3.3;
        double y_voltage = (double)y_adc / 1023.0 * 3.3;
        double z_voltage = (double)z_adc / 1023.0 * 3.3;

        // Convert voltage to acceleration (g)
        double x_acceleration = (x_voltage - ADXL335_ZERO_G_BIAS) / ADXL335_SENSITIVITY;
        double y_acceleration = (y_voltage - ADXL335_ZERO_G_BIAS) / ADXL335_SENSITIVITY;
        double z_acceleration = (z_voltage - ADXL335_ZERO_G_BIAS) / ADXL335_SENSITIVITY;

        // Apply Kalman filter
        double filtered_x = kalman_filter(x_acceleration, &x_filter);
        double filtered_y = kalman_filter(y_acceleration, &y_filter);
        double filtered_z = kalman_filter(z_acceleration, &z_filter);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", filtered_x, filtered_y, filtered_z);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    printf("\nProgram terminated gracefully.\n");
    return 0;
}

