#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_1 4
#define GPIO_PIN_2 17
#define GPIO_PIN_3 27
#define VCC 3.3f
#define V_QUIESCENT (VCC / 2.0f)
#define SENSITIVITY 0.025f
#define MIN_MILLITESLA -100.0f
#define MAX_MILLITESLA 100.0f
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_sensor(struct gpiod_line *line, const char *name) {
    int ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error reading %s (GPIO %d): %s\n", name, gpiod_line_offset(line), strerror(errno));
        return -1;
    }
    return ret;
}

static float calculate_magnetic_field(int sensor_value) {
    float voltage = (float)sensor_value * (VCC / 2.0f);
    return (voltage - V_QUIESCENT) / SENSITIVITY;
}

static int log_data(float m1, float m2, float m3) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    fprintf(fp, "%.2f,%.2f,%.2f\n", m1, m2, m3);
    if (ferror(fp)) {
        fprintf(stderr, "Error writing to %s: %s\n", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    const int pins[3] = {GPIO_PIN_1, GPIO_PIN_2, GPIO_PIN_3};
    const char *names[3] = {"sensor1", "sensor2", "sensor3"};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "drv5055_reader") < 0) {
            fprintf(stderr, "Error requesting GPIO %d as input: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Reading DRV5055VA Hall-Effect sensors on GPIO%d, GPIO%d, GPIO%d...\n", GPIO_PIN_1, GPIO_PIN_2, GPIO_PIN_3);
    printf("Logging to %s every %d ms. Press Ctrl+C to exit.\n", LOG_FILE, SAMPLE_INTERVAL_MS);

    while (program_running) {
        int sensor_values[3];
        int error = 0;

        for (int i = 0; i < 3; i++) {
            sensor_values[i] = read_sensor(lines[i], names[i]);
            if (sensor_values[i] < 0) {
                error = 1;
                break;
            }
        }

        if (error) {
            fprintf(stderr, "Skipping logging due to read error.\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        float m1 = calculate_magnetic_field(sensor_values[0]);
        float m2 = calculate_magnetic_field(sensor_values[1]);
        float m3 = calculate_magnetic_field(sensor_values[2]);

        if (m1 < MIN_MILLITESLA || m1 > MAX_MILLITESLA ||
            m2 < MIN_MILLITESLA || m2 > MAX_MILLITESLA ||
            m3 < MIN_MILLITESLA || m3 > MAX_MILLITESLA) {
            fprintf(stderr, "Warning: Magnetic field out of range (sensor1: %.2f mT, sensor2: %.2f mT, sensor3: %.2f mT)\n",
                    m1, m2, m3);
        }

        if (log_data(m1, m2, m3) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

