#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define LOG_FILE "watering.log"
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "[%s] %s\n", timestamp, message);
    fclose(fp);
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Invalid MCP3008 channel");
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        log_event("SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        log_event("Failed to write pump GPIO");
        return;
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "Pump %s", state ? "ON" : "OFF");
    log_event(msg);
}

void cleanup() {
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    log_event("Watering system started");
    while (running) {
        int moisture = read_mcp3008(0);
        if (moisture < 0) {
            log_event("Failed to read moisture sensor");
        } else {
            int percent = (moisture * 100) / 1023;
            char msg[128];
            snprintf(msg, sizeof(msg), "Moisture level: %d%% (ADC: %d)", percent, moisture);
            log_event(msg);
            if (percent < MOISTURE_THRESHOLD) {
                control_pump(1);
            } else {
                control_pump(0);
            }
        }
        sleep(SAMPLE_INTERVAL);
    }
    log_event("Watering system stopped");
    cleanup();
    return 0;
}

