#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60
#define INITIAL_RECONNECT_DELAY 1

static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t led_state = 0;
static volatile sig_atomic_t pigpio_initialized = 0;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
        int rc = mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to topic");
        }
    } else {
        char msg[128];
        snprintf(msg, sizeof(msg), "MQTT connection error: %s", mosquitto_strerror(result));
        log_error(msg);
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m;
    (void)userdata;
    if (rc != MOSQ_ERR_SUCCESS) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Unexpected MQTT disconnect: %s", mosquitto_strerror(rc));
        log_error(msg);
    }
    printf("Disconnected from MQTT broker\n");
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;
    if (message->payloadlen > 0) {
        cJSON *root = cJSON_Parse((const char *)message->payload);
        if (root == NULL) {
            log_error("Failed to parse JSON payload");
            return;
        }
        cJSON *led_state_json = cJSON_GetObjectItemCaseSensitive(root, "led_state");
        if (led_state_json != NULL && cJSON_IsBool(led_state_json)) {
            led_state = (cJSON_IsTrue(led_state_json) ? 1 : 0);
            if (pigpio_initialized) {
                gpioWrite(GPIO_PIN, led_state);
            }
            printf("Received LED state: %d\n", led_state);
        } else {
            log_error("Invalid JSON payload: missing or non-boolean 'led_state'");
        }
        cJSON_Delete(root);
    }
}

static void on_subscribe(struct mosquitto *m, void *userdata, int mid, int qos_count, const int *granted_qos) {
    (void)m;
    (void)userdata;
    (void)mid;
    if (qos_count > 0 && granted_qos[0] > 0) {
        printf("Subscribed to topic\n");
    }
}

static void cleanup(void) {
    if (mosq != NULL) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
    if (pigpio_initialized) {
        gpioWrite(GPIO_PIN, 0);
        gpioTerminate();
        pigpio_initialized = 0;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }
    pigpio_initialized = 1;

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        log_error("Failed to set GPIO mode");
        cleanup();
        return 1;
    }
    gpioWrite(GPIO_PIN, 0);

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (mosq == NULL) {
        log_error("Failed to create MQTT client");
        cleanup();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_subscribe_callback_set(mosq, on_subscribe);

    int reconnect_delay = INITIAL_RECONNECT_DELAY;
    while (running) {
        int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
        if (rc != MOSQ_ERR_SUCCESS) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
            log_error(msg);
            sleep(reconnect_delay);
            reconnect_delay = (reconnect_delay * 2 > MAX_RECONNECT_DELAY) ? MAX_RECONNECT_DELAY : reconnect_delay * 2;
            continue;
        }
        mosquitto_loop_start(mosq);
        while (running) {
            mosquitto_loop(mosq, 100, 1);
            if (!running) break;
            if (mosquitto_reconnect_delayed(mosq) == MOSQ_ERR_SUCCESS) {
                mosquitto_loop_stop(mosq, false);
                mosquitto_reconnect(mosq);
                sleep(reconnect_delay);
                reconnect_delay = (reconnect_delay * 2 > MAX_RECONNECT_DELAY) ? MAX_RECONNECT_DELAY : reconnect_delay * 2;
                break;
            }
            sleep(1);
        }
        mosquitto_loop_stop(mosq, false);
    }

    mosquitto_loop_stop(mosq, true);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    return 0;
}

