    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_falling_edge_events(line, CONSUMER) < 0) {
        perror("gpiod_line_request_falling_edge_events");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Vibration monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE);

    while (program_running) {
        struct timespec ts = { 1, 0 }; /* 1-second timeout */
        int ret = gpiod_line_event_wait(line, &ts);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0) {
            continue; /* timeout, loop back to check program_running */
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_read");
            break;
        }

        if (log_vibration_event() < 0) {
            fprintf(stderr, "Failed to log vibration event.\n");
        }

        printf("Vibration detected on GPIO%d. Shutting down...\n", GPIO_LINE);

        int rc = system("sudo shutdown -h now");
        if (rc == -1) {
            perror("system(sudo shutdown)");
        } else if (rc != 0) {
            fprintf(stderr, "system(sudo shutdown) returned %d\n", rc);
        }

        break; /* exit loop after shutdown command is issued */
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

