#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE "flame_events.log"
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(int pin, int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s,%d,%d\n", timestamp, pin, state) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_input_flags(line, "flame_sensor",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input with pull-down: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    printf("Flame sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
            break;
        }

        log_event(GPIO_LINE_OFFSET, value);

        if (value == 1) {
            printf("Flame detected on GPIO %d!\n", GPIO_LINE_OFFSET);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup_chip:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return ret;
}

