#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MCP3008_CHANNEL 0
#define MCP4725_ADDR 0x62
#define I2C_BUS 1
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

static int spi_handle = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int write_mcp4725(int value) {
    if (value < 0 || value > 4095) {
        fprintf(stderr, "Invalid DAC value: %d\n", value);
        return -1;
    }
    unsigned char buf[3] = {0x40, (unsigned char)((value >> 4) & 0xFF), (unsigned char)((value << 4) & 0xF0)};
    int ret = i2cWriteDevice(i2c_handle, (char *)buf, 3);
    if (ret != 0) {
        fprintf(stderr, "I2C write failed (ret=%d)\n", ret);
        return -1;
    }
    return 0;
}

static float adc_to_celsius(int adc_value) {
    return (adc_value * 100.0f) / 1024.0f - 50.0f;
}

static float celsius_to_voltage(float celsius) {
    return (celsius / 50.0f) * 3.3f;
}

static int log_data(int adc_value, float temperature, float dac_voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(log_file, "%s, ADC: %d, Temp: %.2f C, DAC: %.2f V\n", timestamp, adc_value, temperature, dac_voltage) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    printf("%s, ADC: %d, Temp: %.2f C, DAC: %.2f V\n", timestamp, adc_value, temperature, dac_voltage);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, MCP4725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        spiClose(spi_handle);
        spi_handle = -1;
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        spiClose(spi_handle);
        spi_handle = -1;
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    printf("Temperature control system started. Press Ctrl+C to exit.\n");
    while (!terminate) {
        int adc_value = -1;
        int retries = 0;
        while (retries < MAX_RETRIES && !terminate) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) break;
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Retrying ADC read (%d/%d)\n", retries, MAX_RETRIES);
                gpioDelay(100000);
            }
        }
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        float temperature = adc_to_celsius(adc_value);
        float dac_voltage = celsius_to_voltage(temperature);
        if (write_mcp4725((int)(dac_voltage * 4095.0f / 3.3f + 0.5f)) != 0) {
            fprintf(stderr, "Failed to write DAC value\n");
        }
        if (log_data(adc_value, temperature, dac_voltage) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    cleanup();
    printf("Temperature control system stopped.\n");
    return 0;
}

