#define LOOP_DELAY_MS 1000

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS];
static const int relay_pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

static volatile sig_atomic_t keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

void deactivate_all_relays(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 0);
        }
    }
}

int main(void) {
    // Open GPIO chip 0 (gpiochip0 on Raspberry Pi 3 B+)
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    // Request each relay pin as output, initially LOW (inactive)
    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", relay_pins[i]);
            cleanup_and_exit(0);
            return EXIT_FAILURE;
        }

        int ret = gpiod_line_request_output(relay_lines[i], "relay-seq", 0);
        if (ret < 0) {
            perror("Failed to request output for relay line");
            cleanup_and_exit(0);
            return EXIT_FAILURE;
        }
    }

    // Set up signal handlers for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Relay sequencer started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        for (int i = 0; i < NUM_RELAYS && keep_running; i++) {
            // Activate relay
            if (gpiod_line_set_value(relay_lines[i], 1) < 0) {
                perror("Failed to activate relay");
                cleanup_and_exit(0);
                return EXIT_FAILURE;
            }
            printf("Relay %d activated\n", i + 1);

            // Wait for relay activation time
            usleep(RELAY_DELAY_MS * 1000);

            // Deactivate relay
            if (gpiod_line_set_value(relay_lines[i], 0) < 0) {
                perror("Failed to deactivate relay");
                cleanup_and_exit(0);
                return EXIT_FAILURE;
            }
            printf("Relay %d deactivated\n", i + 1);

            // Wait for delay between relays
            usleep(LOOP_DELAY_MS * 1000);
        }
    }

    // Cleanup
    deactivate_all_relays();
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_release(relay_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Relay sequencer stopped.\n");
    return EXIT_SUCCESS;
}

