#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_GPIO 16
#define SOUND_THRESHOLD 500
#define DEBOUNCE_DELAY_MS 100
#define LED_ON_DURATION_MS 500
#define LOOP_DELAY_MS 10

static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int result = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_event(void) {
    FILE *fp = fopen("sound_events.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Failed to close log file: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set LED GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to install SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sound_level = read_mcp3008(0);
        if (sound_level < 0) {
            fprintf(stderr, "Error: Failed to read sound level\n");
            gpioDelay(LOOP_DELAY_MS * 1000);
            continue;
        }

        if (sound_level > SOUND_THRESHOLD) {
            printf("Sound detected! Level: %d\n", sound_level);
            gpioWrite(LED_GPIO, 1);
            log_event();
            gpioDelay(LED_ON_DURATION_MS * 1000);
            gpioWrite(LED_GPIO, 0);
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
        }

        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

