#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* Motor driver pins (L298N) */
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000  /* 1 MHz */
#define SPI_MODE 0

/* Rain sensor channel on MCP3008 (single-ended, channel 0) */
#define RAIN_CHANNEL 0

/* Rain level threshold (0-10) */
#define RAIN_THRESHOLD 5

/* Motor PWM duty cycle (0-255) */
#define MOTOR_SPEED 150

/* Motor run duration (seconds) */
#define MOTOR_RUN_DURATION 3

/* Log file path */
#define LOG_FILE "rain_log.txt"

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* Function prototypes */
static int read_mcp3008(int channel);
static int convert_to_rain_level(int adc_value);
static void control_window(int rain_level);
static void log_rain_level(int rain_level);
static void signal_handler(int signal);
static void cleanup(void);

/* Read 10-bit value from MCP3008 single-ended channel (0-7) */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3];
    unsigned char rx[3];

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0, then don't-care */
    tx[0] = 0x01;                       /* Start bit */
    tx[1] = (unsigned char)((0x08 | channel) << 4); /* Single-ended + channel */
    tx[2] = 0x00;                       /* Don't care */

    if (spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + all 8 bits of rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* Convert ADC value (0-1023) to rain level (0-10) */
static int convert_to_rain_level(int adc_value) {
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    /* Invert: higher ADC = drier, so rain level 0 = dry, rain level 10 = heaviest rain */
    return 10 - (adc_value / 102);
}

/* Control window motor: close when rain_level >= RAIN_THRESHOLD, open otherwise */
static void control_window(int rain_level) {
    if (rain_level >= RAIN_THRESHOLD) {
        /* Close window: forward, PWM on */
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
        gpioPWM(MOTOR_ENA, MOTOR_SPEED);
        printf("Closing window (rain level %d >= %d)\n", rain_level, RAIN_THRESHOLD);
    } else {
        /* Open window: reverse, PWM on */
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
        gpioPWM(MOTOR_ENA, MOTOR_SPEED);
        printf("Opening window (rain level %d < %d)\n", rain_level, RAIN_THRESHOLD);
    }
}

/* Log rain level with timestamp to file */
static void log_rain_level(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(g_log_file, "%s, Rain Level: %d\n", timestamp, rain_level) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
    } else {
        fflush(g_log_file);
    }
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    g_running = 0;
}

/* Cleanup all resources */
static void cleanup(void) {
    /* Stop motor */
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0);

    /* Close SPI */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Close log file */
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor pins */
    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_ENA, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set motor GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialization failed (handle=%d)\n", g_spi_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGTERM handler\n");
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int adc_value = read_mcp3008(RAIN_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read rain sensor\n");
            sleep(1);
            continue;
        }

        int rain_level = convert_to_rain_level(adc_value);
        printf("Rain level: %d\n", rain_level);

        control_window(rain_level);
        log_rain_level(rain_level);

        /* Run motor for the configured duration, checking for shutdown */
        for (int i = 0; i < MOTOR_RUN_DURATION && g_running; i++) {
            sleep(1);
        }

        /* After motor run, stop motor to save power */
        gpioPWM(MOTOR_ENA, 0);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

