        fprintf(stderr, "Warning: Failed to install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGTERM handler\n");
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int adc_value = read_mcp3008(RAIN_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read rain sensor\n");
            sleep(1);
            continue;
        }

        int rain_level = convert_to_rain_level(adc_value);
        printf("Rain level: %d\n", rain_level);

        control_window(rain_level);
        log_rain_level(rain_level);

        /* Run motor for the configured duration, checking for shutdown */
        for (int i = 0; i < MOTOR_RUN_DURATION && g_running; i++) {
            sleep(1);
        }

        /* After motor run, stop motor to save power */
        gpioPWM(MOTOR_ENA, 0);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

