#define LOG_FILE "distance_log.txt"
#define GPIO_PATH "/sys/class/gpio/gpio%d/value"
#define CONSUMER "pet_feeder"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int gpio_export(int pin) {
    char buf[64];
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Failed to export GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int pin) {
    char buf[64];
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Failed to unexport GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int pin, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, dir, strlen(dir)) < 0) {
        fprintf(stderr, "Failed to set direction on %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_read_value(int pin) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    char value[2];
    ssize_t n = read(fd, value, sizeof(value) - 1);
    if (n < 0) {
        fprintf(stderr, "Failed to read %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    value[n] = '\0';
    close(fd);
    return atoi(value);
}

static double voltage_to_distance(int gpio_value) {
    if (gpio_value < 0) return -1.0;
    double voltage = (double)gpio_value / 255.0 * 3.3;
    return 26.0 / voltage - 6.0;
}

static void log_distance(double distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Distance: %.2f mm\n", timestamp, distance);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpio_export(GPIO_PIN) < 0) {
        return EXIT_FAILURE;
    }
    if (gpio_set_direction(GPIO_PIN, "in") < 0) {
        gpio_unexport(GPIO_PIN);
        return EXIT_FAILURE;
    }

    printf("Pet Feeder System Started. Press Ctrl+C to exit.\n");

    while (running) {
        int gpio_value = gpio_read_value(GPIO_PIN);
        if (gpio_value < 0) {
            fprintf(stderr, "Error reading GPIO %d. Retrying in 1 second.\n", GPIO_PIN);
            sleep(1);
            continue;
        }

        double distance = voltage_to_distance(gpio_value);
        if (distance < 0) {
            fprintf(stderr, "Invalid distance reading. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        log_distance(distance);

        if (distance < DISTANCE_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    gpio_unexport(GPIO_PIN);
    printf("Pet Feeder System Stopped.\n");
    return EXIT_SUCCESS;
}

