#define ADC_CHANNEL     0
#define VREF_MV         3300
#define ADC_MAX         1023
#define DRV5055_SENS_MV 100
#define DRV5055_QUIESCENT_MV 1650
#define SAMPLE_DELAY_MS 500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_adc(int fd, struct gpiod_line *cs_line, int channel) {
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Failed to set CS low: %s\n", strerror(errno));
        return -1;
    }
    usleep(10);
    if (spi_transfer(fd, tx, rx, 3) < 0) {
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to set CS high: %s\n", strerror(errno));
        return -1;
    }
    usleep(10);
    int adc = ((rx[1] & 0x03) << 8) | rx[2];
    return adc;
}

static float calculate_field_mv(int adc_value) {
    return (float)adc_value * VREF_MV / (float)ADC_MAX;
}

static float calculate_field_mt(float vout_mv) {
    return (vout_mv - DRV5055_QUIESCENT_MV) / (float)DRV5055_SENS_MV;
}

static int log_data(FILE *fp, time_t ts, float field_mt) {
    if (fprintf(fp, "%ld,%.2f\n", (long)ts, field_mt) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

