    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n", GPIO_CHIP, strerror(errno));
        close(spi_fd);
        return 1;
    }
    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, CS_GPIO_LINE);
    if (!cs_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", CS_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }
    if (gpiod_line_request_output(cs_line, "drv5055_cs", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    FILE *log_fp = fopen("magnetic_log.txt", "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open magnetic_log.txt: %s\n", strerror(errno));
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    printf("Starting magnetic field logging. Press Ctrl+C to stop.\n");

    while (g_running) {
        int adc = read_adc(spi_fd, cs_line, ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read error, skipping sample.\n");
        } else {
            float vout_mv = calculate_field_mv(adc);
            float field_mt = calculate_field_mt(vout_mv);
            time_t now = time(NULL);
            if (log_data(log_fp, now, field_mt) < 0) {
                fprintf(stderr, "Logging failed, continuing.\n");
            }
            printf("Timestamp: %ld, Magnetic Field: %.2f mT\n", (long)now, field_mt);
        }
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    fclose(log_fp);
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);
    return 0;
}

