#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LED_GPIO 21
#define VOLTAGE_THRESHOLD 10.0
#define SENSITIVITY_MV_PER_MT 1650.0
#define VCC 3.3
#define ADC_MAX 1023.0
#define LOG_FILE "magnetic_log.txt"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double voltage_to_field_mT(double voltage) {
    double quiescent = VCC / 2.0;
    double sensitivity = SENSITIVITY_MV_PER_MT / 1000.0;
    return (voltage - quiescent) * 1000.0 / sensitivity;
}

static int log_field(double field_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, Field: %.2f mT\n", ts, field_mT);
    }
    fclose(fp);
    return 0;
}

static void control_led(double field_mT) {
    int level = (field_mT > VOLTAGE_THRESHOLD) ? 1 : 0;
    if (gpioWrite(LED_GPIO, level) < 0) {
        fprintf(stderr, "gpioWrite LED failed\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode LED failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    printf("Magnetic field monitor started. Press Ctrl+C to exit.\n");
    while (running) {
        int adc = read_mcp3008(MCP3008_CHANNEL);
        if (adc < 0) {
            gpioDelay(100000);
            continue;
        }
        double voltage = (adc / ADC_MAX) * VCC;
        double field = voltage_to_field_mT(voltage);
        if (log_field(field) < 0) {
            fprintf(stderr, "Logging failed\n");
        }
        control_led(field);
        gpioDelay(100000);
    }
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

