#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "moisture_log.txt"
#define SAMPLE_INTERVAL 60

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx_buf[3] = {0};

    int result = spiXfer(spi_handle, (char *)tx_buf, (char *)rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: returned %d (expected 3)\n", result);
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

static void log_data(int adc_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    if (adc_value >= 0) {
        fprintf(fp, "%s, ADC Value: %d\n", timestamp, adc_value);
    } else {
        fprintf(fp, "%s, Error: Failed to read ADC value\n", timestamp);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

