        sleep(SAMPLE_INTERVAL);
    }

    printf("\nCleaning up and exiting...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

