#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

/* Configuration */
#define SPI_CHANNEL 0          /* CE0 on GPIO8 */
#define SPI_SPEED   1000000    /* 1 MHz */
#define SPI_MODE    0          /* SPI mode 0 (CPOL=0, CPHA=0) */
#define ADC_CHANNEL 0          /* MCP3008 single-ended channel 0 */
#define VREF        5.0        /* MCP3008 VDD tied to Pi 5V rail */
#define MLX_VDD     5.0        /* MLX91211 VDD tied to Pi 5V rail */
#define MLX_RATING  50.0       /* MLX91211 rated current (A) */
#define MLX_VZERO   2.5        /* MLX91211 output at zero current (VDD/2) */
#define LOG_FILE    "current_log.txt"
#define SAMPLE_US   100000     /* 100 ms between samples */

/* Globals for signal handler and cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for Ctrl+C */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read 10-bit value from MCP3008 single-ended channel (0-7) */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI command: start bit (1), single-ended mode (1), channel (3 bits), then don't-care */
    unsigned char tx[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
