    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler\n");
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            /* SPI error already reported; skip this sample */
            gpioDelay(SAMPLE_US);
            continue;
        }

        float current = adc_to_current(adc_value);

        /* Sanity check: voltage must be within 0-5V range */
        float voltage = (float)adc_value / 1023.0f * VREF;
        if (voltage < 0.0f || voltage > VREF) {
            fprintf(stderr, "Warning: Voltage %.2f V out of range, skipping sample\n", voltage);
            gpioDelay(SAMPLE_US);
            continue;
