#define CAPTURE_LOG "%s/cam_%Y%m%d_%H%M%S.jpg"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int ensure_directory(const char *path)
{
    if (access(path, F_OK) == 0) {
        if (access(path, W_OK) == 0)
            return 0;
        syslog(LOG_ERR, "Directory %s exists but is not writable: %s", path, strerror(errno));
        return -1;
    }
    if (mkdir(path, 0755) != 0 && errno != EEXIST) {
        syslog(LOG_ERR, "Failed to create directory %s: %s", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename)
{
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed: %s", strerror(errno));
        return -1;
    }
    if (pid == 0) {
        /* Child: redirect stdout/stderr to /dev/null to keep syslog clean */
        freopen("/dev/null", "w", stdout);
        freopen("/dev/null", "w", stderr);
        execlp("libcamera-still", "libcamera-still", "-o", filename, "-w", "1280", "-h", "720",
               "--encoding", "jpg", "--timeout", "1000", "-q", "85", "--immediate", "--iso", "8601", (char *)NULL);
        /* If exec fails */
        _exit(127);
    }
    /* Parent: wait for child */
    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR) {
            if (!g_running) {
                syslog(LOG_WARNING, "Capture interrupted by signal");
                return -1;
            }
            continue;
        }
        syslog(LOG_ERR, "waitpid() failed: %s", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        syslog(LOG_INFO, "Image captured: %s", filename);
        return 0;
    }
    syslog(LOG_ERR, "Capture failed (exit status %d)", WIFEXITED(status) ? WEXITSTATUS(status) : -1);
    return -1;
}

static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm *timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        syslog(LOG_ERR, "time() failed: %s", strerror(errno));
        return -1;
    }
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        syslog(LOG_ERR, "localtime() failed");
        return -1;
    }
    if (strftime(buf, len, "%Y%m%d_%H%M%S", timeinfo) == 0) {
        syslog(LOG_ERR, "strftime() failed");
        return -1;
    }
    return 0;
}

