        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        return -1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_GREY) {
        fprintf(stderr, "Device does not support 8-bit grayscale\n");
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        return -1;
    }

    void *buffer_start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer_start == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        return -1;
    }

    for (i = 0; i < req.count; i++) {
        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            munmap(buffer_start, buf.length);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        munmap(buffer_start, buf.length);
        return -1;
    }

    return 0;
}

static int capture_frame(int fd, unsigned char **image_data, size_t *image_size) {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return 0;
        fprintf(stderr, "select failed: %s\n", strerror(errno));
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        return -1;
    }

    *image_data = (unsigned char *)buffer_start;
    *image_size = buf.bytesused;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int save_image(const char *filename, const unsigned char *image_data, size_t image_size) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "fopen failed: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", (int)image_size, 1);
    if (fwrite(image_data, 1, image_size, fp) != image_size) {
        fprintf(stderr, "fwrite failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    const char *device = DEFAULT_DEVICE;
    size_t width = DEFAULT_WIDTH;
    size_t height = DEFAULT_HEIGHT;
    const char *filename = DEFAULT_FILENAME;
    int delay_ms = DEFAULT_DELAY_MS;
    int device_index = 0;
    int fd = -1;
    unsigned char *buffer_start = NULL;
    int ret = 1;

    while (device_index < argc && argv[device_index][0] == '-') {
        if (strcmp(argv[device_index], "-d") == 0 && device_index + 1 < argc) {
            device = argv[++device_index];
        } else if (strcmp(argv[device_index], "-w") == 0 && device_index + 1 < argc) {
            width = (size_t)atoi(argv[++device_index]);
        } else if (strcmp(argv[device_index], "-h") == 0 && device_index + 1 < argc) {
            height = (size_t)atoi(argv[++device_index]);
        } else if (strcmp(argv[device_index], "-f") == 0 && device_index + 1 < argc) {
            filename = argv[++device_index];
        } else if (strcmp(argv[device_index], "-s") == 0 && device_index + 1 < argc) {
            delay_ms = atoi(argv[++device_index]);
        } else {
            fprintf(stderr, "Unknown option: %s\n", argv[device_index]);
            goto cleanup;
        }
        device_index++;
    }

    if (device_index < argc) {
        device = argv[device_index];
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", device, strerror(errno));
        goto cleanup;
    }

    if (init_camera(fd, width, height) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        goto cleanup;
    }

    printf("Capturing %s... Press Ctrl+C to stop.\n", filename);

    while (!stop_flag) {
        unsigned char *image_data = NULL;
        size_t image_size = 0;

        if (capture_frame(fd, &image_data, &image_size) < 0) {
            fprintf(stderr, "Frame capture failed\n");
            break;
        }

        char filename_buf[256];
        snprintf(filename_buf, sizeof(filename_buf), filename, 1);

        if (save_image(filename_buf, image_data, image_size) < 0) {
            fprintf(stderr, "Image save failed\n");
            break;
        }

        printf("Saved: %s\n", filename_buf);

        usleep(delay_ms * 1000);
    }

    ret = 0;

cleanup:
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            fprintf(stderr, "VIDIOC_STREAMOFF failed: %s\n", strerror(errno));
        }
        if (buffer_start && buffer_start != MAP_FAILED) {
            munmap(buffer_start, buf.length);
        }
        close(fd);
    }
    return ret;
}

