    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *data = NULL;
    size_t size = 0;

    if (init_camera(&fd, &fmt, &req, &buf) < 0) {
        goto cleanup;
    }

    if (start_streaming(fd, &buf) < 0) {
        goto cleanup;
    }

    if (capture_frame(fd, &buf, &data, &size) < 0) {
        if (g_stop) {
            fprintf(stderr, "Interrupted by signal\n");
        } else {
            fprintf(stderr, "Failed to capture frame\n");
        }
        goto cleanup;
    }

    if (save_image(data, size, "image.jpg") < 0) {
        fprintf(stderr, "Failed to save image\n");
        free(data);
        data = NULL;
