#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH  1920
#define IMAGE_HEIGHT 1080
#define NUM_BUFFERS  4

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd, struct v4l2_format *fmt,
                       struct v4l2_requestbuffers *req,
                       struct v4l2_buffer *buf) {
    *fd = open(DEVICE_NAME, O_RDWR);
    if (*fd < 0) {
        perror("open device");
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, &fmt->capabilities) < 0) {
        perror("VIDIOC_QUERYCAP");
        goto fail;
    }
    if (!(fmt->capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto fail;
    }
    if (!(fmt->capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        goto fail;
    }

    memset(fmt, 0, sizeof(*fmt));
    fmt->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt->fmt.pix.width = IMAGE_WIDTH;
    fmt->fmt.pix.height = IMAGE_HEIGHT;
    fmt->fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt->fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, fmt) < 0) {
        perror("VIDIOC_S_FMT");
        goto fail;
    }

    if (fmt->fmt.pix.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Device does not support MJPEG format\n");
        goto fail;
    }

    memset(req, 0, sizeof(*req));
    req->count = NUM_BUFFERS;
    req->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req->memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, req) < 0) {
        perror("VIDIOC_REQBUFS");
        goto fail;
    }
    if (req->count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto fail;
    }

    for (int i = 0; i < req->count; i++) {
        memset(buf, 0, sizeof(*buf));
        buf->index = i;
        buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf->memory = V4L2_MEMORY_MMAP;

        if (xioctl(*fd, VIDIOC_QUERYBUF, buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            goto fail;
        }

        buf->length = buf->length;
        buf->m.offset = buf->m.offset;

        if (buf->length < 1024 * 1024) {
            fprintf(stderr, "Buffer %d too small (%u bytes)\n", i, buf->length);
            goto fail;
        }

        void *map = mmap(NULL, buf->length, PROT_READ | PROT_WRITE,
                         MAP_SHARED, *fd, buf->m.offset);
        if (map == MAP_FAILED) {
            perror("mmap");
            goto fail;
        }
        buf->m.userptr = (unsigned long)map;
        buf->m.length = buf->length;
    }
    return 0;

fail:
    close(*fd);
    *fd = -1;
    return -1;
}

static int start_streaming(int fd, struct v4l2_buffer *buf) {
    for (int i = 0; i < NUM_BUFFERS; i++) {
        memset(buf, 0, sizeof(*buf));
        buf->index = i;
        buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf->memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_QBUF, buf) < 0) {
            perror("VIDIOC_QBUF");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        return -1;
    }
    return 0;
}

static int capture_frame(int fd, struct v4l2_buffer *buf, unsigned char **out_data,
                         size_t *out_size) {
    for (int i = 0; i < 20; i++) {
        if (g_stop) return -1;
        if (xioctl(fd, VIDIOC_DQBUF, buf) == 0) break;
        if (errno == EAGAIN) continue;
        perror("VIDIOC_DQBUF");
        return -1;
    }
    if (g_stop) return -1;

    if (buf->bytesused == 0) {
        fprintf(stderr, "Empty frame\n");
        return -1;
    }

    *out_data = malloc(buf->bytesused);
    if (!*out_data) {
        perror("malloc");
        return -1;
    }
    memcpy(*out_data, (unsigned char *)buf->m.userptr, buf->bytesused);
    *out_size = buf->bytesused;

    if (xioctl(fd, VIDIOC_QBUF, buf) < 0) {
        perror("VIDIOC_QBUF");
        free(*out_data);
        *out_data = NULL;
        return -1;
    }
    return 0;
}

static int save_image(const unsigned char *data, size_t size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    size_t written = fwrite(data, 1, size, fp);
    if (written != size) {
        fprintf(stderr, "Short write: %zu of %zu bytes\n", written, size);
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    int fd = -1;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *data = NULL;
    size_t size = 0;

    if (init_camera(&fd, &fmt, &req, &buf) < 0) {
        goto cleanup;
    }

    if (start_streaming(fd, &buf) < 0) {
        goto cleanup;
    }

    if (capture_frame(fd, &buf, &data, &size) < 0) {
        if (g_stop) {
            fprintf(stderr, "Interrupted by signal\n");
        } else {
            fprintf(stderr, "Failed to capture frame\n");
        }
        goto cleanup;
    }

    if (save_image(data, size, "image.jpg") < 0) {
        fprintf(stderr, "Failed to save image\n");
        free(data);
        data = NULL;
        goto cleanup;
    }

    printf("Saved %zu bytes to image.jpg\n", size);

cleanup:
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        for (int i = 0; i < NUM_BUFFERS; i++) {
            struct v4l2_buffer *b = &buf;
            b->index = i;
            b->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            b->memory = V4L2_MEMORY_MMAP;
            xioctl(fd, VIDIOC_QBUF, b);
        }
        close(fd);
    }
    if (data) free(data);
    return 0;
}

