#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define PAN_SERVO_PIN      4
#define TILT_SERVO_PIN     5
#define TILT_UP_PIN        6
#define TILT_DOWN_PIN      7
#define PAN_LEFT_PIN       8
#define PAN_RIGHT_PIN      9

#define SERVO_MIN_PULSE_US 1000
#define SERVO_MAX_PULSE_US 2000
#define SERVO_MID          1500
#define SERVO_MIN          25
#define SERVO_MAX          125
#define SERVO_RANGE        (SERVO_MAX - SERVO_MIN + 1)
#define PWM_PERIOD_US      20000
#define PWM_DUTY_MIN       50
#define PWM_DUTY_MAX       1000
#define POLL_INTERVAL_US   50000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int map_range(int x, int in_min, int in_max, int out_min, int out_max) {
    if (in_max == in_min) return out_min;
    return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

static int set_servo_position(struct gpiod_line *line, int position) {
    if (position < SERVO_MIN) position = SERVO_MIN;
    if (position > SERVO_MAX) position = SERVO_MAX;

    int pulse_us = map_range(position, SERVO_MIN, SERVO_MAX, SERVO_MIN_PULSE_US, SERVO_MAX_PULSE_US);
    int duty = map_range(pulse_us, SERVO_MIN_PULSE_US, SERVO_MAX_PULSE_US, PWM_DUTY_MIN, PWM_DUTY_MAX);

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set line high: %s\n", strerror(errno));
        return -1;
    }
    usleep(duty);
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set line low: %s\n", strerror(errno));
        return -1;
    }
    usleep(PWM_PERIOD_US - duty);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pan_line = NULL;
    struct gpiod_line *tilt_line = NULL;
    struct gpiod_line *tilt_up_line = NULL;
    struct gpiod_line *tilt_down_line = NULL;
    struct gpiod_line *pan_left_line = NULL;
    struct gpiod_line *pan_right_line = NULL;
    int pan_position = SERVO_MID;
    int tilt_position = SERVO_MID;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    pan_line = gpiod_chip_get_line(chip, PAN_SERVO_PIN);
    tilt_line = gpiod_chip_get_line(chip, TILT_SERVO_PIN);
    tilt_up_line = gpiod_chip_get_line(chip, TILT_UP_PIN);
    tilt_down_line = gpiod_chip_get_line(chip, TILT_DOWN_PIN);
    pan_left_line = gpiod_chip_get_line(chip, PAN_LEFT_PIN);
    pan_right_line = gpiod_chip_get_line(chip, PAN_RIGHT_PIN);

    if (!pan_line || !tilt_line || !tilt_up_line || !tilt_down_line || !pan_left_line || !pan_right_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(pan_line, "pan_servo", 0) < 0) {
        fprintf(stderr, "Failed to request pan line as output: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(tilt_line, "tilt_servo", 0) < 0) {
        fprintf(stderr, "Failed to request tilt line as output: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(tilt_up_line, "tilt_up") < 0) {
        fprintf(stderr, "Failed to request tilt up line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(tilt_down_line, "tilt_down") < 0) {
        fprintf(stderr, "Failed to request tilt down line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(pan_left_line, "pan_left") < 0) {
        fprintf(stderr, "Failed to request pan left line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(pan_right_line, "pan_right") < 0) {
        fprintf(stderr, "Failed to request pan right line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(tilt_up_line, "tilt_up") < 0 ||
        gpiod_line_request_input(tilt_down_line, "tilt_down") < 0 ||
        gpiod_line_request_input(pan_left_line, "pan_left") < 0 ||
        gpiod_line_request_input(pan_right_line, "pan_right") < 0) {
        fprintf(stderr, "Failed to request button lines as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_set_flags(tilt_up_line, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0 ||
        gpiod_line_set_flags(tilt_down_line, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0 ||
        gpiod_line_set_flags(pan_left_line, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0 ||
        gpiod_line_set_flags(pan_right_line, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on button lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (set_servo_position(pan_line, pan_position) < 0 ||
        set_servo_position(tilt_line, tilt_position) < 0) {
        goto cleanup;
    }

    while (running) {
        int tilt_up = gpiod_line_get_value(tilt_up_line);
        int tilt_down = gpiod_line_get_value(tilt_down_line);
        int pan_left = gpiod_line_get_value(pan_left_line);
        int pan_right = gpiod_line_get_value(pan_right_line);

        if (tilt_up == 0) {
            tilt_position = map_range(tilt_position, SERVO_MIN, SERVO_MAX, SERVO_MIN, SERVO_MAX - 5);
            if (tilt_position < SERVO_MIN) tilt_position = SERVO_MIN;
            if (set_servo_position(tilt_line, tilt_position) < 0) {
                goto cleanup;
            }
        }
        if (tilt_down == 0) {
            tilt_position = map_range(tilt_position, SERVO_MIN, SERVO_MAX, SERVO_MIN + 5, SERVO_MAX);
            if (tilt_position > SERVO_MAX) tilt_position = SERVO_MAX;
            if (set_servo_position(tilt_line, tilt_position) < 0) {
                goto cleanup;
            }
        }
        if (pan_left == 0) {
            pan_position = map_range(pan_position, SERVO_MIN, SERVO_MAX, SERVO_MIN, SERVO_MAX - 5);
            if (pan_position < SERVO_MIN) pan_position = SERVO_MIN;
            if (set_servo_position(pan_line, pan_position) < 0) {
                goto cleanup;
            }
        }
        if (pan_right == 0) {
            pan_position = map_range(pan_position, SERVO_MIN, SERVO_MAX, SERVO_MIN + 5, SERVO_MAX);
            if (pan_position > SERVO_MAX) pan_position = SERVO_MAX;
            if (set_servo_position(pan_line, pan_position) < 0) {
                goto cleanup;
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (pan_line) gpiod_line_release(pan_line);
    if (tilt_line) gpiod_line_release(tilt_line);
    if (tilt_up_line) gpiod_line_release(tilt_up_line);
    if (tilt_down_line) gpiod_line_release(tilt_down_line);
    if (pan_left_line) gpiod_line_release(pan_left_line);
    if (pan_right_line) gpiod_line_release(pan_right_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

