#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <jpeglib.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FORMAT V4L2_PIX_FMT_YUYV
#define NUM_BUFFERS 4
#define BLUR_KERNEL_SIZE 5
#define BLUR_RADIUS 2
#define JPEG_QUALITY 75
#define CAPTURE_TIMEOUT_SEC 2

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd, struct v4l2_format *fmt) {
    *fd = open(DEVICE_NAME, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    struct v4l2_capability cap;
    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(*fd);
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(*fd);
        return -1;
    }

    memset(fmt, 0, sizeof(*fmt));
    fmt->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt->fmt.pix.width = WIDTH;
    fmt->fmt.pix.height = HEIGHT;
    fmt->fmt.pix.pixelformat = FORMAT;
    fmt->fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(*fd, VIDIOC_S_FMT, fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }
    if (fmt->fmt.pix.pixelformat != FORMAT) {
        fprintf(stderr, "Warning: driver did not accept YUYV format\n");
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    for (int i = 0; i < NUM_BUFFERS; i++) {
        buf.index = i;
        if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer %d: %s\n", i, strerror(errno));
            close(*fd);
            return -1;
        }
        void *addr = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);
        if (addr == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %d: %s\n", i, strerror(errno));
            close(*fd);
            return -1;
        }
        if (xioctl(*fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer %d: %s\n", i, strerror(errno));
            munmap(addr, buf.length);
            close(*fd);
            return -1;
        }
    }
    return 0;
}

static int capture_frame(int fd, struct v4l2_buffer *buf, unsigned char **frame, int *frame_len) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = CAPTURE_TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    memset(buf, 0, sizeof(*buf));
    buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    *frame_len = buf->bytesused;
    *frame = malloc(buf->bytesused);
    if (!*frame) {
        fprintf(stderr, "Error allocating memory for frame: %s\n", strerror(errno));
        xioctl(fd, VIDIOC_QBUF, buf);
        return -1;
    }
    memcpy(*frame, (unsigned char *)buf + buf->m.offset, buf->bytesused);
    xioctl(fd, VIDIOC_QBUF, buf);
    return 0;
}

static void yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            int idx = (i * width + j) * 2;
            int y1 = yuyv[idx];
            int u = yuyv[idx + 1];
            int y2 = yuyv[idx + 2];
            int v = yuyv[idx + 3];

            int r1 = y1 + (1402 * (v - 128)) / 1000;
            int g1 = y1 - (344 * (u - 128)) / 1000 - (714 * (v - 128)) / 1000;
            int b1 = y1 + (1772 * (u - 128)) / 1000;

            int r2 = y2 + (1402 * (v - 128)) / 1000;
            int g2 = y2 - (344 * (u - 128)) / 1000 - (714 * (v - 128)) / 1000;
            int b2 = y2 + (1772 * (u - 128)) / 1000;

            int idx_rgb = (i * width + j) * 3;
            rgb[idx_rgb] = (r1 > 255) ? 255 : (r1 < 0) ? 0 : r1;
            rgb[idx_rgb + 1] = (g1 > 255) ? 255 : (g1 < 0) ? 0 : g1;
            rgb[idx_rgb + 2] = (b1 > 255) ? 255 : (b1 < 0) ? 0 : b1;
            rgb[idx_rgb + 3] = (r2 > 255) ? 255 : (r2 < 0) ? 0 : r2;
            rgb[idx_rgb + 4] = (g2 > 255) ? 255 : (g2 < 0) ? 0 : g2;
            rgb[idx_rgb + 5] = (b2 > 255) ? 255 : (b2 < 0) ? 0 : b2;
        }
    }
}

static void box_blur(unsigned char *rgb, int width, int height, int kernel_size, int radius) {
    int kernel_radius = (kernel_size - 1) / 2;
    int kernel_size_sq = kernel_size * kernel_size;
    unsigned char *temp = malloc(width * height * 3);
    if (!temp) {
        fprintf(stderr, "Error allocating temp buffer\n");
        return;
    }
    memcpy(temp, rgb, width * height * 3);

    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            int sum[3] = {0, 0, 0};
            for (int k = -radius; k <= radius; k++) {
                int y = i + k;
                if (y < 0 || y >= height) continue;
                for (int l = -radius; l <= radius; l++) {
                    int x = j + l;
                    if (x < 0 || x >= width) continue;
                    for (int c = 0; c < 3; c++) {
                        sum[c] += temp[(y * width + x) * 3 + c];
                    }
                }
            }
            for (int c = 0; c < 3; c++) {
                rgb[(i * width + j) * 3 + c] = (sum[c] + kernel_size_sq / 2) / kernel_size_sq;
            }
        }
    }
    free(temp);
}

static int save_jpeg(const char *filename, const unsigned char *rgb, int width, int height, int quality) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile = NULL;
    JSAMPROW row_pointer[1];
    int row_stride = width * 3;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    outfile = fopen(filename, "wb");
    if (!outfile) {
        fprintf(stderr, "Error opening output file: %s\n", strerror(errno));
        jpeg_destroy_compress(&cinfo);
        return -1;
    }
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;
    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);
    return 0;
}

int main(void) {
    int fd = -1;
    struct v4l2_format fmt;
    unsigned char *frame = NULL;
    int frame_len = 0;
    char filename[256];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (init_camera(&fd, &fmt) < 0) {
        return 1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_STREAMON, &buf.type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (capture_frame(fd, &buf, &frame, &frame_len) < 0) {
        xioctl(fd, VIDIOC_STREAMOFF, &buf.type);
        close(fd);
        return 1;
    }

    yuyv_to_rgb24(frame, frame, WIDTH, HEIGHT);
    box_blur(frame, WIDTH, HEIGHT, BLUR_KERNEL_SIZE, BLUR_RADIUS);

    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

    if (save_jpeg(filename, frame, WIDTH, HEIGHT, JPEG_QUALITY) < 0) {
        fprintf(stderr, "Error saving JPEG\n");
    } else {
        printf("Saved %s\n", filename);
    }

    xioctl(fd, VIDIOC_STREAMOFF, &buf.type);
    free(frame);
    close(fd);
    return 0;
}

