            } else if (frmsize.type == V4L2_FRMSIZE_TYPE_CONTINUOUS) {
                printf("  Continuous\n");
            }
            frmsize.index++;
        }
        if (errno != EINVAL) {
            fprintf(stderr, "Error enumerating frame sizes: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    if (!(cap.capabilities & V4L2_CAP_TIMEPERFRAME)) {
        printf("  Frame interval enumeration not supported\n");
    } else {
        printf("Supported frame rates:\n");
        struct v4l2_frmivalenum frmival;
