        frmival.index = 0;
        frmival.pixel_format = V4L2_PIX_FMT_ANY;

        while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
            if (frmival.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
                print_frame_rate("Discrete", frmival.discrete.numerator,
                                 frmival.discrete.denominator);
            } else if (frmival.type == V4L2_FRMIVAL_TYPE_STEPWISE) {
                printf("  Stepwise: min %u/%u, max %u/%u\n",
                       frmival.stepwise.min.numerator, frmival.stepwise.min.denominator,
                       frmival.stepwise.max.numerator, frmival.stepwise.max.denominator);
            } else if (frmival.type == V4L2_FRMIVAL_TYPE_CONTINUOUS) {
                printf("  Continuous\n");
            }
            frmival.index++;
        }
        if (errno != EINVAL) {
            fprintf(stderr, "Error enumerating frame intervals: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    struct v4l2_queryctrl ctrl;
    memset(&ctrl, 0, sizeof(ctrl));
    ctrl.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &ctrl) < 0) {
        if (errno == EINVAL) {
            printf("Autofocus control not supported\n");
        } else {
            fprintf(stderr, "Error querying focus control: %s\n", strerror(errno));
        }
    } else {
        printf("Autofocus control supported: %s\n", ctrl.flags & V4L2_CTRL_FLAG_ENABLED ? "yes" : "no");
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

