#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5
#define UP_BUTTON_PIN    6
#define DOWN_BUTTON_PIN  7
#define LEFT_BUTTON_PIN  8
#define RIGHT_BUTTON_PIN 9

#define SERVO_MIN_PULSE  1000
#define SERVO_MAX_PULSE  2000
#define SERVO_CENTER     1500
#define LOOP_DELAY_US    50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int set_servo(int pin, int pulse_us)
{
    if (pulse_us < SERVO_MIN_PULSE || pulse_us > SERVO_MAX_PULSE) {
        fprintf(stderr, "Error: pulse %d us out of range [%d, %d]\n",
                pulse_us, SERVO_MIN_PULSE, SERVO_MAX_PULSE);
        return -1;
    }
    if (gpioServo(pin, pulse_us) != 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed\n", pin, pulse_us);
        return -1;
    }
    return 0;
}

static int read_button(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed\n", pin);
        return -1;
    }
    return (v == 0) ? 1 : 0;  /* active-low */
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with internal pull-ups (active-low) */
    int button_pins[] = {UP_BUTTON_PIN, DOWN_BUTTON_PIN,
                         LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN};
    for (size_t i = 0; i < sizeof(button_pins) / sizeof(button_pins[0]); ++i) {
        if (gpioSetMode(button_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(%d, INPUT) failed\n", button_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(button_pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown(%d, UP) failed\n", button_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Configure servo pins as outputs (gpioServo drives PWM) */
    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, OUTPUT) failed\n", PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, OUTPUT) failed\n", TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Center both servos */
    if (set_servo(PAN_SERVO_PIN, SERVO_CENTER) != 0 ||
        set_servo(TILT_SERVO_PIN, SERVO_CENTER) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pan-tilt control started.\n");
    printf("  Pan servo : GPIO%d (center %d us)\n", PAN_SERVO_PIN, SERVO_CENTER);
    printf("  Tilt servo: GPIO%d (center %d us)\n", TILT_SERVO_PIN, SERVO_CENTER);
    printf("  Buttons: UP=GPIO%d, DOWN=GPIO%d, LEFT=GPIO%d, RIGHT=GPIO%d\n",
           UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");

    int pan_pos   = SERVO_CENTER;
    int tilt_pos  = SERVO_CENTER;

    while (g_running) {
        int up   = read_button(UP_BUTTON_PIN);
        int down = read_button(DOWN_BUTTON_PIN);
        int left = read_button(LEFT_BUTTON_PIN);
        int right = read_button(RIGHT_BUTTON_PIN);

        if (up < 0 || down < 0 || left < 0 || right < 0) {
            break;
        }

        if (up) {
            pan_pos   += 10;
            tilt_pos  += 10;
        } else if (down) {
            pan_pos   -= 10;
            tilt_pos  -= 10;
        } else if (left) {
            pan_pos   -= 10;
        } else if (right) {
            pan_pos   += 10;
        }

        if (pan_pos < SERVO_MIN_PULSE) pan_pos = SERVO_MIN_PULSE;
        if (pan_pos > SERVO_MAX_PULSE) pan_pos = SERVO_MAX_PULSE;
        if (tilt_pos < SERVO_MIN_PULSE) tilt_pos = SERVO_MIN_PULSE;
        if (tilt_pos > SERVO_MAX_PULSE) tilt_pos = SERVO_MAX_PULSE;

        if (set_servo(PAN_SERVO_PIN, pan_pos) != 0 ||
            set_servo(TILT_SERVO_PIN, tilt_pos) != 0) {
            break;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown: stop PWM on both servo pins */
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

