#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>
#include <curl/curl.h>

#define PIR_GPIO 17
#define DEBOUNCE_MS 2000
#define POLL_INTERVAL_MS 100
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CAPTURE_QUALITY 85
#define MOTION_STATUS 1
#define SERVER_IP "127.0.0.1"
#define SERVER_PORT "8080"
#define MOTION_CAPTURE_DIR "motion_captures"
#define TIMESTAMP_LEN 32
#define FILENAME_LEN 64
#define JSON_BUF_LEN 512

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int create_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: %s exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        if (errno != EEXIST) {
            fprintf(stderr, "Error creating directory %s: %s\n", path, strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command),
             "libcamera-still -o %s -w %d -h %d --quality %d --nopreview 2>/dev/null",
             filename, CAPTURE_WIDTH, CAPTURE_HEIGHT, CAPTURE_QUALITY);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error: system() failed to execute libcamera-still: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: libcamera-still failed (status=0x%04X)\n", status);
        return -1;
    }
    return 0;
}

static int send_data(const char *server_ip, const char *server_port, const char *filename) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error: curl_easy_init() failed\n");
        return -1;
    }

    char json[JSON_BUF_LEN];
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[TIMESTAMP_LEN];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Error: localtime() failed\n");
        curl_easy_cleanup(curl);
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    snprintf(json, sizeof(json),
             "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion_status\":%d,\"gpio_pin\":%d}",
             filename, timestamp, MOTION_STATUS, PIR_GPIO);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "Error: curl_slist_append() failed\n");
        curl_easy_cleanup(curl);
        return -1;
    }

