#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define PIR_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_MS 50
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }
    fclose(fp);
}

static int capture_image(void) {
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        log_event("localtime_r failed");
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", &tm);
    char filename[256];
    snprintf(filename, sizeof(filename), "%s/%s_mmm.jpg", IMAGE_DIR, timestamp);

    char command[512];
    snprintf(command, sizeof(command),
             "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview",
             filename);

    int ret = system(command);
    if (ret == -1) {
        log_event("system() failed");
        return -1;
    }
    if (!WIFEXITED(ret) || WEXITSTATUS(ret) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "libcamera-still failed (ret=%d)", ret);
        log_event(msg);
        return -1;
    }
    log_event("Image captured successfully");
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        log_event("Failed to open GPIO chip");
        return 1;
    }

    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        perror("gpiod_chip_get_line");
        log_event("Failed to get PIR GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_falling_edge_events(pir_line, "pir-motion") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        log_event("Failed to request falling edge events on PIR line");
        gpiod_chip_close(chip);
        return 1;
    }

    log_event("Motion detection started on GPIO17");

    while (program_running) {
        struct timespec ts = {0, POLL_TIMEOUT_MS * 1000000L};
        int ret = gpiod_line_event_wait(pir_line, &ts);
        if (ret < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_wait");
            log_event("GPIO event wait error");
            break;
        }
        if (ret == 0) continue;

        struct gpiod_line_event event;
        if (gpiod_line_event_read(pir_line, &event) < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_read");
            log_event("GPIO event read error");
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            log_event("Motion detected");
            if (capture_image() != 0) {
                log_event("Image capture failed");
            }
        }
    }

    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    log_event("Motion detection stopped");
    return 0;
}

