#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define CROP_X 100
#define CROP_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define CROP_SIZE (CROP_WIDTH * CROP_HEIGHT)
#define YUYV_SIZE (CROP_SIZE * 2)
#define TIMEOUT_SEC 2

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_device(int *fd, struct v4l2_format *fmt,
                       struct v4l2_requestbuffers *req,
                       struct v4l2_buffer *buf) {
    *fd = open(DEVICE_NAME, O_RDWR);
    if (*fd < 0) {
        perror("open device");
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        goto fail;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto fail;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        goto fail;
    }

    memset(fmt, 0, sizeof(*fmt));
    fmt->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt->fmt.pix.width = WIDTH;
    fmt->fmt.pix.height = HEIGHT;
    fmt->fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt->fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(*fd, VIDIOC_S_FMT, fmt) < 0) {
        perror("VIDIOC_S_FMT");
        goto fail;
    }
    if (fmt->fmt.pix.width != WIDTH || fmt->fmt.pix.height != HEIGHT) {
        fprintf(stderr, "Warning: driver did not accept %dx%d, got %dx%d\n",
                WIDTH, HEIGHT, fmt->fmt.pix.width, fmt->fmt.pix.height);
    }

    memset(req, 0, sizeof(*req));
    req->count = 1;
    req->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req->memory = V4L2_MEMORY_MMAP;
    if (xioctl(*fd, VIDIOC_REQBUFS, req) < 0) {
        perror("VIDIOC_REQBUFS");
        goto fail;
    }

    memset(buf, 0, sizeof(*buf));
    buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;
    buf->index = 0;
    if (xioctl(*fd, VIDIOC_QUERYBUF, buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        goto fail;
    }

    buf->length = buf->length > 0 ? buf->length : req->length;
    void *map = mmap(NULL, buf->length, PROT_READ | PROT_WRITE, MAP_SHARED,
                     *fd, buf->m.offset);
    if (map == MAP_FAILED) {
        perror("mmap");
        goto fail;
    }
    if (xioctl(*fd, VIDIOC_QBUF, buf) < 0) {
        perror("VIDIOC_QBUF");
        munmap(map, buf->length);
        goto fail;
    }
    return 0;

fail:
    close(*fd);
    *fd = -1;
    return -1;
}

static int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
