#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_GPIO 17
#define TILT_GPIO 18
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define NEUTRAL_ANGLE 90
#define STEP_SIZE 5
#define DELAY_MS 100

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int set_servo_angle(int gpio, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range [%d, %d]\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)angle / MAX_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));
    if (gpioServo(gpio, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set PWM on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    if (gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d\n", PAN_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d\n", TILT_GPIO);
        gpioTerminate();
        return 1;
    }

    int pan_angle = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    if (set_servo_angle(PAN_GPIO, pan_angle) != 0 || set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    printf("Pan-Tilt Camera Mount Control\n");
    printf("Arrow keys: Up/Down=tilt, Left/Right=pan. 'q' to quit.\n");
    printf("Current: Pan=%d, Tilt=%d\n", pan_angle, tilt_angle);

    while (keep_running) {
        int c = getchar();
        if (c == 'q') break;
        if (c == 'w') {
            if (pan_angle + STEP_SIZE <= MAX_ANGLE) {
                pan_angle += STEP_SIZE;
                if (set_servo_angle(PAN_GPIO, pan_angle) == 0) {
                    printf("Pan: %d\n", pan_angle);
                }
            }
        } else if (c == 's') {
            if (pan_angle - STEP_SIZE >= MIN_ANGLE) {
                pan_angle -= STEP_SIZE;
                if (set_servo_angle(PAN_GPIO, pan_angle) == 0) {
                    printf("Pan: %d\n", pan_angle);
                }
            }
        } else if (c == 'a') {
            if (tilt_angle - STEP_SIZE >= MIN_ANGLE) {
                tilt_angle -= STEP_SIZE;
                if (set_servo_angle(TILT_GPIO, tilt_angle) == 0) {
                    printf("Tilt: %d\n", tilt_angle);
                }
            }
        } else if (c == 'd') {
            if (tilt_angle + STEP_SIZE <= MAX_ANGLE) {
                tilt_angle += STEP_SIZE;
                if (set_servo_angle(TILT_GPIO, tilt_angle) == 0) {
                    printf("Tilt: %d\n", tilt_angle);
                }
            }
        }
        usleep(DELAY_MS * 1000);
    }

    set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE);
    set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

