#include <pigpio.h>

#define OLED_WIDTH 128
#define OLED_HEIGHT 64
#define OLED_I2C_ADDR 0x3C
#define I2C_BUS 1

#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64
#define SSD1306_PAGES (SSD1306_HEIGHT / 8)

#define SSD1306_CMD 0x00
#define SSD1306_DATA 0x40

#define SSD1306_DISPLAY_OFF 0xAE
#define SSD1306_DISPLAY_ON 0xAF
#define SSD1306_SET_DISPLAY_CLOCK_DIV 0xD5
#define SSD1306_SET_MULTIPLEX 0xA8
#define SSD1306_SET_DISPLAY_OFFSET 0xD3
#define SSD1306_SET_START_LINE 0x40
#define SSD1306_CHARGE_PUMP 0x8D
#define SSD1306_MEMORY_MODE 0x20
#define SSD1306_SEG_REMAP 0xA0
#define SSD1306_COM_SCAN_DEC 0xC8
#define SSD1306_COM_PIN_CFG 0x12
#define SSD1306_SET_CONTRAST 0x81
#define SSD1306_SET_PRECHARGE 0xD9
#define SSD1306_SET_VCOMDETECT 0xDB
#define SSD1306_DISPLAY_ALL_ON_RESUME 0xA4
#define SSD1306_NORMAL_DISPLAY 0xA6
#define SSD1306_COLUMN_ADDR 0x21
#define SSD1306_PAGE_ADDR 0x22
#define SSD1306_DISPLAY_RAM 0x00

#define TEMP_ERROR "N/A"
#define USAGE_ERROR "N/A"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ssd1306_command(unsigned char cmd) {
    char buf[2] = {SSD1306_CMD, (char)cmd};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write error: command 0x%02X\n", cmd);
        return -1;
    }
    return 0;
}

static int ssd1306_command2(unsigned char cmd, unsigned char arg) {
    char buf[3] = {SSD1306_CMD, (char)cmd, (char)arg};
    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "I2C write error: command 0x%02X arg 0x%02X\n", cmd, arg);
        return -1;
    }
    return 0;
