static int ssd1306_draw_string(int x, int y, const char *str) {
    int col = x;
    for (int i = 0; str[i] != '\0'; i++) {
        if (col + 5 > OLED_WIDTH) {
            col = x;
            y += 6;
            if (y + 6 > OLED_HEIGHT) return -1;
        }
        unsigned char c = (unsigned char)str[i];
        if (c >= 32 && c < 128) {
            const unsigned char *glyph = font5x7[c - 32];
            for (int j = 0; j < 5; j++) {
                unsigned char byte = glyph[j];
                for (int bit = 0; bit < 8; bit++) {
                    if (byte & (1 << bit)) {
                        if (ssd1306_set_cursor(col + j, y / 8) != 0) return -1;
                        if (i2cWriteByte(i2c_handle, SSD1306_DATA) != 0) return -1;
                        if (i2cWriteByte(i2c_handle, 0x01) != 0) return -1;
                    }
                }
            }
        }
        col += 6;
    }
    return 0;
}

static const char *read_cpu_temp(void) {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        fprintf(stderr, "Error opening CPU temperature file\n");
        return TEMP_ERROR;
    }
    char buffer[16];
    if (!fgets(buffer, sizeof(buffer), fp)) {
        fprintf(stderr, "Error reading CPU temperature\n");
        fclose(fp);
        return TEMP_ERROR;
    }
    fclose(fp);
    return buffer;
}

static const char *read_cpu_usage(void) {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error opening CPU usage file\n");
        return USAGE_ERROR;
    }
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error parsing CPU usage data\n");
        fclose(fp);
        return USAGE_ERROR;
    }
    fclose(fp);
    unsigned long long prev_idle = idle + iowait;
    unsigned long long prev_non_idle = user + nice + system + irq + softirq + steal;
    unsigned long long prev_total = prev_idle + prev_non_idle;
    time_sleep(1.0);
    fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error opening CPU usage file (2)\n");
        return USAGE_ERROR;
    }
    unsigned long long user2, nice2, system2, idle2, iowait2, irq2, softirq2, steal2, guest2, guest_nice2;
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user2, &nice2, &system2, &idle2, &iowait2, &irq2, &softirq2, &steal2, &guest2, &guest_nice2) != 10) {
        fprintf(stderr, "Error parsing CPU usage data (2)\n");
        fclose(fp);
        return USAGE_ERROR;
    }
    fclose(fp);
    unsigned long long idle2_total = idle2 + iowait2;
    unsigned long long non_idle2_total = user2 + nice2 + system2 + irq2 + softirq2 + steal2;
    unsigned long long total2 = idle2_total + non_idle2_total;
    unsigned long long totald = total2 - prev_total;
    unsigned long long idled = idle2_total - prev_idle;
    double usage = ((double)(totald - idled) / totald) * 100.0;
    char buffer[32];
    snprintf(buffer, sizeof(buffer), "%.2f", usage);
    return buffer;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, OLED_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, OLED_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (ssd1306_init() != 0) {
        fprintf(stderr, "SSD1306 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (ssd1306_clear() != 0) {
        fprintf(stderr, "SSD1306 clear failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    while (running) {
        const char *temp = read_cpu_temp();
        const char *usage = read_cpu_usage();
        if (ssd1306_set_cursor(0, 0) != 0) break;
        if (i2cWriteByte(i2c_handle, SSD1306_DATA) != 0) break;
        if (i2cWriteByte(i2c_handle, 0x00) != 0) break;
        if (ssd1306_draw_string(0, 0, "CPU Temp: ") != 0) break;
        if (ssd1306_draw_string(60, 0, temp) != 0) break;
        if (ssd1306_draw_string(0, 12, "CPU Usage: ") != 0) break;
        if (ssd1306_draw_string(60, 12, usage) != 0) break;
        time_sleep(1.0);
    }
    ssd1306_clear();
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

