#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define LCD_I2C_ADDR 0x27
#define I2C_BUS 1
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04

static volatile int running = 1;
static int i2c_handle = -1;
static double total_volume = 0.0;
static time_t start_time = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void lcd_pulse_enable(int handle, int data) {
    gpioWrite(handle, ENABLE, 1);
    gpioDelay(1);
    gpioWrite(handle, ENABLE, 0);
    gpioDelay(50);
}

static void lcd_send_nibble(int handle, int nibble, int mode) {
    int bits = (mode << 4) | (nibble & 0x0F);
    gpioWrite(handle, 4, (bits >> 4) & 1);
    gpioWrite(handle, 5, (bits >> 5) & 1);
    gpioWrite(handle, 6, (bits >> 6) & 1);
    gpioWrite(handle, 7, (bits >> 7) & 1);
    lcd_pulse_enable(handle, handle);
}

static void lcd_send_byte(int handle, int bits, int mode) {
    lcd_send_nibble(handle, bits >> 4, mode);
    lcd_send_nibble(handle, bits & 0x0F, mode);
}

static void lcd_command(int handle, int cmd) {
    lcd_send_byte(handle, cmd, LCD_CMD);
}

static void lcd_data(int handle, int data) {
    lcd_send_byte(handle, data, LCD_CHR);
}

static void lcd_string(int handle, const char *s) {
    while (*s) {
        lcd_data(handle, (unsigned char)*s++);
    }
}

static void lcd_clear(int handle) {
    lcd_command(handle, 0x01);
    gpioDelay(2000);
}

static void lcd_init(int handle) {
    gpioDelay(50000);
    lcd_send_nibble(handle, 0x03, LCD_CMD);
    gpioDelay(5000);
    lcd_send_nibble(handle, 0x03, LCD_CMD);
    gpioDelay(150);
    lcd_send_nibble(handle, 0x03, LCD_CMD);
    lcd_send_nibble(handle, 0x02, LCD_CMD);
    gpioDelay(150);

    lcd_command(handle, 0x28);
    lcd_command(handle, 0x0C);
    lcd_command(handle, 0x06);
    lcd_command(handle, 0x01);
    gpioDelay(2000);
}

static void update_lcd(int handle, double flow_rate, double volume) {
    char line1[LCD_WIDTH + 1];
    char line2[LCD_WIDTH + 1];

    snprintf(line1, sizeof(line1), "Flow: %.2f L/min", flow_rate);
    snprintf(line2, sizeof(line2), "Vol: %.2f L", volume);

    lcd_clear(handle);
    lcd_command(handle, LCD_LINE_1);
    lcd_string(handle, line1);
    lcd_command(handle, LCD_LINE_2);
    lcd_string(handle, line2);
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    static uint32_t last_tick = 0;
    uint32_t diff;

    if (last_tick == 0) {
        last_tick = tick;
        return;
    }

    diff = tick - last_tick;
    last_tick = tick;

    if (diff > 0) {
        double elapsed = (double)diff / 1000000.0;
        double flow_rate = (PULSES_PER_LITER / elapsed) / 60.0;
        total_volume += (PULSES_PER_LITER * elapsed) / 60.0;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function on GPIO%d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X on bus %d\n", LCD_I2C_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    lcd_init(i2c_handle);

    start_time = time(NULL);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        time_t current_time = time(NULL);
        double elapsed = difftime(current_time, start_time);
        double flow_rate = (PULSES_PER_LITER * elapsed) / 60.0;

        printf("Flow Rate: %.2f L/min, Total Volume: %.2f L\n", flow_rate, total_volume);

        if (i2c_handle >= 0) {
            update_lcd(i2c_handle, flow_rate, total_volume);
        }

        sleep(1);
    }

    printf("\nShutting down...\n");

    if (i2c_handle >= 0) {
        lcd_clear(i2c_handle);
        i2cClose(i2c_handle);
    }

    gpioTerminate();
    return 0;
}

