#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define PULSES_PER_LITER 7.5
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04
#define E_PULSE_US 500
#define E_DELAY_US 500
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static volatile int pulse_count = 0;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)tick; (void)userdata;
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

static int lcd_byte(int bits, int mode) {
    int bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;

    gpioWrite(i2c_handle, bits_high | ENABLE);
    gpioDelay(E_PULSE_US);
    gpioWrite(i2c_handle, 0);
    gpioDelay(E_DELAY_US);

    gpioWrite(i2c_handle, bits_low | ENABLE);
    gpioDelay(E_PULSE_US);
    gpioWrite(i2c_handle, 0);
    gpioDelay(E_DELAY_US);
    return 0;
}

static void lcd_string(const char *s) {
    while (*s) {
        lcd_byte((unsigned char)*s++, LCD_CHR);
    }
}

static void lcd_clear(void) {
    lcd_byte(0x01, LCD_CMD);
    gpioDelay(2000);
}

static void lcd_init(void) {
    gpioDelay(50000);
    lcd_byte(0x33, LCD_CMD);
    lcd_byte(0x32, LCD_CMD);
    lcd_byte(0x28, LCD_CMD);
    lcd_byte(0x0C, LCD_CMD);
    lcd_byte(0x06, LCD_CMD);
    lcd_byte(0x01, LCD_CMD);
    gpioDelay(2000);
}

static void display_flow_rate(float flow_rate) {
    char line1[LCD_WIDTH + 1];
    char line2[LCD_WIDTH + 1];

    snprintf(line1, sizeof(line1), "Flow Rate:");
    snprintf(line2, sizeof(line2), "%.2f L/min", flow_rate);

    lcd_clear();
    lcd_string(line1);
    lcd_string(line2);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        lcd_clear();
        lcd_string("Shutting down...");
        gpioDelay(1000000);
        lcd_clear();
        lcd_string("Goodbye!");
        gpioDelay(1000000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function on GPIO%d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    lcd_init();

    printf("Water Flow Monitoring System\n");
    printf("GPIO%d, I2C 0x%02X, %.1f pulses/L\n", FLOW_SENSOR_GPIO, I2C_ADDR, PULSES_PER_LITER);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        pulse_count = 0;
        gpioDelay(POLL_INTERVAL_US);

        float flow_rate = (float)pulse_count / PULSES_PER_LITER * 60.0f;

        if (flow_rate < 0.0f) {
            flow_rate = 0.0f;
        }

        display_flow_rate(flow_rate);

        if (flow_rate == 0.0f) {
            lcd_string("Sensor absent");
            gpioDelay(1000000);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

