#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define SCAN_DELAY_US 800

static const unsigned int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const unsigned int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *row_lines[NUM_ROWS];
static struct gpiod_line *col_lines[NUM_COLS];
static volatile sig_atomic_t keep_running = 1;

static void cleanup(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_set_value(row_lines[i], 0);
            gpiod_line_release(row_lines[i]);
            row_lines[i] = NULL;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_set_value(col_lines[i], 1);
            gpiod_line_release(col_lines[i]);
            col_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row line %u\n", row_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(row_lines[i], "wave_matrix", 0) < 0) {
            perror("gpiod_line_request_output (row)");
            return -1;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get col line %u\n", col_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(col_lines[i], "wave_matrix", 1) < 0) {
            perror("gpiod_line_request_output (col)");
            return -1;
        }
    }
    return 0;
}

static void display_row(int row, int *pattern) {
    for (int c = 0; c < NUM_COLS; c++) {
        if (pattern[c]) {
            gpiod_line_set_value(row_lines[row], 1);
            gpiod_line_set_value(col_lines[c], 0);
        } else {
            gpiod_line_set_value(row_lines[row], 0);
            gpiod_line_set_value(col_lines[c], 1);
        }
    }
}

static void clear_matrix(void) {
    for (int r = 0; r < NUM_ROWS; r++) {
        gpiod_line_set_value(row_lines[r], 0);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    int left_to_right[NUM_COLS] = {1, 0, 0, 0, 0, 0, 0, 0};
    int right_to_left[NUM_COLS] = {0, 0, 0, 0, 0, 0, 0, 1};

    while (keep_running) {
        for (int r = 0; r < NUM_ROWS && keep_running; r++) {
            display_row(r, left_to_right);
            usleep(SCAN_DELAY_US);
            display_row(r, right_to_left);
            usleep(SCAN_DELAY_US);
        }
