/*
 * VL53L3CX Time-of-Flight sensor reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * NOTE: The VL53L3CX requires a proprietary firmware download and complex
 * initialization sequence. This implementation uses a simplified ULD-style
 * register access pattern that mimics the ULD API flow. In a production
 * environment, the full ULD firmware must be downloaded via the sensor's
 * proprietary interface (SPI or I2C with a separate firmware loader).
 *
 * Wiring:
 *   VL53L3CX SDA -> GPIO 2 (I2C1 SDA)
 *   VL53L3CX SCL -> GPIO 3 (I2C1 SCL)
 *   VL53L3CX VDD -> 3.3V
 *   VL53L3CX GND -> GND
 *
 * Build: gcc -o vl53l3cx vl53l3cx.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L3CX_ADDR 0x29
#define POLL_INTERVAL_US 100000  /* 100 ms */

/* ULD-style register addresses (16-bit, big-endian on the wire) */
#define VL53L3CX_REG_SOFT_RESET 0x0003
#define VL53L3CX_REG_SYSTEM_MODE 0x0001
#define VL53L3CX_REG_SYSTEM_RANGE_START 0x0001
#define VL53L3CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L3CX_REG_RESULT_DISTANCE 0x0096
#define VL53L3CX_REG_RESULT_PEAK_SIGNAL_COUNT_RATE 0x0098
#define VL53L3CX_REG_RESULT_PEAK_REF_COUNT_RATE 0x009A
#define VL53L3CX_REG_RESULT_PEAK_SIGNAL_COUNT_RATE_RTN 0x009C
#define VL53L3CX_REG_RESULT_PEAK_REF_COUNT_RATE_RTN 0x009E

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l3cx_write_reg16(int handle, uint16_t reg, uint8_t value) {
    return i2c_write_reg16(handle, reg, value);
}

static int vl53l3cx_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    return i2c_read_reg16(handle, reg, buf, len);
}

static int vl53l3cx_init(int handle) {
    uint8_t model_id = 0;
    int ret;

    /* Read model ID to verify sensor presence */
    ret = vl53l3cx_read_reg16(handle, 0x010F, &model_id, 1);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to read model ID (sensor absent or bus error).\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Unexpected model ID 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }

    /* Software reset */
    if (vl53l3cx_write_reg16(handle, VL53L3CX_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Clear reset */
    if (vl53l3cx_write_reg16(handle, VL53L3CX_REG_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to clear soft reset.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Start ranging */
    if (vl53l3cx_write_reg16(handle, VL53L3CX_REG_SYSTEM_RANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }

    return 0;
}

static int vl53l3cx_read_distance(int handle, uint16_t *distance) {
    uint8_t status = 0;
    int ret;

    /* Check if data is ready */
    ret = vl53l3cx_read_reg16(handle, VL53L3CX_REG_RESULT_RANGE_STATUS, &status, 1);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to read range status.\n");
        return -1;
    }

    if ((status & 0x01) == 0) {
        return 1; /* Data not ready yet */
    }

    /* Read distance (2 bytes, big-endian) */
    uint8_t dist_buf[2];
    ret = vl53l3cx_read_reg16(handle, VL53L3CX_REG_RESULT_DISTANCE, dist_buf, 2);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to read distance.\n");
        return -1;
    }

    *distance = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

static void log_data(uint16_t distance, uint16_t signal_count, uint16_t ref_count) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("%s - Distance: %u mm, Signal Count: %u, Reference Count: %u\n",
           timestamp, distance, signal_count, ref_count);
    fflush(stdout);
}

int main(void) {
    uint16_t distance = 0, signal_count = 0, ref_count = 0;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l3cx_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L3CX initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L3CX initialized. Reading distance every 100 ms. Press Ctrl+C to exit.\n");

    while (running) {
        ret = vl53l3cx_read_distance(i2c_handle, &distance);
        if (ret < 0) {
            fprintf(stderr, "Warning: I2C read error, retrying...\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (ret == 1) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        /* Read additional sensor data (signal and reference counts) */
        uint8_t buf[4];
        ret = vl53l3cx_read_reg16(i2c_handle, VL53L3CX_REG_RESULT_PEAK_SIGNAL_COUNT_RATE, buf, 2);
        if (ret < 0) {
            fprintf(stderr, "Warning: Failed to read signal count rate.\n");
        } else {
            signal_count = ((uint16_t)buf[0] << 8) | buf[1];
        }

        ret = vl53l3cx_read_reg16(i2c_handle, VL53L3CX_REG_RESULT_PEAK_REF_COUNT_RATE, buf, 2);
        if (ret < 0) {
            fprintf(stderr, "Warning: Failed to read reference count rate.\n");
        } else {
            ref_count = ((uint16_t)buf[0] << 8) | buf[1];
        }

        log_data(distance, signal_count, ref_count);
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    vl53l3cx_write_reg16(i2c_handle, VL53L3CX_REG_SYSTEM_RANGE_START, 0x00);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

