#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR        0x60
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY  0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_IRQ_ENABLE 0x0F
#define SI1145_REG_IRQ_MODE1  0x10
#define SI1145_REG_IRQ_MODE2  0x11
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_ALS_IR_DATA0  0x24
#define SI1145_REG_ALS_IR_DATA1  0x25
#define SI1145_REG_PS1_DATA0     0x26
#define SI1145_REG_PS1_DATA1     0x27
#define SI1145_REG_COMMAND       0x18
#define SI1145_REG_RESPONSE      0x20
#define SI1145_CMD_RESET         0x01
#define SI1145_CMD_ALS_FORCE     0x06
#define SI1145_CMD_PS_FORCE      0x05
#define SI1145_CMD_ALS_PS_FORCE  0x07
#define SI1145_CMD_PSALS_AUTO    0x0F
#define SI1145_PART_ID           0x45
#define SAMPLE_INTERVAL_US       500000
#define LOG_FILE_NAME            "biometric_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n",
                reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

static int si1145_init(int handle)
{
    uint8_t part_id = 0;
    if (i2c_read_byte(handle, SI1145_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor absent or bus error\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1145_PART_ID);
        return -1;
    }
    printf("Si1145 detected (PART_ID=0x%02X)\n", part_id);

    if (i2c_write_byte(handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) != 0)
        return -1;
    gpioDelay(10000);

    if (i2c_write_byte(handle, SI1145_REG_HW_KEY, 0x17) != 0)
        return -1;

    if (i2c_write_byte(handle, SI1145_REG_MEAS_RATE0, 0x00) != 0)
        return -1;
    if (i2c_write_byte(handle, SI1145_REG_MEAS_RATE1, 0x00) != 0)
        return -1;

    if (i2c_write_byte(handle, SI1145_REG_IRQ_ENABLE, 0x00) != 0)
        return -1;
    if (i2c_write_byte(handle, SI1145_REG_IRQ_MODE1, 0x00) != 0)
        return -1;
    if (i2c_write_byte(handle, SI1145_REG_IRQ_MODE2, 0x00) != 0)
        return -1;

    if (i2c_write_byte(handle, SI1145_REG_COMMAND, SI1145_CMD_PSALS_AUTO) != 0)
        return -1;

    return 0;
}

static int read_sensor_data(int handle, uint16_t *proximity, uint16_t *ambient)
{
    uint8_t vis_lo = 0, vis_hi = 0, ir_lo = 0, ir_hi = 0;
    uint8_t ps1_lo = 0, ps1_hi = 0;

    if (i2c_read_byte(handle, SI1145_REG_ALS_VIS_DATA0, &vis_lo) != 0) return -1;
    if (i2c_read_byte(handle, SI1145_REG_ALS_VIS_DATA1, &vis_hi) != 0) return -1;
    if (i2c_read_byte(handle, SI1145_REG_ALS_IR_DATA0,  &ir_lo)  != 0) return -1;
    if (i2c_read_byte(handle, SI1145_REG_ALS_IR_DATA1,  &ir_hi)  != 0) return -1;
    if (i2c_read_byte(handle, SI1145_REG_PS1_DATA0,     &ps1_lo) != 0) return -1;
    if (i2c_read_byte(handle, SI1145_REG_PS1_DATA1,     &ps1_hi) != 0) return -1;

    *ambient = ((uint16_t)vis_hi << 8) | vis_lo;
    *proximity = ((uint16_t)ir_hi << 8) | ir_lo;
    return 0;
}

static void log_data(FILE *fp, uint16_t proximity, uint16_t ambient)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Proximity: %u, Ambient: %u\n", ts, proximity, ambient);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si1145_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("fopen");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE_NAME);

    while (g_running) {
        uint16_t proximity = 0, ambient = 0;

        if (read_sensor_data(g_i2c_handle, &proximity, &ambient) == 0) {
            log_data(g_log_file, proximity, ambient);
        } else {
            fprintf(stderr, "Read error - continuing\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

