    if (i2c_read_byte(handle, SI1145_REG_ALS_IR_DATA0,  &ir_lo)  != 0) return -1;
    if (i2c_read_byte(handle, SI1145_REG_ALS_IR_DATA1,  &ir_hi)  != 0) return -1;
    if (i2c_read_byte(handle, SI1145_REG_PS1_DATA0,     &ps1_lo) != 0) return -1;
    if (i2c_read_byte(handle, SI1145_REG_PS1_DATA1,     &ps1_hi) != 0) return -1;

    *ambient = ((uint16_t)vis_hi << 8) | vis_lo;
    *proximity = ((uint16_t)ir_hi << 8) | ir_lo;
    return 0;
}

static void log_data(FILE *fp, uint16_t proximity, uint16_t ambient)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Proximity: %u, Ambient: %u\n", ts, proximity, ambient);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si1145_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("fopen");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE_NAME);

    while (g_running) {
        uint16_t proximity = 0, ambient = 0;

        if (read_sensor_data(g_i2c_handle, &proximity, &ambient) == 0) {
            log_data(g_log_file, proximity, ambient);
        } else {
            fprintf(stderr, "Read error - continuing\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

