#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR 0x60
#define I2C_BUS 1

#define REG_PART_ID 0x00
#define REG_HW_KEY 0x07
#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09
#define REG_PS_LED21_SELECT 0x0F
#define REG_PS1_DATA0 0x18
#define REG_ALS_VIS_DATA0 0x22
#define REG_COMMAND 0x30
#define REG_CH_LIST 0x4F

#define CMD_ALS_FORCE 0x06
#define CMD_PS_FORCE 0x07

#define EXPECTED_PART_ID 0x45

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int si1145_write(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (pigpio rc=%d)\n", value, reg, rc);
    }
    return rc;
}

static int si1145_read(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int si1145_read16(uint8_t reg_low, uint16_t *value) {
    uint8_t lo, hi;
    if (si1145_read(reg_low, &lo) < 0) return -1;
    if (si1145_read(reg_low + 1, &hi) < 0) return -1;
    *value = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int si1145_init(void) {
    uint8_t part_id;
    if (si1145_read(REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor may be absent or bus error\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1145 detected (PART_ID=0x%02X)\n", part_id);

    if (si1145_write(REG_HW_KEY, 0x17) < 0) return -1;
    if (si1145_write(REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (si1145_write(REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (si1145_write(REG_PS_LED21_SELECT, 0x0F) < 0) return -1;
    if (si1145_write(REG_CH_LIST, 0x03) < 0) return -1;
    return 0;
}

static int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light) {
    if (si1145_write(REG_COMMAND, CMD_ALS_FORCE) < 0) return -1;
    if (si1145_write(REG_COMMAND, CMD_PS_FORCE) < 0) return -1;
    gpioDelay(10000);

    if (si1145_read16(REG_PS1_DATA0, proximity) < 0) return -1;
    if (si1145_read16(REG_ALS_VIS_DATA0, ambient_light) < 0) return -1;
    return 0;
}

static void log_data(uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, proximity, ambient_light);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X (pigpio rc=%d)\n", I2C_BUS, SI1145_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si1145_init() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Logging Si1145 data to biometric_data.log. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t proximity, ambient_light;
        if (read_sensor_data(&proximity, &ambient_light) == 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

