#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define LOG_FILE    "distance_log.txt"
#define TIMEOUT_US  30000
#define POLL_INTERVAL_S 60
#define MIN_DISTANCE_CM 15.0
#define MIN_VALID_CM    2.0
#define MAX_VALID_CM    400.0
#define SPEED_OF_SOUND_CM_PER_S 34300.0

static volatile sig_atomic_t program_running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *msg) {
    if (!log_fp) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_fp, "%s %s\n", ts, msg);
    fflush(log_fp);
}

static int trigger_sensor(struct gpiod_line *trig) {
    if (gpiod_line_set_value(trig, 0) < 0) {
        log_event("Error: failed to set trigger low");
        return -1;
    }
    usleep(2);
    if (gpiod_line_set_value(trig, 1) < 0) {
        log_event("Error: failed to set trigger high");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        log_event("Error: failed to reset trigger low");
        return -1;
    }
    return 0;
}

static double measure_distance(struct gpiod_line *echo) {
    struct timespec start, now;
    long long elapsed_ns = 0;
    int val;

    if (trigger_sensor(echo) < 0) return -1.0;

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            log_event("Error: failed to read echo pin");
            return -1.0;
        }
        if (val == 1) break;
        clock_gettime(CLOCK_MONOTONIC, &now);
        elapsed_ns = (now.tv_sec - start.tv_sec) * 1000000000LL +
                     (now.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_US * 1000LL) {
            log_event("Timeout: echo never went high");
            return -1.0;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            log_event("Error: failed to read echo pin");
            return -1.0;
        }
        if (val == 0) break;
        clock_gettime(CLOCK_MONOTONIC, &now);
        elapsed_ns = (now.tv_sec - start.tv_sec) * 1000000000LL +
                     (now.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_US * 1000LL) {
            log_event("Timeout: echo stuck high");
            return -1.0;
        }
    }

    double pulse_sec = (double)elapsed_ns / 1000000000.0;
    double distance = (pulse_sec * SPEED_OF_SOUND_CM_PER_S) / 2.0;
    return distance;
}

static void check_distance(double distance) {
    if (distance < 0.0) {
        log_event("Error: invalid distance reading");
        return;
    }
    if (distance < MIN_DISTANCE_CM) {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Time to water the plant! Distance: %.2f cm", distance);
        log_event(msg);
    } else {
        char msg[128];
        snprintf(msg, sizeof(msg), "Distance: %.2f cm", distance);
        log_event(msg);
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output trig");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input echo");
        goto cleanup;
    }

    log_event("Program started");

    while (program_running) {
        double dist = measure_distance(echo);
        check_distance(dist);
        sleep(POLL_INTERVAL_S);
    }

    log_event("Program exiting");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);
    return ret;
}

