#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define APDS9960_ADDR 0x39
#define APDS9960_ID_REG 0x92
#define APDS9960_ID_VAL 0xAB
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_CDATAL 0x96
#define APDS9960_PDATA 0x9C

#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"
#define I2C_BUS 1

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int apds9960_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int apds9960_read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int apds9960_read_word(uint8_t reg, uint16_t *value) {
    int rc = i2cReadWordData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading word reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint16_t)rc;
    return 0;
}

static int apds9960_init(void) {
    uint8_t id;
    if (apds9960_read_reg(APDS9960_ID_REG, &id) < 0) {
        return -1;
    }
    if (id != APDS9960_ID_VAL) {
        fprintf(stderr, "Invalid sensor ID: 0x%02X (expected 0x%02X)\n", id, APDS9960_ID_VAL);
        return -1;
    }

    if (apds9960_write_reg(APDS9960_ENABLE, 0x03) < 0) return -1;
    if (apds9960_write_reg(APDS9960_ATIME, 0xDB) < 0) return -1;
    if (apds9960_write_reg(APDS9960_WTIME, 0xF6) < 0) return -1;
    if (apds9960_write_reg(APDS9960_PPULSE, 0x87) < 0) return -1;
    if (apds9960_write_reg(APDS9960_CONTROL, 0x03) < 0) return -1;
    if (apds9960_write_reg(APDS9960_CONFIG2, 0x01) < 0) return -1;

    return 0;
}

static int read_sensor_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity) {
    if (apds9960_read_word(APDS9960_CDATAL, red) < 0) return -1;
    if (apds9960_read_word(APDS9960_CDATAL + 2, green) < 0) return -1;
    if (apds9960_read_word(APDS9960_CDATAL + 4, blue) < 0) return -1;
    if (apds9960_read_reg(APDS9960_PDATA, proximity) < 0) return -1;
    return 0;
}

static void log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            red, green, blue, proximity);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, APDS9960_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (apds9960_init() < 0) {
        fprintf(stderr, "APDS9960 initialisation failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t red, green, blue;
    uint8_t proximity;

    while (!terminate) {
        if (read_sensor_data(&red, &green, &blue, &proximity) == 0) {
            if (proximity > PROXIMITY_THRESHOLD) {
                log_data(red, green, blue, proximity);
            }
        } else {
            fprintf(stderr, "Sensor read error, re-initialising...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                gpioDelay(1000000);
                continue;
            }
            if (apds9960_init() < 0) {
                fprintf(stderr, "APDS9960 re-initialisation failed\n");
                gpioDelay(1000000);
                continue;
            }
        }
        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

