/*
 * Si1182-A-GMR Heart-Rate Monitor for Raspberry Pi 5
 *
 * Uses the Linux i2c-dev kernel interface (no wiringPi).
 *
 * Wiring:
 *   Si1182 SDA  -> GPIO2 (pin 3, I2C1 SDA)
 *   Si1182 SCL  -> GPIO3 (pin 5, I2C1 SCL)
 *   Si1182 VDD  -> 3.3 V
 *   Si1182 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o heartrate heartrate.c
 */

#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/ioctl.h>

/* ---- Si1182-A-GMR register map (per datasheet) ---- */
#define SI1182_I2C_ADDR      0x5A
#define SI1182_REG_PART_ID   0x00
#define SI1182_REG_MEAS_RATE0 0x08
#define SI1182_REG_COMMAND   0x47
#define SI1182_REG_PS_DATA0  0x24
#define SI1182_REG_PS_DATA1  0x25

#define SI1182_PART_ID_VAL   0x82   /* expected part ID for Si1182-A-GMR */

/* ---- Command opcodes ---- */
#define SI1182_CMD_RESET     0x01
#define SI1182_CMD_START     0x02

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register using i2c_smbus_write_byte_data().     */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int si1182_write_reg(int fd, uint8_t reg, uint8_t value)
{
    int rc = i2c_smbus_write_byte_data(fd, reg, value);
    if (rc < 0) {
        fprintf(stderr, "i2c_smbus_write_byte_data(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a register using i2c_smbus_read_byte_data().     */
/* Returns 0 on success and stores the value in *out, -1 on error.     */
/* ------------------------------------------------------------------ */
static int si1182_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    int rc = i2c_smbus_read_byte_data(fd, reg);
    if (rc < 0) {
        fprintf(stderr, "i2c_smbus_read_byte_data(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair.                          */
/* ------------------------------------------------------------------ */
static int si1182_read_reg16(int fd, uint8_t reg_lo, uint16_t *out)
{
    uint8_t lo, hi;
    if (si1182_read_reg(fd, reg_lo, &lo) < 0)
        return -1;
    if (si1182_read_reg(fd, reg_lo + 1, &hi) < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the Si1182: verify part ID, configure measurement rate,  */
/* and issue a reset/start command.                                    */
/* ------------------------------------------------------------------ */
static int si1182_init(int fd)
{
    uint8_t part_id = 0;

    /* --- Verify part ID --- */
    if (si1182_read_reg(fd, SI1182_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID register — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != SI1182_PART_ID_VAL) {
        fprintf(stderr,
                "Unexpected PART_ID 0x%02X (expected 0x%02X). "
                "Wrong sensor or wrong address?\n",
                part_id, SI1182_PART_ID_VAL);
        return -1;
    }
    printf("Si1182 detected (PART_ID = 0x%02X).\n", part_id);

    /* --- Configure measurement rate (0x08) --- */
    /* MEAS_RATE0 = 0x00 → 100 ms between measurements. */
    if (si1182_write_reg(fd, SI1182_REG_MEAS_RATE0, 0x00) < 0)
        return -1;

    /* --- Issue reset/start command --- */
    if (si1182_write_reg(fd, SI1182_REG_COMMAND, SI1182_CMD_RESET) < 0)
        return -1;
    usleep(10000);                       /* allow reset to complete */
    if (si1182_write_reg(fd, SI1182_REG_COMMAND, SI1182_CMD_START) < 0)
        return -1;

    printf("Si1182 initialised: measurement rate 100 ms, continuous mode.\n");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 16-bit proximity data and compute a placeholder BPM.           */
/* ------------------------------------------------------------------ */
static int si1182_read_proximity(int fd, uint16_t *prox)
{
    return si1182_read_reg16(fd, SI1182_REG_PS_DATA0, prox);
}

/* ------------------------------------------------------------------ */
/* Log a sample to CSV.                                                */
/* ------------------------------------------------------------------ */
static void log_sample(FILE *csv, uint16_t prox, float bpm)
{
    char ts[32];
    time_t now = time(NULL);
    struct tm tmv;

    if (localtime_r(&now, &tmv) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);

    if (fprintf(csv, "%s,%u,%.2f\n", ts, prox, bpm) < 0)
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
    if (fflush(csv) == EOF)
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
int main(void)
{
    const char *i2c_dev = "/dev/i2c-1";
    const char *csv_fn  = "heartrate.csv";
    int rc = EXIT_FAILURE;

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(i2c_dev, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", i2c_dev, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Acquire slave address ---- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1182_I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    /* ---- Initialise sensor ---- */
    if (si1182_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1182 initialisation failed.\n");
        goto cleanup;
    }

    /* ---- Open CSV file ---- */
    g_csv = fopen(csv_fn, "a");
    if (!g_csv) {
        fprintf(stderr, "fopen(%s) failed: %s\n", csv_fn, strerror(errno));
        goto cleanup;
    }

    /* ---- Write CSV header if file is empty ---- */
    if (ftell(g_csv) == 0) {
        fprintf(g_csv, "timestamp,proximity_bps,bpm\n");
        fflush(g_csv);
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Logging heart-rate data to %s. Press Ctrl-C to stop.\n", csv_fn);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t prox = 0;
        if (si1182_read_proximity(g_i2c_fd, &prox) < 0) {
            fprintf(stderr, "Warning: I2C read failed — skipping sample.\n");
            usleep(100000);
            continue;
        }

        /* Placeholder BPM: proximity signal → BPM */
        float bpm = (float)prox / 100.0f;

        log_sample(g_csv, prox, bpm);
        usleep(100000);  /* 100 ms */
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (g_csv) {
        fflush(g_csv);
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return rc;
}

