#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L0X_ADDR   0x29
#define GPIO_TRIGGER   17

#define REG_SYSRANGE_START      0x00
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS    0x14
#define REG_SYSTEM_INTERRUPT_CLEAR 0x0B

#define LOG_FILE "distance_log.txt"
#define POLL_TIMEOUT_MS 100

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): pigpio error %d\n",
                reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): pigpio error %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, len %u): pigpio error %d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

static int vl53l0x_init(int handle)
{
    uint8_t id = 0;
    if (i2c_read_byte(handle, 0x010F, &id) < 0) {
        fprintf(stderr, "Cannot read VL53L0X ID register\n");
        return -1;
    }
    if (id != 0xEACC) {
        fprintf(stderr, "Unexpected VL53L0X ID 0x%02X (expected 0xEACC)\n", id);
        return -1;
    }
    if (i2c_write_byte(handle, REG_SYSRANGE_START, 0x00) < 0) return -1;
    return 0;
}

static int vl53l0x_read_distance(int handle, uint16_t *distance_mm)
{
    if (i2c_write_byte(handle, REG_SYSRANGE_START, 0x01) < 0) return -1;

    uint8_t status = 0;
    int waited = 0;
    while (waited < POLL_TIMEOUT_MS) {
        if (i2c_read_byte(handle, REG_RESULT_INTERRUPT_STATUS, &status) < 0)
            return -1;
        if (status & 0x01) break;
        gpioDelay(1000);
        waited++;
    }
    if (waited >= POLL_TIMEOUT_MS) {
        fprintf(stderr, "VL53L0X measurement timeout\n");
        return -1;
    }

    uint8_t data[14];
    if (i2c_read_block(handle, REG_RESULT_RANGE_STATUS, data, sizeof(data)) < 0)
        return -1;

    uint16_t dist = ((uint16_t)data[10] << 8) | data[11];
    if (i2c_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    *distance_mm = dist;
    return 0;
}

static void log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance_mm);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): pigpio error %d\n",
                I2C_BUS, VL53L0X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l0x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L0X initialization failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_TRIGGER, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", GPIO_TRIGGER);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d\n", GPIO_TRIGGER);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L0X ranging started on GPIO %d. Press Ctrl+C to stop.\n", GPIO_TRIGGER);

    while (g_running) {
        if (gpioRead(GPIO_TRIGGER) == 0) {
            uint16_t dist = 0;
            if (vl53l0x_read_distance(g_i2c_handle, &dist) == 0) {
                log_distance(g_log_file, dist);
                printf("Distance: %u mm\n", dist);
            } else {
                fprintf(stderr, "Measurement error\n");
            }
            gpioDelay(50000);
        }
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

