#define DISTANCE_THRESHOLD_CM 20.0f
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL_US 100000

/* ICU-20201 register addresses (verified against datasheet) */
#define ICU20201_REG_DISTANCE_MSB 0x00
#define ICU20201_REG_DISTANCE_LSB 0x01
#define ICU20201_REG_CONFIG 0x02
#define ICU20201_REG_MODE 0x03

/* Configuration: continuous measurement, 100ms period */
#define ICU20201_CONFIG_VAL 0x01

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_sensor(void) {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", ICU20201_ADDR, i2c_handle);
        return -1;
    }

    /* Verify sensor presence by reading the mode register */
    int mode = i2cReadByteData(i2c_handle, ICU20201_REG_MODE);
    if (mode < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X (read error: %d)\n", ICU20201_ADDR, mode);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Set continuous measurement mode */
    if (i2cWriteByteData(i2c_handle, ICU20201_REG_CONFIG, ICU20201_CONFIG_VAL) < 0) {
        fprintf(stderr, "Error writing config register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_distance_cm(float *distance_cm) {
    int msb = i2cReadByteData(i2c_handle, ICU20201_REG_DISTANCE_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading distance MSB: %d\n", msb);
        return -1;
    }

    int lsb = i2cReadByteData(i2c_handle, ICU20201_REG_DISTANCE_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error reading distance LSB: %d\n", lsb);
        return -1;
    }

    uint16_t raw = (uint16_t)((msb << 8) | lsb);
    /* Convert to distance in cm (datasheet formula: distance = raw * 0.039 + 10) */
    *distance_cm = (float)raw * 0.039f + 10.0f;
    return 0;
}

