        fprintf(stderr, "Error setting LED GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    if (init_sensor() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering signal handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICU-20201 distance monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance_cm;
        if (read_distance_cm(&distance_cm) == 0) {
            log_distance(distance_cm);
            control_led(distance_cm);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

