#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define REG_ALS 0x16
#define REG_PROX 0x18
#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000
#define SAMPLE_INTERVAL_US 500000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register16(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(handle, reg, buf, 2);
        if (result == 2) {
            *value = (uint16_t)((buf[1] << 8) | buf[0]);
            return 0;
        }
        fprintf(stderr, "I2C read error (reg 0x%02X): %d, retry %d/%d\n",
                reg, result, retries + 1, RETRY_COUNT);
        gpioDelay(RETRY_DELAY_US);
        retries++;
    }
    return -1;
}

static int log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s, Proximity: %u, Ambient Light: %u\n",
                timestamp, proximity, ambient_light) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    uint16_t proximity, ambient_light;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1182-GMR logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        if (read_register16(i2c_handle, REG_PROX, &proximity) != 0) {
            fprintf(stderr, "Failed to read proximity data after %d retries\n", RETRY_COUNT);
        } else if (read_register16(i2c_handle, REG_ALS, &ambient_light) != 0) {
            fprintf(stderr, "Failed to read ambient light data after %d retries\n", RETRY_COUNT);
        } else {
            if (log_data(log_file, proximity, ambient_light) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

