#define WHO_AM_I_VAL 0x20
#define DISTANCE_REG 0x04
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100
#define SAMPLE_INTERVAL_US 50000

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_distance(int handle, int *distance) {
    char reg = DISTANCE_REG;
    char buf[2];
    int rc;

    rc = i2cWriteDevice(handle, &reg, 1);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (reg select): %d\n", rc);
        return -1;
    }

    gpioDelay(1000);

    rc = i2cReadDevice(handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C read error: %d\n", rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "I2C short read: %d bytes\n", rc);
        return -1;
    }

    *distance = ((uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static void log_data(int distance, int threshold) {
    FILE *fp = fopen("tof_log.txt", "a");
    if (!fp) {
        perror("fopen tof_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %d mm, Threshold: %d mm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance, threshold);
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;

    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold: %s\n", argv[1]);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", ICU20201_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    int who = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I: %d\n", who);
        cleanup();
        return 1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        cleanup();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ICU-20201 distance monitoring started. Threshold: %d mm\n", threshold);

    while (running) {
        int distance;
        if (read_distance(i2c_handle, &distance) == 0) {
            log_data(distance, threshold);
            gpioWrite(LED_GPIO, (distance < threshold) ? 1 : 0);
        } else {
            gpioWrite(LED_GPIO, 0);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

