#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define B5L_ADDR       0x50
#define CMD_FRAME_LEN  4
#define RESP_FRAME_LEN 15
#define INTRUSION_DIST 1000
#define SAMPLES        10
#define CYCLE_DELAY_MS 100
#define MEAS_DELAY_MS  10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write(int fd, const uint8_t *buf, size_t len) {
    ssize_t n = write(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C write short: %zd of %zu\n", n, len);
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: %zd of %zu\n", n, len);
        return -1;
    }
    return 0;
}

static int read_distance(int fd, int *distance_mm) {
    uint8_t cmd[CMD_FRAME_LEN] = {0x50, 0x0A, 0x00, 0x01};
    uint8_t resp[RESP_FRAME_LEN];

    if (i2c_write(fd, cmd, CMD_FRAME_LEN) < 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read(fd, resp, RESP_FRAME_LEN) < 0)
        return -1;

    if (resp[0] != 0x50) {
        fprintf(stderr, "Sensor response header mismatch: 0x%02X\n", resp[0]);
        return -1;
    }

    *distance_mm = (resp[10] << 8) | resp[11];
    return 0;
}

static void log_intrusion(FILE *log, int avg_dist) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log, "%s - Intrusion detected! Average distance: %d mm\n", ts, avg_dist);
    fflush(log);
    printf("%s - Intrusion detected! Average distance: %d mm\n", ts, avg_dist);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, B5L_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", B5L_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    FILE *log = fopen("intrusion_log.txt", "a");
    if (!log) {
        fprintf(stderr, "Failed to open intrusion_log.txt: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("Monitoring for intrusions (Ctrl+C to exit)...\n");

    while (g_running) {
        int distances[SAMPLES];
        int valid = 0;

        for (int i = 0; i < SAMPLES; i++) {
            if (!g_running)
                break;
            if (read_distance(g_i2c_fd, &distances[valid]) == 0) {
                valid++;
            } else {
                fprintf(stderr, "Read error on sample %d\n", i);
            }
            usleep(CYCLE_DELAY_MS * 1000);
        }

        if (valid == 0) {
            fprintf(stderr, "No valid samples this cycle\n");
            continue;
        }

        int sum = 0;
        for (int i = 0; i < valid; i++)
            sum += distances[i];

        int avg = sum / valid;

        if (avg < INTRUSION_DIST) {
            log_intrusion(log, avg);
        }

        usleep(CYCLE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (log) fclose(log);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

