#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x4C
#define DIST_REG       0x00
#define POLL_MS        500
#define POLL_NS        0

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    if (out == NULL) {
        return -1;
    }

    /* Write the register pointer */
    if (i2c_smbus_write_byte(fd, reg) < 0) {
        return -1;
    }

    /* Read two bytes (little-endian: low byte first, then high byte) */
    int lo = i2c_smbus_read_byte(fd);
    if (lo < 0) {
        return -1;
    }
    int hi = i2c_smbus_read_byte(fd);
    if (hi < 0) {
        return -1;
    }

    *out = (uint16_t)((hi << 8) | (lo & 0xFF));
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() < 0) {
        goto out;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        goto out;
    }

    if (ioctl(fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                MLX75030_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Probe: read the distance register to confirm the sensor is present */
    uint16_t dist = 0;
    if (i2c_read_reg16(fd, DIST_REG, &dist) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X: %s\n",
                MLX75030_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("MLX75030 detected at 0x%02X. Distance register reads 0x%04X.\n",
           MLX75030_ADDR, dist);

    struct timespec sleep_ts = {
        .tv_sec  = POLL_MS / 1000,
        .tv_nsec = (long)(POLL_MS % 1000) * 1000000L
    };

    while (g_running) {
        uint16_t raw = 0;
        if (i2c_read_reg16(fd, DIST_REG, &raw) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            /* Brief back-off before retrying */
            nanosleep(&sleep_ts, NULL);
            continue;
        }

        /* MLX75030: distance in mm = raw * 0.125 mm/count */
        float distance_mm = (float)raw * 0.125f;
        printf("Distance: %.2f mm\n", distance_mm);
        fflush(stdout);

        nanosleep(&sleep_ts, NULL);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
out:
    return rc;
}

