#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define OPT3101_ADDR 0x44
#define I2C_BUS 1

#define REG_STATUS 0x00
#define REG_DISTANCE 0x04
#define REG_AMBIENT 0x06
#define REG_CONFIG 0x08

#define STATUS_ERROR 0x01
#define STATUS_BUSY 0x02

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int opt3101_read_register(int handle, uint8_t reg, uint8_t *data, uint32_t len) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)data, len);
    if (result != (int)len) {
        fprintf(stderr, "Error reading register 0x%02X: expected %u bytes, got %d\n", reg, len, result);
        return -1;
    }
    return 0;
}

static int opt3101_write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int opt3101_init(int handle) {
    if (opt3101_write_register(handle, REG_CONFIG, 0x01) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int opt3101_read_data(int handle, uint16_t *distance, uint16_t *ambient) {
    uint8_t status;
    if (opt3101_read_register(handle, REG_STATUS, &status, 1) < 0) return -1;

    if (status & STATUS_ERROR) {
        fprintf(stderr, "Sensor error flag set\n");
        return -1;
    }

    if (status & STATUS_BUSY) {
        fprintf(stderr, "Sensor busy\n");
        return -1;
    }

    uint8_t dist_data[2];
    if (opt3101_read_register(handle, REG_DISTANCE, dist_data, 2) < 0) return -1;
    *distance = (uint16_t)((dist_data[1] << 8) | dist_data[0]);

    uint8_t amb_data[2];
    if (opt3101_read_register(handle, REG_AMBIENT, amb_data, 2) < 0) return -1;
    *ambient = (uint16_t)((amb_data[1] << 8) | amb_data[0]);

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (opt3101_init(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("OPT3101 Distance Sensor Reader\n");
    printf("Press Ctrl+C to exit\n\n");

    while (running) {
        uint16_t distance, ambient;
        if (opt3101_read_data(i2c_handle, &distance, &ambient) == 0) {
            printf("Distance: %u mm, Ambient: %u\n", distance, ambient);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioDelay(500000);
    }

    printf("\nExiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

