/*
 * HC-SR04 Ultrasonic Distance Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (modern API, not wiringPi)
 *
 * Wiring (BCM numbering):
 *   TRIGGER -> GPIO 17 (output)
 *   ECHO    -> GPIO 18 (input, 1 kOhm series resistor to GND)
 *
 * HC-SR04 operates at 5V; Pi GPIO is 3.3V tolerant.  The echo pin
 * must be clamped to 5V during the 10 us trigger pulse and during
 * the echo pulse itself (the HC-SR04 is not 3.3V tolerant).
 *
 * Build:  gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US  10          /* HC-SR04 requires >= 10 us */
#define ECHO_TIMEOUT_US   200000      /* 200 ms max echo wait        */
#define MAX_PULSE_US      38000       /* HC-SR04 max range ~4.5 m    */
#define SAMPLE_PERIOD_US  1000000     /* 1 second between readings   */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    }
}

/* ------------------------------------------------------------------ */
/* Read distance in cm.  Returns -1.0 on any error.                    */
/* ------------------------------------------------------------------ */
static float read_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* --- Issue 10 us trigger pulse --- */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        print_timestamp();
        fprintf(stderr, "Error: gpioWrite(trigger HIGH) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        print_timestamp();
        fprintf(stderr, "Error: gpioWrite(trigger LOW) failed\n");
        return -1.0f;
    }

    /* --- Wait for echo rising edge (timeout 200 ms) --- */
    start_tick = gpioTick();
    timeout_tick = start_tick + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            print_timestamp();
            fprintf(stderr, "Error: Echo rising-edge timeout (no object detected)\n");
            return -1.0f;
        }
    }

    /* --- Measure echo pulse width (timeout 200 ms) --- */
    start_tick = gpioTick();
    timeout_tick = start_tick + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        end_tick = gpioTick();
        if ((int32_t)(end_tick - timeout_tick) >= 0) {
            print_timestamp();
            fprintf(stderr, "Error: Echo falling-edge timeout (sensor stuck)\n");
            return -1.0f;
        }
    }

    uint32_t pulse_us = end_tick - start_tick;

    /* --- Sanity-check pulse duration --- */
    if (pulse_us == 0) {
        print_timestamp();
        fprintf(stderr, "Error: Zero pulse duration\n");
        return -1.0f;
    }
    if (pulse_us > MAX_PULSE_US) {
        print_timestamp();
        fprintf(stderr, "Warning: Pulse %u us exceeds max range (%u us) — object out of range\n",
                pulse_us, MAX_PULSE_US);
        return -1.0f;
    }

    /* distance = (pulse_us * 0.0343) / 2  (cm) */
    return (float)pulse_us * 0.0343f / 2.0f;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger init LOW) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        print_timestamp();
        fprintf(stderr, "Warning: Could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        print_timestamp();
        fprintf(stderr, "Warning: Could not install SIGTERM handler\n");
    }

    print_timestamp();
    printf("HC-SR04 distance reader started.  Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        float distance = read_distance();

        if (distance >= 0.0f) {
            print_timestamp();
            printf("Distance: %.2f cm\n", distance);
        }

        /* Sleep for the remainder of the 1-second period */
        gpioDelay(SAMPLE_PERIOD_US - TRIGGER_PULSE_US);
    }

    /* --- Graceful shutdown --- */
    print_timestamp();
    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

