#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define GPIO_LED 17
#define INTRUSION_THRESHOLD 1.0f
#define RANGE_RESOLUTION 0.0486f
#define NUM_RANGE_BINS 64
#define DATA_FRAME_SIZE (NUM_RANGE_BINS * 2)
#define MAGIC_WORD_SIZE 8
#define RAW_DATA_SIZE (DATA_FRAME_SIZE - MAGIC_WORD_SIZE)
#define LOG_FILE "intrusion_log.csv"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("open UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, B115200);
    cfsetispeed(&tty, B115200);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_lflag = 0;
    tty.c_oflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 10;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("read");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART read timeout\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int process_range_profile(const uint8_t *raw, float *distances) {
    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        uint16_t val = (uint16_t)((raw[i * 2] << 8) | raw[i * 2 + 1]);
        distances[i] = (float)i * RANGE_RESOLUTION;
    }
    return 0;
}

static int detect_intrusion(const float *distances) {
    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        if (distances[i] > 0.0f && distances[i] < INTRUSION_THRESHOLD) {
            return 1;
        }
    }
    return 0;
}

static void log_intrusion(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s,%.3f\n", ts, distance);
        fflush(log_file);
    }
    printf("Intrusion detected at %.3f meters\n", distance);
}

static void cleanup(void) {
    if (uart_fd >= 0) {
        close(uart_fd);
        uart_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_DEVICE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    uint8_t magic[MAGIC_WORD_SIZE];
    uint8_t raw[RAW_DATA_SIZE];
    float distances[NUM_RANGE_BINS];

    while (running) {
        if (read_exact(uart_fd, magic, MAGIC_WORD_SIZE) != 0) {
            if (!running) break;
            usleep(100000);
            continue;
        }

        if (memcmp(magic, "\x02\x01\x04\x03\x06\x05\x08\x07", MAGIC_WORD_SIZE) != 0) {
            fprintf(stderr, "Invalid magic word\n");
            continue;
        }

        if (read_exact(uart_fd, raw, RAW_DATA_SIZE) != 0) {
            if (!running) break;
            usleep(100000);
            continue;
        }

        process_range_profile(raw, distances);
        if (detect_intrusion(distances)) {
            log_intrusion(distances[0]);
            gpioWrite(GPIO_LED, 1);
            gpioDelay(2000000);
            gpioWrite(GPIO_LED, 0);
        }
    }

    cleanup();
    return 0;
}

