/*
 * Raspberry Pi 4 Model B - TDK Chirp ICU-20201 Ultrasonic ToF Sensor
 * Library: pigpio (I2C + GPIO)
 * Bus: I2C-1 (GPIO2=SDA, GPIO3=SCL), Address: 0x69
 * Distance alert: GPIO17 (BCM 17)
 *
 * Build: gcc -Wall -Wextra -O2 -o distance_monitor distance_monitor.c -lpigpio -lrt
 * Run:   sudo ./distance_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ICU20201_ADDR        0x69
#define DISTANCE_HIGH_REG    0x31
#define DISTANCE_LOW_REG     0x32
#define DISTANCE_THRESHOLD   10.0f   /* cm */
#define ALERT_GPIO           17
#define SAMPLE_PERIOD_US     100000  /* 100 ms */
#define LOG_FILE             "distance_log.txt"

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_fp   = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  read_distance(float *distance_out);
static void log_distance(float distance);
static void trigger_alert(float distance);
static void cleanup(void);

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;          /* let main loop exit cleanly */
}

/* ----------------------------- I2C init ---------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ICU20201_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/* ----------------------------- Read distance ------------------------------ */
static int read_distance(float *distance_out)
{
    if (distance_out == NULL) {
        return -1;
    }

    /* Read high byte first, then low byte */
    int hi = i2cReadByteData(g_i2c_handle, DISTANCE_HIGH_REG);
    if (hi < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(0x%02X) failed: %d\n",
                DISTANCE_HIGH_REG, hi);
        return -1;
    }

    int lo = i2cReadByteData(g_i2c_handle, DISTANCE_LOW_REG);
    if (lo < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(0x%02X) failed: %d\n",
                DISTANCE_LOW_REG, lo);
        return -1;
    }

    uint16_t raw = ((uint16_t)hi << 8) | (uint16_t)lo;
    *distance_out = (float)raw;   /* raw units are in cm (per datasheet) */
    return 0;
}

/* ----------------------------- Log distance ------------------------------- */
static void log_distance(float distance)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[WARN] time() failed; logging with epoch\n");
        now = 0;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "[WARN] localtime_r() failed\n");
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    if (fprintf(g_log_fp, "%s, Distance: %.2f cm\n", ts, distance) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "[WARN] fflush log failed\n");
    }
}

/* ----------------------------- Alert GPIO --------------------------------- */
static void trigger_alert(float distance)
{
    if (distance < DISTANCE_THRESHOLD) {
        if (gpioWrite(ALERT_GPIO, 1) < 0) {
            fprintf(stderr, "[WARN] gpioWrite(%d, 1) failed\n", ALERT_GPIO);
        }
        printf("[ALERT] Object within %.1f cm (current: %.2f cm)\n",
               DISTANCE_THRESHOLD, distance);
    } else {
        if (gpioWrite(ALERT_GPIO, 0) < 0) {
            fprintf(stderr, "[WARN] gpioWrite(%d, 0) failed\n", ALERT_GPIO);
        }
    }
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(ALERT_GPIO, 0);
    gpioSetMode(ALERT_GPIO, PI_INPUT);
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure alert GPIO */
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", ALERT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_GPIO, 0);

    /* Initialize I2C */
    if (init_i2c() != 0) {
        fprintf(stderr, "[FATAL] I2C initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed\n");
    }

    printf("ICU-20201 distance monitor started.  Threshold: %.1f cm  GPIO%d\n",
           DISTANCE_THRESHOLD, ALERT_GPIO);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        float distance = 0.0f;

        if (read_distance(&distance) != 0) {
            fprintf(stderr, "[ERROR] Distance read failed; skipping sample\n");
        } else {
            log_distance(distance);
            trigger_alert(distance);
        }

        /* Sleep 100 ms, but wake early on signal */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

