{
    uint8_t model_id = 0;
    if (vl53l1x_read_reg16(handle, VL53L1X_MODEL_ID_REG, &model_id, 1) < 0) {
        fprintf(stderr, "Error: failed to read model ID register.\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, VL53L1X_MODEL_ID_EXPECTED);
        return -1;
    }
    printf("VL53L1X detected (model ID 0x%02X).\n", model_id);

    if (vl53l1x_write_reg16(handle, VL53L1X_SOFT_RESET_REG, VL53L1X_SOFT_RESET_VAL) < 0) {
        fprintf(stderr, "Error: failed to write soft reset register.\n");
        return -1;
    }
    gpioDelay(2000);

