#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

/* CH201 I2C default address (7-bit) */
#define CH201_ADDR 0x45

/* GPIO pin for the LED (BCM numbering) */
#define LED_PIN 18

/* I2C bus on Raspberry Pi 4 (GPIO 2 = SDA, GPIO 3 = SCL) */
#define I2C_BUS 1

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 100000

/* Retry parameters for I2C operations */
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_US 10000

/* CH201 register addresses */
#define CH201_REG_DISTANCE_MSB 0x00
#define CH201_REG_DISTANCE_LSB 0x01
#define CH201_REG_CONFIG 0x02

/* Configuration: 100 ms period, 10 Hz output rate, 16-bit resolution */
#define CH201_CONFIG_VALUE 0x000A

/* Distance range mapping */
#define MIN_DISTANCE_MM 50
#define MAX_DISTANCE_MM 500
#define MIN_FREQUENCY_HZ 10
#define MAX_FREQUENCY_HZ 1

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a CH201 register via I2C                   */
/* ------------------------------------------------------------------ */
static int ch201_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 3);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, I2C_RETRIES, strerror(errno));
        gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a CH201 register via I2C                  */
/* ------------------------------------------------------------------ */
static int ch201_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[2];

    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, reg_buf, 1);
        if (rc != 0) {
            fprintf(stderr, "I2C write (reg select 0x%02X) failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, I2C_RETRIES, strerror(errno));
            gpioDelay(I2C_RETRY_DELAY_US);
            continue;
        }

        rc = i2cReadDevice(handle, data, 2);
        if (rc == 2) {
            *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
            return 0;
        }
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, I2C_RETRIES, strerror(errno));
        gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Initialise the CH201 sensor: configure output rate                 */
/* ------------------------------------------------------------------ */
static int ch201_init(int handle)
{
    if (ch201_write_reg16(handle, CH201_REG_CONFIG, CH201_CONFIG_VALUE) != 0) {
        fprintf(stderr, "Failed to configure CH201 (sensor may be absent or bus error)\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in millimetres from the CH201                        */
/* ------------------------------------------------------------------ */
static int ch201_read_distance(int handle, uint16_t *distance_mm)
{
    return ch201_read_reg16(handle, CH201_REG_DISTANCE_MSB, distance_mm);
}

/* ------------------------------------------------------------------ */
/* Map distance to a blink frequency (Hz)                             */
/* ------------------------------------------------------------------ */
static int distance_to_frequency(uint16_t distance_mm)
{
    if (distance_mm <= MIN_DISTANCE_MM)
        return MAX_FREQUENCY_HZ;
    if (distance_mm >= MAX_DISTANCE_MM)
        return MIN_FREQUENCY_HZ;

    float frac = (float)(distance_mm - MIN_DISTANCE_MM) /
                 (float)(MAX_DISTANCE_MM - MIN_DISTANCE_MM);
    return (int)(MAX_FREQUENCY_HZ - frac * (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ));
}

/* ------------------------------------------------------------------ */
/* Blink the LED at the given frequency for one half-cycle             */
/* ------------------------------------------------------------------ */
static void blink_led(int pin, int frequency_hz)
{
    if (frequency_hz <= 0) {
        gpioWrite(pin, 0);
        return;
    }
    int half_period_us = 500000 / frequency_hz / 2;
    gpioWrite(pin, 1);
    gpioDelay(half_period_us);
    gpioWrite(pin, 0);
    gpioDelay(half_period_us);
}

/* ------------------------------------------------------------------ */
/* Log a timestamped reading                                           */
/* ------------------------------------------------------------------ */
static void log_reading(uint16_t distance_mm, int frequency_hz)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Distance: %u mm, Blink frequency: %d Hz\n",
           timestamp, distance_mm, frequency_hz);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure LED pin --- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, CH201_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialise sensor --- */
    if (ch201_init(g_i2c_handle) != 0) {
        fprintf(stderr, "CH201 initialisation failed — sensor may be absent or bus error\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH201 distance sensor running. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t distance_mm = 0;

        if (ch201_read_distance(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "Failed to read distance — continuing\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int frequency_hz = distance_to_frequency(distance_mm);
        blink_led(LED_PIN, frequency_hz);
        log_reading(distance_mm, frequency_hz);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

