#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x60
#define MEASURE_CMD 0x01
#define MEASURE_DELAY_US 10000
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3
#define LOG_FILE "distance_log.csv"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, MLX75030_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int trigger_measurement(void) {
    char cmd = MEASURE_CMD;
    int rc = i2cWriteDevice(i2c_handle, &cmd, 1);
    if (rc < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", rc);
        return -1;
    }
    return 0;
}

static int read_distance(uint16_t *distance_cm) {
    char buf[2];
    int rc = i2cReadDevice(i2c_handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading distance (rc=%d)\n", rc);
        return -1;
    }
    *distance_cm = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int log_data(uint16_t distance_cm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%u\n", timestamp, distance_cm) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("MLX75030 distance logger started. Press Ctrl+C to stop.\n");

    while (running) {
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            if (trigger_measurement() != 0) {
                retries++;
                gpioDelay(100000);
                continue;
            }
            gpioDelay(MEASURE_DELAY_US);
            uint16_t distance_cm;
            if (read_distance(&distance_cm) == 0) {
                success = 1;
                break;
            }
            retries++;
            gpioDelay(100000);
        }

        if (success) {
            if (log_data(distance_cm) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
        }

        if (running) {
            gpioDelay(SAMPLE_INTERVAL_US);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

