#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x49
#define CSV_FILENAME   "distance_log.csv"

/* CH-101 register map */
#define REG_MEAS_TRIGGER  0x04
#define REG_MEAS_STATUS   0x06
#define REG_DIST_HIGH     0x08
#define REG_DIST_LOW      0x09

#define MEAS_STATUS_DATA_READY 0x01
#define MEAS_TRIGGER_VALUE     0x01
#define POLL_TIMEOUT_MS        50
#define POLL_DELAY_MS          1
#define SAMPLE_INTERVAL_MS     500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

