#define REG_RESULT_PEAK_SIGNAL_RATE_28 0x0027
#define REG_RESULT_PEAK_SIGNAL_RATE_29 0x0028
#define REG_RESULT_PEAK_SIGNAL_RATE_30 0x0029
#define REG_RESULT_PEAK_SIGNAL_RATE_31 0x002A
