static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address (big-endian) followed by `len` data bytes. */
static int i2c_write_reg_block(int fd, uint16_t reg, const uint8_t *data, size_t len)
{
    uint8_t buf[3 + 32];
    size_t total = 3 + len;
    if (total > sizeof(buf))
        return -1;

    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    memcpy(buf + 2, data, len);

    ssize_t n = write(fd, buf, total);
    if (n < 0) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (n != (ssize_t)total) {
        fprintf(stderr, "I2C write to reg 0x%04X short: %zd/%zu\n", reg, n, total);
        return -1;
    }
    return 0;
}

/* Read `len` bytes starting from a 16-bit register address. */
static int i2c_read_reg_block(int fd, uint16_t reg, uint8_t *data, size_t len)
{
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) for reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, data, len);
    if (n < 0) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%04X short: got %zd, expected %zu\n", reg, n, len);
        return -1;
    }
    return 0;
}

static int vl53l5cx_write_reg(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (addr) for reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (write(fd, &value, 1) != 1) {
        fprintf(stderr, "I2C write data to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l5cx_read_reg(int fd, uint16_t reg, uint8_t *value)
{
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) for reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l5cx_init(int fd)
{
    /* Soft reset */
    if (vl53l5cx_write_reg(fd, REG_SOFT_RESET, 0x00) < 0) return -1;
    usleep(10000);  /* 10 ms */
    if (vl53l5cx_write_reg(fd, REG_SOFT_RESET, 0x01) < 0) return -1;
    usleep(10000);  /* 10 ms */

    /* Start ranging (8x8 grid, continuous mode) */
    if (vl53l5cx_write_reg(fd, REG_SYSTEM_MODE_START, 0x01) < 0) return -1;
    usleep(10000);  /* 10 ms */

    return 0;
}

static int vl53l5cx_read_distance(int fd, uint8_t *distance)
{
    uint8_t status;
    if (vl53l5cx_read_reg(fd, REG_RESULT_INTERRUPT_STATUS, &status) < 0)
        return -1;

    if ((status & 0x01) == 0)
        return 1;  /* no new data yet */

    uint8_t dist;
    if (vl53l5cx_read_reg(fd, REG_RESULT_DISTANCE, &dist) < 0)
        return -1;

    *distance = dist;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                VL53L5CX_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (vl53l5cx_init(fd) < 0) {
        fprintf(stderr, "VL53L5CX initialization failed.\n");
        close(fd);
        return 1;
    }

    printf("VL53L5CX initialized. Reading 8x8 grid every 500 ms. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint8_t distances[NUM_ZONES];
        int err = 0;

        for (int i = 0; i < NUM_ZONES && g_running; i++) {
            if (vl53l5cx_read_distance(fd, &distances[i]) < 0) {
                fprintf(stderr, "Error reading zone %d\n", i);
                err = 1;
                break;
            }
        }

        if (err)
            continue;

        printf("Zone Distances (8x8 grid, 64 zones):\n");
        for (int i = 0; i < NUM_ZONES; i++) {
            printf("Zone %2d: %3u mm\n", i, distances[i]);
        }
        printf("---\n");
        fflush(stdout);

        usleep(READ_INTERVAL);
    }

    /* Stop ranging */
    vl53l5cx_write_reg(fd, REG_SYSTEM_MODE_START, 0x00);

    close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

