#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define MLX75030_I2C_ADDR 0x4C
#define I2C_BUS 1
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_distance(int handle, uint16_t *distance) {
    char buf[2];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cReadDevice(handle, buf, 2);
        if (result == 2) {
            *distance = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

static void log_distance(uint16_t distance) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    printf("[%ld.%03ld] Distance: %u mm\n",
           (long)ts.tv_sec, ts.tv_nsec / 1000000, distance);
    fflush(stdout);
}

int main(void) {
    int handle = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, MLX75030_I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %s\n",
                I2C_BUS, MLX75030_I2C_ADDR, strerror(errno));
        goto cleanup_gpio;
    }

    while (running) {
        uint16_t distance;
        if (read_distance(handle, &distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup_i2c:
    if (handle >= 0) {
        i2cClose(handle);
    }
cleanup_gpio:
    gpioTerminate();
    return ret;
}

