#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

/* VL53L4CX I2C default address (SA0 tied to GND) */
#define VL53L4CX_ADDR 0x29

/* VL53L4CX register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET          0x7FFF
#define REG_SYSTEM_START        0x0009
#define REG_INT_STATUS          0x0046
#define REG_DISTANCE_HIGH       0x0096
#define REG_DISTANCE_LOW        0x0097

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address and 1 byte of data */
static int write_reg16(uint8_t handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing register 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit register address and return the 16-bit value (big-endian) */
static int read_reg16(uint8_t handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing register address 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading register 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* Initialize the VL53L4CX sensor */
static int init_sensor(uint8_t handle) {
    /* Soft reset */
    if (write_reg16(handle, REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Failed to write soft reset register\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Start ranging */
    if (write_reg16(handle, REG_SYSTEM_START, 0x00) != 0) {
        fprintf(stderr, "Failed to start ranging\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms for first measurement */
    return 0;
}

/* Read distance in mm; returns -1 on error */
static int read_distance(uint8_t handle) {
    uint16_t status = 0;
    if (read_reg16(handle, REG_INT_STATUS, &status) != 0) {
        return -1;
    }
    if ((status & 0x01) == 0) {
        return -1; /* No new data yet */
    }

    uint16_t distance_high = 0, distance_low = 0;
    if (read_reg16(handle, REG_DISTANCE_HIGH, &distance_high) != 0) {
        return -1;
    }
    if (read_reg16(handle, REG_DISTANCE_LOW, &distance_low) != 0) {
        return -1;
    }

    return (int)((distance_high << 8) | distance_low);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at the VL53L4CX address */
    g_i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %s\n",
                VL53L4CX_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    /* Initialize the sensor */
    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L4CX distance sensor started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int distance = read_distance(g_i2c_handle);

        if (distance >= 0) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            struct tm tm_info;
            localtime_r(&ts.tv_sec, &tm_info);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
            printf("Timestamp: %s.%06ld, Distance: %d mm\n",
                   timestamp, ts.tv_nsec / 1000, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(500000); /* 500 ms */
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return 0;
}

