        return -1;
    }
    if (read_reg16(handle, REG_DISTANCE_LOW, &distance_low) != 0) {
        return -1;
    }

    return (int)((distance_high << 8) | distance_low);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at the VL53L4CX address */
    g_i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %s\n",
                VL53L4CX_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    /* Initialize the sensor */
    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L4CX distance sensor started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int distance = read_distance(g_i2c_handle);

        if (distance >= 0) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            struct tm tm_info;
            localtime_r(&ts.tv_sec, &tm_info);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
            printf("Timestamp: %s.%06ld, Distance: %d mm\n",
                   timestamp, ts.tv_nsec / 1000, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(500000); /* 500 ms */
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return 0;
}

