#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD_MM 100
#define POLL_INTERVAL_US 500000

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET              0x0001
#define REG_I2C_SLAVE_DEVICE_ADDR   0x0001
#define REG_SYSTEM_MODE_START       0x0007
#define REG_RESULT_FINAL_DIST_MM    0x0096

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address followed by a single byte value */
static int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Write a 16-bit register address followed by a 16-bit value (little-endian) */
static int vl53l1x_write_word(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value & 0xFF;
    buf[3] = (value >> 8) & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit value from a 16-bit register address (little-endian on the bus) */
static int vl53l1x_read_word(int handle, uint16_t reg, uint16_t *out) {
    char addr_buf[2];
    char data_buf[2];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr_buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, data_buf, 2) != 2) return -1;

    *out = (uint16_t)data_buf[0] | ((uint16_t)data_buf[1] << 8);
    return 0;
}

static int vl53l1x_init(int handle) {
    /* Soft reset */
    if (vl53l1x_write_byte(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Set I2C slave address (default 0x29) */
    if (vl53l1x_write_byte(handle, REG_I2C_SLAVE_DEVICE_ADDR, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Error: failed to set I2C slave address\n");
        return -1;
    }

    /* Start continuous ranging mode */
    if (vl53l1x_write_byte(handle, REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start continuous ranging\n");
        return -1;
    }

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm) {
    return vl53l1x_read_word(handle, REG_RESULT_FINAL_DIST_MM, distance_mm);
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        /* Stop continuous ranging mode */
        vl53l1x_write_byte(g_i2c_handle, REG_SYSTEM_MODE_START, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X\n",
                I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    bool buzzer_active = false;

    while (g_running) {
        uint16_t distance_mm = 0;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance_mm);

        if (rc < 0) {
            fprintf(stderr, "Warning: I2C read error, skipping iteration\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        printf("Distance: %u mm\n", distance_mm);

        if (distance_mm < DISTANCE_THRESHOLD_MM) {
            if (!buzzer_active) {
                gpioWrite(BUZZER_GPIO, 1);
                buzzer_active = true;
                printf("Buzzer ON\n");
            }
        } else {
            if (buzzer_active) {
                gpioWrite(BUZZER_GPIO, 0);
                buzzer_active = false;
                printf("Buzzer OFF\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

