#define REG_SOFT_RESET 0x0000
#define REG_SYSTEM_START 0x0080
#define REG_RESULT_RANGE_STATUS 0x0089
#define REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int msg_queue_id = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, REG_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error: Failed to read model ID (sensor absent or bus error).\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Unexpected model ID 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }
    printf("VL53L1X detected, model ID: 0x%02X\n", model_id);

    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write soft reset 0x00.\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to write soft reset 0x01.\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg16(handle, 0x0001, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write timing budget register.\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg16(handle, REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
