        if (i2c_read_reg16(handle, REG_RESULT_RANGE_STATUS, &status, 1) != 1) {
            fprintf(stderr, "Warning: I2C read error (status), retry %d/%d\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
