        if (status & 0x01) {
            uint8_t dist_buf[2];
            if (i2c_read_reg16(handle, REG_RESULT_DISTANCE, dist_buf, 2) != 2) {
                fprintf(stderr, "Warning: I2C read error (distance), retry %d/%d\n", retries + 1, MAX_RETRIES);
                retries++;
                gpioDelay(10000);
                continue;
            }
            return (dist_buf[0] << 8) | dist_buf[1];
        }
        gpioDelay(10000);
        retries++;
    }
    return -1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2c_write_reg16(i2c_handle, REG_SYSTEM_START, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (msg_queue_id >= 0) {
        msgctl(msg_queue_id, IPC_RMID, NULL);
        msg_queue_id = -1;
    }
    gpioTerminate();
}

