#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define BUZZER_THRESHOLD_CM 30.0
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 50000
#define LOOP_DELAY_US 100000

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile int      g_echo_seen  = 0;
static volatile int      g_running    = 1;

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_start_tick = tick;
        g_echo_seen  = 0;
    } else if (level == 0 && g_start_tick != 0) {
        g_end_tick = tick;
        g_echo_seen = 1;
    }
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double calculate_distance(uint32_t pulse_width_us)
{
    return (double)pulse_width_us * SPEED_OF_SOUND_CM_PER_S / 2000000.0;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert function on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize BUZZER_PIN %d to LOW.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioWrite(BUZZER_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        g_start_tick = 0;
        g_end_tick   = 0;
        g_echo_seen  = 0;

        trigger_sensor();

        uint32_t waited = 0;
        while (!g_echo_seen && waited < ECHO_TIMEOUT_US && g_running) {
            gpioDelay(100);
            waited += 100;
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_seen) {
            fprintf(stderr, "Warning: sensor timeout (no echo received).\n");
            gpioWrite(BUZZER_PIN, 0);
        } else {
            uint32_t pulse_width = g_end_tick - g_start_tick;
            double distance = calculate_distance(pulse_width);

            if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
                fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f, %.0f].\n",
                        distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
            } else {
                printf("Distance: %.2f cm\n", distance);
            }

            if (distance < BUZZER_THRESHOLD_CM) {
                gpioWrite(BUZZER_PIN, 1);
            } else {
                gpioWrite(BUZZER_PIN, 0);
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

