/*
 * HC-SR04 Ultrasonic Distance Measurement for Raspberry Pi 4 Model B
 * Library: pigpio (modern API, no wiringPi)
 *
 * Wiring:
 *   TRIG -> GPIO 23 (physical pin 16, BCM)
 *   ECHO -> GPIO 24 (physical pin 18, BCM) via voltage divider / logic-level
 *          converter because the HC-SR04 ECHO is 5V.
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIG_PIN          23
#define ECHO_PIN          24

#define SPEED_OF_SOUND    0.0343          /* cm per microsecond (343 m/s) */
#define MIN_PULSE_US      100             /* reject < 100 us noise        */
#define MAX_PULSE_US      30000           /* reject > 30 ms timeout       */
#define TIMEOUT_US        60000           /* 60 ms timeout for echo       */
#define SAMPLE_PERIOD_US  200000          /* 5 Hz measurement rate        */
#define TRIG_PULSE_US     10              /* 10 us trigger pulse          */

#define LOG_FILE          "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

/* ------------------------------------------------------------------ */
/* Echo alert callback (runs in pigpio thread)                          */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    static uint32_t rising_tick = 0;
    static bool     got_rising  = false;

    if (level == 1) {
        /* Rising edge: echo starts */
        rising_tick = tick;
        got_rising  = true;
    } else if (level == 0 && got_rising) {
        /* Falling edge: echo ends */
        uint32_t pulse_us = tick - rising_tick;   /* handles 32-bit wrap */
        double   distance = (double)pulse_us * SPEED_OF_SOUND / 2.0;

        if (distance >= (double)MIN_PULSE_US &&
            distance <= (double)MAX_PULSE_US) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));

            printf("%s - Distance: %.2f cm\n", ts, distance);
            fflush(stdout);

            if (g_log_fp) {
                fprintf(g_log_fp, "%s - Distance: %.2f cm\n",
                        ts, distance);
                fflush(g_log_fp);
            }
        } else {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            fprintf(stderr, "%s - Warning: invalid reading (%.0f us) "
                            "rejected (min %d, max %d)\n",
                    ts, (double)pulse_us, MIN_PULSE_US, MAX_PULSE_US);
        }

        got_rising = false;
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure GPIO ---- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set TRIG_PIN %d as output.\n", TRIG_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: cannot set pull-down on ECHO_PIN %d.\n",
                ECHO_PIN);
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(5000);  /* 5 ms settle */

    /* ---- register alert callback ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: cannot register alert on ECHO_PIN %d.\n",
                ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HC-SR04 distance measurement started.\n");
    printf("  TRIG_PIN : GPIO %d\n", TRIG_PIN);
    printf("  ECHO_PIN : GPIO %d\n", ECHO_PIN);
    printf("  Log file : %s\n", LOG_FILE);
    printf("  Sample period : %d us (5 Hz)\n", SAMPLE_PERIOD_US);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- main measurement loop ---- */
    while (g_running) {
        /* Reset echo state for this cycle */
        static bool echo_active = false;
        static uint32_t echo_start_tick = 0;

        /* Generate 10 us trigger pulse */
        gpioWrite(TRIG_PIN, 1);
        gpioDelay(TRIG_PULSE_US);
        gpioWrite(TRIG_PIN, 0);

        /* Wait for echo or timeout */
        uint32_t elapsed = 0;
        while (gpioRead(ECHO_PIN) == 0 && elapsed < TIMEOUT_US && g_running) {
            gpioDelay(100);  /* 100 us granularity */
            elapsed += 100;
        }

        if (elapsed >= TIMEOUT_US) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            fprintf(stderr, "%s - Warning: echo timeout (no object detected)\n",
                    ts);
            fflush(stderr);
        }

        /* Wait for echo to go HIGH (rising edge) */
        if (gpioRead(ECHO_PIN) == 1) {
            echo_start_tick = gpioTick();
            echo_active = true;
        }

        /* Wait for echo to go LOW (falling edge) or timeout */
        elapsed = 0;
        while (echo_active && elapsed < TIMEOUT_US && g_running) {
            if (gpioRead(ECHO_PIN) == 0) {
                echo_active = false;
                break;
            }
            gpioDelay(100);
            elapsed += 100;
        }

        if (echo_active) {
            /* Echo still active after timeout — warn */
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            fprintf(stderr, "%s - Warning: echo stuck HIGH (sensor fault)\n",
                    ts);
            fflush(stderr);
        }

        /* Sleep until next sample period */
        uint32_t remaining = SAMPLE_PERIOD_US;
        while (remaining > 0 && g_running) {
            uint32_t chunk = (remaining > 100000) ? 100000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    /* ---- clean shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

