#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_OPEN_PIN 18
#define GATE_CLOSE_PIN 19
#define DISTANCE_THRESHOLD_MM 200
#define POLL_INTERVAL_US 500000
#define LOG_FILE "gate_events.log"

/* VL53L1X 16-bit register addresses */
#define VL53L1X_REG_SOFT_RESET 0x0003
#define VL53L1X_REG_SYSTEM_MODE_START 0x0001
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x000B
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0013
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l1x_write_reg16(uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteI2CBlockData(i2c_handle, buf[0], &buf[1], 2);
}

static int vl53l1x_read_reg16(uint16_t reg, uint8_t *buf, uint8_t len) {
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    return i2cReadI2CBlockData(i2c_handle, addr[0], (char *)buf, len);
}

static int vl53l1x_init(void) {
    if (vl53l1x_write_reg16(VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset register.\n");
        return -1;
    }
    gpioDelay(10000);

    if (vl53l1x_write_reg16(VL53L1X_REG_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to clear soft reset.\n");
        return -1;
    }
    gpioDelay(10000);

    /* Basic configuration: set timing budget to 20 ms (0x000A) */
    if (vl53l1x_write_reg16(0x0001, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write timing budget.\n");
        return -1;
    }
    gpioDelay(10000);

    return 0;
}

static int vl53l1x_read_distance(uint16_t *distance_mm) {
    uint8_t status = 0;
    uint8_t dist_buf[2];

    /* Clear any pending interrupt */
    if (vl53l1x_write_reg16(VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        return -1;
    }

    /* Check if data is ready */
    if (vl53l1x_read_reg16(VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status, 1) < 0) {
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1; /* Not ready yet */
    }

    /* Read 16-bit distance */
    if (vl53l1x_read_reg16(VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) {
        return -1;
    }
    *distance_mm = (dist_buf[0] << 8) | dist_buf[1];

    /* Clear interrupt to allow next measurement */
    if (vl53l1x_write_reg16(VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        return -1;
    }

    return 0;
}

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);

    if (log_file) {
        fprintf(log_file, "%s - %s\n", timestamp, event);
        fflush(log_file);
    }
    printf("%s - %s\n", timestamp, event);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 1);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT);
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 1);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init() < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    log_event("System started");

    while (running) {
        uint16_t distance = 0;
        int ret = vl53l1x_read_distance(&distance);

        if (ret < 0) {
            log_event("Error: I2C communication failure");
