#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18
#define TRIGGER_PIN 24
#define DISTANCE_THRESHOLD_LOW 100
#define DISTANCE_THRESHOLD_HIGH 300
#define POLL_TIMEOUT_MS 1000
#define MAX_RETRIES 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 3);
        if (rc == 3) return 0;
        fprintf(stderr, "I2C write failed (reg 0x%04X, val 0x%02X), rc=%d, attempt %d\n",
                reg, value, rc, attempt + 1);
        gpioDelay(100 << attempt);
    }
    return -1;
}

static int i2c_read_word(int handle, uint16_t reg, uint16_t *out) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, reg_buf, 2);
        if (rc != 2) {
            fprintf(stderr, "I2C write (reg select) failed for 0x%04X, rc=%d, attempt %d\n",
                    reg, rc, attempt + 1);
            gpioDelay(100 << attempt);
            continue;
        }
        char data[2];
        rc = i2cReadDevice(handle, data, 2);
        if (rc == 2) {
            *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
            return 0;
        }
        fprintf(stderr, "I2C read failed for 0x%04X, rc=%d, attempt %d\n",
                reg, rc, attempt + 1);
        gpioDelay(100 << attempt);
    }
    return -1;
}

static int vl53l1x_init(int handle) {
    if (i2c_write_byte(handle, 0x0000, 0x00) != 0) return -1;
    gpioDelay(1000);
    if (i2c_write_byte(handle, 0x0000, 0x01) != 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint16_t status = 0;
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (i2c_read_word(handle, 0x0089, &status) != 0) return -1;
        if (status & 0x0001) break;
        gpioDelay(1000);
    }
    if (!(status & 0x0001)) {
        fprintf(stderr, "VL53L1X data not ready after timeout\n");
        return -1;
    }
    if (i2c_read_word(handle, 0x0096, distance) != 0) return -1;
    return 0;
}

static void motor_stop(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
}

static void motor_forward(void) {
    motor_stop();
    gpioWrite(MOTOR_FORWARD_PIN, 1);
    printf("Motor: Forward\n");
}

static void motor_backward(void) {
    motor_stop();
    gpioWrite(MOTOR_BACKWARD_PIN, 1);
    printf("Motor: Backward\n");
}

static void trigger_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)tick; (void)userdata;
    if (level == 1) {
        uint16_t distance = 0;
        if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
            printf("Distance: %u mm\n", distance);
            if (distance < DISTANCE_THRESHOLD_LOW) motor_forward();
            else if (distance > DISTANCE_THRESHOLD_HIGH) motor_backward();
            else motor_stop();
        } else {
            fprintf(stderr, "Sensor read failed, stopping motor\n");
            motor_stop();
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed (sensor absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(TRIGGER_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    motor_stop();

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR on GPIO%d\n", TRIGGER_PIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L1X distance sensor ready. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    motor_stop();
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

