#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPR121_ADDR    0x5A

#define LED_PIN_1 17
#define LED_PIN_2 18
#define LED_PIN_3 27
#define LED_PIN_4 22

#define POLL_DELAY_US 50000

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG0    0x5E
#define MPR121_AUTOCONFIG0   0x5A
#define MPR121_AUTOCONFIG1   0x5B
#define MPR121_AUTOCONFIG2   0x5C
#define MPR121_AUTOCONFIG3   0x5D
#define MPR121_SOFTRESET     0x80

/* Expected presence value from register 0x00 after a soft reset */
#define MPR121_EXPECTED_RESET_TOUCHSTATUS 0x00

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_lines[4] = {NULL};
static const int led_pins[4] = {LED_PIN_1, LED_PIN_2, LED_PIN_3, LED_PIN_4};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, msg);
    fflush(log_file);
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    /* Soft reset */
    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0) return -1;
    usleep(10000); /* 10 ms settle after reset */

    uint8_t reset_touchstatus;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &reset_touchstatus) < 0) return -1;
    if (reset_touchstatus != MPR121_EXPECTED_RESET_TOUCHSTATUS) {
        fprintf(stderr, "MPR121 not detected (touchstatus=0x%02X, expected 0x%02X)\n",
                reset_touchstatus, MPR121_EXPECTED_RESET_TOUCHSTATUS);
        return -1;
    }

    /* Stop mode: disable all electrodes */
    if (i2c_write_reg8(fd, MPR121_ELECONFIG0, 0x00) < 0) return -1;

    /* Baseline filtering */
    if (i2c_write_reg8(fd, 0x2B, 0x01) < 0) return -1; /* MHDR */
    if (i2c_write_reg8(fd, 0x2C, 0x01) < 0) return -1; /* NHDR */
    if (i2c_write_reg8(fd, 0x2D, 0x0E) < 0) return -1; /* NCLR */
    if (i2c_write_reg8(fd, 0x2E, 0x00) < 0) return -1; /* FDLR */

    /* Auto-configuration thresholds */
    if (i2c_write_reg8(fd, MPR121_AUTOCONFIG0, 0x0B) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_AUTOCONFIG1, 0xC8) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_AUTOCONFIG2, 0x82) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_AUTOCONFIG3, 0xB4) < 0) return -1;

    /* Enable all 12 electrodes in run mode */
    if (i2c_write_reg8(fd, MPR121_ELECONFIG0, 0x0C) < 0) return -1;

    return 0;
}

