#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define LED_GPIO 27
#define I2C_BUS 1
#define PROXIMITY_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x05
#define LOG_FILE "proximity.log"

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_DEBOUNCE 0x5B
#define MPR121_AFE_CONFIG0 0x5C
#define MPR121_AFE_CONFIG1 0x5D
#define MPR121_ELECTRODE_FILTER 0x5E
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %s\n",
                value, reg, pigpio_error(rc));
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write_reg(MPR121_TOUCHTH_0, PROXIMITY_THRESHOLD) < 0) return -1;
    if (mpr121_write_reg(MPR121_RELEASETH_0, RELEASE_THRESHOLD) < 0) return -1;

    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_AFE_CONFIG0, 0x10) < 0) return -1;
    if (mpr121_write_reg(MPR121_AFE_CONFIG1, 0x20) < 0) return -1;
    if (mpr121_write_reg(MPR121_ELECTRODE_FILTER, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDF, 0x05) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLT, 0x00) < 0) return -1;

    if (mpr121_write_reg(MPR121_ELECTRODE_CONFIG, 0x01) < 0) return -1;

    return 0;
}

static int read_proximity(void) {
    int low = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (low < 0) {
        fprintf(stderr, "Error reading touch status low byte: %s\n", pigpio_error(low));
        return -1;
    }
    int high = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (high < 0) {
        fprintf(stderr, "Error reading touch status high byte: %s\n", pigpio_error(high));
        return -1;
    }
    return (high << 8) | low;
}

static void log_proximity_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Proximity detected on electrode 0\n", timestamp);
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting LED GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int proximity = read_proximity();
        if (proximity < 0) {
            gpioDelay(100000);
            continue;
        }

        if (proximity & 0x01) {
            printf("Proximity detected!\n");
            gpioWrite(LED_GPIO, 1);
            log_proximity_event();
            gpioDelay(1000000);
            gpioWrite(LED_GPIO, 0);
        }
        gpioDelay(100000);
    }

    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

