#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define TIMEOUT_US  30000   /* 30 ms timeout for echo */
#define SPEED_CM_US 0.0343  /* 343 m/s -> cm/us */
#define MIN_DIST_CM 2.0
#define MAX_DIST_CM 400.0

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

static void log_reading(float distance)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(log_fp, "%s,%.2f\n", ts, distance);
    fflush(log_fp);
}

static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(log_fp, "%s,ERROR,%s\n", ts, msg);
    fflush(log_fp);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(log)");
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Ensure trigger starts low */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig,0)");
            break;
        }
        usleep(5);

        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trig,1)");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig,0)");
            break;
        }

        /* Wait for echo rising edge */
        int val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value(echo)");
            break;
        }
        if (val == 1) {
            struct timespec t0, t1;
            clock_gettime(CLOCK_MONOTONIC, &t0);

            /* Wait for echo falling edge */
            do {
                val = gpiod_line_get_value(echo);
                if (val < 0) {
                    perror("gpiod_line_get_value(echo)");
                    break;
                }
                clock_gettime(CLOCK_MONOTONIC, &t1);
            } while (val == 1 && (t1.tv_sec - t0.tv_sec) * 1000000 +
                     (t1.tv_nsec - t0.tv_nsec) / 1000 < TIMEOUT_US);

            if (val != 1) {
                log_error("Echo timeout (no response)");
                continue;
            }

            long pulse_us = (t1.tv_sec - t0.tv_sec) * 1000000 +
                            (t1.tv_nsec - t0.tv_nsec) / 1000;
            float dist = (pulse_us * SPEED_CM_US) / 2.0f;

            if (dist < MIN_DIST_CM || dist > MAX_DIST_CM) {
                log_error("Reading out of range");
            } else {
                log_reading(dist);
            }
        } else {
            log_error("Echo never rose (sensor absent?)");
        }

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);
    return ret;
}

