#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define TRIGGER_US  10
#define SAMPLE_US   1000000
#define MIN_PULSE_US 58
#define MAX_PULSE_US 25000

static volatile sig_atomic_t running = 1;
static volatile uint32_t echo_start = 0;
static volatile uint32_t echo_end   = 0;
static volatile int      echo_ready = 0;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        echo_start = tick;
    } else if (level == 0) {
        echo_end = tick;
        echo_ready = 1;
    }
}

static double calculate_distance(uint32_t start, uint32_t end) {
    uint32_t diff;
    if (end >= start) {
        diff = end - start;
    } else {
        diff = (0xFFFFFFFFu - start) + end + 1u;
    }
    return (double)diff * 34300.0 / 2000000.0;
}

static int log_distance(double distance) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(log_fp, "%s,%.3f\n", timestamp, distance) < 0) {
        perror("fprintf to log file failed");
        return -1;
    }
    fflush(log_fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR on ECHO_PIN %d\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_ready = 0;
        echo_start = 0;
        echo_end   = 0;

        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Failed to set TRIGGER_PIN high\n");
            break;
        }
        gpioDelay(TRIGGER_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Failed to set TRIGGER_PIN low\n");
            break;
        }

        if (gpioDelay(SAMPLE_US) != 0) {
            fprintf(stderr, "gpioDelay failed\n");
            break;
        }

        if (!echo_ready) {
            fprintf(stderr, "No echo received within sample window\n");
            continue;
        }

        double distance = calculate_distance(echo_start, echo_end);

        if (distance < 0.0 || distance > 400.0) {
            fprintf(stderr, "Out-of-range distance: %.3f m\n", distance);
            continue;
        }

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Failed to log distance\n");
        }
    }

    printf("\nShutting down...\n");
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

