#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define TRIGGER_PIN 27
#define DISTANCE_REG 0x0014
#define STATUS_REG 0x0016
#define CONFIG_REG 0x0018
#define TIMEOUT_REG 0x0019
#define START_RANGING_REG 0x0020

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg16(uint8_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int read_reg16(uint8_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(i2c_handle, (char *)buf, len);
}

static int init_vl53l1x(void) {
    if (write_reg16(CONFIG_REG, 0x00) < 0) return -1;
