#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define GATE_GPIO      24
#define DISTANCE_THRESHOLD_CM 20
#define POLL_DELAY_US  100000
#define LOG_FILE       "gate_log.txt"

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_MODEL_ID             0x010F
#define REG_SOFT_RESET           0x000B
#define REG_SYSTEM_MODE_START    0x0015
#define REG_SYSTEM_INTERRUPT     0x0014
#define REG_SYSTEM_INTERRUPT_CLEAR 0x0015
#define REG_RESULT_RANGE_STATUS  0x0089
#define REG_RESULT_DISTANCE      0x0089
#define REG_RANGE_CONFIG_A       0x0021
#define EXPECTED_MODEL_ID        0xEA

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---------- helpers ---------- */

static void log_msg(const char *msg)
{
    if (!g_log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(g_log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(g_log_file);
}

static void log_error(const char *msg)
{
    log_msg(msg);
    fprintf(stderr, "[ERROR] %s\n", msg);
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---------- I2C helpers ---------- */

static int i2c_write_reg16(int h, uint16_t reg, uint8_t val)
{
    char buf[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)val };
    if (i2cWriteDevice(h, buf, 3) < 0) return -1;
    return 0;
}

static int i2c_read_reg16(int h, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char wbuf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(h, wbuf, 2) < 0) return -1;
    if (i2cReadDevice(h, (char *)buf, len) != (int)len) return -1;
    return 0;
}

/* ---------- VL53L1X ---------- */

static int vl53l1x_init(int h)
{
    uint8_t id = 0;
    if (i2c_read_reg16(h, REG_MODEL_ID, &id, 1) < 0) {
        log_error("Failed to read model ID");
        return -1;
    }
    if (id != EXPECTED_MODEL_ID) {
        char msg[64];
        snprintf(msg, sizeof(msg), "Unexpected model ID 0x%02X (expected 0x%02X)",
                 id, EXPECTED_MODEL_ID);
        log_error(msg);
        return -1;
    }
    log_msg("VL53L1X detected, model ID 0x%02X");

    /* Software reset */
    if (i2c_write_reg16(h, REG_SOFT_RESET, 0x00) < 0) {
        log_error("Soft reset write failed");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Set short ranging mode (register 0x0021 = 0x00) */
    if (i2c_write_reg16(h, REG_RANGE_CONFIG_A, 0x00) < 0) {
        log_error("Failed to set ranging mode");
        return -1;
    }

    /* Start ranging (register 0x0015 = 0x01) */
    if (i2c_write_reg16(h, REG_SYSTEM_MODE_START, 0x01) < 0) {
        log_error("Failed to start ranging");
        return -1;
    }

    log_msg("VL53L1X initialised and ranging started");
    return 0;
}

static int vl53l1x_read_distance(int h, int *distance_cm)
{
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0};

    /* Poll for data-ready (bit 0 of register 0x0014) */
    for (int i = 0; i < 100; i++) {
        if (i2c_read_reg16(h, REG_SYSTEM_INTERRUPT, &status, 1) < 0) return -1;
        if (status & 0x01) break;
        gpioDelay(1000); /* 1 ms */
    }
    if (!(status & 0x01)) {
        log_msg("Ranging timeout");
        return -1;
    }

    /* Read 16-bit distance from 0x0089-0x008A */
    if (i2c_read_reg16(h, REG_RESULT_DISTANCE, dist_buf, 2) < 0) return -1;

    uint16_t raw = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    *distance_cm = (int)(raw / 10.0f);

    /* Clear interrupt so next measurement can signal */
    if (i2c_write_reg16(h, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) return -1;

    return 0;
}

/* ---------- gate control ---------- */

static void control_gate(int distance_cm, int *gate_state)
{
    if (distance_cm < DISTANCE_THRESHOLD_CM) {
        if (*gate_state == 0) {
            if (gpioWrite(GATE_GPIO, 1) == 0) {
                *gate_state = 1;
                log_msg("Gate opened");
            } else {
                log_error("Failed to set gate GPIO high");
            }
        }
    } else {
        if (*gate_state == 1) {
            if (gpioWrite(GATE_GPIO, 0) == 0) {
                *gate_state = 0;
                log_msg("Gate closed");
            } else {
                log_error("Failed to set gate GPIO low");
            }
        }
    }
}

/* ---------- cleanup ---------- */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        log_msg("Program terminated");
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ---------- main ---------- */

int main(void)
{
    /* pigpio init */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* I2C open */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Sensor init */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        log_error("VL53L1X initialisation failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Gate GPIO setup */
    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) < 0) {
        log_error("Failed to set gate GPIO mode");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GATE_GPIO, 0); /* start closed */

    /* Log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int gate_state = 0;
    log_msg("Program started");

    /* Main loop */
    while (g_running) {
        int distance_cm = 0;
        if (vl53l1x_read_distance(g_i2c_handle, &distance_cm) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %d cm", distance_cm);
            log_msg(msg);
            control_gate(distance_cm, &gate_state);
        } else {
            log_error("Failed to read distance");
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

