#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <string.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   400.0
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define SERVO_DEFAULT_ANGLE 90
#define ECHO_TIMEOUT_US 30000
#define TRIGGER_PULSE_US 10
#define SAMPLE_COUNT 5
#define TRIGGER_INTERVAL_US 100000

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int echo_timeout = 0;
static volatile int echo_error = 0;

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio != ECHO_PIN) return;
    if (level == 1) {
        start_tick = tick;
        echo_received = 0;
        echo_timeout = 0;
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 1;
        echo_timeout = 0;
    }
}

static double measure_distance(void) {
    echo_received = 0;
