    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x0001) < 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x0000) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_CONFIG, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_A, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_B, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_C, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_D, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_E, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_F, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_G, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_H, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_I, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_J, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_K, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_L, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_M, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_N, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_O, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_P, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_Q, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_R, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_S, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_T, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_U, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_V, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_W, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_X, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_Y, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_Z, 0x0001) < 0) return -1;

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x0001) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int read_distance(int handle, int16_t *distance) {
    uint16_t status = 0;
    int attempts = 0;
    while (attempts < 10) {
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0) return -1;
        if ((status & 0x0001) != 0) break;
        gpioDelay(10000);
        attempts++;
    }
    if (attempts >= 10) return -1;
    uint16_t dist = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, &dist) < 0) return -1;
    *distance = (int16_t)dist;
    return 0;
}

static void update_buffer(int16_t distance) {
    distance_buffer[buffer_index] = distance;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void check_threshold(int16_t distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t distance = 0;
        if (read_distance(i2c_handle, &distance) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
        } else {
            update_buffer(distance);
            check_threshold(distance);
            printf("Distance: %d mm\n", distance);
        }
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

