#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define PROXIMITY_HIGH_REG 0x08
#define PROXIMITY_LOW_REG 0x09
#define INTERRUPT_GPIO 27
#define LOG_FILE "proximity.log"

static int i2c_handle = -1;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int proximity_threshold = DEFAULT_THRESHOLD;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n", i2c_address, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_proximity(int *proximity) {
    int high = i2cReadByteData(i2c_handle, PROXIMITY_HIGH_REG);
    if (high < 0) {
        fprintf(stderr, "Error reading high byte: %s\n", strerror(errno));
        return -1;
    }
    int low = i2cReadByteData(i2c_handle, PROXIMITY_LOW_REG);
    if (low < 0) {
        fprintf(stderr, "Error reading low byte: %s\n", strerror(errno));
        return -1;
    }
    *proximity = (high << 8) | low;
    return 0;
}

static void log_proximity(int proximity, const char *status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Proximity: %d, Status: %s\n", timestamp, proximity, status);
    fflush(log_file);
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    int proximity;
    if (read_proximity(&proximity) == 0) {
        const char *status = (proximity <= proximity_threshold) ? "SAFE" : "ALERT";
        log_proximity(proximity, status);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 't':
                proximity_threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(INTERRUPT_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", INTERRUPT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error setting pull-down on GPIO %d\n", INTERRUPT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(INTERRUPT_GPIO, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler on GPIO %d\n", INTERRUPT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

