#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define PWM_PIN     18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  200.0f
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000
#define PWM_DUTY_CYCLE   128   /* 50% of 255 */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance using the HC-SR04.
 * Returns distance in cm on success, or -1.0 on timeout/error.
 */
static float measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioTrigger(TRIGGER_PIN, 10, 1) < 0) {
        fprintf(stderr, "Error: gpioTrigger failed\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout ~200 ms) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > 200000) {
            fprintf(stderr, "Error: echo rising-edge timeout\n");
            return -1.0f;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout ~200 ms) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > 200000) {
            fprintf(stderr, "Error: echo falling-edge timeout\n");
            return -1.0f;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_width = echo_end - echo_start;
    float distance = (float)pulse_width * 0.0343f / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range\n", distance);
        return -1.0f;
    }
    return distance;
}

static int set_frequency(int freq)
{
    if (freq < MIN_FREQUENCY_HZ) freq = MIN_FREQUENCY_HZ;
    if (freq > MAX_FREQUENCY_HZ) freq = MAX_FREQUENCY_HZ;

    int pwm_freq = freq;
    int pwm_range = 255;

    if (gpioSetPWMfrequency(PWM_PIN, pwm_freq) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", pwm_freq);
        return -1;
    }
    if (gpioSetPWMrange(PWM_PIN, pwm_range) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d) failed\n", pwm_range);
        return -1;
    }
    if (gpioPWM(PWM_PIN, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "Error: gpioPWM failed\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(PWM) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int prev_freq = 0;
    int first_read = 1;

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            /* Keep previous frequency on error */
            if (!first_read) {
                fprintf(stderr, "Error: measurement failed, keeping previous frequency\n");
            }
            gpioDelay(50000);
            continue;
        }

        first_read = 0;

        /* Logarithmic mapping: f = 200 * exp(d/50) */
        float freq = MIN_FREQUENCY_HZ * expf(distance / 50.0f);

        if (set_frequency((int)freq) < 0) {
            fprintf(stderr, "Error: failed to set frequency\n");
        } else {
            prev_freq = (int)freq;
            printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, prev_freq);
        }

        gpioDelay(50000); /* 50 ms loop delay */
    }

    /* Clean shutdown */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

