#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_FREQ    200
#define MAX_FREQ    2000
#define MIN_DIST    50.0
#define MAX_DIST    500.0

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        return -1;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set echo pull-down\n");
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low\n");
        return -1;
    }
    return 0;
}

static double measure_distance(void) {
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;
    int timeout = 0;

    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > 100000) {
            timeout = 1;
            break;
        }
    }
    if (timeout) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1.0;
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > 100000) {
            timeout = 1;
            break;
        }
    }
    if (timeout) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1.0;
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    double distance = (pulse_width / 58.0);
    return distance;
}

static int set_frequency(double distance) {
    if (distance < 0) {
        return -1;
    }
    double freq = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST);
    if (freq < MIN_FREQ) freq = MIN_FREQ;
    if (freq > MAX_FREQ) freq = MAX_FREQ;
    return gpioHardwarePWM(BUZZER_PIN, (unsigned)freq, 500000);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_gpio() < 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        gpioHardwarePWM(BUZZER_PIN, 0, 0);
        gpioTerminate();
        return 1;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Sensor read error, using last valid distance\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
        }
        int ret = set_frequency(distance);
        if (ret < 0) {
            fprintf(stderr, "Failed to set frequency\n");
        }
        gpioDelay(10000);
    }

    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

