#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 50000
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define TOO_CLOSE_CM 10.0
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioWrite(TRIGGER_PIN, 0);
    return 0;
}

static int trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
    return 0;
}

static int measure_pulse_width(int *out_us) {
    uint32_t start_tick, end_tick, timeout_tick;

    start_tick = gpioTick();
    timeout_tick = start_tick + TIMEOUT_US;

    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            return -1;
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            return -1;
        }
    }
    end_tick = gpioTick();

    *out_us = (int)(end_tick - start_tick);
    return 0;
}

static float calculate_distance_cm(int pulse_us) {
    return (float)pulse_us / 2.0f / 29.1f;
}

static void print_distance(float distance) {
    printf("Distance: %.2f cm", distance);
    if (distance < TOO_CLOSE_CM) {
        printf("  *** TOO CLOSE ***");
    }
    printf("\n");
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    while (running) {
        trigger_sensor();
        int pulse_us;
        if (measure_pulse_width(&pulse_us) != 0) {
            fprintf(stderr, "Error: echo pulse timeout (sensor absent or wiring fault)\n");
        } else {
            float distance = calculate_distance_cm(pulse_us);
            if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
                printf("Invalid reading: %.2f cm (out of range)\n", distance);
            } else {
                print_distance(distance);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioTerminate();
    return 0;
}

