#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define CS_PIN 8
#define LOG_FILE "distance_log.csv"
#define READ_INTERVAL_MS 100

#define ICU20201_REG_MEAS_MODE 0x01
#define ICU20201_REG_RANGE 0x02
#define ICU20201_REG_DISTANCE_LOW 0x0C
#define ICU20201_REG_DISTANCE_HIGH 0x0D
#define ICU20201_REG_TRIGGER 0x00

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_write_reg(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg | 0x80), (char)value };
    char rx[2] = {0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int spi_read_reg(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg & 0x7F), 0x00 };
    char rx[2] = {0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int init_icu20201(void) {
    if (spi_write_reg(ICU20201_REG_MEAS_MODE, 0x01) != 0) return -1;
    if (spi_write_reg(ICU20201_REG_RANGE, 0x00) != 0) return -1;
    if (spi_write_reg(ICU20201_REG_TRIGGER, 0x01) != 0) return -1;
    return 0;
}

static int read_distance(uint16_t *distance) {
    uint8_t low, high;
    if (spi_read_reg(ICU20201_REG_DISTANCE_LOW, &low) != 0) return -1;
    if (spi_read_reg(ICU20201_REG_DISTANCE_HIGH, &high) != 0) return -1;
    *distance = ((uint16_t)high << 8) | low;
    return 0;
}

static void log_distance(uint16_t distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file) { fclose(log_file); log_file = NULL; }
    if (spi_handle >= 0) { spiClose(spi_handle); spi_handle = -1; }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return 1;
    }

    if (init_icu20201() != 0) {
        fprintf(stderr, "ICU-20201 initialisation failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Obstacle avoidance node started. Logging to %s\n", LOG_FILE);

    while (running) {
        uint16_t distance;
        if (read_distance(&distance) == 0) {
            log_distance(distance);
            printf("Distance: %u mm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        gpioDelay(READ_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

