    if (spi_read_reg(ICU20201_REG_DISTANCE_HIGH, &high) != 0) return -1;
    *distance = ((uint16_t)high << 8) | low;
    return 0;
}

static void log_distance(uint16_t distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file) { fclose(log_file); log_file = NULL; }
    if (spi_handle >= 0) { spiClose(spi_handle); spi_handle = -1; }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return 1;
    }

    if (init_icu20201() != 0) {
        fprintf(stderr, "ICU-20201 initialisation failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Obstacle avoidance node started. Logging to %s\n", LOG_FILE);

    while (running) {
        uint16_t distance;
        if (read_distance(&distance) == 0) {
            log_distance(distance);
            printf("Distance: %u mm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        gpioDelay(READ_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

