#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1120_ADDR        0x60
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_RESET   0x30
#define SI1120_REG_ALS_L   0x22
#define SI1120_REG_ALS_H   0x23
#define SI1120_REG_PS1_L   0x18
#define SI1120_REG_PS1_H   0x19
#define SI1120_PART_ID     0x41
#define I2C_BUS            1
#define SAMPLE_PERIOD_US   500000
#define MAX_RETRIES        3
#define RETRY_DELAY_US     10000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: pigpio rc=%d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X = 0x%02X: pigpio rc=%d\n", reg, value, rc);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, uint16_t *als, uint16_t *prox)
{
    uint8_t als_l, als_h, ps1_l, ps1_h;

    if (read_register(handle, SI1120_REG_ALS_L, &als_l) < 0) return -1;
    if (read_register(handle, SI1120_REG_ALS_H, &als_h) < 0) return -1;
    if (read_register(handle, SI1120_REG_PS1_L, &ps1_l) < 0) return -1;
    if (read_register(handle, SI1120_REG_PS1_H, &ps1_h) < 0) return -1;

    *als  = (uint16_t)((als_h << 8) | als_l);
    *prox = (uint16_t)((ps1_h << 8) | ps1_l);
    return 0;
}

static int log_data(FILE *fp, uint16_t als, uint16_t prox)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return -1;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s, ALS: %u, Proximity: %u\n", ts, als, prox) < 0) {
        fprintf(stderr, "fprintf() to log failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed\n");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: pigpio rc=%d\n", I2C_BUS, SI1120_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_register(g_i2c_handle, SI1120_REG_RESET, 0x01) < 0) {
        fprintf(stderr, "Failed to reset Si1120\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(10000);

    uint8_t part_id = 0;
    if (read_register(g_i2c_handle, SI1120_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Failed to read Si1120 part ID\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Unexpected part ID 0x%02X (expected 0x%02X) - wrong sensor?\n", part_id, SI1120_PART_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("si1120_log.txt", "a");
    if (g_log_file == NULL) {
        perror("fopen(si1120_log.txt)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1120 initialised. Logging to si1120_log.txt. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t als = 0, prox = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_sensor_data(g_i2c_handle, &als, &prox) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                gpioDelay(RETRY_DELAY_US);
            }
        }

        if (ok) {
            if (log_data(g_log_file, als, prox) < 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed after %d attempts; skipping sample\n", MAX_RETRIES);
        }

        if (g_running) {
            gpioDelay(SAMPLE_PERIOD_US);
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

