        if (ok) {
            if (log_data(g_log_file, als, prox) < 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed after %d attempts; skipping sample\n", MAX_RETRIES);
        }

        if (g_running) {
            gpioDelay(SAMPLE_PERIOD_US);
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

