#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27
#define DISTANCE_THRESHOLD 20.0
#define SPEED_OF_SOUND 0.0343
#define TRIGGER_PULSE_US 10
#define SAMPLE_INTERVAL_US 1000000

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick   = 0;
static volatile int      echo_received = 0;
static volatile int      running = 1;

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        start_tick = tick;
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 1;
    }
}

static void trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger high) failed\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger low) failed\n");
    }
}

static double calculate_distance(uint32_t pulse_width_us)
{
    return (double)pulse_width_us * SPEED_OF_SOUND / 2.0;
}

static void control_buzzer(double distance)
{
    if (distance < DISTANCE_THRESHOLD) {
        if (gpioWrite(BUZZER_PIN, 1) < 0) {
            fprintf(stderr, "Error: gpioWrite(buzzer on) failed\n");
        }
    } else {
        if (gpioWrite(BUZZER_PIN, 0) < 0) {
            fprintf(stderr, "Error: gpioWrite(buzzer off) failed\n");
        }
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(buzzer) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger init low) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(buzzer init low) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_received = 0;
        start_tick = 0;
        end_tick = 0;

        trigger_sensor();

        if (gpioDelay(30000) < 0) {
            fprintf(stderr, "Error: gpioDelay failed\n");
            break;
        }

        if (echo_received) {
            uint32_t pulse_width = end_tick - start_tick;
            double distance = calculate_distance(pulse_width);
            printf("Distance: %.2f cm\n", distance);
            control_buzzer(distance);
        } else {
            printf("No echo received (sensor absent or out of range)\n");
            control_buzzer(0.0);
        }

        if (running) {
            gpioDelay(SAMPLE_INTERVAL_US);
        }
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

