#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define MAX_DISTANCE 200.0
#define MIN_DISTANCE 20.0
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_MID_ANGLE 90
#define ECHO_TIMEOUT_US 30000
#define LOOP_DELAY_US 100000

static volatile int keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

float measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo start timeout\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo end timeout\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (diff * SPEED_OF_SOUND) / 2000000.0;
    return distance;
}

int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Invalid servo angle %d\n", angle);
        return -1;
    }
    int pulse_width = SERVO_MIN_PULSE + (angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) / 180);
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Error: gpioServo failed\n");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        float distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Error: Distance measurement failed, retrying...\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int angle = SERVO_MID_ANGLE;
        if (distance < MAX_DISTANCE) {
            angle = SERVO_MID_ANGLE - (int)((distance - MIN_DISTANCE) * 100.0 / (MAX_DISTANCE - MIN_DISTANCE));
        }
        if (angle < 0) angle = 0;
