#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7005_ADDR    0x40
#define CONFIG_REG     0x03
#define TEMP_REG       0x01
#define HUMID_REG      0x02
#define CONV_DELAY_US  10000   /* 10 ms conversion wait */
#define LOOP_DELAY_US  2000000 /* 2 s between readings */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, SI7005_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int configure_sensor(void)
{
    /* Write 0x00 to CONFIG_REG to select internal temperature sensor,
     * disable heater, and wait for the first conversion. */
    if (i2cWriteByteData(g_i2c_handle, CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing CONFIG register\n");
        return -1;
    }
    gpioDelay(CONV_DELAY_US);
    return 0;
}

static int read_temperature(float *temp)
{
    if (i2cWriteByte(g_i2c_handle, TEMP_REG) < 0) {
        fprintf(stderr, "Error selecting temperature register\n");
        return -1;
    }
    gpioDelay(CONV_DELAY_US);
    int raw = i2cReadWordData(g_i2c_handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature register: %d\n", raw);
        return -1;
    }
    *temp = ((175.72f * raw) / 65536.0f) - 46.85f;
    return 0;
}

static int read_humidity(float *hum)
{
    if (i2cWriteByte(g_i2c_handle, HUMID_REG) < 0) {
        fprintf(stderr, "Error selecting humidity register\n");
        return -1;
    }
    gpioDelay(CONV_DELAY_US);
    int raw = i2cReadWordData(g_i2c_handle, HUMID_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading humidity register: %d\n", raw);
        return -1;
    }
    *hum = ((125.0f * raw) / 65536.0f) - 6.0f;
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (configure_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp, hum;
        int ok = 1;

        if (read_temperature(&temp) != 0) {
            ok = 0;
        }
        if (ok && read_humidity(&hum) != 0) {
            ok = 0;
        }

        if (ok) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        } else {
            fprintf(stderr, "Sensor read failed; re-initialising I2C\n");
            if (init_i2c() != 0 || configure_sensor() != 0) {
                fprintf(stderr, "Re-initialisation failed; exiting\n");
                break;
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

