#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_WHO_AM_I   0x75
#define MPU6050_WHO_AM_I_VAL 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_PWR_MGMT_2 0x6C
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_SMPLRT_DIV 0x19

/* Expected sample rate = 1 kHz / (1 + SMPLRT_DIV) */
#define SAMPLE_RATE_HZ 125

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int mpu6050_init(int handle)
{
    int who = i2cReadByteData(handle, MPU6050_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who);
        return -1;
    }
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Reset device */
    if (i2cWriteByteData(handle, MPU6050_PWR_MGMT_1, 0x80) < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1 reset\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms */

    /* Wake up: clear sleep bit, set internal oscillator */
    if (i2cWriteByteData(handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1 wake\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms stabilization */

    /* Sample-rate divider: 1 kHz / (1 + 7) = 125 Hz */
    if (i2cWriteByteData(handle, MPU6050_SMPLRT_DIV, 7) < 0) {
        fprintf(stderr, "Error writing SMPLRT_DIV\n");
        return -1;
    }

    /* Accelerometer: ±2 g range */
    if (i2cWriteByteData(handle, MPU6050_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing ACCEL_CONFIG\n");
        return -1;
    }

    /* Gyroscope: ±250 °/s range */
    if (i2cWriteByteData(handle, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing GYRO_CONFIG\n");
        return -1;
    }

    return 0;
}

static int read_mpu6050_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                             int16_t *gx, int16_t *gy, int16_t *gz)
{
    char buf[14];

    if (i2cReadI2CBlockData(handle, MPU6050_ACCEL_XOUT_H, buf, 14) != 14) {
        fprintf(stderr, "Error reading 14-byte data block\n");
        return -1;
    }

    *ax = (int16_t)((buf[0]  << 8) | (uint8_t)buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | (uint8_t)buf[3]);
    *az = (int16_t)((buf[4]  << 8) | (uint8_t)buf[5]);
    /* buf[6..7] = temperature (skipped) */
    *gx = (int16_t)((buf[8]  << 8) | (uint8_t)buf[9]);
    *gy = (int16_t)((buf[10] << 8) | (uint8_t)buf[11]);
    *gz = (int16_t)((buf[12] << 8) | (uint8_t)buf[13]);

    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n",
                MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpu6050_init(g_i2c_handle) < 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialised at 0x%02X. Logging at %d Hz. Press Ctrl+C to stop.\n",
           MPU6050_ADDR, SAMPLE_RATE_HZ);

    int16_t ax, ay, az, gx, gy, gz;
    while (g_running) {
        if (read_mpu6050_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Read error — continuing\n");
        }
        gpioDelay(1000000 / SAMPLE_RATE_HZ); /* 10 ms */
    }

    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

