#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_fp = NULL;
static FILE *err_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    if (!err_fp) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(err_fp, "%s: %s (errno: %d - %s)\n", ts, msg, errno, strerror(errno));
    fflush(err_fp);
}

static int read_temperature(float *temp) {
    uint8_t cmd[2] = {0x04, 0x00};
    uint8_t buf[6];
    int rc;

    rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        log_error("I2C write failed");
        return -1;
    }

    gpioDelay(10000); /* 10 ms conversion time */

    rc = i2cReadDevice(i2c_handle, (char *)buf, 6);
    if (rc < 0) {
        log_error("I2C read failed");
        return -1;
    }
    if (rc != 6) {
        log_error("I2C read short");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp = -45.0f + 175.0f * (float)raw / 65535.0f;
    return 0;
}

