    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: got %zd of %zu bytes: %s\n",
                n, len, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int read_sht40(int fd, float *temperature, float *humidity)
{
    uint8_t data[6];

    if (i2c_write_cmd(fd, MEASURE_CMD) != 0)
        return -1;

    usleep(MEASURE_DELAY);

    if (i2c_read_bytes(fd, data, sizeof(data)) != 0)
        return -1;

    /* Validate CRC for temperature (bytes 0-1, CRC byte 2) */
    if (sht40_crc8(data, 2) != data[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    /* Validate CRC for humidity (bytes 3-4, CRC byte 5) */
    if (sht40_crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t h_raw = (uint16_t)((data[3] << 8) | data[4]);

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

static void log_data(FILE *fp, float temperature, float humidity)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
            ts, temperature, humidity);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SHT40_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Smart Greenhouse Monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature, humidity;

        if (read_sht40(g_i2c_fd, &temperature, &humidity) == 0) {
            log_data(g_log_fp, temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

