#include <unistd.h>

#define I2C_BUS 1
#define SDP31_ADDR 0x28
#define LOG_FILE "airflow.log"
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3
#define RETRY_DELAY_BASE_US 1000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, SDP31_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sdp31(float *pressure, float *temperature) {
    unsigned char cmd[2] = {0x21, 0x96};
    unsigned char buf[6];
    int retries = 0;
    int delay_us = RETRY_DELAY_BASE_US;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d/%d), retrying in %d us...\n",
                    retries + 1, MAX_RETRIES, delay_us);
            gpioDelay(delay_us);
            retries++;
            delay_us *= 2;
            continue;
        }

        gpioDelay(1000);

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d/%d), retrying in %d us...\n",
                    retries + 1, MAX_RETRIES, delay_us);
            gpioDelay(delay_us);
            retries++;
            delay_us *= 2;
            continue;
        }

        int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

        *pressure = (float)raw_pressure / 60.0f;
        *temperature = (float)raw_temperature / 200.0f;
        return 0;
    }

    fprintf(stderr, "Failed to read SDP31 after %d retries.\n", MAX_RETRIES);
    return -1;
}

static int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s.\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float pressure, temperature;

    while (running) {
        if (read_sdp31(&pressure, &temperature) == 0) {
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "Logging failed, continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed, continuing.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

