#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define CMD_CONT_MEAS  0x362F
#define MEAS_DELAY_MS  45
#define SAMPLE_MS     100
#define LOG_FILE      "airflow_data.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len)
{
    int n = read(fd, buf, len);
    if (n != len) {
        fprintf(stderr, "I2C read failed: got %d of %d (%s)\n",
                n, len, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int read_sdp800(int fd, float *pressure, float *temperature)
{
    uint8_t buf[9];

    if (i2c_write_cmd(fd, CMD_CONT_MEAS) < 0)
        return -1;

