#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD_HIGH_REP 0x2C06
#define CONVERSION_DELAY_US 15000
#define SAMPLE_INTERVAL_S 5
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("fopen error_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temperature);
    fclose(fp);
}

static int read_temperature(float *temperature) {
    uint8_t cmd[2] = { (MEASURE_CMD_HIGH_REP >> 8) & 0xFF, MEASURE_CMD_HIGH_REP & 0xFF };
    uint8_t buf[3];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        log_error("I2C write failed");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(i2c_handle, (char *)buf, 3) != 3) {
        log_error("I2C read failed");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        log_error("CRC mismatch");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temperature = -45.0f + (175.0f * (float)raw / 65535.0f);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature;
    while (running) {
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
        }
        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

