#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_HIGH 28.0f
#define TEMP_LOW 27.0f
#define BUFFER_SIZE 60
#define RETRY_COUNT 3
#define MEAS_DELAY_US 10000
#define POLL_INTERVAL_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} SensorData;

static SensorData data_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_measurement(uint8_t cmd, uint16_t *raw) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, cmd);
        if (result < 0) {
            fprintf(stderr, "I2C write error (cmd 0x%02X): %d, retry %d/%d\n",
                    cmd, result, retries + 1, RETRY_COUNT);
            retries++;
            gpioDelay(100000);
            continue;
        }

        gpioDelay(MEAS_DELAY_US);

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            *raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }

        fprintf(stderr, "I2C read error (cmd 0x%02X): %d, retry %d/%d\n",
                cmd, result, retries + 1, RETRY_COUNT);
        retries++;
        gpioDelay(100000);
    }
    return -1;
}

static int read_temperature(float *temp) {
    uint16_t raw;
    if (read_measurement(0xE3, &raw) != 0) {
        return -1;
    }
    *temp = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

static int read_humidity(float *hum) {
    uint16_t raw;
    if (read_measurement(0xE5, &raw) != 0) {
        return -1;
    }
    *hum = (125.0f * (float)raw / 65536.0f) - 6.0f;
    return 0;
}

static void add_to_buffer(float temp, float hum) {
    data_buffer[buffer_index].timestamp = time(NULL);
    data_buffer[buffer_index].temperature = temp;
    data_buffer[buffer_index].humidity = hum;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void) {
    int start = (buffer_index == 0) ? BUFFER_SIZE - 1 : buffer_index - 1;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&data_buffer[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str));
        }
        printf("[%s] Temp: %.2f C, Hum: %.2f %%\n",
               time_str, data_buffer[idx].temperature, data_buffer[idx].humidity);
    }
    fflush(stdout);
}

static void control_fan(float temp) {
    static int fan_on = 0;
    if (temp > TEMP_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON (temp %.2f C)\n", temp);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (temp < TEMP_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (temp %.2f C)\n", temp);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7021 fan controller started. Press Ctrl+C to exit.\n");

    while (running) {
        float temp, hum;

        if (read_temperature(&temp) != 0) {
            fprintf(stderr, "Temperature read failed; skipping cycle\n");
        } else if (read_humidity(&hum) != 0) {
            fprintf(stderr, "Humidity read failed; skipping cycle\n");
        } else {
            add_to_buffer(temp, hum);
            print_buffer();
            control_fan(temp);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

