#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_SEC 5
#define STARTUP_DELAY_SEC 1

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: failed to send command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int read_data(uint8_t *data, int len) {
    if (i2cReadDevice(i2c_handle, (char *)data, len) != len) {
        fprintf(stderr, "Error: failed to read %d bytes from sensor\n", len);
        return -1;
    }
    return 0;
}

static int start_periodic_measurement(void) {
    return send_command(0x21B1);
}

static int stop_periodic_measurement(void) {
    return send_command(0x3F86);
}

static int is_data_ready(void) {
    if (send_command(0xE4B8) != 0)
        return -1;
    uint8_t data[3];
    if (read_data(data, 3) != 0)
        return -1;
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Error: CRC mismatch on data-ready word\n");
        return -1;
    }
    uint16_t word = (data[0] << 8) | data[1];
    return (word & 0x07FF) ? 1 : 0;
}

static int read_measurement(uint16_t *co2, float *temp, float *hum) {
    if (send_command(0xEC05) != 0)
        return -1;
    uint8_t data[9];
    if (read_data(data, 9) != 0)
        return -1;
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5] || crc8(data + 6, 2) != data[8]) {
        fprintf(stderr, "Error: CRC mismatch on measurement data\n");
        return -1;
    }
    uint16_t co2_raw = (data[0] << 8) | data[1];
    uint16_t temp_raw = (data[3] << 8) | data[4];
    uint16_t hum_raw = (data[6] << 8) | data[7];
    *co2 = co2_raw;
    *temp = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *hum = 100.0f * (float)hum_raw / 65535.0f;
    return 0;
}

static void log_data(uint16_t co2, float temp, float hum) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%u,%.2f,%.2f\n", ts, co2, temp, hum);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at 0x%02X on bus %d\n", SCD40_I2C_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (start_periodic_measurement() != 0) {
        fprintf(stderr, "Error: failed to start periodic measurement\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    for (int i = 0; i < STARTUP_DELAY_SEC && !terminate; i++)
        sleep(1);

    if (terminate) {
        stop_periodic_measurement();
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    while (!terminate) {
        int ready = is_data_ready();
        if (ready < 0) {
            fprintf(stderr, "Error: data-ready check failed, retrying in %d s\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }
        if (ready) {
            uint16_t co2;
            float temp, hum;
            if (read_measurement(&co2, &temp, &hum) == 0) {
                log_data(co2, temp, hum);
                printf("CO2: %u ppm, Temp: %.2f C, Hum: %.2f %%\n", co2, temp, hum);
            } else {
                fprintf(stderr, "Error: failed to read measurement\n");
            }
        }
        for (int i = 0; i < POLL_INTERVAL_SEC && !terminate; i++)
            sleep(1);
    }

    stop_periodic_measurement();
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

