#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define SCD40_I2C_ADDR 0x62
#define LED_GPIO 17
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20
#define MEASUREMENT_INTERVAL_SEC 5

/* SCD40 command codes */
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT  0x3F86
#define CMD_GET_DATA_READY_STATUS      0xE4B8
#define CMD_READ_MEASUREMENT           0xEC05

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
    time_t timestamp;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int write_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X): %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

static int read_bytes(uint8_t *buf, int len) {
    int rc = i2cReadDevice(i2c_handle, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "I2C read failed: expected %d, got %d\n", len, rc);
        return -1;
    }
    return 0;
}

static int start_periodic_measurement(void) {
    return write_command(CMD_START_PERIODIC_MEASUREMENT);
}

static int stop_periodic_measurement(void) {
    return write_command(CMD_STOP_PERIODIC_MEASUREMENT);
}

static int get_data_ready_status(bool *ready) {
    if (write_command(CMD_GET_DATA_READY_STATUS) < 0)
        return -1;
    gpioDelay(2000); /* 2 ms processing time */
    uint8_t buf[3];
    if (read_bytes(buf, 3) < 0)
        return -1;
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on data-ready status\n");
        return -1;
    }
    uint16_t word = (buf[0] << 8) | buf[1];
    *ready = (word & 0x07FF) != 0;
    return 0;
}

static int read_measurement(uint16_t *co2, float *temp, float *hum) {
    if (write_command(CMD_READ_MEASUREMENT) < 0)
        return -1;
    gpioDelay(2000);
    uint8_t buf[9];
    if (read_bytes(buf, 9) < 0)
        return -1;
    if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5] || crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "CRC mismatch on measurement data\n");
        return -1;
    }
    uint16_t co2_raw = (buf[0] << 8) | buf[1];
    uint16_t temp_raw = (buf[3] << 8) | buf[4];
    uint16_t hum_raw = (buf[6] << 8) | buf[7];
    *co2 = co2_raw;
    *temp = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *hum = 100.0f * (float)hum_raw / 65535.0f;
    return 0;
}

static void buffer_init(circular_buffer_t *b) {
    b->head = 0;
    b->count = 0;
}

static void buffer_add(circular_buffer_t *b, sensor_data_t d) {
    b->data[b->head] = d;
    b->head = (b->head + 1) % BUFFER_SIZE;
    if (b->count < BUFFER_SIZE)
        b->count++;
}

static void buffer_print(circular_buffer_t *b) {
    int start = (b->count == BUFFER_SIZE) ? b->head : 0;
    for (int i = 0; i < b->count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm = localtime(&b->data[idx].timestamp);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
        printf("[%s] CO2: %u ppm, T: %.2f C, H: %.2f %%\n",
               ts, b->data[idx].co2, b->data[idx].temperature, b->data[idx].humidity);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        stop_periodic_measurement();
        gpioDelay(500000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n", SCD40_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (start_periodic_measurement() < 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    buffer_init(&buffer);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD40 monitoring started. Press Ctrl+C to stop.\n");

    while (running) {
        bool ready = false;
        if (get_data_ready_status(&ready) < 0) {
            fprintf(stderr, "Sensor read error, continuing...\n");
            sleep(MEASUREMENT_INTERVAL_SEC);
            continue;
        }
        if (!ready) {
            sleep(MEASUREMENT_INTERVAL_SEC);
            continue;
        }

        uint16_t co2;
        float temp, hum;
        if (read_measurement(&co2, &temp, &hum) < 0) {
            fprintf(stderr, "Measurement read error\n");
            sleep(MEASUREMENT_INTERVAL_SEC);
            continue;
        }

        sensor_data_t d = { .co2 = co2, .temperature = temp, .humidity = hum, .timestamp = time(NULL) };
        buffer_add(&buffer, d);
        buffer_print(&buffer);

        if (co2 > CO2_THRESHOLD)
            gpioWrite(LED_GPIO, 1);
        else
            gpioWrite(LED_GPIO, 0);

        sleep(MEASUREMENT_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

