static void cleanup(void) {
    if (i2c_handle >= 0) {
        stop_periodic_measurement();
        gpioDelay(500000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

