    i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n", SCD40_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (start_periodic_measurement() < 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    buffer_init(&buffer);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD40 monitoring started. Press Ctrl+C to stop.\n");

    while (running) {
        bool ready = false;
        if (get_data_ready_status(&ready) < 0) {
            fprintf(stderr, "Sensor read error, continuing...\n");
            sleep(MEASUREMENT_INTERVAL_SEC);
            continue;
        }
        if (!ready) {
            sleep(MEASUREMENT_INTERVAL_SEC);
            continue;
        }

        uint16_t co2;
        float temp, hum;
        if (read_measurement(&co2, &temp, &hum) < 0) {
            fprintf(stderr, "Measurement read error\n");
            sleep(MEASUREMENT_INTERVAL_SEC);
            continue;
        }

        sensor_data_t d = { .co2 = co2, .temperature = temp, .humidity = hum, .timestamp = time(NULL) };
        buffer_add(&buffer, d);
        buffer_print(&buffer);

        if (co2 > CO2_THRESHOLD)
            gpioWrite(LED_GPIO, 1);
        else
            gpioWrite(LED_GPIO, 0);

        sleep(MEASUREMENT_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

