#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds */
#define EDGE_TIMEOUT_US 50000        /* 50 ms timeout per edge */
#define MAX_CONSECUTIVE_ERRORS 3

/* TMP05 conversion formula (from datasheet) */
#define TEMP_MIN -40.0f
#define TEMP_MAX 150.0f
#define TEMP_SCALE 4215.0f
#define TEMP_NOMINAL 2143.0f

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one TMP05 cycle via busy-wait polling.                         */
/* Returns 0 on success (TH, TL stored), -1 on timeout, -2 on error.   */
/* ------------------------------------------------------------------ */
static int read_tmp05_cycle(int gpio_pin, uint32_t *th_us, uint32_t *tl_us)
{
    uint32_t start_tick, end_tick;
    int level;
    int consecutive_high = 0;
    int consecutive_low = 0;

    /* Wait for a falling edge (start of high pulse) */
    start_tick = gpioTick();
    do {
        level = gpioRead(gpio_pin);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on pin %d\n", gpio_pin);
            return -2;
        }
        if (level == 0) {
            break;
        }
        if ((gpioTick() - start_tick) > EDGE_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge (sensor absent?)\n");
            return -1;
        }
    } while (1);

    /* Measure high pulse width */
    start_tick = gpioTick();
    do {
        level = gpioRead(gpio_pin);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on pin %d\n", gpio_pin);
            return -2;
        }
        if (level == 1) {
            consecutive_high++;
        } else {
            consecutive_high = 0;
        }
        if ((gpioTick() - start_tick) > EDGE_TIMEOUT_US) {
            fprintf(stderr, "Timeout measuring high pulse width\n");
            return -1;
        }
    } while (level == 1);

    *th_us = (uint32_t)(gpioTick() - start_tick);

    /* Measure total cycle width */
    start_tick = gpioTick();
    do {
        level = gpioRead(gpio_pin);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on pin %d\n", gpio_pin);
            return -2;
        }
        if (level == 0) {
            consecutive_low++;
        } else {
            consecutive_low = 0;
        }
        if ((gpioTick() - start_tick) > EDGE_TIMEOUT_US) {
            fprintf(stderr, "Timeout measuring total cycle width\n");
            return -1;
        }
    } while (level == 0);

    *tl_us = (uint32_t)(gpioTick() - start_tick);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert TH/TL to temperature in degrees Celsius.                   */
/* Returns -999.0 on invalid TL (division by zero).                   */
/* ------------------------------------------------------------------ */
static float calculate_temperature(uint32_t th_us, uint32_t tl_us)
{
    if (tl_us == 0) {
        return -999.0f;
    }
    return TEMP_SCALE - ((float)th_us * TEMP_SCALE / (float)tl_us);
}

/* ------------------------------------------------------------------ */
/* Log a reading with an ISO-8601 timestamp.                           */
/* ------------------------------------------------------------------ */
static void log_reading(float temperature)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (temperature > TEMP_MIN && temperature < TEMP_MAX) {
        fprintf(log_file, "%s, Temperature: %.2f C\n", timestamp, temperature);
    } else {
        fprintf(log_file, "%s, ERROR: Temperature reading out of range: %.2f C\n",
                timestamp, temperature);
    }
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Log a sensor malfunction entry.                                     */
/* ------------------------------------------------------------------ */
static void log_sensor_malfunction(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, ERROR: SENSOR MALFUNCTION\n", timestamp);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — closes file and releases pigpio.                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int consecutive_errors = 0;
    uint32_t th_us, tl_us;
    float temperature;

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO as input */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMP05 temperature logger started on GPIO%d. Logging to '%s'.\n",
           GPIO_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (program_running) {
        int rc = read_tmp05_cycle(GPIO_PIN, &th_us, &tl_us);

        if (rc == 0) {
            consecutive_errors = 0;
            temperature = calculate_temperature(th_us, tl_us);
            log_reading(temperature);
        } else if (rc == -1) {
            /* Timeout — log and continue */
            fprintf(stderr, "Sensor read timeout — continuing.\n");
            log_sensor_malfunction();
        } else {
            /* rc == -2 — gpioRead error — log and continue */
            fprintf(stderr, "gpioRead error — continuing.\n");
            log_sensor_malfunction();
        }

        /* Check for sensor malfunction after MAX_CONSECUTIVE_ERRORS */
        if (consecutive_errors < MAX_CONSECUTIVE_ERRORS) {
            consecutive_errors++;
        }
        if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
            fprintf(stderr, "MAX_CONSECUTIVE_ERRORS reached — logging sensor malfunction.\n");
            log_sensor_malfunction();
            consecutive_errors = 0;  /* Reset to avoid spamming */
        }

        /* Sleep for the sample interval, but wake early on signal */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

