    uint8_t cmd[2] = {MEASUREMENT_CMD_HIGH_REP, MEASUREMENT_CMD_NO_CLOCK_STRETCH};
    uint8_t buf[6];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (retries left: %d)\n", retries - 1);
            retries--;
            if (retries > 0) gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (retries left: %d)\n", retries - 1);
            retries--;
            if (retries > 0) gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "CRC mismatch (retries left: %d)\n", retries - 1);
            retries--;
            if (retries > 0) gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t raw_temperature = (buf[0] << 8) | buf[1];
        uint16_t raw_humidity = (buf[3] << 8) | buf[4];

        *temperature = -45.0f + (175.0f * (float)raw_temperature / 65535.0f);
        *humidity = 100.0f * (float)raw_humidity / 65535.0f;

        return 0;
    }

    fprintf(stderr, "SHT35 read failed after %d retries\n", RETRY_COUNT);
    *temperature = NAN;
    *humidity = NAN;
    return -1;
}

static void simulate_offset(float *temperature, float *humidity) {
    time_t now = time(NULL);
    double offset = sin((double)now / 3600.0) * 2.0;
    *temperature += offset;
    *humidity += offset;
    if (*humidity > 100.0f) *humidity = 100.0f;
    if (*humidity < 0.0f) *humidity = 0.0f;
}

static void log_data(FILE *fp, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", SHT35_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float temperature, humidity;
    while (running) {
        if (read_sht35(i2c_handle, &temperature, &humidity) == 0) {
            simulate_offset(&temperature, &humidity);
            log_data(log_file, temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed, logging NaN values\n");
            log_data(log_file, NAN, NAN);
        }
        sleep(LOG_INTERVAL_S);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

