#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT35_ADDR     0x44
#define MEASURE_CMD    0x2400  /* single-shot, high repeatability, clock stretching disabled */
#define MEASURE_DELAY_US 15000 /* 15 ms measurement wait */
#define SAMPLE_INTERVAL_S 5
#define CSV_FILENAME   "environment.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR */
static uint8_t sht35_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int write_command(int handle, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int read_measurement(int handle, uint8_t *buf, size_t len) {
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "Error: i2cReadDevice failed (expected %zu bytes)\n", len);
        return -1;
    }
    return 0;
}

static int read_sht35(int handle, float *temperature, float *humidity) {
    if (write_command(handle, MEASURE_CMD) != 0)
        return -1;

    gpioDelay(MEASURE_DELAY_US);

    uint8_t data[6];
    if (read_measurement(handle, data, sizeof(data)) != 0)
        return -1;

    /* Validate CRCs */
    if (sht35_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                sht35_crc8(&data[0], 2), data[2]);
        return -1;
    }
    if (sht35_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                sht35_crc8(&data[3], 2), data[5]);
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + (175.0f * (float)t_raw / 65535.0f);
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

static int log_data(const char *filename, float temperature, float humidity) {
    int file_exists = (access(filename, F_OK) == 0);
    int is_empty = (file_exists && (access(filename, R_OK) == 0) &&
                    (ftell(fopen(filename, "r")) == 0));

    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for append\n", filename);
        return -1;
    }

    if (is_empty) {
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: error closing %s\n", filename);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT35 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           CSV_FILENAME, SAMPLE_INTERVAL_S);

    while (g_running) {
        float temperature, humidity;

        if (read_sht35(g_i2c_handle, &temperature, &humidity) == 0) {
            printf("T=%.2f C  RH=%.2f %%\n", temperature, humidity);
            if (log_data(CSV_FILENAME, temperature, humidity) != 0) {
                fprintf(stderr, "Warning: logging failed for this sample\n");
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed, will retry next cycle\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

