#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7021_ADDR    0x40
#define CMD_MEASURE_HUMIDITY_NOHOLD  0xF5
#define CMD_MEASURE_TEMP_NOHOLD     0xF3
#define CMD_READ_TEMP_PREV_HUMID    0xE0
#define CMD_RESET                   0xFE
#define LOG_FILE        "environment.log"
#define POLL_TIMEOUT_MS 100
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_measurement(int fd, uint8_t cmd, uint16_t *raw) {
    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;

    struct timespec ts = {0, POLL_TIMEOUT_MS * 1000000L};
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        if (!g_running)
            return -1;
    }

    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, 3) < 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on measurement (cmd 0x%02X)\n", cmd);
        return -1;
    }

    *raw = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_humidity(int fd, float *humidity) {
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_HUMIDITY_NOHOLD, &raw) < 0)
        return -1;
    *humidity = 125.0f * (float)raw / 65536.0f - 6.0f;
    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;
    return 0;
}

static int read_temperature(int fd, float *temperature) {
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_TEMP_NOHOLD, &raw) < 0)
        return -1;
    *temperature = 175.72f * (float)raw / 65536.0f - 46.85f;
    return 0;
}

static int read_previous_temperature(int fd, float *temperature) {
    uint8_t buf[3];
    if (i2c_write_cmd(fd, CMD_READ_TEMP_PREV_HUMID) < 0)
        return -1;
    if (i2c_read_bytes(fd, buf, 3) < 0)
        return -1;
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on previous temperature read\n");
        return -1;
    }
    uint16_t raw = (uint16_t)((buf[0] << 8) | buf[1]);
    *temperature = 175.72f * (float)raw / 65536.0f - 46.85f;
    return 0;
}

static int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    } else {
        fprintf(fp, "TIMESTAMP_ERROR,%.2f,%.2f\n", temperature, humidity);
    }
    fclose(fp);
    return 0;
}

static int log_error(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,ERROR,ERROR\n", ts);
    } else {
        fprintf(fp, "TIMESTAMP_ERROR,ERROR,ERROR\n");
    }
    fclose(fp);
    return 0;
}

static int reset_sensor(int fd) {
    if (i2c_write_cmd(fd, CMD_RESET) < 0)
        return -1;
    struct timespec ts = {0, 15 * 1000000L};
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        if (!g_running)
            return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (fp) {
            fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
            fclose(fp);
        }
    } else {
        fclose(fp);
    }

    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;
        int ok = 1;

        if (read_humidity(g_i2c_fd, &humidity) < 0) {
            ok = 0;
        } else if (read_temperature(g_i2c_fd, &temperature) < 0) {
            ok = 0;
        } else {
            if (log_data(LOG_FILE, temperature, humidity) < 0)
                fprintf(stderr, "Failed to log data\n");
        }

        if (!ok) {
            fprintf(stderr, "Sensor read failed; resetting...\n");
            if (reset_sensor(g_i2c_fd) < 0)
                fprintf(stderr, "Sensor reset failed\n");
            if (log_error(LOG_FILE) < 0)
                fprintf(stderr, "Failed to log error\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return 0;
}

