    crc_t = crc8(buf + 3, 2);
    if (crc_t != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch (calc=0x%02X, got=0x%02X)\n", crc_t, buf[5]);
        return -1;
    }

    raw_pressure = (buf[0] << 8) | buf[1];
    raw_temperature = (buf[3] << 8) | buf[4];

    *pressure = (float)raw_pressure / SCALE_FACTOR;
    return 0;
}

