#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* Configuration */
#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "flow_log.txt"

/* Sensor transfer function constants */
#define RAW_COUNTS_AT_0_SLPM 1638
#define RAW_COUNTS_AT_10_SLPM 14745
#define MAX_FLOW_RATE_SLPM 10.0

/* Global state */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int initialize(void);
static int read_sensor(int handle, uint16_t *raw_pressure);
static double convert_to_flow_rate(uint16_t raw_pressure);
static void set_fan_speed(double flow_rate);
static void log_data(double flow_rate);
static void signal_handler(int signal);
static void cleanup(void);

int main(void) {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Flow control system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t raw_pressure = 0;
        if (read_sensor(i2c_handle, &raw_pressure) != 0) {
            fprintf(stderr, "Error reading sensor data.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double flow_rate = convert_to_flow_rate(raw_pressure);
        set_fan_speed(flow_rate);
        log_data(flow_rate);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

static int initialize(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor(int handle, uint16_t *raw_pressure) {
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device: expected 2 bytes, got %d\n", bytes_read);
        return -1;
    }

    *raw_pressure = ((uint16_t)(buf[0] & 0x3F) << 8) | (uint16_t)buf[1];
    return 0;
}

static double convert_to_flow_rate(uint16_t raw_pressure) {
    double raw_counts = (double)raw_pressure;
    double flow_rate = (raw_counts - RAW_COUNTS_AT_0_SLPM) *
                       (MAX_FLOW_RATE_SLPM / (RAW_COUNTS_AT_10_SLPM - RAW_COUNTS_AT_0_SLPM));
    if (flow_rate < 0.0) flow_rate = 0.0;
    if (flow_rate > MAX_FLOW_RATE_SLPM) flow_rate = MAX_FLOW_RATE_SLPM;
    return flow_rate;
}

static void set_fan_speed(double flow_rate) {
    int pwm_value = (int)((flow_rate / MAX_FLOW_RATE_SLPM) * PWM_RANGE);
    if (pwm_value < 0) pwm_value = 0;
    if (pwm_value > PWM_RANGE) pwm_value = PWM_RANGE;
    gpioPWM(FAN_GPIO, pwm_value);
}

static void log_data(double flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

static void cleanup(void) {
    printf("\nCleaning up...\n");

    /* Turn off the fan */
    gpioPWM(FAN_GPIO, 0);

    /* Close I2C handle */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    /* Close log file */
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();
    printf("Cleanup complete.\n");
}

