#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LPS33HW_ADDR 0x5D
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0xB1
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error: reg 0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: reg 0x%02X, val 0x%02X, rc=%d\n", reg, val, rc);
        return -1;
    }
    return 0;
}

static int read_pressure(int handle, int32_t *pressure) {
    uint8_t xl, l, h;
    if (read_register(handle, PRESS_OUT_XL, &xl) < 0) return -1;
    if (read_register(handle, PRESS_OUT_L, &l) < 0) return -1;
    if (read_register(handle, PRESS_OUT_H, &h) < 0) return -1;
    int32_t raw = ((int32_t)h << 16) | ((int32_t)l << 8) | (int32_t)xl;
    if (raw & 0x800000) raw |= 0xFF000000;
    *pressure = raw;
    return 0;
}

