#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define LED_GPIO       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define POLL_DELAY_US  1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read temperature from STLM75.
 * Returns 0 on success and stores Celsius in *temp; returns -1 on error.
 */
static int read_temperature(float *temp)
{
    int raw = i2cReadWordData(g_i2c_handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "I2C read error (pigpio code %d)\n", raw);
        return -1;
    }

    /* pigpio returns bytes in little-endian order; swap them */
    uint16_t swapped = (uint16_t)(((raw & 0xFF00) >> 8) |
                                  ((raw & 0x00FF) << 8));

    /* Extract 9-bit value: bits 15..7 are the data, bits 6..0 are 0 */
    int16_t value = (int16_t)(swapped >> 7);

    /* Sign-extend from 9 bits to 16 bits */
    if (value & 0x0100) {
        value |= 0xFE00;
    }

    *temp = (float)value / 2.0f;
    return 0;
}

static void update_buffer(float new_temp, float *buffer, int *index)
{
    buffer[*index] = new_temp;
    *index = (*index + 1) % BUFFER_SIZE;
}

static float calculate_average(const float *buffer, int size)
{
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += buffer[i];
    }
    return sum / (float)size;
}

static void control_led(float average_temp)
{
    if (average_temp > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(void)
{
    float temperature_buffer[BUFFER_SIZE];
    int   buffer_index = 0;
    float average_temperature = 0.0f;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (pigpio code %d)\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature;

        if (read_temperature(&temperature) == 0) {
            update_buffer(temperature, temperature_buffer, &buffer_index);
            average_temperature = calculate_average(temperature_buffer, BUFFER_SIZE);
            control_led(average_temperature);
            printf("Temperature: %.2f C, Average: %.2f C\n",
                   temperature, average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature; skipping iteration.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

