#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD30_I2C_ADDR 0x61
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define MEASUREMENT_INTERVAL_SEC 2
#define CO2_THRESHOLD_LOW 800
#define CO2_THRESHOLD_HIGH 1200

/* SCD30 commands (16-bit, big-endian on the wire) */
#define CMD_START_CONT_MEAS 0x0010
#define CMD_STOP_CONT_MEAS 0x0104
#define CMD_READ_MEASUREMENT 0x0300
#define CMD_GET_DATA_READY 0x0202

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* CRC-8 for SCD30: polynomial 0x31, initial value 0xFF */
static uint8_t scd30_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int scd30_write_command(int handle, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int scd30_write_command_with_arg(int handle, uint16_t cmd, uint16_t arg) {
    uint8_t buf[5];
    buf[0] = (uint8_t)(cmd >> 8);
    buf[1] = (uint8_t)(cmd & 0xFF);
    buf[2] = (uint8_t)(arg >> 8);
    buf[3] = (uint8_t)(arg & 0xFF);
    buf[4] = scd30_crc8(&buf[2], 2);
    if (i2cWriteDevice(handle, (char *)buf, 5) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for command 0x%04X with arg 0x%04X\n", cmd, arg);
        return -1;
    }
    return 0;
}

static int scd30_read_data(int handle, uint8_t *data, size_t len) {
    if (i2cReadDevice(handle, (char *)data, len) != (int)len) {
        fprintf(stderr, "Error: i2cReadDevice failed (expected %zu bytes)\n", len);
        return -1;
    }
    return 0;
}

static int scd30_start_continuous_measurement(int handle) {
    if (scd30_write_command(handle, CMD_START_CONT_MEAS) != 0)
        return -1;
    /* 10 ms delay for command processing */
    gpioDelay(10000);
    return 0;
}

static int scd30_stop_continuous_measurement(int handle) {
    if (scd30_write_command(handle, CMD_STOP_CONT_MEAS) != 0)
        return -1;
    /* 10 ms delay for command processing */
    gpioDelay(10000);
    return 0;
}

static int scd30_is_data_ready(int handle) {
    if (scd30_write_command(handle, CMD_GET_DATA_READY) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms processing time */
    uint8_t data[3];
    if (scd30_read_data(handle, data, 3) != 0)
        return -1;
    if (scd30_crc8(data, 2) != data[2]) {
        fprintf(stderr, "Error: CRC mismatch on data-ready response\n");
        return -1;
    }
    uint16_t val = (uint16_t)((data[0] << 8) | data[1]);
    return (val == 1) ? 1 : 0;
}

static int scd30_read_measurement(int handle, float *co2, float *temperature, float *humidity) {
    if (scd30_write_command(handle, CMD_READ_MEASUREMENT) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms processing time */
    uint8_t data[18];
    if (scd30_read_data(handle, data, 18) != 0)
        return -1;

    /* Validate CRC for each 3-byte group (2 data + 1 CRC) */
    for (int i = 0; i < 6; i++) {
        if (scd30_crc8(&data[i * 3], 2) != data[i * 3 + 2]) {
            fprintf(stderr, "Error: CRC mismatch on measurement data group %d\n", i);
            return -1;
        }
    }

    uint16_t co2_raw = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t temp_raw = (uint16_t)((data[6] << 8) | data[7]);
    uint16_t hum_raw = (uint16_t)((data[12] << 8) | data[13]);

    *co2 = (float)co2_raw;
    *temperature = (float)temp_raw / 100.0f;
    *humidity = (float)hum_raw / 100.0f;

    return 0;
}

static void log_data(float co2, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: gmtime failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(g_log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(g_log_file);
}

static void control_ventilation(float co2) {
    if (co2 < CO2_THRESHOLD_LOW) {
        printf("CO2: %.2f ppm < %.0f ppm -> Ventilation: OFF\n", co2, CO2_THRESHOLD_LOW);
    } else if (co2 < CO2_THRESHOLD_HIGH) {
        printf("CO2: %.2f ppm >= %.0f ppm and < %.0f ppm -> Ventilation: LOW\n", co2, CO2_THRESHOLD_LOW, CO2_THRESHOLD_HIGH);
    } else {
        printf("CO2: %.2f ppm >= %.0f ppm -> Ventilation: HIGH\n", co2, CO2_THRESHOLD_HIGH);
    }
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        scd30_stop_continuous_measurement(g_i2c_handle);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SCD30_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). Sensor may be absent or bus unavailable.\n", g_i2c_handle);
        gpioTerminate();
        return 0; /* Graceful exit on sensor-absent */
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
