/*
 * SDP32 Differential Pressure Sensor Reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Build: gcc -Wall -Wextra -O2 -o sdp32_reader sdp32_reader.c -lpigpio -lrt
 * Run:   sudo ./sdp32_reader [sampling_interval_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SDP32_I2C_ADDR        0x21
#define SDP32_CMD_CONT_MEAS   0x362F  /* Continuous measurement, mass flow mode */
#define SDP32_READ_LEN        9       /* 3 words: pressure, temperature, scale factor */
#define SDP32_CRC_POLY        0x31
#define SDP32_CRC_INIT        0xFF
#define DEFAULT_INTERVAL_MS   1000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = SDP32_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ SDP32_CRC_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte SDP32 sample                                        */
/* Returns 0 on success, -1 on I2C error, -2 on CRC mismatch           */
/* ------------------------------------------------------------------ */
static int read_sdp32(int handle, float *pressure_pa)
{
    uint8_t cmd[2] = {
        (uint8_t)((SDP32_CMD_CONT_MEAS >> 8) & 0xFF),
        (uint8_t)(SDP32_CMD_CONT_MEAS & 0xFF)
    };
    uint8_t buf[SDP32_READ_LEN];

    /* Send continuous-measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to write continuous-measurement command to I2C device.\n");
        return -1;
    }

    /* SDP32 needs a short delay before first data is ready */
    gpioDelay(2000); /* 2 ms */

    /* Read 9 bytes: pressure(2)+crc, temp(2)+crc, scale(2)+crc */
    int bytes_read = i2cReadDevice(handle, (char *)buf, SDP32_READ_LEN);
    if (bytes_read != SDP32_READ_LEN) {
        fprintf(stderr, "Error: I2C read failed (got %d bytes, expected %d).\n",
                bytes_read, SDP32_READ_LEN);
        return -1;
    }

    /* Verify CRC for pressure word (bytes 0-1, CRC at byte 2) */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: pressure CRC mismatch.\n");
        return -2;
    }

    /* Verify CRC for temperature word (bytes 3-4, CRC at byte 5) */
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: temperature CRC mismatch.\n");
        return -2;
    }

    /* Verify CRC for scale-factor word (bytes 6-7, CRC at byte 8) */
    if (crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "Error: scale-factor CRC mismatch.\n");
        return -2;
    }

    /* Raw pressure is 16-bit signed, big-endian */
    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    /* Raw scale factor is 16-bit unsigned, big-endian */
    uint16_t scale_factor = (uint16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Error: scale factor is zero, cannot convert pressure.\n");
        return -1;
    }

    *pressure_pa = (float)raw_pressure / (float)scale_factor;
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int sampling_interval_ms = DEFAULT_INTERVAL_MS;

    if (argc > 1) {
        sampling_interval_ms = atoi(argv[1]);
        if (sampling_interval_ms <= 0) {
            fprintf(stderr, "Warning: invalid sampling interval '%s', using default %d ms.\n",
                    argv[1], DEFAULT_INTERVAL_MS);
            sampling_interval_ms = DEFAULT_INTERVAL_MS;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the SDP32 address */
    g_i2c_handle = i2cOpen(1, SDP32_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at address 0x%02X on bus 1 (code %d).\n",
                SDP32_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP32 Differential Pressure Reader\n");
    printf("I2C address: 0x%02X, sampling interval: %d ms\n", SDP32_I2C_ADDR, sampling_interval_ms);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main sampling loop */
    while (g_running) {
        float pressure_pa = 0.0f;
        int rc = read_sdp32(g_i2c_handle, &pressure_pa);

        if (rc == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Pressure: %.2f Pa\n", ts, pressure_pa);
        } else if (rc == -1) {
            fprintf(stderr, "Error: I2C communication failure. Check sensor wiring and address.\n");
        } else {
            fprintf(stderr, "Error: CRC mismatch on SDP32 data. Sensor may be disconnected.\n");
        }

        /* Sleep for the sampling interval, but wake early on signal */
        for (int i = 0; i < sampling_interval_ms / 100 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

