#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HDC1000_ADDR        0x40
#define HDC1000_TEMP_REG    0x00
#define HDC1000_CONFIG_REG  0x02
#define HDC1000_CONFIG_14BIT 0x1000  /* bit 12 = 1 -> 14-bit temp, 14-bit humidity */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }

    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int hdc1000_init(int fd)
{
    if (i2c_write_reg16(fd, HDC1000_CONFIG_REG, HDC1000_CONFIG_14BIT) != 0) {
        fprintf(stderr, "Failed to configure HDC1000 (sensor may be absent or bus error)\n");
        return -1;
    }
    return 0;
}

static int hdc1000_read(int fd, float *temperature, float *humidity)
{
    uint16_t raw_temp, raw_hum;

    if (i2c_read_reg16(fd, HDC1000_TEMP_REG, &raw_temp) != 0) {
        fprintf(stderr, "Failed to read temperature register\n");
        return -1;
    }

    if (i2c_read_reg16(fd, HDC1000_TEMP_REG + 2, &raw_hum) != 0) {
        fprintf(stderr, "Failed to read humidity register\n");
        return -1;
    }

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_hum  / 65536.0f) * 100.0f;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    float temperature, humidity;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                HDC1000_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (hdc1000_init(g_i2c_fd) != 0) {
        fprintf(stderr, "HDC1000 initialization failed. Check wiring and sensor presence.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    while (g_running) {
        if (hdc1000_read(g_i2c_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read temperature and humidity.\n");
        }

        /* Sleep 5 seconds, checking g_running every second for responsive shutdown */
        for (int i = 0; i < 5 && g_running; i++) {
            sleep(1);
        }
    }

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

