#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define MLX90833_ADDR 0x60
#define PRESSURE_REG 0x00
#define READ_INTERVAL_US 500000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_pressure(int handle, float *pressure) {
    char buf[2];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 2);
        if (result == 2) {
            uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            *pressure = (float)raw / 100.0f;
            return 0;
        }
        fprintf(stderr, "I2C read attempt %d failed (returned %d): %s\n",
                attempt + 1, result, strerror(errno));
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(10000);
        }
    }
    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X on bus %d (error %d)\n",
                MLX90833_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90833 pressure sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        float pressure;
        if (read_pressure(i2c_handle, &pressure) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Pressure: %.2f Pa\n", ts, pressure);
        } else {
            fprintf(stderr, "Failed to read pressure after %d attempts\n", MAX_RETRIES);
        }
        gpioDelay(READ_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

