#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ICP10101_ADDR 0x63
#define CMD_READ_CALIBRATION 0x50
#define CMD_READ_MEASUREMENT 0x40
#define MEASUREMENT_DELAY_US 7000
#define READ_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

static int read_calibration(int handle, uint16_t cal[4]) {
    char cmd = CMD_READ_CALIBRATION;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write calibration read command\n");
        return -1;
    }
    gpioDelay(10000);
    char buf[8];
    if (i2cReadDevice(handle, buf, 8) != 8) {
        fprintf(stderr, "Error: failed to read 8 bytes of calibration data\n");
        return -1;
    }
    for (int i = 0; i < 4; i++) {
        cal[i] = ((uint16_t)(uint8_t)buf[i * 2] << 8) | (uint8_t)buf[i * 2 + 1];
    }
    return 0;
}

static int read_measurement(int handle, uint16_t cal[4], float *temp, float *press) {
    char cmd = CMD_READ_MEASUREMENT;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write measurement command\n");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_US);
    char buf[6];
    if (i2cReadDevice(handle, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6 bytes of measurement data\n");
        return -1;
    }
    uint16_t raw_t = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint32_t raw_p = ((uint32_t)(uint8_t)buf[2] << 16) |
                     ((uint32_t)(uint8_t)buf[3] << 8) |
                     (uint8_t)buf[4];
    uint16_t raw_p2 = ((uint16_t)(uint8_t)buf[5] << 8) | (uint8_t)buf[6];

    if (raw_t == 0xFFFF || raw_p == 0xFFFFFFFF || raw_p2 == 0xFFFF) {
        fprintf(stderr, "Error: sensor returned invalid data (0x%04X 0x%08X 0x%04X)\n",
                raw_t, raw_p, raw_p2);
        return -1;
    }

    float t = (float)raw_t;
    float p = (float)raw_p;
    float p2 = (float)raw_p2;

    float t_comp = t - 273.15f;
    float p_comp = p * 0.01f;
    float p2_comp = p2 * 0.01f;

    float t_comp2 = t_comp * t_comp;
    float t_comp3 = t_comp2 * t_comp;

    float scale_factor_lut = 1.0f + (cal[0] * 0.0001f);
    float scale_factor_h = 1.0f + (cal[1] * 0.0001f);
    float scale_factor_p = 1.0f + (cal[2] * 0.0001f);
    float scale_factor_p2 = 1.0f + (cal[3] * 0.0001f);

    float t_comp_scaled = t_comp * scale_factor_lut;
    float t_comp2_scaled = t_comp2 * scale_factor_h;
    float t_comp3_scaled = t_comp3 * scale_factor_p;
    float t_comp4_scaled = t_comp2_scaled * scale_factor_p2;

    float t_comp_final = t_comp_scaled + t_comp2_scaled + t_comp3_scaled + t_comp4_scaled;
    float p_comp_final = p_comp + p2_comp;

    *temp = t_comp_final;
    *press = p_comp_final;
    return 0;
}

static void log_data(float temp, float press) {
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", ts, temp, press);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ICP10101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at bus %d addr 0x%02X\n",
                I2C_BUS, ICP10101_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t cal[4];
    if (read_calibration(g_i2c_handle, cal) != 0) {
        fprintf(stderr, "Error: cannot read calibration data — sensor may be absent\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICP-10101 sensor initialized. Logging every %d seconds. Press Ctrl+C to exit.\n",
           READ_INTERVAL_S);

    while (g_running) {
        float temp, press;
        if (read_measurement(g_i2c_handle, cal, &temp, &press) == 0) {
            log_data(temp, press);
        } else {
            fprintf(stderr, "Warning: measurement read failed, will retry next cycle\n");
        }
        sleep(READ_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

