#define SCALE_FACTOR 0.01f
#define MIN_PRESSURE 200.0f
#define MAX_PRESSURE 250.0f
#define LOG_FILE "pressure_log.csv"
#define POLL_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int open_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, pigpio_error(i2c_handle));
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (rc != 2) {
