            if (open_i2c() != 0) {
                fprintf(stderr, "Recovery failed, exiting.\n");
                break;
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    printf("Tire pressure monitoring stopped.\n");
    return EXIT_SUCCESS;
}

