#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576  /* 1 MB */
#define SAMPLE_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_US 40000   /* 40 ms */
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
            timestamp, temperature, humidity);

    if (ferror(fp)) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (ftell(fp) > LOG_FILE_SIZE_LIMIT) {
        fflush(fp);
        fclose(fp);
        remove(LOG_FILE);
        fp = fopen(LOG_FILE, "a");
        if (!fp) {
            perror("fopen log file after truncate");
            return -1;
        }
    } else {
        fflush(fp);
    }

    fclose(fp);
    return 0;
}

static int read_hih6130(int handle, float *temperature, float *humidity) {
    char cmd = 0x00;
    char buf[4];

    /* Trigger measurement: write 0x00 to the sensor */
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to trigger measurement\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    /* Read 4 bytes: [status, T_msb, T_lsb, H_msb] */
    if (i2cReadDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "Error: failed to read 4 bytes from sensor\n");
        return -1;
    }

    uint8_t status = (uint8_t)buf[0];
    uint16_t raw_temperature = ((uint16_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[2];
    uint16_t raw_humidity = ((uint16_t)(uint8_t)buf[3] << 8) | (uint8_t)buf[2];

    /* Validate status bits: bit 0 = busy, bit 1 = error */
    if (status & 0x03) {
        fprintf(stderr, "Error: sensor status indicates error or busy (0x%02X)\n", status);
        return -1;
    }

    /* Convert raw values to physical units */
    *temperature = (float)raw_temperature * 165.0f / 16383.0f - 40.0f;
    *humidity = (float)raw_humidity * 100.0f / 16383.0f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at 0x%02X on bus %d (code %d)\n",
                HIH6130_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("HIH6130 environmental monitor started. Logging to %s\n", LOG_FILE);

    while (running) {
        float temperature = 0.0f, humidity = 0.0f;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_hih6130(i2c_handle, &temperature, &humidity) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Warning: read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            gpioDelay(100000); /* 100 ms backoff before retry */
        }

        if (success) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: sensor read failed after %d attempts\n", MAX_RETRIES);
        }

        /* Sleep in 1-second increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Resources released. Goodbye.\n");
    return 0;
}

