#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define TICK_US 3
#define SYNC_TICKS 56
#define MIN_NIBBLE_TICKS 12
#define MAX_NIBBLE_TICKS 271
#define NIBBLES_PER_FRAME 5
#define TIMEOUT_US 100000
#define LOG_FILE "pressure_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sent_frame(int gpio, int *nibbles, int *status) {
    uint32_t start_tick, end_tick;
    int nibble_count = 0;
    int nibble = 0;
    int bit = 0;
    int timeout = 0;

    while (nibble_count < NIBBLES_PER_FRAME && running) {
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            gpioDelay(TICK_US);
            if (++timeout > TIMEOUT_US) return -1;
        }
        start_tick = gpioTick();

        timeout = 0;
        while (gpioRead(gpio) == 1) {
            gpioDelay(TICK_US);
            if (++timeout > TIMEOUT_US) return -1;
        }
        end_tick = gpioTick();

        int ticks = (int)(end_tick - start_tick);
        if (ticks < 0) ticks += 1000000;

        if (ticks >= MIN_NIBBLE_TICKS && ticks <= MAX_NIBBLE_TICKS) {
            nibble <<= 1;
            if (ticks > (MIN_NIBBLE_TICKS + MAX_NIBBLE_TICKS) / 2) nibble |= 1;
            bit++;
            if (bit == 4) {
                nibbles[nibble_count++] = nibble;
                nibble = 0;
                bit = 0;
            }
        } else {
            return -1;
