#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x01
#define EXPECTED_DEVICE_ID 0x0117
#define SAMPLE_INTERVAL_SEC 60
#define FILENAME "greenhouse_temps.dat"

static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_temperature(float *temp_out) {
    char buf[2];
    int rc;

    rc = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read error (reg 0x%02X): rc=%d, errno=%d (%s)\n",
                TEMP_REG, rc, errno, strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    *temp_out = (float)raw * 0.0078125f;
    return 0;
}

static int write_temperature_to_file(float temp) {
    if (fwrite(&temp, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "File write error: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    float temperature;
    time_t current_time;
    struct tm *time_info;
    char timestamp[32];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n",
                I2C_BUS, TMP117_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    int device_id = i2cReadWordData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Failed to read device ID register: %d\n", device_id);
        cleanup();
        return 1;
    }
    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Device ID mismatch: got 0x%04X, expected 0x%04X\n",
                device_id, EXPECTED_DEVICE_ID);
        cleanup();
        return 1;
    }

    fp = fopen(FILENAME, "ab");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file %s: %s\n", FILENAME, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Greenhouse monitoring started. Logging to %s every %d seconds.\n",
           FILENAME, SAMPLE_INTERVAL_SEC);

    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            current_time = time(NULL);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
            printf("[%s] Temperature: %.2f °C\n", timestamp, temperature);

            if (write_temperature_to_file(temperature) != 0) {
                fprintf(stderr, "Failed to write temperature to file.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying in %d seconds.\n",
                    SAMPLE_INTERVAL_SEC);
        }

        if (!terminate) {
            gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_SEC, 0);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

