#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHTC3_ADDR        0x70
#define SHTC3_CMD_MEASURE 0x7866  /* normal power, clock stretching disabled */
#define SHTC3_MEAS_MS     12      /* worst-case conversion time */
#define LOG_FILE          "shtc3_environment.log"
#define SAMPLE_INTERVAL   5       /* seconds */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t shtc3_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Read one SHTC3 sample ----
 * Returns 0 on success, -1 on I2C error, -2 on CRC error, -3 out-of-range. */
static int read_shtc3(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[2] = {
        (uint8_t)((SHTC3_CMD_MEASURE >> 8) & 0xFF),
        (uint8_t)(SHTC3_CMD_MEASURE & 0xFF)
    };
    uint8_t data[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (cmd 0x%04X)\n", SHTC3_CMD_MEASURE);
        return -1;
    }

    gpioDelay(SHTC3_MEAS_MS * 1000);  /* microseconds */

    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed (expected 6 bytes)\n");
        return -1;
    }

    /* CRC checks */
    if (shtc3_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -2;
    }
    if (shtc3_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch\n");
        return -2;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    float t = 175.0f * t_raw / 65535.0f - 45.0f;
    float h = 100.0f * h_raw / 65535.0f;

    if (t < -40.0f || t > 125.0f || h < 0.0f || h > 100.0f) {
        fprintf(stderr, "Error: out-of-range reading (T=%.2f, H=%.2f)\n", t, h);
        return -3;
    }

    *temperature = t;
    *humidity    = h;
    return 0;
}

/* ---- Log a reading to file and stdout ---- */
static void log_reading(float temperature, float humidity)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[24];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for append\n", LOG_FILE);
        return;
    }
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fclose(fp);

    printf("%s,%.2f,%.2f\n", ts, temperature, humidity);
    fflush(stdout);
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, SHTC3_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle %d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHTC3 monitoring started. Logging to %s every %d s. Ctrl+C to exit.\n",
           LOG_FILE, SAMPLE_INTERVAL);

    while (g_running) {
        float temperature, humidity;
        int rc = read_shtc3(g_i2c_handle, &temperature, &humidity);

        if (rc == 0) {
            log_reading(temperature, humidity);
        } else if (rc == -1) {
            fprintf(stderr, "Warning: I2C communication error, retrying...\n");
        } else if (rc == -2) {
            fprintf(stderr, "Warning: CRC error, retrying...\n");
        } else {
            fprintf(stderr, "Warning: out-of-range reading, retrying...\n");
        }

        /* Sleep in 1 s increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

