#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <errno.h>

#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */

/* Si7202 register addresses */
#define SI7202_REG_TEMP 0x00
#define SI7202_REG_FIELD 0x01
#define SI7202_REG_CONFIG 0x02

/* Configuration: continuous conversion, 100 Hz */
#define SI7202_CONFIG_VAL 0x00

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, SI7202_ADDR, pigpio_error(i2c_handle));
        return -1;
    }
    return 0;
}

static int configure_sensor(void) {
    /* Write configuration register to start continuous conversions */
    if (i2cWriteByteData(i2c_handle, SI7202_REG_CONFIG, SI7202_CONFIG_VAL) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", pigpio_error(i2c_handle));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int16_t *field_raw, int16_t *temp_raw) {
    int rc;

    rc = i2cReadWordData(i2c_handle, SI7202_REG_FIELD);
    if (rc < 0) {
        fprintf(stderr, "Error reading field register: %s\n", pigpio_error(rc));
        return -1;
    }
    *field_raw = (int16_t)rc;

    rc = i2cReadWordData(i2c_handle, SI7202_REG_TEMP);
    if (rc < 0) {
        fprintf(stderr, "Error reading temperature register: %s\n", pigpio_error(rc));
        return -1;
    }
    *temp_raw = (int16_t)rc;

    return 0;
}

static void convert_data(int16_t field_raw, int16_t temp_raw,
                         float *field_gauss, float *temp_celsius) {
    *field_gauss = (float)field_raw * 0.1f;
    *temp_celsius = (float)temp_raw * 0.01f - 25.0f;
}

static int log_data(float field_gauss, float temp_celsius) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, field_gauss, temp_celsius) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Magnetic Field (Gauss),Temperature (Celsius)\n");
        fflush(log_file);
    }

    printf("Si7202 rotational speed measurement started. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t field_raw, temp_raw;
        float field_gauss, temp_celsius;

        if (read_sensor_data(&field_raw, &temp_raw) == 0) {
            convert_data(field_raw, temp_raw, &field_gauss, &temp_celsius);
            if (log_data(field_gauss, temp_celsius) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed, logging NaN values...\n");
            if (log_data(NAN, NAN) != 0) {
                fprintf(stderr, "Logging failed for error entry, continuing...\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

