#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define LOG_FILE "dht11_readings.txt"
#define ERROR_LOG_FILE "dht11_errors.log"
#define SAMPLE_INTERVAL_US 2000000  /* 2 seconds */
#define MAX_RETRIES 3

/* DHT11 timing constants (microseconds) */
#define DHT11_START_LOW_US  18000
#define DHT11_START_HIGH_US 40
#define DHT11_RESP_LOW_US   80
#define DHT11_RESP_HIGH_US  80
#define DHT11_BIT_LOW_US    50
#define DHT11_BIT_THRESHOLD 50
#define DHT11_TIMEOUT_US    1000

typedef struct {
    float temperature;
    float humidity;
    int status;
} DHT11Data;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("fopen error log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error]: %s\n", message);
    }
    fclose(fp);
}

static void log_reading(float temp, float hum) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,%.1f,%.1f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temp, hum);
    } else {
        fprintf(fp, "[timestamp error],%.1f,%.1f\n", temp, hum);
    }
    fclose(fp);
}

/*
 * Bit-bang the DHT11 single-wire protocol.
 * Returns 0 on success, -1 on timeout, -2 on checksum error.
 */
static int read_dht11(DHT11Data *data) {
    memset(data, 0, sizeof(*data));

    /* --- Start signal: pull low for >= 18 ms, then release --- */
    if (gpioSetMode(DHT11_GPIO, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(DHT11_GPIO, 0) < 0) return -1;
    gpioDelay(DHT11_START_LOW_US);

    /* Release line: switch to input (internal pull-up keeps it high) */
    if (gpioSetMode(DHT11_GPIO, PI_INPUT) < 0) return -1;

    /* --- Sensor response: ~80 us low + ~80 us high --- */
    int elapsed = 0;
    while (gpioRead(DHT11_GPIO) == 1) {
        if (elapsed >= DHT11_TIMEOUT_US) return -1;
        gpioDelay(1);
        elapsed++;
    }
    elapsed = 0;
    while (gpioRead(DHT11_GPIO) == 0) {
        if (elapsed >= DHT11_TIMEOUT_US) return -1;
        gpioDelay(1);
        elapsed++;
    }
    elapsed = 0;
    while (gpioRead(DHT11_GPIO) == 1) {
        if (elapsed >= DHT11_TIMEOUT_US) return -1;
        gpioDelay(1);
        elapsed++;
    }

    /* --- Read 40 data bits --- */
    unsigned char data_bytes[5] = {0};
    for (int i = 0; i < 40; i++) {
        /* Each bit begins with a 50 us low pulse */
        elapsed = 0;
        while (gpioRead(DHT11_GPIO) == 0) {
            if (elapsed >= DHT11_TIMEOUT_US) return -1;
            gpioDelay(1);
            elapsed++;
        }
        /* Measure high-pulse duration to determine bit value */
        elapsed = 0;
        while (gpioRead(DHT11_GPIO) == 1) {
            if (elapsed >= DHT11_TIMEOUT_US) return -1;
            gpioDelay(1);
            elapsed++;
        }
        if (elapsed > DHT11_BIT_THRESHOLD) {
            data_bytes[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    /* --- Checksum validation --- */
    unsigned char checksum = (unsigned char)(data_bytes[0] + data_bytes[1] +
                                              data_bytes[2] + data_bytes[3]);
    if (checksum != data_bytes[4]) {
        return -2;
    }

    /* DHT11: humidity = data_bytes[0] (integer), data_bytes[1] (decimal) */
    data->humidity = (float)data_bytes[0];
    /* Temperature = data_bytes[2] (integer), data_bytes[3] (decimal) */
    data->temperature = (float)data_bytes[2];
    data->status = 0;
    return 0;
