    }

    DHT11Data dht11_data;
    int consecutive_errors = 0;

    while (running) {
        int result = read_dht11(&dht11_data);

        if (result == 0) {
            log_reading(dht11_data.temperature, dht11_data.humidity);
            consecutive_errors = 0;
        } else {
            const char *msg;
            if (result == -1) {
