#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ADPD105_ADDR_1 0x64
#define ADPD105_ADDR_2 0x65
#define ADPD105_REG_ID 0x00
#define ADPD105_REG_RED 0x64
#define ADPD105_REG_GREEN 0x66
#define ADPD105_REG_BLUE 0x68
#define ADPD105_EXPECTED_ID 0x2A
#define LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle_1 = -1;
static int i2c_handle_2 = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register16(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteI2CBlockData(handle, reg, NULL, 0) < 0) return -1;
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) return -1;
    *value = (uint16_t)((uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

static int read_sensor_data(int handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (read_register16(handle, ADPD105_REG_RED, red) < 0) return -1;
    if (read_register16(handle, ADPD105_REG_GREEN, green) < 0) return -1;
    if (read_register16(handle, ADPD105_REG_BLUE, blue) < 0) return -1;
    return 0;
}

static float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    float r = (float)red / 65535.0f;
    float g = (float)green / 65535.0f;
    float b = (float)blue / 65535.0f;
    float X = r * 0.664511f + g * 0.153623f + b * 0.168448f;
    float Y = r * 0.283820f + g * 0.669065f + b * 0.046115f;
    if (Y == 0.0f) return 0.0f;
    float Z = X / Y;
    float n = (X - Z) / (X + Z);
    float CCT = 449.0f * powf(n, 3.0f) + 3525.0f * powf(n, 2.0f) + 6823.3f * n + 5520.33f;
    return CCT;
}

static void log_cct(float cct) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_fp, "%s,%.2f\n", ts, cct);
    fflush(log_fp);
}

static void cleanup(void) {
    if (i2c_handle_1 >= 0) i2cClose(i2c_handle_1);
    if (i2c_handle_2 >= 0) i2cClose(i2c_handle_2);
    if (log_fp) fclose(log_fp);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle_1 = i2cOpen(1, ADPD105_ADDR_1, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Failed to open I2C device 1 at 0x%02X: %d\n", ADPD105_ADDR_1, i2c_handle_1);
        gpioTerminate();
        return 1;
