static int read_sensor_data(int handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (read_register16(handle, ADPD105_REG_RED, red) < 0) return -1;
    if (read_register16(handle, ADPD105_REG_GREEN, green) < 0) return -1;
    if (read_register16(handle, ADPD105_REG_BLUE, blue) < 0) return -1;
    return 0;
