/* Calibration parameters (example values) */
#define PRESSURE_OUTPUT_MIN 0
#define PRESSURE_OUTPUT_MAX 32768
#define PRESSURE_MIN_KPA 0.0
#define PRESSURE_MAX_KPA 800.0
#define TEMP_SCALE 0.01
#define TEMP_OFFSET -40.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
}

static void log_error(const char *msg) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
