    if (log_file) {
        fprintf(log_file, "%s ERROR: %s\n", ts, msg);
        fflush(log_file);
    }
}

static int read_register16(int handle, uint16_t reg, int16_t *out) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_pressure(int handle, float *pressure_kpa) {
    int16_t raw;
    if (read_register16(handle, PRESSURE_REG, &raw) != 0) {
        return -1;
    }
    *pressure_kpa = ((float)raw - PRESSURE_OUTPUT_MIN) *
                    (PRESSURE_MAX_KPA - PRESSURE_MIN_KPA) /
                    (float)(PRESSURE_OUTPUT_MAX - PRESSURE_OUTPUT_MIN) +
                    PRESSURE_MIN_KPA;
    return 0;
}

static int read_temperature(int handle, float *temp_c) {
    int16_t raw;
    if (read_register16(handle, TEMPERATURE_REG, &raw) != 0) {
        return -1;
    }
    *temp_c = raw * TEMP_SCALE + TEMP_OFFSET;
    return 0;
}

static void log_data(float pressure_kpa, float temp_c) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(log_file, "%s Pressure: %.2f kPa, Temperature: %.2f C\n",
            ts, pressure_kpa, temp_c);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n",
                MLX90824_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90824 PMS running. Press Ctrl+C to stop.\n");

    while (running) {
        float pressure_kpa, temp_c;

        if (read_pressure(i2c_handle, &pressure_kpa) != 0) {
            log_error("Failed to read pressure register");
        } else if (read_temperature(i2c_handle, &temp_c) != 0) {
            log_error("Failed to read temperature register");
        } else {
            log_data(pressure_kpa, temp_c);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

