#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LM75B_ADDR     0x48
#define TEMP_REG       0x00
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD_HIGH 28.0f
#define TEMP_THRESHOLD_LOW  26.0f
#define SAMPLE_PERIOD_US 1000000  /* 1 second */

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static int  g_pigpio_ready = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; do not call pigpio or close I2C    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio, I2C, and fan GPIO                                */
/* ------------------------------------------------------------------ */
static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    g_pigpio_ready = 1;

    g_i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d addr=0x%02X): %d\n",
                I2C_BUS, LM75B_ADDR, g_i2c_handle);
        gpioTerminate();
        g_pigpio_ready = 0;
        return -1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed.\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        g_pigpio_ready = 0;
        return -1;
    }

    if (gpioWrite(FAN_GPIO, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed.\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        g_pigpio_ready = 0;
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature from LM75B (0.5 °C resolution, 9-bit signed)       */
/* Returns 0 on success, -1 on I2C error.                              */
/* ------------------------------------------------------------------ */
static int read_temperature(float *temperature)
{
    char reg = (char)TEMP_REG;
    char data[2];
    int  result;

    /* Point to the temperature register */
    result = i2cWriteDevice(g_i2c_handle, &reg, 1);
    if (result < 0) {
        fprintf(stderr, "Error: i2cWriteDevice (reg select) failed: %d\n", result);
        return -1;
    }

    /* Read 2 bytes from the current register */
    result = i2cReadDevice(g_i2c_handle, data, 2);
    if (result < 0) {
        fprintf(stderr, "Error: i2cReadDevice failed: %d\n", result);
        return -1;
    }
    if (result != 2) {
        fprintf(stderr, "Error: short read: got %d bytes, expected 2\n", result);
        return -1;
    }

    /* LM75B: 9-bit two's-complement, bits D9-D1 = temperature, D0 = 0 */
    int16_t raw = (int16_t)(((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1]);
    raw >>= 1;                       /* arithmetic shift keeps sign */
    *temperature = (float)raw * 0.5f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Circular buffer operations                                         */
/* ------------------------------------------------------------------ */
static void buffer_add(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float buffer_average(const CircularBuffer *cb)
{
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* ------------------------------------------------------------------ */
/* Fan control with hysteresis                                        */
/* ------------------------------------------------------------------ */
static void control_fan(float average_temp)
{
    static int fan_on = 0;

    if (average_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON  (avg %.2f C)\n", average_temp);
        } else {
            fprintf(stderr, "Error: gpioWrite(%d, 1) failed.\n", FAN_GPIO);
        }
    } else if (average_temp < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (avg %.2f C)\n", average_temp);
        } else {
            fprintf(stderr, "Error: gpioWrite(%d, 0) failed.\n", FAN_GPIO);
        }
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup — safe to call from any exit path                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_pigpio_ready) {
        gpioWrite(FAN_GPIO, 0);
        if (g_i2c_handle >= 0) {
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
        }
        gpioTerminate();
        g_pigpio_ready = 0;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    CircularBuffer temp_buffer = {0};
    temp_buffer.head = 0;
    temp_buffer.count = 0;

    printf("LM75B fan controller started. Ctrl+C to exit.\n");

    while (g_running) {
        float temperature;

        if (read_temperature(&temperature) == 0) {
            buffer_add(&temp_buffer, temperature);
            float avg = buffer_average(&temp_buffer);
            printf("Temp: %.2f C  Avg: %.2f C\n", temperature, avg);
            control_fan(avg);
        } else {
            fprintf(stderr, "Warning: temperature read failed; retrying next cycle.\n");
        }

        /* Sleep 1 s in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

