        if (gpiod_line_set_value(led_line, led_state) < 0) {
            fprintf(stderr, "Failed to set LED GPIO value: %s\n",
                    strerror(errno));
            goto cleanup;
        }

        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip)
        gpiod_chip_close(chip);
    if (i2c_fd >= 0)
        close(i2c_fd);
    return ret;
}

