#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASUREMENT_CMD 0x362F
#define MEASUREMENT_DELAY_MS 45
#define LOG_FILE "flow_data.txt"
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", SDP800_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int send_measurement_command(void) {
    char cmd[2] = {(MEASUREMENT_CMD >> 8) & 0xFF, MEASUREMENT_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: expected 9 bytes, got %d\n", result);
        return -1;
    }
    return 0;
}

static int validate_crc(const uint8_t *data, int len) {
    uint8_t calculated_crc = crc8(data, len);
    if (calculated_crc != data[len]) {
        fprintf(stderr, "CRC mismatch: calculated 0x%02X, received 0x%02X\n", calculated_crc, data[len]);
        return -1;
    }
    return 0;
}

static int convert_data(const uint8_t *data, sensor_data_t *out) {
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t scale_factor = (data[6] << 8) | data[7];

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    out->differential_pressure = (float)raw_pressure / (float)scale_factor;
    out->temperature = (float)raw_temperature / 200.0f;

    return 0;
}

static int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->differential_pressure, data->temperature) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (initialize_i2c() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t data[9];
    sensor_data_t sensor_data;

    while (!terminate) {
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Measurement command failed, retrying...\n");
            gpioDelay(1000000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_MS * 1000);

        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Sensor read failed, retrying...\n");
            gpioDelay(1000000);
            continue;
        }

        if (validate_crc(data, 2) != 0) {
            fprintf(stderr, "Pressure CRC validation failed, retrying...\n");
            gpioDelay(1000000);
            continue;
        }

        if (validate_crc(data + 3, 2) != 0) {
            fprintf(stderr, "Temperature CRC validation failed, retrying...\n");
            gpioDelay(1000000);
            continue;
        }

        if (convert_data(data, &sensor_data) != 0) {
            fprintf(stderr, "Data conversion failed, retrying...\n");
            gpioDelay(1000000);
            continue;
        }

        if (log_data(&sensor_data) != 0) {
            fprintf(stderr, "Logging failed, retrying...\n");
            gpioDelay(1000000);
            continue;
        }

        printf("Differential Pressure: %.2f Pa, Temperature: %.2f C\n", sensor_data.differential_pressure, sensor_data.temperature);

        gpioDelay(1000000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

