#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define SAMPLE_PERIOD  60          /* seconds between readings */
#define MAX_RETRIES    3
#define MEASURE_DELAY  20000       /* microseconds (20 ms) */

/* Si7021 commands (no register addressing) */
#define CMD_MEASURE_RH_NO_HOLD  0xF5
#define CMD_MEASURE_TEMP_NO_HOLD 0xF3
#define CMD_READ_PREV_RH       0xE0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single command byte to the Si7021                          */
/* ------------------------------------------------------------------ */
static int si7021_write_cmd(int handle, uint8_t cmd)
{
    char buf[1] = { (char)cmd };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 1);
        if (rc == 0)
            return 0;
        fprintf(stderr, "[WARN] i2cWriteDevice(0x%02X) failed (attempt %d/%d): %d\n",
                cmd, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(10000);  /* 10 ms back-off */
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read 2 bytes from the Si7021 (no register addressing)               */
/* ------------------------------------------------------------------ */
static int si7021_read_2bytes(int handle, uint16_t *raw)
{
    char buf[2];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadDevice(handle, buf, 2);
        if (rc == 2) {
            *raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "[WARN] i2cReadDevice failed (attempt %d/%d): %d\n",
                attempt + 1, MAX_RETRIES, rc);
        gpioDelay(10000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read temperature (°C)                                              */
/* ------------------------------------------------------------------ */
static int read_temperature(int handle, float *temp_c)
{
    if (si7021_write_cmd(handle, CMD_MEASURE_TEMP_NO_HOLD) != 0)
        return -1;
    gpioDelay(MEASURE_DELAY);

    uint16_t raw;
    if (si7021_read_2bytes(handle, &raw) != 0)
        return -1;

    *temp_c = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read relative humidity (%%)                                        */
/* ------------------------------------------------------------------ */
static int read_humidity(int handle, float *rh)
{
    if (si7021_write_cmd(handle, CMD_MEASURE_RH_NO_HOLD) != 0)
        return -1;
    gpioDelay(MEASURE_DELAY);

    uint16_t raw;
    if (si7021_read_2bytes(handle, &raw) != 0)
        return -1;

    *rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (*rh < 0.0f)   *rh = 0.0f;
    if (*rh > 100.0f) *rh = 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature from the previous RH measurement (°C)              */
/* ------------------------------------------------------------------ */
static int read_previous_temperature(int handle, float *temp_c)
{
    if (si7021_write_cmd(handle, CMD_READ_PREV_RH) != 0)
        return -1;
    gpioDelay(MEASURE_DELAY);

    uint16_t raw;
    if (si7021_read_2bytes(handle, &raw) != 0)
        return -1;

    *temp_c = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a reading to file and stdout                                   */
/* ------------------------------------------------------------------ */
static void log_reading(float temp_c, float rh)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, rh);
        fclose(fp);
    } else {
        perror("[ERROR] fopen(" LOG_FILE ")");
    }

    printf("%s,%.2f,%.2f\n", ts, temp_c, rh);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Log an error to file and stderr                                    */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s,ERROR,%s\n", ts, msg);
        fclose(fp);
    } else {
        perror("[ERROR] fopen(" LOG_FILE ")");
    }

    fprintf(stderr, "%s,ERROR,%s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Validate sensor presence by reading the firmware revision          */
/* ------------------------------------------------------------------ */
static int validate_sensor(int handle)
{
    /* Issue a no-hold measure command for firmware revision */
    if (si7021_write_cmd(handle, CMD_MEASURE_RH_NO_HOLD) != 0)
        return -1;
    gpioDelay(MEASURE_DELAY);

    uint16_t raw;
    if (si7021_read_2bytes(handle, &raw) != 0)
        return -1;

    /* Firmware revision is the lower byte of the raw result */
    uint8_t fw = (uint8_t)(raw & 0xFF);
    if (fw == 0x00 || fw == 0xFF) {
        log_error("Sensor not responding (firmware revision 0x00 or 0xFF)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                     */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at Si7021 address 0x40 */
    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Validate sensor presence */
    if (validate_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] Si7021 not detected or unresponsive\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si7021 environment logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");
    fflush(stdout);

    /* Main sampling loop */
    while (g_running) {
        float temp_c, rh;

        if (read_temperature(g_i2c_handle, &temp_c) != 0) {
            log_error("Failed to read temperature");
        } else if (read_humidity(g_i2c_handle, &rh) != 0) {
            log_error("Failed to read humidity");
        } else {
            log_reading(temp_c, rh);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

