#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HDC1080_ADDR 0x40
#define TEMP_REG 0x00
#define CONFIG_REG 0x02
#define LOG_FILE "enviro_log.txt"
#define I2C_BUS 1
#define SAMPLE_INTERVAL_SEC 5

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_hdc1080(int handle) {
    /* Configure: 14-bit temp (0x10), 14-bit humidity (0x20), heater off (0x00) */
    uint8_t config = 0x10 | (0x20 << 4);
    if (i2cWriteByteData(handle, CONFIG_REG, config) < 0) {
        fprintf(stderr, "Error writing HDC1080 config register\n");
        return -1;
    }
    return 0;
}

static int read_hdc1080(int handle, float *temperature, float *humidity) {
    uint8_t buf[4];
    int result;

    /* Trigger a measurement by writing the pointer to register 0x00 */
    result = i2cWriteByte(handle, TEMP_REG);
    if (result < 0) {
        fprintf(stderr, "Error triggering HDC1080 measurement\n");
        return -1;
    }

    /* Wait for conversion to complete (14-bit temp + 14-bit humidity = ~16.4 ms max) */
    gpioDelay(20000); /* 20 ms */

    /* Read 4 bytes: 2 bytes temp, 2 bytes humidity */
    result = i2cReadDevice(handle, (char *)buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading HDC1080 data (got %d bytes)\n", result);
        return -1;
    }

    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    uint16_t raw_humidity = (buf[2] << 8) | buf[3];

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_humidity / 65536.0f) * 100.0f;

    return 0;
}

static int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, HDC1080_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_hdc1080(i2c_handle) < 0) {
        fprintf(stderr, "HDC1080 initialization failed (sensor may be absent)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;

    while (!terminate) {
        if (read_hdc1080(i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(LOG_FILE, temperature, humidity) == 0) {
                printf("Logged: %.2f C, %.2f %%\n", temperature, humidity);
            } else {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && !terminate; i++) {
            sleep(1);
        }
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

