#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_ADAPTER "/dev/i2c-1"
#define STS40_ADDR   0x44
#define LOG_FILE     "temperature_log.txt"
#define SAMPLE_MS    5000
#define CONV_MS      10

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;
static FILE *g_log = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int sts40_read_temp(int fd, float *temp) {
    uint8_t cmd[2] = {0x2C, 0xE0};
    uint8_t buf[3];

    if (write(fd, cmd, sizeof(cmd)) != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    usleep(CONV_MS * 1000);

    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read failed: got %zd bytes, expected 3: %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }

    uint16_t raw = (uint16_t)((buf[0] << 8) | buf[1]);
    *temp = -45.0f + (175.0f * (float)raw / 65535.0f);
    return 0;
}

static void log_temp(FILE *fp, float temp) {
    time_t now = time(NULL);
    struct tm tmv;
    char ts[32];
    localtime_r(&now, &tmv);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);
    fprintf(fp, "%s, %.2f\n", ts, temp);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    g_fd = open(I2C_ADAPTER, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_ADAPTER, strerror(errno));
        return 1;
    }

    if (ioctl(g_fd, I2C_SLAVE, STS40_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                STS40_ADDR, strerror(errno));
        close(g_fd);
        return 1;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_fd);
        return 1;
    }

    while (g_running) {
        float temp;
        if (sts40_read_temp(g_fd, &temp) == 0) {
            log_temp(g_log, temp);
        } else {
            fprintf(stderr, "Sensor read error; continuing.\n");
        }
        usleep(SAMPLE_MS * 1000);
    }

    if (g_log) fclose(g_log);
    if (g_fd >= 0) close(g_fd);
    printf("\nShutdown complete.\n");
    return 0;
}

