#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define DATA_FILE_PREFIX "scd40_data_"
#define DATA_FILE_SUFFIX ".csv"
#define MEASUREMENT_INTERVAL_SEC 5
#define LOGGING_INTERVAL_SEC 60
#define START_PERIODIC_CMD 0x21B1
#define STOP_PERIODIC_CMD 0x3F86
#define READ_MEASUREMENT_CMD 0xE000

typedef struct {
    time_t timestamp;
    unsigned int co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;
static circular_buffer_t buffer;
static pthread_t logging_thread;
static int logging_thread_created = 0;

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open error log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int send_command(int handle, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, (char *)buf, 2);
    if (result != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to send command 0x%04X: %d", command, result);
        log_error(msg);
        return -1;
    }
    return 0;
}

static int read_measurement(int handle, unsigned int *co2, float *temperature, float *humidity) {
    uint8_t buf[9];
    int result = i2cReadDevice(handle, (char *)buf, 9);
    if (result != 9) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to read measurement: expected 9 bytes, got %d", result);
        log_error(msg);
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        log_error("CO2 CRC mismatch");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        log_error("Temperature CRC mismatch");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        log_error("Humidity CRC mismatch");
        return -1;
    }

    *co2 = (buf[0] << 8) | buf[1];
    *temperature = -45.0f + 175.0f * ((float)((buf[3] << 8) | buf[4])) / 65535.0f;
    *humidity = 100.0f * ((float)((buf[6] << 8) | buf[7])) / 65535.0f;
    return 0;
}

static void buffer_init(circular_buffer_t *buf) {
    buf->head = 0;
    buf->count = 0;
    pthread_mutex_init(&buf->mutex, NULL);
}

static void buffer_add(circular_buffer_t *buf, sensor_data_t data) {
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
    pthread_mutex_unlock(&buf->mutex);
}

static void buffer_flush(circular_buffer_t *buf, const char *filename) {
    pthread_mutex_lock(&buf->mutex);
    int count = buf->count;
    int start = (buf->head - count + BUFFER_SIZE) % BUFFER_SIZE;
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        log_error("Failed to open data file for writing");
        pthread_mutex_unlock(&buf->mutex);
        return;
    }
    fprintf(fp, "timestamp,co2_ppm,temperature_c,humidity_pct\n");
    for (int i = 0; i < count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        struct tm tm = *localtime(&buf->data[idx].timestamp);
        char timestamp_str[64];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%u,%.2f,%.2f\n",
                timestamp_str, buf->data[idx].co2,
                buf->data[idx].temperature, buf->data[idx].humidity);
    }
    fclose(fp);
    pthread_mutex_unlock(&buf->mutex);
}

static void *logging_thread_func(void *arg) {
    (void)arg;
    time_t last_log_time = time(NULL);
    while (running) {
        sleep(LOGGING_INTERVAL_SEC);
        time_t now = time(NULL);
        if (difftime(now, last_log_time) >= LOGGING_INTERVAL_SEC) {
            char filename[256];
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            snprintf(filename, sizeof(filename), "%s/%s%04d%02d%02d_%02d%02d%02d%s",
                     LOG_DIR, DATA_FILE_PREFIX, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                     tm.tm_hour, tm.tm_min, tm.tm_sec, DATA_FILE_SUFFIX);
            buffer_flush(&buffer, filename);
            last_log_time = now;
        }
    }
    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (send_command(i2c_handle, START_PERIODIC_CMD) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    sleep(1);

    buffer_init(&buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (mkdir(LOG_DIR, 0755) != 0 && errno != EEXIST) {
        log_error("Failed to create log directory");
    }

    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        log_error("Failed to create logging thread");
        running = 0;
        pthread_join(logging_thread, NULL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    logging_thread_created = 1;

    while (running) {
        unsigned int co2;
        float temperature, humidity;
        if (read_measurement(i2c_handle, &co2, &temperature, &humidity) == 0) {
            sensor_data_t data;
            data.timestamp = time(NULL);
            data.co2 = co2;
            data.temperature = temperature;
            data.humidity = humidity;
            buffer_add(&buffer, data);
        } else {
            log_error("Failed to read measurement, skipping this cycle");
        }
        sleep(MEASUREMENT_INTERVAL_SEC);
    }

    running = 0;
    if (logging_thread_created) {
        pthread_join(logging_thread, NULL);
    }
    send_command(i2c_handle, STOP_PERIODIC_CMD);
    buffer_flush(&buffer, "final_data.csv");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

