#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD_MSB 0x36
#define MEASURE_CMD_LSB 0x2F
#define MEASUREMENT_DELAY_US 45000
#define LOG_FILE "sdp810_log.txt"
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sdp810(int handle, float *pressure, float *temperature) {
    uint8_t cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    uint8_t buf[9];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: I2C read failed\n");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on pressure data\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: CRC mismatch on temperature data\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: CRC mismatch on scale factor data\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Error: Invalid scale factor (0)\n");
        return -1;
    }

    *pressure = (float)raw_pressure * (float)scale_factor / 1000.0f;
    *temperature = -45.0f + 175.0f * (float)raw_temp / 65535.0f;

    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure, temperature);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    float pressure, temperature;
    while (!terminate) {
        if (read_sdp810(i2c_handle, &pressure, &temperature) == 0) {
            log_data(log_file, pressure, temperature);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping log entry\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();

    return 0;
}

