#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define ICP_10110_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define WHO_AM_I_VAL 0x08
#define CALIB_REG 0x05
#define MEAS_REG 0x00
#define DATA_REG 0x00
#define SAMPLE_INTERVAL_S 5
#define MEAS_DELAY_US 10000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_calibration(int handle, float *c0, float *c1, float *c2, float *c3) {
    uint8_t buf[8];
    if (i2cReadI2CBlockData(handle, CALIB_REG, (char *)buf, 8) != 8) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    uint16_t c0_raw = (buf[1] << 8) | buf[0];
    uint16_t c1_raw = (buf[3] << 8) | buf[2];
    uint16_t c2_raw = (buf[5] << 8) | buf[4];
    uint16_t c3_raw = (buf[7] << 8) | buf[6];
    *c0 = (float)c0_raw / 100.0f;
    *c1 = (float)c1_raw / 100.0f;
    *c2 = (float)c2_raw / 100.0f;
    *c3 = (float)c3_raw / 100.0f;
    return 0;
}

static int read_sensor_data(int handle, float *pressure, float *temperature) {
    if (i2cWriteByteData(handle, MEAS_REG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    uint8_t data[6];
    if (i2cReadI2CBlockData(handle, DATA_REG, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read sensor data\n");
        return -1;
    }

    uint16_t raw_p = (data[1] << 8) | data[0];
    uint16_t raw_t = (data[3] << 8) | data[2];

    float c0 = 0.0f, c1 = 0.0f, c2 = 0.0f, c3 = 0.0f;
    if (read_calibration(handle, &c0, &c1, &c2, &c3) != 0) {
        return -1;
    }

    float p = c0 + c1 * raw_p + c2 * raw_t + c3 * raw_p * raw_t;
    *pressure = p;
    *temperature = (float)raw_t / 100.0f;
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f hPa, %.2f C\n", timestamp, pressure, temperature);
    fflush(fp);
    printf("%s, %.2f hPa, %.2f C\n", timestamp, pressure, temperature);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICP_10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", ICP_10110_ADDR);
        gpioTerminate();
        return 1;
    }

    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n", who_am_i, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open environmental_data.txt\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    float pressure, temperature;
    while (program_running) {
        if (read_sensor_data(i2c_handle, &pressure, &temperature) == 0) {
            log_data(log_file, pressure, temperature);
        } else {
            fprintf(stderr, "Warning: Skipping sample due to read error\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

