#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x63
#define LED_GPIO       17
#define ALTITUDE_THRESHOLD 95000.0f
#define POLL_INTERVAL  1
#define MEAS_DELAY_MS  20
#define LED_NORMAL_HZ  1
#define LED_WARN_HZ    5

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/* CRC-8 polynomial 0x31, init 0x00 (InvenSense convention) */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write16 to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_n(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_calibration(int fd, uint16_t cal[4]) {
    uint8_t buf[8];
    if (i2c_read_n(fd, 0x66, buf, 8) < 0)
        return -1;
    for (int i = 0; i < 4; i++) {
        if (crc8(&buf[i * 2], 2) != buf[i * 2 + 2]) {
            fprintf(stderr, "Calibration CRC mismatch at index %d\n", i);
            return -1;
        }
        cal[i] = (uint16_t)((buf[i * 2] << 8) | buf[i * 2 + 1]);
    }
    return 0;
}

static int read_sensor(int fd, const uint16_t cal[4], float *pressure, float *temperature) {
    if (i2c_write16(fd, 0x40, 0x11) < 0)
        return -1;
    usleep(MEAS_DELAY_MS * 1000);

    uint8_t buf[6];
    if (i2c_read_n(fd, 0x00, buf, 6) < 0)
        return -1;

    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 2], 2) != buf[i * 2 + 2]) {
            fprintf(stderr, "CRC mismatch on data word %d\n", i);
            return -1;
        }
    }

    uint32_t raw_p = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    uint32_t raw_t = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | buf[5];

    float p_comp = (float)raw_p - 32768.0f;
    float t_comp = (float)raw_t - 32768.0f;

    float p = (float)cal[0] + p_comp * (float)cal[1] / 65536.0f;
    float t = (float)cal[2] + t_comp * (float)cal[3] / 65536.0f;

    *pressure = p;
    *temperature = t;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_BUS);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    uint16_t cal[4];
    if (read_calibration(i2c_fd, cal) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
