#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define HTTP_PORT 8080
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 15000

static int i2c_handle = -1;
static int server_fd = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sht40(int handle, float *temperature, float *humidity) {
    char cmd = MEASURE_CMD;
    char buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, &cmd, 1) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            usleep(10000);
            continue;
        }

        usleep(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(handle, buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            usleep(10000);
            continue;
        }

        unsigned int raw_t = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
        unsigned int raw_h = ((unsigned char)buf[3] << 8) | (unsigned char)buf[4];

        *temperature = -45.0f + 175.0f * ((float)raw_t / 65535.0f);
        *humidity = -6.0f + 125.0f * ((float)raw_h / 65535.0f);

        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    fprintf(stderr, "SHT40 read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);

    if (bytes_received < 0) {
        perror("recv failed");
        return;
    }

    if (bytes_received == 0) {
        printf("Client disconnected\n");
        return;
    }

    buffer[bytes_received] = '\0';
    printf("Received: %s\n", buffer);

    float temperature, humidity;
    if (read_sht40(i2c_handle, &temperature, &humidity) != 0) {
        const char *error_response = "HTTP/1.1 500 Internal Server Error\r\n"
                                     "Content-Type: text/html\r\n"
                                     "Connection: close\r\n"
                                     "\r\n"
                                     "<html><body><h1>Server Error</h1></body></html>";
        send(client_socket, error_response, strlen(error_response), 0);
        close(client_socket);
        return;
    }

    char response[256];
    snprintf(response, sizeof(response),
             "HTTP/1.1 200 OK\r\n"
             "Content-Type: text/html\r\n"
             "Connection: close\r\n"
             "\r\n"
             "<html><body>"
             "<h1>Temperature: %.2f &deg;C</h1>"
             "<h1>Humidity: %.2f %%</h1>"
             "</body></html>",
             temperature, humidity);

    send(client_socket, response, strlen(response), 0);
    close(client_socket);
}

static int setup_server(int port) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket failed");
        return -1;
    }

    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(fd);
        return -1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);

    if (bind(fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(fd);
        return -1;
    }

    if (listen(fd, 3) < 0) {
        perror("listen failed");
        close(fd);
        return -1;
    }

    printf("Server listening on port %d\n", port);
    return fd;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n", SHT40_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    server_fd = setup_server(HTTP_PORT);
    if (server_fd < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting HTTP server...\n");

    while (!terminate) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);

        if (client_socket < 0) {
            if (errno == EINTR && terminate) break;
            perror("accept failed");
            continue;
        }

        handle_client(client_socket);
    }

    printf("\nShutting down...\n");
    if (server_fd >= 0) close(server_fd);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

