#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define HDC2010_ADDR        0x40
#define REG_TEMP_LOW        0x00
#define REG_TEMP_HIGH       0x01
#define REG_HUM_LOW         0x02
#define REG_HUM_HIGH        0x03
#define REG_MEASUREMENT_CONFIG 0x0E
#define REG_CONFIG          0x0F

#define MEASUREMENT_CONFIG_TRIGGER 0x01
#define CONFIG_HEATER_DISABLE      0x00
#define CONFIG_RESOLUTION_14BIT    0x00

#define I2C_BUS             1
#define MAX_RETRIES         3
#define POLL_TIMEOUT_MS     500
#define POLL_DELAY_US       1000
#define SAMPLE_INTERVAL_S   5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "i2cReadWordData(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

static int hdc2010_trigger_measurement(int handle) {
    if (i2c_write_byte(handle, REG_MEASUREMENT_CONFIG,
                       MEASUREMENT_CONFIG_TRIGGER) < 0) {
        return -1;
    }
    return 0;
}

static int hdc2010_wait_for_measurement(int handle) {
    uint16_t cfg;
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (i2c_read_word(handle, REG_MEASUREMENT_CONFIG, &cfg) < 0) {
            return -1;
        }
        if ((cfg & 0x01) == 0) {
            return 0;
        }
        gpioDelay(POLL_DELAY_US);
    }
    fprintf(stderr, "HDC2010 measurement timeout\n");
    return -1;
}

static int hdc2010_read_temperature(int handle, float *temp) {
    uint16_t raw;
    if (i2c_read_word(handle, REG_TEMP_LOW, &raw) < 0) {
        return -1;
    }
    *temp = ((float)raw / 65536.0f) * 165.0f - 40.0f;
    return 0;
}

static int hdc2010_read_humidity(int handle, float *hum) {
    uint16_t raw;
    if (i2c_read_word(handle, REG_HUM_LOW, &raw) < 0) {
        return -1;
    }
    *hum = ((float)raw / 65536.0f) * 100.0f;
    return 0;
}

static int hdc2010_init(int handle) {
    if (i2c_write_byte(handle, REG_CONFIG,
                       CONFIG_HEATER_DISABLE | CONFIG_RESOLUTION_14BIT) < 0) {
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, HDC2010_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, HDC2010_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (hdc2010_init(g_i2c_handle) < 0) {
        fprintf(stderr, "HDC2010 init failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && g_running) {
            if (hdc2010_trigger_measurement(g_i2c_handle) < 0) {
                retries++;
                continue;
            }
            if (hdc2010_wait_for_measurement(g_i2c_handle) < 0) {
                retries++;
                continue;
            }
            float temp, hum;
            if (hdc2010_read_temperature(g_i2c_handle, &temp) < 0 ||
                hdc2010_read_humidity(g_i2c_handle, &hum) < 0) {
                retries++;
                continue;
            }
            success = 1;
            break;
        }

        if (success) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read sensor after %d retries\n", MAX_RETRIES);
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

