#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define GPIO_CHIP "gpiochip0"
#define RELAY_PIN 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;

static float Kp = 1.0, Ki = 0.1, Kd = 0.01;
static float integral = 0.0, prev_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI");
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return -1;
    }
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip); chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(relay_line, "reflow_oven", 0) < 0) {
        perror("gpiod_line_request_output");
        relay_line = NULL;
        gpiod_chip_close(chip); chip = NULL;
        return -1;
    }
    return 0;
}

static int read_thermocouple(float *temp) {
    uint8_t tx[2] = {0x00, 0x00};
    uint8_t rx[2] = {0, 0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }
    uint16_t raw = ((uint16_t)rx[0] << 8) | rx[1];
    if (raw & 0x0004) {
        fprintf(stderr, "MAX6675: open circuit\n");
        return -1;
    }
    *temp = ((float)((raw >> 3) & 0x0FFF)) / 4.0f;
    return 0;
}

static float pid_control(float target, float current) {
    float error = target - current;
    integral += error;
    float derivative = error - prev_error;
    float output = Kp * error + Ki * integral + Kd * derivative;
    prev_error = error;
    if (output < 0.0f) output = 0.0f;
    if (output > 1.0f) output = 1.0f;
    return output;
}

static int set_relay(float duty) {
    int val = (duty > 0.5f) ? 1 : 0;
    if (gpiod_line_set_value(relay_line, val) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static int log_data(float temp, float duty) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, duty);
    fclose(fp);
    return 0;
}

static int read_profile(float *temps, int *times, int max_points) {
    FILE *fp = fopen(PROFILE_FILE, "r");
    if (!fp) {
        perror("fopen profile");
        return -1;
    }
    int count = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp) && count < max_points) {
        if (sscanf(line, "%d,%f", &times[count], &temps[count]) == 2) {
            count++;
        }
    }
    fclose(fp);
    return count;
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    if (spi_init() < 0) return 1;
    if (gpio_init() < 0) { close(spi_fd); return 1; }
    float temps[100], times[100];
    int n = read_profile(temps, times, sizeof(temps) / sizeof(temps[0]));
    if (n <= 0) {
        fprintf(stderr, "No valid profile points. Exiting.\n");
        cleanup();
        return 1;
    }
    printf("Profile loaded: %d points\n", n);
    int i = 0;
    while (running && i < n) {
        float target = temps[i];
        float current = 0.0f;
        int elapsed = 0;
        while (running && elapsed < times[i] && i < n) {
            if (read_thermocouple(&current) < 0) {
                fprintf(stderr, "Thermocouple read error, retrying...\n");
                sleep(1);
                continue;
            }
            float duty = pid_control(target, current);
            if (set_relay(duty) < 0) {
                fprintf(stderr, "Relay control error\n");
            }
            if (log_data(current, duty) < 0) {
                fprintf(stderr, "Logging error\n");
            }
            sleep(1);
            elapsed++;
        }
        i++;
    }
    cleanup();
    printf("Program finished.\n");
    return 0;
}

