#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <gpiod.h>

#define HEATER_ENABLE_PIN 17
#define HEATER_PWM_PIN 18
#define SENSOR_PATH "/sys/bus/w1/devices/"
#define LOG_FILE "greenhouse.log"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *enable_line = NULL;
static struct gpiod_line *pwm_line = NULL;

static double Kp, Ki, Kd;
static double integral = 0.0;
static double previous_error = 0.0;
static double setpoint = 50.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(double temperature, double setpoint, double pid_output, int pwm_duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Temperature: %.2f, Setpoint: %.2f, PID Output: %.2f, PWM Duty Cycle: %d\n",
            timestamp, temperature, setpoint, pid_output, pwm_duty_cycle);
    fflush(log_file);
}

static double calculate_pid(double temperature) {
    double error = setpoint - temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    return output;
}

static int set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    int ret = gpiod_line_set_value(pwm_line, duty_cycle > 0 ? 1 : 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set PWM line value: %s\n", strerror(errno));
        return -1;
    }
    return duty_cycle;
}

static int read_temperature(void) {
    DIR *dir = opendir(SENSOR_PATH);
    if (!dir) {
