#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38
#define GPIO_CHIP      "gpiochip4"
#define GPIO_LINE      17
#define HUMIDITY_HIGH  60.0f
#define HUMIDITY_LOW   55.0f
#define POLL_INTERVAL  5
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 10
#define MEAS_DELAY_MS  80

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd1, uint8_t cmd2, uint8_t cmd3) {
    uint8_t buf[3] = {cmd1, cmd2, cmd3};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 3) == 3) return 0;
        fprintf(stderr, "I2C write failed (attempt %d): %s\n", attempt + 1, strerror(errno));
        if (attempt < MAX_RETRIES - 1) usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        ssize_t n = read(fd, buf, len);
        if (n == (ssize_t)len) return 0;
        fprintf(stderr, "I2C read failed (attempt %d): got %zd of %zu (%s)\n",
                attempt + 1, n, len, strerror(errno));
        if (attempt < MAX_RETRIES - 1) usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int aht20_init(int fd) {
    if (i2c_write_cmd(fd, 0xBE, 0x08, 0x00) != 0) {
        fprintf(stderr, "AHT20 init failed: sensor may be absent or bus error\n");
        return -1;
    }
    usleep(10000);
    return 0;
}

static int aht20_read(int fd, float *humidity) {
    if (i2c_write_cmd(fd, 0xAC, 0x33, 0x00) != 0) return -1;
    usleep(MEAS_DELAY_MS * 1000);

    uint8_t buf[6];
    if (i2c_read_bytes(fd, buf, 6) != 0) return -1;

    uint8_t status = buf[0];
    if (status & 0x08) {
        fprintf(stderr, "AHT20 busy or not calibrated (status=0x%02X)\n", status);
        return -1;
    }
    if (status & 0x03) {
        fprintf(stderr, "AHT20 warning bits set (status=0x%02X)\n", status);
    }

    uint32_t raw = ((uint32_t)buf[1] << 12) |
                   ((uint32_t)buf[2] << 4)  |
                   ((uint32_t)buf[3] >> 4);
    *humidity = (float)raw / 1048576.0f * 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (aht20_init(i2c_fd) != 0) {
        fprintf(stderr, "AHT20 initialization failed. Continuing to poll.\n");
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line *relay = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!relay) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(relay, "dehumidifier", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    int relay_state = 0;

    while (running) {
        float humidity;
        if (aht20_read(i2c_fd, &humidity) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Humidity: %.2f%%\n", ts, humidity);

            if (humidity > HUMIDITY_HIGH && relay_state == 0) {
                if (gpiod_line_set_value(relay, 1) == 0) {
                    relay_state = 1;
                    printf("[%s] Dehumidifier ON\n", ts);
                } else {
                    fprintf(stderr, "[%s] Failed to set relay HIGH: %s\n",
                            ts, strerror(errno));
                }
            } else if (humidity < HUMIDITY_LOW && relay_state == 1) {
                if (gpiod_line_set_value(relay, 0) == 0) {
                    relay_state = 0;
                    printf("[%s] Dehumidifier OFF\n", ts);
                } else {
                    fprintf(stderr, "[%s] Failed to set relay LOW: %s\n",
                            ts, strerror(errno));
                }
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing to poll.\n");
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    gpiod_line_set_value(relay, 0);
    gpiod_line_release(relay);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

