#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <syslog.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HTU21D_ADDR    0x40
#define API_URL        "http://api.example.com/humidity"
#define READ_INTERVAL  60
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_sock_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, unsigned char reg, unsigned short *out) {
    unsigned char buf[3];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 3) != 3) return -1;
    unsigned short raw = ((unsigned short)buf[0] << 8) | buf[1];
    unsigned char crc = (unsigned char)(raw & 0x00FF);
    unsigned char poly = 0x31, b = (raw >> 8) & 0x00FF;
    for (int i = 0; i < 8; i++) {
        if (crc & 0x80) crc = (crc << 1) ^ poly;
        else crc <<= 1;
    }
    if (crc != buf[2]) return -2;
    *out = raw;
    return 0;
}

static int read_humidity(int fd, float *humidity) {
    unsigned short raw;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg16(fd, 0xE5, &raw) == 0) {
            *humidity = -6.0f + 125.0f * (float)raw / 65536.0f;
            if (*humidity < 0.0f) *humidity = 0.0f;
            if (*humidity > 100.0f) *humidity = 100.0f;
            return 0;
        }
        syslog(LOG_WARNING, "HTU21D read attempt %d failed: %s", attempt + 1, strerror(errno));
        sleep(1);
    }
    return -1;
}

static int http_post(const char *url, const char *json) {
    struct sockaddr_in addr;
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) { syslog(LOG_ERR, "socket: %s", strerror(errno)); return -1; }
    g_sock_fd = sock;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(80);
    if (inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "inet_pton: %s", strerror(errno)); close(sock); return -1;
    }
    if (connect(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        syslog(LOG_ERR, "connect: %s", strerror(errno)); close(sock); return -1;
    }
    char req[512];
    int len = snprintf(req, sizeof(req), "POST %s HTTP/1.1\r\n"
                        "Host: %s\r\n"
                        "Content-Type: application/json\r\n"
                        "Content-Length: %zu\r\n"
                        "Connection: close\r\n"
                        "\r\n%s",
                        url, url, strlen(json), json);
    if (len < 0 || len >= (int)sizeof(req)) { close(sock); return -1; }
    if (write(sock, req, len) != len) { syslog(LOG_ERR, "write: %s", strerror(errno)); close(sock); return -1; }
    char resp[1024];
    ssize_t n = read(sock, resp, sizeof(resp) - 1);
    if (n < 0) { syslog(LOG_ERR, "read: %s", strerror(errno)); close(sock); return -1; }
    resp[n] = '\0';
    close(sock);
    g_sock_fd = -1;
    if (strstr(resp, "200 OK") == NULL) { syslog(LOG_ERR, "HTTP error: %s", resp); return -1; }
    return 0;
}

int main(void) {
    openlog("htu21d_monitor", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa = { .sa_handler = signal_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) { syslog(LOG_ERR, "open %s: %s", I2C_BUS, strerror(errno)); closelog(); return 1; }
    if (ioctl(g_i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "ioctl I2C_SLAVE 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(g_i2c_fd); closelog(); return 1;
    }
    syslog(LOG_INFO, "HTU21D monitor started on %s @ 0x%02X", I2C_BUS, HTU21D_ADDR);
    while (g_running) {
        float humidity;
        if (read_humidity(g_i2c_fd, &humidity) == 0) {
            char json[64];
            snprintf(json, sizeof(json), "{\"humidity\":%.2f}", humidity);
            if (http_post(API_URL, json) == 0) {
                syslog(LOG_INFO, "Posted: %s", json);
            } else {
                syslog(LOG_ERR, "HTTP POST failed");
            }
        } else {
            syslog(LOG_ERR, "HTU21D read failed after %d attempts", MAX_RETRIES);
        }
        for (int i = 0; i < READ_INTERVAL && g_running; i++) sleep(1);
    }
    syslog(LOG_INFO, "Shutting down");
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    if (g_sock_fd >= 0) close(g_sock_fd);
    closelog();
    return 0;
}

