#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_STATUS 0xF3
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB 0x88
#define BMP280_CHIP_ID 0x58
#define PRESSURE_HIGH_THRESHOLD 1020.0
#define PRESSURE_LOW_THRESHOLD 980.0
#define SAMPLE_INTERVAL_US 2000000
#define CONVERSION_WAIT_US 10000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static bmp280_calib_data calib;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C read error: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: reg=0x%02X, val=0x%02X, rc=%d\n", reg, val, rc);
        return -1;
    }
    return 0;
}

static int read_calibration_data(int handle) {
    uint8_t data[24];
    if (i2c_read_block(handle, BMP280_REG_CALIB, data, 24) != 0) {
        return -1;
    }
    calib.dig_T1 = (uint16_t)(data[0] | (data[1] << 8));
    calib.dig_T2 = (int16_t)(data[2] | (data[3] << 8));
    calib.dig_T3 = (int16_t)(data[4] | (data[5] << 8));
    calib.dig_P1 = (uint16_t)(data[6] | (data[7] << 8));
    calib.dig_P2 = (int16_t)(data[8] | (data[9] << 8));
    calib.dig_P3 = (int16_t)(data[10] | (data[11] << 8));
    calib.dig_P4 = (int16_t)(data[12] | (data[13] << 8));
    calib.dig_P5 = (int16_t)(data[14] | (data[15] << 8));
    calib.dig_P6 = (int16_t)(data[16] | (data[17] << 8));
    calib.dig_P7 = (int16_t)(data[18] | (data[19] << 8));
    calib.dig_P8 = (int16_t)(data[20] | (data[21] << 8));
    calib.dig_P9 = (int16_t)(data[22] | (data[23] << 8));
    return 0;
}

static int32_t compensate_temperature(int32_t adc_T) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)calib.dig_T1 << 1))) * ((int32_t)calib.dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)calib.dig_T1)) * ((adc_T >> 4) - ((int32_t)calib.dig_T1))) >> 12) * ((int32_t)calib.dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t adc_P) {
    int32_t var1, var2;
    uint32_t p;
    var1 = ((int32_t)t_fine >> 1) - 64000;
    var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * ((int32_t)calib.dig_P6);
    var2 = var2 + ((var1 * ((int32_t)calib.dig_P5)) << 1);
    var2 = (var2 >> 2) + (((int32_t)calib.dig_P4) << 16);
    var1 = (((calib.dig_P3 * (((var1 >> 2) * (var1 >> 2)) >> 13)) >> 3) + ((((int32_t)calib.dig_P2) * var1) >> 1)) >> 18;
    var1 = ((((32768 + var1)) * ((int32_t)calib.dig_P1)) >> 15);
    if (var1 == 0) return 0;
    p = (((uint32_t)(((1048576) - adc_P) - (var2 >> 12))) << 12) / (uint32_t)var1;
    var1 = (((int32_t)calib.dig_P9) * ((int32_t)(((p >> 3) * (p >> 3)) >> 13))) >> 12;
    var2 = (((int32_t)(p >> 2)) * ((int32_t)calib.dig_P8)) >> 13;
    p = (uint32_t)((int32_t)p + ((var1 + var2 + calib.dig_P7) >> 4));
    return p;
}

static int read_raw_data(int handle, int32_t *raw_P, int32_t *raw_T) {
    uint8_t data[6];
    if (i2c_read_block(handle, BMP280_REG_PRESS_MSB, data, 6) != 0) {
        return -1;
    }
    *raw_P = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *raw_T = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);
    return 0;
}

static int32_t read_bmp280(int32_t *raw_P, int32_t *raw_T) {
    if (i2c_write_byte(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) {
        return -1;
    }
    gpioDelay(CONVERSION_WAIT_US);
    if (read_raw_data(i2c_handle, raw_P, raw_T) != 0) {
        return -1;
    }
    int32_t temp = compensate_temperature(*raw_T);
    (void)temp;
    uint32_t press = compensate_pressure(*raw_P);
    return (int32_t)press;
}

static void log_pressure_breach(float pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) {
        perror("Error opening pressure_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Pressure: %.2f hPa\n", timestamp, pressure);
    fclose(fp);
}

static int init_bmp280(void) {
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n", BMP280_I2C_ADDR, i2c_handle);
        return -1;
    }
    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_CHIP_ID);
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: expected 0x%02X, got 0x%02X\n", BMP280_CHIP_ID, chip_id);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    if (read_calibration_data(i2c_handle) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    if (i2c_write_byte(i2c_handle, BMP280_REG_CONFIG, 0x00) != 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (init_bmp280() != 0) {
        fprintf(stderr, "BMP280 initialisation failed\n");
        cleanup();
        return 1;
    }
    printf("BMP280 initialised successfully. Monitoring pressure...\n");
    while (!terminate) {
        int32_t raw_P, raw_T;
        int retries = 0;
        int success = 0;
        while (retries < MAX_RETRIES && !terminate) {
            int32_t press = read_bmp280(&raw_P, &raw_T);
            if (press >= 0) {
                float pressure = (float)press / 100.0f;
                if (pressure > PRESSURE_HIGH_THRESHOLD || pressure < PRESSURE_LOW_THRESHOLD) {
                    log_pressure_breach(pressure);
                }
                success = 1;
                break;
            }
            retries++;
            fprintf(stderr, "Read attempt %d failed, retrying...\n", retries);
            gpioDelay(100000);
        }
        if (!success) {
            fprintf(stderr, "Failed to read BMP280 after %d retries, re-initialising...\n", MAX_RETRIES);
            i2cClose(i2c_handle);
            i2c_handle = -1;
            if (init_bmp280() != 0) {
                fprintf(stderr, "Re-initialisation failed, exiting\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

