    }
    *raw_P = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *raw_T = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);
    return 0;
}

static int32_t read_bmp280(int32_t *raw_P, int32_t *raw_T) {
    if (i2c_write_byte(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) {
        return -1;
    }
    gpioDelay(CONVERSION_WAIT_US);
    if (read_raw_data(i2c_handle, raw_P, raw_T) != 0) {
        return -1;
    }
    int32_t temp = compensate_temperature(*raw_T);
    (void)temp;
    uint32_t press = compensate_pressure(*raw_P);
    return (int32_t)press;
}

static void log_pressure_breach(float pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) {
        perror("Error opening pressure_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Pressure: %.2f hPa\n", timestamp, pressure);
    fclose(fp);
}

static int init_bmp280(void) {
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n", BMP280_I2C_ADDR, i2c_handle);
        return -1;
    }
    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_CHIP_ID);
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: expected 0x%02X, got 0x%02X\n", BMP280_CHIP_ID, chip_id);
        i2cClose(i2c_handle);
