    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (init_bmp280() != 0) {
        fprintf(stderr, "BMP280 initialisation failed\n");
        cleanup();
        return 1;
    }
    printf("BMP280 initialised successfully. Monitoring pressure...\n");
    while (!terminate) {
        int32_t raw_P, raw_T;
        int retries = 0;
        int success = 0;
        while (retries < MAX_RETRIES && !terminate) {
            int32_t press = read_bmp280(&raw_P, &raw_T);
            if (press >= 0) {
                float pressure = (float)press / 100.0f;
                if (pressure > PRESSURE_HIGH_THRESHOLD || pressure < PRESSURE_LOW_THRESHOLD) {
                    log_pressure_breach(pressure);
                }
                success = 1;
                break;
            }
            retries++;
            fprintf(stderr, "Read attempt %d failed, retrying...\n", retries);
            gpioDelay(100000);
        }
        if (!success) {
            fprintf(stderr, "Failed to read BMP280 after %d retries, re-initialising...\n", MAX_RETRIES);
            i2cClose(i2c_handle);
            i2c_handle = -1;
            if (init_bmp280() != 0) {
                fprintf(stderr, "Re-initialisation failed, exiting\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

