#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define I2C_BUS "/dev/i2c-1"
#define LOG_DIR "/var/log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) return -1;
    return 0;
}

static int i2c_write_cmd2(int fd, uint8_t cmd1, uint8_t cmd2) {
    uint8_t buf[2] = {cmd1, cmd2};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int tmp117_read_temp(int fd, float *temp) {
    uint8_t reg = 0x00;
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp = raw * 0.0078125f;
    return 0;
}

static int aht20_init(int fd) {
    uint8_t init_cmd[3] = {0xBE, 0x08, 0x00};
    if (write(fd, init_cmd, 3) != 3) return -1;
    usleep(10000);
    return 0;
}

static int aht20_read(int fd, float *temp, float *hum) {
    uint8_t measure_cmd[3] = {0xAC, 0x33, 0x00};
    if (write(fd, measure_cmd, 3) != 3) return -1;
    usleep(80000);
    uint8_t buf[7];
    if (i2c_read_bytes(fd, buf, 7) < 0) return -1;
    if (buf[0] & 0x80) return 1; // busy
    uint32_t raw_hum = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | (buf[3] >> 4);
    uint32_t raw_temp = (((uint32_t)buf[3] & 0x0F) << 16) | ((uint32_t)buf[4] << 8) | buf[5];
    *hum = (raw_hum * 100.0f) / 1048576.0f;
    *temp = (raw_temp * 200.0f) / 1048576.0f - 50.0f;
    return 0;
}

static int pir_read(struct gpiod_line *line) {
    int val = gpiod_line_get_value(line);
    if (val < 0) return -1;
    return val;
}

static void get_timestamp(char *ts, size_t len) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    strftime(ts, len, "%Y-%m-%d %H:%M:%S", tm);
}

static void get_daily_filename(char *fn, size_t len) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    strftime(fn, len, "%Y-%m-%d.log", tm);
}

static int log_data(const char *fn, float temp, float hum, int motion) {
    FILE *fp = fopen(fn, "a");
    if (!fp) { perror("fopen"); return -1; }
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, temp, hum, motion);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) { perror("gpiod_chip_open"); return 1; }
    struct gpiod_line *pir = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir) { perror("gpiod_chip_get_line"); gpiod_chip_close(chip); return 1; }
    if (gpiod_line_request_input(pir, "pir_logger") < 0) {
        perror("gpiod_line_request_input"); gpiod_chip_close(chip); return 1;
    }

    int tmp_fd = open(I2C_BUS, O_RDWR);
    if (tmp_fd < 0) { perror("open i2c"); gpiod_chip_close(chip); return 1; }
    if (ioctl(tmp_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("ioctl tmp117"); close(tmp_fd); gpiod_chip_close(chip); return 1;
    }
    float tmp;
    if (tmp117_read_temp(tmp_fd, &tmp) < 0) {
        fprintf(stderr, "TMP117 not detected\n");
    } else {
        printf("TMP117: %.2f C\n", tmp);
    }
    close(tmp_fd);

    int aht_fd = open(I2C_BUS, O_RDWR);
    if (aht_fd < 0) { perror("open i2c aht"); gpiod_chip_close(chip); return 1; }
    if (ioctl(aht_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("ioctl aht"); close(aht_fd); gpiod_chip_close(chip); return 1;
    }
    if (aht20_init(aht_fd) < 0) {
        fprintf(stderr, "AHT20 init failed\n");
    } else {
        printf("AHT20 ready\n");
    }

    char daily_fn[64];
    get_daily_filename(daily_fn, sizeof(daily_fn));
    FILE *hdr = fopen(daily_fn, "w");
    if (hdr) { fprintf(hdr, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n"); fclose(hdr); }

    while (running) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        int motion = pir_read(pir);
        float temp = -999.0f, hum = -999.0f;

        if (motion >= 0) {
            printf("%s Motion: %d\n", ts, motion);
        }

        int tmp_ok = 0;
        for (int r = 0; r < MAX_RETRIES; r++) {
            tmp_fd = open(I2C_BUS, O_RDWR);
            if (tmp_fd < 0) { usleep(RETRY_DELAY_MS * 1000); continue; }
            if (ioctl(tmp_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
                close(tmp_fd); usleep(RETRY_DELAY_MS * 1000); continue;
            }
            if (tmp117_read_temp(tmp_fd, &tmp) == 0) { tmp_ok = 1; break; }
            close(tmp_fd); usleep(RETRY_DELAY_MS * 1000);
        }
        if (tmp_ok) printf("%s TMP117: %.2f C\n", ts, tmp);

        int aht_ok = 0;
        for (int r = 0; r < MAX_RETRIES; r++) {
            aht_fd = open(I2C_BUS, O_RDWR);
            if (aht_fd < 0) { usleep(RETRY_DELAY_MS * 1000); continue; }
            if (ioctl(aht_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
                close(aht_fd); usleep(RETRY_DELAY_MS * 1000); continue;
            }
            if (aht20_read(aht_fd, &temp, &hum) == 0) { aht_ok = 1; break; }
            close(aht_fd); usleep(RETRY_DELAY_MS * 1000);
        }
        if (aht_ok) printf("%s AHT20: T=%.2f C H=%.2f %%\n", ts, temp, hum);

        if (log_data(daily_fn, tmp, hum, motion) < 0) {
            fprintf(stderr, "Log write failed\n");
        }

        sleep(1);
    }

    close(aht_fd);
    close(tmp_fd);
    gpiod_line_release(pir);
    gpiod_chip_close(chip);
    printf("\nExiting cleanly.\n");
    return 0;
}

