#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int clamp(int v)
{
    if (v < 0)   return 0;
    if (v > 255) return 255;
    return v;
}

static void set_led_color(int r, int g, int b)
{
    gpioPWM(RED_PIN,   clamp(r));
    gpioPWM(GREEN_PIN, clamp(g));
    gpioPWM(BLUE_PIN,  clamp(b));
}

static void led_off(void)
{
    gpioPWM(RED_PIN,   0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN,  0);
}

static void cleanup(void)
{
    led_off();
    gpioTerminate();
}

static void sleep_ms(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static long long now_ms(void)
{
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return (long long)tv.tv_sec * 1000LL + (long long)tv.tv_usec / 1000LL;
}

static long long elapsed_ms(long long start)
{
    return now_ms() - start;
}

static void update_led(long long *last, float load)
{
    long long now = now_ms();
    if (elapsed_ms(*last) < 500)
        return;
    *last = now;

    int r, g, b;
    if (load < 0.0f) {
        r = g = b = 0;
    } else if (load < 0.5f) {
        r = 0;
        g = (int)(load / 0.5f * 255.0f);
        b = 0;
    } else if (load < 1.0f) {
        r = (int)((1.0f - load) / 0.5f * 255.0f);
        g = 255;
        b = 0;
    } else {
        r = 255;
        g = 0;
        b = 0;
    }
    set_led_color(r, g, b);
}

static float calc_load(long long *prev_idle, long long *prev_total)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen /proc/stat");
        return -1.0f;
    }

    long long idle, non_idle, total;
    if (fscanf(fp, "cpu  %lld %lld %lld %lld",
               &idle, &non_idle, &idle, &non_idle) != 4) {
        fprintf(stderr, "Failed to parse /proc/stat\n");
        fclose(fp);
        return -1.0f;
    }
    fclose(fp);

    long long idle_diff  = idle  - *prev_idle;
    long long total_diff = non_idle - *prev_total;
    *prev_idle  = idle;
    *prev_total = non_idle;

    if (total_diff == 0) return 0.0f;
    return (float)(total_diff - idle_diff) / (float)total_diff;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        cleanup();
        return 1;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return 1;
    }

    long long prev_idle = 0, prev_total = 0;
    float load = calc_load(&prev_idle, &prev_total);
    if (load < 0.0f) {
        cleanup();
        return 1;
    }

    long long last_update = now_ms();
    set_led_color(0, 0, 0);

    while (g_running) {
        load = calc_load(&prev_idle, &prev_total);
        if (load < 0.0f) {
            fprintf(stderr, "CPU load calculation failed; continuing\n");
            sleep_ms(100);
            continue;
        }
        update_led(&last_update, load);
        sleep_ms(100);
    }

    cleanup();
    return 0;
}

