#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL_US 1000000

/* Piecewise fan-speed curve (0-255 duty) */
typedef struct {
    float temp_min;
    float temp_max;
    int   duty_min;
    int   duty_max;
} fan_curve_t;

static const fan_curve_t fan_curve[] = {
    { 25.0f,  50.0f, 0 },
    { 50.0f, 200.0f, 50 },
    { 60.0f, 200.0f, 100 }
};
static const int NUM_CURVES = (int)(sizeof(fan_curve) / sizeof(fan_curve[0]));

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

typedef struct {
    time_t timestamp;
    float  temperature;
    int    pwm_duty;
} log_entry_t;

static log_entry_t log_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d, %d Hz)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

/*
 * Read 4 bytes from the MAX31855 over SPI.
 * Returns 0 on success, -1 on SPI error, -2 on MAX31855 fault.
 */
static int read_max31855(uint8_t data[4]) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    int ret = spiXfer(spi_handle, tx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "Error: SPI transfer returned %d (expected 4)\n", ret);
        return -1;
    }

    memcpy(data, rx, 4);
    return 0;
}

/*
 * Extract thermocouple temperature (signed 14-bit, 0.25°C/LSB).
 * Returns 0 on success, -1 on fault.
 */
static int extract_temperature(const uint8_t data[4], float *temp_out) {
    uint32_t raw = ((uint32_t)data[0] << 24) |
                   ((uint32_t)data[1] << 16) |
                   ((uint32_t)data[2] << 8)  |
                   ((uint32_t)data[3]);

    /* Fault bit is bit 16 */
    if (raw & 0x00010000) {
        if (raw & 0x00000001) {
            fprintf(stderr, "MAX31855 fault: open circuit\n");
        } else if (raw & 0x00000002) {
            fprintf(stderr, "MAX31855 fault: short to GND\n");
        } else if (raw & 0x00000004) {
            fprintf(stderr, "MAX31855 fault: short to VCC\n");
        } else {
            fprintf(stderr, "MAX31855 fault: unknown\n");
        }
        return -1;
    }

    /* Thermocouple temperature: bits 31..18, signed 14-bit */
    int16_t thermocouple_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple_raw & 0x2000) {
        thermocouple_raw |= 0xC000; /* sign-extend */
    }

    *temp_out = (float)thermocouple_raw * 0.25f;
    return 0;
}

static int calculate_fan_speed(float temperature) {
    for (int i = 0; i < NUM_CURVES; i++) {
        if (temperature >= fan_curve[i].temp_min && temperature <= fan_curve[i].temp_max) {
            float frac = (temperature - fan_curve[i].temp_min) /
                         (fan_curve[i].temp_max - fan_curve[i].temp_min);
            return fan_curve[i].duty_min + (int)(frac * (float)(fan_curve[i].duty_max - fan_curve[i].duty_min));
        }
    }
    return 0;
}

static void update_fan_speed(int pwm_duty) {
    if (gpioPWM(FAN_GPIO, pwm_duty) < 0) {
        fprintf(stderr, "Error: gpioPWM failed for duty %d\n", pwm_duty);
    }
}

static void log_data(float temperature, int pwm_duty) {
    log_buffer[buffer_index].timestamp = time(NULL);
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].pwm_duty = pwm_duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void) {
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&log_buffer[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            snprintf(time_str, sizeof(time_str), "INVALID");
        }
        printf("[%s] Temp: %.2f°C, PWM: %d\n", time_str, log_buffer[idx].temperature, log_buffer[idx].pwm_duty);
    }
    printf("--- End of Buffer ---\n");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize() != 0) {
        return 1;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        uint8_t data[4];
        float temperature;
        int ret = read_max31855(data);

        if (ret == 0) {
            if (extract_temperature(data, &temperature) == 0) {
                int pwm_duty = calculate_fan_speed(temperature);
                update_fan_speed(pwm_duty);
                log_data(temperature, pwm_duty);
                printf("Temp: %.2f°C, PWM: %d\n", temperature, pwm_duty);
            } else {
                fprintf(stderr, "MAX31855 fault — skipping fan update\n");
            }
        } else if (ret == -1) {
            fprintf(stderr, "SPI transfer error — skipping fan update\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    print_buffer();
    return 0;
}

