static int extract_temperature(const uint8_t data[4], float *temp_out) {
    uint32_t raw = ((uint32_t)data[0] << 24) |
                   ((uint32_t)data[1] << 16) |
                   ((uint32_t)data[2] << 8)  |
                   ((uint32_t)data[3]);

    /* Fault bit is bit 16 */
    if (raw & 0x00010000) {
        if (raw & 0x00000001) {
            fprintf(stderr, "MAX31855 fault: open circuit\n");
        } else if (raw & 0x00000002) {
            fprintf(stderr, "MAX31855 fault: short to GND\n");
        } else if (raw & 0x00000004) {
            fprintf(stderr, "MAX31855 fault: short to VCC\n");
        } else {
            fprintf(stderr, "MAX31855 fault: unknown\n");
        }
        return -1;
    }

    /* Thermocouple temperature: bits 31..18, signed 14-bit */
    int16_t thermocouple_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple_raw & 0x2000) {
        thermocouple_raw |= 0xC000; /* sign-extend */
    }

    *temp_out = (float)thermocouple_raw * 0.25f;
    return 0;
}

static int calculate_fan_speed(float temperature) {
    for (int i = 0; i < NUM_CURVES; i++) {
        if (temperature >= fan_curve[i].temp_min && temperature <= fan_curve[i].temp_max) {
            float frac = (temperature - fan_curve[i].temp_min) /
                         (fan_curve[i].temp_max - fan_curve[i].temp_min);
            return fan_curve[i].duty_min + (int)(frac * (float)(fan_curve[i].duty_max - fan_curve[i].duty_min));
        }
    }
    return 0;
}

static void update_fan_speed(int pwm_duty) {
    if (gpioPWM(FAN_GPIO, pwm_duty) < 0) {
        fprintf(stderr, "Error: gpioPWM failed for duty %d\n", pwm_duty);
    }
}

static void log_data(float temperature, int pwm_duty) {
    log_buffer[buffer_index].timestamp = time(NULL);
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].pwm_duty = pwm_duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void) {
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&log_buffer[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            snprintf(time_str, sizeof(time_str), "INVALID");
        }
        printf("[%s] Temp: %.2f°C, PWM: %d\n", time_str, log_buffer[idx].temperature, log_buffer[idx].pwm_duty);
    }
    printf("--- End of Buffer ---\n");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize() != 0) {
        return 1;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        uint8_t data[4];
        float temperature;
        int ret = read_max31855(data);

        if (ret == 0) {
            if (extract_temperature(data, &temperature) == 0) {
                int pwm_duty = calculate_fan_speed(temperature);
                update_fan_speed(pwm_duty);
                log_data(temperature, pwm_duty);
                printf("Temp: %.2f°C, PWM: %d\n", temperature, pwm_duty);
            } else {
                fprintf(stderr, "MAX31855 fault — skipping fan update\n");
            }
        } else if (ret == -1) {
            fprintf(stderr, "SPI transfer error — skipping fan update\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    print_buffer();
    return 0;
}

