#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define OSS 3

static volatile int logging_enabled = 0;
static volatile int i2c_handle = -1;
static volatile int running = 1;
static FILE *log_file = NULL;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t cal;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(int handle, bmp180_cal_t *c) {
    int v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_AC1); if (v < 0) return -1; c->ac1 = (int16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_AC2); if (v < 0) return -1; c->ac2 = (int16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_AC3); if (v < 0) return -1; c->ac3 = (int16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_AC4); if (v < 0) return -1; c->ac4 = (uint16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_AC5); if (v < 0) return -1; c->ac5 = (uint16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_AC6); if (v < 0) return -1; c->ac6 = (uint16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_B1);  if (v < 0) return -1; c->b1  = (int16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_B2);  if (v < 0) return -1; c->b2  = (int16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_MB);  if (v < 0) return -1; c->mb  = (int16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_MC);  if (v < 0) return -1; c->mc  = (int16_t)v;
    v = i2cReadWordData(handle, BMP180_REG_CAL_MD);  if (v < 0) return -1; c->md  = (int16_t)v;
    return 0;
}

static int read_raw_temp(int handle, int32_t *ut) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    int v = i2cReadWordData(handle, BMP180_REG_MSB);
    if (v < 0) return -1;
    *ut = (int32_t)(v << 8);
    v = i2cReadByteData(handle, BMP180_REG_LSB);
    if (v < 0) return -1;
    *ut |= v;
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) < 0) return -1;
    gpioDelay(2000);
    int msb = i2cReadByteData(handle, BMP180_REG_MSB);
    if (msb < 0) return -1;
    int lsb = i2cReadByteData(handle, BMP180_REG_LSB);
    if (lsb < 0) return -1;
    int xlsb = i2cReadByteData(handle, BMP180_REG_XLSB);
    if (xlsb < 0) return -1;
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
}

static int compute_b5(int32_t ut, const bmp180_cal_t *c, int32_t *b5) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    *b5 = x1 + x2;
    return 0;
}

static int read_temperature(int handle, const bmp180_cal_t *c, float *temp) {
    int32_t ut;
    if (read_raw_temp(handle, &ut) < 0) return -1;
    int32_t b5;
    if (compute_b5(ut, c, &b5) < 0) return -1;
    *temp = ((b5 + 8) >> 4) / 10.0f;
    return 0;
}

static int read_pressure(int handle, const bmp180_cal_t *c, float *press) {
    int32_t up;
    if (read_raw_pressure(handle, &up) < 0) return -1;
    int32_t b5;
    if (compute_b5(0, c, &b5) < 0) return -1;
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((int32_t)c->ac1 * 4 + x3) << OSS) + 2;
    b3 /= 4;
    uint32_t b4 = ((uint32_t)c->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    *press = (float)p;
    return 0;
}

static void log_data(FILE *f, float temp, float press) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(f, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, press);
    fflush(f);
}

static void toggle_logging(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)tick; (void)userdata;
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration(i2c_handle, &cal) < 0) {
        fprintf(stderr, "Calibration read failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("altitude_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    gpioSetMode(2, PI_INPUT);
    gpioSetPullUpDown(2, PI_PUD_UP);
    if (gpioSetISRFuncEx(2, FALLING_EDGE, 0, toggle_logging, NULL) < 0) {
        fprintf(stderr, "ISR setup failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    while (running) {
        if (logging_enabled) {
            float temp, press;
            if (read_temperature(i2c_handle, &cal, &temp) < 0) {
                fprintf(stderr, "Temp read error\n");
            } else if (read_pressure(i2c_handle, &cal, &press) < 0) {
                fprintf(stderr, "Press read error\n");
            } else {
                log_data(log_file, temp, press);
            }
        }
        gpioDelay(1000000);
    }
    gpioSetISRFuncEx(2, FALLING_EDGE, 0, NULL, NULL);
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

