#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CALIB 0xAA
#define ALERT_GPIO 24
#define BUFFER_SIZE 60
#define I2C_BUS 1
#define OSS 0
#define ALERT_THRESHOLD 5.0

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_calib_t;

static bmp180_calib_t calib;
static float pressure_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(void) {
    int reg, val;
    reg = BMP180_REG_CALIB;
    if (i2cWriteByte(i2c_handle, reg) < 0) return -1;
    if (i2cWriteByte(i2c_handle, reg) < 0) return -1;
    for (int i = 0; i < 22; i++) {
        val = i2cReadByte(i2c_handle);
        if (val < 0) return -1;
        if (i < 2) calib.ac1 = (calib.ac1 << 8) | val;
        else if (i < 4) calib.ac2 = (calib.ac2 << 8) | val;
        else if (i < 6) calib.ac3 = (calib.ac3 << 8) | val;
        else if (i < 8) calib.ac4 = (calib.ac4 << 8) | val;
        else if (i < 10) calib.ac5 = (calib.ac5 << 8) | val;
        else if (i < 12) calib.ac6 = (calib.ac6 << 8) | val;
        else if (i < 14) calib.b1 = (calib.b1 << 8) | val;
        else if (i < 16) calib.b2 = (calib.b2 << 8) | val;
        else if (i < 18) calib.mb = (calib.mb << 8) | val;
        else if (i < 20) calib.mc = (calib.mc << 8) | val;
        else if (i < 22) calib.md = (calib.md << 8) | val;
    }
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    int reg = BMP180_REG_CONTROL;
    if (i2cWriteByteData(i2c_handle, reg, 0x2E) < 0) return -1;
    gpioDelay(5000);
    reg = BMP180_REG_MSB;
    int msb = i2cReadByteData(i2c_handle, reg);
    int lsb = i2cReadByteData(i2c_handle, reg + 1);
    if (msb < 0 || lsb < 0) return -1;
    *ut = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    int reg = BMP180_REG_CONTROL;
    if (i2cWriteByteData(i2c_handle, reg, 0x34 + (OSS << 6)) < 0) return -1;
    gpioDelay(5000);
    reg = BMP180_REG_MSB;
    int msb = i2cReadByteData(i2c_handle, reg);
    int lsb = i2cReadByteData(i2c_handle, reg + 1);
    int xlsb = i2cReadByteData(i2c_handle, reg + 2);
    if (msb < 0 || lsb < 0 || xlsb < 0) return -1;
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
}

static float calculate_pressure(int32_t ut, int32_t up) {
    int32_t x1 = ((ut - (int32_t)calib.ac6) * (int32_t)calib.ac5) >> 15;
    int32_t x2 = ((int32_t)calib.mc << 11) / (x1 + (int32_t)calib.md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)calib.b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)calib.ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)calib.ac1) * 4 + x3) << OSS) + 2) >> 2;
    x1 = ((int32_t)calib.ac3 * b6) >> 13;
    x2 = ((int32_t)calib.b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)calib.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p / 100.0f;
}

static void timer_callback(void *user_data) {
    (void)user_data;
    int32_t ut, up;
    if (read_raw_temperature(&ut) < 0) {
        fprintf(stderr, "Error: Failed to read raw temperature\n");
        return;
    }
    if (read_raw_pressure(&up) < 0) {
        fprintf(stderr, "Error: Failed to read raw pressure\n");
        return;
    }
    float pressure = calculate_pressure(ut, up);
    pressure_buffer[buffer_index] = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) sum += pressure_buffer[i];
