#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQ 25000
#define PWM_RANGE 255
#define TEMP_MIN 40.0
#define TEMP_MAX 70.0
#define TEMP_STEP 1.0
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(float *temp_out) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature file");
        return -1;
    }
    int raw;
    if (fscanf(fp, "%d", &raw) != 1) {
        fprintf(stderr, "Failed to parse temperature\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    *temp_out = (float)raw / 1000.0f;
    return 0;
}

static int set_fan_speed(float temp) {
    if (temp < TEMP_MIN) temp = TEMP_MIN;
    if (temp > TEMP_MAX) temp = TEMP_MAX;
    float duty = (temp - TEMP_MIN) / (TEMP_MAX - TEMP_MIN) * (float)PWM_RANGE;
    if (duty < 0.0f) duty = 0.0f;
    if (duty > (float)PWM_RANGE) duty = (float)PWM_RANGE;
    int duty_int = (int)(duty + 0.5f);
    if (gpioPWM(FAN_GPIO, duty_int) < 0) {
        fprintf(stderr, "gpioPWM failed\n");
        return -1;
    }
    return 0;
}

static int log_data(float temp, int duty) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    if (fprintf(log_fp, "%s,%.2f,%d\n", ts, temp, duty) < 0) {
        perror("fprintf log");
        return -1;
    }
    fflush(log_fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioPWM(FAN_GPIO, 0) < 0) {
        fprintf(stderr, "gpioPWM initial off failed\n");
        gpioTerminate();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log file");
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        return 1;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temp;
        if (read_cpu_temp(&temp) < 0) {
            fprintf(stderr, "Temperature read failed; skipping cycle\n");
        } else {
            if (set_fan_speed(temp) < 0) {
                fprintf(stderr, "Fan speed set failed\n");
            }
            if (log_data(temp, gpioGetPWMdutycycle(FAN_GPIO)) < 0) {
                fprintf(stderr, "Log write failed\n");
            }
        }
        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    if (log_fp) fclose(log_fp);
    gpioTerminate();
    return 0;
}

