#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_BUS        "/dev/i2c-1"
#define BMP280_DEFAULT_ADDR   0x76
#define BMP280_ALT_ADDR       0x77
#define BMP280_CHIP_ID_REG    0xD0
#define BMP280_CHIP_ID        0x58
#define BMP280_RESET_REG      0xE0
#define BMP280_RESET_CMD      0xB6
#define BMP280_CTRL_MEAS_REG  0xF4
#define BMP280_STATUS_REG     0xF3
#define BMP280_PRESS_MSB_REG  0xF7
#define BMP280_CALIB_START    0x88
#define BMP280_CALIB_LEN      24
#define BMP280_FORCED_MODE    0x25
#define BMP280_OSRS_T_X1      0x01
#define BMP280_OSRS_P_X1      0x01
#define BMP280_MEAS_TIMEOUT   100
#define LOG_FILE              "weather_data.txt"
#define SAMPLE_INTERVAL_SEC   5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (block reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read block from 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_init(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus for addr 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    uint8_t chip_id = 0;
    if (i2c_read_reg(fd, BMP280_CHIP_ID_REG, &chip_id) < 0) {
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: got 0x%02X, expected 0x%02X (addr 0x%02X)\n",
                chip_id, BMP280_CHIP_ID, addr);
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_RESET_REG, BMP280_RESET_CMD) < 0) {
        return -1;
    }
    usleep(2000);
    uint8_t ctrl = (BMP280_OSRS_T_X1 << 5) | (BMP280_OSRS_P_X1 << 2) | BMP280_FORCED_MODE;
    if (i2c_write_reg(fd, BMP280_CTRL_MEAS_REG, ctrl) < 0) {
        return -1;
    }
    return 0;
}

static int bmp280_read_calibration(int fd, int addr, int32_t *dig_T1, int32_t *dig_T2, int32_t *dig_T3,
                                   int32_t *dig_P1, int32_t *dig_P2, int32_t *dig_P3,
                                   int32_t *dig_P4, int32_t *dig_P5, int32_t *dig_P6,
                                   int32_t *dig_P7, int32_t *dig_P8, int32_t *dig_P9) {
    uint8_t cal[BMP280_CALIB_LEN];
    if (i2c_read_block(fd, BMP280_CALIB_START, cal, BMP280_CALIB_LEN) < 0) {
        return -1;
    }
    *dig_T1 = (int32_t)((uint32_t)cal[0]  | ((uint32_t)cal[1]  << 8));
    *dig_T2 = (int32_t)((uint32_t)cal[2]  | ((uint32_t)cal[3]  << 8));
    *dig_T3 = (int32_t)((uint32_t)cal[4]  | ((uint32_t)cal[5]  << 8));
    *dig_P1 = (int32_t)((uint32_t)cal[6]  | ((uint32_t)cal[7]  << 8));
    *dig_P2 = (int32_t)((uint32_t)cal[8]  | ((uint32_t)cal[9]  << 8));
    *dig_P3 = (int32_t)((uint32_t)cal[10] | ((uint32_t)cal[11] << 8));
    *dig_P4 = (int32_t)((uint32_t)cal[12] | ((uint32_t)cal[13] << 8));
    *dig_P5 = (int32_t)((uint32_t)cal[14] | ((uint32_t)cal[15] << 8));
    *dig_P6 = (int32_t)((uint32_t)cal[16] | ((uint32_t)cal[17] << 8));
    *dig_P7 = (int32_t)((uint32_t)cal[18] | ((uint32_t)cal[19] << 8));
    *dig_P8 = (int32_t)((uint32_t)cal[20] | ((uint32_t)cal[21] << 8));
    *dig_P9 = (int32_t)((uint32_t)cal[22] | ((uint32_t)cal[23] << 8));
    return 0;
}

static int bmp280_read_raw(int fd, int addr, int32_t *raw_t, int32_t *raw_p) {
    uint8_t status = 0;
    for (int i = 0; i < BMP280_MEAS_TIMEOUT; i++) {
        if (i2c_read_reg(fd, BMP280_STATUS_REG, &status) < 0) {
            return -1;
        }
        if ((status & 0x08) == 0) break;
        usleep(2000);
        if (i == BMP280_MEAS_TIMEOUT - 1) {
            fprintf(stderr, "BMP280 measurement timeout\n");
            return -1;
        }
    }
    uint8_t data[6];
    if (i2c_read_block(fd, BMP280_PRESS_MSB_REG, data, 6) < 0) {
        return -1;
    }
    *raw_p = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *raw_t = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);
    return 0;
}

static double bmp280_compensate_temp(int32_t raw_t, int32_t *t_fine, int32_t dig_T1, int16_t dig_T2, int16_t dig_T3) {
    double v1 = ((double)raw_t / 16384.0 - (double)dig_T1 / 1024.0) * (double)dig_T2;
    double v2 = ((double)raw_t / 131072.0 - (double)dig_T1 / 8192.0) *
                ((double)raw_t / 131072.0 - (double)dig_T1 / 8192.0) * (double)dig_T3;
    *t_fine = (int32_t)(v1 + v2);
    return (v1 + v2) / 5120.0;
}

static double bmp280_compensate_press(int32_t raw_p, int32_t t_fine, int32_t dig_P1, int16_t dig_P2, int16_t dig_P3,
                                      int16_t dig_P4, int16_t dig_P5, int16_t dig_P6, int16_t dig_P7,
                                      int16_t dig_P8, int16_t dig_P9) {
    double v1 = (double)t_fine / 2.0 - 64000.0;
    double v2 = v1 * v1 * (double)dig_P6 / 32768.0;
    v2 = v2 + v1 * (double)dig_P5 * 2.0;
    v2 = v2 / 4.0 + (double)dig_P4 * 65536.0;
    v1 = ((double)dig_P3 * v1 * v1 / 524288.0 + (double)dig_P2 * v1) / 524288.0;
    v1 = (1.0 + v1 / 32768.0) * (double)dig_P1;
    if (v1 == 0.0) return 0.0;
    double p = 1048576.0 - (double)raw_p;
    p = (p - v2 / 4096.0) * 6250.0 / v1;
    v1 = (double)dig_P9 * p * p / 2147483648.0;
    v2 = p * (double)dig_P8 / 32768.0;
    p = p + (v1 + v2 + (double)dig_P7) / 16.0;
    return p / 100.0;
}

static int log_data(const char *filename, double temp, double press) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    if (fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", ts, temp, press) < 0) {
        fprintf(stderr, "Failed to write to %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close %s: %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(BMP280_I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", BMP280_I2C_BUS, strerror(errno));
        return 1;
    }

    int addr = BMP280_DEFAULT_ADDR;
    if (bmp280_init(fd, addr) < 0) {
        fprintf(stderr, "Failed to init BMP280 at 0x%02X\n", addr);
        close(fd);
        return 1;
    }
    printf("BMP280 initialized at 0x%02X\n", addr);

    int32_t dig_T1, dig_T2, dig_T3, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
    if (bmp280_read_calibration(fd, addr, &dig_T1, &dig_T2, &dig_T3, &dig_P1, &dig_P2, &dig_P3, &dig_P4, &dig_P5, &dig_P6, &dig_P7, &dig_P8, &dig_P9) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(fd);
        return 1;
    }
    printf("Calibration data loaded\n");

    while (g_running) {
        int32_t raw_t = 0, raw_p = 0;
        if (bmp280_read_raw(fd, addr, &raw_t, &raw_p) < 0) {
            fprintf(stderr, "Read failed, continuing\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }
        int32_t t_fine;
        double temp = bmp280_compensate_temp(raw_t, &t_fine, dig_T1, dig_T2, dig_T3);
        double press = bmp280_compensate_press(raw_p, t_fine, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9);
        if (log_data(LOG_FILE, temp, press) < 0) {
            fprintf(stderr, "Logging failed\n");
        }
        printf("Temperature: %.2f °C, Pressure: %.2f hPa\n", temp, press);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

