#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define MAX31865_CONFIG_REG 0x80
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07
#define MAX31865_VBIAS 0x40
#define MAX31865_AVRG 0x02
#define MAX31865_CRIT 0x01
#define MAX31865_CONV 0x04
#define MAX31865_RDIV4 0x00
#define MAX31865_RDIV16 0x04
#define MAX31865_RREF 430.0
#define PT100_NOMINAL_RESISTANCE 100.0
#define TARGET_TEMP 25.0
#define MAX_TEMP 80.0
#define LOG_FILE "heater_control.log"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static double target_temperature = TARGET_TEMP;
static double Kp = 1.0, Ki = 0.1, Kd = 0.01;
static double integral = 0.0, previous_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fclose(fp);
    }
    fprintf(stderr, "%s\n", msg);
}

static int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) return 0;
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=\n");
        char *val = strtok(NULL, "\n");
        if (!key || !val) continue;
        if (strcmp(key, "target_temperature") == 0) target_temperature = atof(val);
        else if (strcmp(key, "Kp") == 0) Kp = atof(val);
        else if (strcmp(key, "Ki") == 0) Ki = atof(val);
        else if (strcmp(key, "Kd") == 0) Kd = atof(val);
    }
    fclose(fp);
    return 0;
}

static int max31865_init(void) {
    if (spi_handle >= 0) spiClose(spi_handle);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        log_message("Failed to open SPI");
        return -1;
    }
    if (spiWrite(spi_handle, (char[]){MAX31865_CONFIG_REG, MAX31865_VBIAS | MAX31865_AVRG | MAX31865_CRIT | MAX31865_CONV}, 2) != 0) {
        log_message("Failed to write MAX31865 config");
        spiClose(spi_handle);
        spi_handle = -1;
        return -1;
    }
    return 0;
}

static int max31865_read_rtd(double *resistance) {
    char buf[3];
    if (spiRead(spi_handle, buf, 3) != 3) {
        log_message("SPI read failed");
        return -1;
    }
    int rtd_code = ((buf[0] << 8) | buf[1]) & 0x7FFF;
    if (rtd_code == 0) {
        log_message("RTD fault detected (code=0)");
        return -1;
    }
    if (rtd_code & 0x0001) {
        char fault_buf[3];
        if (spiRead(spi_handle, fault_buf, 3) != 3) {
            log_message("Failed to read fault register");
            return -1;
        }
        int fault = (fault_buf[2] << 8) | fault_buf[1];
        if (fault & 0x0001) log_message("RTD fault: open circuit");
        else if (fault & 0x0002) log_message("RTD fault: short to GND");
        else if (fault & 0x0004) log_message("RTD fault: short to VCC");
        else log_message("RTD fault: unknown");
        return -1;
    }
    *resistance = (rtd_code / 32768.0) * MAX31865_RREF;
    return 0;
}

static double rtd_to_temperature(double rtd_resistance) {
    if (rtd_resistance <= 0.0) return -1000.0;
    double r0 = PT100_NOMINAL_RESISTANCE;
    double r = rtd_resistance;
    double a = 3.9083e-3, b = -5.775e-7;
    double t = (r0 / r - 1.0) / (a + b);
    if (t < 0.0) t = 0.0;
    return t;
}

static double pid_control(double setpoint, double actual) {
    double error = setpoint - actual;
    integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    if (output < 0.0) output = 0.0;
    if (output > 1000.0) output = 1000.0;
    return output;
}

static void set_heater_pwm(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1000.0) duty_cycle = 1000.0;
    gpioPWM(HEATER_GPIO, (int)duty_cycle);
}

static void cleanup(void) {
    set_heater_pwm(0.0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return 1;
    }
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioPWM(HEATER_GPIO, 0);
    read_config("config.json");
    if (max31865_init() != 0) {
        log_message("MAX31865 init failed; exiting");
        cleanup();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    log_message("Heater control started");
    while (running) {
        double rtd_resistance = 0.0;
        if (max31865_read_rtd(&rtd_resistance) != 0) {
            log_message("Temperature read failed; failsafe");
            set_heater_pwm(0.0);
            break;
        }
        double temperature = rtd_to_temperature(rtd_resistance);
        if (temperature < 0.0) {
            log_message("RTD fault detected; failsafe");
            set_heater_pwm(0.0);
            break;
        }
        if (temperature > MAX_TEMP) {
            log_message("Temperature exceeds max; failsafe");
            set_heater_pwm(0.0);
            break;
        }
        double duty_cycle = pid_control(target_temperature, temperature);
        set_heater_pwm(duty_cycle);
        gpioDelay(100000);
    }
    log_message("Shutting down");
    cleanup();
    return 0;
}

