#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP180_ADDR 0x77
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "breach_log.txt"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3

/* BMP180 Registers */
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

/* BMP180 Commands */
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34
#define BMP180_CMD_PRESSURE1 0x74
#define BMP180_CMD_PRESSURE2 0xB4
#define BMP180_CMD_PRESSURE3 0xF4

/* Calibration coefficients */
typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d): %s\n",
                reg, attempt + 1, strerror(errno));
        usleep(10000);
    }
    return -1;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) == 1 && read(fd, buf, len) == (ssize_t)len) return 0;
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d): %s\n",
                reg, attempt + 1, strerror(errno));
        usleep(10000);
    }
    return -1;
}

static int read_calibration(int fd, bmp180_cal_t *cal) {
    uint8_t buf[22];
    if (i2c_read_block(fd, 0xAA, buf, sizeof(buf)) != 0) return -1;

    cal->ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    cal->ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    cal->ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    cal->ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    cal->ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    cal->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    cal->b1  = (int16_t)((buf[12] << 8) | buf[13]);
    cal->b2  = (int16_t)((buf[14] << 8) | buf[15]);
    cal->mb  = (int16_t)((buf[16] << 8) | buf[17]);
    cal->mc  = (int16_t)((buf[18] << 8) | buf[19]);
    cal->md  = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int fd, int32_t *raw_temp) {
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0) return -1;
    usleep(5000);
    uint8_t buf[2];
    if (i2c_read_block(fd, BMP180_REG_MSB, buf, 2) != 0) return -1;
    *raw_temp = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int fd, int32_t *raw_pressure) {
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE0) != 0) return -1;
    usleep(5000);
    uint8_t buf[3];
    if (i2c_read_block(fd, BMP180_REG_MSB, buf, 3) != 0) return -1;
    *raw_pressure = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | buf[2];
    *raw_pressure >>= 8;
    return 0;
}

static int compute_b5(int32_t ut, const bmp180_cal_t *cal, int32_t *b5_out) {
    int32_t x1 = ((ut - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    *b5_out = x1 + x2;
    return 0;
}

static int read_temperature(int fd, const bmp180_cal_t *cal, float *temp_c) {
    int32_t ut, b5;
    if (read_raw_temperature(fd, &ut) != 0) return -1;
    if (compute_b5(ut, cal, &b5) != 0) return -1;
    *temp_c = ((b5 + 8) >> 4) / 10.0f;
    return 0;
}

static int read_pressure(int fd, const bmp180_cal_t *cal, float *pressure_hpa) {
    int32_t up, b5;
    if (read_raw_pressure(fd, &up) != 0) return -1;
    if (compute_b5(up, cal, &b5) != 0) return -1;

    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((int32_t)cal->ac1 * 4 + x3) << 2) / 4;
    x1 = ((int32_t)cal->ac3 * b6) >> 13;
    x2 = ((int32_t)cal->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    *pressure_hpa = (float)p / 100.0f;
    return 0;
}

static void log_breach(float temp, float press) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_fp, "%s - Temperature: %.2f C, Pressure: %.2f hPa\n", ts, temp, press);
    fflush(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_BUS);
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    bmp180_cal_t cal;
    if (read_calibration(i2c_fd, &cal) != 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data (sensor absent or bus error)\n");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen " LOG_FILE);
        close(i2c_fd);
        return 1;
    }

    printf("BMP180 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float temp, press;
        if (read_temperature(i2c_fd, &cal, &temp) != 0) {
            fprintf(stderr, "Temperature read failed; retrying next cycle\n");
        } else if (read_pressure(i2c_fd, &cal, &press) != 0) {
            fprintf(stderr, "Pressure read failed; retrying next cycle\n");
        } else {
            if (temp > 30.0f || press < 950.0f) {
                log_breach(temp, press);
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

