#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_LSB          0xF7
#define BMP180_REG_XLSB         0xF8
#define BMP180_REG_CAL_AC1      0xAA
#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESSURE     0x34
#define FAN_GPIO                18
#define BUFFER_SIZE             60
#define SAMPLE_INTERVAL_US      500000
#define TEMP_THRESHOLD_C        30.0f
#define OSS                     0

typedef struct {
    time_t timestamp;
    float  temperature;
    float  pressure;
} sensor_data_t;

static sensor_data_t data_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    uint8_t buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)buf, 22) != 22) {
        fprintf(stderr, "Error: failed to read BMP180 calibration data\n");
        return -1;
    }
    ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1  = (int16_t)((buf[12] << 8) | buf[13]);
    b2  = (int16_t)((buf[14] << 8) | buf[15]);
    mb  = (int16_t)((buf[16] << 8) | buf[17]);
    mc  = (int16_t)((buf[18] << 8) | buf[19]);
    md  = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int32_t *raw_temp) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) {
        fprintf(stderr, "Error: failed to write temperature command\n");
        return -1;
    }
    gpioDelay(5000);
    uint8_t msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    uint8_t lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (msb < 0 || lsb < 0) {
        fprintf(stderr, "Error: failed to read temperature data\n");
        return -1;
    }
    *raw_temp = (int32_t)((msb << 8) | lsb);
    return 0;
}

static int read_raw_pressure(int32_t *raw_pressure) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE + (OSS << 6)) < 0) {
        fprintf(stderr, "Error: failed to write pressure command\n");
        return -1;
    }
    gpioDelay(2000 + (3000 << OSS));
    uint8_t msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    uint8_t lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    uint8_t xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    if (msb < 0 || lsb < 0 || xlsb < 0) {
        fprintf(stderr, "Error: failed to read pressure data\n");
        return -1;
    }
    *raw_pressure = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
}

static float calculate_temperature(int32_t raw_temp) {
    int32_t x1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t raw_pressure, int32_t raw_temp) {
    int32_t x1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    int32_t x3 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x4 = ((int32_t)ac2 * b6) >> 11;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x4 + x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)raw_pressure - (uint32_t)b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p;
}

static void timer_callback(void) {
    int32_t raw_temp = 0, raw_pressure = 0;
    if (read_raw_temperature(&raw_temp) != 0) return;
    if (read_raw_pressure(&raw_pressure) != 0) return;
    float temperature = calculate_temperature(raw_temp);
    float pressure = calculate_pressure(raw_pressure, raw_temp);
    data_buffer[buffer_index].timestamp = time(NULL);
    data_buffer[buffer_index].temperature = temperature;
    data_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
    printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
    if (temperature > TEMP_THRESHOLD_C) {
        gpioWrite(FAN_GPIO, 1);
    } else {
        gpioWrite(FAN_GPIO, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to set timer callback\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    while (running) {
        gpioDelay(100000);
    }
    gpioWrite(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

