    v = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC2);
    if (v < 0) return -1; cal.ac2 = (int16_t)v;
    v = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC3);
    if (v < 0) return -1; cal.ac3 = (int16_t)v;
    v = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC4);
    if (v < 0) return -1; cal.ac4 = (uint16_t)v;
    v = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC5);
    if (v < 0) return -1; cal.ac5 = (uint16_t)v;
    v = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC6);
    if (v < 0) return -1; cal.ac6 = (uint16_t)v;
    v = i2cReadWordData(i2c_handle, BMP180_REG_CAL_B1);
