    v = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MC);
    if (v < 0) return -1; cal.mc = (int16_t)v;
    v = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MD);
    if (v < 0) return -1; cal.md = (int16_t)v;
    return 0;
