        cleanup();
        return 1;
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    uint32_t last_edge_tick = 0;
    while (running) {
        if (gpioRead(GPIO_PIN) == 0) {
            uint32_t now = gpioTick();
            if (now - last_edge_tick > DEBOUNCE_MS * 1000) {
                logging_enabled = !logging_enabled;
                printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
                last_edge_tick = now;
            }
        }
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temp(&ut) < 0 || read_raw_pressure(&up) < 0) {
                fprintf(stderr, "I2C read error\n");
            } else {
                int32_t pressure = compute_pressure(up, ut);
                log_pressure(pressure);
            }
        }
        sleep(SAMPLE_INTERVAL_S);
    }
    cleanup();
    return 0;
}

