    *raw = ((uint32_t)(uint8_t)rx[0] << 24) |
           ((uint32_t)(uint8_t)rx[1] << 16) |
           ((uint32_t)(uint8_t)rx[2] << 8)  |
           ((uint32_t)(uint8_t)rx[3]);
    return 0;
}

static int check_fault(uint32_t raw) {
    if (raw & 0x00010000) return 1; /* Open circuit */
    if (raw & 0x00020000) return 2; /* Short to GND */
    if (raw & 0x00040000) return 3; /* Short to VCC */
    return 0;
}

static float calculate_temperature(uint32_t raw) {
    int16_t thermocouple = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple & 0x2000) thermocouple |= 0xC000;
    return thermocouple * 0.25f;
}

static void set_heater(float duty_cycle) {
    if (duty_cycle < 0.0f) duty_cycle = 0.0f;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;
    gpioPWM(HEATER_GPIO, (int)(duty_cycle * PWM_RANGE / MAX_DUTY_CYCLE));
}

static void log_data(float temperature, float duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f\n", ts, temperature, duty_cycle);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQ);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float integral = 0.0f;
    float error = 0.0f;
    float last_error = 0.0f;

    while (running) {
        uint32_t raw;
        if (read_max31855(&raw) != 0) {
            fprintf(stderr, "Max31855 read error, heater off\n");
            set_heater(0.0f);
            log_data(-999.0f, 0.0f);
            gpioDelay(100000);
            continue;
        }

        int fault = check_fault(raw);
        if (fault) {
            fprintf(stderr, "Max31855 fault %d, heater off\n", fault);
            set_heater(0.0f);
            log_data(-999.0f, 0.0f);
            gpioDelay(100000);
            continue;
        }

        float temperature = calculate_temperature(raw);
        error = TARGET_TEMP - temperature;
        integral += error;
        if (integral > MAX_DUTY_CYCLE) integral = MAX_DUTY_CYCLE;
        if (integral < 0.0f) integral = 0.0f;

        float derivative = error - last_error;
        float output = PI_KP * error + PI_KI * integral + PI_KI * derivative;
        last_error = error;

        float duty = output;
        if (duty < 0.0f) duty = 0.0f;
        if (duty > MAX_DUTY_CYCLE) duty = MAX_DUTY_CYCLE;

        set_heater(duty);
        log_data(temperature, duty);
        gpioDelay(100000);
    }

    set_heater(0.0f);
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

