#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define PWM_RANGE 255
#define PWM_FREQ  1000
#define SAMPLE_US 500000  /* 0.5 s */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int set_pwm(int pin, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "gpioPWM(pin=%d, duty=%d) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

static int read_cpu_temp(int *temp_mC)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    int val;
    if (fscanf(fp, "%d", &val) != 1) {
        fprintf(stderr, "fscanf failed on %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "read error on %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s) failed: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    *temp_mC = val;
    return 0;
}

static void set_led(int r, int g, int b)
{
    /* Common-anode: 0 duty = fully on, 255 duty = fully off */
    set_pwm(RED_PIN,   PWM_RANGE - r);
    set_pwm(GREEN_PIN, PWM_RANGE - g);
    set_pwm(BLUE_PIN,  PWM_RANGE - b);
}

static void cleanup(void)
{
    set_pwm(RED_PIN,   PWM_RANGE);
    set_pwm(GREEN_PIN, PWM_RANGE);
    set_pwm(BLUE_PIN,  PWM_RANGE);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* Configure PWM on each pin */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Mood light started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int temp_mC = 0;
        if (read_cpu_temp(&temp_mC) < 0) {
            fprintf(stderr, "Temperature read failed; skipping cycle\n");
        } else {
            int r = 0, g = 0, b = 0;
            if (temp_mC < 40000) {
                b = 255;
            } else if (temp_mC < 60000) {
                g = 255;
            } else {
                r = 255;
            }
            set_led(r, g, b);
            printf("Temp: %d m°C  R:%3d G:%3d B:%3d\n", temp_mC, r, g, b);
        }
        usleep(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

