#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define READ_INTERVAL_SEC 60

volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} SensorData;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void sleep_ms(int ms) {
    struct timespec ts = { ms / 1000, (ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int wait_for_level(int gpio, int level, int timeout_ms) {
    int elapsed = 0;
    while (gpioRead(gpio) != level) {
        if (terminate) return -1;
        sleep_ms(1);
        elapsed += 1;
        if (elapsed > timeout_ms) return -1;
    }
    return 0;
}

static int read_dht22(SensorData *data) {
    int i, j;
    int bits[40] = {0};
    int pulse_lengths[40] = {0};
    int pulse_count = 0;

    if (gpioSetMode(DHT22_GPIO, PI_OUTPUT) < 0) return -1;
    gpioWrite(DHT22_GPIO, 0);
    sleep_ms(2);
    gpioWrite(DHT22_GPIO, 1);
    sleep_ms(30);
    if (gpioSetMode(DHT22_GPIO, PI_INPUT) < 0) return -1;

    if (wait_for_level(DHT22_GPIO, 0, 100) < 0) return -1;
    if (wait_for_level(DHT22_GPIO, 1, 100) < 0) return -1;
    if (wait_for_level(DHT22_GPIO, 0, 100) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_level(DHT22_GPIO, 1, 100) < 0) return -1;
        if (wait_for_level(DHT22_GPIO, 0, 100) < 0) return -1;

        int start_tick = gpioTick();
        while (gpioRead(DHT22_GPIO) == 0) {
            if (terminate) return -1;
            if (gpioTick() - start_tick > 100) return -1;
        }
        int end_tick = gpioTick();
        pulse_lengths[i] = end_tick - start_tick;
        bits[i] = (pulse_lengths[i] > 50) ? 1 : 0;
    }

    int checksum = bits[0] + bits[2] + bits[4] + bits[6] + bits[8] +
                   bits[10] + bits[12] + bits[14] +
                   bits[16] + bits[18] + bits[20] +
                   bits[22] + bits[24] + bits[26] + bits[28] + bits[30];

    if (checksum != (bits[1] + bits[3] + bits[5] + bits[7] + bits[9] +
                     bits[11] + bits[13] + bits[15] + bits[17] + bits[19])) {
        return -2;
    }

    int raw_humidity = (bits[0] << 7) | (bits[1] << 6) | (bits[2] << 5) | (bits[3] << 4) |
                       (bits[4] << 3) | (bits[5] << 2) | (bits[6] << 1) | bits[7];
    int raw_temp = (bits[8] << 7) | (bits[9] << 6) | (bits[10] << 5) | (bits[11] << 4) |
                   (bits[12] << 3) | (bits[13] << 2) | (bits[14] << 1) | bits[15];

    if (raw_temp & 0x800) {
        raw_temp = ~(raw_temp & 0x7FF);
        data->temperature = -((float)raw_temp / 10.0);
    } else {
        data->temperature = (float)raw_temp / 10.0;
    }
    data->humidity = (float)raw_humidity / 10.0;

    if (data->humidity < 0 || data->humidity > 100 || data->temperature < -40 || data->temperature > 80) {
        return -3;
    }
    return 0;
}

static int post_data(SensorData data) {
    CURL *curl = curl_easy_init();
    if (!curl) return -1;

    char json[128];
    snprintf(json, sizeof(json), "{\"temperature\":%.1f,\"humidity\":%.1f}", data.temperature, data.humidity);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");

    curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    int ret = 0;
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        ret = -1;
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return ret;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    curl_global_init(CURL_GLOBAL_ALL);

    while (!terminate) {
        SensorData data;
        int retries = 0;
        int result = -1;

        while (retries < MAX_RETRIES && !terminate) {
            result = read_dht22(&data);
            if (result == 0) break;
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "DHT22 read failed, retrying (%d/%d)\n", retries, MAX_RETRIES);
                sleep_ms(2000);
            }
        }

        if (result == 0) {
            if (post_data(data) == 0) {
                printf("Data posted successfully: T=%.1fC, H=%.1f%%\n", data.temperature, data.humidity);
            } else {
                fprintf(stderr, "Failed to post data\n");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 after %d retries\n", MAX_RETRIES);
        }

        for (int i = 0; i < READ_INTERVAL_SEC && !terminate; i++) {
            sleep_ms(1000);
        }
    }

    gpioTerminate();
    curl_global_cleanup();
    return 0;
}

