        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        ret = -1;
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return ret;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    curl_global_init(CURL_GLOBAL_ALL);

    while (!terminate) {
        SensorData data;
        int retries = 0;
        int result = -1;

        while (retries < MAX_RETRIES && !terminate) {
            result = read_dht22(&data);
            if (result == 0) break;
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "DHT22 read failed, retrying (%d/%d)\n", retries, MAX_RETRIES);
                sleep_ms(2000);
            }
        }

        if (result == 0) {
            if (post_data(data) == 0) {
                printf("Data posted successfully: T=%.1fC, H=%.1f%%\n", data.temperature, data.humidity);
            } else {
                fprintf(stderr, "Failed to post data\n");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 after %d retries\n", MAX_RETRIES);
