#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR        0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB     0xF6
#define BMP180_REG_LSB     0xF7
#define BMP180_REG_XLSB    0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_OSS         3
#define DEBOUNCE_US        200000
#define SAMPLE_INTERVAL_S  2
#define LOG_FILE           "pressure_log.txt"

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_last_tick = 0;
static volatile int          g_logging_enabled = 0;
static int                   g_i2c_handle = -1;

typedef struct {
    int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t g_cal;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_calibration(int handle, bmp180_cal_t *cal) {
    uint8_t buf[22];
    if (i2cReadI2CBlockData(handle, BMP180_REG_CAL_AC1, (char *)buf, 22) != 22) {
        fprintf(stderr, "Error: failed to read BMP180 calibration data\n");
        return -1;
    }
    cal->ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    cal->ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    cal->ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    cal->ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    cal->ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    cal->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    cal->b1  = (int16_t)((buf[12] << 8) | buf[13]);
    cal->b2  = (int16_t)((buf[14] << 8) | buf[15]);
    cal->mb  = (int16_t)((buf[16] << 8) | buf[17]);
    cal->mc  = (int16_t)((buf[18] << 8) | buf[19]);
    cal->md  = (int16_t)((buf[20] << 8) | buf[21]);
    if (cal->ac1 == 0 || cal->ac1 == -1 || cal->ac6 == 0 || cal->ac6 == -1) {
        fprintf(stderr, "Error: BMP180 calibration data invalid (sensor absent?)\n");
        return -1;
    }
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    uint8_t cmd = 0x2E;
    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) return -1;
    gpioDelay(5000);
    uint8_t buf[2];
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, (char *)buf, 2) != 2) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    uint8_t cmd = 0x34 + (BMP180_OSS << 6);
    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) return -1;
    gpioDelay(26000);
    uint8_t buf[3];
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, (char *)buf, 3) != 3) return -1;
    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | (int32_t)buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut, const bmp180_cal_t *c) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t ut, const bmp180_cal_t *c) {
    int32_t b5 = compute_b5(ut, c);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)c->ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);
    x1 = ((int32_t)c->ac3 * b6) >> 13;
    x2 = ((int32_t)c->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)c->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000UL) p = (b7 * 2) / b4;
    else                  p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    if (tick - g_last_tick < DEBOUNCE_US) return;
    g_last_tick = tick;
    g_logging_enabled = !g_logging_enabled;
    printf("Logging %s\n", g_logging_enabled ? "enabled" : "disabled");
    fflush(stdout);
}

static void log_pressure(int32_t pressure_hpa) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Pressure: %.2f hPa\n", ts, pressure_hpa / 100.0);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    g_i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n", BMP180_ADDR, g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration(g_i2c_handle, &g_cal) != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(4, PI_INPUT);
    gpioSetPullUpDown(4, PI_PUD_UP);
    if (gpioSetISRFuncEx(4, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Error setting ISR on GPIO4\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("BMP180 logging started. Press button on GPIO4 to toggle logging.\n");
    while (g_running) {
        if (g_logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(g_i2c_handle, &ut) == 0 &&
                read_raw_pressure(g_i2c_handle, &up) == 0) {
                int32_t b5 = compute_b5(ut, &g_cal);
                int32_t p = compute_pressure(up, ut, &g_cal);
                log_pressure(p);
            } else {
                fprintf(stderr, "Error reading BMP180 data\n");
            }
        } else {
            printf("Logging disabled\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }
    gpioSetISRFuncEx(4, FALLING_EDGE, 0, NULL, NULL);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

