#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 2000
#define READ_INTERVAL_S 10
#define DHT22_TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;
static char server_url[256] = "http://your-server.com/api/humidity";

typedef struct {
    char *data;
    size_t size;
} MemoryStruct;

static size_t write_cb(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;
    char *ptr = realloc(mem->data, mem->size + realsize + 1);
    if (!ptr) {
        syslog(LOG_ERR, "realloc failed");
        return 0;
    }
    mem->data = ptr;
    memcpy(&(mem->data[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->data[mem->size] = '\0';
    return realsize;
}

static int read_dht22(int gpio, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int bits = 0;
    uint32_t start_tick, now_tick;

    if (gpioSetMode(gpio, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(gpio, PI_LOW) < 0) return -1;
    gpioDelay(2000);
    if (gpioWrite(gpio, PI_HIGH) < 0) return -1;
    gpioDelay(30);

    if (gpioSetMode(gpio, PI_INPUT) < 0) return -1;

    start_tick = gpioTick();
    while (gpioRead(gpio) == PI_HIGH) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
    }
    start_tick = gpioTick();
    while (gpioRead(gpio) == PI_LOW) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
    }
    start_tick = gpioTick();
    while (gpioRead(gpio) == PI_HIGH) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
    }

    for (bits = 0; bits < 40; bits++) {
        start_tick = gpioTick();
        while (gpioRead(gpio) == PI_LOW) {
            if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
        }
        start_tick = gpioTick();
        while (gpioRead(gpio) == PI_HIGH) {
            if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
        }
        now_tick = gpioTick();
        if (now_tick - start_tick > 50) {
            data[bits / 8] |= (1 << (7 - (bits % 8)));
        }
    }

    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        syslog(LOG_ERR, "DHT22 checksum failed");
        return -1;
    }

    int raw_humidity = (data[0] << 8) | data[1];
    *humidity = (float)raw_humidity / 10.0f;
    return 0;
}

static int post_humidity(const char *url, float humidity) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "curl_easy_init failed");
        return -1;
    }

    MemoryStruct chunk = {0};
    chunk.data = malloc(1);
    chunk.size = 0;
    if (!chunk.data) {
        syslog(LOG_ERR, "malloc failed");
        curl_easy_cleanup(curl);
        return -1;
    }

    char json[128];
    snprintf(json, sizeof(json), "{\"humidity\": %.1f}", humidity);

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_cb);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);

    CURLcode res = curl_easy_perform(curl);
    int ret = -1;
    if (res != CURLE_OK) {
        syslog(LOG_ERR, "curl_easy_perform failed: %s", curl_easy_strerror(res));
    } else {
        long http_code = 0;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code >= 200 && http_code < 300) {
            syslog(LOG_INFO, "Humidity posted successfully (HTTP %ld)", http_code);
            ret = 0;
        } else {
            syslog(LOG_ERR, "HTTP error: %ld", http_code);
        }
    }

    free(chunk.data);
    curl_easy_cleanup(curl);
    return ret;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                strncpy(server_url, optarg, sizeof(server_url) - 1);
                server_url[sizeof(server_url) - 1] = '\0';
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("dht22_humidity", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        syslog(LOG_ERR, "curl_global_init failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
