#define RETRY_DELAY_MS 2000
#define READ_INTERVAL_S 10
#define DHT22_TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;
static char server_url[256] = "http://your-server.com/api/humidity";

typedef struct {
    char *data;
    size_t size;
} MemoryStruct;

static size_t write_cb(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;
    char *ptr = realloc(mem->data, mem->size + realsize + 1);
    if (!ptr) {
        syslog(LOG_ERR, "realloc failed");
        return 0;
    }
    mem->data = ptr;
    memcpy(&(mem->data[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->data[mem->size] = '\0';
    return realsize;
}

static int read_dht22(int gpio, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int bits = 0;
    uint32_t start_tick, now_tick;

    if (gpioSetMode(gpio, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(gpio, PI_LOW) < 0) return -1;
    gpioDelay(2000);
    if (gpioWrite(gpio, PI_HIGH) < 0) return -1;
    gpioDelay(30);

    if (gpioSetMode(gpio, PI_INPUT) < 0) return -1;

    start_tick = gpioTick();
    while (gpioRead(gpio) == PI_HIGH) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
    }
    start_tick = gpioTick();
    while (gpioRead(gpio) == PI_LOW) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
    }
    start_tick = gpioTick();
    while (gpioRead(gpio) == PI_HIGH) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
    }

    for (bits = 0; bits < 40; bits++) {
        start_tick = gpioTick();
        while (gpioRead(gpio) == PI_LOW) {
            if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
        }
        start_tick = gpioTick();
        while (gpioRead(gpio) == PI_HIGH) {
            if (gpioTick() - start_tick > DHT22_TIMEOUT_US) return -1;
        }
        now_tick = gpioTick();
        if (now_tick - start_tick > 50) {
            data[bits / 8] |= (1 << (7 - (bits % 8)));
        }
    }

    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        syslog(LOG_ERR, "DHT22 checksum failed");
        return -1;
    }

    int raw_humidity = (data[0] << 8) | data[1];
    *humidity = (float)raw_humidity / 10.0f;
    return 0;
}

