#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define CPU_TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

static int read_cpu_temp(int *temp_milli) {
    FILE *fp = fopen(CPU_TEMP_PATH, "r");
    if (!fp) {
        perror("Error opening CPU temperature file");
        return -1;
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading CPU temperature\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    *temp_milli = temp;
    return 0;
}

static int write_fan_state(int state) {
    FILE *fp = fopen(FAN_STATE_PATH, "w");
    if (!fp) {
        perror("Error opening fan state file for writing");
        return -1;
    }
    if (fprintf(fp, "%d", state) < 0) {
        perror("Error writing fan state");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("Error closing fan state file");
        return -1;
    }
    return 0;
}

static int get_max_fan_state(void) {
    FILE *fp = fopen(FAN_STATE_PATH, "r");
    if (!fp) {
        perror("Error opening fan state file for reading max state");
        return -1;
    }
    int max_state;
    if (fscanf(fp, "%d", &max_state) != 1) {
        fprintf(stderr, "Error reading max fan state\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return max_state;
}

static int set_fan_speed(int temp_milli) {
    int temp_celsius = temp_milli / 1000;
    int fan_state = 0;
    if (temp_celsius < 45) {
        fan_state = 0;
    } else if (temp_celsius < 55) {
        fan_state = 1;
    } else if (temp_celsius < 65) {
        fan_state = 2;
    } else {
        fan_state = 3;
    }
    int max_state = get_max_fan_state();
    if (max_state < 0) {
        return -1;
    }
    if (fan_state > max_state) {
        fprintf(stderr, "Requested fan state %d exceeds max state %d\n", fan_state, max_state);
        return -1;
    }
    if (write_fan_state(fan_state) != 0) {
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error setting SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting SIGTERM handler");
        return 1;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int temp_milli;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && program_running) {
            if (read_cpu_temp(&temp_milli) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                sleep(1);
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read CPU temperature after %d retries. Skipping cycle.\n", MAX_RETRIES);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int temp_celsius = temp_milli / 1000;
        int current_fan_state = -1;
        int fan_state_changed = 0;

        if (set_fan_speed(temp_milli) != 0) {
            fprintf(stderr, "Failed to set fan speed. Continuing.\n");
        } else {
            current_fan_state = get_max_fan_state();
            if (current_fan_state < 0) {
                fprintf(stderr, "Failed to read current fan state. Continuing.\n");
            } else {
                fan_state_changed = 1;
            }
        }

        if (fan_state_changed) {
            char log_message[256];
            snprintf(log_message, sizeof(log_message),
                     "Fan speed changed to %d (CPU: %d°C)", current_fan_state, temp_celsius);
            log_message(log_message);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (write_fan_state(0) != 0) {
        fprintf(stderr, "Error stopping fan during shutdown.\n");
    }
    log_message("Fan control stopped.");
    return 0;
}

