#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define TARGET_TEMPERATURE 50.0
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0
#define LOG_FILE "heater_log.txt"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static float Kp = 1.0, Ki = 0.1, Kd = 0.01;
static float integral = 0.0, previous_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", ts, msg);
    fflush(log_file);
}

static void heater_off(void) {
    gpioPWM(HEATER_GPIO, 0);
    log_message("Heater disabled (failsafe or error)");
}

static int read_max31855(float *temp) {
    char rx[4] = {0};
    int bytes = spiRead(spi_handle, rx, 4);
    if (bytes != 4) {
        log_message("SPI read error");
        return -1;
    }
    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);
    if (raw & 0x00010000) {
        if (raw & 0x00000001) log_message("Thermocouple open circuit");
        else if (raw & 0x00000002) log_message("Thermocouple short to GND");
        else if (raw & 0x00000004) log_message("Thermocouple short to VCC");
        else log_message("Unknown fault");
        return -1;
    }
    int16_t thermocouple = (int16_t)(raw >> 18);
    *temp = thermocouple * 0.25f;
    return 0;
}

static float calculate_pid(float setpoint, float actual) {
    float error = setpoint - actual;
    integral += error;
    if (integral > 100.0) integral = 100.0;
    if (integral < -100.0) integral = -100.0;
    float derivative = error - previous_error;
    float output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    if (output < 0) output = 0;
    if (output > 100) output = 100;
    return output;
}

static void cleanup(void) {
    heater_off();
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
    if (log_file) {
        log_message("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Cannot open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_message("Program started");

    while (running) {
        float temp;
        if (read_max31855(&temp) != 0) {
            heater_off();
            integral = 0.0;
            previous_error = 0.0;
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (temp > MAX_TEMPERATURE || temp < MIN_TEMPERATURE) {
            log_message("Temperature out of range, disabling heater");
            heater_off();
            integral = 0.0;
            previous_error = 0.0;
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float pid_out = calculate_pid(TARGET_TEMPERATURE, temp);
        int duty = (int)(pid_out + 0.5f);
        gpioPWM(HEATER_GPIO, duty);

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
        fprintf(log_file, "%s, Temp: %.2f, Duty: %d, PID: %.2f\n",
                ts, temp, duty, pid_out);
        fflush(log_file);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

