#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define PWM_FREQUENCY 25000
#define PWM_RANGE 100
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature file");
        return -1;
    }
    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Failed to parse temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp_milli;
}

static int calculate_duty_cycle(int temp_milli) {
    if (temp_milli < 0) return 0;
    double temp_celsius = temp_milli / 1000.0;
    if (temp_celsius <= MIN_TEMP) return 0;
    if (temp_celsius >= MAX_TEMP) return PWM_RANGE;
    double fraction = (temp_celsius - MIN_TEMP) / (MAX_TEMP - MIN_TEMP);
    return (int)(fraction * PWM_RANGE);
}

static int set_fan_speed(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "gpioPWM failed for duty cycle %d\n", duty_cycle);
        return -1;
    }
    return 0;
}

static int log_data(int temp_milli, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%d\n", timestamp, temp_milli, duty_cycle);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "gpioSetPWMfrequency failed for GPIO %d\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "gpioSetPWMrange failed for GPIO %d\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Initial gpioPWM failed for GPIO %d\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (fp) {
            fprintf(fp, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
            fclose(fp);
        } else {
            perror("fopen log file for header");
            gpioTerminate();
            return 1;
        }
    } else {
        fclose(fp);
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        int temp_milli = read_cpu_temp();
        if (temp_milli < 0) {
            fprintf(stderr, "Temperature read failed, skipping cycle\n");
        } else {
            int duty_cycle = calculate_duty_cycle(temp_milli);
            if (set_fan_speed(duty_cycle) != 0) {
                fprintf(stderr, "Failed to set fan speed\n");
            }
            if (log_data(temp_milli, duty_cycle) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
            printf("Temp: %d mC, Duty: %d%%\n", temp_milli, duty_cycle);
        }
        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    printf("Fan stopped, resources released.\n");
    return 0;
}

