    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting flow monitoring (sensors at 0x%02X and 0x%02X)...\n", SENSOR1_ADDR, SENSOR2_ADDR);

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = (read_flow_rate(i2c_handle1, &flow1) == 0);
        int ok2 = (read_flow_rate(i2c_handle2, &flow2) == 0);

        if (ok1 && ok2) {
