#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18
#define LOG_FILE "encoder_log.txt"
#define PULSES_PER_REV 360.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(float angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, Angle: %.2f\n", timestamp, angle);
    } else {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_A_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_B_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_A_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_B_PIN);
        gpioTerminate();
        return 1;
    }

    int last_a = gpioRead(SENSOR_A_PIN);
    int last_b = gpioRead(SENSOR_B_PIN);
    if (last_a < 0 || last_b < 0) {
        fprintf(stderr, "Failed to read initial GPIO state\n");
        gpioTerminate();
        return 1;
    }

    int state = (last_a << 1) | last_b;
    int last_state = state;
    int count = 0;

    printf("Rotary encoder monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int a = gpioRead(SENSOR_A_PIN);
        int b = gpioRead(SENSOR_B_PIN);

        if (a < 0 || b < 0) {
            fprintf(stderr, "Error reading GPIO pins\n");
            break;
        }

        int current_state = (a << 1) | b;

        if (current_state != last_state) {
            int delta = (current_state - last_state) & 0x03;
            if (delta == 1) {
                count++;
            } else if (delta == 3) {
                count--;
            }
            last_state = current_state;
        }

        float angle = (float)count / PULSES_PER_REV * 360.0f;

        if (log_event(angle) != 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        gpioDelay(10000);
    }

    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

