/*
 * ADPD144RI IR/Red photometric sensor reader with LED alert.
 * Board:  Raspberry Pi 3 Model B+
 * Library: libgpiod (for GPIO 17) + Linux I2C character-device interface.
 *
 * Build:  gcc -O2 -Wall -Wextra -o adpd144ri adpd144ri.c -lgpiod
 * Run:    ./adpd144ri
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>

/* ---- ADPD144RI constants (16-bit, 7-bit address 0x39) ---- */
#define I2C_BUS          "/dev/i2c-1"
#define ADPD144RI_ADDR   0x39
#define FIFO_DATA_REG    0x60
#define LED_GPIO_LINE    17
#define IR_THRESHOLD     2000
#define SAMPLE_MS        100

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_log_fp   = NULL;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_led  = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_led) {
        gpiod_line_set_value(g_led, 0);
        gpiod_line_release(g_led);
        g_led = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t cmd = reg;
    uint8_t data[2];

    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((data[0] << 8) | data[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_i2c(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                ADPD144RI_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "Cannot open gpiochip0: %s\n", strerror(errno));
        return -1;
    }
    g_led = gpiod_chip_get_line(g_chip, LED_GPIO_LINE);
    if (!g_led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                LED_GPIO_LINE, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(g_led, "adpd144ri-led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                LED_GPIO_LINE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_log(void)
{
    g_log_fp = fopen("adpd144ri_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open log file: %s\n", strerror(errno));
        return -1;
    }
    setvbuf(g_log_fp, NULL, _IOLBF, 0);
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    fprintf(g_log_fp, "%s,%u,%u\n", ts, red, ir);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Quick presence check: try reading the FIFO data register. */
    uint16_t dummy;
    if (i2c_read_reg16(g_i2c_fd, FIFO_DATA_REG, &dummy) < 0) {
        fprintf(stderr, "ADPD144RI not responding at 0x%02X on %s\n",
                ADPD144RI_ADDR, I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_log() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADPD144RI monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t red, ir;

        if (i2c_read_reg16(g_i2c_fd, FIFO_DATA_REG, &red) < 0 ||
            i2c_read_reg16(g_i2c_fd, FIFO_DATA_REG, &ir) < 0) {
            fprintf(stderr, "Sensor read error — continuing.\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        log_data(red, ir);

        int led = (ir > IR_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(g_led, led) < 0) {
            fprintf(stderr, "Failed to set LED: %s\n", strerror(errno));
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

