#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x39
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"
#define SAMPLE_DELAY_MS 100

/* ADPD144RI register addresses */
#define REG_PART_ID 0x00
#define REG_FIFO_DATA 0x04
#define REG_FIFO_STATUS 0x05
#define REG_INT_STATUS 0x06
#define REG_INT_MASK 0x07
#define REG_MODE 0x08
#define REG_LED1 0x09
#define REG_LED2 0x0A
#define REG_LED3 0x0B
#define REG_LED4 0x0C
#define REG_LED5 0x0D
#define REG_LED6 0x0E
#define REG_LED7 0x0F
#define REG_LED8 0x10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int adpd144ri_init(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADPD144RI_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    uint8_t part_id;
    if (i2c_read_reg8(i2c_fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "ADPD144RI not responding at address 0x%02X\n", ADPD144RI_ADDR);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    printf("ADPD144RI detected (PART_ID=0x%02X)\n", part_id);

    /* Configure LED channels (example values) */
    if (i2c_write_reg8(i2c_fd, REG_LED1, 0x7F) < 0) return -1;
    if (i2c_write_reg8(i2c_fd, REG_LED2, 0x7F) < 0) return -1;
    if (i2c_write_reg8(i2c_fd, REG_LED3, 0x7F) < 0) return -1;
    if (i2c_write_reg8(i2c_fd, REG_LED4, 0x7F) < 0) return -1;
    if (i2c_write_reg8(i2c_fd, REG_LED5, 0x7F) < 0) return -1;
    if (i2c_write_reg8(i2c_fd, REG_LED6, 0x7F) < 0) return -1;
    if (i2c_write_reg8(i2c_fd, REG_LED7, 0x7F) < 0) return -1;
    if (i2c_write_reg8(i2c_fd, REG_LED8, 0x7F) < 0) return -1;

    /* Clear any pending interrupts */
    if (i2c_write_reg8(i2c_fd, REG_INT_STATUS, 0xFF) < 0) return -1;

    /* Enable all interrupts */
    if (i2c_write_reg8(i2c_fd, REG_INT_MASK, 0x00) < 0) return -1;

    /* Start continuous mode */
    if (i2c_write_reg8(i2c_fd, REG_MODE, 0x01) < 0) return -1;

    return 0;
}

static int read_sensor_data(uint16_t *red, uint16_t *ir) {
    uint8_t status;
    if (i2c_read_reg8(i2c_fd, REG_FIFO_STATUS, &status) < 0) return -1;

    if ((status & 0x01) == 0) {
        /* FIFO not full — skip this sample */
        return 1;
    }

    if (i2c_read_reg16(i2c_fd, REG_FIFO_DATA, red) < 0) return -1;
    if (i2c_read_reg16(i2c_fd, REG_FIFO_DATA, ir) < 0) return -1;

    return 0;
}

static void control_led(int on) {
    if (led_line) {
        gpiod_line_set_value(led_line, on ? 1 : 0);
    }
}

static void log_data(uint16_t red, uint16_t ir) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%u,%u\n", timestamp, red, ir);
    fflush(log_file);
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (adpd144ri_init() < 0) {
        fprintf(stderr, "ADPD144RI initialization failed\n");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "adpd144ri_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Starting data acquisition. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t red, ir;
        int ret = read_sensor_data(&red, &ir);

        if (ret == 0) {
            log_data(red, ir);
            control_led(ir > IR_THRESHOLD ? 1 : 0);
        } else if (ret < 0) {
            fprintf(stderr, "I2C read error — continuing\n");
        }

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

