#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x70
#define LOG_FILE "air_quality_log.csv"
#define READ_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, uint8_t *buf, int len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int rc = i2cReadI2CBlockData(handle, 0x00, (char *)buf, len);
        if (rc == len) return 0;
        fprintf(stderr, "I2C read failed (rc=%d), retry %d/%d\n", rc, retries + 1, MAX_RETRIES);
        retries++;
        gpioDelay(100000);
    }
    return -1;
}

static int parse_sensor_data(const uint8_t *buf, int *tvoc, int *eco2) {
    if (buf[0] != 0x00) {
        fprintf(stderr, "Unexpected state byte 0x%02X\n", buf[0]);
        return -1;
    }
    *tvoc = (buf[1] << 8) | buf[2];
    *eco2 = (buf[5] << 8) | buf[6];
    return 0;
}

static float calculate_iaq(int tvoc) {
    float eco2 = (float)tvoc * 10.0f;
    float diff = (float)tvoc - 400.0f;
    if (diff < 0.0f) diff = 0.0f;
    float iaq = 100.0f - (eco2 / 10.0f) - (diff / 50.0f);
    if (iaq < 0.0f) iaq = 0.0f;
    if (iaq > 100.0f) iaq = 100.0f;
    return iaq;
}

static int log_data(FILE *fp, float iaq, int tvoc, int eco2) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%d,%d\n", ts, iaq, tvoc, eco2) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (rc=%d)\n", i2c_handle);
        gpioTerminate();
