#define LOG_FILE "air_quality_log.csv"
#define READ_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, uint8_t *buf, int len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int rc = i2cReadI2CBlockData(handle, 0x00, (char *)buf, len);
        if (rc == len) return 0;
        fprintf(stderr, "I2C read failed (rc=%d), retry %d/%d\n", rc, retries + 1, MAX_RETRIES);
        retries++;
        gpioDelay(100000);
    }
    return -1;
}

static int parse_sensor_data(const uint8_t *buf, int *tvoc, int *eco2) {
    if (buf[0] != 0x00) {
        fprintf(stderr, "Unexpected state byte 0x%02X\n", buf[0]);
        return -1;
    }
    *tvoc = (buf[1] << 8) | buf[2];
    *eco2 = (buf[5] << 8) | buf[6];
    return 0;
}

static float calculate_iaq(int tvoc) {
    float eco2 = (float)tvoc * 10.0f;
    float diff = (float)tvoc - 400.0f;
    if (diff < 0.0f) diff = 0.0f;
    float iaq = 100.0f - (eco2 / 10.0f) - (diff / 50.0f);
    if (iaq < 0.0f) iaq = 0.0f;
    if (iaq > 100.0f) iaq = 100.0f;
    return iaq;
}

