#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_MS 100
#define INTRUSION_THRESHOLD_S 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line, "ttp223_tamper") < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring TTP223B touch sensor on GPIO %d (active-high). "
           "Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    struct timespec last_touch_time = {0, 0};
    int last_value = -1;

    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
            goto cleanup;
        }

        if (value != last_value) {
            if (value == 1) {
                if (clock_gettime(CLOCK_MONOTONIC, &last_touch_time) == -1) {
                    fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
                    goto cleanup;
                }
                printf("Touch detected on GPIO %d\n", GPIO_LINE_OFFSET);
                fflush(stdout);
            } else {
                last_touch_time.tv_sec = 0;
                last_touch_time.tv_nsec = 0;
            }
            last_value = value;
        }

        if (value == 1) {
            struct timespec now;
            if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) {
                fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
                goto cleanup;
            }

            long elapsed_ms = (now.tv_sec - last_touch_time.tv_sec) * 1000L +
                              (now.tv_nsec - last_touch_time.tv_nsec) / 1000000L;

            if (elapsed_ms >= INTRUSION_THRESHOLD_S * 1000L) {
                printf("INTRUSION DETECTED! Touch held for %ld ms\n", elapsed_ms);
                fflush(stdout);
                last_touch_time = now;
            }
        }

        struct timespec sleep_ts = {0, POLL_INTERVAL_MS * 1000000L};
        nanosleep(&sleep_ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("Exiting cleanly.\n");

    return ret;
}

