#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <gpiod.h>

#define PCM_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define SAMPLE_RATE 48000
#define BITS_PER_SAMPLE 16
#define NUM_CHANNELS 1
#define BUFFER_SIZE 4096
#define PCM_BUFFER_SIZE (BUFFER_SIZE * NUM_CHANNELS)

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_i2s_frame(int pcm_fd, int16_t *sample) {
    uint8_t buffer[4];
    ssize_t bytes_read = read(pcm_fd, buffer, sizeof(buffer));
    if (bytes_read != (ssize_t)sizeof(buffer)) {
        if (bytes_read < 0) {
            fprintf(stderr, "I2S read error: %s\n", strerror(errno));
        } else {
            fprintf(stderr, "I2S read incomplete: %zd bytes\n", bytes_read);
        }
        return -1;
    }
    uint32_t raw = ((uint32_t)buffer[0] << 24) |
                   ((uint32_t)buffer[1] << 16) |
                   ((uint32_t)buffer[2] << 8)  |
                   ((uint32_t)buffer[3]);
    *sample = (int16_t)(raw >> 8);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "inmp441-lr-select", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int pcm_fd = open(PCM_DEVICE, O_RDONLY);
    if (pcm_fd < 0) {
        fprintf(stderr, "Failed to open PCM device %s: %s\n", PCM_DEVICE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int format = AFMT_S16_LE;
    if (ioctl(pcm_fd, SNDCTL_DSP_SETFMT, &format) == -1) {
        fprintf(stderr, "Failed to set DSP format: %s\n", strerror(errno));
        close(pcm_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int channels = NUM_CHANNELS;
    if (ioctl(pcm_fd, SNDCTL_DSP_CHANNELS, &channels) == -1) {
        fprintf(stderr, "Failed to set DSP channels: %s\n", strerror(errno));
        close(pcm_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int rate = SAMPLE_RATE;
    if (ioctl(pcm_fd, SNDCTL_DSP_SPEED, &rate) == -1) {
        fprintf(stderr, "Failed to set DSP sample rate: %s\n", strerror(errno));
        close(pcm_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen("audio_capture.pcm", "wb");
    if (!fp) {
        fprintf(stderr, "Failed to open audio file: %s\n", strerror(errno));
        close(pcm_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int16_t *buffer = malloc(PCM_BUFFER_SIZE);
    if (!buffer) {
        fprintf(stderr, "Failed to allocate buffer: %s\n", strerror(errno));
        fclose(fp);
        close(pcm_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Audio capture started. Press Ctrl+C to stop.\n");

    while (running) {
        size_t samples_read = 0;
        while (samples_read < BUFFER_SIZE && running) {
            int16_t sample;
            if (read_i2s_frame(pcm_fd, &sample) == -1) {
                break;
            }
            buffer[samples_read++] = sample;
        }

        if (samples_read > 0) {
            size_t bytes_written = fwrite(buffer, sizeof(int16_t), samples_read, fp);
            if (bytes_written != samples_read) {
                fprintf(stderr, "File write error: %s\n", strerror(errno));
                break;
            }
        }

        if (samples_read == 0 && !running) {
            break;
        }
    }

    printf("\nAudio capture stopped.\n");

    free(buffer);
    fclose(fp);
    close(pcm_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Audio capture complete.\n");
    return EXIT_SUCCESS;
}

