            if (read_i2s_frame(pcm_fd, &sample) == -1) {
                break;
            }
            buffer[samples_read++] = sample;
        }

        if (samples_read > 0) {
            size_t bytes_written = fwrite(buffer, sizeof(int16_t), samples_read, fp);
            if (bytes_written != samples_read) {
                fprintf(stderr, "File write error: %s\n", strerror(errno));
                break;
            }
        }

        if (samples_read == 0 && !running) {
            break;
        }
    }

    printf("\nAudio capture stopped.\n");

    free(buffer);
    fclose(fp);
    close(pcm_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Audio capture complete.\n");
    return EXIT_SUCCESS;
}

