#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define PWM_FREQUENCY 100
#define DEBOUNCE_DELAY_US 50000
#define POLL_DELAY_US 50000
#define TIMEOUT_SEC 10
#define LOG_FILE "flame_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s %s\n", ts, message);
    }
    fclose(fp);
}

static int read_flame_sensor(void) {
    int v = gpioRead(FLAME_SENSOR_PIN);
    if (v < 0) {
        log_event("ERROR: gpioRead failed on FLAME_SENSOR_PIN");
        return -1;
    }
    return v;
}

static void set_fan_pwm(int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    int pwm = (duty_percent * 255) / 100;
    if (gpioPWM(FAN_PIN, pwm) < 0) {
        log_event("ERROR: gpioPWM failed on FAN_PIN");
    }
}

static void cleanup(void) {
    set_fan_pwm(0);
    gpioWrite(FAN_PIN, 0);
    gpioWrite(FLAME_SENSOR_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set FLAME_SENSOR_PIN as input\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set FAN_PIN as output\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on FAN_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_PIN, 255) < 0) {
        fprintf(stderr, "Failed to set PWM range on FAN_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("System started");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    int flame_active = 0;
    time_t flame_start = 0;
    int last_flame = -1;

    while (running) {
        int flame = read_flame_sensor();
        if (flame < 0) {
            log_event("ERROR: flame sensor read failure");
            break;
        }

        if (flame != last_flame) {
            if (flame == 0) {
                flame_start = time(NULL);
                flame_active = 1;
                log_event("Flame detected");
            } else {
                if (flame_active) {
                    time_t now = time(NULL);
                    if (difftime(now, flame_start) > TIMEOUT_SEC) {
                        log_event("Flame ended (timeout)");
                    } else {
                        log_event("Flame ended");
                    }
                    flame_active = 0;
                }
            }
            last_flame = flame;
        }

        if (flame_active) {
            time_t now = time(NULL);
            double elapsed = difftime(now, flame_start);
            int duty = (int)(elapsed * 8.0);
            if (duty > 100) duty = 100;
            set_fan_pwm(duty);
        } else {
            set_fan_pwm(0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("System shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

