#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_MODE    0
#define TRIGGER_PIN 23
#define DATA_READY_PIN 24
#define DATA_SIZE   32768
#define LOG_FILE    "radar_log.bin"

typedef struct {
    uint32_t magic;
    uint8_t  timestamp[8];
    uint32_t start_freq;
    uint32_t end_freq;
    uint32_t num_chirps;
    uint32_t num_samples;
    uint32_t frame_period_ms;
} __attribute__((packed)) RadarConfig;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) return -1;
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) < 0) return -1;
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1;
    return 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int read_spi_data(uint8_t *data, int len) {
    int ret = spiXfer(spi_handle, (char *)data, (char *)data, len);
    if (ret != len) {
        fprintf(stderr, "spiXfer failed: %s\n", pigpio_error(ret));
        return -1;
    }
    return 0;
}

static int log_frame(uint8_t *data, int frame_num) {
    uint8_t ts[8];
    struct timespec ts_spec;
    clock_gettime(CLOCK_REALTIME, &ts_spec);
    memcpy(ts, &ts_spec, sizeof(ts));
    if (fwrite(ts, 1, sizeof(ts), log_file) != sizeof(ts)) return -1;
    if (fwrite(&frame_num, 1, sizeof(frame_num), log_file) != sizeof(frame_num)) return -1;
    if (fwrite(data, 1, DATA_SIZE, log_file) != (size_t)DATA_SIZE) return -1;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO init failed\n");
        gpioTerminate();
        return 1;
    }

    if (init_spi() < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "wb");
    if (!log_file) {
        perror("fopen");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    RadarConfig cfg;
    cfg.magic = 0x52444144;
    cfg.start_freq = 77000;
    cfg.end_freq = 79000;
    cfg.num_chirps = 64;
    cfg.num_samples = 256;
    cfg.frame_period_ms = 100;

    if (fwrite(&cfg, 1, sizeof(cfg), log_file) != sizeof(cfg)) {
        perror("fwrite config");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Radar logging started. Press Ctrl+C to stop.\n");

    while (running) {
        if (gpioWrite(TRIGGER_PIN, 1) < 0) break;
        gpioDelay(1000);
        if (gpioWrite(TRIGGER_PIN, 0) < 0) break;

        int ready = 0;
        while (running && !ready) {
            ready = gpioRead(DATA_READY_PIN);
            if (ready < 0) break;
            gpioDelay(1000);
        }
        if (!running) break;
        if (ready < 0) break;

        uint8_t *data = malloc(DATA_SIZE);
        if (!data) {
            fprintf(stderr, "malloc failed\n");
            break;
        }

        if (read_spi_data(data, DATA_SIZE) < 0) {
            free(data);
            break;
        }

        uint32_t frame_num = 0;
        if (fread(&frame_num, 1, sizeof(frame_num), log_file) != sizeof(frame_num)) {
            fprintf(stderr, "Failed to write frame number\n");
            free(data);
            break;
        }

        if (log_frame(data, frame_num) < 0) {
            fprintf(stderr, "Log write failed\n");
            free(data);
            break;
        }

        free(data);
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

