#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3001_ADDR 0x44
#define REG_RESULT 0x00
#define REG_CONFIG 0x01
#define REG_MANUFACTURER_ID 0x7E
#define REG_DEVICE_ID 0x7F
#define EXPECTED_MANUFACTURER_ID 0x5449
#define EXPECTED_DEVICE_ID 0x3001

#define CONFIG_CONTINUOUS 0x0000
#define CONFIG_100MS 0x0000
#define CONFIG_AUTO_RANGE 0x0000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register16(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int write_register16(int handle, uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 3);
}

static int configure_sensor(int handle) {
    uint16_t manuf_id, dev_id;
    if (read_register16(handle, REG_MANUFACTURER_ID, &manuf_id) < 0) {
        fprintf(stderr, "Error: Failed to read manufacturer ID.\n");
        return -1;
    }
    if (manuf_id != EXPECTED_MANUFACTURER_ID) {
        fprintf(stderr, "Error: Manufacturer ID mismatch (0x%04X, expected 0x%04X).\n", manuf_id, EXPECTED_MANUFACTURER_ID);
        return -1;
    }
    if (read_register16(handle, REG_DEVICE_ID, &dev_id) < 0) {
        fprintf(stderr, "Error: Failed to read device ID.\n");
        return -1;
    }
    if (dev_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Error: Device ID mismatch (0x%04X, expected 0x%04X).\n", dev_id, EXPECTED_DEVICE_ID);
        return -1;
    }
    uint16_t config = CONFIG_CONTINUOUS | CONFIG_100MS | CONFIG_AUTO_RANGE;
    if (write_register16(handle, REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error: Failed to write configuration register.\n");
        return -1;
    }
    return 0;
}

static int read_lux(int handle, float *lux_out) {
    uint16_t raw;
    if (read_register16(handle, REG_RESULT, &raw) < 0) {
        fprintf(stderr, "Error: Failed to read result register.\n");
        return -1;
    }
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    *lux_out = 0.01f * (float)(1 << exponent) * (float)mantissa;
    return 0;
}

static void log_data(FILE *fp, float lux) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f\n", timestamp, lux);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X.\n", OPT3001_ADDR);
        gpioTerminate();
        return 1;
    }

    if (configure_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Error: Sensor configuration failed. Check wiring and address.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("OPT3001 initialized. Logging to light_data.txt. Press Ctrl+C to stop.\n");

    while (running) {
        float lux;
        if (read_lux(i2c_handle, &lux) == 0) {
            log_data(log_file, lux);
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Warning: Read failed, retrying...\n");
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

