#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    if (signum == SIGINT) {
        program_running = 0;
    }
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *line_settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_request *line_req = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure line settings: input with pull-up bias */
    line_settings = gpiod_line_settings_new();
    if (line_settings == NULL) {
        fprintf(stderr, "Error: Failed to allocate line settings: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_settings_set_direction(line_settings, GPIOD_LINE_DIRECTION_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set line direction: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_settings_set_bias(line_settings, GPIOD_LINE_BIAS_PULL_UP) != 0) {
        fprintf(stderr, "Error: Failed to set line bias: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure the line with the settings */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "Error: Failed to allocate line config: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_config_add_line_settings(line_cfg, &(unsigned int){GPIO_LINE_OFFSET}, 1, line_settings) != 0) {
        fprintf(stderr, "Error: Failed to add line settings: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request config */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "Error: Failed to allocate request config: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_request_config_set_consumer(req_cfg, "flame_detect") != 0) {
        fprintf(stderr, "Error: Failed to set consumer: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request the line */
    line_req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (line_req == NULL) {
        fprintf(stderr, "Error: Failed to request GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Flame detection system started on GPIO line %d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    /* Main polling loop */
    while (program_running) {
        int value = gpiod_line_request_get_value(line_req, GPIO_LINE_OFFSET);
        if (value < 0) {
            fprintf(stderr, "Error: Failed to read GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup;
        }

        char timestamp[32];
        if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
            fprintf(stderr, "Error: Failed to get timestamp: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("%s Flame Detected: %s\n", timestamp, (value == 0) ? "YES" : "NO");
        fflush(stdout);

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line_req != NULL) {
        gpiod_line_request_release(line_req);
    }
    if (req_cfg != NULL) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (line_settings != NULL) {
        gpiod_line_settings_free(line_settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

