#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 100

static const unsigned int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int ret;
    int i;

    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = NULL;
    }

    /* Open the default gpiochip (gpiochip0 on Pi Zero W) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get each line and request it as input */
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error: Failed to get GPIO line %u: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }

        ret = gpiod_line_request_input(lines[i], "ttp226-touch");
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to request GPIO line %u as input: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler: %s\n", strerror(errno));
    }

    printf("TTP226 Touch Sensor Reader (libgpiod)\n");
    printf("Channels: BCM GPIO %u, %u, %u, %u, %u, %u, %u, %u\n",
           channel_pins[0], channel_pins[1], channel_pins[2], channel_pins[3],
           channel_pins[4], channel_pins[5], channel_pins[6], channel_pins[7]);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main polling loop */
    while (running) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error: Failed to read GPIO line %u: %s\n",
                        channel_pins[i], strerror(errno));
                continue;
            }
            printf("Channel %d: %d\n", i + 1, val);
        }
        printf("---\n");
        fflush(stdout);

        /* Sleep 100 ms, checking running flag every 10 ms for responsive shutdown */
        for (int ms = 0; ms < POLL_INTERVAL_MS && running; ms += 10) {
            usleep(10000);
        }
    }

    printf("\nExiting gracefully...\n");

cleanup:
    /* Release all lines and close chip */
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return (running == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

