#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TILT_GPIO 4
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void log_tilt_event(int tilt_state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("%s - Tilt State: %s\n", timestamp,
           tilt_state ? "Tilted" : "Not Tilted");
    fflush(stdout);
}

int main(void)
{
    int last_tilt_state = -1;
    int ret;

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO 4 as input with internal pull-up --- */
    if (gpioSetMode(TILT_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TILT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", TILT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Allow pull-up to settle (internal pull-up is fast) --- */
    gpioDelay(10000);  /* 10 ms */

    printf("Tilt sensor monitoring started on GPIO %d.\n", TILT_GPIO);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        int tilt_state = gpioRead(TILT_GPIO);

        if (tilt_state < 0) {
            fprintf(stderr, "gpioRead failed on GPIO %d (code %d)\n",
                    TILT_GPIO, tilt_state);
            break;
        }

        if (tilt_state != last_tilt_state) {
            log_tilt_event(tilt_state);
            last_tilt_state = tilt_state;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

