#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR 0x60
#define I2C_BUS 1

#define REG_PART_ID 0x00
#define REG_HW_KEY 0x07
#define REG_MEAS_RATE0 0x08
#define REG_ALS_VIS_DATA0 0x22
#define REG_UV_INDEX0 0x2C
#define REG_COMMAND 0x30
#define REG_CHLIST 0x01

#define CMD_ALS_FORCE 0x06
#define CMD_RESET 0x01

#define HW_KEY_VAL 0x17
#define PART_ID_VAL 0x45

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int si1145_write(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %d\n", value, reg, rc);
    }
    return rc;
}

static int si1145_read(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int si1145_init(void) {
    uint8_t part_id = 0;

    if (si1145_read(REG_PART_ID, &part_id) < 0) {
        return -1;
    }
    if (part_id != PART_ID_VAL) {
        fprintf(stderr, "Unexpected PART ID: 0x%02X (expected 0x%02X)\n", part_id, PART_ID_VAL);
        return -1;
    }

    if (si1145_write(REG_HW_KEY, HW_KEY_VAL) < 0) {
        return -1;
    }

    if (si1145_write(REG_MEAS_RATE0, 0x00) < 0) {
        return -1;
    }

    if (si1145_write(REG_CHLIST, 0x03) < 0) {
        return -1;
    }

    if (si1145_write(REG_COMMAND, CMD_RESET) < 0) {
        return -1;
    }
    gpioDelay(10000);

    if (si1145_write(REG_COMMAND, CMD_ALS_FORCE) < 0) {
        return -1;
    }
    gpioDelay(10000);

    return 0;
}

static int read_uv_index(float *uv_index) {
    uint8_t msb = 0, lsb = 0;

    if (si1145_read(REG_UV_INDEX0, &msb) < 0) return -1;
    if (si1145_read(REG_UV_INDEX0 + 1, &lsb) < 0) return -1;

    uint16_t raw = ((uint16_t)msb << 8) | lsb;
    *uv_index = (float)raw / 10.0f;
    return 0;
}

static int read_als_visible(uint16_t *als_visible) {
    uint8_t msb = 0, lsb = 0;

    if (si1145_read(REG_ALS_VIS_DATA0, &msb) < 0) return -1;
    if (si1145_read(REG_ALS_VIS_DATA0 + 1, &lsb) < 0) return -1;

    *als_visible = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static void log_data(float uv_index, uint16_t als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%u\n", timestamp, uv_index, als_visible);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, SI1145_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (si1145_init() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
    }

    printf("Si1145 initialized. Logging to uv_als_log.csv. Press Ctrl+C to stop.\n");

    while (!terminate) {
        float uv_index = 0.0f;
        uint16_t als_visible = 0;

        if (read_uv_index(&uv_index) < 0) {
            fprintf(stderr, "Error reading UV index\n");
        } else if (read_als_visible(&als_visible) < 0) {
            fprintf(stderr, "Error reading ALS data\n");
        } else {
            log_data(uv_index, als_visible);
            printf("UV Index: %.2f, ALS Visible: %u\n", uv_index, als_visible);
        }

        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

