#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define GPIO_CHIP "gpiochip4"
#define ALARM_GPIO_LINE 17
#define FLOW_THRESHOLD 0.5f
#define FLOW_SCALE_FACTOR 0.036f
#define MEASUREMENT_DELAY_MS 100
#define LOOP_DELAY_MS 1000

static volatile sig_atomic_t running = 1;
static int i2c_fd1 = -1, i2c_fd2 = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *alarm_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t reg, uint16_t cmd) {
    uint8_t buf[3] = {reg, (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF)};
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int init_sensor(int fd, uint8_t addr) {
    if (ioctl(i2c_fd1, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    if (i2c_write_cmd(fd, 0x08, 0x3608) < 0) {
        fprintf(stderr, "Failed to start measurement on 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    usleep(MEASUREMENT_DELAY_MS * 1000);
    return 0;
}

static int read_flow_rate(int fd, uint8_t addr, float *flow_rate) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    uint8_t buf[9];
    if (i2c_read_reg(fd, 0x00, buf, 9) < 0) {
        fprintf(stderr, "Failed to read flow data from 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data from 0x%02X\n", addr);
        return -1;
    }
    int16_t raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw_flow * FLOW_SCALE_FACTOR;
    return 0;
}

static void log_flow_rate(float flow1, float flow2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    float avg = (flow1 + flow2) / 2.0f;
    fprintf(log_file, "%s, Flow1: %.2f ml/min, Flow2: %.2f ml/min, Avg: %.2f ml/min\n",
            ts, flow1, flow2, avg);
    fflush(log_file);
}

static void cleanup(void) {
    if (alarm_line) {
        gpiod_line_set_value(alarm_line, 0);
        gpiod_line_release(alarm_line);
        alarm_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd1 >= 0) { close(i2c_fd1); i2c_fd1 = -1; }
    if (i2c_fd2 >= 0) { close(i2c_fd2); i2c_fd2 = -1; }
    if (log_file) { fclose(log_file); log_file = NULL; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        perror("Failed to open flow_log.txt");
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return 1;
    }
    alarm_line = gpiod_chip_get_line(chip, ALARM_GPIO_LINE);
    if (!alarm_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }
    if (gpiod_line_request_output(alarm_line, "flow_alarm", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    i2c_fd1 = open(I2C_BUS, O_RDWR);
    if (i2c_fd1 < 0) {
        perror("Failed to open I2C bus");
        cleanup();
        return 1;
    }
    i2c_fd2 = open(I2C_BUS, O_RDWR);
    if (i2c_fd2 < 0) {
        perror("Failed to open I2C bus");
        cleanup();
        return 1;
    }

    if (init_sensor(i2c_fd1, SENSOR1_ADDR) < 0 || init_sensor(i2c_fd2, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = read_flow_rate(i2c_fd1, SENSOR1_ADDR, &flow1);
        int ok2 = read_flow_rate(i2c_fd2, SENSOR2_ADDR, &flow2);

        if (ok1 < 0 || ok2 < 0) {
            fprintf(stderr, "Sensor read error, skipping cycle\n");
        } else {
            log_flow_rate(flow1, flow2);
            int alarm = (flow1 + flow2) / 2.0f < FLOW_THRESHOLD ? 1 : 0;
            gpiod_line_set_value(alarm_line, alarm);
        }
        usleep(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

