#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x55
#define CSV_FILE       "fan_health.csv"
#define SAMPLE_PERIOD  500000   /* microseconds */
#define MAX_INIT_WAIT  1000000  /* microseconds (1 s) */

/* D7S register addresses */
#define REG_MODE_CONTROL  0x1D
#define REG_OPERATING_STATUS 0x1B
#define REG_X_LSB         0x2A
#define REG_X_MSB         0x2B
#define REG_Y_LSB         0x2C
#define REG_Y_MSB         0x2D
#define REG_Z_LSB         0x2E
#define REG_Z_MSB         0x2F

/* Scaling factor: 0.0009765625 g/LSB (16-bit signed, 1 LSB = 0.0009765625 g) */
#define SCALE_FACTOR      0.0009765625f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t wbuf[1] = { reg };
    uint8_t rbuf[2] = { 0, 0 };
    ssize_t n;

    n = write(fd, wbuf, sizeof(wbuf));
    if (n != (ssize_t)sizeof(wbuf)) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    n = read(fd, rbuf, sizeof(rbuf));
    if (n != (ssize_t)sizeof(rbuf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (int16_t)((uint16_t)rbuf[0] | ((uint16_t)rbuf[1] << 8));
    return 0;
}

static int init_d7s(int fd)
{
    /* Switch to active mode (MODE_CONTROL = 0x10) */
    if (i2c_write_reg8(fd, REG_MODE_CONTROL, 0x10) != 0)
        return -1;

    /* Poll operating status bit 0 until it reads 1 (active) */
    for (int waited = 0; waited < MAX_INIT_WAIT; waited += 10000) {
        int16_t status = 0;
        if (i2c_read_reg16(fd, REG_OPERATING_STATUS, &status) != 0)
            return -1;
        if (status & 0x01)
            return 0;
        usleep(10000);
    }

    fprintf(stderr, "D7S operating status did not become active within %d us\n",
            MAX_INIT_WAIT);
    return -1;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    if (i2c_read_reg16(fd, REG_X_LSB, x) != 0) return -1;
    if (i2c_read_reg16(fd, REG_Y_LSB, y) != 0) return -1;
    if (i2c_read_reg16(fd, REG_Z_LSB, z) != 0) return -1;
    return 0;
}

static void log_csv(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    float gx = (float)x * SCALE_FACTOR;
    float gy = (float)y * SCALE_FACTOR;
    float gz = (float)z * SCALE_FACTOR;

