#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_THRESHOLD_SEC 2
#define LOG_FILE "stall_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int gpio) {
    int v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio, pigpio_error(v));
        return -1;
    }
    return v;
}

static int detect_stall(void) {
    int s1 = read_sensor(SENSOR_1_GPIO);
    int s2 = read_sensor(SENSOR_2_GPIO);
    if (s1 < 0 || s2 < 0) {
        return 0;  /* error already reported */
    }
    /* E18-D80NK: LOW = object detected, HIGH = clear */
    return (s1 == 0 && s2 == 0) ? 1 : 0;
}

static void log_stall_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s - Stall detected on GPIO %d and GPIO %d\n",
                timestamp, SENSOR_1_GPIO, SENSOR_2_GPIO) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", LOG_FILE, strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* E18-D80NK: enable internal pull-up so the line is defined when sensor is absent */
    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring conveyor belt on GPIO %d and GPIO %d. Press Ctrl+C to exit.\n",
           SENSOR_1_GPIO, SENSOR_2_GPIO);

    int stall_active = 0;
    time_t stall_start = 0;

    while (running) {
        if (detect_stall()) {
            if (!stall_active) {
                stall_active = 1;
                stall_start = time(NULL);
                printf("Stall detected!\n");
            } else {
                time_t now = time(NULL);
                if (now - stall_start >= STALL_THRESHOLD_SEC) {
                    log_stall_event();
                    stall_active = 0;
                    printf("Stall confirmed and logged.\n");
                }
            }
        } else {
            if (stall_active) {
                stall_active = 0;
                printf("Stall cleared.\n");
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

