    if (fprintf(fp, "%s - Stall detected on GPIO %d and GPIO %d\n",
                timestamp, SENSOR_1_GPIO, SENSOR_2_GPIO) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", LOG_FILE, strerror(errno));
