#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* TMAG5170-Q1 I2C address (A0=A1=0) */
#define TMAG5170_ADDR 0x0E

/* TMAG5170 register addresses */
#define REG_DEVICE_ID   0x00
#define REG_X_CH_RESULT 0x04
#define REG_Y_CH_RESULT 0x06
#define REG_Z_CH_RESULT 0x08
#define REG_CONFIG      0x01

/* Expected device ID for TMAG5170-Q1 */
#define TMAG5170_DEVICE_ID 0x8D

/* 50 mT range: LSB scale factor = 0.0001 mT/LSB */
#define LSB_SCALE_50MT 0.0001f

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Global resources for signal handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; cleanup happens in main()           */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a TMAG5170 register                          */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int tmag_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian result from a TMAG5170 axis register     */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int tmag_read_axis(uint8_t reg, float *out_mT)
{
    int raw = i2cReadWordData(i2c_handle, reg);
    if (raw < 0) {
        fprintf(stderr, "Error: i2cReadWordData(reg=0x%02X) failed: %d\n", reg, raw);
        return -1;
    }

    /* pigpio returns data as (low_byte << 8) | high_byte; TMAG5170
       sends MSB first over I2C, so swap bytes to get the signed
       16-bit value. */
    int16_t signed_raw = (int16_t)(((raw & 0xFF) << 8) | ((raw >> 8) & 0xFF));

    *out_mT = (float)signed_raw * LSB_SCALE_50MT;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify the device ID register — sensor presence check               */
/* ------------------------------------------------------------------ */
static int verify_device_id(void)
{
    int id = i2cReadByteData(i2c_handle, REG_DEVICE_ID);
    if (id < 0) {
        fprintf(stderr, "Error: failed to read device ID register: %d\n", id);
        return -1;
    }
    if (id != TMAG5170_DEVICE_ID) {
        fprintf(stderr, "Error: unexpected device ID 0x%02X (expected 0x%02X)\n",
                id, TMAG5170_DEVICE_ID);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure the TMAG5170 for continuous-conversion mode               */
/* ------------------------------------------------------------------ */
static int configure_sensor(void)
{
    /*
     * Config register (0x01) — bit layout (16-bit, little-endian on wire):
     *   [15]   0   — reserved
     *   [14:12] 000 — continuous-conversion mode
     *   [11:9]  000 — auto-convert off
     *   [8]     0   — reserved
     *   [7:5]   000 — 50 mT range
     *   [4]     0   — reserved
     *   [3:2]   00  — 100 Hz output rate
     *   [1:0]   00  — all axes enabled
     * Binary: 0x0000
     */
    if (tmag_write_reg(REG_CONFIG, 0x0000) != 0) {
        fprintf(stderr, "Error: failed to configure TMAG5170\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one CSV row with ISO-8601 timestamp                             */
/* ------------------------------------------------------------------ */
static void log_data(float x_mT, float y_mT, float z_mT)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(log_file, "%s,%.4f,%.4f,%.4f\n", ts, x_mT, y_mT, z_mT);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the TMAG5170 address */
    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                TMAG5170_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence */
    if (verify_device_id() != 0) {
        fprintf(stderr, "Error: TMAG5170 not detected at address 0x%02X\n",
                TMAG5170_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure sensor */
    if (configure_sensor() != 0) {
        fprintf(stderr, "Error: sensor configuration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open magnetic_log.csv for append\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,x_mT,y_mT,z_mT\n");
        fflush(log_file);
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("TMAG5170 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        float x_mT, y_mT, z_mT;

        if (tmag_read_axis(REG_X_CH_RESULT, &x_mT) != 0 ||
            tmag_read_axis(REG_Y_CH_RESULT, &y_mT) != 0 ||
            tmag_read_axis(REG_Z_CH_RESULT, &z_mT) != 0) {
            fprintf(stderr, "Warning: sensor read error — skipping sample\n");
        } else {
            log_data(x_mT, y_mT, z_mT);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

