#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_GPIO 23
#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL_SEC 2
#define REINIT_DELAY_SEC 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s %s\n", timestamp, message);
    fclose(fp);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }
    gpioSetMode(SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN);
    return 0;
}

static int read_sensor(void) {
    int value = gpioRead(SENSOR_GPIO);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", SENSOR_GPIO);
        return -1;
    }
    return value;
}

static void trigger_alert(void) {
    printf("ALERT: Water detected!\n");
    log_message("ALERT: Water detected!");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Water level monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_GPIO);

    time_t last_reinit = 0;

    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            log_message("ERROR: Sensor read failure, attempting re-initialization");
            if (last_reinit == 0 || (time(NULL) - last_reinit) >= REINIT_DELAY_SEC) {
                if (initialize_gpio() != 0) {
                    log_message("ERROR: Re-initialization failed");
                } else {
                    last_reinit = time(NULL);
                }
            }
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (sensor_value == 1) {
            trigger_alert();
        }

        sleep(POLL_INTERVAL_SEC);
    }

    gpioTerminate();
    printf("Water level monitoring stopped.\n");
    return 0;
}

