#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static atomic_int pulse_count = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;
    if (level == 1) {
