#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

#define SENSOR_A 17
#define SENSOR_B 27
#define LOG_FILE "rotation_log.txt"

static volatile int g_quadrature_state = 0;
static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *g_log_file = NULL;
static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void quadrature_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    if (gpio != SENSOR_A && gpio != SENSOR_B) return;

    int current_state = (gpio == SENSOR_A) ? level : 0;
    pthread_mutex_lock(&g_mutex);
    int prev = g_quadrature_state;
    g_quadrature_state = current_state;
    pthread_mutex_unlock(&g_mutex);

    if (prev == 0 && current_state == 1) {
        pthread_mutex_lock(&g_mutex);
        if (g_log_file) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            struct tm tm_info;
            localtime_r(&ts.tv_sec, &tm_info);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
            fprintf(g_log_file, "%s.%03ld: CW\n", timestamp, ts.tv_nsec / 1000000);
            fflush(g_log_file);
        }
        pthread_mutex_unlock(&g_mutex);
    } else if (prev == 1 && current_state == 0) {
        pthread_mutex_lock(&g_mutex);
        if (g_log_file) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            struct tm tm_info;
            localtime_r(&ts.tv_sec, &tm_info);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
            fprintf(g_log_file, "%s.%03ld: CCW\n", timestamp, ts.tv_nsec / 1000000);
            fflush(g_log_file);
        }
        pthread_mutex_unlock(&g_mutex);
    }
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_A, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_A);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SENSOR_B, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_B);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_A, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_A);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_B, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_B);
        gpioTerminate();
        return -1;
    }

    if (gpioSetAlertFunc(SENSOR_A, quadrature_callback) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", SENSOR_A);
        gpioTerminate();
        return -1;
    }
    if (gpioSetAlertFunc(SENSOR_B, quadrature_callback) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", SENSOR_B);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

