#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define TOUCH_SENSOR_GPIO 23
#define LED_GPIO 18
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    /* Open the default GPIO chip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        goto cleanup;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_GPIO);
    if (!touch_line) {
        syslog(LOG_ERR, "Failed to get touch sensor line %d: %s", TOUCH_SENSOR_GPIO, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        syslog(LOG_ERR, "Failed to get LED line %d: %s", LED_GPIO, strerror(errno));
        goto cleanup;
    }

    /* Request touch sensor line as input */
    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        syslog(LOG_ERR, "Failed to request touch sensor line as input: %s", strerror(errno));
        goto cleanup;
    }

    /* Request LED line as output, initial value LOW (off) */
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        syslog(LOG_ERR, "Failed to request LED line as output: %s", strerror(errno));
        goto cleanup;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install SIGINT handler: %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler: %s", strerror(errno));
        goto cleanup;
    }

    syslog(LOG_INFO, "Touch sensor and LED control started (GPIO %d, GPIO %d).", TOUCH_SENSOR_GPIO, LED_GPIO);

    int last_state = -1; /* Force initial log */

    while (program_running) {
        int val = gpiod_line_get_value(touch_line);
        if (val < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor: %s", strerror(errno));
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (val != last_state) {
            if (val == 1) {
                syslog(LOG_INFO, "Touch detected on GPIO %d", TOUCH_SENSOR_GPIO);
            } else {
                syslog(LOG_INFO, "Touch released on GPIO %d", TOUCH_SENSOR_GPIO);
            }
            last_state = val;
        }

        /* Drive LED state: 1 = touched, 0 = not touched */
        if (gpiod_line_set_value(led_line, val) < 0) {
            syslog(LOG_ERR, "Failed to set LED state: %s", strerror(errno));
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down gracefully.");
    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0); /* Ensure LED is off */
        gpiod_line_release(led_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    return ret;
}

