#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TOUCH_PIN 17
#define LED_PIN 18
#define DEBOUNCE_MS 50
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        fprintf(stderr, "Failed to get touch line (GPIO %d): %s\n", TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line (GPIO %d): %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(touch_line, "ttp223b-touch") < 0) {
        fprintf(stderr, "Failed to request touch line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "ttp223b-led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    int led_state = 0;
    int last_touch_state = 0;
    struct timespec last_event_time = {0, 0};

    while (running) {
        struct timespec ts = {0, POLL_TIMEOUT_MS * 1000000L};
        int ev = gpiod_line_event_wait(touch_line, &ts);

        if (ev < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error waiting for touch event: %s\n", strerror(errno));
            goto cleanup;
        }

        if (ev == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(touch_line, &event) < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error reading touch event: %s\n", strerror(errno));
            goto cleanup;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            continue;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        long elapsed_ms = (now.tv_sec - last_event_time.tv_sec) * 1000L +
                          (now.tv_nsec - last_event_time.tv_nsec) / 1000000L;

        if (elapsed_ms < DEBOUNCE_MS) {
            continue;
        }

        last_event_time = now;

        int touch_state = gpiod_line_get_value(touch_line);
        if (touch_state < 0) {
            fprintf(stderr, "Error reading touch sensor: %s\n", strerror(errno));
            continue;
        }

        if (touch_state != last_touch_state) {
            last_touch_state = touch_state;
            led_state = !led_state;
            if (gpiod_line_set_value(led_line, led_state) < 0) {
                fprintf(stderr, "Error writing LED: %s\n", strerror(errno));
            } else {
                printf("LED toggled to %s\n", led_state ? "ON" : "OFF");
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

