#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} TouchEvent;

static volatile sig_atomic_t running = 1;
static TouchEvent touch_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int overflow_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_1_PIN);
        return -1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_2_PIN);
        return -1;
    }

    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED on GPIO %d\n", LED_1_PIN);
        return -1;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED on GPIO %d\n", LED_2_PIN);
        return -1;
    }

    return 0;
}

static void log_touch_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Warning: time() failed\n");
        return;
    }

    int idx = buffer_index;
    touch_buffer[idx].sensor_pin = sensor_pin;
    touch_buffer[idx].timestamp = now;
    touch_buffer[idx].state = state;
    buffer_index = (idx + 1) % BUFFER_SIZE;

    if (idx == overflow_count) {
        overflow_count++;
    }
}

static void control_led(int sensor_pin, int state) {
    int led_pin = (sensor_pin == SENSOR_1_PIN) ? LED_1_PIN : LED_2_PIN;
    if (gpioWrite(led_pin, state) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d\n", led_pin);
    }
}

static void print_log_buffer(void) {
    printf("\n--- Touch Event Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index - overflow_count + i) % BUFFER_SIZE;
        if (idx < 0) idx += BUFFER_SIZE;
        if (touch_buffer[idx].sensor_pin != -1) {
            printf("Sensor %d, Timestamp: %ld, State: %d\n",
                   touch_buffer[idx].sensor_pin,
                   (long)touch_buffer[idx].timestamp,
                   touch_buffer[idx].state);
        }
    }
    printf("Overflow Count: %d\n", overflow_count);
    printf("-----------------------\n");
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: gpioRead failed (s1=%d, s2=%d)\n", s1, s2);
            break;
        }

        if (s1 == 1) {
            control_led(SENSOR_1_PIN, 1);
            log_touch_event(SENSOR_1_PIN, 1);
        } else {
            control_led(SENSOR_1_PIN, 0);
            log_touch_event(SENSOR_1_PIN, 0);
        }

        if (s2 == 1) {
            control_led(SENSOR_2_PIN, 1);
            log_touch_event(SENSOR_2_PIN, 1);
        } else {
            control_led(SENSOR_2_PIN, 0);
            log_touch_event(SENSOR_2_PIN, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    control_led(SENSOR_1_PIN, 0);
    control_led(SENSOR_2_PIN, 0);
    gpioTerminate();

    print_log_buffer();
    return 0;
}

