#include <errno.h>

#define RAIN_SENSOR_GPIO 17
#define LOG_FILE "/var/log/rain_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Log a rain event with a timestamp */
static void log_rain_event(int rain_detected) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        if (rain_detected) {
            fprintf(log_file, "%s - Rain Detected\n", timestamp);
        } else {
            fprintf(log_file, "%s - No Rain\n", timestamp);
        }
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

int main(void) {
    int last_rain_state = -1;  /* Force initial log */
    int current_rain_state;
    int pigpio_initialised = 0;

    /* Register signal handlers */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    pigpio_initialised = 1;

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO 17 as input with internal pull-up */
    if (gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", RAIN_SENSOR_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", RAIN_SENSOR_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Read initial state */
    last_rain_state = gpioRead(RAIN_SENSOR_GPIO);
    if (last_rain_state < 0) {
        fprintf(stderr, "Failed to read GPIO %d\n", RAIN_SENSOR_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", RAIN_SENSOR_GPIO);

    /* Main polling loop */
    while (program_running) {
        current_rain_state = gpioRead(RAIN_SENSOR_GPIO);
        if (current_rain_state < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", RAIN_SENSOR_GPIO);
            break;
        }

        /* Rain is detected when the pin reads LOW (0) */
        if (current_rain_state != last_rain_state) {
            log_rain_event(current_rain_state == 0);
            last_rain_state = current_rain_state;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Cleanup */
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    if (pigpio_initialised) {
        gpioTerminate();
    }

    printf("Rain sensor monitoring stopped.\n");
    return EXIT_SUCCESS;
}

