#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define PULSES_PER_REV 2
#define DEBOUNCE_US 5000
#define LOG_FILE "shaft_log.txt"

static volatile sig_atomic_t running = 1;
static volatile int sensor1_state = 0;
static volatile int sensor2_state = 0;
static volatile uint32_t last_tick1 = 0;
static volatile uint32_t last_tick2 = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(int s1, int s2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%d,%d\n", ts, s1, s2);
    }
    fclose(fp);
}

static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    static uint32_t last_tick = 0;
    static int last_level = 0;
    static int first = 1;

    if (first) {
        last_tick = tick;
        last_level = level;
        first = 0;
        return;
    }

    uint32_t diff = tick - last_tick;
    if (diff > DEBOUNCE_US) {
        if (level != last_level) {
            if (level == 1) {
                if (gpio == SENSOR_1_GPIO) {
                    sensor1_state = 1;
                    last_tick1 = tick;
                } else if (gpio == SENSOR_2_GPIO) {
                    sensor2_state = 1;
                    last_tick2 = tick;
                }
            } else {
                if (gpio == SENSOR_1_GPIO) {
                    sensor1_state = 0;
                    last_tick1 = tick;
                } else if (gpio == SENSOR_2_GPIO) {
                    sensor2_state = 0;
                    last_tick2 = tick;
                }
            }
            log_data(sensor1_state, sensor2_state);
        }
    }
    last_tick = tick;
    last_level = level;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN) != 0 ||
        gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistors\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_1_GPIO, sensor_callback) != 0 ||
        gpioSetAlertFunc(SENSOR_2_GPIO, sensor_callback) != 0) {
        fprintf(stderr, "Failed to set alert functions\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
        if (sensor1_state && sensor2_state) {
            uint32_t t1 = gpioTick();
            uint32_t t2 = gpioTick();
            uint32_t dt = t2 - t1;
            float rpm = (float)PULSES_PER_REV * 60000000.0f / (float)dt;
            printf("RPM: %.2f\n", rpm);
        }
    }

    gpioTerminate();
    printf("RPM monitoring stopped.\n");
    return EXIT_SUCCESS;
}

