    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t part_id;
    if (read_register(i2c_handle, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        cleanup();
        return 1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        cleanup();
        return 1;
    }

    if (write_register(i2c_handle, REG_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        cleanup();
        return 1;
    }

