    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler\n");
        cleanup();
        return 1;
    }

    printf("Starting heart rate and SpO2 monitoring. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_sensor_data(i2c_handle, &heart_rate, &spo2) == 0) {
            if (log_data(log_file, heart_rate, spo2) != 0) {
                fprintf(stderr, "Error logging data\n");
