/*
 * Raspberry Pi 3 Model B+ — Omron D7S-A0011 Seismic Sensor Monitor
 *
 * Wiring:
 *   D7S SDA  -> GPIO2  (I2C bus 1 SDA)
 *   D7S SCL  -> GPIO3  (I2C bus 1 SCL)
 *   D7S VDD  -> 3.3 V
 *   D7S GND  -> GND
 *   LED     -> GPIO17 (with ~330 ohm series resistor to GND)
 *
 * Build:
 *   gcc -O2 -Wall -o seismic seismic.c -lpigpio -lm -lrt
 * Run:
 *   sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define I2C_ADDR             0x1D          /* D7S default 7-bit I2C address */
#define CTRL1_REG            0x1F
#define ACCEL_XOUT_L_REG     0x28          /* 3-axis acceleration, little-endian */
#define ACCEL_XOUT_H_REG     0x29
#define ACCEL_YOUT_L_REG     0x2A
#define ACCEL_YOUT_H_REG     0x2B
#define ACCEL_ZOUT_L_REG     0x2C
#define ACCEL_ZOUT_H_REG     0x2D
#define ACCEL_BLOCK_LEN      6             /* 3 axes × 2 bytes */
#define VIBRATION_THRESHOLD  500.0f
#define LED_GPIO             17
#define POLL_INTERVAL_US     100000        /* 100 ms */
#define MAX_RETRIES          3
#define LOG_FILE             "seismic_events.log"

/* ---- Globals for cleanup ---- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Helpers ---- */
static void timestamp_str(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
}

static void log_event(const char *msg)
{
    char ts[32];
    timestamp_str(ts, sizeof(ts));
    fprintf(log_file, "%s: %s\n", ts, msg);
    fflush(log_file);
}

/* ---- I2C helpers ---- */
static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint8_t len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int n = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
        if (n == (int)len)
            return 0;
        if (n < 0)
            fprintf(stderr, "I2C read error (reg 0x%02X, attempt %d/%d): %d\n",
                    reg, attempt + 1, MAX_RETRIES, n);
        else
            fprintf(stderr, "I2C short read (reg 0x%02X, got %d/%d, attempt %d/%d)\n",
                    reg, n, len, attempt + 1, MAX_RETRIES);
        gpioDelay(10000); /* 10 ms backoff */
    }
    return -1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, val);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write error (reg 0x%02X, val 0x%02X, attempt %d/%d): %d\n",
                reg, val, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(10000);
    }
    return -1;
}

/* ---- Sensor init ---- */
static int init_sensor(void)
{
    /* Verify sensor presence by reading CTRL1 */
    uint8_t ctrl1;
    if (i2c_read_block(i2c_handle, CTRL1_REG, &ctrl1, 1) != 0) {
        fprintf(stderr, "Sensor not responding on I2C bus %d addr 0x%02X\n",
                I2C_BUS, I2C_ADDR);
        return -1;
    }
    printf("D7S detected (CTRL1=0x%02X)\n", ctrl1);

    /* Clear power-down bit (bit 0) in CTRL1 to wake the sensor */
    if (i2c_write_byte(i2c_handle, CTRL1_REG, ctrl1 & 0xFE) != 0) {
        fprintf(stderr, "Failed to wake D7S\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */
    return 0;
}

/* ---- Read acceleration (3 axes, little-endian) ---- */
static int read_acceleration(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[ACCEL_BLOCK_LEN];
    if (i2c_read_block(i2c_handle, ACCEL_XOUT_L_REG, buf, ACCEL_BLOCK_LEN) != 0)
        return -1;

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* ---- Vibration magnitude ---- */
static float vibration_magnitude(int16_t x, int16_t y, int16_t z)
{
    return sqrtf((float)(x * x + y * y + z * z));
}

/* ---- LED control ---- */
static void led_on(void)
{
    gpioWrite(LED_GPIO, 1);
}

static void led_off(void)
{
    gpioWrite(LED_GPIO, 0);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

/* ---- Main ---- */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    led_off();

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed on bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring vibration (threshold %.1f). Ctrl+C to exit.\n",
           (double)VIBRATION_THRESHOLD);

    /* Main loop */
    while (running) {
        int16_t x, y, z;
        if (read_acceleration(&x, &y, &z) != 0) {
            fprintf(stderr, "Failed to read acceleration after %d retries; "
                            "sensor may be disconnected\n", MAX_RETRIES);
            led_off();
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        float mag = vibration_magnitude(x, y, z);
        if (mag > VIBRATION_THRESHOLD) {
            led_on();
            log_event("Vibration threshold exceeded");
            printf("Vibration magnitude: %.2f (threshold %.1f) — LED ON\n",
                   (double)mag, (double)VIBRATION_THRESHOLD);
            gpioDelay(1000000); /* 1 s */
            led_off();
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

