        if (!sensor_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", sensor_pins[i]);
            goto cleanup;
        }
    }

    /* Get LED line */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED GPIO line");
        goto cleanup;
    }

    /* Request sensor lines as inputs */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpiod_line_request_input(sensor_lines[i], "ky032-sensor") < 0) {
            perror("Failed to request sensor line as input");
            goto cleanup;
        }
    }

    /* Request LED line as output, initial value LOW */
    if (gpiod_line_request_output(led_line, "ky032-led", 0) < 0) {
        perror("Failed to request LED line as output");
        goto cleanup;
    }

