        if (gpiod_line_set_value(led_line, any_obstacle ? 1 : 0) < 0) {
            perror("Failed to set LED value");
            goto cleanup;
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure LED is off on exit */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("Exiting cleanly.\n");
    }
    return ret;
}

