/*
 * flame_monitor.c — 5x KY-026 flame sensor monitor using libgpiod (v1.6+)
 *
 * Board:  Raspberry Pi 3 Model B+
 * Library: libgpiod (v1.6+)
 *
 * Wiring (BCM numbering):
 *   Sensor 1: GPIO 2  (physical pin 3)
 *   Sensor 2: GPIO 3  (physical pin 5)
 *   Sensor 3: GPIO 4  (physical pin 7)
 *   Sensor 4: GPIO 17 (physical pin 11)
 *   Sensor 5: GPIO 27 (physical pin 13)
 *
 * Sensor output: LOW  = flame detected, HIGH = no flame.
 * VCC/GND: 3.3 V, GND.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 *
 * Run:
 *   sudo ./flame_monitor   (root needed for /dev/gpiochip0 access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/file.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_S 1
#define LOG_FILE "/var/log/flame_events.log"

/* Sensor IDs (correspond to BCM GPIO numbers) */
static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

/* Per-sensor state */
typedef struct {
    unsigned int pin;
    struct gpiod_line *line;
    int flame_state;          /* 0 = no flame, 1 = flame */
    int last_raw;             /* last raw read value (0 or 1) */
    struct timespec last_change;
} sensor_t;

static sensor_t sensors[NUM_SENSORS];
static struct gpiod_chip *chip = NULL;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/* Return an ISO-8601 UTC timestamp string (caller must free). */
static char *get_iso8601_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        return NULL;
    }
    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        return NULL;
    }
    char *buf = malloc(32);
    if (buf == NULL) {
        return NULL;
    }
    if (strftime(buf, 32, "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        free(buf);
        return NULL;
    }
    return buf;
}

/* Append a flame event line to the log file. */
static int log_event(int sensor_id, unsigned int pin)
{
    char *ts = get_iso8601_timestamp();
    if (ts == NULL) {
        syslog(LOG_ERR, "Failed to generate timestamp: %s", strerror(errno));
        return -1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open %s: %s", LOG_FILE, strerror(errno));
        free(ts);
        return -1;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock(LOCK_EX) failed: %s", strerror(errno));
        fclose(fp);
        free(ts);
        return -1;
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %u) - Flame Detected\n",
                ts, sensor_id, pin) < 0) {
        syslog(LOG_ERR, "fprintf to log failed: %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        free(ts);
        return -1;
    }

    if (fflush(fp) == EOF) {
        syslog(LOG_ERR, "fflush failed: %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        free(ts);
        return -1;
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_WARNING, "flock(LOCK_UN) failed: %s", strerror(errno));
    }

    if (fclose(fp) == EOF) {
        syslog(LOG_ERR, "fclose failed: %s", strerror(errno));
        free(ts);
        return -1;
    }

    free(ts);
    return 0;
}

/* Read a sensor line; returns 0 or 1, or -1 on error. */
static int read_sensor(sensor_t *s)
{
    int val = gpiod_line_get_value(s->line);
    if (val < 0) {
        syslog(LOG_ERR, "gpiod_line_get_value(pin %u) failed: %s",
               s->pin, strerror(errno));
        return -1;
    }
    return val;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensors[i].line != NULL) {
            gpiod_line_release(sensors[i].line);
            sensors[i].line = NULL;
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    closelog();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- Acquire and request each line ---- */
    for (int i = 0; i < NUM_SENSORS; i++) {
        sensors[i].pin = sensor_pins[i];
        sensors[i].line = NULL;
        sensors[i].flame_state = 0;
        sensors[i].last_raw = -1;          /* unknown */
        sensors[i].last_change.tv_sec = 0;
        sensors[i].last_change.tv_nsec = 0;

        sensors[i].line = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (sensors[i].line == NULL) {
            syslog(LOG_ERR, "gpiod_chip_get_line(pin %u) failed: %s",
                   sensor_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_input(sensors[i].line, "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(pin %u) failed: %s",
                   sensor_pins[i], strerror(errno));
            sensors[i].line = NULL;        /* line not acquired */
            cleanup();
            return EXIT_FAILURE;
        }
    }

    syslog(LOG_INFO, "Flame sensor monitoring started (5 sensors on BCM %u, %u, %u, %u, %u).",
           sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    /* ---- Main polling loop ---- */
    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int raw = read_sensor(&sensors[i]);
            if (raw < 0) {
                /* Read error — skip this sensor this cycle, keep running. */
                continue;
            }

            /* Detect rising edge: no-flame -> flame */
            if (raw == 1 && sensors[i].last_raw == 0) {
                struct timespec now;
                if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) {
                    syslog(LOG_ERR, "clock_gettime failed: %s", strerror(errno));
                    continue;
                }

                /* Debounce: re-read after DEBOUNCE_MS */
                struct timespec debounce_ts;
                debounce_ts.tv_sec = now.tv_sec;
                debounce_ts.tv_nsec = now.tv_nsec + (DEBOUNCE_MS * 1000000L);
                if (debounce_ts.tv_nsec >= 1000000000L) {
                    debounce_ts.tv_sec += 1;
                    debounce_ts.tv_nsec -= 1000000000L;
                }

                int confirmed = 0;
                while (program_running) {
                    int r = read_sensor(&sensors[i]);
                    if (r < 0) {
                        break;
                    }
                    if (r == 1) {
                        confirmed = 1;
                        break;
                    }
                    if (clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME,
                                        &debounce_ts, NULL) == -1) {
                        if (errno == EINTR) {
                            continue;
                        }
                        syslog(LOG_ERR, "clock_nanosleep failed: %s",
                               strerror(errno));
                        break;
                    }
                }

                if (confirmed) {
                    sensors[i].flame_state = 1;
                    if (log_event(i + 1, sensor_pins[i]) == 0) {
                        syslog(LOG_INFO, "Flame detected on sensor %d (GPIO %u).",
                               i + 1, sensor_pins[i]);
                    } else {
                        syslog(LOG_ERR, "Failed to log event for sensor %d (GPIO %u).",
                               i + 1, sensor_pins[i]);
                    }
                }
            }

            sensors[i].last_raw = raw;
        }

        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Shutting down.");
    cleanup();
    return EXIT_SUCCESS;
}

