        sensors[i].last_raw = -1;          /* unknown */
        sensors[i].last_change.tv_sec = 0;
        sensors[i].last_change.tv_nsec = 0;

        sensors[i].line = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (sensors[i].line == NULL) {
            syslog(LOG_ERR, "gpiod_chip_get_line(pin %u) failed: %s",
                   sensor_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_input(sensors[i].line, "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(pin %u) failed: %s",
                   sensor_pins[i], strerror(errno));
            sensors[i].line = NULL;        /* line not acquired */
            cleanup();
            return EXIT_FAILURE;
        }
    }

    syslog(LOG_INFO, "Flame sensor monitoring started (5 sensors on BCM %u, %u, %u, %u, %u).",
           sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    /* ---- Main polling loop ---- */
    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int raw = read_sensor(&sensors[i]);
            if (raw < 0) {
                /* Read error — skip this sensor this cycle, keep running. */
                continue;
            }

            /* Detect rising edge: no-flame -> flame */
            if (raw == 1 && sensors[i].last_raw == 0) {
                struct timespec now;
                if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) {
                    syslog(LOG_ERR, "clock_gettime failed: %s", strerror(errno));
                    continue;
                }

                /* Debounce: re-read after DEBOUNCE_MS */
                struct timespec debounce_ts;
                debounce_ts.tv_sec = now.tv_sec;
                debounce_ts.tv_nsec = now.tv_nsec + (DEBOUNCE_MS * 1000000L);
                if (debounce_ts.tv_nsec >= 1000000000L) {
                    debounce_ts.tv_sec += 1;
                    debounce_ts.tv_nsec -= 1000000000L;
                }

                int confirmed = 0;
                while (program_running) {
                    int r = read_sensor(&sensors[i]);
                    if (r < 0) {
                        break;
                    }
                    if (r == 1) {
                        confirmed = 1;
                        break;
                    }
                    if (clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME,
                                        &debounce_ts, NULL) == -1) {
                        if (errno == EINTR) {
                            continue;
                        }
                        syslog(LOG_ERR, "clock_nanosleep failed: %s",
                               strerror(errno));
                        break;
                    }
                }

                if (confirmed) {
                    sensors[i].flame_state = 1;
                    if (log_event(i + 1, sensor_pins[i]) == 0) {
                        syslog(LOG_INFO, "Flame detected on sensor %d (GPIO %u).",
                               i + 1, sensor_pins[i]);
                    } else {
                        syslog(LOG_ERR, "Failed to log event for sensor %d (GPIO %u).",
                               i + 1, sensor_pins[i]);
                    }
                }
            }

            sensors[i].last_raw = raw;
        }

        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Shutting down.");
    cleanup();
    return EXIT_SUCCESS;
}

