#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int touch_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_state_change(int channel, int value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);
    } else {
        strncpy(timestamp, "UNKNOWN", sizeof(timestamp));
        timestamp[sizeof(timestamp) - 1] = '\0';
    }

    printf("[%s] Channel %d (BCM %u): %s\n",
           timestamp, channel, touch_pins[channel], value ? "Touched" : "Released");
    fflush(stdout);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    struct gpiod_line_bulk bulk;
    int prev_states[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));
    memset(prev_states, 0, sizeof(prev_states));

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = NULL;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: Failed to get GPIO line %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    if (gpiod_line_request_bulk_input(lines, "ttp226-touch") < 0) {
        fprintf(stderr, "Error: Failed to request bulk input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("TTP226 touch sensor monitoring started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        int values[NUM_CHANNELS];

        if (gpiod_line_get_value_bulk(&bulk, lines, NUM_CHANNELS) < 0) {
            fprintf(stderr, "Error: Failed to read GPIO values: %s\n", strerror(errno));
            goto cleanup;
        }

        for (int i = 0; i < NUM_CHANNELS; i++) {
            values[i] = gpiod_line_get_value(lines[i]);
            if (values[i] < 0) {
                fprintf(stderr, "Error: Failed to read GPIO line %u: %s\n",
                        touch_pins[i], strerror(errno));
                goto cleanup;
            }

            if (values[i] != prev_states[i]) {
                log_state_change(i, values[i]);
                prev_states[i] = values[i];
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

