#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VEML7700_ADDR        0x10
#define VEML7700_CONFIG_REG  0x00
#define VEML7700_ALS_REG     0x04
#define LED_GPIO             18
#define PWM_FREQUENCY        1000
#define PWM_RANGE            100
#define LUX_THRESHOLD_1     100
#define LUX_THRESHOLD_2     500
#define LUX_THRESHOLD_3     1000
#define LUX_SCALE           0.0576f
#define SAMPLE_INTERVAL_US  1000000
#define CONFIG_VALUE        0x0000  /* ALS gain 1/8, IT 100 ms, no interrupts */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int veml7700_write_config(int handle, uint16_t config)
{
    char buf[3];
    buf[0] = (char)VEML7700_CONFIG_REG;
    buf[1] = (char)(config & 0xFF);          /* low byte first */
    buf[2] = (char)((config >> 8) & 0xFF);   /* high byte second */
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error: failed to write VEML7700 config register\n");
        return -1;
    }
    return 0;
}

static int veml7700_read_als(int handle, uint16_t *raw)
{
    char reg = (char)VEML7700_ALS_REG;
    char data[2];

    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to select ALS register\n");
        return -1;
    }
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read ALS data\n");
        return -1;
    }
    *raw = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int veml7700_init(int handle)
{
    if (veml7700_write_config(handle, CONFIG_VALUE) != 0)
        return -1;
    /* Allow first integration cycle to complete (100 ms + margin) */
    gpioDelay(150000);
    return 0;
}

static int set_led_brightness(int gpio, int brightness)
{
    if (brightness < 0)   brightness = 0;
    if (brightness > 100) brightness = 100;
    if (gpioPWM(gpio, brightness) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, float lux, int brightness, int error_code)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Lux: %.2f, Brightness: %d, Error: %d\n",
                ts, lux, brightness, error_code) < 0) {
        fprintf(stderr, "Error: fprintf to log failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, VEML7700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d) - sensor may be absent\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (veml7700_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: VEML7700 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_led_brightness(LED_GPIO, 0) != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("grow_log.txt", "a");
    if (g_log_file == NULL) {
        perror("Error: fopen grow_log.txt");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Grow light system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw = 0;
        float lux = 0.0f;
        int error_code = 0;

        if (veml7700_read_als(g_i2c_handle, &raw) != 0) {
            error_code = 1;
            goto read_error;
        }

        lux = (float)raw * LUX_SCALE;

        int brightness = 100;
        if (lux < LUX_THRESHOLD_1) {
            brightness = 100;
        } else if (lux < LUX_THRESHOLD_2) {
            brightness = 75;
        } else if (lux < LUX_THRESHOLD_3) {
            brightness = 50;
        } else {
            brightness = 25;
        }

        if (set_led_brightness(LED_GPIO, brightness) != 0) {
            error_code = 2;
            goto read_error;
        }

        if (log_data(g_log_file, lux, brightness, error_code) != 0) {
            error_code = 3;
        }

    read_error:
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful shutdown */
    set_led_brightness(LED_GPIO, 0);
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    if (g_log_file)        fclose(g_log_file);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

