#include <signal.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define LED_PIN 17
#define POLL_DELAY_US 50000  /* 50 ms */

static const int sensor_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_touch_event(int channel) {
    FILE *fp = fopen("touch_log.txt", "a");
    if (!fp) {
        perror("fopen(touch_log.txt)");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Channel %d Touched\n", timestamp, channel) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs with pull-down */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", sensor_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down on GPIO %d\n", sensor_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Configure LED pin as output and ensure it starts off */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise LED state on GPIO %d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_state[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        last_state[i] = 0;
    }

    printf("Security Keypad Monitoring Started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int level = gpioRead(sensor_pins[i]);
            if (level < 0) {
                fprintf(stderr, "gpioRead failed on GPIO %d\n", sensor_pins[i]);
                continue;
            }

            /* Detect rising edge: untouched -> touched */
            if (level == 1 && last_state[i] == 0) {
                if (log_touch_event(i + 1) == 0) {
                    printf("Touch detected on Channel %d\n", i + 1);
                }
                if (gpioWrite(LED_PIN, 1) != 0) {
                    fprintf(stderr, "Failed to turn on LED\n");
                }
            }

            last_state[i] = level;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful shutdown */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

