#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define OPT3001_ADDR        0x44
#define REG_RESULT          0x00
#define REG_CONFIG          0x01
#define CONFIG_WORD         0xC810  /* RN=100ms, CT=100ms, M=0, FC=0, CT=0, POL=0, ME=0, FC=0, M=0, RN=100ms */
#define LOG_FILE            "light_data.txt"
#define SAMPLE_INTERVAL_S   1
#define CONV_WAIT_MS        100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Swap bytes: little-endian host -> big-endian (OPT3001 expects MSB first) */
static uint16_t swap16(uint16_t v)
{
    return (uint16_t)((v >> 8) | (v << 8));
}

static int opt3001_write_config(int handle, uint16_t config)
{
    int rc = i2cWriteWordData(handle, REG_CONFIG, swap16(config));
    if (rc < 0) {
        fprintf(stderr, "Error writing config register (pigpio rc=%d): %s\n",
                rc, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int opt3001_read_result(int handle, uint16_t *out)
{
    int rc = i2cReadWordData(handle, REG_RESULT);
    if (rc < 0) {
        fprintf(stderr, "Error reading result register (pigpio rc=%d): %s\n",
                rc, pigpio_error(rc));
        return -1;
    }
    *out = swap16((uint16_t)rc);
    return 0;
}

static int read_lux(int handle, float *lux_out)
{
    uint16_t raw;
    if (opt3001_read_result(handle, &raw) != 0)
        return -1;

    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    *lux_out = (float)mantissa * 0.01f * (float)(1u << exponent);
    return 0;
}

static int log_lux(float lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", ts, lux) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("Error flushing log file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X (pigpio rc=%d): %s\n",
                OPT3001_ADDR, g_i2c_handle, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (opt3001_write_config(g_i2c_handle, CONFIG_WORD) != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Wait for first conversion to complete */
    gpioDelay(CONV_WAIT_MS * 1000);

    while (g_running) {
        float lux;
        if (read_lux(g_i2c_handle, &lux) == 0) {
            printf("Lux: %.2f\n", lux);
            if (log_lux(lux) != 0) {
                fprintf(stderr, "Warning: failed to log lux value\n");
            }
        } else {
            fprintf(stderr, "Warning: failed to read lux value\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

