#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 4
#define ALERT_PIN 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */
#define ALERT_DURATION_US 1000000 /* 1 second */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void trigger_alert(void) {
    if (gpioWrite(ALERT_PIN, 1) < 0) {
        log_event("ERROR: Failed to set ALERT_PIN HIGH");
        return;
    }
    gpioDelay(ALERT_DURATION_US);
    if (gpioWrite(ALERT_PIN, 0) < 0) {
        log_event("ERROR: Failed to set ALERT_PIN LOW");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        log_event("ERROR: Failed to set FLAME_SENSOR_PIN as input");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        log_event("ERROR: Failed to set ALERT_PIN as output");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALERT_PIN, 0) < 0) {
        log_event("ERROR: Failed to initialize ALERT_PIN to LOW");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_event("ERROR: Failed to register SIGINT handler");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Flame sensor monitoring started");

    while (running) {
        int sensor_value = gpioRead(FLAME_SENSOR_PIN);
        if (sensor_value < 0) {
            log_event("ERROR: Failed to read FLAME_SENSOR_PIN");
        } else {
            char message[128];
            snprintf(message, sizeof(message), "Sensor value: %d", sensor_value);
            log_event(message);

            if (sensor_value == 0) {
                log_event("Flame detected! Triggering alert.");
                trigger_alert();
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("Shutting down gracefully");
    gpioWrite(ALERT_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

