    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_event("ERROR: Failed to register SIGINT handler");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Flame sensor monitoring started");

    while (running) {
        int sensor_value = gpioRead(FLAME_SENSOR_PIN);
        if (sensor_value < 0) {
            log_event("ERROR: Failed to read FLAME_SENSOR_PIN");
        } else {
            char message[128];
            snprintf(message, sizeof(message), "Sensor value: %d", sensor_value);
            log_event(message);

            if (sensor_value == 0) {
                log_event("Flame detected! Triggering alert.");
                trigger_alert();
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("Shutting down gracefully");
    gpioWrite(ALERT_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

