#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x08
#define LOG_FILE       "cooling_log.csv"
#define SAMPLE_US      1000000  /* 1 second */
#define MEAS_DELAY_US  2000     /* 2 ms after start command */
#define FLOW_SCALE     90.0f
#define FLOW_MIN       0.0f
#define FLOW_MAX       100.0f
#define CRC_POLY       0x31
#define CRC_INIT       0xFF

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)                */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Initialize I2C                                                       */
/* ------------------------------------------------------------------ */
static int init_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Start continuous measurement (0x3608)                               */
/* ------------------------------------------------------------------ */
static int start_measurement(void)
{
    uint8_t cmd[2] = { 0x36, 0x08 };
    int rc = i2cWriteDevice(g_i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice (start) failed: %d\n", rc);
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one 3-byte sample and convert to ml/min                       */
/* ------------------------------------------------------------------ */
static int read_flow_rate(float *flow_rate)
{
    uint8_t buf[3];
    int rc = i2cReadDevice(g_i2c_handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 3)\n", rc);
        return -1;
    }

    /* CRC check */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch (calc=0x%02X recv=0x%02X)\n",
                crc8(buf, 2), buf[2]);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw / FLOW_SCALE;

    /* Sanity range check */
    if (*flow_rate < FLOW_MIN || *flow_rate > FLOW_MAX) {
        fprintf(stderr, "Warning: flow rate %.2f ml/min out of plausible range\n",
                *flow_rate);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one row                                                         */
/* ------------------------------------------------------------------ */
static void log_data(float flow_rate, int flags, const char *status)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s,%.2f,%s\n", ts, flow_rate, status);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file (append); write header if new/empty */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Error: fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(g_log_file);
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start continuous measurement */
    if (start_measurement() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Coolant flow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float flow_rate;
        int flags = 0;

        if (read_flow_rate(&flow_rate) == 0) {
            flags = 0;
            log_data(flow_rate, flags, "OK");
        } else {
            flags = 1;
            log_data(0.0f, flags, "ERROR");
            fprintf(stderr, "Error: I2C read failed; re-initializing I2C...\n");
            if (init_i2c() != 0) {
                fprintf(stderr, "Error: I2C re-init failed; exiting.\n");
                break;
            }
            if (start_measurement() != 0) {
                fprintf(stderr, "Error: measurement start failed; exiting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

