#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define FLAME_SENSOR_GPIO 4
#define CONSUMER "flame_monitor"
#define LOG_FILE "flame_events.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

static void print_alert(const char *message) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    printf("%s: %s\n", timestamp, message);
    fflush(stdout);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("Failed to open gpiochip4");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, FLAME_SENSOR_GPIO);
    if (!line) {
        perror("Failed to get GPIO line");
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(line, CONSUMER) < 0) {
        perror("Failed to request falling edge events on GPIO line");
        goto cleanup;
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n", FLAME_SENSOR_GPIO);
    fflush(stdout);

    while (program_running) {
        struct timespec ts = {1, 0}; // 1 second timeout
        int event = gpiod_line_event_wait(line, &ts);
        if (event < 0) {
            perror("Error waiting for GPIO event");
            break;
        }
        if (event == 0) {
            continue; // Timeout, no event
        }

        struct gpiod_line_event ev;
        if (gpiod_line_event_read(line, &ev) < 0) {
            perror("Error reading GPIO event");
            continue;
        }

        if (ev.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            char message[128];
            snprintf(message, sizeof(message), "Flame detected on GPIO%d", FLAME_SENSOR_GPIO);
            print_alert(message);
            log_event(message);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Exiting.\n");
    return ret;
}

