/*
 * TMAG5110A1 Hall-effect latch sensor monitor for Raspberry Pi 4 Model B.
 *
 * Wiring (BCM numbering):
 *   Sensor 1 OUT -> GPIO4   (active-low: magnet = 0, no-magnet = 1)
 *   Sensor 2 OUT -> GPIO17  (active-low: magnet = 0, no-magnet = 1)
 *   Sensor 3 OUT -> GPIO27  (active-low: magnet = 0, no-magnet = 1)
 *
 * The TMAG5110A1 latch output is open-drain; an external pull-up keeps
 * the line high when no magnet is present.  A south-pole magnet draws
 * current through the pull-up, driving the line low.  Therefore:
 *   0  -> magnet present
 *   1  -> magnet absent
 *
 * Build:  gcc -O2 -Wall -Wextra -o mag_monitor mag_monitor.c -lpigpio -lrt
 * Run:    sudo ./mag_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27

#define LOG_FILE "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    if (localtime_r(&now, &tmv) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
    } else {
        snprintf(buf, len, "1970-01-01T00:00:00");
    }
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (g_log_fp) {
        fprintf(g_log_fp, "%s %s\n", ts, msg);
        fflush(g_log_fp);
    }
    fprintf(stderr, "%s %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/*
 * Returns:
 *   0  -> magnet present (active-low line reads LOW)
 *   1  -> magnet absent   (active-low line reads HIGH)
 *  -1  -> read error
 */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        return -1;
    }
    return (v == 0) ? 0 : 1;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure pins as inputs with pull-ups ---- */
    int pins[] = {SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pins[i]);
            goto cleanup;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) < 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d\n", pins[i]);
            goto cleanup;
        }
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error installing signal handler");
        goto cleanup;
    }

    /* ---- initial state ---- */
    int prev1 = read_sensor(SENSOR_1_PIN);
    int prev2 = read_sensor(SENSOR_2_PIN);
    int prev3 = read_sensor(SENSOR_3_PIN);

    if (prev1 < 0 || prev2 < 0 || prev3 < 0) {
        fprintf(stderr, "Error: initial sensor read failed.\n");
        goto cleanup;
    }

    log_event("Monitoring started.");

    /* ---- main poll loop ---- */
    while (g_running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);
        int s3 = read_sensor(SENSOR_3_PIN);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            log_event("Error: sensor read failed.");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (s1 != prev1) {
            log_event(s1 ? "Sensor 1: magnet removed" : "Sensor 1: magnet present");
            prev1 = s1;
        }
        if (s2 != prev2) {
            log_event(s2 ? "Sensor 2: magnet removed" : "Sensor 2: magnet present");
            prev2 = s2;
        }
        if (s3 != prev3) {
            log_event(s3 ? "Sensor 3: magnet removed" : "Sensor 3: magnet present");
            prev3 = s3;
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("Monitoring stopped.");

cleanup:
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

