#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x4A

#define REG_PART_ID 0x00
#define REG_HW_REV  0x01
#define REG_LED1    0x3F
#define REG_AVG     0x04
#define REG_ENABLE  0x01
#define REG_HR      0x2A

#define EXPECTED_PART_ID 0x02
#define EXPECTED_HW_REV  0x01

#define MOVING_AVG_SIZE 5
#define SAMPLE_INTERVAL_US 1000000
#define MIN_BPM 30.0f
#define MAX_BPM 220.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int configure_sensor(int handle) {
    if (write_register(handle, REG_LED1, 0x0A) < 0) return -1;
    if (write_register(handle, REG_AVG, 0x04) < 0) return -1;
    if (write_register(handle, REG_ENABLE, 0x01) < 0) return -1;
    return 0;
}

static int read_heart_rate(int handle, float *bpm) {
    int raw = i2cReadWordData(handle, REG_HR);
    if (raw < 0) {
        fprintf(stderr, "Error reading heart-rate register: %d\n", raw);
        return -1;
    }
    *bpm = (float)raw * 0.5f;
    return 0;
}

static float moving_average(float new_value, float *buffer, int size, int *index) {
    buffer[*index] = new_value;
    *index = (*index + 1) % size;
    float sum = 0.0f;
    for (int i = 0; i < size; i++) sum += buffer[i];
    return sum / (float)size;
}

static int log_data(float bpm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(log_file, "%s,%.2f\n", timestamp, bpm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t part_id = 0, hw_rev = 0;
    if (read_register(i2c_handle, REG_PART_ID, &part_id) < 0 ||
        read_register(i2c_handle, REG_HW_REV, &hw_rev) < 0) {
        fprintf(stderr, "Sensor not responding or absent\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (part_id != EXPECTED_PART_ID || hw_rev != EXPECTED_HW_REV) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X) or HW_REV 0x%02X (expected 0x%02X)\n",
                part_id, EXPECTED_PART_ID, hw_rev, EXPECTED_HW_REV);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (configure_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("heart_rate.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening heart_rate.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float buffer[MOVING_AVG_SIZE] = {0.0f};
    int buffer_index = 0;
    int consecutive_errors = 0;

    while (running) {
        float bpm = 0.0f;
        if (read_heart_rate(i2c_handle, &bpm) == 0) {
            consecutive_errors = 0;
            if (bpm >= MIN_BPM && bpm <= MAX_BPM) {
                float avg = moving_average(bpm, buffer, MOVING_AVG_SIZE, &buffer_index);
                if (log_data(avg) == 0) {
                    printf("BPM: %.2f\n", avg);
                }
            } else {
                fprintf(stderr, "BPM out of range: %.2f\n", bpm);
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error (%d)\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive errors, aborting\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

