/*
 * TTP226 8-channel capacitive touch counter on Raspberry Pi Zero W.
 *
 * Wiring (BCM numbering):
 *   TTP226 OUT1..OUT8 -> GPIO 5, 6, 7, 8, 9, 10, 11, 12
 *   Counter display    -> GPIO 17 (bit 0), GPIO 24 (bit 7)
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 * Run:    ./touch_counter
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define LOG_FILE     "touch_log.txt"
#define POLL_MS      10
#define STAB_MS      200

static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int output_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_touch_event(int channel, int counter)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm);
        fprintf(fp, "%s, Channel: %d, Counter: %d\n", ts, channel, counter);
    } else {
        fprintf(fp, "UNKNOWN, Channel: %d, Counter: %d\n", channel, counter);
    }
    fclose(fp);
}

static void log_error(const char *msg)
{
    fprintf(stderr, "Error: %s (errno %d: %s)\n", msg, errno, strerror(errno));
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *sensor_req = NULL;
    struct gpiod_line_request *output_req = NULL;
    struct gpiod_line_config *sensor_cfg = NULL;
    struct gpiod_line_config *output_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    int prev_state[NUM_CHANNELS];
    int counter = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_error("sigaction failed");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("gpiod_chip_open failed");
        return EXIT_FAILURE;
    }

    sensor_cfg = gpiod_line_config_new();
    output_cfg = gpiod_line_config_new();
    if (!sensor_cfg || !output_cfg) {
        log_error("gpiod_line_config_new failed");
        goto cleanup;
    }

    settings = gpiod_line_settings_new();
    if (!settings) {
        log_error("gpiod_line_settings_new failed");
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_config_add_line_settings(sensor_cfg, &sensor_pins[i], 1, settings) < 0) {
            log_error("gpiod_line_config_add_line_settings (sensor) failed");
            goto cleanup;
        }
        if (gpiod_line_config_add_line_settings(output_cfg, &output_pins[i], 1, settings) < 0) {
            log_error("gpiod_line_config_add_line_settings (output) failed");
            goto cleanup;
        }
    }

    sensor_req = gpiod_chip_request_lines(chip, NULL, sensor_cfg);
    if (!sensor_req) {
        log_error("gpiod_chip_request_lines (sensor) failed");
        goto cleanup;
    }

    output_req = gpiod_chip_request_lines(chip, NULL, output_cfg);
    if (!output_req) {
        log_error("gpiod_chip_request_lines (output) failed");
        goto cleanup;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        prev_state[i] = gpiod_line_request_get_value(sensor_req, sensor_pins[i]);
        if (prev_state[i] < 0) {
            log_error("gpiod_line_request_get_value (init) failed");
            goto cleanup;
        }
    }

    usleep(STAB_MS * 1000);

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_set_value(output_req, output_pins[i], 0) < 0) {
            log_error("gpiod_line_request_set_value (init) failed");
            goto cleanup;
        }
    }

    printf("Touch counter running. Press Ctrl+C to exit.\n");

    while (g_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_request_get_value(sensor_req, sensor_pins[i]);
            if (val < 0) {
                log_error("gpiod_line_request_get_value failed");
                continue;
            }

            if (val == 1 && prev_state[i] == 0) {
                counter = (counter + 1) & 0xFF;
                for (int b = 0; b < NUM_CHANNELS; b++) {
                    if (gpiod_line_request_set_value(output_req, output_pins[b], (counter >> b) & 1) < 0) {
                        log_error("gpiod_line_request_set_value failed");
                    }
                }
                log_touch_event(i + 1, counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
            prev_state[i] = val;
        }
        usleep(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (output_req) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            gpiod_line_request_set_value(output_req, output_pins[i], 0);
        }
        gpiod_line_request_release(output_req);
    }
    if (sensor_req) {
        gpiod_line_request_release(sensor_req);
    }
    if (output_cfg) gpiod_line_config_free(output_cfg);
    if (sensor_cfg) gpiod_line_config_free(sensor_cfg);
    if (settings) gpiod_line_settings_free(settings);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

