#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_SENSORS 4
#define POLL_INTERVAL_MS 100
#define CSV_FILENAME "tracking_log.csv"

static const unsigned int sensor_pins[NUM_SENSORS] = {17, 18, 27, 22};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int write_header_if_new(FILE *fp) {
    long pos = ftell(fp);
    if (pos < 0) {
        perror("ftell");
        return -1;
    }
    if (pos == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n") < 0) {
            perror("fprintf header");
            return -1;
        }
        if (fflush(fp) != 0) {
            perror("fflush header");
            return -1;
        }
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    struct timespec sleep_time = {0, POLL_INTERVAL_MS * 1000000L};
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line failed for BCM %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "ky033_tracking") < 0) {
            fprintf(stderr, "gpiod_line_request_input failed for BCM %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        perror("fopen");
        goto cleanup;
    }

    if (write_header_if_new(fp) != 0) {
        goto cleanup;
    }

    while (program_running) {
        int values[NUM_SENSORS];
        int read_error = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_get_value failed for BCM %u: %s\n",
                        sensor_pins[i], strerror(errno));
                values[i] = -1;
                read_error = 1;
            } else {
                values[i] = val;
            }
        }

        if (read_error) {
            nanosleep(&sleep_time, NULL);
            continue;
        }

        time_t rawtime = time(NULL);
        if (rawtime == (time_t)-1) {
            perror("time");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        struct tm timeinfo;
        if (localtime_r(&rawtime, &timeinfo) == NULL) {
            perror("localtime_r");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        char timestamp[32];
        if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
            fprintf(stderr, "strftime failed\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        if (fprintf(fp, "%s,%d,%d,%d,%d\n",
                    timestamp, values[0], values[1], values[2], values[3]) < 0) {
            perror("fprintf");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        if (fflush(fp) != 0) {
            perror("fflush");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        nanosleep(&sleep_time, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            perror("fclose");
        }
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

