#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN    22
#define LOG_FILE   "obstacle_log.csv"
#define POLL_MS    100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(FILE *fp, int s1, int s2, int led) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, s1, s2, led) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *s1 = NULL, *s2 = NULL, *led = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    s1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    s2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (s1 == NULL || s2 == NULL || led == NULL) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(s1, "tcrt5000-s1") != 0) {
        fprintf(stderr, "Failed to request sensor1 as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(s2, "tcrt5000-s2") != 0) {
        fprintf(stderr, "Failed to request sensor2 as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "tcrt5000-led", 0) != 0) {
        fprintf(stderr, "Failed to request LED as output: %s\n", strerror(errno));
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    while (running) {
        int v1 = gpiod_line_get_value(s1);
        int v2 = gpiod_line_get_value(s2);
        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "Error reading sensor GPIOs: %s\n", strerror(errno));
            break;
        }

        int obstacle = (v1 == 0 && v2 == 0) ? 1 : 0;
        int led_state = obstacle ? 1 : 0;

        if (gpiod_line_set_value(led, led_state) != 0) {
            fprintf(stderr, "Error writing LED GPIO: %s\n", strerror(errno));
            break;
        }

        if (log_data(fp, v1, v2, led_state) != 0) {
            break;
        }

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led != NULL) {
        gpiod_line_set_value(led, 0);
        gpiod_line_release(led);
    }
    if (s1 != NULL) gpiod_line_release(s1);
    if (s2 != NULL) gpiod_line_release(s2);
    if (chip != NULL) gpiod_chip_close(chip);
    if (fp != NULL) fclose(fp);

    if (ret == EXIT_SUCCESS) {
        printf("Obstacle avoidance system stopped.\n");
    }
    return ret;
}

