        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(MIC_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", MIC_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is OFF at start */
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize LED GPIO%d to LOW.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ICS-40180 sound peak detection started.\n");
    printf("  MIC GPIO%d (digital input, HIGH = peak)\n", MIC_GPIO);
    printf("  LED GPIO%d (100 ms HIGH on peak)\n", LED_GPIO);
    printf("Sampling at ~8 kHz. Press Ctrl+C to exit.\n");

    while (g_running) {
        int mic_value = gpioRead(MIC_GPIO);
        if (mic_value < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d (code %d).\n", MIC_GPIO, mic_value);
            break;
        }

        if (mic_value == 1) {
            print_timestamp_ms();
            if (gpioWrite(LED_GPIO, 1) != 0) {
                fprintf(stderr, "Error: gpioWrite failed on GPIO%d (ON).\n", LED_GPIO);
                break;
            }
            gpioDelay(LED_ON_TIME_US);
            if (gpioWrite(LED_GPIO, 0) != 0) {
                fprintf(stderr, "Error: gpioWrite failed on GPIO%d (OFF).\n", LED_GPIO);
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

