    if (!center_line) {
        perror("Failed to get center sensor line");
        goto cleanup;
    }

    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    if (!right_line) {
        perror("Failed to get right sensor line");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(left_line, CONSUMER, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to request left line as input with pull-up");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(center_line, CONSUMER, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to request center line as input with pull-up");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(right_line, CONSUMER, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to request right line as input with pull-up");
        goto cleanup;
    }

    printf("Tracing sensor reading started. Press Ctrl+C to exit.\n");

    while (running) {
        int left_val = gpiod_line_get_value(left_line);
        int center_val = gpiod_line_get_value(center_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || center_val < 0 || right_val < 0) {
            fprintf(stderr, "Error reading sensor values: %s\n", strerror(errno));
        } else {
            printf("Left: %d, Center: %d, Right: %d\n", left_val, center_val, right_val);
        }

        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (left_line) gpiod_line_release(left_line);
    if (center_line) gpiod_line_release(center_line);
    if (right_line) gpiod_line_release(right_line);
    if (chip) gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully.\n");
    }
    return ret;
}

