#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define LEFT_PIN 2
#define MIDDLE_PIN 3
#define RIGHT_PIN 4
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL;
    struct gpiod_line *middle_line = NULL;
    struct gpiod_line *right_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO lines */
    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    if (left_line == NULL) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n", LEFT_PIN, strerror(errno));
        goto cleanup;
    }

    middle_line = gpiod_chip_get_line(chip, MIDDLE_PIN);
    if (middle_line == NULL) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n", MIDDLE_PIN, strerror(errno));
        goto cleanup;
    }

    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);
    if (right_line == NULL) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n", RIGHT_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request each line as input individually */
    if (gpiod_line_request_input(left_line, "3way-tracking-left") < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line %d as input: %s\n", LEFT_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(middle_line, "3way-tracking-middle") < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line %d as input: %s\n", MIDDLE_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(right_line, "3way-tracking-right") < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line %d as input: %s\n", RIGHT_PIN, strerror(errno));
        goto cleanup;
    }

    printf("3-Way Tracking Sensor Reader started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        int left_val = gpiod_line_get_value(left_line);
        int middle_val = gpiod_line_get_value(middle_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || middle_val < 0 || right_val < 0) {
            fprintf(stderr, "Error: Failed to read GPIO values: %s\n", strerror(errno));
            break;
        }

        printf("L:%d M:%d R:%d\n", left_val, middle_val, right_val);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (left_line != NULL) gpiod_line_release(left_line);
    if (middle_line != NULL) gpiod_line_release(middle_line);
    if (right_line != NULL) gpiod_line_release(right_line);
    if (chip != NULL) gpiod_chip_close(chip);

    return ret;
}

