#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define PWM_FREQ  1000
#define PWM_RANGE 255
#define FADE_STEPS 50
#define FADE_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_mode_checked(unsigned pin, unsigned mode) {
    int rc = gpioSetMode(pin, mode);
    if (rc < 0) {
        syslog(LOG_ERR, "gpioSetMode(pin=%u, mode=%u) failed: %d", pin, mode, rc);
    }
    return rc;
}

static int pwm_checked(unsigned pin, unsigned duty) {
    int rc = gpioPWM(pin, duty);
    if (rc < 0) {
        syslog(LOG_ERR, "gpioPWM(pin=%u, duty=%u) failed: %d", pin, duty, rc);
    }
    return rc;
}

static void hsv_to_rgb(float h, float s, float v, uint8_t *r, uint8_t *g, uint8_t *b) {
    if (s <= 0.0f) {
        *r = *g = *b = (uint8_t)(v * 255.0f);
        return;
    }
    float hh = h / 60.0f;
    int   i  = (int)(hh);
    float ff = hh - (float)i;
    float p  = v * (1.0f - s);
    float q  = v * (1.0f - s * ff);
    float t  = v * (1.0f - s * (1.0f - ff));
    switch (i) {
        case 0:  *r = (uint8_t)(v * 255.0f); *g = (uint8_t)(t * 255.0f); *b = (uint8_t)(p * 255.0f); break;
        case 1:  *r = (uint8_t)(q * 255.0f); *g = (uint8_t)(v * 255.0f); *b = (uint8_t)(p * 255.0f); break;
        case 2:  *r = (uint8_t)(p * 255.0f); *g = (uint8_t)(v * 255.0f); *b = (uint8_t)(t * 255.0f); break;
        case 3:  *r = (uint8_t)(p * 255.0f); *g = (uint8_t)(q * 255.0f); *b = (uint8_t)(v * 255.0f); break;
        case 4:  *r = (uint8_t)(t * 255.0f); *g = (uint8_t)(p * 255.0f); *b = (uint8_t)(v * 255.0f); break;
        default: *r = (uint8_t)(v * 255.0f); *g = (uint8_t)(p * 255.0f); *b = (uint8_t)(q * 255.0f); break;
    }
}

static void set_led(uint8_t r, uint8_t g, uint8_t b) {
    /* Common-anode: invert for hardware PWM */
    uint8_t r_pwm = 255 - r;
    uint8_t g_pwm = 255 - g;
    uint8_t b_pwm = 255 - b;
    pwm_checked(RED_PIN,   r_pwm);
    pwm_checked(GREEN_PIN, g_pwm);
    pwm_checked(BLUE_PIN,  b_pwm);
}

static void fade_to_random_color(void) {
    uint8_t r, g, b;
    float   h = (float)rand() / (float)RAND_MAX * 360.0f;
    float   s = 1.0f;
    float   v = 1.0f;
    hsv_to_rgb(h, s, v, &r, &g, &b);
    set_led(r, g, b);
}

int main(void) {
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (set_mode_checked(RED_PIN,   PI_OUTPUT) < 0 ||
        set_mode_checked(GREEN_PIN, PI_OUTPUT) < 0 ||
        set_mode_checked(BLUE_PIN,  PI_OUTPUT) < 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    srand((unsigned)time(NULL));
    set_led(0, 0, 0);

    while (running) {
        for (int i = 0; i < FADE_STEPS && running; i++) {
            float t = (float)i / (float)FADE_STEPS;
            float h = (float)rand() / (float)RAND_MAX * 360.0f;
            float s = 1.0f;
            float v = 1.0f;
            uint8_t r, g, b;
            hsv_to_rgb(h, s, v, &r, &g, &b);
            uint8_t r_pwm   = (uint8_t)((float)r   * t);
            uint8_t g_pwm   = (uint8_t)((float)g   * t);
            uint8_t b_pwm   = (uint8_t)((float)b   * t);
            set_led(r_pwm, g_pwm, b_pwm);
            gpioDelay(1000000 / FADE_STEPS);
        }
        if (running) {
            fade_to_random_color();
        }
    }

    /* Graceful shutdown */
    set_led(0, 0, 0);
    gpioTerminate();
    syslog(LOG_INFO, "Shutdown complete");
    closelog();
    return EXIT_SUCCESS;
}

