#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29

#define TCS34725_ENABLE  0x00
#define TCS34725_ATIME   0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID      0x12
#define TCS34725_CDATA   0x14
#define TCS34725_RDATA   0x16
#define TCS34725_GDATA   0x18
#define TCS34725_BDATA   0x1A

#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02
#define TCS34725_ATIME_154MS 0x00
#define TCS34725_CONTROL_1X  0x00

#define RED_THRESHOLD 200
#define LED_PIN       17
#define POLL_MS       200

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int tcs34725_init(int fd) {
    if (i2c_write_reg8(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) return -1;
    usleep(3000);
    if (i2c_write_reg8(fd, TCS34725_ATIME, TCS34725_ATIME_154MS) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_CONTROL, TCS34725_CONTROL_1X) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) return -1;
    uint8_t id;
    if (read(fd, &id, 1) != 1) {
        fprintf(stderr, "Failed to read ID register: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Unexpected sensor ID: 0x%02X (expected 0x44)\n", id);
        return -1;
    }
    return 0;
}

static int tcs34725_read(int fd, uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b) {
    if (i2c_read_reg16(fd, TCS34725_CDATA, c) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_RDATA, r) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_GDATA, g) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_BDATA, b) < 0) return -1;
    return 0;
}

static void calibrate(uint16_t r, uint16_t g, uint16_t b, uint16_t c,
                      float *r_gain, float *g_gain, float *b_gain, float *c_gain) {
    *r_gain = 1.0f;
    *g_gain = 1.0f;
    *b_gain = 1.0f;
    *c_gain = 1.0f;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TCS34725_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        close(fd);
