#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x23
#define BH1750_ONE_TIME_HIGH_RES 0x20
#define BH1750_CONV_TIME_MS 120

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define NUM_LEDS 10

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux) {
    if (i2c_write_cmd(fd, BH1750_ONE_TIME_HIGH_RES) < 0) return -1;

    usleep(BH1750_CONV_TIME_MS * 1000);

    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int spi_transfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int set_led_brightness(int spi_fd, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 31) brightness = 31;

    uint8_t tx[4 * NUM_LEDS + 4];
    uint8_t rx[4 * NUM_LEDS + 4];

    tx[0] = 0x00; tx[1] = 0x00; tx[2] = 0x00; tx[3] = 0x00;  // start frame
    for (int i = 0; i < NUM_LEDS; i++) {
        tx[4 + i * 4]     = 0xE0 | (brightness & 0x1F);
        tx[4 + i * 4 + 1] = 0x00;
        tx[4 + i * 4 + 2] = 0x00;
        tx[4 + i * 4 + 3] = 0x00;
    }
    tx[4 + NUM_LEDS * 4] = 0xFF;  // end frame

    if (spi_transfer(spi_fd, tx, rx, sizeof(tx)) < 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to configure SPI: %s\n", strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    printf("BH1750 and APA102 initialized. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (read_bh1750(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            sleep(1);
            continue;
        }

        int brightness = 0;
        if (lux > 10.0f) {
            if (lux > 300.0f) lux = 300.0f;
            brightness = (int)(((lux - 10.0f) / 290.0f) * 31.0f);
        }

        if (set_led_brightness(spi_fd, brightness) < 0) {
            fprintf(stderr, "LED update error\n");
        }

        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        sleep(1);
    }

    printf("\nShutting down...\n");
    set_led_brightness(spi_fd, 0);
    close(spi_fd);
    close(i2c_fd);
    return 0;
}

