#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_CMD_OT_HRES2 0x21
#define BH1750_CONV_MS 180
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_LEDS 10
#define BRIGHTNESS_MAX 31
#define FADE_MS 500
#define LOOP_DELAY_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_handles[2] = {-1, -1};
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux_out) {
    if (handle < 0) return -1;
    if (i2cWriteByte(handle, BH1750_CMD_OT_HRES2) != 0) {
        fprintf(stderr, "BH1750 write error on handle %d\n", handle);
        return -1;
    }
    gpioDelay(BH1750_CONV_MS * 1000);
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "BH1750 read error on handle %d\n", handle);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int calculate_brightness(float lux) {
    if (lux < 0.0f) return 0;
    int b = (int)(BRIGHTNESS_MAX - (lux / 100.0f) * BRIGHTNESS_MAX);
    if (b < 0) b = 0;
    if (b > BRIGHTNESS_MAX) b = BRIGHTNESS_MAX;
    return b;
}

static void set_led_brightness(int spi_handle, int brightness) {
    if (spi_handle < 0) return;
    uint8_t data[NUM_LEDS * 4 + 4];
    data[0] = 0xE0 | (brightness & 0x1F);
    for (int i = 1; i < (NUM_LEDS * 4 + 4); i++) data[i] = 0x00;
    if (spiWrite(spi_handle, (char *)data, sizeof(data)) != (int)sizeof(data)) {
        fprintf(stderr, "SPI write error\n");
    }
}

static void fade_brightness(int spi_handle, int target_brightness, int fade_ms) {
    int current_brightness = 0;
    int step = (target_brightness > current_brightness) ? 1 : -1;
    int elapsed = 0;
    while (elapsed < fade_ms && running) {
        current_brightness += step;
        if (current_brightness < 0) current_brightness = 0;
        if (current_brightness > BRIGHTNESS_MAX) current_brightness = BRIGHTNESS_MAX;
        set_led_brightness(spi_handle, current_brightness);
        gpioDelay(1000);
        elapsed += 100;
    }
    set_led_brightness(spi_handle, target_brightness);
}

