    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        cleanup();
        return 1;
    }

    while (running) {
        float lux_sum = 0.0f;
        int sensor_count = 0;
        for (int i = 0; i < 2; i++) {
            if (i2c_handles[i] < 0) continue;
