#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

#define POLL_INTERVAL_MS 50
#define SELF_TEST_READS 5
#define SELF_TEST_INTERVAL_MS 100
#define SELF_TEST_BLINK_CYCLES 2
#define SELF_TEST_BLINK_HALF_MS 500
#define BUZZER_SHORT_MS 200
#define BUZZER_LONG_MS 600
#define BUZZER_REPEATS 3

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int blink_led(struct gpiod_line *led, int cycles, int half_ms) {
    for (int i = 0; i < cycles && program_running; i++) {
        if (gpiod_line_set_value(led, 1) < 0) {
            log_event("Error: failed to set LED on");
            return -1;
        }
        usleep(half_ms * 1000);
        if (gpiod_line_set_value(led, 0) < 0) {
            log_event("Error: failed to set LED off");
            return -1;
        }
        usleep(half_ms * 1000);
    }
    return 0;
}

static int buzzer_pattern(struct gpiod_line *buzzer) {
    int patterns[][4] = {
        {BUZZER_SHORT_MS, BUZZER_SHORT_MS, BUZZER_LONG_MS, BUZZER_SHORT_MS},
        {BUZZER_SHORT_MS, BUZZER_SHORT_MS, BUZZER_LONG_MS, BUZZER_SHORT_MS},
        {BUZZER_SHORT_MS, BUZZER_SHORT_MS, BUZZER_LONG_MS, BUZZER_SHORT_MS}
    };
    for (int i = 0; i < BUZZER_REPEATS && program_running; i++) {
        for (int j = 0; j < 4; j++) {
            if (gpiod_line_set_value(buzzer, 1) < 0) {
                log_event("Error: failed to set buzzer on");
                return -1;
            }
            usleep(patterns[i][j] * 1000);
            if (gpiod_line_set_value(buzzer, 0) < 0) {
                log_event("Error: failed to set buzzer off");
                return -1;
            }
            usleep(1000);
        }
    }
    return 0;
}

static int self_test(struct gpiod_line *flame, struct gpiod_line *led, struct gpiod_line *buzzer) {
    log_event("Starting self-test...");

    if (blink_led(led, SELF_TEST_BLINK_CYCLES, SELF_TEST_BLINK_HALF_MS) < 0) {
        log_event("Self-test failed: LED blink pattern failed");
        return -1;
    }
    log_event("Self-test: LED blink pattern passed");

    for (int i = 0; i < SELF_TEST_BLINK_CYCLES; i++) {
        if (gpiod_line_set_value(led, 1) < 0) {
            log_event("Error: failed to set LED on");
            return -1;
        }
        usleep(SELF_TEST_BLINK_HALF_MS * 1000);
        if (gpiod_line_set_value(led, 0) < 0) {
            log_event("Error: failed to set LED off");
            return -1;
        }
        usleep(SELF_TEST_BLINK_HALF_MS * 1000);
    }

    int fault = 1;
    for (int i = 0; i < SELF_TEST_READS; i++) {
        int val = gpiod_line_get_value(flame);
