#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR 0x23
#define I2C_DEV "/dev/i2c-1"
#define GPIO_CHIP "/sys/class/gpio"
#define GPIO_EXPORT "export"
#define GPIO_UNEXPORT "unexport"
#define GPIO_LED 17
#define LUX_BUFFER_SIZE 60
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_MEASUREMENT_TIME_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int gpio_exported = 0;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int gpio_export(int pin) {
    int fd = open(GPIO_CHIP "/gpiochip0/" GPIO_EXPORT, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP "/gpiochip0/" GPIO_EXPORT, strerror(errno));
        return -1;
    }
    char buf[4];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Failed to export GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    gpio_exported = 1;
    return 0;
}

static int gpio_unexport(int pin) {
    int fd = open(GPIO_CHIP "/gpiochip0/" GPIO_UNEXPORT, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP "/gpiochip0/" GPIO_UNEXPORT, strerror(errno));
        return -1;
    }
    char buf[4];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Failed to unexport GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    gpio_exported = 0;
    return 0;
}

static int gpio_set_direction(int pin, const char *dir) {
    int fd = open(GPIO_CHIP "/gpiochip0/gpio" + pin + "/direction", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open direction for GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    if (write(fd, dir, strlen(dir)) != (ssize_t)strlen(dir)) {
        fprintf(stderr, "Failed to set direction for GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_write(int pin, int value) {
    int fd = open(GPIO_CHIP "/gpiochip0/gpio" + pin + "/value", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open value for GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    char buf[2];
    int len = snprintf(buf, sizeof(buf), "%d", value);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Failed to write value for GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int bh1750_init(int fd) {
    uint8_t cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Failed to send init command: %s\n", strerror(errno));
        return -1;
    }
    usleep(BH1750_MEASUREMENT_TIME_MS * 1000);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to read lux data: %s\n", strerror(errno));
        return -1;
    }
    uint16_t raw = (buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void update_lux_buffer(float *buffer, int size, float new_value) {
    static int index = 0;
    buffer[index] = new_value;
    index = (index + 1) % size;
}

static float calculate_average_lux(float *buffer, int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += buffer[i];
    }
    return sum / size;
}

static float calculate_blink_rate(float avg_lux) {
    float rate = 0.5f + (avg_lux / 1000.0f) * 4.5f;
    if (rate < 0.5f) rate = 0.5f;
    if (rate > 5.0f) rate = 5.0f;
    return rate;
}

static void blink_led(float rate) {
    float period_us = 1000000.0f / rate;
    float half_period_us = period_us / 2.0f;
    int on_time = (int)(half_period_us / 1000);
    int off_time = (int)(half_period_us / 1000);
    if (on_time < 1) on_time = 1;
    if (off_time < 1) off_time = 1;
    while (running) {
        if (gpio_write(GPIO_LED, 1) < 0) break;
        usleep(on_time * 1000);
        if (!running) break;
        if (gpio_write(GPIO_LED, 0) < 0) break;
        usleep(off_time * 1000);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    if (gpio_export(GPIO_LED) < 0) {
        close(i2c_fd);
        return 1;
    }

    if (gpio_set_direction(GPIO_LED, "out") < 0) {
        gpio_unexport(GPIO_LED);
        close(i2c_fd);
        return 1;
    }

    float lux_buffer[LUX_BUFFER_SIZE];
    for (int i = 0; i < LUX_BUFFER_SIZE; i++) {
        lux_buffer[i] = 0.0f;
    }

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Error reading lux, retrying...\n");
            sleep(1);
            continue;
        }

        update_lux_buffer(lux_buffer, LUX_BUFFER_SIZE, lux);
        float avg_lux = calculate_average_lux(lux_buffer, LUX_BUFFER_SIZE);
        float blink_rate = calculate_blink_rate(avg_lux);

        printf("Lux: %.2f, Avg Lux: %.2f, Blink Rate: %.2f Hz\n", lux, avg_lux, blink_rate);
        blink_led(blink_rate);

        sleep(1);
    }

    gpio_write(GPIO_LED, 0);
    gpio_unexport(GPIO_LED);
    close(i2c_fd);
    printf("\nExiting gracefully.\n");
    return 0;
}

