        close(i2c_fd);
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    if (gpio_export(GPIO_LED) < 0) {
        close(i2c_fd);
        return 1;
    }

    if (gpio_set_direction(GPIO_LED, "out") < 0) {
        gpio_unexport(GPIO_LED);
        close(i2c_fd);
        return 1;
    }

    float lux_buffer[LUX_BUFFER_SIZE];
    for (int i = 0; i < LUX_BUFFER_SIZE; i++) {
        lux_buffer[i] = 0.0f;
    }

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Error reading lux, retrying...\n");
            sleep(1);
            continue;
        }

        update_lux_buffer(lux_buffer, LUX_BUFFER_SIZE, lux);
        float avg_lux = calculate_average_lux(lux_buffer, LUX_BUFFER_SIZE);
        float blink_rate = calculate_blink_rate(avg_lux);

        printf("Lux: %.2f, Avg Lux: %.2f, Blink Rate: %.2f Hz\n", lux, avg_lux, blink_rate);
        blink_led(blink_rate);

        sleep(1);
    }

    gpio_write(GPIO_LED, 0);
    gpio_unexport(GPIO_LED);
    close(i2c_fd);
    printf("\nExiting gracefully.\n");
    return 0;
}

