        0b01100110, // 4
        0b01101101, // 5
        0b01111101, // 6
        0b00000111, // 7
        0b01111111, // 8
        0b01101111  // 9
    };
    if (digit < 0 || digit > 9) digit = 0;
    shift_out(segments[digit]);
