#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define LED_PIN 17
#define BUTTON_PIN 18
#define CHIP_NAME "gpiochip0"
#define CONSUMER "blink_button"

static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    struct gpiod_line_event event;
    struct timespec ts = {1, 0}; // 1-second timeout
    int ret;

    // Set up signal handler for graceful exit
    signal(SIGINT, handle_sigint);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request LED line as output, initially low
    ret = gpiod_line_request_output(led_line, CONSUMER, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get button line
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Failed to get button line %d: %s\n", BUTTON_PIN, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request button line as input with pull-up and falling-edge events
    ret = gpiod_line_request_falling_edge_events_flags(button_line, CONSUMER, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to request button line as input: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Blinking LED on BCM GPIO17. Press the button (BCM GPIO18) to stop.\n");

    // Main loop: blink while waiting for button event
    while (keep_running) {
        // Toggle LED
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set LED high: %s\n", strerror(errno));
            break;
        }
        sleep(1);
        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set LED low: %s\n", strerror(errno));
            break;
        }
        sleep(1);

        // Check for button event with timeout
        ret = gpiod_line_event_wait(button_line, &ts);
        if (ret < 0) {
            if (errno == EINTR) continue; // Interrupted by signal, check keep_running
            fprintf(stderr, "Failed to wait for button event: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) continue; // Timeout, continue blinking

        // Event detected, read it
        ret = gpiod_line_event_read(button_line, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to read button event: %s\n", strerror(errno));
            break;
        }

        // Falling edge detected (button press)
        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            printf("Button pressed! Stopping.\n");
            break;
        }
    }

    // Cleanup: turn off LED and release resources
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

