#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 24
#define BUTTON_PIN 22
#define CHIP_NAME "gpiochip0"
#define BLINK_DELAY_MS 500

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    int ret;

    /* Register signal handlers for clean shutdown */
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    /* Get the LED line */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the button line */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Failed to get button line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request LED line as output, initially low */
    ret = gpiod_line_request_output(led_line, "led-blink", 0);
    if (ret < 0) {
        perror("Failed to request LED line as output");
        goto cleanup;
    }

    /* Request button line as input with internal pull-down */
    ret = gpiod_line_request_input_flags(button_line, "button-reader",
                                          GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN);
    if (ret < 0) {
        perror("Failed to request button line as input with pull-down");
        goto cleanup;
    }

    printf("LED on GPIO24, button on GPIO22. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int button_val = gpiod_line_get_value(button_line);
        if (button_val < 0) {
            perror("Failed to read button value");
            break;
        }

        if (button_val == 0) {
            /* Button pressed: blink LED */
            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                perror("Failed to turn LED on");
                break;
            }
            usleep(BLINK_DELAY_MS * 1000);
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("Failed to turn LED off");
                break;
            }
            usleep(BLINK_DELAY_MS * 1000);
        } else {
            /* Button released: keep LED off */
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("Failed to turn LED off");
                break;
            }
            usleep(10000); /* 10 ms poll interval */
        }
    }

cleanup:
    /* Ensure LED is off before releasing */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nClean exit.\n");
    return EXIT_SUCCESS;
}

