#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18
#define PWM_PERIOD_NS 10000000  /* 10 ms = 100 Hz */
#define PWM_DUTY_MAX  100
#define LOOP_DELAY_NS 100000000 /* 100 ms */

static volatile sig_atomic_t keep_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int set_pwm(struct gpiod_line *line, int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;

    long on_ns  = (long)duty * PWM_PERIOD_NS / PWM_DUTY_MAX;
    long off_ns = PWM_PERIOD_NS - on_ns;

    struct timespec ts_on  = { .tv_sec = 0, .tv_nsec = on_ns  };
    struct timespec ts_off = { .tv_sec = 0, .tv_nsec = off_ns };

    while (on_ns > 0) {
        long chunk = (on_ns > 1000000000L) ? 1000000000L : on_ns;
        if (gpiod_line_set_value(line, 1) < 0) return -1;
        clock_nanosleep(CLOCK_MONOTONIC, 0, &ts_on, NULL);
        on_ns -= chunk;
    }

    while (off_ns > 0) {
        long chunk = (off_ns > 1000000000L) ? 1000000000L : off_ns;
        if (gpiod_line_set_value(line, 0) < 0) return -1;
        clock_nanosleep(CLOCK_MONOTONIC, 0, &ts_off, NULL);
        off_ns -= chunk;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    int ret = 1;

    srand((unsigned int)time(NULL));

    /* Open GPIO chip 0 (Raspberry Pi 5) */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return 1;
    }

    red_line   = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line  = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(red_line, "rgb-led", 0) < 0 ||
        gpiod_line_request_output(green_line, "rgb-led", 0) < 0 ||
        gpiod_line_request_output(blue_line, "rgb-led", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        goto cleanup;
    }

    printf("RGB LED control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int red   = rand() % (PWM_DUTY_MAX + 1);
        int green = rand() % (PWM_DUTY_MAX + 1);
        int blue  = rand() % (PWM_DUTY_MAX + 1);

        if (set_pwm(red_line, red) < 0 ||
            set_pwm(green_line, green) < 0 ||
            set_pwm(blue_line, blue) < 0) {
            fprintf(stderr, "PWM write failed\n");
            goto cleanup;
        }

        struct timespec delay = { .tv_sec = 0, .tv_nsec = LOOP_DELAY_NS };
        nanosleep(&delay, NULL);
    }

    ret = 0;

cleanup:
    if (red_line)   gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line)  gpiod_line_release(blue_line);
    if (chip)       gpiod_chip_close(chip);

    if (ret == 0)
        printf("\nExiting cleanly.\n");
    return ret;
}

