#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define LED_GPIO 18
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define LOG_FILE "color_log.csv"
#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

/* ADPD188BI register addresses */
#define REG_MODE 0x0D
#define REG_ALS_LSB 0x64
#define REG_ALS_MSB 0x65
#define REG_RED_LSB 0x66
#define REG_RED_MSB 0x67
#define REG_GREEN_LSB 0x68
#define REG_GREEN_MSB 0x69
#define REG_BLUE_LSB 0x6A
#define REG_BLUE_MSB 0x6B

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint8_t reg_lsb, uint16_t *out) {
    char reg_buf[1] = { (char)reg_lsb };
    char data[2] = {0};

    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg_lsb, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg_lsb, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int read_sensor_data(int handle, uint16_t *als, uint16_t *r, uint16_t *g, uint16_t *b) {
    if (i2c_read_reg16(handle, REG_ALS_LSB, als) != 0) return -1;
    if (i2c_read_reg16(handle, REG_RED_LSB, r) != 0) return -1;
    if (i2c_read_reg16(handle, REG_GREEN_LSB, g) != 0) return -1;
    if (i2c_read_reg16(handle, REG_BLUE_LSB, b) != 0) return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t als, uint16_t r, uint16_t g, uint16_t b) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            als, r, g, b);
    fflush(fp);
}

static void control_led(int als_value) {
    if (als_value < 0) als_value = 0;
    if (als_value > 65535) als_value = 65535;
    int duty = (int)((float)als_value / 65535.0f * PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(LED_GPIO, duty);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioSetMode(LED_GPIO, PI_INPUT);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_write_reg8(i2c_handle, REG_MODE, 0x01) != 0) {
        fprintf(stderr, "Failed to initialize ADPD188BI (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioPWM(LED_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,als_r,als_g,als_b\n");
    fflush(log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Smart lighting system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t als = 0, r = 0, g = 0, b = 0;

        if (read_sensor_data(i2c_handle, &als, &r, &g, &b) == 0) {
            log_data(log_file, als, r, g, b);
            control_led(als);
        } else {
            fprintf(stderr, "Sensor read error; retrying in %d ms\n", RETRY_DELAY_US / 1000);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

