#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

/* FXOS8700CQ I2C address (SA0 tied to GND) */
#define FXOS8700_ADDRESS 0x1F

/* FXOS8700CQ register addresses */
#define FXOS8700_WHO_AM_I   0x0D
#define FXOS8700_WHO_AM_I_VAL 0xC7
#define FXOS8700_XYZ_DATA_CFG 0x0E
#define FXOS8700_CTRL_REG1   0x2A
#define FXOS8700_OUT_X_MSB   0x01

/* ±2g range: 4096 counts/g, 9.81 m/s^2 per g */
#define ACCEL_SENSITIVITY 4096.0f
#define GRAVITY_MPS2      9.81f
#define IMPACT_THRESHOLD  (2.0f * GRAVITY_MPS2)
#define SAMPLE_PERIOD_US  50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read a single byte register; returns 0 on success, -1 on error */
static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error: reg 0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Write a single byte register; returns 0 on success, -1 on error */
static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: reg 0x%02X, val 0x%02X, rc=%d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* Read 6 bytes of acceleration data (X, Y, Z) and convert to m/s^2 */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    char buffer[6];
    int rc = i2cReadI2CBlockData(handle, FXOS8700_OUT_X_MSB, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C block read error: expected 6 bytes, got %d\n", rc);
        return -1;
    }

    /* 14-bit left-justified: shift right by 2 */
    int16_t raw_x = (int16_t)(((uint16_t)buffer[0] << 8) | (uint8_t)buffer[1]) >> 2;
    int16_t raw_y = (int16_t)(((uint16_t)buffer[2] << 8) | (uint8_t)buffer[3]) >> 2;
    int16_t raw_z = (int16_t)(((uint16_t)buffer[4] << 8) | (uint8_t)buffer[5]) >> 2;

    *x = (float)raw_x / ACCEL_SENSITIVITY * GRAVITY_MPS2;
    *y = (float)raw_y / ACCEL_SENSITIVITY * GRAVITY_MPS2;
    *z = (float)raw_z / ACCEL_SENSITIVITY * GRAVITY_MPS2;
    return 0;
}

static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

static void log_impact(float x, float y, float z, float magnitude)
{
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening impact_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z, magnitude);

    if (fclose(fp) != 0) {
        perror("Error closing impact_log.txt");
    }
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at FXOS8700 address */
    g_i2c_handle = i2cOpen(1, FXOS8700_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: rc=%d\n",
                FXOS8700_ADDRESS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify device identity */
    uint8_t who_am_i = 0;
    if (read_register(g_i2c_handle, FXOS8700_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure ±2g range */
    if (write_register(g_i2c_handle, FXOS8700_XYZ_DATA_CFG, 0x00) != 0) {
        fprintf(stderr, "Failed to configure XYZ_DATA_CFG\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Put sensor into standby (clear bit 0 of CTRL_REG1) */
    if (write_register(g_i2c_handle, FXOS8700_CTRL_REG1, 0x00) != 0) {
        fprintf(stderr, "Failed to set standby mode\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Activate: bit 0 = active mode, 200 Hz ODR (0x01) */
    if (write_register(g_i2c_handle, FXOS8700_CTRL_REG1, 0x01) != 0) {
        fprintf(stderr, "Failed to activate sensor\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float x, y, z, magnitude;

        if (read_acceleration(g_i2c_handle, &x, &y, &z) != 0) {
            /* Read error: log and continue rather than crash */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        magnitude = calculate_magnitude(x, y, z);

        if (magnitude > IMPACT_THRESHOLD) {
            log_impact(x, y, z, magnitude);
            printf("Impact detected! Magnitude: %.3f m/s^2\n", magnitude);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

