#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REG 0x01
#define CONTROL_REG 0x00
#define ENABLE_MEASUREMENT 0x80
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE "audio_log.dat"

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_sensor(int handle, int addr) {
    if (i2cWriteByteData(handle, CONTROL_REG, ENABLE_MEASUREMENT) < 0) {
        fprintf(stderr, "Error enabling measurement on sensor 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, int addr, int16_t *data) {
    int raw = i2cReadWordData(handle, DATA_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading data from sensor 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    *data = (int16_t)raw;
    return 0;
}

static void log_data(FILE *fp, struct timespec ts, int16_t s1, int16_t s2, double tdoa) {
    fprintf(fp, "%ld.%09ld,%d,%d,%.6f\n", ts.tv_sec, ts.tv_nsec, s1, s2, tdoa);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle1 = i2cOpen(1, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 1 (0x%02X): %s\n", SENSOR1_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle2 = i2cOpen(1, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 2 (0x%02X): %s\n", SENSOR2_ADDR, strerror(errno));
        i2cClose(i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(i2c_handle1, SENSOR1_ADDR) < 0 || init_sensor(i2c_handle2, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting bat echolocation analysis. Press Ctrl+C to stop.\n");

    while (running) {
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            fprintf(stderr, "Error getting time: %s\n", strerror(errno));
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int16_t s1 = 0, s2 = 0;
        if (read_sensor_data(i2c_handle1, SENSOR1_ADDR, &s1) < 0 ||
            read_sensor_data(i2c_handle2, SENSOR2_ADDR, &s2) < 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double tdoa = (double)s1 - (double)s2;
        log_data(log_file, ts, s1, s2, tdoa);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    fclose(log_file);
    i2cClose(i2c_handle1);
