#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADIS16488A register addresses */
#define REG_GYRO_XOUT 0x04
#define REG_GYRO_YOUT 0x06
#define REG_GYRO_ZOUT 0x08
#define REG_ACCEL_XOUT 0x0A
#define REG_ACCEL_YOUT 0x0C
#define REG_ACCEL_ZOUT 0x0E

/* Sensitivities (LSB units) */
#define GYRO_SENSITIVITY 0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY 0.00025f /* g/LSB */

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0x10000000  /* mode 3: CPOL=1, CPHA=1, aux off */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t running = 1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Cleanup helper: close SPI, file, terminate pigpio */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }
    gpioTerminate();
}

/* Read a 16-bit register from the ADIS16488A.
 * Protocol: send a 16-bit word whose MSB is 0 and whose LSB is the
 * 7-bit register address; the data is returned on the next 16-bit
 * transfer.  We use a dummy read of 0x0000 to satisfy the device's
 * read-acknowledge cycle. */
static int read_register(uint8_t reg, int16_t *value) {
    char tx[2], rx[2];
    int ret;

    /* Request register read: MSB=0, LSB=reg */
    tx[0] = 0x00;
    tx[1] = reg;

    /* Stall 40 us to satisfy the ADIS16488A read-acknowledge cycle */
    gpioDelay(40);

    /* Dummy read: send 0x0000 to get the register data */
    tx[0] = 0x00;
    tx[1] = 0x00;

    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "spiXfer (request) failed for reg 0x%02X: %d\n", reg, ret);
        return -1;
    }

    /* Data transfer: send 0x0000 to read the requested register */
    tx[0] = 0x00;
    tx[1] = 0x00;

    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "spiXfer (data) failed for reg 0x%02X: %d\n", reg, ret);
        return -1;
    }

    *value = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* Read all six sensor axes and convert to physical units */
static void read_imu_data(int16_t *gx, int16_t *gy, int16_t *gz,
                          int16_t *ax, int16_t *ay, int16_t *az) {
    if (read_register(REG_GYRO_XOUT, gx) != 0) *gx = 0;
    if (read_register(REG_GYRO_YOUT, gy) != 0) *gy = 0;
    if (read_register(REG_GYRO_ZOUT, gz) != 0) *gz = 0;
    if (read_register(REG_ACCEL_XOUT, ax) != 0) *ax = 0;
    if (read_register(REG_ACCEL_YOUT, ay) != 0) *ay = 0;
    if (read_register(REG_ACCEL_ZOUT, az) != 0) *az = 0;
}

/* Log one sample to the CSV file */
static void log_data(int16_t gx, int16_t gy, int16_t gz,
                     int16_t ax, int16_t ay, int16_t az) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[40];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000);

    fprintf(csv_file, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp,
            (float)gx * GYRO_SENSITIVITY,
            (float)gy * GYRO_SENSITIVITY,
            (float)gz * GYRO_SENSITIVITY,
            (float)ax * ACCEL_SENSITIVITY,
            (float)ay * ACCEL_SENSITIVITY,
            (float)az * ACCEL_SENSITIVITY);
    fflush(csv_file);
}

int main(void) {
    int16_t gx, gy, gz, ax, ay, az;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 at 1 MHz, mode 3 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV file in append mode */
    csv_file = fopen("imu_data.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(csv_file, 0, SEEK_END);
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
        fflush(csv_file);
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGUSR1, &sa, NULL);
    sigaction(SIGUSR2, &sa, NULL);

    /* Register cleanup on every exit path */
    atexit(cleanup);

    /* Main sampling loop */
    while (running) {
        read_imu_data(&gx, &gy, &gz, &ax, &ay, &az);
        log_data(gx, gy, gz, ax, ay, az);
        gpioDelay(100000); /* 100 ms */
    }

    return EXIT_SUCCESS;
}

