#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define CS_GPIO_CHIP    "gpiochip4"
#define CS_GPIO_LINE    8
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define SAMPLE_DELAY_MS 100

/* ADIS16448 register addresses */
#define REG_XGYRO_OUT   0x04
#define REG_YGYRO_OUT   0x06
#define REG_ZGYRO_OUT   0x08
#define REG_XACCL_OUT   0x0A
#define REG_YACCL_OUT   0x0C
#define REG_ZACCL_OUT   0x0E

/* Scale factors (from datasheet) */
#define GYRO_SCALE      0.02f   /* degrees/sec per LSB */
#define ACCL_SCALE      0.00025f /* g per LSB */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read a 16-bit register from the ADIS16448 via SPI.
 * Protocol: send 16-bit address with bit 7 set (read), then read 16-bit data.
 * Returns 0 on success, -1 on error. */
static int adis_read_reg(int spi_fd, struct gpiod_line *cs, uint8_t reg, int16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0, 0 };
    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (gpiod_line_set_value(cs, 0) < 0) {
        fprintf(stderr, "CS low failed: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI read transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs, 1) < 0) {
        fprintf(stderr, "CS high failed: %s\n", strerror(errno));
        return -1;
    }

    /* ADIS16448 sends data MSB first */
    *out = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

static void log_data(float gyro_x, float gyro_y, float gyro_z,
                     float accl_x, float accl_y, float accl_z)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps | "
           "Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
           ts, gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z);
    fflush(stdout);
}

int main(void)
{
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs = NULL;
    int ret = EXIT_FAILURE;

    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open libgpiod chip and request CS line */
    chip = gpiod_chip_open_by_name(CS_GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CS_GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    cs = gpiod_chip_get_line(chip, CS_GPIO_LINE);
    if (!cs) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs, "adis16448-cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open SPI device */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("ADIS16448 IMU reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t raw_gx, raw_gy, raw_gz, raw_ax, raw_ay, raw_az;

        if (adis_read_reg(spi_fd, cs, REG_XGYRO_OUT, &raw_gx) < 0 ||
            adis_read_reg(spi_fd, cs, REG_YGYRO_OUT, &raw_gy) < 0 ||
            adis_read_reg(spi_fd, cs, REG_ZGYRO_OUT, &raw_gz) < 0 ||
            adis_read_reg(spi_fd, cs, REG_XACCL_OUT, &raw_ax) < 0 ||
            adis_read_reg(spi_fd, cs, REG_YACCL_OUT, &raw_ay) < 0 ||
            adis_read_reg(spi_fd, cs, REG_ZACCL_OUT, &raw_az) < 0) {
            fprintf(stderr, "SPI read error, retrying...\n");
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }

        float gyro_x = (float)raw_gx * GYRO_SCALE;
        float gyro_y = (float)raw_gy * GYRO_SCALE;
        float gyro_z = (float)raw_gz * GYRO_SCALE;
        float accl_x = (float)raw_ax * ACCL_SCALE;
        float accl_y = (float)raw_ay * ACCL_SCALE;
        float accl_z = (float)raw_az * ACCL_SCALE;

        log_data(gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z);

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (spi_fd >= 0)
        close(spi_fd);
    if (cs)
        gpiod_line_release(cs);
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

