#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>

/* ADIS16448 Register Addresses */
#define ADIS16448_X_GYRO_OUT  0x04
#define ADIS16448_Y_GYRO_OUT  0x06
#define ADIS16448_Z_GYRO_OUT  0x08
#define ADIS16448_X_ACCL_OUT  0x0A
#define ADIS16448_Y_ACCL_OUT  0x0C
#define ADIS16448_Z_ACCL_OUT  0x0E

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0

/* Scaling factors (from ADIS16448 datasheet) */
#define GYRO_SCALE  0.05f   /* deg/sec per LSB */
#define ACCL_SCALE  0.00025f /* g per LSB */

/* Globals for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* Signal handler for Ctrl+C */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Read a 16-bit register from the ADIS16448 via two-cycle SPI.
 * Returns 0 on success, -1 on SPI transfer failure. */
static int read_register(uint8_t reg, int16_t *out) {
    char tx_buf[2];
    char rx_buf[2];

    /* ADIS16448 requires two SPI transfers per register read:
     * 1) Send the read command (reg | 0x8000) in the first 16-bit transfer.
     * 2) Send a dummy 0x0000 in the second 16-bit transfer to clock out the data.
     * The ADIS16448 returns the data in the second transfer. */

    /* Build the read command: set bit 15 (read) and mask the 15-bit address */
    uint16_t cmd = (uint16_t)(reg | 0x8000);

    /* First transfer: send command */
    tx_buf[0] = (char)(cmd >> 8);
    tx_buf[1] = (char)(cmd & 0xFF);

    if (spiXfer(g_spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI transfer failed (read cmd 0x%04X)\n", cmd);
        return -1;
    }

    /* Stall: ADIS16448 requires at least 40 microseconds between the two SPI cycles */
    gpioDelay(40); /* microseconds */

    /* Second transfer: send dummy 0x0000 to clock out the data */
    tx_buf[0] = 0x00;
    tx_buf[1] = 0x00;

    if (spiXfer(g_spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI transfer failed (read data 0x%04X)\n", cmd);
        return -1;
    }

    /* Combine the two received bytes into a 16-bit signed value */
    *out = (int16_t)(((uint16_t)(uint8_t)rx_buf[0] << 8) | (uint8_t)rx_buf[1]);
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 at 1 MHz, Mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d, mode %d)\n",
                SPI_CHANNEL, SPI_SPEED, SPI_MODE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADIS16448 IMU Reader (pigpio)\n");
    printf("SPI channel %d, %d Hz, Mode %d\n", SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main loop */
    while (g_running) {
        int16_t gyro_x, gyro_y, gyro_z;
        int16_t accl_x, accl_y, accl_z;

        if (read_register(ADIS16448_X_GYRO_OUT, &gyro_x) != 0 ||
            read_register(ADIS16448_Y_GYRO_OUT, &gyro_y) != 0 ||
            read_register(ADIS16448_Z_GYRO_OUT, &gyro_z) != 0 ||
            read_register(ADIS16448_X_ACCL_OUT, &accl_x) != 0 ||
            read_register(ADIS16448_Y_ACCL_OUT, &accl_y) != 0 ||
            read_register(ADIS16448_Z_ACCL_OUT, &accl_z) != 0) {
            fprintf(stderr, "Failed to read one or more IMU registers. Exiting.\n");
            break;
        }

        /* Convert raw values to physical units */
        float gyro_x_dps = (float)gyro_x * GYRO_SCALE;
        float gyro_y_dps = (float)gyro_y * GYRO_SCALE;
        float gyro_z_dps = (float)gyro_z * GYRO_SCALE;
        float accl_x_g   = (float)accl_x * ACCL_SCALE;
        float accl_y_g   = (float)accl_y * ACCL_SCALE;
        float accl_z_g   = (float)accl_z * ACCL_SCALE;

        /* Print the data to the console */
        printf("Gyro X: %8.2f deg/sec | Gyro Y: %8.2f deg/sec | Gyro Z: %8.2f deg/sec | "
               "Accel X: %8.4f g | Accel Y: %8.4f g | Accel Z: %8.4f g\n",
               gyro_x_dps, gyro_y_dps, gyro_z_dps, accl_x_g, accl_y_g, accl_z_g);

        /* Wait 100 ms */
        gpioDelay(100000); /* microseconds */
    }

    /* Clean up */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

