        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, EXPECTED_WHO_AM_I);
        goto cleanup;
    }

    if (i2c_write_reg8(fd, REG_PWR_MGMT_1, 0x00) != 0) {
        goto cleanup;
    }
    usleep(100000);

    if (i2c_write_reg8(fd, REG_ACCEL_CONFIG, 0x00) != 0) {
        goto cleanup;
    }
    if (i2c_write_reg8(fd, REG_GYRO_CONFIG, 0x00) != 0) {
