        int16_t ax = 0, ay = 0, az = 0, gx = 0, gy = 0, gz = 0;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_sensor_data(fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
                success = 1;
