            float gy_dps = gy * GYRO_SCALE / 32768.0f;
            float gz_dps = gz * GYRO_SCALE / 32768.0f;

            printf("Accel: X=%.3f g, Y=%.3f g, Z=%.3f g | Gyro: X=%.3f dps, Y=%.3f dps, Z=%.3f dps\n",
