#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_DEVID   0x00
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0  0x32
#define ADXL345_BW_RATE 0x2C
#define ADXL345_FILTER  0x2D
#define ADXL345_RANGE_2G 0x00
#define ADXL345_RANGE_4G 0x01
#define ADXL345_RANGE_8G 0x02
#define ADXL345_RANGE_16G 0x03

#define LED_GPIO 17
#define IMPACT_THRESHOLD 2.5f
#define POLL_DELAY_US 10000
#define LED_ON_TIME_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int adxl345_init(int handle) {
    int devid = i2cReadByteData(handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error: Failed to read DEVID register (I2C error: %d)\n", devid);
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Error: ADXL345 not detected (DEVID=0x%02X, expected 0xE5)\n", devid);
        return -1;
    }

    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset POWER_CTL\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2cWriteByteData(handle, ADXL345_BW_RATE, 0x0A) < 0) {
        fprintf(stderr, "Error: Failed to set BW_RATE\n");
        return -1;
    }

    if (i2cWriteByteData(handle, ADXL345_FILTER, ADXL345_RANGE_2G) < 0) {
        fprintf(stderr, "Error: Failed to set range\n");
        return -1;
    }

    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to enable measurement mode\n");
        return -1;
    }

    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read acceleration data\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x / 256.0f;
    *y = (float)raw_y / 256.0f;
    *z = (float)raw_z / 256.0f;

    return 0;
}

static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void log_impact(FILE *fp, float magnitude, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - Impact: Magnitude = %.2f g, X = %.2f g, Y = %.2f g, Z = %.2f g\n",
            timestamp, magnitude, x, y, z);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X (error %d)\n", ADXL345_ADDRESS, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (adxl345_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);

    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open impact_log.txt for appending\n");
        cleanup();
        return 1;
    }

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            float magnitude = calculate_magnitude(x, y, z);
            if (magnitude > IMPACT_THRESHOLD) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                gpioWrite(LED_GPIO, 1);
                log_impact(log_file, magnitude, x, y, z);
                gpioDelay(LED_ON_TIME_US);
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, retrying...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

