#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define MMA8451_ADDR        0x1D
#define MMA8451_WHO_AM_I    0x0D
#define MMA8451_WHO_AM_I_VAL 0x1A
#define MMA8451_XYZ_DATA_CFG 0x0E
#define MMA8451_CTRL_REG1   0x2A
#define MMA8451_OUT_X_MSB   0x01

#define LED_PIN             17
#define I2C_BUS             "/dev/i2c-1"
#define IMPACT_THRESHOLD    2.0f
#define POLL_INTERVAL_MS    100
#define LED_ON_MS           500
#define G_PER_COUNT         1024.0f

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (burst reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mma8451(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg(fd, MMA8451_WHO_AM_I, &who_am_i) < 0) return -1;
    if (who_am_i != MMA8451_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, MMA8451_WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg(fd, MMA8451_XYZ_DATA_CFG, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, MMA8451_CTRL_REG1, 0x01) < 0) return -1;
    return 0;
}

static int read_accel(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, MMA8451_OUT_X_MSB, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *x = (float)raw_x / G_PER_COUNT;
    *y = (float)raw_y / G_PER_COUNT;
    *z = (float)raw_z / G_PER_COUNT;
    return 0;
}

static void log_impact(float x, float y, float z) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open impact_log.txt: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s - Impact: X=%.2f g, Y=%.2f g, Z=%.2f g\n", ts, x, y, z);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MMA8451_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_mma8451(i2c_fd) < 0) {
        fprintf(stderr, "MMA8451 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led, "mma8451_impact", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    printf("MMA8451 impact detection started. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        if (read_accel(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        float mag = sqrtf(x * x + y * y + z * z);
        if (mag > IMPACT_THRESHOLD) {
            printf("Impact detected! X=%.2f g, Y=%.2f g, Z=%.2f g, Mag=%.2f g\n", x, y, z, mag);
            gpiod_line_set_value(led, 1);
            log_impact(x, y, z);
            usleep(LED_ON_MS * 1000);
            gpiod_line_set_value(led, 0);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

