#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <poll.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_THRESH_FF 0x24
#define ADXL345_REG_TIME_FF 0x20
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_MAP 0x2F
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_FILTER_CTL 0x2D
#define ADXL345_REG_POWER_CTL_MEASURE 0x08
#define ADXL345_REG_POWER_CTL_STANDBY 0x00
#define ADXL345_REG_DEVID_EXPECTED 0xE5

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_OFFSET 17
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "freefall_log.csv"

static volatile sig_atomic_t program_running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int adxl345_init(int fd) {
    uint8_t devid = 0;
    if (i2c_read_reg8(fd, ADXL345_REG_DEVID, &devid) < 0) {
        return -1;
    }
    if (devid != ADXL345_REG_DEVID_EXPECTED) {
        fprintf(stderr, "ADXL345 not found: DEVID=0x%02X (expected 0x%02X)\n", devid, ADXL345_REG_DEVID_EXPECTED);
        return -1;
    }

    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, ADXL345_REG_POWER_CTL_STANDBY) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg8(fd, ADXL345_REG_INT_ENABLE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_REG_INT_MAP, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_REG_TIME_FF, 0x0A) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_REG_THRESH_FF, 0x0A) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_REG_INT_ENABLE, 0x04) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, ADXL345_REG_POWER_CTL_MEASURE) < 0) return -1;

    return 0;
}

static int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "Failed to read acceleration data: %s\n", strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long milliseconds = ts.tv_nsec / 1000000;
    if (fprintf(fp, "%s.%03ld,%d,%d,%d\n", timestamp, milliseconds, x, y, z) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        i2c_write_reg8(i2c_fd, ADXL345_REG_INT_ENABLE, 0x00);
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        cleanup();
        return 1;
    }

    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed.\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        cleanup();
        return 1;
    }
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_falling_edge_events(line, "adxl345_freefall") < 0) {
        fprintf(stderr, "Failed to request falling edge events on GPIO %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }

    printf("Freefall detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        struct pollfd pfd;
        pfd.fd = gpiod_line_event_get_fd(line);
        pfd.events = POLLIN;
        int ret = poll(&pfd, 1, 1000);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "poll failed: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) continue;
        if (pfd.revents & POLLIN) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(line, &event) < 0) {
                if (errno == EINTR) continue;
                fprintf(stderr, "Failed to read GPIO event: %s\n", strerror(errno));
                continue;
            }
            if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                uint8_t int_source = 0;
                if (i2c_read_reg8(i2c_fd, ADXL345_REG_INT_SOURCE, &int_source) < 0) {
                    fprintf(stderr, "Failed to read INT_SOURCE during freefall event.\n");
                    continue;
                }
                if (int_source & 0x04) {
                    int16_t x, y, z;
                    if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
                        if (log_data(log_file, x, y, z) < 0) {
                            fprintf(stderr, "Failed to log data.\n");
                        }
                    } else {
                        fprintf(stderr, "Failed to read acceleration data during freefall event.\n");
                    }
                }
            }
        }
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

