        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        i2c_write_reg8(i2c_fd, ADXL345_REG_INT_ENABLE, 0x00);
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        cleanup();
        return 1;
    }

    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed.\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        cleanup();
        return 1;
    }
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_falling_edge_events(line, "adxl345_freefall") < 0) {
        fprintf(stderr, "Failed to request falling edge events on GPIO %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }

    printf("Freefall detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        struct pollfd pfd;
        pfd.fd = gpiod_line_event_get_fd(line);
        pfd.events = POLLIN;
        int ret = poll(&pfd, 1, 1000);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "poll failed: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) continue;
        if (pfd.revents & POLLIN) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(line, &event) < 0) {
                if (errno == EINTR) continue;
                fprintf(stderr, "Failed to read GPIO event: %s\n", strerror(errno));
                continue;
            }
            if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                uint8_t int_source = 0;
                if (i2c_read_reg8(i2c_fd, ADXL345_REG_INT_SOURCE, &int_source) < 0) {
                    fprintf(stderr, "Failed to read INT_SOURCE during freefall event.\n");
                    continue;
                }
                if (int_source & 0x04) {
                    int16_t x, y, z;
                    if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
                        if (log_data(log_file, x, y, z) < 0) {
                            fprintf(stderr, "Failed to log data.\n");
                        }
                    } else {
                        fprintf(stderr, "Failed to read acceleration data during freefall event.\n");
                    }
                }
            }
        }
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

