#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define LSM6DSR_ADDR 0x6A
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0x6A
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

#define ACCEL_SENSITIVITY 0.061f
#define GYRO_SENSITIVITY 8.75f
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define IMPACT_WINDOW 1.0f
#define SAMPLE_PERIOD_US 10000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

typedef enum {
    IDLE,
    FREEFALL,
    IMPACT
} fall_state_t;

static fall_state_t state = IDLE;
static time_t freefall_start_time = 0;
static float freefall_max_accel = 0.0f;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    int who = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) {
        fprintf(stderr, "Error writing CTRL1_XL\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) {
        fprintf(stderr, "Error writing CTRL2_G\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    return 0;
}

static int read_accel(float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buf, 6) != 6) {
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x * ACCEL_SENSITIVITY;
    *y = (float)raw_y * ACCEL_SENSITIVITY;
    *z = (float)raw_z * ACCEL_SENSITIVITY;
    return 0;
}

static int read_gyro(float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buf, 6) != 6) {
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x * GYRO_SENSITIVITY;
    *y = (float)raw_y * GYRO_SENSITIVITY;
    *z = (float)raw_z * GYRO_SENSITIVITY;
    return 0;
}

static void log_data(float ax, float ay, float az, float gx, float gy, float gz) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", ts, ax, ay, az, gx, gy, gz);
    fflush(log_file);
}

static void fall_detection(float ax, float ay, float az) {
    float mag = sqrtf(ax * ax + ay * ay + az * az);
    time_t now = time(NULL);

    switch (state) {
        case IDLE:
            if (mag < FREEFALL_THRESHOLD) {
                state = FREEFALL;
                freefall_start_time = now;
                freefall_max_accel = mag;
            }
            break;
        case FREEFALL:
            if (mag > freefall_max_accel) {
                freefall_max_accel = mag;
            }
            if (difftime(now, freefall_start_time) > IMPACT_WINDOW) {
                state = IMPACT;
            }
            break;
        case IMPACT:
            break;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen("motion_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float ax, ay, az, gx, gy, gz;
        if (read_accel(&ax, &ay, &az) == 0 && read_gyro(&gx, &gy, &gz) == 0) {
            log_data(ax, ay, az, gx, gy, gz);
            fall_detection(ax, ay, az);
        } else {
            fprintf(stderr, "I2C read error\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

