    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, len);
    if (ret != len) {
        fprintf(stderr, "SPI transfer failed (returned %d, expected %d): %s\n",
                ret, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register                                              */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, uint16_t *value)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    if (spi_transfer(tx, rx, 2) != 0)
        return -1;

    /* ADIS16266 returns data in the second byte of the response */
    *value = (uint16_t)rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify device identity                                              */
/* ------------------------------------------------------------------ */
static int verify_device_id(uint16_t who_am_i)
{
    if (who_am_i == ADIS16266_WHO_AM_I_VAL) {
        printf("ADIS16266 detected (WHO_AM_I = 0x%04X)\n", who_am_i);
        return 0;
    }
    fprintf(stderr, "Unexpected WHO_AM_I value: 0x%04X (expected 0x%04X)\n",
            who_am_i, ADIS16266_WHO_AM_I_VAL);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Log a timestamped angular-rate reading                              */
/* ------------------------------------------------------------------ */
static void log_data(float gyro_rate)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,%.4f\n", timestamp, gyro_rate);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file once */
    g_log_file = fopen("gyro_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open gyro_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,GyroRate_dps\n");
        fflush(g_log_file);
    }

    /* Verify device identity */
    uint16_t who_am_i = 0;
    if (read_register(ADIS16266_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (verify_device_id(who_am_i) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging ADIS16266 X_GYRO_OUT every 10 ms. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t raw = 0;
        if (read_register(ADIS16266_X_GYRO_OUT, &raw) != 0) {
            fprintf(stderr, "Failed to read X_GYRO_OUT register\n");
            break;
        }

        float gyro_rate = (float)raw * GYRO_SCALE;
        log_data(gyro_rate);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

