#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* GY-50 L3G4200D I2C address (SA0 tied to GND) */
#define GYRO_ADDR 0x69

/* L3G4200D register addresses */
#define WHO_AM_I   0x0F
#define CTRL_REG1  0x20
#define CTRL_REG4  0x23
#define OUT_X_L    0x28

/* Expected device ID */
#define WHO_AM_I_VAL 0xD3

/* Sensitivity for +/-250 dps range: 8.75 mdps/LSB */
#define SENSITIVITY 114.285f

/* I2C bus on Raspberry Pi 4 Model B */
#define I2C_BUS 1

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 10000

/* Retry count for I2C operations */
#define I2C_RETRY_COUNT 3

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; cleanup happens in main()          */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a byte to a register with retry                              */
/* ------------------------------------------------------------------ */
static int gyro_write_reg(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < I2C_RETRY_COUNT; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "Warning: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed (rc=%d), attempt %d/%d\n",
                reg, value, rc, attempt + 1, I2C_RETRY_COUNT);
        gpioDelay(1000); /* 1 ms backoff */
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read WHO_AM_I register and verify device identity                 */
/* ------------------------------------------------------------------ */
static int gyro_verify_device(int handle)
{
    int id = i2cReadByteData(handle, WHO_AM_I);
    if (id < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register (rc=%d)\n", id);
        return -1;
    }
    if (id != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                id, WHO_AM_I_VAL);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the L3G4200D gyroscope                                 */
/* ------------------------------------------------------------------ */
static int gyro_init(int handle)
{
    /* CTRL_REG1: 0x0F = normal mode, all axes enabled, 100 Hz ODR */
    if (gyro_write_reg(handle, CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG1\n");
        return -1;
    }

    /* CTRL_REG4: 0x00 = +/-250 dps full-scale, continuous update */
    if (gyro_write_reg(handle, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG4\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of angular velocity data (X, Y, Z)                   */
/* ------------------------------------------------------------------ */
static int gyro_read_data(int handle, float *x, float *y, float *z)
{
    char buffer[6];

    /* Read 6 bytes starting at OUT_X_L in a single block transfer */
    int rc = i2cReadI2CBlockData(handle, OUT_X_L, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "Error: i2cReadI2CBlockData returned %d (expected 6)\n", rc);
        return -1;
    }

    /* Data is little-endian: low byte first, high byte second */
    int16_t raw_x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);

    /* Convert to degrees per second */
    *x = (float)raw_x / SENSITIVITY;
    *y = (float)raw_y / SENSITIVITY;
    *z = (float)raw_z / SENSITIVITY;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample with nanosecond timestamp                           */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Warning: clock_gettime failed: %s\n", strerror(errno));
        ts.tv_sec = 0;
        ts.tv_nsec = 0;
    }

    fprintf(fp, "%ld.%09ld,%.4f,%.4f,%.4f\n",
            (long)ts.tv_sec, ts.tv_nsec, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup — release all resources                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                              */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at GY-50 address */
    g_i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed (rc=%d)\n",
                I2C_BUS, GYRO_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify device identity */
    if (gyro_verify_device(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: L3G4200D not detected at address 0x%02X\n", GYRO_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize gyroscope */
    if (gyro_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: gyroscope initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("gyro_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open gyro_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,X,Y,Z\n");
        fflush(g_log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Gyroscope logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (gyro_read_data(g_i2c_handle, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
        } else {
            fprintf(stderr, "Warning: read failed, continuing...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

