#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x53
#define CSV_FILE       "vibration_log.csv"
#define SAMPLE_MS      100
#define REG_X_LSB      0x28
#define REG_X_MSB      0x29
#define REG_Y_LSB      0x2A
#define REG_Y_MSB      0x2B
#define REG_Z_LSB      0x2C
#define REG_Z_MSB      0x2D

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_axis(int fd, uint8_t lsb_reg, uint8_t msb_reg, int16_t *out)
{
    uint8_t lsb = 0, msb = 0;
    if (i2c_read_reg8(fd, lsb_reg, &lsb) < 0)
        return -1;
    if (i2c_read_reg8(fd, msb_reg, &msb) < 0)
        return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm_utc;
    char ts[32];
    if (!gmtime_r(&t, &tm_utc)) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", D7S_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Probe: try a zero-length read to detect a NACK (sensor absent). */
    uint8_t probe;
    ssize_t n = read(fd, &probe, 0);
    if (n < 0) {
        fprintf(stderr, "I2C probe read failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(CSV_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Write header if file is empty. */
    if (ftell(fp) == 0) {
        if (fprintf(fp, "Timestamp,X,Y,Z\n") < 0) {
            fprintf(stderr, "write header failed: %s\n", strerror(errno));
            fclose(fp);
            close(fd);
            return EXIT_FAILURE;
        }
        fflush(fp);
    }

    printf("Vibration monitoring started. Logging to %s every %d ms. Press Ctrl+C to stop.\n",
           CSV_FILE, SAMPLE_MS);

    while (g_running) {
        int16_t x = 0, y = 0, z = 0;
        int err = 0;

        if (read_axis(fd, REG_X_LSB, REG_X_MSB, &x) < 0) err = 1;
        if (read_axis(fd, REG_Y_LSB, REG_Y_MSB, &y) < 0) err = 1;
        if (read_axis(fd, REG_Z_LSB, REG_Z_MSB, &z) < 0) err = 1;

        if (err) {
            fprintf(stderr, "Sensor read error — skipping sample.\n");
        } else {
            if (log_data(fp, x, y, z) < 0) {
                fprintf(stderr, "CSV write error — continuing.\n");
            }
        }

        /* Sleep SAMPLE_MS, but wake early on signal. */
        struct timespec ts = { .tv_sec = SAMPLE_MS / 1000,
                               .tv_nsec = (SAMPLE_MS % 1000) * 1000000L };
        nanosleep(&ts, NULL);
    }

    printf("\nShutting down cleanly.\n");
    if (fclose(fp) != 0)
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
    if (close(fd) != 0)
        fprintf(stderr, "close(fd) failed: %s\n", strerror(errno));
    return EXIT_SUCCESS;
}

