        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (burst reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_lis3mdl(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, WHO_AM_I, &who_am_i) < 0) return -1;
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, CTRL_REG1, CTRL1_VAL) < 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG4, CTRL4_VAL) < 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG3, CTRL3_VAL) < 0) return -1;
    return 0;
}

static int read_magnetometer(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, OUT_X_L, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x * SCALE_MG + OFFSET_X;
    *y = (float)raw_y * SCALE_MG + OFFSET_Y;
    *z = (float)raw_z * SCALE_MG + OFFSET_Z;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", LIS3MDL_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    int init_ok = 0;
    for (int attempt = 0; attempt < MAX_INIT_RETRIES; attempt++) {
        if (init_lis3mdl(g_i2c_fd) == 0) {
            init_ok = 1;
            break;
        }
        fprintf(stderr, "Init attempt %d/%d failed\n", attempt + 1, MAX_INIT_RETRIES);
        usleep(100000);
    }
    if (!init_ok) {
        fprintf(stderr, "LIS3MDL init failed after %d attempts\n", MAX_INIT_RETRIES);
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("LIS3MDL initialized. Logging to %s at %d Hz. Press Ctrl+C to stop.\n", LOG_FILE, SAMPLE_HZ);

    while (g_running) {
        float x, y, z;
        if (read_magnetometer(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_log_fp, x, y, z);
            float mag = sqrtf(x * x + y * y + z * z);
            if (mag > THRESHOLD_MG) {
                fprintf(stderr, "Metal detected! |B| = %.2f mG\n", mag);
            }
        } else {
            fprintf(stderr, "Read error; re-initializing sensor...\n");
            for (int attempt = 0; attempt < MAX_INIT_RETRIES; attempt++) {
                if (init_lis3mdl(g_i2c_fd) == 0) {
                    init_ok = 1;
                    break;
                }
                fprintf(stderr, "Re-init attempt %d/%d failed\n", attempt + 1, MAX_INIT_RETRIES);
                usleep(100000);
            }
            if (!init_ok) {
                fprintf(stderr, "Re-init failed; aborting.\n");
                break;
            }
        }
        usleep(SAMPLE_DELAY_US);
    }

    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

