#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL354B Register Addresses
#define ADXL354B_PARTID       0x01
#define ADXL354B_RESET        0x1F
#define ADXL354B_STATUS       0x04
#define ADXL354B_XDATA        0x08
#define ADXL354B_YDATA        0x0B
#define ADXL354B_ZDATA        0x0E
#define ADXL354B_POWER_CTL    0x2D

// ADXL354B Constants
#define ADXL354B_PARTID_VAL   0x1D
#define ADXL354B_RESET_VAL    0x52
#define ADXL354B_SENSITIVITY  0.0000039f  // 3.9 microg/LSB for +-2g range
#define SPI_CHANNEL           0
#define SPI_SPEED             1000000     // 1 MHz
#define SPI_MODE              0
#define LOG_FILE              "vibration_log.txt"
#define SAMPLE_INTERVAL_US    100000      // 100 ms
#define MAX_RETRIES           3

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int adxl354b_init(void);
int adxl354b_read_axis(int axis, float *value);
int adxl354b_reset(void);
int adxl354b_set_measurement_mode(void);
int adxl354b_read_register(uint8_t reg, uint8_t *value);
int adxl354b_write_register(uint8_t reg, uint8_t value);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len);
void log_data(float x, float y, float z);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Initialize the ADXL354B accelerometer
int adxl354b_init(void) {
    uint8_t partid = 0;

    // Check sensor presence
    if (adxl354b_read_register(ADXL354B_PARTID, &partid) != 0) {
        fprintf(stderr, "Error: Failed to read PARTID register.\n");
        return -1;
    }
    if (partid != ADXL354B_PARTID_VAL) {
        fprintf(stderr, "Error: Unexpected PARTID value: 0x%02X (expected 0x%02X).\n", partid, ADXL354B_PARTID_VAL);
        return -1;
    }

    // Reset the device
    if (adxl354b_reset() != 0) {
        fprintf(stderr, "Error: ADXL354B reset failed.\n");
        return -1;
    }

    // Set measurement mode
    if (adxl354b_set_measurement_mode() != 0) {
        fprintf(stderr, "Error: Failed to set measurement mode.\n");
        return -1;
    }

    return 0;
}

// Read a single axis of acceleration data
int adxl354b_read_axis(int axis, float *value) {
    uint8_t reg = 0;
    uint8_t data[3];
    int retries = 0;

    // Determine the register address based on the axis
    switch (axis) {
        case 0:  // X axis
            reg = ADXL354B_XDATA;
            break;
        case 1:  // Y axis
            reg = ADXL354B_YDATA;
            break;
        case 2:  // Z axis
            reg = ADXL354B_ZDATA;
            break;
        default:
            fprintf(stderr, "Error: Invalid axis index: %d\n", axis);
            return -1;
    }

    // Read 3 bytes of data (20-bit signed, MSB first)
    while (retries < MAX_RETRIES) {
        // SPI read command: bit 7 = 1 (read), bit 6 = 1 (multi-byte)
        uint8_t tx_buf[4] = {0x81, 0x81, reg, 0x00};
        uint8_t rx_buf[4] = {0};

        if (spi_transfer(tx_buf, rx_buf, 4) == 0) {
            // Combine the 3 bytes into a 20-bit signed value
            int32_t raw = ((int32_t)rx_buf[2] << 16) | ((int32_t)rx_buf[1] << 8) | (int32_t)rx_buf[3];
            // Sign extend from 20 bits to 32 bits
            if (raw & 0x80000) {
                raw |= 0xFFF00000;
            }
            *value = (float)raw * ADXL354B_SENSITIVITY;
            return 0;
        }
        retries++;
        gpioDelay(1000); // 1 ms delay before retry
    }

    fprintf(stderr, "Error: Failed to read axis %d after %d retries.\n", axis, MAX_RETRIES);
    return -1;
}

// Reset the ADXL354B accelerometer
int adxl354b_reset(void) {
    uint8_t reset_val = ADXL354B_RESET_VAL;
    return adxl354b_write_register(ADXL354B_RESET, reset_val);
}

// Set the ADXL354B to measurement mode
int adxl354b_set_measurement_mode(void) {
    uint8_t power_ctl = 0;
    uint8_t run_bit = 0x01;

    // Read the current POWER_CTL register value
    if (adxl354b_read_register(ADXL354B_POWER_CTL, &power_ctl) != 0) {
        return -1;
    }

    // Clear the RUN bit to enter standby mode
    power_ctl &= ~run_bit;

    // Write the updated value back to the POWER_CTL register
    if (adxl354b_write_register(ADXL354B_POWER_CTL, power_ctl) != 0) {
        return -1;
    }

    // Wait for the STABLE bit to be set (sensor stabilizes after reset)
    uint8_t status = 0;
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (adxl354b_read_register(ADXL354B_STATUS, &status) == 0) {
            if (status & 0x01) { // STABLE bit
                break;
            }
        }
        gpioDelay(1000); // 1 ms delay
        retries++;
    }

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Error: STABLE bit not set after reset.\n");
        return -1;
    }

    // Set the RUN bit to start measurement
    power_ctl |= run_bit;
    if (adxl354b_write_register(ADXL354B_POWER_CTL, power_ctl) != 0) {
        return -1;
    }

    return 0;
}

// Read a single register from the ADXL354B
int adxl354b_read_register(uint8_t reg, uint8_t *value) {
    uint8_t tx_buf[2] = {0x80 | reg, 0x00}; // Read command: bit 7 = 1
    uint8_t rx_buf[2] = {0};

    if (spi_transfer(tx_buf, rx_buf, 2) != 0) {
        return -1;
    }

    *value = rx_buf[1];
    return 0;
}

// Write a single register to the ADXL354B
int adxl354b_write_register(uint8_t reg, uint8_t value) {
    uint8_t tx_buf[2] = {reg, value}; // Write command: bit 7 = 0
    uint8_t rx_buf[2] = {0};

    if (spi_transfer(tx_buf, rx_buf, 2) != 0) {
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    int result = spiXfer(spi_handle, (char *)tx_buf, (char *)rx_buf, len);
    if (result != len) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d, expected %d).\n", result, len);
        return -1;
    }
    return 0;
}

// Log data to file
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %.6f g, Y: %.6f g, Z: %.6f g\n", timestamp, x, y, z);
    fflush(log_file);
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d).\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL354B
    if (adxl354b_init() != 0) {
        fprintf(stderr, "Error: ADXL354B initialization failed.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("ADXL354B vibration logger started. Press Ctrl+C to stop.\n");

    // Main loop
    while (!terminate) {
        float x, y, z;

        if (adxl354b_read_axis(0, &x) != 0 ||
            adxl354b_read_axis(1, &y) != 0 ||
            adxl354b_read_axis(2, &z) != 0) {
            fprintf(stderr, "Error: Failed to read acceleration data.\n");
        } else {
            log_data(x, y, z);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");

    return 0;
}

