#include <string.h>
#include <errno.h>

/* ADIS16362 Register Addresses */
#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCL 0x0A
#define Y_ACCL 0x0C
#define Z_ACCL 0x0E

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_FLAGS 0x03  /* Mode 3: active-high clock, sampled on trailing edge */

/* Scaling factors (from ADIS16362 datasheet) */
#define GYRO_SCALE 0.05f   /* deg/sec per LSB */
#define ACCL_SCALE 0.0025f /* g per LSB */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a 16-bit register from the ADIS16362.
 * Protocol: send (reg | 0x80) with MSB set, then a dummy byte.
 * The requested register's data is returned on the next 16-bit transfer.
 * Returns 0 on success, -1 on error. */
static int read_register(uint8_t reg, int16_t *value) {
    char tx[2], rx[2];
    int ret;

    /* Send read command: MSB set, no MSB set */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;
    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read command failed for reg 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }

    /* Small delay to allow conversion to complete */
    gpioDelay(1000); /* 1 ms */

    /* Read the data byte */
    tx[0] = 0x00;
    tx[1] = 0x00;
    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI data read failed for reg 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }

    *value = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* Log a data row to the CSV file */
static void log_data(float x_gyro, float y_gyro, float z_gyro,
                     float x_accel, float y_accel, float z_accel) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, ts.tv_nsec, x_gyro, y_gyro, z_gyro,
            x_accel, y_accel, z_accel);
    fflush(log_file);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed on channel %d (handle=%d)\n", SPI_CHANNEL, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    fflush(log_file);

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Logging IMU data to imu_log.csv. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
        int16_t raw_accel_x, raw_accel_y, raw_accel_z;

        if (read_register(X_GYRO, &raw_gyro_x) != 0 ||
            read_register(Y_GYRO, &raw_gyro_y) != 0 ||
            read_register(Z_GYRO, &raw_gyro_z) != 0 ||
            read_register(X_ACCL, &raw_accel_x) != 0 ||
            read_register(Y_ACCL, &raw_accel_y) != 0 ||
            read_register(Z_ACCL, &raw_accel_z) != 0) {
            fprintf(stderr, "Error reading IMU data, skipping logging.\n");
        } else {
            float x_gyro = (float)raw_gyro_x * GYRO_SCALE;
            float y_gyro = (float)raw_gyro_y * GYRO_SCALE;
            float z_gyro = (float)raw_gyro_z * GYRO_SCALE;
            float x_accel = (float)raw_accel_x * ACCL_SCALE;
            float y_accel = (float)raw_accel_y * ACCL_SCALE;
            float z_accel = (float)raw_accel_z * ACCL_SCALE;

            log_data(x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel);
        }

        gpioDelay(10000); /* 10 ms delay (~100 Hz sampling) */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

