/*
 * KY-032 IR Obstacle Avoidance Sensor Reader (libgpiod v2 API)
 * Board:  Raspberry Pi 3 Model B+
 * Sensors: Keyes KY-032 on GPIO17 (BCM) and GPIO27 (BCM)
 * Logic:  Active-low: 0 = obstacle detected, 1 = clear
 * Polling: 100 ms
 * Build:  gcc -Wall -Wextra -O2 -o ky032_avoid ky032_avoid.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_PIN_1     17
#define GPIO_PIN_2     27
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines;
    struct gpiod_line_request *req = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct timespec ts = { 0, POLL_INTERVAL_US * 1000 };
    int ret = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open the gpiochip --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure both lines as inputs --- */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "gpiod_line_settings_new failed: %s\n", strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new failed: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned int offsets[2] = { GPIO_PIN_1, GPIO_PIN_2 };
    if (gpiod_line_config_add_line_settings(line_cfg, offsets, 2, settings) != 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings failed: %s\n", strerror(errno));
        goto cleanup;
    }

    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "gpiod_request_config_new failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ky032-avoid");

    req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (req == NULL) {
        fprintf(stderr, "Failed to request GPIO lines %u and %u: %s\n",
                GPIO_PIN_1, GPIO_PIN_2, strerror(errno));
        goto cleanup;
    }

    /* --- Main polling loop --- */
    while (g_running) {
        int values[2];

        if (gpiod_line_request_get_values(req, values) != 0) {
            fprintf(stderr, "gpiod_line_request_get_values failed: %s\n", strerror(errno));
            break;
        }

        /* KY-032 is active-low: 0 => obstacle detected */
        int obstacle1 = (values[0] == 0) ? 1 : 0;
        int obstacle2 = (values[1] == 0) ? 1 : 0;

        print_timestamp();
        printf("Obstacle on GPIO%d: %s | Obstacle on GPIO%d: %s\n",
               GPIO_PIN_1, obstacle1 ? "YES" : "NO",
               GPIO_PIN_2, obstacle2 ? "YES" : "NO");

        fflush(stdout);

        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (req != NULL)
        gpiod_line_request_release(req);
    if (req_cfg != NULL)
        gpiod_request_config_free(req_cfg);
    if (line_cfg != NULL)
        gpiod_line_config_free(line_cfg);
    if (settings != NULL)
        gpiod_line_settings_free(settings);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

