#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_LINE_OFFSET 8  /* GPIO8 = SPI0 CE0 */

#define ADIS16266_REG_XGYRO_OUT 0x04
#define ADIS16266_REG_YGYRO_OUT 0x06
#define ADIS16266_REG_ZGYRO_OUT 0x08
#define ADIS16266_REG_MSC_CTRL  0x24

#define ADIS16266_SCALE_FACTOR 0.02f

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int adis16266_write_reg(int fd, uint8_t reg, uint16_t value) {
    uint8_t tx[3] = { (uint8_t)(reg | 0x80), (uint8_t)(value >> 8), (uint8_t)(value & 0xFF) };
    uint8_t rx[3] = {0};
    return spi_transfer(fd, tx, rx, 3);
}

static int adis16266_read_reg(int fd, uint8_t reg, uint16_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), 0x00 };
    uint8_t rx[2] = {0};
    if (spi_transfer(fd, tx, rx, 2) < 0) return -1;
    *value = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

static int adis16266_init(int fd) {
    if (adis16266_write_reg(fd, ADIS16266_REG_MSC_CTRL, 0x0001) < 0) return -1;
    usleep(10000);
    return 0;
}

static int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint16_t raw_x, raw_y, raw_z;
    if (adis16266_read_reg(fd, ADIS16266_REG_XGYRO_OUT, &raw_x) < 0) return -1;
    if (adis16266_read_reg(fd, ADIS16266_REG_YGYRO_OUT, &raw_y) < 0) return -1;
    if (adis16266_read_reg(fd, ADIS16266_REG_ZGYRO_OUT, &raw_z) < 0) return -1;
    *x = (float)((int16_t)raw_x) * ADIS16266_SCALE_FACTOR;
    *y = (float)((int16_t)raw_y) * ADIS16266_SCALE_FACTOR;
    *z = (float)((int16_t)raw_z) * ADIS16266_SCALE_FACTOR;
    return 0;
}

int main(void) {
    struct sigaction sa = { .sa_handler = sigint_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(cs_line, "adis16266-cs", 1) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE_3;
    uint8_t bits = 8;
    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI config");
        close(spi_fd);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (adis16266_init(spi_fd) < 0) {
        fprintf(stderr, "ADIS16266 initialization failed (sensor absent or bus error)\n");
        close(spi_fd);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("ADIS16266 initialized. Reading gyroscope data every 100 ms...\n");

    while (running) {
        gpiod_line_set_value(cs_line, 0);
        usleep(10);
        float x, y, z;
        if (read_gyro_data(spi_fd, &x, &y, &z) == 0) {
            printf("X: %7.2f deg/s, Y: %7.2f deg/s, Z: %7.2f deg/s\n", x, y, z);
        } else {
            fprintf(stderr, "Error reading gyroscope data\n");
        }
        gpiod_line_set_value(cs_line, 1);
        usleep(100000);
    }

    printf("\nExiting cleanly...\n");
    close(spi_fd);
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

