#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C 7-bit address (SA0 tied to GND) */
#define LSM6DSR_ADDR 0x6B

/* LSM6DSR register addresses */
#define WHO_AM_I     0x0F
#define CTRL1_XL     0x10
#define CTRL2_G      0x11
#define OUTX_L_G     0x22

/* Expected device ID */
#define WHO_AM_I_VAL 0x6B

/* Sensitivities (from datasheet) */
#define GYRO_SENSITIVITY  0.00875f   /* mdps/LSB  -> 0.00875 dps/LSB */
#define ACCEL_SENSITIVITY 0.000061f  /* mg/LSB     -> 0.000061 g/LSB */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: pigpio rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X = 0x%02X: pigpio rc=%d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

static int read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error reading burst from 0x%02X: expected %u bytes, got %d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

static int init_lsm6dsr(int handle)
{
    uint8_t who_am_i = 0;

    if (read_register(handle, WHO_AM_I, &who_am_i) != 0)
        return -1;

    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    /* Accel: 104 Hz, +/-2g, anti-aliasing 50 Hz */
    if (write_register(handle, CTRL1_XL, 0x42) != 0)
        return -1;

    /* Gyro: 104 Hz, +/-250 dps */
    if (write_register(handle, CTRL2_G, 0x42) != 0)
        return -1;

    return 0;
}

static int read_sensor_data(int handle, float *gx, float *gy, float *gz,
                            float *ax, float *ay, float *az)
{
    uint8_t buf[12];

    if (read_burst(handle, OUTX_L_G, buf, sizeof(buf)) != 0)
        return -1;

    /* Gyro: X/Y/Z in buf[0..2], buf[3..5] */
    int16_t raw_gx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_gy = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_gz = (int16_t)((buf[5] << 8) | buf[4]);

    /* Accel: X/Y/Z in buf[6..8], buf[9..11] */
    int16_t raw_ax = (int16_t)((buf[8] << 8) | buf[6]);
    int16_t raw_ay = (int16_t)((buf[10] << 8) | buf[7]);
    int16_t raw_az = (int16_t)((buf[11] << 8) | buf[9]);

    *gx = (float)raw_gx * GYRO_SENSITIVITY;
    *gy = (float)raw_gy * GYRO_SENSITIVITY;
    *gz = (float)raw_gz * GYRO_SENSITIVITY;
    *ax = (float)raw_ax * ACCEL_SENSITIVITY;
    *ay = (float)raw_ay * ACCEL_SENSITIVITY;
    *az = (float)raw_az * ACCEL_SENSITIVITY;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: pigpio rc=%d\n",
                LSM6DSR_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(g_i2c_handle) != 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("LSM6DSR initialised. Reading at 104 Hz every 100 ms. Ctrl+C to stop.\n");

    while (g_running) {
        float gx, gy, gz, ax, ay, az;

        if (read_sensor_data(g_i2c_handle, &gx, &gy, &gz, &ax, &ay, &az) == 0) {
            printf("Gx: %7.2f  Gy: %7.2f  Gz: %7.2f  dps  |  "
                   "Ax: %7.2f  Ay: %7.2f  Az: %7.2f  mg\n",
                   gx, gy, gz, ax, ay, az);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        /* 100 ms delay; pigpio timeDelay is interrupt-safe */
        timeDelay(100);
    }

    printf("\nShutting down cleanly...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

