#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* FXOS8700 I2C address (SDO tied to GND) */
#define FXOS8700_ADDR 0x1D

/* FXOS8700 register addresses */
#define FXOS8700_WHO_AM_I   0x0D
#define FXOS8700_WHO_AM_I_VAL 0xC7
#define FXOS8700_CTRL_REG1  0x2A
#define FXOS8700_CTRL_REG2  0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB  0x01

/* Global handle for signal handler */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a single byte register; returns 0 on success, -1 on error */
static int read_reg8(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error: reg 0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/* Write a single byte register; returns 0 on success, -1 on error */
static int write_reg8(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: reg 0x%02X, val 0x%02X, rc=%d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

/* Read a 16-bit little-endian register; returns 0 on success, -1 on error */
static int read_reg16(int handle, uint8_t reg, int16_t *val) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read-word error: reg 0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *val = (int16_t)rc;
    return 0;
}

/* Initialize FXOS8700: verify identity, then configure hybrid mode */
static int init_fxos8700(int handle) {
    uint8_t who_am_i = 0;

    if (read_reg8(handle, FXOS8700_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error\n");
        return -1;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (write_reg8(handle, FXOS8700_CTRL_REG1, 0x00) != 0) return -1;

    /* M_CTRL_REG1: hybrid mode, 100 Hz ODR, 16-bit magnetometer */
    if (write_reg8(handle, FXOS8700_M_CTRL_REG1, 0x1F) != 0) return -1;

    /* M_CTRL_REG2: 100 Hz ODR, 16-bit magnetometer */
    if (write_reg8(handle, FXOS8700_M_CTRL_REG2, 0x20) != 0) return -1;

    /* CTRL_REG1: active mode, 100 Hz ODR, 14-bit accel, hybrid mode */
    if (write_reg8(handle, FXOS8700_CTRL_REG1, 0x01) != 0) return -1;

    return 0;
}

/* Read 12 bytes of combined data: 6 accel (14-bit) + 6 mag (16-bit) */
static int read_sensor_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *mx, int16_t *my, int16_t *mz) {
    char buf[12];

    int rc = i2cReadI2CBlockData(handle, FXOS8700_OUT_X_MSB, buf, 12);
    if (rc != 12) {
        fprintf(stderr, "I2C block read failed: rc=%d\n", rc);
        return -1;
    }

    /* Accelerometer: 14-bit left-aligned, 2 bytes each */
    *ax = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1]) >> 2;
    *ay = (int16_t)(((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3]) >> 2;
    *az = (int16_t)(((uint16_t)(uint8_t)buf[4] << 8) | (uint8_t)buf[5]) >> 2;

    /* Magnetometer: 16-bit, little-endian */
    *mx = (int16_t)(((uint16_t)(uint8_t)buf[6] << 8) | (uint8_t)buf[7]);
    *my = (int16_t)(((uint16_t)(uint8_t)buf[8] << 8) | (uint8_t)buf[9]);
    *mz = (int16_t)(((uint16_t)(uint8_t)buf[10] << 8) | (uint8_t)buf[11]);

    return 0;
}

int main(void) {
    int16_t ax, ay, az, mx, my, mz;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at FXOS8700_ADDR */
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_fxos8700(i2c_handle) != 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("FXOS8700 initialized. Reading data every 100 ms. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Mag: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Read failed; retrying in 100 ms...\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    /* Cleanup */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

