#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_GPIO 17
#define SAMPLE_INTERVAL_US 1000   /* 1 ms */
#define WINDOW_DURATION_US  5000000 /* 5 seconds */
#define PAUSE_BETWEEN_WINDOWS 1000000 /* 1 second */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return -1;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    /* KY-038 OUT is active-high; no pull-up needed. */
    if (gpioSetPullUpDown(SOUND_SENSOR_GPIO, PI_PUD_OFF) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up/down on GPIO%d.\n", SOUND_SENSOR_GPIO);
    }

    return 0;
}

static int read_sensor(void)
{
    return gpioRead(SOUND_SENSOR_GPIO);
}

static void print_timestamped_alert(int threshold, int count)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
    } else {
        strncpy(timestamp, "UNKNOWN", sizeof(timestamp) - 1);
        timestamp[sizeof(timestamp) - 1] = '\0';
    }

    printf("%s - ALERT: %d high readings in 5 seconds (threshold: %d)\n",
           timestamp, count, threshold);
    fflush(stdout);
}

static void print_status(int high_count, int threshold)
{
    printf("Status: %d high readings in 5 seconds (threshold: %d)\n",
           high_count, threshold);
    fflush(stdout);
}

int main(int argc, char *argv[])
{
    int threshold = 0;
    int high_count;
    int ret = EXIT_SUCCESS;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        fprintf(stderr, "  threshold: minimum high-readings per 5-second window\n");
        return EXIT_FAILURE;
    }

    threshold = atoi(argv[1]);
    if (threshold <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer.\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-038 sound sensor on GPIO%d. Threshold: %d high readings in 5 seconds.\n",
           SOUND_SENSOR_GPIO, threshold);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        high_count = 0;
        uint32_t start_tick = gpioTick();

        while (g_running && (gpioTick() - start_tick) < WINDOW_DURATION_US) {
            int val = read_sensor();
            if (val < 0) {
                fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", SOUND_SENSOR_GPIO);
                ret = EXIT_FAILURE;
                goto cleanup;
            }
            if (val == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        if (!g_running) {
            break;
        }

        if (high_count > threshold) {
            print_timestamped_alert(threshold, high_count);
        } else {
            print_status(high_count, threshold);
        }

        /* Pause between monitoring windows to avoid hogging CPU. */
        gpioDelay(PAUSE_BETWEEN_WINDOWS);
    }

cleanup:
    gpioTerminate();
    return ret;
}

