#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_DOOR_A 17
#define GPIO_DOOR_B 27
#define CODE_LENGTH 6
#define UNLOCK_DURATION_SEC 5
#define LOG_FILE "access_log.txt"
#define CHIP_NAME "gpiochip4"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int generate_random_code(char *code, size_t len) {
    if (len < CODE_LENGTH + 1) return -1;
    int num = rand() % 900000 + 100000;
    snprintf(code, len, "%d", num);
    return 0;
}

static int unlock_door(struct gpiod_line *line, int gpio_pin) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    printf("Door unlocked on GPIO %d\n", gpio_pin);
    return 0;
}

static int lock_door(struct gpiod_line *line, int gpio_pin) {
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    printf("Door locked on GPIO %d\n", gpio_pin);
    return 0;
}

static int log_access(const char *code) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Failed to format timestamp\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s,%s\n", timestamp, code) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    srand((unsigned int)time(NULL));

    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return 1;
    }

    struct gpiod_line *line_a = gpiod_chip_get_line(chip, GPIO_DOOR_A);
    if (!line_a) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", GPIO_DOOR_A, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    struct gpiod_line *line_b = gpiod_chip_get_line(chip, GPIO_DOOR_B);
    if (!line_b) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", GPIO_DOOR_B, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", GPIO_DOOR_A, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", GPIO_DOOR_B, strerror(errno));
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        return 1;
    }

    char code[CODE_LENGTH + 1];
    if (generate_random_code(code, sizeof(code)) < 0) {
        fprintf(stderr, "Failed to generate random code\n");
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("Security code: %s\n", code);

    while (program_running) {
        printf("Enter security code: ");
        fflush(stdout);

        char input[CODE_LENGTH + 1];
        if (fgets(input, sizeof(input), stdin) == NULL) {
            if (feof(stdin)) {
                printf("\nEOF received, exiting.\n");
                break;
            }
            fprintf(stderr, "Failed to read input: %s\n", strerror(errno));
            continue;
        }

        char *endptr;
        long val = strtol(input, &endptr, 10);
        if (*endptr != '\n' && *endptr != '\0') {
            fprintf(stderr, "Invalid input. Please enter a 6-digit number.\n");
            continue;
        }
        if (val < 100000 || val > 999999) {
            fprintf(stderr, "Invalid input. Please enter a 6-digit number.\n");
            continue;
        }

        if (val == (long)atoi(code)) {
            printf("Access granted!\n");
            if (unlock_door(line_a, GPIO_DOOR_A) == 0) {
                sleep(UNLOCK_DURATION_SEC);
                lock_door(line_a, GPIO_DOOR_A);
            }
            if (log_access(code) == 0) {
                printf("Access logged.\n");
            }
            if (generate_random_code(code, sizeof(code)) < 0) {
                fprintf(stderr, "Failed to generate new code\n");
            }
        } else {
            printf("Access denied.\n");
        }
    }

    lock_door(line_a, GPIO_DOOR_A);
    lock_door(line_b, GPIO_DOOR_B);
    gpiod_line_release(line_a);
    gpiod_line_release(line_b);
    gpiod_chip_close(chip);
    printf("Program terminated.\n");
    return 0;
}

