static int read_touch_data(int *touch_data) {
    char buf[12];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 12) != 12) return -1;
    for (int i = 0; i < 12; i++) touch_data[i] = (buf[i] & 0x0F);
    return 0;
}

static int calculate_frequency(int *touch_data) {
    int max_value = 0;
    for (int i = 0; i < 12; i++) {
        if (touch_data[i] > max_value) max_value = touch_data[i];
    }
    if (max_value == 0) return 0;
    float freq = 220.0 + (float)(max_value - 1) * 660.0 / 4095.0;
    return (int)freq;
}

static void play_tone(int frequency) {
    if (frequency > 0) {
        gpioSetPWMfrequency(PWM_GPIO, frequency);
        gpioPWM(PWM_GPIO, 128);
    } else {
        gpioPWM(PWM_GPIO, 0);
    }
}

static void log_frequency(int frequency) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Frequency: %d Hz\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, frequency);
        fclose(fp);
    }
}

static void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received > 0) {
        buffer[bytes_received] = '\0';
        if (strstr(buffer, MOTION_DETECTED_PREFIX) != NULL &&
            strstr(buffer, SECRET_KEY) != NULL) {
            int *touch_data = malloc(12 * sizeof(int));
            if (!touch_data) { send(client_socket, "Error: Memory allocation failed", 28, 0); return; }
            int frequency;
            time_t start_time = time(NULL);
            while (time(NULL) - start_time < PLAYBACK_DURATION_S && !terminate) {
                if (read_touch_data(touch_data) == 0) {
                    frequency = calculate_frequency(touch_data);
                    play_tone(frequency);
                    log_frequency(frequency);
                } else {
                    fprintf(stderr, "Error reading touch data\n");
                }
                gpioDelay(SAMPLE_INTERVAL_US);
            }
            free(touch_data);
            send(client_socket, "Tone playback complete", 22, 0);
        } else {
            send(client_socket, "Invalid message format", 22, 0);
        }
    } else if (bytes_received == 0) {
        printf("Client disconnected\n");
    } else {
        perror("recv failed");
    }
    close(client_socket);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (mpr121_init() != 0) {
        fprintf(stderr, "Error initializing MPR121\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(PWM_GPIO, 1000);
    gpioPWM(PWM_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("Theremin server listening on port %d\n", PORT);
    while (!terminate) {
        int client_socket = accept(server_fd, NULL, NULL);
        if (client_socket < 0) {
            if (terminate) break;
            perror("accept failed");
            continue;
        }
        handle_client(client_socket);
    }
    gpioPWM(PWM_GPIO, 0);
    if (server_fd >= 0) close(server_fd);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Theremin server terminated\n");
    return 0;
}

