        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, val, rc);
    }
    return rc;
}

static int read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, expected %u, got %d)\n", reg, len, rc);
        return -1;
    }
    return 0;
}

static int init_hmc5883l(void) {
    if (write_reg(CONFIG_A, 0x70) < 0) return -1;
    if (write_reg(CONFIG_B, 0x20) < 0) return -1;
    if (write_reg(MODE, 0x00) < 0) return -1;
    return 0;
}

static int read_raw(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (read_block(DATA_X_MSB, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void correct(int16_t x, int16_t y, int16_t z,
                    double *ox, double *oy, double *oz) {
    *ox = (double)x - *ox;
    *oy = (double)y - *oy;
    *oz = (double)z - *oz;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", HMC5883L_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    double ox = 0, oy = 0, oz = 0;
    int count = 0;

    while (running) {
        int16_t x, y, z;
        if (read_raw(&x, &y, &z) < 0) {
            fprintf(stderr, "Read error, continuing\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        if (count < SAMPLE_WINDOW) {
            ox += (double)x;
            oy += (double)y;
            oz += (double)z;
            count++;
        } else {
            ox = (ox * (SAMPLE_WINDOW - 1) + (double)x) / SAMPLE_WINDOW;
            oy = (oy * (SAMPLE_WINDOW - 1) + (double)y) / SAMPLE_WINDOW;
            oz = (oz * (SAMPLE_WINDOW - 1) + (double)z) / SAMPLE_WINDOW;
        }

        double cx, cy, cz;
        correct(x, y, z, &cx, &cy, &cz);

        printf("X: %+.2f, Y: %+.2f, Z: %+.2f\n", cx, cy, cz);
        fflush(stdout);

        gpioDelay(SAMPLE_DELAY_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

