/*
 * LSM303D Accelerometer Interrupt Monitor for Raspberry Pi Zero W
 *
 * Reads tri-axial acceleration data from an LSM303D accelerometer/magnetometer
 * via I2C (address 0x1D, SA0 tied high) on /dev/i2c-1 using the Linux i2c-dev
 * kernel API.  Monitors the INT1 GPIO interrupt line (BCM pin 23, physical
 * pin 16) for rising-edge threshold events and dumps the last 10 samples
 * to stdout on each trigger.
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 *
 * Wiring:
 *   LSM303D SDA  -> Pi GPIO2  (physical pin 3)
 *   LSM303D SCL  -> Pi GPIO3  (physical pin 5)
 *   LSM303D VDD  -> 3.3 V
 *   LSM303D GND  -> GND
 *   LSM303D SA0  -> VDD  (I2C address 0x1D)
 *   LSM303D INT1 -> Pi GPIO23 (physical pin 16)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- LSM303D constants (datasheet) ------------------------------------- */
#define LSM303D_ADDR        0x1D          /* SA0 tied high */
#define LSM303D_WHO_AM_I    0x0F
#define LSM303D_WHO_AM_I_VAL 0x49
#define LSM303D_CTRL_REG1   0x20
#define LSM303D_CTRL_REG4   0x23
#define LSM303D_INT1_CFG    0x30
#define LSM303D_OUT_X_L_A   0x28          /* auto-increment MSB = 0x80 */

/* ---- Threshold interrupt parameters ------------------------------------ */
#define INT1_THRESHOLD_MG   2000.0f
#define INT1_DURATION_US    0
#define INT1_THRESHOLD_REG  (uint8_t)(INT1_THRESHOLD_MG / 16.0f)  /* 125 */

/* ---- GPIO / interrupt --------------------------------------------------- */
#define GPIO_CHIP_NAME      "gpiochip0"
#define INT1_GPIO_LINE      23             /* BCM 23, physical pin 16 */

/* ---- Sampling ---------------------------------------------------------- */
#define BUFFER_SIZE         64
#define SAMPLE_PERIOD_US    10000          /* 10 ms -> ~100 Hz poll rate */

/* ---- Globals ------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_int1_line = NULL;

/* ---- Data structures --------------------------------------------------- */
typedef struct {
    int16_t x, y, z;
} accel_sample_t;

typedef struct {
    accel_sample_t samples[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Prototypes -------------------------------------------------------- */
static int  i2c_read_reg8(int fd, uint8_t reg, uint8_t *val);
static int  i2c_write_reg8(int fd, uint8_t reg, uint8_t val);
static int  i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len);
static int  init_lsm303d(void);
static int  read_accel(circular_buffer_t *buf, accel_sample_t *out);
static void dump_buffer(const circular_buffer_t *buf);
static void int1_isr_cb(struct gpiod_line *line, void *userdata);
static void cleanup(void);
static void sigint_handler(int sig);

/* ---- I2C helpers ------------------------------------------------------- */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    int rc = i2c_smbus_read_byte_data(fd, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    int rc = i2c_smbus_write_byte_data(fd, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write reg 0x%02X = 0x%02X failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len)
{
    /* Set MSB of register address to enable auto-increment */
    int rc = i2c_smbus_read_i2c_block_data(fd, reg | 0x80, len, buf);
    if (rc < 0) {
        fprintf(stderr, "I2C block read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (rc != len) {
        fprintf(stderr, "I2C block read reg 0x%02X: got %d of %d bytes\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

/* ---- LSM303D initialization --------------------------------------------- */
static int init_lsm303d(void)
{
    uint8_t who_am_i = 0;

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                LSM303D_ADDR, strerror(errno));
        return -1;
    }

    /* Verify device identity */
    if (i2c_read_reg8(g_i2c_fd, LSM303D_WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LSM303D_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: 50 Hz ODR, all axes enabled, normal mode */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1, 0x57) < 0)
        return -1;

    /* CTRL_REG4: full-scale +-2g, little-endian, high-resolution */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG4, 0x00) < 0)
        return -1;

    /* INT1_CFG: rising edge, any-axis-high, no latch, no active-high */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_INT1_CFG,
                       0x2A | (INT1_DURATION_US & 0x0F)) < 0)
        return -1;

    /* INT1_THS: threshold 125 (2000 mg / 16) */
    if (i2c_write_reg8(g_i2c_fd, 0x31, INT1_THRESHOLD_REG) < 0)
        return -1;

    return 0;
}

/* ---- Read acceleration with error recovery ------------------------------ */
static int read_accel(circular_buffer_t *buf, accel_sample_t *out)
{
    uint8_t raw[6];

    if (i2c_read_block(g_i2c_fd, LSM303D_OUT_X_L_A, raw, 6) < 0)
        return -1;

    out->x = (int16_t)((raw[1] << 8) | raw[0]);
    out->y = (int16_t)((raw[3] << 8) | raw[2]);
    out->z = (int16_t)((raw[5] << 8) | raw[4]);
    return 0;
}

/* ---- Circular buffer --------------------------------------------------- */
static void circular_buffer_init(circular_buffer_t *cb)
{
    cb->head = 0;
    cb->count = 0;
}

static void circular_buffer_push(circular_buffer_t *cb, const accel_sample_t *s)
{
    cb->samples[cb->head] = *s;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static void dump_buffer(const circular_buffer_t *cb)
{
    printf("--- Last %d buffered samples ---\n", cb->count);
    for (int i = 0; i < cb->count; i++) {
        int idx = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("  [%2d] X=%6d  Y=%6d  Z=%6d\n",
               i, cb->samples[idx].x, cb->samples[idx].y, cb->samples[idx].z);
    }
    fflush(stdout);
}

/* ---- GPIO / interrupt --------------------------------------------------- */
static void int1_isr_cb(struct gpiod_line *line, void *userdata)
{
    (void)line;
    (void)userdata;
    static int in_isr = 0;
    if (in_isr)
        return;
    in_isr = 1;

    circular_buffer_t *cb = (circular_buffer_t *)userdata;
    dump_buffer(cb);
    in_isr = 0;
}

static void cleanup(void)
{
    if (g_int1_line) {
        gpiod_line_release(g_int1_line);
        g_int1_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Disable accelerometer before closing */
        (void)i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Main --------------------------------------------------------------- */
int main(void)
{
    circular_buffer_t buffer;
    circular_buffer_init(&buffer);

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize LSM303D */
    if (init_lsm303d() < 0) {
        fprintf(stderr, "LSM303D initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request INT1 line */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_int1_line = gpiod_chip_get_line(g_chip, INT1_GPIO_LINE);
    if (!g_int1_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                INT1_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(g_int1_line, "lsm303d_int1") < 0) {
        fprintf(stderr, "Cannot request rising-edge events on GPIO %d: %s\n",
                INT1_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register callback */
    if (gpiod_line_set_consumer(g_int1_line, "lsm303d_int1_cb") < 0) {
        fprintf(stderr, "Cannot set consumer label: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Enable the accelerometer (50 Hz, all axes) */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Failed to enable accelerometer.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM303D ready.  INT1 rising-edge threshold interrupt monitoring.\n");
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    /* Main loop */
    while (g_running) {
        accel_sample_t sample;
        if (read_accel(&buffer, &sample) == 0) {
            circular_buffer_push(&buffer, &sample);
        } else {
            /* I2C read failed; warn and keep going */
            fprintf(stderr, "Warning: I2C read failed; skipping sample.\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

