    in_isr = 1;

    circular_buffer_t *cb = (circular_buffer_t *)userdata;
    dump_buffer(cb);
    in_isr = 0;
}

static void cleanup(void)
{
    if (g_int1_line) {
        gpiod_line_release(g_int1_line);
        g_int1_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Disable accelerometer before closing */
        (void)i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Main --------------------------------------------------------------- */
int main(void)
{
    circular_buffer_t buffer;
    circular_buffer_init(&buffer);

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize LSM303D */
    if (init_lsm303d() < 0) {
        fprintf(stderr, "LSM303D initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request INT1 line */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_int1_line = gpiod_chip_get_line(g_chip, INT1_GPIO_LINE);
    if (!g_int1_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                INT1_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(g_int1_line, "lsm303d_int1") < 0) {
        fprintf(stderr, "Cannot request rising-edge events on GPIO %d: %s\n",
                INT1_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register callback */
    if (gpiod_line_set_consumer(g_int1_line, "lsm303d_int1_cb") < 0) {
        fprintf(stderr, "Cannot set consumer label: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Enable the accelerometer (50 Hz, all axes) */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Failed to enable accelerometer.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM303D ready.  INT1 rising-edge threshold interrupt monitoring.\n");
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    /* Main loop */
    while (g_running) {
        accel_sample_t sample;
        if (read_accel(&buffer, &sample) == 0) {
            circular_buffer_push(&buffer, &sample);
        } else {
            /* I2C read failed; warn and keep going */
            fprintf(stderr, "Warning: I2C read failed; skipping sample.\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

