#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DELAY_MS      500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec req;
    req.tv_sec  = ms / 1000;
    req.tv_nsec = (long)(ms % 1000) * 1000000L;

    while (nanosleep(&req, &req) == -1) {
        if (errno != EINTR) {
            perror("nanosleep");
            break;
        }
        /* Retry with remaining time after interruption */
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    line1 = gpiod_chip_get_line(chip, SOLENOID_1_PIN);
    if (line1 == NULL) {
        perror("gpiod_chip_get_line(solenoid 1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SOLENOID_2_PIN);
    if (line2 == NULL) {
        perror("gpiod_chip_get_line(solenoid 2)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, "solenoid-1", 0) < 0) {
        perror("gpiod_line_request_output(solenoid 1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "solenoid-2", 0) < 0) {
        perror("gpiod_line_request_output(solenoid 2)");
        goto cleanup;
    }

    /* Ensure both solenoids start de-energized */
    if (gpiod_line_set_value(line1, 0) < 0) {
        perror("gpiod_line_set_value(solenoid 1, 0)");
        goto cleanup;
    }
    if (gpiod_line_set_value(line2, 0) < 0) {
        perror("gpiod_line_set_value(solenoid 2, 0)");
        goto cleanup;
    }

    printf("Solenoid actuator started. Press Ctrl+C to exit.\n");

    while (g_running) {
        /* Energize solenoid 1 */
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value(solenoid 1, 1)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value(solenoid 2, 0)");
            goto cleanup;
        }
        printf("Solenoid 1 ON\n");
        sleep_ms(DELAY_MS);

        if (!g_running)
            break;

        /* De-energize solenoid 1, energize solenoid 2 */
        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value(solenoid 1, 0)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value(solenoid 2, 1)");
            goto cleanup;
        }
        printf("Solenoid 1 OFF, Solenoid 2 ON\n");
        sleep_ms(DELAY_MS);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* De-energize both solenoids before releasing */
    if (line1 != NULL)
        gpiod_line_set_value(line1, 0);
    if (line2 != NULL)
        gpiod_line_set_value(line2, 0);

    if (line1 != NULL)
        gpiod_line_release(line1);
    if (line2 != NULL)
        gpiod_line_release(line2);
    if (chip != NULL)
        gpiod_chip_close(chip);

    printf("Solenoid actuator stopped.\n");
    return ret;
}

