#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define UART1_PORT "/dev/serial0"
#define UART2_PORT "/dev/serial1"
#define EXPECTED_CODE "123456"
#define CODE_LENGTH 6
#define BAUD_RATE 9600
#define POLL_DELAY_US 100000  /* 100 ms */
#define READ_TIMEOUT_S 5

static volatile sig_atomic_t g_running = 1;
static int g_uart1_fd = -1;
static int g_uart2_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return -1;
    }
    if (gpioSetMode(LOCK1_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LOCK1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LOCK2_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LOCK2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LOCK1_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to write GPIO%d LOW\n", LOCK1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to write GPIO%d LOW\n", LOCK2_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_uart(const char *port, int *fd_out) {
    int fd = serOpen(port, BAUD_RATE, 0);
    if (fd < 0) {
        fprintf(stderr, "Error: failed to open %s: %s\n", port, strerror(errno));
        return -1;
    }
    *fd_out = fd;
    return 0;
}

static int read_code(int fd, char *buffer, size_t buffer_size, size_t *read_count) {
    char ch;
    size_t i = 0;
    time_t start = time(NULL);

    while (i < buffer_size - 1) {
        if (g_running == 0) return -1;
        if (serDataAvailable(fd) > 0) {
            if (serRead(fd, &ch, 1) != 1) {
                fprintf(stderr, "Error: serial read failed on fd %d\n", fd);
                return -1;
            }
            if (ch >= '0' && ch <= '9') {
                buffer[i++] = ch;
            } else {
                i = 0;
            }
        } else {
            if (time(NULL) - start >= READ_TIMEOUT_S) {
                break;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }
    buffer[i] = '\0';
    *read_count = i;
    return 0;
}

static int unlock_doors(void) {
    if (gpioWrite(LOCK1_GPIO, 1) < 0) {
        fprintf(stderr, "Error: failed to write GPIO%d HIGH\n", LOCK1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 1) < 0) {
        fprintf(stderr, "Error: failed to write GPIO%d HIGH\n", LOCK2_GPIO);
        gpioWrite(LOCK1_GPIO, 0);
        return -1;
    }
    printf("Doors unlocked\n");
    return 0;
}

static int lock_doors(void) {
    if (gpioWrite(LOCK1_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to write GPIO%d LOW\n", LOCK1_GPIO);
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to write GPIO%d LOW\n", LOCK2_GPIO);
        gpioWrite(LOCK1_GPIO, 1);
        return -1;
    }
    printf("Doors locked\n");
    return 0;
}

static int compare_codes(const char *code1, const char *code2) {
    if (code1 == NULL || code2 == NULL) return 0;
    return (strncmp(code1, code2, CODE_LENGTH) == 0);
}

static void cleanup(void) {
    if (g_uart1_fd >= 0) {
        serClose(g_uart1_fd);
        g_uart1_fd = -1;
    }
    if (g_uart2_fd >= 0) {
        serClose(g_uart2_fd);
        g_uart2_fd = -1;
    }
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    char code1[CODE_LENGTH + 1];
    char code2[CODE_LENGTH + 1];
    size_t code1_len = 0, code2_len = 0;
    int ret = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() < 0) return 1;

    if (init_uart(UART1_PORT, &g_uart1_fd) < 0) {
        cleanup();
        return 1;
    }
    if (init_uart(UART2_PORT, &g_uart2_fd) < 0) {
        cleanup();
        return 1;
    }

    printf("Dual-factor authentication system started.\n");
    printf("Expected code: %s\n", EXPECTED_CODE);
    printf("Listening on %s and %s...\n", UART1_PORT, UART2_PORT);

    while (g_running) {
        if (read_code(g_uart1_fd, code1, sizeof(code1), &code1_len) == 0) {
            if (code1_len > 0) {
                printf("Code from UART1: %s\n", code1);
            }
        }
        if (read_code(g_uart2_fd, code2, sizeof(code2), &code2_len) == 0) {
            if (code2_len > 0) {
                printf("Code from UART2: %s\n", code2);
            }
        }

        if (code1_len > 0 && code2_len > 0) {
            if (compare_codes(code1, code2) && compare_codes(code1, EXPECTED_CODE)) {
                if (unlock_doors() == 0) {
                    sleep(2);
                    if (lock_doors() != 0) {
                        fprintf(stderr, "Warning: failed to re-lock doors\n");
                    }
                }
            } else {
                fprintf(stderr, "Mismatch: code1=%s, code2=%s, expected=%s\n",
                        code1, code2, EXPECTED_CODE);
            }
            code1_len = 0;
            code2_len = 0;
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return ret;
}

