    if (init_gpio() < 0) return 1;

    if (init_uart(UART1_PORT, &g_uart1_fd) < 0) {
        cleanup();
        return 1;
    }
    if (init_uart(UART2_PORT, &g_uart2_fd) < 0) {
        cleanup();
        return 1;
    }

    printf("Dual-factor authentication system started.\n");
    printf("Expected code: %s\n", EXPECTED_CODE);
    printf("Listening on %s and %s...\n", UART1_PORT, UART2_PORT);

    while (g_running) {
        if (read_code(g_uart1_fd, code1, sizeof(code1), &code1_len) == 0) {
            if (code1_len > 0) {
                printf("Code from UART1: %s\n", code1);
            }
        }
        if (read_code(g_uart2_fd, code2, sizeof(code2), &code2_len) == 0) {
            if (code2_len > 0) {
                printf("Code from UART2: %s\n", code2);
            }
        }

        if (code1_len > 0 && code2_len > 0) {
            if (compare_codes(code1, code2) && compare_codes(code1, EXPECTED_CODE)) {
                if (unlock_doors() == 0) {
                    sleep(2);
                    if (lock_doors() != 0) {
                        fprintf(stderr, "Warning: failed to re-lock doors\n");
                    }
                }
            } else {
                fprintf(stderr, "Mismatch: code1=%s, code2=%s, expected=%s\n",
                        code1, code2, EXPECTED_CODE);
            }
            code1_len = 0;
            code2_len = 0;
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return ret;
}

