#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN      4
#define RELAY_PIN    17
#define CHIP_NAME    "gpiochip0"
#define RELAY_ON_MS  1000
#define POLL_MS      50
#define FAILSAFE_SEC 10

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static void log_msg(int priority, const char *msg) {
    syslog(priority, "%s", msg);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(%s): %s", CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "gpiod_chip_get_line(%d): %s", PIR_PIN, strerror(errno));
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "gpiod_chip_get_line(%d): %s", RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(pir_line, "door_strike-pir") < 0) {
        syslog(LOG_ERR, "gpiod_line_request_input(PIR): %s", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, "door_strike-relay", 0) < 0) {
        syslog(LOG_ERR, "gpiod_line_request_output(RELAY): %s", strerror(errno));
        goto cleanup;
    }

    syslog(LOG_INFO, "Door strike system started (PIR=GPIO%d, Relay=GPIO%d)", PIR_PIN, RELAY_PIN);

    time_t last_motion = 0;
    int relay_state = 0;

    while (running) {
        int pir_val = gpiod_line_get_value(pir_line);
        if (pir_val < 0) {
            syslog(LOG_ERR, "gpiod_line_get_value(PIR): %s", strerror(errno));
            break;
        }

        if (pir_val == 1) {
            if (relay_state == 0) {
                if (gpiod_line_set_value(relay_line, 1) < 0) {
                    syslog(LOG_ERR, "gpiod_line_set_value(RELAY ON): %s", strerror(errno));
                    break;
                }
                relay_state = 1;
                log_msg(LOG_INFO, "Motion detected, relay energized");
            }

            if (last_motion == 0) {
                last_motion = time(NULL);
            } else {
                time_t now = time(NULL);
                if (difftime(now, last_motion) >= FAILSAFE_SEC) {
                    syslog(LOG_WARNING, "PIR active for >%d s - potential malfunction", FAILSAFE_SEC);
                    last_motion = now;
                }
            }
        } else {
            if (relay_state == 1) {
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    syslog(LOG_ERR, "gpiod_line_set_value(RELAY OFF): %s", strerror(errno));
                    break;
                }
                relay_state = 0;
                log_msg(LOG_INFO, "Motion cleared, relay de-energized");
            }
            last_motion = 0;
        }

        if (relay_state == 1) {
            struct timespec ts = { RELAY_ON_MS / 1000, (RELAY_ON_MS % 1000) * 1000000L };
            nanosleep(&ts, NULL);
        } else {
            struct timespec ts = { POLL_MS / 1000, (POLL_MS % 1000) * 1000000L };
            nanosleep(&ts, NULL);
        }
    }

    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    syslog(LOG_INFO, "Door strike system stopped");
    ret = EXIT_SUCCESS;

cleanup:
    closelog();
    return ret;
}

