#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <string.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define ACTIVATION_TIME 300   /* seconds */
#define PAUSE_TIME      60     /* seconds */
#define TIMER_INTERVAL  60     /* seconds */

static const int relay_pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

static volatile sig_atomic_t running = 1;

/* State machine: 0 = idle, 1 = activating, 2 = deactivating, 3 = pause */
static volatile int state = 0;
static volatile int current_relay = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

static void deactivate_all_relays(void) {
    for (int i = 0; i < 4; i++) {
        if (gpioWrite(relay_pins[i], 1) != 0) {
            log_message(LOG_ERR, "Failed to deactivate relay");
        }
    }
}

static void cleanup(void) {
    deactivate_all_relays();
    gpioTerminate();
    closelog();
}

static void timer_callback(void *userdata) {
    (void)userdata;
    if (state == 1) {
        /* Activate relay */
        if (gpioWrite(relay_pins[current_relay], 0) != 0) {
            log_message(LOG_ERR, "Failed to activate relay");
            state = 0;
            return;
        }
        log_message(LOG_INFO, "Relay activated");
        state = 2;
    } else if (state == 2) {
        /* Deactivate relay */
        if (gpioWrite(relay_pins[current_relay], 1) != 0) {
            log_message(LOG_ERR, "Failed to deactivate relay");
            state = 0;
            return;
        }
        log_message(LOG_INFO, "Relay deactivated");
        state = 0;
        current_relay = (current_relay + 1) % 4;
        if (current_relay == 0) {
            /* Loop back to first relay */
            log_message(LOG_INFO, "Looping to first relay");
        }
    } else if (state == 3) {
        /* Pause */
        log_message(LOG_INFO, "Pause");
        state = 0;
    }
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Set GPIO modes to output and initialize all relays to OFF (HIGH) */
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            log_message(LOG_ERR, "Failed to set GPIO mode");
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) {
            log_message(LOG_ERR, "Failed to initialize relay to OFF");
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_message(LOG_ERR, "Failed to install signal handlers");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Start timer every 60 seconds */
    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback, NULL) != 0) {
        log_message(LOG_ERR, "Failed to set timer function");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Irrigation system started");

    /* Main loop: sleep until signal received */
    while (running) {
        sleep(1);
    }

    log_message(LOG_INFO, "Shutting down irrigation system");
    cleanup();
    return EXIT_SUCCESS;
}

