#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define ACCEL_XOUT_H   0x3B
#define PWR_MGMT_1     0x6B
#define ACCEL_CONFIG   0x1C
#define ACCEL_SCALE    16384.0f

#define TIMER_INTERVAL_NS 100000000L  /* 100 Hz */
#define TIMER_PERIOD_NS   10000000L   /* 10 ms  */

#define CIRCULAR_BUFFER_SIZE 100

typedef struct {
    float x, y, z;
} accel_data_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_timer_id = -1;
static accel_data_t g_circular_buffer[CIRCULAR_BUFFER_SIZE];
static int g_buffer_index = 0;
static int g_buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg8(fd, ACCEL_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_accel(int fd, accel_data_t *data) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    data->x = (float)raw_x / ACCEL_SCALE;
    data->y = (float)raw_y / ACCEL_SCALE;
    data->z = (float)raw_z / ACCEL_SCALE;
    return 0;
}

static void timer_handler(int sig, siginfo_t *si, void *uc) {
    (void)sig; (void)si; (void)uc;
    accel_data_t data;
    if (read_accel(g_i2c_fd, &data) < 0) {
        fprintf(stderr, "Failed to read accel data\n");
        return;
    }
    g_circular_buffer[g_buffer_index] = data;
    g_buffer_index = (g_buffer_index + 1) % CIRCULAR_BUFFER_SIZE;
    if (g_buffer_count < CIRCULAR_BUFFER_SIZE) g_buffer_count++;

    FILE *sysfs = fopen("/sys/kernel/mpu6050_accel/latest", "w");
    if (!sysfs) {
        fprintf(stderr, "Failed to open sysfs: %s\n", strerror(errno));
        return;
    }
    fprintf(sysfs, "%.3f,%.3f,%.3f\n", data.x, data.y, data.z);
    fclose(sysfs);
}

static int create_timer(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = timer_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGRTMIN, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return -1;
    }

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_ptr = NULL;
    if (timer_create(CLOCK_MONOTONIC, &sev, &g_timer_id) < 0) {
        fprintf(stderr, "timer_create failed: %s\n", strerror(errno));
        return -1;
    }

    struct itimerspec its;
