#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define RELAY_INTERVALS {2, 3, 5, 7}
#define RELAY_PINS {18, 23, 24, 25}

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_seconds(int seconds) {
    struct timespec ts = { .tv_sec = seconds, .tv_nsec = 0 };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        if (!running) break;
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int prev_state[NUM_RELAYS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = NULL;
        prev_state[i] = 0;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, RELAY_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", RELAY_PINS[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "smart-lighting", 0) < 0) {
            fprintf(stderr, "Failed to request output for GPIO %d\n", RELAY_PINS[i]);
            goto cleanup;
        }
        if (gpiod_line_set_value(lines[i], 0) < 0) {
            fprintf(stderr, "Failed to set initial value for GPIO %d\n", RELAY_PINS[i]);
            goto cleanup;
        }
        prev_state[i] = 0;
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    while (running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (gpiod_line_get_value(lines[i]) < 0) {
                fprintf(stderr, "Failed to read GPIO %d\n", RELAY_PINS[i]);
                goto cleanup;
            }
            if (gpiod_line_get_value(lines[i]) != prev_state[i]) {
                if (gpiod_line_set_value(lines[i], !prev_state[i]) < 0) {
                    fprintf(stderr, "Failed to set GPIO %d\n", RELAY_PINS[i]);
                    goto cleanup;
                }
                prev_state[i] = !prev_state[i];
            }
        }

        sleep_seconds(RELAY_INTERVALS[0]);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

