#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 I2C address (AD0 tied to GND)
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define MPU6050_REG_SMPLRT_DIV   0x19
#define MPU6050_REG_CONFIG       0x1A
#define MPU6050_REG_GYRO_CONFIG  0x1B
#define MPU6050_REG_GYRO_XOUT_H  0x43
#define MPU6050_REG_PWR_MGMT_1   0x6B
#define MPU6050_REG_WHO_AM_I     0x75

// Expected WHO_AM_I value for MPU-6050
#define MPU6050_WHO_AM_I_VAL     0x68

// Sensitivity scale factor for default +/-250 dps range
#define GYRO_SCALE_FACTOR 131.0f

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold (degrees/second)
#define ANGULAR_VELOCITY_THRESHOLD 50.0f

// Global variables
static int i2c_fd = -1;
static volatile sig_atomic_t program_running = 1;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Structure for the circular buffer
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Function prototypes
int i2c_init(const char *device, int address);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int mpu6050_init(int fd);
int read_gyro_data(int fd, gyro_data_t *gyro_data);
float calculate_angular_velocity(gyro_data_t gyro_data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
bool check_threshold(circular_buffer_t *buffer, float angular_velocity);
void signal_handler(int signal);
void cleanup();

// I2C initialization function
int i2c_init(const char *device, int address) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", device, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", address, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to write a single byte to a register
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from a register
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading %d bytes from register 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the MPU-6050
int mpu6050_init(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_bytes(fd, MPU6050_REG_WHO_AM_I, &who_am_i, 1) < 0) {
        return -1;
    }

    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0x%02X\n", who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep bit)
    if (i2c_write_byte(fd, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) {
        return -1;
    }

    // Set sample rate divider to 7 (1 kHz / (1 + 7) = 125 Hz)
    if (i2c_write_byte(fd, MPU6050_REG_SMPLRT_DIV, 0x07) < 0) {
        return -1;
    }

    // Set DLPF configuration to 9 (bandwidth 12.5 Hz, delay 0.98 ms)
    if (i2c_write_byte(fd, MPU6050_REG_CONFIG, 0x09) < 0) {
        return -1;
    }

    // Set gyroscope full-scale range to +/- 250 degrees/second
    if (i2c_write_byte(fd, MPU6050_REG_GYRO_CONFIG, 0x00) < 0) {
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, gyro_data_t *gyro_data) {
    uint8_t buf[6];
    if (i2c_read_bytes(fd, MPU6050_REG_GYRO_XOUT_H, buf, 6) < 0) {
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    gyro_data->x = (float)raw_x / GYRO_SCALE_FACTOR;
    gyro_data->y = (float)raw_y / GYRO_SCALE_FACTOR;
    gyro_data->z = (float)raw_z / GYRO_SCALE_FACTOR;

    return 0;
}

// Function to calculate angular velocity
float calculate_angular_velocity(gyro_data_t gyro_data) {
    return sqrtf(gyro_data.x * gyro_data.x + gyro_data.y * gyro_data.y + gyro_data.z * gyro_data.z);
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
}

// Function to check if the angular velocity exceeds the threshold
bool check_threshold(circular_buffer_t *buffer, float angular_velocity) {
    if (angular_velocity > ANGULAR_VELOCITY_THRESHOLD) {
        return true;
    }
    return false;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup function
void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main() {
    // Register signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Initialize I2C
    i2c_fd = i2c_init("/dev/i2c-1", MPU6050_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize MPU-6050
    if (mpu6050_init(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing MPU-6050\n");
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    circular_buffer_t buffer;
    buffer.head = 0;
    buffer.tail = 0;
    buffer.count = 0;

    // Define a callback function (user-defined)
    void callback_function() {
        printf("Angular velocity threshold exceeded!\n");
    }

    // Main loop
    while (program_running) {
        gyro_data_t gyro_data;
        if (read_gyro_data(i2c_fd, &gyro_data) < 0) {
            fprintf(stderr, "Error reading gyroscope data, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        float angular_velocity = calculate_angular_velocity(gyro_data);
        add_to_buffer(&buffer, gyro_data);

        if (check_threshold(&buffer, angular_velocity)) {
            callback_function();
        }

        usleep(10000); // 10ms delay
    }

    // Cleanup
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

