#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define READ_INTERVAL_SEC 5
#define READ_TIMEOUT_SEC 1
#define MAX_RETRIES 10
#define MH_Z19B_CMD_LEN 9
#define MH_Z19B_RESPONSE_LEN 9

static volatile sig_atomic_t running = 1;
static int uart_handle = -1;
static FILE *log_fp = NULL;
static FILE *err_fp = NULL;

static void log_error(const char *msg) {
    if (!err_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(err_fp, "%04d-%02d-%02d %02d:%02d:%02d ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(err_fp);
}

static void log_data(int co2_ppm, int error) {
    if (!log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(log_fp, "{\"timestamp\":\"%04d-%02d-%02dT%02d:%02d:%02d\","
            "\"co2_ppm\":%d,\"error\":%d}\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, co2_ppm, error);
    fflush(log_fp);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        log_error("Failed to open UART device");
        return -1;
    }
    return 0;
}

static int send_command(const unsigned char *cmd, int len) {
    int written = serWrite(uart_handle, (char *)cmd, len);
    if (written != len) {
        log_error("UART write failed");
        return -1;
    }
    return 0;
}

static int read_response(unsigned char *buf, int len) {
    int total = 0;
    while (total < len) {
        int avail = serDataAvailable(uart_handle);
        if (avail < 0) {
            log_error("serDataAvailable failed");
            return -1;
        }
        if (avail == 0) {
            if (total == 0) return 0; /* timeout, no data yet */
            log_error("UART read timeout");
            return -1;
        }
        int to_read = (avail < (len - total)) ? avail : (len - total);
        int n = serRead(uart_handle, (char *)(buf + total), to_read);
        if (n < 0) {
            log_error("serRead failed");
            return -1;
        }
        total += n;
    }
    return 0;
}

static int validate_checksum(const unsigned char *resp) {
    unsigned int sum = 0;
    for (int i = 1; i <= 7; i++) sum += resp[i];
    unsigned char expected = (unsigned char)((0x100 - sum) + 1);
    if (expected != resp[8]) {
        log_error("Checksum mismatch");
        return -1;
    }
    return 0;
}

static int read_co2_ppm(int *co2_ppm) {
    unsigned char cmd[MH_Z19B_CMD_LEN] = {
        0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79
    };
    unsigned char resp[MH_Z19B_RESPONSE_LEN];

    if (send_command(cmd, MH_Z19B_CMD_LEN) != 0) return -1;
    gpioDelay(100000); /* 100 ms */

    if (read_response(resp, MH_Z19B_RESPONSE_LEN) != 0) return -1;

    if (validate_checksum(resp) != 0) return -1;

    *co2_ppm = (resp[2] << 8) | resp[3];
    return 0;
}

static void cleanup(void) {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
    if (log_fp) { fclose(log_fp); log_fp = NULL; }
    if (err_fp) { fclose(err_fp); err_fp = NULL; }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!err_fp) {
        perror("fopen error log");
        fclose(log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_uart() != 0) {
        log_error("UART init failed, exiting");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CO2 monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        int co2_ppm = 0;
        int error = 0;

        if (read_co2_ppm(&co2_ppm) == 0) {
            error = 0;
        } else {
            error = 1;
            co2_ppm = -1;
        }

        log_data(co2_ppm, error);

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

