        int n = serRead(uart_handle, (char *)(buf + total), to_read);
        if (n < 0) {
            log_error("serRead failed");
            return -1;
        }
        total += n;
    }
    return 0;
}

static int validate_checksum(const unsigned char *resp) {
    unsigned int sum = 0;
    for (int i = 1; i <= 7; i++) sum += resp[i];
    unsigned char expected = (unsigned char)((0x100 - sum) + 1);
    if (expected != resp[8]) {
        log_error("Checksum mismatch");
        return -1;
    }
    return 0;
}

static int read_co2_ppm(int *co2_ppm) {
    unsigned char cmd[MH_Z19B_CMD_LEN] = {
        0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79
    };
    unsigned char resp[MH_Z19B_RESPONSE_LEN];

    if (send_command(cmd, MH_Z19B_CMD_LEN) != 0) return -1;
    gpioDelay(100000); /* 100 ms */

    if (read_response(resp, MH_Z19B_RESPONSE_LEN) != 0) return -1;

    if (validate_checksum(resp) != 0) return -1;

    *co2_ppm = (resp[2] << 8) | resp[3];
    return 0;
}

static void cleanup(void) {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
    if (log_fp) { fclose(log_fp); log_fp = NULL; }
    if (err_fp) { fclose(err_fp); err_fp = NULL; }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!err_fp) {
        perror("fopen error log");
        fclose(log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_uart() != 0) {
        log_error("UART init failed, exiting");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CO2 monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        int co2_ppm = 0;
        int error = 0;

        if (read_co2_ppm(&co2_ppm) == 0) {
            error = 0;
        } else {
            error = 1;
            co2_ppm = -1;
        }

        log_data(co2_ppm, error);

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

