#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define CONFIG_A_REG 0x00
#define CONFIG_B_REG 0x01
#define MODE_REG 0x02
#define DATA_REG 0x03
#define GPIO_PIN 17
#define TARGET_HEADING 90.0
#define HEADING_THRESHOLD 10.0
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer heading_buffer;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cb_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(i2c_handle, buf, 2);
        if (rc == 0) return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d): rc=%d\n", reg, attempt + 1, rc);
        gpioDelay(10000);
    }
    return -1;
}

static int i2c_read_burst(uint8_t reg, uint8_t *buf, int len) {
    char reg_buf[1] = {(char)reg};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(i2c_handle, reg_buf, 1);
        if (rc != 0) {
            fprintf(stderr, "I2C write (reg select) failed (attempt %d): rc=%d\n", attempt + 1, rc);
            gpioDelay(10000);
            continue;
        }
        rc = i2cReadDevice(i2c_handle, (char *)buf, len);
        if (rc == len) return 0;
        fprintf(stderr, "I2C read burst failed (attempt %d): rc=%d\n", attempt + 1, rc);
        gpioDelay(10000);
    }
    return -1;
}

static int init_hmc5883l(void) {
    if (i2c_write_reg(CONFIG_A_REG, 0x70) != 0) return -1;
    if (i2c_write_reg(CONFIG_B_REG, 0x20) != 0) return -1;
    if (i2c_write_reg(MODE_REG, 0x00) != 0) return -1;
    return 0;
}

static int read_magnetometer(float *x, float *y, float *z) {
    uint8_t data[6];
    if (i2c_read_burst(DATA_REG, data, 6) != 0) return -1;
    int16_t raw_x = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_z = (int16_t)((data[2] << 8) | data[3]);
    int16_t raw_y = (int16_t)((data[4] << 8) | data[5]);
    *x = (float)raw_x;
    *y = (float)raw_y;
    *z = (float)raw_z;
    return 0;
}

static float compensate_heading(float x, float y, float x_off, float y_off) {
    float heading = atan2f(y, x) * 180.0f / M_PI;
    if (heading < 0) heading += 360.0f;
    return heading - (heading - y_off) / (x_off - y_off) * (heading - TARGET_HEADING);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", HMC5883L_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_hmc5883l() != 0) {
        fprintf(stderr, "Failed to configure HMC5883L\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GPIO_PIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_PIN, 0);

    cb_init(&heading_buffer);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float x_off = 100.0f;
    float y_off = -50.0f;

    while (!terminate) {
        float x, y, z;
        if (read_magnetometer(&x, &y, &z) != 0) {
            fprintf(stderr, "Magnetometer read failed; retrying next cycle\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float heading = compensate_heading(x, y, x_off, y_off);
        cb_add(&heading_buffer, heading);

        bool deviate = (fabsf(heading - TARGET_HEADING) > HEADING_THRESHOLD);
        gpioWrite(GPIO_PIN, deviate ? 1 : 0);

        printf("Heading: %.2f deg | Deviate: %s\n", heading, deviate ? "YES" : "NO");
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(GPIO_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

