#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define RED_PIN      17
#define GREEN_PIN    27
#define BLUE_PIN     22
#define I2C_BUS      "/dev/i2c-1"
#define BH1750_ADDR  0x23
#define LOG_FILE     "lighting_log.txt"
#define POLL_INTERVAL_S 1

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_init(int fd) {
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        return -1;
    }
    /* Continuous high-resolution mode: power on, then write 0x10 */
    unsigned char cmd = 0x10;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Failed to write BH1750 config: %s\n", strerror(errno));
        return -1;
    }
    /* First conversion takes ~120 ms */
    usleep(150000);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    unsigned char buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        if (n < 0)
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C short read: %zd bytes\n", n);
        return -1;
    }
    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void set_relay(struct gpiod_line *line, int val) {
    if (gpiod_line_set_value(line, val) < 0)
        fprintf(stderr, "Failed to set relay line: %s\n", strerror(errno));
}

static void log_data(FILE *log, float lux, int r, int g, int b) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log, "%s, Lux: %.2f, R: %d, G: %d, B: %d\n", ts, lux, r, g, b);
    fflush(log);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *red   = gpiod_chip_get_line(chip, RED_PIN);
    struct gpiod_line *green = gpiod_chip_get_line(chip, GREEN_PIN);
    struct gpiod_line *blue  = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red || !green || !blue) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(red, "lighting", 0) < 0 ||
        gpiod_line_request_output(green, "lighting", 0) < 0 ||
        gpiod_line_request_output(blue, "lighting", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed.\n");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Smart lighting system started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
            sleep(POLL_INTERVAL_S);
            continue;
        }

        int r = 0, g = 0, b = 0;
        if (lux < 50.0f) {
            r = 1;
        } else if (lux < 150.0f) {
            g = 1;
        } else if (lux < 300.0f) {
            b = 1;
        } else {
            r = 1; g = 1; b = 1;
        }

        set_relay(red,   r);
        set_relay(green, g);
        set_relay(blue,  b);
        log_data(log, lux, r, g, b);

        sleep(POLL_INTERVAL_S);
    }

    /* Cleanup */
    set_relay(red, 0); set_relay(green, 0); set_relay(blue, 0);
    fclose(log);
    close(i2c_fd);
    gpiod_chip_close(chip);
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

