        gpiod_line_request_output(green, "lighting", 0) < 0 ||
        gpiod_line_request_output(blue, "lighting", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed.\n");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Smart lighting system started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
            sleep(POLL_INTERVAL_S);
            continue;
        }

        int r = 0, g = 0, b = 0;
        if (lux < 50.0f) {
            r = 1;
        } else if (lux < 150.0f) {
            g = 1;
        } else if (lux < 300.0f) {
            b = 1;
        } else {
            r = 1; g = 1; b = 1;
        }

        set_relay(red,   r);
        set_relay(green, g);
        set_relay(blue,  b);
        log_data(log, lux, r, g, b);

        sleep(POLL_INTERVAL_S);
    }

    /* Cleanup */
    set_relay(red, 0); set_relay(green, 0); set_relay(blue, 0);
    fclose(log);
    close(i2c_fd);
    gpiod_chip_close(chip);
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

