#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define MIN_DISTANCE 10
#define MAX_DISTANCE 100
#define OBSTACLE_THRESHOLD 50
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_direction(int in1, int in2, int pwm_pin, int distance) {
    int duty = (distance >= MAX_DISTANCE) ? 0 : (distance <= MIN_DISTANCE) ? PWM_RANGE : (MAX_DISTANCE - distance) * PWM_RANGE / (MAX_DISTANCE - MIN_DISTANCE);
    if (distance < OBSTACLE_THRESHOLD) {
        if (gpioWrite(in1, 1) < 0) return -1;
        if (gpioWrite(in2, 0) < 0) return -1;
        if (gpioPWM(pwm_pin, duty) < 0) return -1;
    } else {
        if (gpioWrite(in1, 0) < 0) return -1;
        if (gpioWrite(in2, 0) < 0) return -1;
        if (gpioPWM(pwm_pin, 0) < 0) return -1;
    }
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) < 0) return -1;
    if (gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) < 0) return -1;
    if (gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) < 0) return -1;
    if (gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) < 0) return -1;
    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0) return -1;
    if (gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) return -1;
    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) < 0) return -1;
    if (gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) < 0) return -1;
    if (gpioWrite(MOTOR_A_IN1, 0) < 0) return -1;
    if (gpioWrite(MOTOR_A_IN2, 0) < 0) return -1;
    if (gpioWrite(MOTOR_B_IN3, 0) < 0) return -1;
    if (gpioWrite(MOTOR_B_IN4, 0) < 0) return -1;
    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);
    gpioPWM(MOTOR_A_IN2, 0);
    gpioPWM(MOTOR_B_IN4, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (initialize_gpio() < 0) {
        return 1;
    }

    int distance_a = 40;
    int distance_b = 60;

    while (running) {
        if (set_motor_direction(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_A_IN2, distance_a) < 0) {
            fprintf(stderr, "Error: failed to control Motor A.\n");
            break;
        }
        if (set_motor_direction(MOTOR_B_IN3, MOTOR_B_IN4, MOTOR_B_IN4, distance_b) < 0) {
            fprintf(stderr, "Error: failed to control Motor B.\n");
            break;
        }
        usleep(LOOP_DELAY_US);
    }

    cleanup_gpio();
    return 0;
}

