#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/file.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 20000000
#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int pwm_fd = -1;
static int log_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        fprintf(stderr, "I2C write failed (reg 0x%02X): %s\n", reg, strerror(errno));
        usleep(RETRY_DELAY_MS * (1 << attempt));
    }
    return -1;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write reg failed (0x%02X): %s\n", reg, strerror(errno));
            usleep(RETRY_DELAY_MS * (1 << attempt));
            continue;
        }
        if (read(fd, buf, len) == len) return 0;
        fprintf(stderr, "I2C read burst failed (reg 0x%02X): %s\n", reg, strerror(errno));
        usleep(RETRY_DELAY_MS * (1 << attempt));
    }
    return -1;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (i2c_write_byte(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU-6050\n");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_pwm(void) {
    char path[128];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    int p = open(path, O_WRONLY);
    if (p < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(p, "20000000", 8) != 8) {
        fprintf(stderr, "Failed to set period: %s\n", strerror(errno));
        close(p);
        return -1;
    }
    close(p);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    int d = open(path, O_WRONLY);
    if (d < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(d, "0", 1) != 1) {
        fprintf(stderr, "Failed to set duty cycle: %s\n", strerror(errno));
        close(d);
        return -1;
    }
    close(d);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    int e = open(path, O_WRONLY);
    if (e < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(e, "1", 1) != 1) {
        fprintf(stderr, "Failed to enable PWM: %s\n", strerror(errno));
        close(e);
        return -1;
    }
    close(e);
    return 0;
}

static int read_mpu6050(float *ax, float *ay, float *az, float *gx, float *gy, float *gz) {
    uint8_t buf[14];
    if (i2c_read_burst(i2c_fd, ACCEL_XOUT_H, buf, 14) < 0) return -1;
    int16_t ax_raw = (buf[0] << 8) | buf[1];
    int16_t ay_raw = (buf[2] << 8) | buf[3];
    int16_t az_raw = (buf[4] << 8) | buf[5];
    int16_t gx_raw = (buf[8] << 8) | buf[9];
    int16_t gy_raw = (buf[10] << 8) | buf[11];
    int16_t gz_raw = (buf[12] << 8) | buf[13];
    *ax = (float)ax_raw / 16384.0f;
    *ay = (float)ay_raw / 16384.0f;
    *az = (float)az_raw / 16384.0f;
    *gx = (float)gx_raw / 131.0f;
    *gy = (float)gy_raw / 131.0f;
    *gz = (float)gz_raw / 131.0f;
    return 0;
}

static int set_servo_angle(float angle) {
    if (angle < 0.0f) angle = 0.0f;
    if (angle > 180.0f) angle = 180.0f;
