#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define FADE_DURATION 1800
#define SCHEDULE_FILE "lighting_schedule.txt"
#define TIMESTAMP_LEN 20
#define LINE_LEN 256

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int parse_schedule(const char *filename, int *schedule, int max_entries) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("fopen schedule");
        return -1;
    }

    int count = 0;
    char line[LINE_LEN];
    while (fgets(line, sizeof(line), fp) && count < max_entries) {
        char time_str[TIMESTAMP_LEN];
        int relay_num;
        int on_off;

        if (sscanf(line, "%19[^,],%d,%d", time_str, &relay_num, &on_off) != 3) {
            fprintf(stderr, "Invalid schedule entry: %s", line);
            continue;
        }

        if (relay_num < 1 || relay_num > NUM_RELAYS) {
            fprintf(stderr, "Invalid relay number: %d\n", relay_num);
            continue;
        }

        struct tm tm_info;
        if (!strptime(time_str, "%H:%M:%S", &tm_info)) {
            fprintf(stderr, "Invalid time format: %s", time_str);
            continue;
        }

        schedule[count] = (tm_info.tm_hour * 3600 + tm_info.tm_min * 60 + tm_info.tm_sec) * 1000000;
        schedule[count + 1] = relay_num;
        schedule[count + 2] = on_off;
        count += 3;
    }

    fclose(fp);
    return count / 3;
}

static void set_relay(int pin, int state) {
    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "gpioWrite failed on pin %d\n", pin);
    }
}

static void fade_to_brightness(int pin, int relay_num, int target_brightness) {
    int current_brightness = gpioGetPWMdutycycle(pin);
    if (current_brightness == target_brightness) return;

    int step = (target_brightness > current_brightness) ? 1 : -1;
    int elapsed = 0;

    while (elapsed < FADE_DURATION && running) {
        current_brightness += step;
        if (current_brightness < 0) current_brightness = 0;
        if (current_brightness > PWM_RANGE) current_brightness = PWM_RANGE;

        if (gpioPWM(pin, current_brightness) < 0) {
            fprintf(stderr, "gpioPWM failed on pin %d\n", pin);
            return;
        }

        gpioDelay(100000);
        elapsed++;
    }

    if (running) {
        gpioPWM(pin, target_brightness);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "gpioSetMode failed on pin %d\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        set_relay(relay_pins[i], 0);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int schedule[100 * 3];
    int num_entries = parse_schedule(SCHEDULE_FILE, schedule, sizeof(schedule) / sizeof(schedule[0]));
    if (num_entries <= 0) {
        fprintf(stderr, "No valid schedule entries found. Exiting.\n");
        for (int i = 0; i < NUM_RELAYS; i++) {
            set_relay(relay_pins[i], 0);
        }
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Home Lighting System started. Press Ctrl+C to exit.\n");

    while (running) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        if (!tm_info) {
            fprintf(stderr, "localtime failed\n");
            break;
        }

        int current_time = tm_info->tm_hour * 3600 + tm_info->tm_min * 60 + tm_info->tm_sec;

        for (int i = 0; i < num_entries; i += 3) {
            if (schedule[i] == current_time) {
                int relay_num = schedule[i + 1];
                int on_off = schedule[i + 2];

                if (on_off) {
                    set_relay(relay_pins[relay_num - 1], 1);
                    fade_to_brightness(relay_pins[relay_num - 1], relay_num, PWM_RANGE);
                } else {
                    fade_to_brightness(relay_pins[relay_num - 1], relay_num, 0);
                    set_relay(relay_pins[relay_num - 1], 0);
                }
                break;
            }
        }

        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay(relay_pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

