#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  30.0f
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000

#define SPEED_OF_SOUND_CM_PER_US 0.0343f
#define TRIGGER_PULSE_US         10
#define LOOP_DELAY_US            20000   /* 50 Hz */
#define ECHO_TIMEOUT_US          300000  /* 300 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in cm. Returns 0 on success, -1 on timeout or
 * sensor-absent (no echo within ECHO_TIMEOUT_US).
 */
static int measure_distance(float *distance_cm)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1;
    }

    /* Wait for echo rising edge */
    start_tick = gpioTick();
    timeout_tick = start_tick;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo start timeout (sensor absent or not responding)\n");
            return -1;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_tick = start_tick;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo end timeout (stuck high)\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    *distance_cm = (float)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;
    return 0;
}

static int set_buzzer_frequency(int frequency_hz)
{
    if (frequency_hz < 0) {
        frequency_hz = 0;
    }
    if (frequency_hz > 0) {
        if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode(BUZZER, PI_OUTPUT) failed\n");
            return -1;
        }
        if (gpioSetPWMfrequency(BUZZER_PIN, frequency_hz) < 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", frequency_hz);
            return -1;
        }
        if (gpioPWM(BUZZER_PIN, 128) < 0) {
            fprintf(stderr, "Error: gpioPWM(BUZZER, 128) failed\n");
            return -1;
        }
    } else {
        if (gpioPWM(BUZZER_PIN, 0) < 0) {
            fprintf(stderr, "Error: gpioPWM(BUZZER, 0) failed\n");
            return -1;
        }
    }
    return 0;
}

