{
    float distance_cm;
    int frequency_hz;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, PI_OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, PI_INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER, PI_OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000); /* 50 ms settle */

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed; Ctrl+C will not clean up\n");
    }

    printf("Theremin running. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (measure_distance(&distance_cm) == 0) {
            if (distance_cm < MIN_DISTANCE_CM) {
                distance_cm = MIN_DISTANCE_CM;
            } else if (distance_cm > MAX_DISTANCE_CM) {
                distance_cm = MAX_DISTANCE_CM;
            }

            frequency_hz = (int)((distance_cm - MIN_DISTANCE_CM) /
                                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM) *
                                 (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) +
                                 MIN_FREQUENCY_HZ);

            if (set_buzzer_frequency(frequency_hz) < 0) {
                fprintf(stderr, "Warning: Failed to set buzzer frequency\n");
            }
        } else {
            /* Sensor failure: silence buzzer and wait briefly */
            set_buzzer_frequency(0);
            gpioDelay(100000); /* 100 ms */
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    set_buzzer_frequency(0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

