#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255
#define PWM_FREQ  1000  /* 1 kHz for smooth LED transitions */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Simulate a proximity value in the range 0.0 to 1.0.
 * In a real application this would read from a network socket.
 */
static float simulate_proximity(void)
{
    static double phase = 0.0;
    phase += 0.01;
    return (float)(sin(phase) + 1.0) / 2.0;
}

/*
 * Set the RGB LED to a color derived from the proximity value.
 * Common-anode LED: 0 = on (white), 255 = off (off).
 */
static void set_led_color(float proximity)
{
    int red, green, blue;

    if (proximity < 0.0f) proximity = 0.0f;
    if (proximity > 1.0f) proximity = 1.0f;

    /* Blue dominant at low proximity, red dominant at high proximity. */
    blue = (int)(proximity * 255.0f);
    red  = (int)((1.0f - proximity) * 255.0f);
    green = 0;

    /* Common-anode: invert duty cycle. */
    gpioPWM(RED_PIN,   255 - red);
    gpioPWM(GREEN_PIN, 255 - green);
    gpioPWM(BLUE_PIN,  255 - blue);
}

int main(void)
{
    /* Install signal handlers for clean shutdown. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure PWM on all three pins. */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", GREEN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", BLUE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LED off. */
    gpioPWM(RED_PIN,   255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN,  255);

    printf("Color-based proximity alert started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float proximity = simulate_proximity();
        set_led_color(proximity);
        usleep(50000); /* 50 ms */
    }

    /* Clean shutdown: turn off LED and release pigpio. */
    gpioPWM(RED_PIN,   255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN,  255);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

