#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_US 50000
#define PWM_FREQ 1000
#define PWM_DUTY 500000  /* 50% of 1,000,000 */

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t play_melody = 0;
static volatile uint32_t last_press_tick = 0;

/* Melody: (frequency, duration_us) pairs. */
static const int melody[][2] = {
    {262, 200}, {294, 200}, {330, 200}, {349, 200},
    {392, 200}, {440, 200}, {494, 200}, {523, 200}
};
static const int melody_len = sizeof(melody) / sizeof(melody[0]);

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level != 0) return;  /* only act on falling edge (active-low) */

    uint32_t elapsed = tick - last_press_tick;
    if (elapsed < DEBOUNCE_US) return;
    last_press_tick = tick;

    if (play_melody) {
        /* Second press during playback: stop immediately. */
        play_melody = 0;
        gpioHardwarePWM(BUZZER_PIN, PWM_FREQ, 0);
        printf("Melody stopped.\n");
    } else {
        play_melody = 1;
        printf("Melody started.\n");
    }
}

static void play_melody(void) {
    for (int i = 0; i < melody_len && running; i++) {
        if (gpioHardwarePWM(BUZZER_PIN, melody[i][0], PWM_DUTY) != 0) {
            fprintf(stderr, "gpioHardwarePWM failed at note %d\n", i);
            return;
        }
        gpioDelay(melody[i][1]);
        if (gpioHardwarePWM(BUZZER_PIN, 0, 0) != 0) {
            fprintf(stderr, "gpioHardwarePWM stop failed at note %d\n", i);
            return;
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set button pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on button pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for button\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Musical doorbell ready. Press button on GPIO17 to play melody.\n");

    while (running) {
        if (play_melody) {
            play_melody();
            play_melody = 0;
        }
        gpioDelay(10000);  /* 10 ms poll */
    }

    /* Clean shutdown */
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

