#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define WINDOW_SIZE 5
#define DEFAULT_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_event(int value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s, %d\n", timestamp, value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(log_file) == EOF) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

static void earthquake_alert(int *window, int size, int value)
{
    static int count = 0;
    static int index = 0;

    window[index] = value;
    index = (index + 1) % size;
    if (value == 1) {
        count++;
    } else {
        count = 0;
    }

    if (count >= 3) {
        time_t rawtime;
        struct tm timeinfo;
        char timestamp[32];

        time(&rawtime);
        if (localtime_r(&rawtime, &timeinfo) == NULL) {
            fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
            return;
        }

        if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
            fprintf(stderr, "strftime failed\n");
            return;
        }

        printf("EARTHQUAKE ALERT: %s - %d consecutive HIGH events\n", timestamp, count);
        fflush(stdout);
    }
}

int main(int argc, char *argv[])
{
    int timeout_ms = DEFAULT_TIMEOUT_MS;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_event event;
    int window[WINDOW_SIZE] = {0};
    int window_index = 0;
    int window_count = 0;
    int ret;

    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout '%s', using default %d ms\n", argv[1], DEFAULT_TIMEOUT_MS);
            timeout_ms = DEFAULT_TIMEOUT_MS;
        }
    }

    log_file = fopen("vibration_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        fclose(log_file);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        fclose(log_file);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "vibration_sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    printf("Vibration sensor monitoring started on GPIO%d. Timeout: %d ms. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET, timeout_ms);

    while (program_running) {
        struct timespec ts = { .tv_sec = timeout_ms / 1000, .tv_nsec = (timeout_ms % 1000) * 1000000L };
        int rv = gpiod_line_event_wait(line, &ts);

        if (rv < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error waiting for event: %s\n", strerror(errno));
            break;
        }

        if (rv == 0) {
            continue;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            fprintf(stderr, "Error reading event: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            log_event(1);
            earthquake_alert(window, WINDOW_SIZE, 1);
            window_index = (window_index + 1) % WINDOW_SIZE;
            window[window_index] = 1;
            window_count++;
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            log_event(0);
            earthquake_alert(window, WINDOW_SIZE, 0);
            window_index = (window_index + 1) % WINDOW_SIZE;
            window[window_index] = 0;
            window_count++;
        }
    }

    printf("\nCleaning up...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    if (log_file != NULL) {
        if (fclose(log_file) == EOF) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        }
    }
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

