#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define LSM303_ADDRESS_MAG 0x1E
#define LSM303_REGISTER_MR_REG_M 0x02
#define LSM303_REGISTER_CRA_REG_M 0x00
#define LSM303_REGISTER_OUT_X_H_M 0x03

#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

#define I2C_BUS "/dev/i2c-1"
#define CSV_FILE "mag_log.csv"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int initialize_magnetometer(int fd) {
    if (i2c_write_byte(fd, LSM303_REGISTER_MR_REG_M, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, LSM303_REGISTER_CRA_REG_M, 0x14) < 0) return -1;
    return 0;
}

static int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, LSM303_REGISTER_OUT_X_H_M, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static float calibrate_magnetometer_data(int16_t x, int16_t y, int16_t z) {
    return (float)(x - X_OFFSET, y - Y_OFFSET, z - Z_OFFSET);
}

static float calculate_heading(float x, float y) {
    float heading = atan2f(y, x) * 180.0f / (float)M_PI;
    if (heading < 0.0f) heading += 360.0f;
    return heading;
}

static const char *determine_compass_direction(float heading) {
    if (heading >= 337.5f || heading < 22.5f) return "N";
    if (heading < 67.5f) return "NE";
    if (heading < 112.5f) return "E";
    if (heading < 157.5f) return "SE";
    if (heading < 202.5f) return "S";
    if (heading < 247.5f) return "SW";
    if (heading < 292.5f) return "W";
    return "NW";
}

static int log_data_to_csv(FILE *fp, float x, float y, float z, float heading, const char *direction) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f,%s\n", timestamp, x, y, z, heading, direction) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, LSM303_ADDRESS_MAG) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LSM303_ADDRESS_MAG, strerror(errno));
        close(fd);
        return 1;
    }

    if (initialize_magnetometer(fd) < 0) {
        fprintf(stderr, "Failed to initialize magnetometer.\n");
        close(fd);
        return 1;
    }

    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", CSV_FILE, strerror(errno));
        close(fd);
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n");
        fflush(fp);
    }

    printf("Logging magnetometer data to %s. Press Ctrl+C to stop.\n", CSV_FILE);

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        if (read_magnetometer_data(fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Skipping sample due to I2C read error.\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float x = calibrate_magnetometer_data(raw_x, raw_y, raw_z);
        float y = calibrate_magnetometer_data(raw_x, raw_y, raw_z);
        float heading = calculate_heading(x, y);
        const char *direction = determine_compass_direction(heading);

        printf("Calibrated X: %.2f, Calibrated Y: %.2f, Calibrated Z: %.2f, Heading: %.2f, Direction: %s\n",
               x, y, z, heading, direction);

        if (log_data_to_csv(fp, x, y, z, heading, direction) < 0) {
            fprintf(stderr, "Failed to log data to CSV.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly.\n");
    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
    }
    if (close(fd) < 0) {
        fprintf(stderr, "close(fd) failed: %s\n", strerror(errno));
    }
    return 0;
}

