/*
 * Automated plant watering system for Raspberry Pi Zero W
 * Two SG90 servos: valve (GPIO17) and nozzle (GPIO18)
 * Simulated soil-moisture readings cycle 20, 40, 60, 80, 100
 * Valve: 0 deg = closed, 90 deg = open
 * Nozzle: 0 deg, 45 deg, 90 deg, 135 deg, 180 deg
 * Below 50 -> open valve, sweep nozzle, hold, close valve
 * Compile: gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 */
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

#define VALVE_CLOSED_US  500   /* ~0 deg   */
#define VALVE_OPEN_US    1500  /* ~90 deg  */
#define NOZZLE_MIN_US    500
#define NOZZLE_MAX_US    2500

#define MOISTURE_THRESHOLD 50
#define WATERING_DURATION 5
#define NOZZLE_STEP_DELAY 2
#define CYCLE_DELAY      5
#define MAX_RETRIES      3
#define RETRY_DELAY_US   100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse_safe(unsigned pin, unsigned pulse_us)
{
    int rc;
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        rc = gpioServo(pin, pulse_us);
        if (rc == 0)
            return 0;
        fprintf(stderr, "gpioServo(pin=%u, %u) failed (rc=%d), attempt %d/%d\n",
                pin, pulse_us, rc, attempt + 1, MAX_RETRIES);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int open_valve(void)
{
    return set_servo_pulse_safe(VALVE_SERVO_PIN, VALVE_OPEN_US);
}

static int close_valve(void)
{
    return set_servo_pulse_safe(VALVE_SERVO_PIN, VALVE_CLOSED_US);
}

static int set_nozzle_angle(int angle)
{
    unsigned pulse;
    switch (angle) {
        case 0:  pulse = NOZZLE_MIN_US; break;
        case 45: pulse = 1125;          break;
        case 90: pulse = 1500;          break;
        case 135: pulse = 1875;         break;
        case 180: pulse = NOZZLE_MAX_US; break;
        default:
            fprintf(stderr, "Invalid nozzle angle %d\n", angle);
            return -1;
    }
    return set_servo_pulse_safe(NOZZLE_SERVO_PIN, pulse);
}

static int read_soil_moisture(void)
{
    static const int moisture_levels[] = {20, 40, 60, 80, 100};
    static int index = 0;
    int moisture = moisture_levels[index];
    index = (index + 1) % (int)(sizeof(moisture_levels) / sizeof(moisture_levels[0]));
    printf("Soil moisture: %d%%\n", moisture);
    return moisture;
}

static void cleanup_servos(void)
{
    /* Stop PWM signal (pulse width 0) before terminating pigpio */
    gpioServo(VALVE_SERVO_PIN, 0);
    gpioServo(NOZZLE_SERVO_PIN, 0);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Automated Plant Watering System started\n");
    printf("Valve servo on GPIO%d, Nozzle servo on GPIO%d\n",
           VALVE_SERVO_PIN, NOZZLE_SERVO_PIN);

    while (g_running) {
        int moisture = read_soil_moisture();

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold (%d%% < %d%%). Starting watering cycle.\n",
                   moisture, MOISTURE_THRESHOLD);

            if (open_valve() != 0) {
                fprintf(stderr, "Critical: Failed to open valve. Aborting cycle.\n");
                break;
            }

            int angles[] = {0, 45, 90, 135, 180};
            for (size_t i = 0; i < sizeof(angles) / sizeof(angles[0]); ++i) {
                if (!g_running)
                    break;
                if (set_nozzle_angle(angles[i]) != 0) {
                    fprintf(stderr, "Error: Failed to set nozzle angle %d. Skipping cycle.\n",
                            angles[i]);
                    break;
                }
                gpioDelay(NOZZLE_STEP_DELAY * 1000000);
            }

            if (close_valve() != 0) {
                fprintf(stderr, "Warning: Failed to close valve.\n");
            }
        } else {
            printf("Moisture above threshold (%d%% >= %d%%). Skipping watering.\n",
                   moisture, MOISTURE_THRESHOLD);
        }

        if (g_running)
            gpioDelay(CYCLE_DELAY * 1000000);
    }

    cleanup_servos();
    gpioTerminate();
    printf("Automated Plant Watering System stopped\n");
    return EXIT_SUCCESS;
}

