#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define STEP1 4
#define STEP2 17
#define STEP3 27
#define STEP4 22
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

#define STEP_DELAY_US 3000
#define DEBOUNCE_US 50000
#define STEP_COUNT 512

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_write(unsigned gpio, int level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %d) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_set_pull(unsigned gpio, unsigned pud) {
    if (gpioSetPullUpDown(gpio, pud) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%u, %u) failed\n", gpio, pud);
        return -1;
    }
    return 0;
}

static void deenergize(void) {
    safe_write(STEP1, 0);
    safe_write(STEP2, 0);
    safe_write(STEP3, 0);
    safe_write(STEP4, 0);
}

static int rotate_clockwise(int steps) {
    int pattern[4] = {1, 0, 0, 1};
    for (int i = 0; i < steps && running; i++) {
        for (int j = 0; j < 4; j++) {
            if (safe_write(STEP1, pattern[j]) < 0) return -1;
            if (safe_write(STEP2, pattern[(j + 1) & 3]) < 0) return -1;
            if (safe_write(STEP3, pattern[(j + 2) & 3]) < 0) return -1;
            if (safe_write(STEP4, pattern[(j + 3) & 3]) < 0) return -1;
            gpioDelay(STEP_DELAY_US);
        }
    }
    deenergize();
    return 0;
}

static int rotate_counter_clockwise(int steps) {
    int pattern[4] = {1, 0, 0, 1};
    for (int i = 0; i < steps && running; i++) {
        for (int j = 0; j < 4; j++) {
            if (safe_write(STEP1, pattern[(j + 3) & 3]) < 0) return -1;
            if (safe_write(STEP2, pattern[(j + 2) & 3]) < 0) return -1;
            if (safe_write(STEP3, pattern[(j + 1) & 3]) < 0) return -1;
            if (safe_write(STEP4, pattern[j]) < 0) return -1;
            gpioDelay(STEP_DELAY_US);
        }
    }
    deenergize();
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(STEP1, PI_OUTPUT) < 0 ||
        safe_set_mode(STEP2, PI_OUTPUT) < 0 ||
        safe_set_mode(STEP3, PI_OUTPUT) < 0 ||
        safe_set_mode(STEP4, PI_OUTPUT) < 0 ||
        safe_set_mode(LOCK_BUTTON, PI_INPUT) < 0 ||
        safe_set_mode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_pull(LOCK_BUTTON, PI_PUD_UP) < 0 ||
        safe_set_pull(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_write(STEP1, 0) < 0 || safe_write(STEP2, 0) < 0 ||
        safe_write(STEP3, 0) < 0 || safe_write(STEP4, 0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Automatic Door Lock System\n");
    printf("Press LOCK (GPIO24) to rotate clockwise\n");
    printf("Press UNLOCK (GPIO23) to rotate counter-clockwise\n");
    printf("Press Ctrl+C to exit\n\n");

    while (running) {
        int lock_state = gpioRead(LOCK_BUTTON);
        int unlock_state = gpioRead(UNLOCK_BUTTON);

        if (lock_state == 0) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(LOCK_BUTTON) == 0) {
                printf("Locking door...\n");
                if (rotate_clockwise(STEP_COUNT) < 0) {
                    fprintf(stderr, "Error: lock rotation failed\n");
                } else {
                    printf("Door locked\n");
                }
            }
        }

        if (unlock_state == 0) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(UNLOCK_BUTTON) == 0) {
                printf("Unlocking door...\n");
                if (rotate_counter_clockwise(STEP_COUNT) < 0) {
                    fprintf(stderr, "Error: unlock rotation failed\n");
                } else {
                    printf("Door unlocked\n");
                }
            }
        }

        gpioDelay(10000);
    }

    deenergize();
    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

