/*
 * HC-SR04 ultrasonic distance logger for Raspberry Pi 4 Model B.
 * Uses libgpiod v2.x (modern GPIO API) instead of deprecated wiringPi.
 *
 * Wiring:
 *   HC-SR04 VCC -> 5V (Pin 2 or 4)
 *   HC-SR04 GND -> GND (Pin 6)
 *   HC-SR04 TRIG -> BCM GPIO17 (Pin 11)
 *   HC-SR04 ECHO -> BCM GPIO18 (Pin 12) via 560 ohm series resistor
 *   (Echo output is 5 V; use a voltage divider or level shifter to 3.3 V.)
 *
 * Build: gcc -O2 -Wall -Wextra -o hcsr04_log hcsr04_log.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN  17
#define ECHO_PIN     18

#define SPEED_OF_SOUND_CM_PER_US  0.01715   /* 343 m/s / 2 / 1e6 */
#define TRIGGER_PULSE_US          10
#define ECHO_TIMEOUT_US           50000      /* 50 ms */
#define MEASURE_INTERVAL_S        1
#define MIN_MEASUREMENT_GAP_S     0.1        /* 60 ms */
#define LOG_FILE_PATH             "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void sleep_us(unsigned int us)
{
    struct timespec ts = {
        .tv_sec  = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

static void sleep_ms(unsigned int ms)
{
    sleep_us(ms * 1000U);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_distance(int distance_cm)
{
    if (g_log_fp == NULL) {
        fprintf(stderr, "Log file not open; cannot log distance %d cm.\n",
                distance_cm);
        return;
    }

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }

    fprintf(g_log_fp, "%s, %d\n", ts, distance_cm);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* HC-SR04 measurement                                                 */
/* ------------------------------------------------------------------ */
/*
 * Returns:
 *   >= 0  distance in cm
 *   -1    timeout or GPIO error
 */
static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo)
{
    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    sleep_us(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    sleep_us(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for echo rising edge (timeout) */
    unsigned int waited = 0;
    while (gpiod_line_get_value(echo) == 0) {
        if (waited >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo rising edge.\n");
            return -1;
        }
        sleep_us(100);
        waited += 100;
    }

    /* Measure echo pulse width (timeout) */
    unsigned int start_tick = gpiod_line_get_value(echo);
    if (start_tick < 0) {
        fprintf(stderr, "Failed to read echo line: %s\n", strerror(errno));
        return -1;
    }

    unsigned int elapsed = 0;
    while (gpiod_line_get_value(echo) == 1) {
        if (elapsed >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo falling edge.\n");
            return -1;
        }
        sleep_us(100);
        elapsed += 100;
    }

    unsigned int end_tick = gpiod_line_get_value(echo);
    if (end_tick < 0) {
        fprintf(stderr, "Failed to read echo line: %s\n", strerror(errno));
        return -1;
    }

    unsigned int duration_us = end_tick - start_tick;
    if (duration_us == 0) {
        fprintf(stderr, "Invalid echo pulse width: %u us\n", duration_us);
        return -1;
    }

    return (int)((double)duration_us * SPEED_OF_SOUND_CM_PER_US);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Open log file once */
    g_log_fp = fopen(LOG_FILE_PATH, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                LOG_FILE_PATH, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open default gpiochip (gpiochip4 on Pi 4 Bookworm) */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        chip = gpiod_chip_open_by_label("pinctrl-bcm2711");
    }
    if (chip == NULL) {
        chip = gpiod_chip_open_by_number(0);
    }
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        goto cleanup;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (trig == NULL || echo == NULL) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request trigger as output, initial low */
    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request echo as input */
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
