#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define RELAY_GPIO     18
#define DISTANCE_THRESHOLD 50  /* cm */
#define POLL_DELAY_US  100000  /* 100 ms */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET          0x0000
#define REG_SYSTEM_START        0x0080
#define REG_INT_STATUS          0x0044
#define REG_RESULT_DISTANCE_MSB 0x0096
#define REG_RESULT_DISTANCE_LSB 0x0097

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address followed by a single byte value. */
static int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

/* Read a 16-bit register address and return the 8-bit data. */
static int vl53l1x_read_byte(int handle, uint16_t reg)
{
    char addr[2];
    char data;
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, &data, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed\n", reg);
        return -1;
    }
    return (int)(uint8_t)data;
}

static int vl53l1x_init(int handle)
{
    /* Software reset: write 0x00 to register 0x0000 */
    if (vl53l1x_write_byte(handle, REG_SOFT_RESET, 0x00) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Set ranging mode to continuous (bit 0 = 1) */
    if (vl53l1x_write_byte(handle, REG_SYSTEM_START, 0x01) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms for first measurement */

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance)
{
    int status;
    int msb, lsb;

    /* Check data-ready bit (bit 0 of INT_STATUS) */
    status = vl53l1x_read_byte(handle, REG_INT_STATUS);
    if (status < 0)
        return -1;
    if ((status & 0x01) == 0)
        return 1; /* no new data yet */

    /* Read MSB and LSB from registers 0x0096 and 0x0097 */
    msb = vl53l1x_read_byte(handle, REG_RESULT_DISTANCE_MSB);
    if (msb < 0)
        return -1;
    lsb = vl53l1x_read_byte(handle, REG_RESULT_DISTANCE_LSB);
    if (lsb < 0)
        return -1;

    *distance = ((uint16_t)msb << 8) | (uint16_t)lsb;
    return 0;
}

static void control_relay(int gpio, int state)
{
    if (gpioWrite(gpio, state) != 0)
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", gpio, state);
}

int main(void)
{
    uint16_t distance;
    int ret;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at VL53L1X default address */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize VL53L1X sensor */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO as output, initially LOW */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    /* Install signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity-based door control started. Threshold: %d cm. Press Ctrl+C to exit.\n",
           DISTANCE_THRESHOLD);

    while (g_running) {
        ret = vl53l1x_read_distance(g_i2c_handle, &distance);

        if (ret == 0) {
            printf("Distance: %u cm\n", distance);
            if (distance <= DISTANCE_THRESHOLD) {
                printf("Threshold reached! Opening door.\n");
                control_relay(RELAY_GPIO, 1);
            } else {
                control_relay(RELAY_GPIO, 0);
            }
        } else if (ret < 0) {
            fprintf(stderr, "I2C read error. Retrying...\n");
        }
        /* ret == 1 means no new data yet; just wait */

        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    control_relay(RELAY_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

