#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PINS {17, 18, 27, 22}
#define NUM_RELAYS 4
#define WATERING_DURATION 5
#define CYCLE_INTERVAL 86400
#define POLL_INTERVAL 60
#define LOG_FILE "watering_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_watering_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s\n", timestamp) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_RELAYS];
    int pin_values[NUM_RELAYS] = {1, 1, 1, 1};  /* active-low: 1 = inactive (watering off) */
    int pin_numbers[NUM_RELAYS] = GPIO_PINS;

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_numbers[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", pin_numbers[i], strerror(errno));
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(lines[i], "watering-system", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%d) failed: %s\n", pin_numbers[i], strerror(errno));
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    printf("Watering system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        time_t current_time = time(NULL);
        if (current_time == (time_t)-1) {
            perror("time");
            sleep(POLL_INTERVAL);
            continue;
        }

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (!program_running) break;

            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "gpiod_line_set_value(%d, 0) failed: %s\n", pin_numbers[i], strerror(errno));
                continue;
            }

            if (log_watering_event() < 0) {
                fprintf(stderr, "Failed to log watering event for relay %d\n", i + 1);
            }

            printf("Relay %d (GPIO%d) activated for %d seconds.\n", i + 1, pin_numbers[i], WATERING_DURATION);

            for (int elapsed = 0; elapsed < WATERING_DURATION && program_running; elapsed++) {
                sleep(1);
            }

            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "gpiod_line_set_value(%d, 1) failed: %s\n", pin_numbers[i], strerror(errno));
            }
        }

        if (program_running) {
            for (int elapsed = 0; elapsed < CYCLE_INTERVAL && program_running; elapsed += POLL_INTERVAL) {
                sleep(POLL_INTERVAL);
            }
        }
    }

    printf("\nShutting down...\n");

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
        }
    }
    gpiod_chip_close(chip);

    printf("Watering system stopped.\n");
    return EXIT_SUCCESS;
}

