#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define SUNRISE_DURATION 30
#define STEP_DELAY 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO%d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    if (gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", RELAY1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", RELAY2_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", RELAY3_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", RELAY4_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(RELAY1_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", RELAY1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(RELAY2_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", RELAY2_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(RELAY3_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", RELAY3_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(RELAY4_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", RELAY4_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void sunrise_simulation(void) {
    log_event("Sunrise simulation started");

    for (int i = 0; i <= 255 && running; i++) {
        if (gpioPWM(RELAY1_PIN, i) != 0) {
            log_event("Error: gpioPWM failed on GPIO17");
            break;
        }
        if (gpioPWM(RELAY2_PIN, i) != 0) {
            log_event("Error: gpioPWM failed on GPIO18");
            break;
        }
        if (gpioPWM(RELAY3_PIN, i) != 0) {
            log_event("Error: gpioPWM failed on GPIO27");
            break;
        }
        if (gpioPWM(RELAY4_PIN, i) != 0) {
            log_event("Error: gpioPWM failed on GPIO22");
            break;
        }

        char log_message[128];
        snprintf(log_message, sizeof(log_message),
                 "Sunrise step %d: PWM duty cycle = %d", i, i);
        log_event(log_message);

        sleep(STEP_DELAY);
    }

    log_event("Sunrise simulation complete");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (setup_gpio() != 0) {
        return 1;
    }

    sunrise_simulation();

    gpioTerminate();
    log_event("pigpio terminated");
    return 0;
}

