#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_WHO_AM_I   0x75
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_GYRO_XOUT_H 0x43

/* Expected device ID */
#define MPU6050_WHO_AM_I_VAL 0x68

/* GPIO pin for LED */
#define LED_PIN 17

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Gyroscope sensitivity for ±250 deg/s range */
#define GYRO_SENSITIVITY 131.0f

/* Threshold for angular velocity (deg/s) */
#define THRESHOLD 250.0f

/* Sampling period (microseconds) */
#define SAMPLE_PERIOD_US 50000

/* Re-initialisation retries */
#define REINIT_RETRIES 3

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Data structure for gyroscope readings */
typedef struct {
    time_t timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

/* Circular buffer */
static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Initialise MPU-6050: wake up, set sample rate, configure gyroscope */
static int init_mpu6050(void) {
    int rc;

    /* Wake up the sensor (clear sleep bit) */
    rc = i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x00);
    if (rc < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %d\n", rc);
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Set sample rate divider to 1 (1 kHz / (1 + 1) = 500 Hz) */
    rc = i2cWriteByteData(i2c_handle, MPU6050_SMPLRT_DIV, 0x07);
    if (rc < 0) {
        fprintf(stderr, "Error writing SMPLRT_DIV: %d\n", rc);
        return -1;
    }

    /* Configure gyroscope: ±250 deg/s full-scale range */
    rc = i2cWriteByteData(i2c_handle, MPU6050_GYRO_CONFIG, 0x00);
    if (rc < 0) {
        fprintf(stderr, "Error writing GYRO_CONFIG: %d\n", rc);
        return -1;
    }

    return 0;
}

/* Read 6 bytes of gyroscope data and convert to degrees/second */
static int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int rc;

    rc = i2cReadI2CBlockData(i2c_handle, MPU6050_GYRO_XOUT_H, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading gyroscope data: %d\n", rc);
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

/* Add a reading to the circular buffer */
static void add_to_buffer(float x, float y, float z) {
    gyro_buffer[buffer_index].timestamp = time(NULL);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* Check if any axis exceeds the threshold */
static bool check_threshold(float x, float y, float z) {
    return (fabsf(x) > THRESHOLD ||
            fabsf(y) > THRESHOLD ||
            fabsf(z) > THRESHOLD);
}

/* Re-initialise the I2C connection */
static int reinit_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    gpioDelay(100000); /* 100 ms settle */

    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error re-opening I2C: %d\n", i2c_handle);
        return -1;
    }

    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error re-initialising MPU-6050\n");
        return -1;
    }

    return 0;
}

int main(void) {
    float x, y, z;
    int retries = 0;

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Configure LED pin */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open I2C bus 1 at address 0x68 */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Verify device identity */
    int who = i2cReadByteData(i2c_handle, MPU6050_WHO_AM_I);
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, MPU6050_WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialise sensor */
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error initialising MPU-6050\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Main loop */
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);

            if (check_threshold(x, y, z)) {
                gpioWrite(LED_PIN, 1);
            } else {
                gpioWrite(LED_PIN, 0);
            }

            printf("X: %.2f, Y: %.2f, Z: %.2f deg/s\n", x, y, z);
        } else {
            retries++;
            fprintf(stderr, "Read failed (%d/%d)\n", retries, REINIT_RETRIES);
            if (reinit_i2c() < 0) {
                fprintf(stderr, "Re-initialisation failed, exiting\n");
                break;
            }
            retries = 0;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();

    return 0;
}

