#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_LINE_OFFSET  8
#define LOG_FILE        "gyro_log.txt"
#define SAMPLE_PERIOD_NS 10000000L
#define MAX_RETRIES     3

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int read_gyro(int fd, struct gpiod_line *cs, float *x, float *y, float *z) {
    uint8_t tx[6] = {0x43, 0x00, 0x00, 0x00, 0x00, 0x00};
    uint8_t rx[6] = {0};
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (gpiod_line_set_value(cs, 0) < 0) {
            fprintf(stderr, "CS low failed: %s\n", strerror(errno));
            retries++;
            usleep(1000);
            continue;
        }
        usleep(10);
        if (spi_transfer(fd, tx, rx, 6) == 0) {
            int16_t raw_x = (int16_t)((rx[0] << 8) | rx[1]);
            int16_t raw_y = (int16_t)((rx[2] << 8) | rx[3]);
            int16_t raw_z = (int16_t)((rx[4] << 8) | rx[5]);
            *x = (float)raw_x / 131.0f;
            *y = (float)raw_y / 131.0f;
            *z = (float)raw_z / 131.0f;
            if (gpiod_line_set_value(cs, 1) < 0) {
                fprintf(stderr, "CS high failed: %s\n", strerror(errno));
                return -1;
            }
            return 0;
        }
        if (gpiod_line_set_value(cs, 1) < 0) {
            fprintf(stderr, "CS high failed: %s\n", strerror(errno));
        }
        retries++;
        usleep(1000);
    }
    return -1;
}

static int log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);
    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_line *cs = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(cs, "mpu9250-gyro", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(cs);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    while (running) {
        float x, y, z;
        if (read_gyro(spi_fd, cs, &x, &y, &z) == 0) {
            if (log_data(fp, x, y, z) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "SPI read failed after %d retries\n", MAX_RETRIES);
        }
        struct timespec sleep_ts = {0, SAMPLE_PERIOD_NS};
        nanosleep(&sleep_ts, NULL);
    }

    fclose(fp);
    gpiod_line_release(cs);
    gpiod_chip_close(chip);
    close(spi_fd);
    printf("\nShutdown complete.\n");
    return 0;
}

