#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define LED_PIN         17
#define CS_PIN          8
#define BUFFER_SIZE     64
#define GYRO_SENSITIVITY 131.0f
#define THRESHOLD       200.0f
#define BLINK_DELAY_MS  500
#define SAMPLE_DELAY_MS 100

typedef struct {
    time_t timestamp;
    float  x;
    float  y;
    float  z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS: %s\n", strerror(errno));
        return -1;
    }
    usleep(10);
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = 3900000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS: %s\n", strerror(errno));
        return -1;
    }
    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gyro_axis(uint8_t reg, float *out) {
    uint8_t tx[2] = { reg | 0x80, 0x00 };
    uint8_t rx[2] = { 0 };
    if (spi_transfer(tx, rx, 2) < 0) return -1;
    int16_t raw = (int16_t)((rx[0] << 8) | rx[1]);
    *out = (float)raw / GYRO_SENSITIVITY;
    return 0;
}

static void add_to_buffer(float x, float y, float z) {
    gyro_buffer[buffer_index].timestamp = time(NULL);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void check_threshold(float x, float y, float z) {
    if (x > THRESHOLD || x < -THRESHOLD ||
        y > THRESHOLD || y < -THRESHOLD ||
        z > THRESHOLD || z < -THRESHOLD) {
        if (gpiod_line_set_value(led_line, 1) < 0) {
            fprintf(stderr, "Failed to set LED on: %s\n", strerror(errno));
        }
        usleep(BLINK_DELAY_MS * 1000);
        if (gpiod_line_set_value(led_line, 0) < 0) {
            fprintf(stderr, "Failed to set LED off: %s\n", strerror(errno));
        }
        usleep(BLINK_DELAY_MS * 1000);
    }
}

static void print_buffer(void) {
    printf("Timestamp,X(deg/s),Y(deg/s),Z(deg/s)\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        struct tm *tm_info = localtime(&gyro_buffer[idx].timestamp);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("%s,%.2f,%.2f,%.2f\n",
               ts, gyro_buffer[idx].x, gyro_buffer[idx].y, gyro_buffer[idx].z);
    }
    printf("\n");
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (cs_line) gpiod_line_release(cs_line);
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
}

int main(void) {
    struct sigaction sa = { .sa_handler = signal_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }
    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!cs_line || !led_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(cs_line, "mpu6050-cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(led_line, "mpu6050-led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 3900000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to configure SPI: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Gyroscope monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        if (read_gyro_axis(0x43, &x) < 0 ||
            read_gyro_axis(0x45, &y) < 0 ||
            read_gyro_axis(0x47, &z) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }
        add_to_buffer(x, y, z);
        check_threshold(x, y, z);
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    print_buffer();
    cleanup();
    return 0;
}

