#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

/* GPIO pin for LED */
#define LED_PIN 21

/* Tilt threshold in degrees */
#define TILT_THRESHOLD 45.0

/* I2C bus on Raspberry Pi 4 Model B */
#define I2C_BUS 1

/* Global variables for cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Initialise the MPU-6050: wake up and set accelerometer range to ±2g */
static int init_mpu6050(int handle) {
    /* Wake up the device (clear sleep bit) */
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time */

    /* Set accelerometer full-scale range to ±2g (AFS_SEL = 0) */
    if (i2cWriteByteData(handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write ACCEL_CONFIG: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100000);

    return 0;
}

/* Read 6 bytes of raw accelerometer data and convert to g */
static int read_accelerometer(int handle, float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    /* ±2g range: 16384 LSB/g */
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;

    return 0;
}

/* Calculate roll and pitch from accelerometer data */
static void calculate_tilt(float x, float y, float z, float *roll, float *pitch) {
    *roll  = atan2f(y, z) * 180.0f / M_PI;
    *pitch = atan2f(-x, sqrtf(y * y + z * z)) * 180.0f / M_PI;
}

/* Log tilt data to file */
static void log_tilt_data(float roll, float pitch) {
    FILE *fp = fopen("tilt_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open tilt_log.txt: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fclose(fp);
}

/* Control the LED based on tilt thresholds */
static void control_led(float roll, float pitch) {
    int state = (fabsf(roll) > TILT_THRESHOLD || fabsf(pitch) > TILT_THRESHOLD) ? 1 : 0;
    gpioWrite(LED_PIN, state);
}

int main(void) {
    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
