#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define SI1145_REG_ALS_VIS_DATA0 0x20
#define SI1145_REG_PS1_DATA0 0x22
#define GPIO_CHIP "gpiochip0"
#define GPIO_LED 17
#define PROXIMITY_THRESHOLD 100
#define LOG_FILE "biometric_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 100

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_chip *chip = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t als_lo, als_hi, ps_lo, ps_hi;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read_reg8(fd, SI1145_REG_ALS_VIS_DATA0, &als_lo) == 0 &&
            i2c_read_reg8(fd, SI1145_REG_ALS_VIS_DATA0 + 1, &als_hi) == 0 &&
            i2c_read_reg8(fd, SI1145_REG_PS1_DATA0, &ps_lo) == 0 &&
            i2c_read_reg8(fd, SI1145_REG_PS1_DATA0 + 1, &ps_hi) == 0) {
            *ambient_light = (uint16_t)((als_hi << 8) | als_lo);
            *proximity = (uint16_t)((ps_hi << 8) | ps_lo);
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,AmbientLight:%u,Proximity:%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            ambient_light, proximity);
    fflush(fp);
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }
    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(led_line, "si1145_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    printf("Si1145 sensor interface started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t ambient_light, proximity;
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(log_file, ambient_light, proximity);
            if (proximity > PROXIMITY_THRESHOLD) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup();
    printf("Exiting gracefully.\n");
    return 0;
}

