#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADXRS290 register addresses (upper nibble of address byte) */
#define ADXRS290_REG_X_RATE 0x02
#define ADXRS290_REG_Y_RATE 0x04

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0        /* CPOL=0, CPHA=0 */

/* Sensitivity: 200 LSB/deg/s */
#define SENSITIVITY 200.0f

/* Sampling interval: ~100 Hz */
#define SAMPLE_INTERVAL_US 10000

/* Reinitialisation retries */
#define MAX_REINIT_RETRIES 3

/* Global state */
static int spi_handle = -1;
static FILE *data_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; cleanup happens in main()           */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit two's-complement register from the ADXRS290           */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int read_gyro_axis(int handle, uint8_t reg_addr, int16_t *out)
{
    char tx[2];
    char rx[2];

    /* ADXRS290 read: send address OR'd with 0x80, then a dummy byte */
    tx[0] = (char)(reg_addr | 0x80);
    tx[1] = 0x00;

    int ret = spiXfer(handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "spiXfer failed for reg 0x%02X (ret=%d)\n", reg_addr, ret);
        return -1;
    }

    /* rx[0] is the high byte, rx[1] is the low byte (MSB first) */
    uint16_t raw = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];

    /* Sign-extend 16-bit two's complement */
    if (raw & 0x8000) {
        raw |= 0xFFFF0000;
    }

    *out = (int16_t)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise SPI                                                      */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int init_spi(void)
{
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Reinitialise SPI after a failure                                    */
/* ------------------------------------------------------------------ */
static int reinit_spi(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    for (int attempt = 1; attempt <= MAX_REINIT_RETRIES; attempt++) {
        if (init_spi() == 0) {
            fprintf(stderr, "SPI reinitialised (attempt %d/%d)\n",
                    attempt, MAX_REINIT_RETRIES);
            return 0;
        }
        fprintf(stderr, "SPI reinitialisation attempt %d/%d failed\n",
                attempt, MAX_REINIT_RETRIES);
        if (attempt < MAX_REINIT_RETRIES) {
            gpioDelay(100000); /* 100 ms backoff */
        }
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Log one sample to the CSV file                                      */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int16_t x_rate, int16_t y_rate)
{
    struct timeval tv;
    if (gettimeofday(&tv, NULL) != 0) {
        fprintf(stderr, "gettimeofday failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&tv.tv_sec, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s.%06ld,%d,%d\n",
                timestamp, (long)tv.tv_usec, x_rate, y_rate) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — release all resources                                     */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (data_file != NULL) {
        fflush(data_file);
        fclose(data_file);
        data_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Open CSV file */
    data_file = fopen("gyro_data.csv", "a");
    if (data_file == NULL) {
        fprintf(stderr, "fopen(gyro_data.csv) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(data_file) == 0) {
        fprintf(data_file, "timestamp,X_rate,Y_rate\n");
        fflush(data_file);
    }

    /* Initialise SPI */
    if (init_spi() != 0) {
        fprintf(stderr, "Initial SPI setup failed; exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "ADXRS290 gyroscope reader started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        int16_t x_rate = 0, y_rate = 0;

        if (read_gyro_axis(spi_handle, ADXRS290_REG_X_RATE, &x_rate) != 0) {
            fprintf(stderr, "Failed to read X-axis data; reinitialising SPI.\n");
            if (reinit_spi() != 0) {
                fprintf(stderr, "SPI reinitialisation failed; exiting.\n");
                break;
            }
            continue;
        }

        if (read_gyro_axis(spi_handle, ADXRS290_REG_Y_RATE, &y_rate) != 0) {
            fprintf(stderr, "Failed to read Y-axis data; reinitialising SPI.\n");
            if (reinit_spi() != 0) {
                fprintf(stderr, "SPI reinitialisation failed; exiting.\n");
                break;
            }
            continue;
        }

        /* Convert raw LSB to deg/s */
        float x_rate_dps = (float)x_rate / SENSITIVITY;
        float y_rate_dps = (float)y_rate / SENSITIVITY;

        if (log_data(data_file, x_rate, y_rate) != 0) {
            fprintf(stderr, "Failed to log data; reinitialising SPI.\n");
            if (reinit_spi() != 0) {
                fprintf(stderr, "SPI reinitialisation failed; exiting.\n");
                break;
            }
            continue;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "Shutting down...\n");
