#define ALERT_PIN    17
#define LOG_FILE     "seismic_events.txt"
#define ALERT_DURATION_MS 2000
#define SEISMIC_DURATION_MS 500
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_fp) {
        fprintf(log_fp, "%s - Seismic event detected!\n", timestamp);
        fflush(log_fp);
    } else {
        fprintf(stderr, "Log file not open; event not logged.\n");
    }
}

static void alert_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    if (gpio == ALERT_PIN && level == 1) {
        if (gpioWrite(ALERT_PIN, 1) != 0) {
            fprintf(stderr, "Failed to set alert pin HIGH\n");
            return;
        }
        gpioDelay(ALERT_DURATION_MS * 1000);
        if (gpioWrite(ALERT_PIN, 0) != 0) {
            fprintf(stderr, "Failed to set alert pin LOW\n");
        }
    }
}

static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    static uint32_t last_tick = 0;
    uint32_t now = gpioTick();

    if (last_tick == 0) {
        last_tick = now;
        return;
    }

    uint32_t diff = now - last_tick;
    last_tick = now;

    if (level == 1) {
        if (diff >= SEISMIC_DURATION_MS * 1000) {
            log_event();
            alert_callback(ALERT_PIN, 1, 0);
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SENSOR_1_PIN mode\n");
        goto cleanup;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SENSOR_2_PIN mode\n");
        goto cleanup;
    }
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set ALERT_PIN mode\n");
        goto cleanup;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on SENSOR_1_PIN\n");
        goto cleanup;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on SENSOR_2_PIN\n");
        goto cleanup;
    }

    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise ALERT_PIN LOW\n");
        goto cleanup;
    }

    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register callback for SENSOR_1_PIN\n");
        goto cleanup;
    }
    if (gpioSetAlertFuncEx(SENSOR_2_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register callback for SENSOR_2_PIN\n");
        goto cleanup;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler\n");
        goto cleanup;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(POLL_DELAY_US);
    }

cleanup:
    printf("\nShutting down...\n");
    gpioWrite(ALERT_PIN, 0);
    gpioSetAlertFuncEx(SENSOR_1_PIN, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_2_PIN, NULL, NULL);
    gpioTerminate();
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    return EXIT_SUCCESS;
}

