#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <string.h>

/* ADXRS290 register addresses (upper nibble = register address, lower nibble = read/write bit) */
#define ADXRS290_REG_RATE_XL  0x02
#define ADXRS290_REG_RATE_XH  0x03
#define ADXRS290_REG_RATE_YL  0x04
#define ADXRS290_REG_RATE_YH  0x05

/* SPI configuration */
#define SPI_CHANNEL 0          /* CE0 on GPIO8 */
#define SPI_SPEED   1000000    /* 1 MHz */
#define SPI_FLAGS   0          /* Mode 0, active-low CE */

/* LED output pin */
#define LED_PIN 17

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Angular velocity threshold (deg/s) */
#define THRESHOLD 20.0

/* Sensitivity: 200 LSB/deg/s */
#define SENSITIVITY 200.0

/* Data structure for storing timestamped angular velocity readings */
typedef struct {
    struct timespec timestamp;
    float angular_velocity;
} gyro_data_t;

/* Circular buffer structure */
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* Global state */
static int spi_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t running = 1;

/* Function prototypes */
static int init_gpio(void);
static int init_spi(void);
static int read_gyro_data(int16_t *x_rate, int16_t *y_rate);
static float convert_to_degrees_per_second(int16_t raw_data);
static void add_to_buffer(circular_buffer_t *buffer, struct timespec ts, float angular_velocity);
static void check_threshold(float angular_velocity);
static void cleanup(void);
static void signal_handler(int signal);

/* Initialize pigpio and configure LED pin */
static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED pin %d as output\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED pin %d to LOW\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Initialize SPI */
static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed (handle=%d)\n", spi_handle);
        return -1;
    }
    return 0;
}

/* Read 16-bit angular rate data from the ADXRS290 over SPI.
   Returns 0 on success, -1 on SPI transfer failure. */
static int read_gyro_data(int16_t *x_rate, int16_t *y_rate) {
    char tx_buf[4];
    char rx_buf[4];

    /* Read X-axis low byte (0x02) */
    tx_buf[0] = (char)(ADXRS290_REG_RATE_XL | 0x80); /* MSB = 1 for read */
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;
    tx_buf[3] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 4) != 4) {
        fprintf(stderr, "Error: SPI transfer failed for X-axis low byte\n");
        return -1;
    }

    /* Read X-axis high byte (0x03) */
    tx_buf[0] = (char)(ADXRS290_REG_RATE_XH | 0x80);
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;
    tx_buf[3] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 4) != 4) {
        fprintf(stderr, "Error: SPI transfer failed for X-axis high byte\n");
        return -1;
    }

    /* Read Y-axis low byte (0x04) */
    tx_buf[0] = (char)(ADXRS290_REG_RATE_YL | 0x80);
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;
    tx_buf[3] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 4) != 4) {
        fprintf(stderr, "Error: SPI transfer failed for Y-axis low byte\n");
        return -1;
    }

    /* Read Y-axis high byte (0x05) */
    tx_buf[0] = (char)(ADXRS290_REG_RATE_YH | 0x80);
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;
    tx_buf[3] = 0x00;

