#define SPI_SPEED   1000000    /* 1 MHz */
#define SPI_FLAGS   0          /* Mode 0, active-low CE */

/* LED output pin */
#define LED_PIN 17

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Angular velocity threshold (deg/s) */
#define THRESHOLD 20.0

/* Sensitivity: 200 LSB/deg/s */
#define SENSITIVITY 200.0

/* Data structure for storing timestamped angular velocity readings */
typedef struct {
    struct timespec timestamp;
    float angular_velocity;
} gyro_data_t;

/* Circular buffer structure */
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* Global state */
