        return -1;
    }

    /* Read Y-axis high byte (0x05) */
    tx_buf[0] = (char)(ADXRS290_REG_RATE_YH | 0x80);
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;
    tx_buf[3] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 4) != 4) {
