    *x_rate = (int16_t)(((uint16_t)(uint8_t)rx_buf[1] << 8) | (uint8_t)rx_buf[0]);
    *y_rate = (int16_t)(((uint16_t)(uint8_t)rx_buf[3] << 8) | (uint8_t)rx_buf[2]);

