#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27
#define PWM_RANGE 255
#define PWM_FREQ 100
#define MIN_DURATION 1
#define MAX_DURATION 3600

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_lamp(int pin, int duration) {
    if (gpioSetMode(pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pin);
        return -1;
    }
    if (gpioSetPWMfrequency(pin, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d\n", pin);
        return -1;
    }
    if (gpioSetPWMrange(pin, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d\n", pin);
        return -1;
    }
    if (gpioPWM(pin, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM failed to turn off pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int fade_lamp(int pin, int duration) {
    int steps = PWM_RANGE;
    int step_delay_us = (duration * 1000000) / steps;
    if (step_delay_us < 1) step_delay_us = 1;

    for (int i = 0; i <= steps && g_running; i++) {
        int duty = PWM_RANGE - i;
        if (gpioPWM(pin, duty) < 0) {
            fprintf(stderr, "Error: gpioPWM failed for pin %d at step %d\n", pin, i);
            return -1;
        }
        usleep(step_delay_us);
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_seconds>\n", argv[0]);
        fprintf(stderr, "  duration_seconds must be an integer between %d and %d\n",
                MIN_DURATION, MAX_DURATION);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long duration = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || duration < MIN_DURATION || duration > MAX_DURATION) {
        fprintf(stderr, "Error: duration must be an integer between %d and %d\n",
                MIN_DURATION, MAX_DURATION);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator\n");
    printf("Lamps: GPIO%d, GPIO%d, GPIO%d\n", LAMP1_PIN, LAMP2_PIN, LAMP3_PIN);
    printf("Fade duration: %ld seconds\n", duration);
    printf("Press Ctrl+C to abort.\n");

    if (set_lamp(LAMP1_PIN, duration) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_lamp(LAMP2_PIN, duration) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_lamp(LAMP3_PIN, duration) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fade_lamp(LAMP1_PIN, duration) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (!g_running) {
        fprintf(stderr, "Interrupted during lamp 1 fade.\n");
        gpioPWM(LAMP1_PIN, 0);
        gpioPWM(LAMP2_PIN, 0);
        gpioPWM(LAMP3_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fade_lamp(LAMP2_PIN, duration) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (!g_running) {
        fprintf(stderr, "Interrupted during lamp 2 fade.\n");
        gpioPWM(LAMP1_PIN, 0);
        gpioPWM(LAMP2_PIN, 0);
        gpioPWM(LAMP3_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fade_lamp(LAMP3_PIN, duration) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (!g_running) {
        fprintf(stderr, "Interrupted during lamp 3 fade.\n");
        gpioPWM(LAMP1_PIN, 0);
        gpioPWM(LAMP2_PIN, 0);
        gpioPWM(LAMP3_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sunset complete.\n");
    gpioPWM(LAMP1_PIN, 0);
    gpioPWM(LAMP2_PIN, 0);
    gpioPWM(LAMP3_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

