#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define RED_PIN   17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define AMBER_PIN  24

#define RED_TIME   10
#define YELLOW_TIME 2
#define GREEN_TIME 10
#define AMBER_TIME 3

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_seconds(unsigned int seconds) {
    while (seconds > 0 && running) {
        unsigned int chunk = (seconds > 1) ? 1 : seconds;
        sleep(chunk);
        seconds -= chunk;
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};
    const unsigned int pins[4] = {RED_PIN, YELLOW_PIN, GREEN_PIN, AMBER_PIN};
    const char *chipname = "gpiochip4";
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", chipname, strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
