#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define LOG_FILE "touch_relay.log"

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5D
#define MPR121_TOUCH_THRESHOLD 0x41
#define MPR121_RELEASE_THRESHOLD 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_AFE_CONFIG0 0x5C
#define MPR121_SOFTRESET 0x80
#define MPR121_RUN_MODE 0x5E

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(log_file);
}

static int mpr121_write(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C write error: reg=0x%02X, value=0x%02X, rc=%d", reg, value, rc);
        log_message(buf);
    }
    return rc;
}

static int mpr121_read(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C read error: reg=0x%02X, rc=%d", reg, rc);
        log_message(buf);
    }
    return rc;
}

static int mpr121_init(int handle) {
    /* Soft reset */
    if (mpr121_write(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(2000); /* 2 ms */

    /* Stop mode */
    if (mpr121_write(handle, MPR121_RUN_MODE, 0x00) < 0) return -1;
    gpioDelay(1000);

    /* Enable electrode 0 */
    if (mpr121_write(handle, MPR121_ELECTRODE_CONFIG, 0x01) < 0) return -1;
    gpioDelay(1000);

    /* Touch threshold = 10 */
    if (mpr121_write(handle, MPR121_TOUCH_THRESHOLD, 0x0A) < 0) return -1;

    /* Release threshold = 8 */
    if (mpr121_write(handle, MPR121_RELEASE_THRESHOLD, 0x08) < 0) return -1;

    /* Debounce: 3 touches, 3 releases */
    if (mpr121_write(handle, MPR121_DEBOUNCE, 0x21) < 0) return -1;

    /* AFE charge time = 0.5 us */
    if (mpr121_write(handle, MPR121_AFE_CONFIG0, 0x0D) < 0) return -1;

    /* Run mode */
    if (mpr121_write(handle, MPR121_RUN_MODE, 0x0D) < 0) return -1;
    gpioDelay(1000);

    return 0;
}

static int read_touch_status(int handle) {
    int lsb = mpr121_read(handle, MPR121_TOUCHSTATUS_L);
    if (lsb < 0) return -1;
    int msb = mpr121_read(handle, MPR121_TOUCHSTATUS_H);
    if (msb < 0) return -1;
    return (msb << 8) | lsb;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_message("Program started");

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        log_message("Failed to set relay GPIO mode");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Failed to open I2C device at 0x%02X: %d", MPR121_ADDR, i2c_handle);
        log_message(buf);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init(i2c_handle) < 0) {
        log_message("MPR121 initialization failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_message("MPR121 initialized successfully");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int relay_state = 0;
    int last_touch = 0;

    while (!terminate) {
        int touch = read_touch_status(i2c_handle);
        if (touch < 0) {
            log_message("Error reading touch status");
            gpioDelay(100000);
            continue;
        }

        int electrode0 = (touch >> 0) & 1;

        if (electrode0 && !last_touch) {
            relay_state = !relay_state;
            if (gpioWrite(RELAY_GPIO, relay_state) < 0) {
                log_message("Failed to write relay GPIO");
            } else {
                char buf[128];
                snprintf(buf, sizeof(buf), "Relay toggled to %s", relay_state ? "ON" : "OFF");
                log_message(buf);
            }
        }

        last_touch = electrode0;
        gpioDelay(10000); /* 10 ms */
    }

    log_message("Shutting down");
    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

