#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23
#define DEBOUNCE_READS 3
#define DEBOUNCE_DELAY_MS 50
#define POLL_INTERVAL_MS 100
#define LOG_FILE "flame_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (flame_line) gpiod_line_release(flame_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        fprintf(stderr, "Failed to get flame sensor line %d: %s\n", FLAME_SENSOR_PIN, strerror(errno));
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line %d: %s\n", BUZZER_PIN, strerror(errno));
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line %d: %s\n", LED_PIN, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request flame line as input: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request buzzer line as output: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_flame_sensor(void) {
    int val = gpiod_line_get_value(flame_line);
    if (val < 0) {
        fprintf(stderr, "Failed to read flame sensor: %s\n", strerror(errno));
        return -1;
    }
    return val;
}

static void activate_alarm(void) {
    gpiod_line_set_value(buzzer_line, 1);
    gpiod_line_set_value(led_line, 1);
}

static void deactivate_alarm(void) {
    gpiod_line_set_value(buzzer_line, 0);
    gpiod_line_set_value(led_line, 0);
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    printf("Fire alarm system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int flame_detected = 0;
        for (int i = 0; i < DEBOUNCE_READS; i++) {
            int val = read_flame_sensor();
            if (val < 0) {
                cleanup();
                return 1;
            }
            if (val == 0) flame_detected = 1;
            if (i < DEBOUNCE_READS - 1) usleep(DEBOUNCE_DELAY_MS * 1000);
        }

        if (flame_detected) {
            printf("Flame detected!\n");
            activate_alarm();
            log_event("Flame Detected");
            while (program_running) {
                int val = read_flame_sensor();
                if (val < 0) {
                    cleanup();
                    return 1;
                }
                if (val != 0) break;
                usleep(POLL_INTERVAL_MS * 1000);
            }
            deactivate_alarm();
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

