#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DISPENSE_DURATION_MS 1000
#define CYCLE_INTERVAL_S 5
#define HALF_DURATION_MS (DISPENSE_DURATION_MS / 2)

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_dispense(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return 1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return 1;
    }

    if (fprintf(fp, "%s - Solenoid 1 (GPIO%d): %d ms, Solenoid 2 (GPIO%d): %d ms\n",
                timestamp, solenoid1_pin, duration_ms, solenoid2_pin, duration_ms) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return 1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return 1;
    }

    return 0;
}

static int activate_solenoid(int pin, int duration_ms) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error activating solenoid on GPIO%d\n", pin);
        return 1;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error deactivating solenoid on GPIO%d\n", pin);
        return 1;
    }
    return 0;
}

static int dispense_cycle(void) {
    printf("Starting dispense cycle...\n");

    if (activate_solenoid(SOLENOID_1_PIN, HALF_DURATION_MS) != 0) {
        return 1;
    }

    if (activate_solenoid(SOLENOID_2_PIN, HALF_DURATION_MS) != 0) {
        return 1;
    }

    if (log_dispense(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION_MS) != 0) {
        fprintf(stderr, "Error logging dispense event\n");
        return 1;
    }

    printf("Dispense cycle complete.\n");
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(SOLENOID_1_PIN, 0) != 0 || gpioWrite(SOLENOID_2_PIN, 0) != 0) {
        fprintf(stderr, "Error initializing solenoids to OFF state\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        gpioWrite(SOLENOID_1_PIN, 0);
        gpioWrite(SOLENOID_2_PIN, 0);
        gpioTerminate();
        return 1;
    }

    printf("Pneumatic dispensing system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (dispense_cycle() != 0) {
            fprintf(stderr, "Error during dispense cycle\n");
            break;
        }

        if (running) {
            gpioDelay(CYCLE_INTERVAL_S * 1000000);
        }
    }

    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();
    printf("Pneumatic dispensing system stopped.\n");
    return 0;
}

