#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* Motor A */
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

/* Motor B */
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

/* L298N enable pins (PWM capable) */
#define MOTOR_A_ENABLE 24
#define MOTOR_B_ENABLE 25

/* PID parameters */
#define KP 1.0
#define KI 0.01
#define KD 0.1

/* Obstacle avoidance threshold */
#define OBSTACLE_THRESHOLD 20.0

/* PWM range for pigpio (0-255) */
#define PWM_RANGE 255

/* Control loop period in microseconds (50 ms) */
#define LOOP_PERIOD_US 50000

/* Global flag for graceful shutdown */
volatile sig_atomic_t program_running = 1;

/* Log file pointer */
FILE *log_file = NULL;

/* Function prototypes */
void signal_handler(int signal);
int initialize_gpio(void);
void cleanup_gpio(void);
void set_motor_speed(int motor, int speed);
float pid_control(float error, float *integral, float *previous_error);
void obstacle_avoidance(float distance, int *motor_a_speed, int *motor_b_speed);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);

/* Signal handler for graceful shutdown */
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Initialize GPIO pins */
int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    /* Motor A pins */
    if (gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_A_FORWARD);
        return -1;
    }
    if (gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_A_BACKWARD);
        return -1;
    }

    /* Motor B pins */
    if (gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_B_FORWARD);
        return -1;
    }
    if (gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_B_BACKWARD);
        return -1;
    }

    /* L298N enable pins (PWM capable) */
    if (gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_A_ENABLE);
        return -1;
    }
    if (gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_B_ENABLE);
        return -1;
    }

    /* Ensure motors are stopped initially */
    set_motor_speed(0, 0);
    set_motor_speed(1, 0);

    return 0;
}

/* Cleanup GPIO pins */
void cleanup_gpio(void) {
    /* Stop motors */
    set_motor_speed(0, 0);
    set_motor_speed(1, 0);

    /* Set pins to input (safe state) */
    gpioSetMode(MOTOR_A_FORWARD, PI_INPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_INPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_INPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_INPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_INPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_INPUT);

    gpioTerminate();
}

/* Set motor speed (0-255) */
void set_motor_speed(int motor, int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;

    if (motor == 0) {
        /* Motor A: forward = GPIO17, backward = GPIO18 */
        if (speed > 0) {
            gpioWrite(MOTOR_A_FORWARD, 1);
            gpioWrite(MOTOR_A_BACKWARD, 0);
        } else {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 1);
        }
        gpioPWM(MOTOR_A_ENABLE, speed);
    } else if (motor == 1) {
        /* Motor B: forward = GPIO22, backward = GPIO23 */
        if (speed > 0) {
            gpioWrite(MOTOR_B_FORWARD, 1);
            gpioWrite(MOTOR_B_BACKWARD, 0);
        } else {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 1);
        }
        gpioPWM(MOTOR_B_ENABLE, speed);
    }
}

/* PID control: returns motor speed (0-255) */
float pid_control(float error, float *integral, float *previous_error) {
    float derivative = error - *previous_error;
    *integral += error;
    float output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;

    /* Clamp output to [-255, 255] */
    if (output < -PWM_RANGE) output = -PWM_RANGE;
    if (output > PWM_RANGE) output = PWM_RANGE;

    return output;
}

/* Obstacle avoidance: reverse both motors at 50% speed if distance < threshold */
void obstacle_avoidance(float distance, int *motor_a_speed, int *motor_b_speed) {
    if (distance < OBSTACLE_THRESHOLD) {
        *motor_a_speed = -PWM_RANGE / 2;
        *motor_b_speed = -PWM_RANGE / 2;
    } else {
        *motor_a_speed = 0;
        *motor_b_speed = 0;
    }
}

/* Log data to file */
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f, %d, %d\n",
            timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

int main(void) {
    /* Seed random number generator */
    srand(time(NULL));

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        return 1;
    }

    /* Open log file */
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    /* Register signal handler for SIGINT */
    signal(SIGINT, signal_handler);

    float integral_a = 0.0, previous_error_a = 0.0;
    float integral_b = 0.0, previous_error_b = 0.0;

    printf("Self-balancing robot started. Press Ctrl+C to exit.\n");

    while (program_running) {
        /* Simulate tilt error (random between -10.0 and 10.0) */
        float tilt_error = (float)(rand() % 21 - 10);

        /* Simulate ultrasonic distance (random between 2.0 and 400.0) */
        float distance = (float)(rand() % 4001 + 200) / 10.0;

        /* PID control for Motor A */
        int motor_a_speed = (int)pid_control(tilt_error, &integral_a, &previous_error_a);

        /* PID control for Motor B */
        int motor_b_speed = (int)pid_control(tilt_error, &integral_b, &previous_error_b);

        /* Obstacle avoidance */
        obstacle_avoidance(distance, &motor_a_speed, &motor_b_speed);

        /* Set motor speeds */
        set_motor_speed(0, motor_a_speed);
        set_motor_speed(1, motor_b_speed);

        /* Log data */
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        /* Delay for 50 ms */
        gpioDelay(LOOP_PERIOD_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

