            gpioWrite(MOTOR_B_FORWARD, 1);
            gpioWrite(MOTOR_B_BACKWARD, 0);
        } else {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 1);
        }
        gpioPWM(MOTOR_B_ENABLE, speed);
    }
}

/* PID control: returns motor speed (0-255) */
float pid_control(float error, float *integral, float *previous_error) {
    float derivative = error - *previous_error;
    *integral += error;
    float output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;

    /* Clamp output to [-255, 255] */
    if (output < -PWM_RANGE) output = -PWM_RANGE;
    if (output > PWM_RANGE) output = PWM_RANGE;

    return output;
}

/* Obstacle avoidance: reverse both motors at 50% speed if distance < threshold */
void obstacle_avoidance(float distance, int *motor_a_speed, int *motor_b_speed) {
    if (distance < OBSTACLE_THRESHOLD) {
        *motor_a_speed = -PWM_RANGE / 2;
        *motor_b_speed = -PWM_RANGE / 2;
    } else {
        *motor_a_speed = 0;
        *motor_b_speed = 0;
    }
}

/* Log data to file */
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f, %d, %d\n",
            timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

int main(void) {
    /* Seed random number generator */
    srand(time(NULL));

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        return 1;
    }

    /* Open log file */
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    /* Register signal handler for SIGINT */
    signal(SIGINT, signal_handler);

    float integral_a = 0.0, previous_error_a = 0.0;
    float integral_b = 0.0, previous_error_b = 0.0;

    printf("Self-balancing robot started. Press Ctrl+C to exit.\n");

    while (program_running) {
        /* Simulate tilt error (random between -10.0 and 10.0) */
        float tilt_error = (float)(rand() % 21 - 10);

        /* Simulate ultrasonic distance (random between 2.0 and 400.0) */
        float distance = (float)(rand() % 4001 + 200) / 10.0;

        /* PID control for Motor A */
        int motor_a_speed = (int)pid_control(tilt_error, &integral_a, &previous_error_a);

        /* PID control for Motor B */
        int motor_b_speed = (int)pid_control(tilt_error, &integral_b, &previous_error_b);

        /* Obstacle avoidance */
        obstacle_avoidance(distance, &motor_a_speed, &motor_b_speed);

        /* Set motor speeds */
        set_motor_speed(0, motor_a_speed);
        set_motor_speed(1, motor_b_speed);

        /* Log data */
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        /* Delay for 50 ms */
        gpioDelay(LOOP_PERIOD_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

