#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000  /* 50 ms in microseconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int relay_state = 0;
    int ret;

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", ret);
        fprintf(stderr, "Ensure pigpiod is not running and you have root privileges.\n");
        return EXIT_FAILURE;
    }

    /* Configure touch sensor pin as input with internal pull-down */
    ret = gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input (code %d).\n", TOUCH_SENSOR_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);
    if (ret != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO%d (code %d).\n", TOUCH_SENSOR_PIN, ret);
        /* Non-fatal: continue anyway */
    }

    /* Configure relay pin as output and ensure it starts OFF */
    ret = gpioSetMode(RELAY_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output (code %d).\n", RELAY_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioWrite(RELAY_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to initialise relay state on GPIO%d (code %d).\n", RELAY_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Light Switch running. Touch sensor on GPIO%d, relay on GPIO%d.\n", TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int touch = gpioRead(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d (code %d).\n", TOUCH_SENSOR_PIN, touch);
            break;
        }

        if (touch == 1) {
            relay_state = !relay_state;
            ret = gpioWrite(RELAY_PIN, relay_state);
            if (ret != 0) {
                fprintf(stderr, "Error: failed to write GPIO%d (code %d).\n", RELAY_PIN, ret);
                break;
            }

            printf("Touch detected. Relay %s.\n", relay_state ? "ON" : "OFF");

            /* Debounce: wait 50 ms before allowing next touch */
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        gpioDelay(10000);  /* 10 ms polling interval */
    }

    /* Clean shutdown: ensure relay is OFF and release pigpio resources */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

