/*
 * mood_light.c — Raspberry Pi 3 Model B+
 * Ambient-noise-driven RGB mood light using pigpio software PWM.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lpigpio -lasound
 * Run:    sudo ./mood_light [sensitivity]
 *
 * Hardware:
 *   Common-cathode RGB LED on GPIO17 (R), GPIO18 (G), GPIO27 (B).
 *   Each pin has a 330 Ω current-limiting resistor.
 *   GPIO12 (PWM0) is the hardware PWM0 pin; pigpio uses software PWM on GPIO12.
 *
 * ALSA capture (when available):
 *   Default capture device, 8000 Hz, 16-bit, 1 channel, period 1024 frames.
 *   RMS of the 16-bit signed little-endian samples is mapped to RGB.
 *
 * Simulated sine-wave amplitude when ALSA is unavailable:
 *   A sine wave is generated and used as the audio input.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define DEFAULT_SENSITIVITY 1.0f
#define DEFAULT_SAMPLE_RATE 8000
#define DEFAULT_PERIOD_SIZE 1024
#define DEFAULT_AMPLITUDE   1.0f

#define PWM_RANGE 255
#define PWM_FREQ  1000

#define SINE_WAVE_AMPLITUDE 1.0f
#define SINE_WAVE_FREQUENCY 1.0f

#define STATUS_INTERVAL_US 10000

#define ALSA_AVAILABLE 1

#if ALSA_AVAILABLE
#include <alsa/asoundlib.h>
#endif

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void set_rgb(int r, int g, int b)
{
    if (r < 0) r = 0; if (r > 255) r = 255;
    if (g < 0) g = 0; if (g > 255) g = 255;
    if (b < 0) b = 0; if (b > 255) b = 255;
    gpioPWM(RED_PIN,   r);
    gpioPWM(GREEN_PIN, g);
    gpioPWM(BLUE_PIN,  b);
}

static void set_rgb_from_amplitude(float amplitude)
{
    /*
     * Non-linear mapping: low amplitude -> cool blue, high amplitude -> warm red.
     * The exponent controls the transition rate.
     */
    float exponent = 2.0f;
    float cool = 1.0f - (amplitude * amplitude) / 2.0f;
    float warm = amplitude * amplitude / 2.0f;

    int r = (int)(warm * 255.0f);
    int g = (int)(cool * 255.0f);
    int b = (int)(cool * 255.0f);

    if (r < 0) r = 0; if (r > 255) r = 255;
    if (g < 0) g = 0; if (g > 255) g = 255;
    if (b < 0) b = 0; if (b > 255) b = 255;

    gpioPWM(RED_PIN,   r);
    gpioPWM(GREEN_PIN, g);
    gpioPWM(BLUE_PIN,  b);
}

