static float calculate_rms(const short *buffer, int frames)
{
    if (frames <= 0) return 0.0f;
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        double v = (double)buffer[i];
        sum_sq += v * v;
    }
    return (float)sqrt((double)sum_sq / frames);
}

static void sine_wave_callback(snd_pcm_sframes_t nframes, void *userdata)
{
    (void)userdata;
    if (nframes <= 0) return;
    short *buf = (short *)snd_pcm_get_buffer_pointer(h_sine);
    if (!buf) return;
    for (int i = 0; i < nframes; i++) {
        float val = SINE_WAVE_AMPLITUDE * sinf(2.0f * M_PI * SINE_WAVE_FREQUENCY * (float)i / DEFAULT_SAMPLE_RATE);
        buf[i] = (short)(val * 32767.0f);
    }
}

