#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int tcs34725_write(uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write to register 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int tcs34725_read_block(uint8_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error: I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != len) {
        fprintf(stderr, "Error: I2C read from register 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int tcs34725_init(void) {
    if (tcs34725_write(TCS34725_ENABLE, 0x03) != 0) return -1;
    if (tcs34725_write(TCS34725_ATIME, 0xD5) != 0) return -1;
    return 0;
}

static int tcs34725_read(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buf[8];
    if (tcs34725_read_block(TCS34725_CDATA, buf, 8) != 0) return -1;
    *clear = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    *red   = (uint16_t)buf[2] | ((uint16_t)buf[3] << 8);
    *green = (uint16_t)buf[4] | ((uint16_t)buf[5] << 8);
    *blue  = (uint16_t)buf[6] | ((uint16_t)buf[7] << 8);
    return 0;
}

static void cleanup(void) {
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (tcs34725_init() != 0) {
        fprintf(stderr, "Error: TCS34725 initialisation failed\n");
        cleanup();
        return 1;
    }

    fp = fopen("color_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open color_data.csv\n");
        cleanup();
        return 1;
    }
    fprintf(fp, "timestamp,clear,red,green,blue\n");

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        uint16_t clear, red, green, blue;
        if (tcs34725_read(&clear, &red, &green, &blue) != 0) {
            clear = 0; red = 0; green = 0; blue = 0;
        }

        time_t now = time(NULL);
        fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)now, clear, red, green, blue);
        fflush(fp);

        gpioDelay(500000);
    }

    cleanup();
    return 0;
}

