#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define CHIP_NAME "gpiochip0"
#define RELAY_PINS {17, 27, 22, 23}  /* BCM GPIO numbers */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_seconds(unsigned int seconds) {
    while (seconds > 0 && running) {
        unsigned int chunk = (seconds > 1) ? 1 : seconds;
        sleep(chunk);
        seconds -= chunk;
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int pin;
    int ret;

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = NULL;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get and request each relay line as output, initially low (relay off) */
    for (int i = 0; i < NUM_RELAYS; i++) {
        pin = RELAY_PINS[i];
        lines[i] = gpiod_chip_get_line(chip, pin);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", pin);
            goto cleanup;
        }
        ret = gpiod_line_request_output(lines[i], "sunrise-sunset", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output\n", pin);
            goto cleanup;
        }
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        goto cleanup;
    }

    printf("Sunrise/sunset lighting simulator started. Press Ctrl+C to exit.\n");

    /* Sunrise: 1 hour of increasing brightness */
    printf("Sunrise phase (1 hour)...\n");
    for (int i = 0; i < 3600 && running; i += 5) {
        for (int j = 0; j < NUM_RELAYS; j++) {
            gpiod_line_set_value(lines[j], 0);  /* Relay ON (active low) */
        }
        sleep_seconds(5);
    }

    if (!running) goto cleanup;

    /* Daytime: 6 hours of full brightness */
    printf("Daytime phase (6 hours)...\n");
    for (int i = 0; i < 3600 * 6 && running; i += 5) {
        for (int j = 0; j < NUM_RELAYS; j++) {
            gpiod_line_set_value(lines[j], 0);  /* Relay ON */
        }
        sleep_seconds(5);
    }

    if (!running) goto cleanup;

    /* Sunset: 1 hour of decreasing brightness */
    printf("Sunset phase (1 hour)...\n");
    for (int i = 0; i < 3600 && running; i += 5) {
        for (int j = 0; j < NUM_RELAYS; j++) {
            gpiod_line_set_value(lines[j], 1);  /* Relay OFF (active low) */
        }
        sleep_seconds(5);
    }

    if (!running) goto cleanup;

    /* Nighttime: 14.4 hours of off */
    printf("Nighttime phase (14.4 hours)...\n");
    for (int i = 0; i < 3600 * 14 && running; i += 5) {
        for (int j = 0; j < NUM_RELAYS; j++) {
            gpiod_line_set_value(lines[j], 1);  /* Relay OFF */
        }
        sleep_seconds(5);
    }

    /* Turn off all relays before exiting */
    printf("Shutting down...\n");
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_set_value(lines[i], 1);  /* Relay OFF */
    }

cleanup:
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return EXIT_SUCCESS;
}

