#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTION_SENSOR_GPIO 17
#define VIDEO_DURATION 5
#define DEBOUNCE_DELAY_MS 200
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"
#define TIMESTAMP_LEN 20
#define CMD_LEN 512

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y%m%d_%H%M%S", timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int record_video(const char *timestamp) {
    char filename[256];
    snprintf(filename, sizeof(filename), "%s%s.h264", VIDEO_DIR, timestamp);
    char command[CMD_LEN];
    snprintf(command, sizeof(command),
             "raspivid -o %s -t %d -w 1280 -h 720 -fps 30",
             filename, VIDEO_DURATION * 1000);
    int ret = system(command);
    if (ret == -1) {
        fprintf(stderr, "Error: system() failed to execute raspivid.\n");
        return -1;
    }
    if (!WIFEXITED(ret) || WEXITSTATUS(ret) != 0) {
        fprintf(stderr, "Error: raspivid exited with status %d.\n", WEXITSTATUS(ret));
        return -1;
    }
    printf("Video saved to %s\n", filename);
    return 0;
}

static int log_motion(const char *timestamp) {
    if (log_fp == NULL) {
        fprintf(stderr, "Error: log file not open.\n");
        return -1;
    }
    if (fprintf(log_fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }
    if (fflush(log_fp) != 0) {
        fprintf(stderr, "Error: failed to flush log file.\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    if (gpioSetMode(MOTION_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", MOTION_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(MOTION_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO %d.\n", MOTION_SENSOR_GPIO);
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", MOTION_SENSOR_GPIO);

    uint32_t last_trigger_tick = 0;
    int first_trigger = 1;

    while (running) {
        int level = gpioRead(MOTION_SENSOR_GPIO);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO %d.\n", MOTION_SENSOR_GPIO);
            break;
        }

        if (level == 0) {
            uint32_t now = gpioTick();
            if (first_trigger || (now - last_trigger_tick) >= (uint32_t)(DEBOUNCE_DELAY_MS * 1000)) {
                char timestamp[TIMESTAMP_LEN];
                if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                    printf("Motion detected at %s\n", timestamp);
                    if (record_video(timestamp) == 0) {
                        if (log_motion(timestamp) != 0) {
                            fprintf(stderr, "Warning: failed to log motion event.\n");
                        }
                    } else {
                        fprintf(stderr, "Warning: video recording failed.\n");
                    }
                } else {
                    fprintf(stderr, "Warning: failed to generate timestamp.\n");
                }
                last_trigger_tick = now;
                first_trigger = 0;
            }
        }
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
    return 0;
}

