#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* MPU-6050 I2C address (AD0 pin low) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43

/* Sensitivity scale factor for ±250°/s full-scale range */
#define GYRO_SCALE 131.0f

/* I2C bus on Raspberry Pi 4 Model B */
#define I2C_BUS 1

/* Log file path */
#define LOG_FILE "gyro_log.csv"

/* Re-initialization retries */
#define REINIT_RETRIES 3

/* Sampling interval in microseconds (100 Hz) */
#define SAMPLE_INTERVAL_US 10000

/* Global state */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Initialize MPU-6050: wake, configure sample rate, configure range   */
/* ------------------------------------------------------------------ */
static int init_mpu6050(void)
{
    int rc;

    /* Wake up the MPU-6050 (clear sleep bit) */
    rc = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
    if (rc < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %s\n", pigpio_error(rc));
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Set sample rate divider to 125 Hz (1 kHz / (1 + 125) = 8 Hz) */
    rc = i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x00);
    if (rc < 0) {
        fprintf(stderr, "Error writing SMPLRT_DIV: %s\n", pigpio_error(rc));
        return -1;
    }

    /* Set gyroscope full-scale range to ±250°/s (FS_SEL = 0) */
    rc = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00);
    if (rc < 0) {
        fprintf(stderr, "Error writing GYRO_CONFIG: %s\n", pigpio_error(rc));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read gyroscope data (6 bytes from GYRO_XOUT_H)                      */
/* ------------------------------------------------------------------ */
static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];
    int rc;

    rc = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading gyro data (rc=%d): %s\n",
                rc, rc < 0 ? pigpio_error(rc) : "short read");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    *y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    *z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw 16-bit values to degrees per second                    */
/* ------------------------------------------------------------------ */
static void convert_to_dps(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                           float *x_dps, float *y_dps, float *z_dps)
{
    *x_dps = (float)raw_x / GYRO_SCALE;
    *y_dps = (float)raw_y / GYRO_SCALE;
    *z_dps = (float)raw_z / GYRO_SCALE;
}

/* ------------------------------------------------------------------ */
/* Log one data row to CSV                                             */
/* ------------------------------------------------------------------ */
static void log_data(float x_dps, float y_dps, float z_dps)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[40];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x_dps, y_dps, z_dps);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Re-initialize the MPU-6050 after a read failure                     */
/* ------------------------------------------------------------------ */
static int reinit_mpu6050(void)
{
    int retries = REINIT_RETRIES;
    int rc;

    while (retries > 0) {
        fprintf(stderr, "Attempting re-initialization (%d retries left)...\n",
                retries - 1);

        rc = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
        if (rc < 0) {
            fprintf(stderr, "Re-init PWR_MGMT_1 failed: %s\n",
                    pigpio_error(rc));
            retries--;
            gpioDelay(100000);
            continue;
        }

        gpioDelay(10000); /* 10 ms settle */

        rc = i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x00);
        if (rc < 0) {
            fprintf(stderr, "Re-init SMPLRT_DIV failed: %s\n",
                    pigpio_error(rc));
            retries--;
            gpioDelay(100000);
            continue;
        }

        rc = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00);
        if (rc < 0) {
            fprintf(stderr, "Re-init GYRO_CONFIG failed: %s\n",
                    pigpio_error(rc));
            retries--;
            gpioDelay(100000);
            continue;
        }

        fprintf(stderr, "Re-initialization successful.\n");
        return 0;
    }

    fprintf(stderr, "Failed to re-initialize MPU-6050 after %d retries.\n",
            REINIT_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t raw_x, raw_y, raw_z;
    float x_dps, y_dps, z_dps;
    int consecutive_errors = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, MPU6050_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_mpu6050() < 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
        fflush(log_file);
    }

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Gyroscope monitoring started. Logging to %s\n", LOG_FILE);

    /* Main sampling loop */
    while (!terminate) {
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            convert_to_dps(raw_x, raw_y, raw_z, &x_dps, &y_dps, &z_dps);
            log_data(x_dps, y_dps, z_dps);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            if (consecutive_errors >= 3) {
                fprintf(stderr, "Too many consecutive read failures; "
                                "attempting re-initialization...\n");
                if (reinit_mpu6050() < 0) {
                    fprintf(stderr, "Re-initialization failed; "
                                    "continuing to retry...\n");
                }
                consecutive_errors = 0;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

