#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <string.h>

#define ZONE1_PIN 4
#define ZONE2_PIN 17
#define ZONE3_PIN 27
#define ZONE4_PIN 22

#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static const int relay_pins[4] = {ZONE1_PIN, ZONE2_PIN, ZONE3_PIN, ZONE4_PIN};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialize GPIO %d HIGH.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_moisture_sensor(void) {
    return rand() % 101;
}

static int control_relay(int zone, int moisture_level) {
    int pin = relay_pins[zone - 1];
    int state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;

    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d.\n", pin);
        return -1;
    }
    return state;
}

static int log_data(int moisture_level, int relay_state, int zone) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed.\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Zone %d, Moisture: %d, Relay: %s\n",
                timestamp, zone, moisture_level,
                relay_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: failed to flush log file.\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    for (int i = 0; i < 4; i++) {
        gpioWrite(relay_pins[i], 1);
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < 4; i++) {
            int moisture_level = read_moisture_sensor();
            int relay_state = control_relay(i + 1, moisture_level);

            if (relay_state < 0) {
