#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ALARM_GPIO 27
#define FREEFALL_THRESHOLD 0.2f
#define FREEFALL_DURATION_MS 500
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "freefall.log"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int adxl345_init(int handle) {
    if (i2cWriteByteData(handle, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing DATA_FORMAT register\n");
        return -1;
    }
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing POWER_CTL register\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, buf, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x / 256.0f;
    *y = (float)raw_y / 256.0f;
    *z = (float)raw_z / 256.0f;
    return 0;
}

static int detect_freefall(int handle) {
    float x, y, z;
    if (read_acceleration(handle, &x, &y, &z) < 0) return 0;
    if (fabsf(x) < FREEFALL_THRESHOLD &&
        fabsf(y) < FREEFALL_THRESHOLD &&
        fabsf(z) < FREEFALL_THRESHOLD) {
        gpioWrite(ALARM_GPIO, 1);
        gpioDelay(FREEFALL_DURATION_MS * 1000);
        gpioWrite(ALARM_GPIO, 0);
        return 1;
    }
    return 0;
}

static void log_freefall(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (adxl345_init(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    while (running) {
        if (detect_freefall(i2c_handle)) {
            float x, y, z;
            if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
                log_freefall(x, y, z);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }
    gpioWrite(ALARM_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

