#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>

#define TRIG_PIN 4
#define ECHO_PIN 18
#define TRIG_PULSE_US 10
#define MEASURE_INTERVAL_US 200000
#define ECHO_TIMEOUT_US 100000
#define MAX_DISTANCE_US 23200
#define LOG_FILE "distance_log.txt"
#define TIMESTAMP_BUF_SIZE 64

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick = 0;
static volatile int g_echo_received = 0;
static pthread_mutex_t g_mutex;

static void echo_rising(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    if (level == 1) {
        g_start_tick = tick;
        g_echo_received = 0;
    }
}

static void echo_falling(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    if (level == 0) {
        g_end_tick = tick;
        g_echo_received = 1;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    gpioSetAlertFuncEx(TRIG_PIN, NULL, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    if (fclose(stdout) == EOF) perror("fclose stdout");
    if (fclose(stderr) == EOF) perror("fclose stderr");
    if (fclose(stdout) == EOF) perror("fclose stdout");
    gpioTerminate();
    pthread_mutex_destroy(&g_mutex);
    exit(0);
}

static void get_timestamp_ns(char *buf, size_t len) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        snprintf(buf, len, "0");
        return;
    }
    snprintf(buf, len, "%ld", (long)ts.tv_sec * 1000000000L + ts.tv_nsec);
}

static void log_distance(const char *timestamp, float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    fprintf(fp, "%s,%.2f\n", timestamp, distance);
    if (fclose(fp) == EOF) perror("fclose log");
}

int main(void) {
    if (pthread_mutex_init(&g_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex init failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        pthread_mutex_destroy(&g_mutex);
        return 1;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIG_PIN mode\n");
        gpioTerminate();
        pthread_mutex_destroy(&g_mutex);
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        gpioTerminate();
        pthread_mutex_destroy(&g_mutex);
        return 1;
    }

    if (gpioWrite(TRIG_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write TRIG_PIN low\n");
        gpioTerminate();
        pthread_mutex_destroy(&g_mutex);
        return 1;
    }
    gpioDelay(50000);

    if (gpioSetAlertFuncEx(TRIG_PIN, echo_rising, NULL) != 0) {
        fprintf(stderr, "Failed to set TRIG_PIN alert\n");
        gpioTerminate();
        pthread_mutex_destroy(&g_mutex);
        return 1;
    }
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_falling, NULL) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN alert\n");
        gpioSetAlertFuncEx(TRIG_PIN, NULL, NULL);
        gpioTerminate();
        pthread_mutex_destroy(&g_mutex);
        return 1;
    }

    signal(SIGINT, signal_handler);

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (1) {
        char timestamp[TIMESTAMP_BUF_SIZE];
        get_timestamp_ns(timestamp, sizeof(timestamp));

        if (gpioWrite(TRIG_PIN, 1) != 0) {
            fprintf(stderr, "Failed to trigger TRIG_PIN high\n");
            log_distance(timestamp, -1.0f);
            gpioDelay(MEASURE_INTERVAL_US);
            continue;
        }
        gpioDelay(TRIG_PULSE_US);
        if (gpioWrite(TRIG_PIN, 0) != 0) {
            fprintf(stderr, "Failed to trigger TRIG_PIN low\n");
            log_distance(timestamp, -1.0f);
            gpioDelay(MEASURE_INTERVAL_US);
            continue;
        }

        uint32_t start_tick, end_tick;
        int received;
        pthread_mutex_lock(&g_mutex);
        start_tick = g_start_tick;
        end_tick = g_end_tick;
        received = g_echo_received;
        pthread_mutex_unlock(&g_mutex);

        if (!received) {
            fprintf(stderr, "Timeout: no echo received within %d us\n", ECHO_TIMEOUT_US);
            log_distance(timestamp, -1.0f);
            gpioDelay(MEASURE_INTERVAL_US);
            continue;
        }

        uint32_t pulse_us;
        if (start_tick >= end_tick) {
            pulse_us = (0xFFFFFFFF - start_tick + end_tick + 1);
        } else {
            pulse_us = end_tick - start_tick;
        }

        if (pulse_us > MAX_DISTANCE_US) {
            fprintf(stderr, "Distance out of range: %u us\n", pulse_us);
            log_distance(timestamp, -1.0f);
            gpioDelay(MEASURE_INTERVAL_US);
            continue;
        }

        float distance_cm = (float)pulse_us / 58.0f;
        log_distance(timestamp, distance_cm);
        printf("%s: Distance = %.2f cm\n", timestamp, distance_cm);

        gpioDelay(MEASURE_INTERVAL_US);
    }

    return 0;
}

