            pulse_us = (0xFFFFFFFF - start_tick + end_tick + 1);
        } else {
            pulse_us = end_tick - start_tick;
        }

        if (pulse_us > MAX_DISTANCE_US) {
            fprintf(stderr, "Distance out of range: %u us\n", pulse_us);
            log_distance(timestamp, -1.0f);
            gpioDelay(MEASURE_INTERVAL_US);
            continue;
        }

        float distance_cm = (float)pulse_us / 58.0f;
        log_distance(timestamp, distance_cm);
        printf("%s: Distance = %.2f cm\n", timestamp, distance_cm);

        gpioDelay(MEASURE_INTERVAL_US);
    }

    return 0;
}

