#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x18
#define BUZZER_GPIO 17

#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28

#define DEFAULT_FREEFALL_THRESHOLD 0.2f
#define DEFAULT_IMPACT_THRESHOLD 1.5f
#define DEFAULT_I2C_RETRIES 3
#define DEFAULT_I2C_RETRY_DELAY_US 10000
#define BUZZER_DURATION_US 1000000
#define SAMPLE_DELAY_US 10000

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    for (int i = 0; i < DEFAULT_I2C_RETRIES; i++) {
        int rc = i2cWriteByteData(i2c_handle, reg, value);
        if (rc == 0) return 0;
        fprintf(stderr, "I2C write reg 0x%02X failed (attempt %d): %d\n", reg, i + 1, rc);
        gpioDelay(DEFAULT_I2C_RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    for (int i = 0; i < DEFAULT_I2C_RETRIES; i++) {
        int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
        if (rc == (int)len) return 0;
        fprintf(stderr, "I2C read block reg 0x%02X failed (attempt %d): %d\n", reg, i + 1, rc);
        gpioDelay(DEFAULT_I2C_RETRY_DELAY_US);
    }
    return -1;
}

static int init_lis3dh(void) {
    if (i2c_write_reg(CTRL_REG1, 0x77) != 0) return -1;
    if (i2c_write_reg(CTRL_REG4, 0x00) != 0) return -1;
    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(OUT_X_L, buf, 6) != 0) return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;
    return 0;
}

static void activate_buzzer(void) {
    gpioWrite(BUZZER_GPIO, 1);
    gpioDelay(BUZZER_DURATION_US);
    gpioWrite(BUZZER_GPIO, 0);
}

int main(int argc, char *argv[]) {
    float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    float impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    if (argc > 1) freefall_threshold = strtof(argv[1], NULL);
    if (argc > 2) impact_threshold = strtof(argv[2], NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lis3dh() != 0) {
        fprintf(stderr, "Failed to initialize LIS3DH\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Fall detection started. Freefall: %.2f g, Impact: %.2f g\n", freefall_threshold, impact_threshold);

    while (running) {
        float x, y, z;
        if (read_acceleration(&x, &y, &z) != 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        float magnitude = sqrtf(x * x + y * y + z * z);

        if (magnitude < freefall_threshold) {
            printf("Freefall detected!\n");
        } else if (magnitude > impact_threshold) {
            printf("Impact detected!\n");
            activate_buzzer();
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(BUZZER_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

