#define LEFT_SENSOR_PIN    4
#define CENTER_SENSOR_PIN  17
#define RIGHT_SENSOR_PIN   27
#define ALERT_LED_PIN      22

#define BUFFER_SIZE        5
#define POLL_INTERVAL_MS   10
#define ALERT_DURATION_MS  2000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

typedef struct {
    int left;
    int center;
    int right;
} sensor_data_t;

static sensor_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void add_to_buffer(int left, int center, int right) {
    circular_buffer[buffer_index].left = left;
    circular_buffer[buffer_index].center = center;
    circular_buffer[buffer_index].right = right;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static int read_sensor(struct gpiod_line *line, int pin) {
    int ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return ret;
}

static void line_following_control(int left, int center, int right) {
    if (center == 0) {
        printf("Center sensor detected line. Moving forward.\n");
        // Placeholder: move forward
    } else if (left == 0) {
        printf("Left sensor detected line. Turning left.\n");
        // Placeholder: turn left
    } else if (right == 0) {
        printf("Right sensor detected line. Turning right.\n");
        // Placeholder: turn right
    } else {
        printf("No line detected. Stopping.\n");
        // Placeholder: stop
    }
}

static void alert_system(struct gpiod_line *alert_line) {
    printf("Alert triggered! Driving alert LED HIGH for %d ms.\n", ALERT_DURATION_MS);
    if (gpiod_line_set_value(alert_line, 1) < 0) {
        fprintf(stderr, "Error setting alert LED HIGH: %s\n", strerror(errno));
    }
    usleep(ALERT_DURATION_MS * 1000);
    if (gpiod_line_set_value(alert_line, 0) < 0) {
        fprintf(stderr, "Error setting alert LED LOW: %s\n", strerror(errno));
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL;
    struct gpiod_line *center_line = NULL;
    struct gpiod_line *right_line = NULL;
    struct gpiod_line *alert_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    alert_line = gpiod_chip_get_line(chip, ALERT_LED_PIN);
    if (!left_line || !center_line || !right_line || !alert_line) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(left_line, "line-following") < 0) {
        fprintf(stderr, "Error requesting left sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(center_line, "line-following") < 0) {
        fprintf(stderr, "Error requesting center sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(right_line, "line-following") < 0) {
        fprintf(stderr, "Error requesting right sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(alert_line, "line-following", 0) < 0) {
        fprintf(stderr, "Error requesting alert LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int left = read_sensor(left_line, LEFT_SENSOR_PIN);
        int center = read_sensor(center_line, CENTER_SENSOR_PIN);
        int right = read_sensor(right_line, RIGHT_SENSOR_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        add_to_buffer(left, center, right);
        line_following_control(left, center, right);

        int no_line_count = 0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            if (circular_buffer[i].center == 1) {
                no_line_count = 0;
            } else {
                no_line_count++;
                if (no_line_count >= 5) {
                    alert_system(alert_line);
                    no_line_count = 0;
                    break;
                }
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (alert_line) {
        gpiod_line_set_value(alert_line, 0);
        gpiod_line_release(alert_line);
    }
    if (right_line) gpiod_line_release(right_line);
    if (center_line) gpiod_line_release(center_line);
    if (left_line) gpiod_line_release(left_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

