#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7210_ADDR    0x30
#define SI7210_REG_DATA 0xC0
#define SI7210_REG_CTRL 0xC1
#define SI7210_CMD_START 0x01
#define SI7210_CMD_RESET 0x02
#define SI7210_RESET_MS  100
#define RELAY_GPIO       17
#define FIELD_THRESHOLD  5.0f
#define SAMPLE_MS        100
#define POLL_TIMEOUT_MS  50
#define LOG_FILE         "magnetic_events.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, msg);
    } else {
        fprintf(fp, "(unknown time): %s\n", msg);
    }
    fclose(fp);
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C write failed: reg=0x%02X val=0x%02X rc=%d", reg, val, rc);
        log_event(buf);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C read failed: reg=0x%02X rc=%d", reg, rc);
        log_event(buf);
    }
    return rc;
}

static int si7210_reset(int handle) {
    if (i2c_write_byte(handle, SI7210_REG_CTRL, SI7210_CMD_RESET) < 0) return -1;
    gpioDelay(SI7210_RESET_MS * 1000);
    return 0;
}

static int si7210_start_conversion(int handle) {
    return i2c_write_byte(handle, SI7210_REG_CTRL, SI7210_CMD_START);
}

static int si7210_wait_conversion(int handle) {
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        int v = i2c_read_byte(handle, SI7210_REG_CTRL);
        if (v < 0) return -1;
        if (v == 0x00) return 0;
        gpioDelay(1000);
    }
    return -1;
}

static int si7210_read_field(int handle, float *field_mT) {
    if (si7210_start_conversion(handle) < 0) return -1;
    if (si7210_wait_conversion(handle) < 0) return -1;
    int lsb = i2c_read_byte(handle, SI7210_REG_DATA);
    if (lsb < 0) return -1;
    int msb = i2c_read_byte(handle, SI7210_REG_DATA + 1);
    if (msb < 0) return -1;
    int16_t raw = (int16_t)((msb << 8) | lsb);
    *field_mT = (float)raw * 25.0f / 1000.0f;
    return 0;
}

static void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "gpioWrite failed: GPIO=%d state=%d", RELAY_GPIO, state);
        log_event(buf);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (g_i2c_handle < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "i2cOpen failed: bus=%d addr=0x%02X rc=%d", I2C_BUS, SI7210_ADDR, g_i2c_handle);
        log_event(buf);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si7210_reset(g_i2c_handle) < 0) {
        log_event("Si7210 reset failed");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        log_event("gpioSetMode failed for relay GPIO");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_relay(0);

    log_event("Program started");

    while (g_running) {
        float field_mT;
        if (si7210_read_field(g_i2c_handle, &field_mT) < 0) {
            log_event("Field read error");
            control_relay(0);
            gpioDelay(SAMPLE_MS * 1000);
            continue;
        }

        char buf[128];
        snprintf(buf, sizeof(buf), "Field: %.2f mT", field_mT);
        log_event(buf);

        if (field_mT > (FIELD_THRESHOLD * 100.0f)) {
            control_relay(1);
            snprintf(buf, sizeof(buf), "Threshold exceeded: %.2f mT, relay ON", field_mT);
        } else {
            control_relay(0);
            snprintf(buf, sizeof(buf), "Field: %.2f mT, relay OFF", field_mT);
        }
        log_event(buf);

        gpioDelay(SAMPLE_MS * 1000);
    }

    log_event("Shutting down");
    control_relay(0);
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

