#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define PORT 5000
#define RELAY_GPIO 18
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;

static void log_event(const char *event) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
    if (client_fd >= 0) {
        shutdown(client_fd, SHUT_RDWR);
        close(client_fd);
        client_fd = -1;
    }
}

static int setup_socket(void) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket");
        return -1;
    }
    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(fd);
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);
    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(fd);
        return -1;
    }
    if (listen(fd, 3) < 0) {
        perror("listen");
        close(fd);
        return -1;
    }
    return fd;
}

static void cleanup(void) {
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        log_event("Server shutting down.");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    server_fd = setup_socket();
    if (server_fd < 0) {
        cleanup();
        return 1;
    }

    log_event("Server started.");

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("accept");
            continue;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        printf("Connection from %s:%d\n", client_ip, ntohs(client_addr.sin_port));

        char buffer[BUFFER_SIZE];
        ssize_t bytes = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes < 0) {
            perror("recv");
            close(client_fd);
            client_fd = -1;
            continue;
        }
        if (bytes == 0) {
            printf("Client disconnected without sending data\n");
            close(client_fd);
            client_fd = -1;
            continue;
        }
        buffer[bytes] = '\0';

        char *cmd = strtok(buffer, " \r\n");
        if (!cmd) {
            log_event("Invalid command: empty");
            const char *resp = "Invalid command\n";
            send(client_fd, resp, strlen(resp), 0);
            close(client_fd);
            client_fd = -1;
            continue;
        }

        char lower_cmd[16];
        int len = strlen(cmd);
        if (len >= (int)sizeof(lower_cmd)) len = (int)sizeof(lower_cmd) - 1;
        for (int i = 0; i < len; i++) lower_cmd[i] = (char)tolower((unsigned char)cmd[i]);
        lower_cmd[len] = '\0';

        if (strcmp(lower_cmd, "on") == 0) {
            gpioWrite(RELAY_GPIO, 1);
            log_event("Relay turned ON");
            const char *resp = "Relay ON\n";
            send(client_fd, resp, strlen(resp), 0);
        } else if (strcmp(lower_cmd, "off") == 0) {
            gpioWrite(RELAY_GPIO, 0);
            log_event("Relay turned OFF");
            const char *resp = "Relay OFF\n";
            send(client_fd, resp, strlen(resp), 0);
        } else {
            log_event("Invalid command");
            const char *resp = "Invalid command\n";
            send(client_fd, resp, strlen(resp), 0);
        }

        close(client_fd);
        client_fd = -1;
    }

    cleanup();
    return 0;
}

