#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define SENSOR1_ADDR     0x08
#define SENSOR2_ADDR     0x09
#define GPIO_RELAY       18
#define FLOW_THRESHOLD   5.0f
#define SCALE_FACTOR     (1.0f / 1500.0f)
#define POLL_DELAY_US    100000
#define START_MEAS_CMD   {0x36, 0x08}
#define CRC_POLY         0x31
#define CRC_INIT         0xFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle1 = -1;
static int g_i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int init_sensor(int handle) {
    if (i2cWriteDevice(handle, (char *)START_MEAS_CMD, 2) != 0) {
        fprintf(stderr, "Error: failed to send start-measurement command to handle %d\n", handle);
        return -1;
    }
    return 0;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t buf[3];
    int bytes_read = i2cReadDevice(handle, (char *)buf, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error: I2C read failed on handle %d (read %d bytes)\n", handle, bytes_read);
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on handle %d (calc 0x%02X, got 0x%02X)\n",
                handle, crc8(buf, 2), buf[2]);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw * SCALE_FACTOR;
    return 0;
}

static void log_flow_rates(float flow1, float flow2) {
    FILE *fp = fopen("flow_log.txt", "a");
    if (!fp) {
        perror("Error opening flow_log.txt");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            timestamp, ts.tv_nsec / 1000000, flow1, flow2);
    fflush(fp);
    fclose(fp);
}

static void control_relay(float flow1, float flow2) {
    int target = (flow1 < FLOW_THRESHOLD || flow2 < FLOW_THRESHOLD) ? 1 : 0;
    if (gpioWrite(GPIO_RELAY, target) != 0) {
        fprintf(stderr, "Warning: gpioWrite failed on relay pin %d\n", GPIO_RELAY);
    }
}

static void cleanup(void) {
    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_handle1 < 0) {
        fprintf(stderr, "Error: failed to open I2C device for sensor 1 (addr 0x%02X): %d\n",
                SENSOR1_ADDR, g_i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_handle2 < 0) {
        fprintf(stderr, "Error: failed to open I2C device for sensor 2 (addr 0x%02X): %d\n",
                SENSOR2_ADDR, g_i2c_handle2);
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_handle1) != 0 || init_sensor(g_i2c_handle2) != 0) {
        fprintf(stderr, "Error: sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", GPIO_RELAY);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(GPIO_RELAY, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed to de-energize relay\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring flow rates... (Ctrl+C to exit)\n");

    while (g_running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = read_flow_rate(g_i2c_handle1, &flow1);
        int ok2 = read_flow_rate(g_i2c_handle2, &flow2);

        if (ok1 == 0 && ok2 == 0) {
            log_flow_rates(flow1, flow2);
            control_relay(flow1, flow2);
        } else {
            fprintf(stderr, "Warning: read error (s1=%d, s2=%d), skipping cycle\n", ok1, ok2);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

