#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>
#include <stdbool.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN   22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24

/* ---- Timing constants (microseconds unless noted) ---- */
#define POLL_INTERVAL_US  200000   /* 200 ms */
#define MOTOR_RUN_US      5000000  /* 5 s   */
#define DRY_THRESHOLD     3        /* consecutive dry polls before re-trigger */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe: only set flag                   */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Motor helpers                                                       */
/* ------------------------------------------------------------------ */
static int motor_stop(void)
{
    int rc = 0;
    if (gpioWrite(MOTOR_ENA_PIN, 0) < 0) {
        syslog(LOG_WARNING, "gpioWrite(ENA, 0) failed");
        rc = -1;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        syslog(LOG_WARNING, "gpioWrite(IN1, 0) failed");
        rc = -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_WARNING, "gpioWrite(IN2, 0) failed");
        rc = -1;
    }
    return rc;
}

static int motor_close_window(void)
{
    if (gpioWrite(MOTOR_ENA_PIN, 1) < 0) {
        syslog(LOG_WARNING, "gpioWrite(ENA, 1) failed");
        return -1;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
        syslog(LOG_WARNING, "gpioWrite(IN1, 1) failed");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_WARNING, "gpioWrite(IN2, 0) failed");
        return -1;
    }
    syslog(LOG_INFO, "Motor started: closing window");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Rain sensor read                                                     */
/* Returns 1 if rain detected (DO LOW), 0 if dry (DO HIGH), -1 on error */
/* ------------------------------------------------------------------ */
static int read_rain_sensor(void)
{
    int v = gpioRead(RAIN_SENSOR_PIN);
    if (v < 0) {
        syslog(LOG_WARNING, "gpioRead(%d) failed", RAIN_SENSOR_PIN);
        return -1;
    }
    return (v == 0) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "pigpio initialised");

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, INPUT) failed", RAIN_SENSOR_PIN);
        goto fail;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(%d, UP) failed", RAIN_SENSOR_PIN);
        goto fail;
    }
    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode for motor pins failed");
        goto fail;
    }
    if (motor_stop() < 0) {
        syslog(LOG_ERR, "Failed to initialise motor GPIOs to safe state");
        goto fail;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed");
        goto fail;
    }

    syslog(LOG_INFO, "Rain-actuated window controller started");

    int dry_count = 0;
    bool motor_active = false;

    while (g_running) {
        int rain = read_rain_sensor();
        if (rain < 0) {
            /* Sensor read error — back off briefly and retry */
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (rain) {
            dry_count = 0;
            if (!motor_active) {
                syslog(LOG_INFO, "Rain detected — window will close");
                if (motor_close_window() == 0) {
                    motor_active = true;
                }
            }
        } else {
            dry_count++;
            if (dry_count >= DRY_THRESHOLD && motor_active) {
                syslog(LOG_INFO, "Dry for %d polls — stopping motor", DRY_THRESHOLD);
                if (motor_stop() == 0) {
                    motor_active = false;
                }
            }
        }

        if (motor_active) {
            /* Run motor for 5 s, checking g_running every 100 ms */
            for (int i = 0; i < 50 && g_running; i++) {
                gpioDelay(100000);
            }
            if (g_running) {
                if (motor_stop() == 0) {
                    motor_active = false;
                    syslog(LOG_INFO, "Motor stopped");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    syslog(LOG_INFO, "Shutting down — stopping motor");
    motor_stop();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;

fail:
    motor_stop();
    gpioTerminate();
    closelog();
    return EXIT_FAILURE;
}

