#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define LOCK_PULSE_US  2000
#define UNLOCK_PULSE_US 1000

#define DEBOUNCE_US    50000   /* 50 ms debounce */
#define POLL_US        10000   /* 10 ms poll interval */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int set_servo_pulse(int pin, int pulse_us)
{
    if (gpioServo(pin, pulse_us) != 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed\n", pin, pulse_us);
        return -1;
    }
    return 0;
}

static void unlock_door(void)
{
    printf("Unlocking door...\n");
    fflush(stdout);
    if (set_servo_pulse(SERVO_PIN, UNLOCK_PULSE_US) != 0)
        fprintf(stderr, "Warning: failed to set unlock pulse\n");
}

static void lock_door(void)
{
    printf("Locking door...\n");
    fflush(stdout);
    if (set_servo_pulse(SERVO_PIN, LOCK_PULSE_US) != 0)
        fprintf(stderr, "Warning: failed to set lock pulse\n");
}

static void shutdown_servo(void)
{
    /* Stop sending pulses so the servo returns to its idle position. */
    if (gpioServo(SERVO_PIN, 0) != 0)
        fprintf(stderr, "Warning: failed to stop servo pulses\n");
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with pull-ups. */
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(LOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(UNLOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(LOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(UNLOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control ready.\n");
    printf("  Lock button : GPIO %d\n", LOCK_BUTTON);
    printf("  Unlock button: GPIO %d\n", UNLOCK_BUTTON);
    printf("  Servo pin: GPIO %d\n", SERVO_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    int last_lock_state = 0;
    int last_unlock_state = 0;

    while (g_running) {
        int lock_state = gpioRead(LOCK_BUTTON);
        int unlock_state = gpioRead(UNLOCK_BUTTON);

        if (lock_state < 0 || unlock_state < 0) {
            fprintf(stderr, "Error: gpioRead failed (lock=%d, unlock=%d)\n",
                    lock_state, unlock_state);
            break;
        }

        /* Detect rising edge: button pressed (low) after release. */
        if (lock_state == 0 && last_lock_state == 1) {
            usleep(DEBOUNCE_US);
            if (gpioRead(LOCK_BUTTON) == 0) {
                lock_door();
                last_lock_state = 1;
            }
        }

        /* Detect rising edge: button pressed (low) after release. */
        if (unlock_state == 0 && last_unlock_state == 1) {
            usleep(DEBOUNCE_US);
            if (gpioRead(UNLOCK_BUTTON) == 0) {
                unlock_door();
                last_unlock_state = 1;
            }
        }

        last_lock_state = lock_state;
        last_unlock_state = unlock_state;

        usleep(POLL_US);
    }

    /* Clean shutdown: stop servo pulses and release pigpio. */
    shutdown_servo();
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

