#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN 4
#define FLOODLIGHT_PIN 17
#define LOG_FILE "security_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */
#define LIGHT_ON_DURATION_S 60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_event(const char *event_type)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - %s\n", timestamp, event_type) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int control_floodlight(int on)
{
    if (gpioWrite(FLOODLIGHT_PIN, on ? 1 : 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", FLOODLIGHT_PIN, on);
        return -1;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(PIR_PIN, PI_INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (control_floodlight(0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        control_floodlight(0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        control_floodlight(0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Security Light started. PIR=GPIO%d, Floodlight=GPIO%d\n",
           PIR_PIN, FLOODLIGHT_PIN);
    printf("Press Ctrl+C to exit.\n");

    int last_pir_state = gpioRead(PIR_PIN);
    if (last_pir_state < 0) {
        fprintf(stderr, "Initial gpioRead(PIR_PIN) failed\n");
        control_floodlight(0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int pir_state = gpioRead(PIR_PIN);
        if (pir_state < 0) {
            fprintf(stderr, "gpioRead(PIR_PIN) failed\n");
            break;
        }

        if (pir_state == 1 && last_pir_state == 0) {
            printf("Motion detected!\n");

            if (control_floodlight(1) < 0) {
                break;
            }

            if (log_event("Motion Detected") < 0) {
                break;
            }

            /* Keep floodlight on for LIGHT_ON_DURATION_S, checking g_running */
            for (int i = 0; i < LIGHT_ON_DURATION_S && g_running; i++) {
                gpioDelay(POLL_DELAY_US);
            }

            if (control_floodlight(0) < 0) {
                break;
            }

            if (log_event("Floodlight Turned Off") < 0) {
                break;
            }

            printf("Floodlight turned off.\n");
        }

        last_pir_state = pir_state;
        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    control_floodlight(0);
    gpioTerminate();
    printf("Smart Security Light stopped.\n");
    return EXIT_SUCCESS;
}

