#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR        0x5A
#define I2C_BUS            1
#define RELAY_GPIO         17
#define DEBOUNCE_MS        200
#define POLL_DELAY_US      10000

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS 0x00
#define MPR121_ECR         0x5E
#define MPR121_SOFTRESET   0x80
#define MPR121_MHD0        0x2B
#define MPR121_NHD0        0x2C
#define MPR121_NCL0        0x2D
#define MPR121_FDL0        0x2E
#define MPR121_DEBOUNCE    0x5B
#define MPR121_CONFIG1     0x5C
#define MPR121_CONFIG2     0x5D
#define MPR121_AUTO_CONFIG0 0x71
#define MPR121_AUTO_CONFIG1 0x72
#define MPR121_AUTO_CONFIG2 0x73
#define MPR121_AUTO_CONFIG3 0x74
#define MPR121_USL         0x75
#define MPR121_LSL         0x76
#define MPR121_TL          0x77

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int mpr121_write(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to MPR121 reg 0x%02X (pigpio rc=%d)\n",
                value, reg, rc);
    }
    return rc;
}

static int mpr121_read(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading MPR121 reg 0x%02X (pigpio rc=%d)\n", reg, rc);
    }
    return rc;
}

static int mpr121_init(int handle) {
    /* Soft reset */
    if (mpr121_write(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000); /* 10 ms settle after reset */

    /* Baseline filtering: MHD=16, NHD=16, NCL=2, FDL=4 */
    if (mpr121_write(handle, MPR121_MHD0, 0x10) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHD0, 0x10) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCL0, 0x02) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDL0, 0x04) < 0) return -1;

    /* Debounce: 3 samples for both touch and release */
    if (mpr121_write(handle, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* CONFIG1: FFI=6 samples, CDC=16 µA */
    if (mpr121_write(handle, MPR121_CONFIG1, 0x10) < 0) return -1;

    /* CONFIG2: CDT=0.5 µs, SFI=4 samples, ESI=4 ms */
    if (mpr121_write(handle, MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Auto-config: enable, USL=120, LSL=60, TL=90, 12 samples, 10 ms */
    if (mpr121_write(handle, MPR121_AUTO_CONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write(handle, MPR121_AUTO_CONFIG1, 0x0C) < 0) return -1;
    if (mpr121_write(handle, MPR121_AUTO_CONFIG2, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_AUTO_CONFIG3, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_USL, 0x78) < 0) return -1;
    if (mpr121_write(handle, MPR121_LSL, 0x48) < 0) return -1;
    if (mpr121_write(handle, MPR121_TL, 0x68) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking, no auto-config */
    if (mpr121_write(handle, MPR121_ECR, 0x8C) < 0) return -1;

    return 0;
}

static int read_touch_status(int handle) {
    int status = mpr121_read(handle, MPR121_TOUCHSTATUS);
    if (status < 0) return -1;
    return status & 0x0FFF;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X (pigpio rc=%d)\n",
                I2C_BUS, MPR121_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init(g_i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor may be absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    printf("MPR121 touch relay control started. Touch electrode 0 to toggle relay on GPIO%d.\n",
           RELAY_GPIO);
    printf("Press Ctrl+C to exit.\n");

    uint32_t last_touch_ms = 0;

    while (g_running) {
        int touch = read_touch_status(g_i2c_handle);
        if (touch < 0) {
            fprintf(stderr, "I2C read error, continuing...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        uint32_t now_ms = gpioTick() / 1000;

        if (touch & 0x0001) {
            if (now_ms - last_touch_ms >= DEBOUNCE_MS) {
                int relay = gpioRead(RELAY_GPIO);
                if (relay < 0) {
                    fprintf(stderr, "Error reading relay GPIO %d\n", RELAY_GPIO);
                } else {
                    relay = !relay;
                    if (gpioWrite(RELAY_GPIO, relay) < 0) {
                        fprintf(stderr, "Error writing relay GPIO %d\n", RELAY_GPIO);
                    } else {
                        printf("Relay toggled to %s\n", relay ? "ON" : "OFF");
                    }
                }
                last_touch_ms = now_ms;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

