static int read_touch_status(int handle) {
    int status = mpr121_read(handle, MPR121_TOUCHSTATUS);
    if (status < 0) return -1;
    return status & 0x0FFF;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X (pigpio rc=%d)\n",
                I2C_BUS, MPR121_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init(g_i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor may be absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    printf("MPR121 touch relay control started. Touch electrode 0 to toggle relay on GPIO%d.\n",
           RELAY_GPIO);
    printf("Press Ctrl+C to exit.\n");

    uint32_t last_touch_ms = 0;

    while (g_running) {
        int touch = read_touch_status(g_i2c_handle);
        if (touch < 0) {
            fprintf(stderr, "I2C read error, continuing...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        uint32_t now_ms = gpioTick() / 1000;

        if (touch & 0x0001) {
            if (now_ms - last_touch_ms >= DEBOUNCE_MS) {
                int relay = gpioRead(RELAY_GPIO);
                if (relay < 0) {
                    fprintf(stderr, "Error reading relay GPIO %d\n", RELAY_GPIO);
                } else {
                    relay = !relay;
                    if (gpioWrite(RELAY_GPIO, relay) < 0) {
                        fprintf(stderr, "Error writing relay GPIO %d\n", RELAY_GPIO);
                    } else {
                        printf("Relay toggled to %s\n", relay ? "ON" : "OFF");
                    }
                }
                last_touch_ms = now_ms;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

