#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <stdarg.h>
#include <gpiod.h>

#define PORT 5000
#define SERVO_PIN 17
#define PIR_PIN 4
#define SERVO_FREQ 50
#define SERVO_PERIOD_US (1000000 / SERVO_FREQ)
#define SERVO_PULSE_MIN_US 1000
#define SERVO_PULSE_MAX_US 2000
#define LOG_FILE "security.log"
#define BUFFER_SIZE 1024

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;

static void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    char buffer[BUFFER_SIZE];
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);
    syslog(LOG_INFO, "%s", buffer);
    if (log_file) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
        fprintf(log_file, "%s: %s\n", timestamp, buffer);
        fflush(log_file);
    }
}

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
    if (client_fd >= 0) {
        shutdown(client_fd, SHUT_RDWR);
        close(client_fd);
        client_fd = -1;
    }
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_message("Invalid servo angle: %d", angle);
        return -1;
    }
    int pulse_width = SERVO_PULSE_MIN_US +
        (int)(((float)angle / 180.0) * (SERVO_PULSE_MAX_US - SERVO_PULSE_MIN_US));
    int on_time = pulse_width / SERVO_PERIOD_US;
    int off_time = SERVO_PERIOD_US - on_time;
    if (gpiod_line_set_value(servo_line, 1) < 0) {
        log_message("Failed to set servo line high");
        return -1;
    }
    usleep(on_time * SERVO_PERIOD_US);
    if (gpiod_line_set_value(servo_line, 0) < 0) {
        log_message("Failed to set servo line low");
        return -1;
    }
    usleep(off_time * SERVO_PERIOD_US);
    return 0;
}

static void *servo_thread(void *arg) {
    (void)arg;
    while (running) {
        set_servo_angle(90);
        sleep(1);
    }
    return NULL;
}

static void cleanup(void) {
    if (servo_line) {
        gpiod_line_set_value(servo_line, 0);
        gpiod_line_release(servo_line);
        servo_line = NULL;
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    closelog();
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        closelog();
        return 1;
    }
    log_message("Starting security system");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message("Failed to set signal handlers");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        log_message("Failed to open gpiochip4");
        cleanup();
        return 1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_message("Failed to get servo line");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        log_message("Failed to request servo line as output");
        cleanup();
        return 1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message("Failed to get PIR line");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_input(pir_line, "pir") < 0) {
        log_message("Failed to request PIR line as input");
        cleanup();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message("Failed to create socket");
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message("Failed to set socket option");
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message("Failed to bind socket");
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        log_message("Failed to listen on socket");
        cleanup();
        return 1;
    }

    log_message("Listening on port %d", PORT);

    pthread_t servo_thread_id;
    if (pthread_create(&servo_thread_id, NULL, servo_thread, NULL) != 0) {
        log_message("Failed to create servo thread");
        cleanup();
        return 1;
    }

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (running) {
                log_message("Failed to accept connection");
            }
            continue;
        }
        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        log_message("Connection from %s", client_ip);

        char buffer[BUFFER_SIZE];
        ssize_t bytes_received;
        while ((bytes_received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0)) > 0) {
            buffer[bytes_received] = '\0';
            buffer[strcspn(buffer, "\r\n")] = '\0';
            if (strcmp(buffer, "PIR") == 0) {
                int pir_value = gpiod_line_get_value(pir_line);
                if (pir_value < 0) {
                    log_message("Failed to read PIR sensor");
                    send(client_fd, "PIR:ERROR\n", 10, 0);
                } else {
                    char response[32];
                    snprintf(response, sizeof(response), "PIR:%d\n", pir_value);
                    send(client_fd, response, strlen(response), 0);
                }
            } else if (strncmp(buffer, "SERVO ", 6) == 0) {
                int angle = atoi(buffer + 6);
                if (set_servo_angle(angle) == 0) {
                    char response[32];
                    snprintf(response, sizeof(response), "SERVO:%d\n", angle);
                    send(client_fd, response, strlen(response), 0);
                }
            } else {
                log_message("Invalid command: %s", buffer);
                send(client_fd, "ERROR\n", 6, 0);
            }
        }
        if (bytes_received < 0) {
            log_message("Error receiving data");
        }
        close(client_fd);
        client_fd = -1;
    }

    pthread_join(servo_thread_id, NULL);
    log_message("Shutting down security system");
    cleanup();
    return 0;
}

