#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define BH1750_ONE_TIME_HIGH_RES 0x20
#define CONVERSION_DELAY_US 120000
#define SAMPLE_INTERVAL_US 2000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, BH1750_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_lux(float *lux_out) {
    if (i2cWriteByte(i2c_handle, BH1750_ONE_TIME_HIGH_RES) < 0) {
        fprintf(stderr, "Error writing measurement command to BH1750\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from BH1750 (read %d bytes)\n", bytes_read);
        return -1;
    }

    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        fprintf(stderr, "Error writing to relay GPIO %d\n", RELAY_GPIO);
    }
}

static void log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s, %.2f\n", timestamp, lux);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    control_relay(0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return 1;
    }
    control_relay(0);

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen("grow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Grow light control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float lux;
        if (read_lux(&lux) == 0) {
            log_data(lux);
            if (lux < LUX_THRESHOLD) {
                control_relay(1);
                printf("Lux: %.2f, Light ON\n", lux);
            } else {
                control_relay(0);
                printf("Lux: %.2f, Light OFF\n", lux);
            }
        } else {
            fprintf(stderr, "Error reading lux value. Retrying in 2 seconds.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

