#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>
#include <getopt.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define HX711_DOUT_PIN  23
#define HX711_SCK_PIN   24
#define SOLENOID_PIN    25

#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE     1.0
#define DEFAULT_DURATION  200
#define DEFAULT_TARE_READINGS 10
#define DEFAULT_READINGS  5
#define TARE_DELAY_MS     100
#define POLL_INTERVAL_MS  500
#define MAX_READY_WAIT_MS 1000
#define MAX_READY_RETRIES 3

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = {
        .tv_sec = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

static int wait_dout_low(struct gpiod_line *dout, int timeout_ms) {
    int elapsed = 0;
    while (gpiod_line_get_value(dout) == 1) {
        if (elapsed >= timeout_ms) return -1;
        sleep_ms(1);
        elapsed++;
    }
    return 0;
}

static int hx711_read(struct gpiod_line *dout, struct gpiod_line *sck, int32_t *out) {
    if (wait_dout_low(dout, MAX_READY_WAIT_MS) != 0) {
        syslog(LOG_ERR, "HX711: DOUT did not go LOW within %d ms", MAX_READY_WAIT_MS);
        return -1;
    }

    uint32_t raw = 0;
    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck, 1) < 0) return -1;
        sleep_ms(1);
        raw <<= 1;
        int bit = gpiod_line_get_value(dout);
        if (bit < 0) return -1;
        if (bit) raw |= 1;
        if (gpiod_line_set_value(sck, 0) < 0) return -1;
        sleep_ms(1);
    }

    /* 25th pulse: select Channel A / Gain 128 */
    if (gpiod_line_set_value(sck, 1) < 0) return -1;
    sleep_ms(1);
    if (gpiod_line_set_value(sck, 0) < 0) return -1;
    sleep_ms(1);

    /* Convert 24-bit two's complement to signed 32-bit */
    if (raw & 0x800000) raw |= 0xFF000000;
    *out = (int32_t)raw;
    return 0;
}

static double calculate_weight(int32_t raw, double offset, double scale) {
    return (double)(raw - offset) / scale;
}

static void control_solenoid(struct gpiod_line *solenoid, int duration_ms) {
    if (gpiod_line_set_value(solenoid, 1) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid HIGH: %s", strerror(errno));
        return;
    }
    sleep_ms(duration_ms);
    if (gpiod_line_set_value(solenoid, 0) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid LOW: %s", strerror(errno));
    }
}

int main(int argc, char *argv[]) {
    double threshold = DEFAULT_THRESHOLD;
    double scale = DEFAULT_SCALE;
    int duration = DEFAULT_DURATION;
    int tare_readings = DEFAULT_TARE_READINGS;
    int readings = DEFAULT_READINGS;

    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:r:")) != -1) {
        switch (opt) {
            case 't': threshold = atof(optarg); break;
            case 's': scale = atof(optarg); break;
            case 'd': duration = atoi(optarg); break;
            case 'r': readings = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_grams] [-s scale_factor] [-d duration_ms] [-r readings_per_cycle]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("solenoid_control", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *dout = gpiod_chip_get_line(chip, HX711_DOUT_PIN);
    struct gpiod_line *sck  = gpiod_chip_get_line(chip, HX711_SCK_PIN);
    struct gpiod_line *solenoid = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!dout || !sck || !solenoid) {
        syslog(LOG_ERR, "Failed to get GPIO lines: %s", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(dout, "hx711_dout") < 0 ||
        gpiod_line_request_output(sck, "hx711_sck", 0) < 0 ||
        gpiod_line_request_output(solenoid, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO lines: %s", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Solenoid control started: threshold=%.1f g, scale=%.2f, duration=%d ms, tare=%d readings, cycle=%d readings", threshold, scale, duration, tare_readings, readings);

    double tare_offset = 0.0;
    int tare_ok = 0;
    for (int attempt = 0; attempt < tare_readings; attempt++) {
        int32_t raw;
        if (hx711_read(dout, sck, &raw) == 0) {
            tare_offset += (double)raw;
            tare_ok++;
            syslog(LOG_INFO, "Tare reading %d/%d: raw=%d", attempt + 1, tare_readings, raw);
        } else {
            syslog(LOG_ERR, "Tare read %d/%d failed", attempt + 1, tare_readings);
        }
        sleep_ms(TARE_DELAY_MS);
    }
    if (tare_ok == 0) {
        syslog(LOG_ERR, "All tare readings failed; aborting");
        gpiod_line_release(dout);
        gpiod_line_release(sck);
        gpiod_line_release(solenoid);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }
    tare_offset /= tare_ok;
    syslog(LOG_INFO, "Tare offset: %.0f", tare_offset);

    while (program_running) {
        double total = 0.0;
        int valid = 0;
        for (int i = 0; i < readings; i++) {
            int32_t raw;
            if (hx711_read(dout, sck, &raw) == 0) {
                total += (double)raw;
                valid++;
            } else {
                syslog(LOG_ERR, "Read %d/%d failed", i + 1, readings);
            }
            sleep_ms(10);
        }
        if (valid == 0) {
            syslog(LOG_ERR, "No valid readings this cycle; skipping control");
            sleep_ms(POLL_INTERVAL_MS);
            continue;
        }
        double avg = total / valid;
        double weight = calculate_weight((int32_t)avg, tare_offset, scale);
        syslog(LOG_INFO, "Weight: %.2f g (avg_raw=%.0f, offset=%.0f, scale=%.2f)", weight, avg, tare_offset, scale);

        if (weight > threshold) {
            control_solenoid(solenoid, duration);
            syslog(LOG_INFO, "Weight exceeded threshold (%.1f g > %.1f g); solenoid activated for %d ms", weight, threshold, duration);
        }

        sleep_ms(POLL_INTERVAL_MS);
    }

    syslog(LOG_INFO, "Shutting down");
    gpiod_line_set_value(solenoid, 0);
    gpiod_line_release(dout);
    gpiod_line_release(sck);
    gpiod_line_release(solenoid);
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

