/*
 * relay_controller.c — MQTT relay controller for Raspberry Pi 4 Model B
 *
 * Subscribes to home/lights/control and drives GPIO17 (BCM) via pigpio.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c \
 *       -lmosquitto -lpigpio -lrt
 *
 * Run:
 *   sudo ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT    1883
#define MQTT_CLIENT_ID      "relay_controller_1"
#define MQTT_TOPIC          "home/lights/control"
#define MQTT_QOS            0
#define GPIO_PIN            17          /* BCM 17, physical pin 11 */
#define KEEPALIVE_INTERVAL  60
#define RECONNECT_DELAY     5
#define MAX_PAYLOAD         256

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_message(int priority, const char *message)
{
    syslog(priority, "%s", message);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */

static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialise GPIO%d LOW", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void gpio_set_state(int state)
{
    if (gpioWrite(GPIO_PIN, state) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO%d", GPIO_PIN);
    }
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */

static void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;

    if (result == MOSQ_ERR_SUCCESS) {
        log_message(LOG_INFO, "Connected to MQTT broker");
        if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to topic %s", MQTT_TOPIC);
        } else {
            log_message(LOG_INFO, "Subscribed to topic home/lights/control");
        }
    } else {
        char buf[128];
        snprintf(buf, sizeof(buf), "MQTT connection error: %s", mosquitto_connack_string(result));
        syslog(LOG_ERR, "%s", buf);
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq;
    (void)userdata;

    if (rc == 0) {
        log_message(LOG_INFO, "Disconnected cleanly");
    } else {
        char buf[128];
        snprintf(buf, sizeof(buf), "Unexpected MQTT disconnect: %s", mosquitto_strerror(rc));
        syslog(LOG_ERR, "%s", buf);
    }
}

static void on_message(struct mosquitto *mosq, void *userdata,
                        const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (message->payloadlen > 0) {
        char payload[MAX_PAYLOAD];
        size_t len = message->payloadlen < MAX_PAYLOAD - 1
                     ? (size_t)message->payloadlen : MAX_PAYLOAD - 1;
        memcpy(payload, message->payload, len);
        payload[len] = '\0';

        if (strcmp(payload, "ON") == 0) {
            log_message(LOG_INFO, "Received ON command — energizing relay");
            gpio_set_state(1);
        } else if (strcmp(payload, "OFF") == 0) {
            log_message(LOG_INFO, "Received OFF command — de-energizing relay");
            gpio_set_state(0);
        } else {
            syslog(LOG_ERR, "Invalid payload '%s' — ignoring", payload);
        }
    } else {
        syslog(LOG_ERR, "Empty MQTT message received");
    }
}

