#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define SERVO1_POS 1000
#define SERVO2_POS 1500
#define SERVO3_POS 2000
#define SERVO4_POS 500
#define SERVO5_POS 2500

#define PWM_FREQUENCY 50
#define PWM_RANGE 20000

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {SERVO1_PIN, SERVO2_PIN, SERVO3_PIN, SERVO4_PIN, SERVO5_PIN};
    int positions[] = {SERVO1_POS, SERVO2_POS, SERVO3_POS, SERVO4_POS, SERVO5_POS};
    int num_servos = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_servos; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) != PWM_FREQUENCY) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != PWM_RANGE) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_servos; i++) {
        if (gpioServo(pins[i], positions[i]) != 0) {
            fprintf(stderr, "Error: failed to set servo position on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Servos moving to positions. Holding for 3 seconds...\n");
    gpioDelay(3000000);

    for (int i = 0; i < num_servos; i++) {
        gpioServo(pins[i], 0);
    }

    gpioTerminate();
    printf("Servos stopped. pigpio terminated.\n");
    return EXIT_SUCCESS;
}

