#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdatomic.h>
#include <stdbool.h>

/* Motor A */
#define MOTOR_A_PWM_PIN 17
#define MOTOR_A_DIR_PIN 18

/* Motor B */
#define MOTOR_B_PWM_PIN 22
#define MOTOR_B_DIR_PIN 23

/* Encoder A */
#define ENCODER_A_A_PIN 4
#define ENCODER_A_B_PIN 5

/* Encoder B */
#define ENCODER_B_A_PIN 6
#define ENCODER_B_B_PIN 12

#define TARGET_RPM 50.0
#define PWM_FREQUENCY 10000
#define PWM_RANGE 255
#define ENCODER_TICKS_PER_REV 64
#define ENCODER_STALL_TIMEOUT_SEC 2.0
#define CONTROL_PERIOD_US 100000
#define KP 0.5
#define KI 0.05
#define MAX_DUTY_CYCLE 255
#define MIN_DUTY_CYCLE 0

static volatile sig_atomic_t g_running = 1;
static atomic_int g_encoder_a_count = 0;
static atomic_int g_encoder_b_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    int current = atomic_fetch_add(&g_encoder_a_count, 1);
    if (current < 0) atomic_store(&g_encoder_a_count, 0);
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    int current = atomic_fetch_add(&g_encoder_b_count, 1);
    if (current < 0) atomic_store(&g_encoder_b_count, 0);
}

static double calculate_rpm(int encoder_ticks, double dt) {
    if (dt <= 0.0) return 0.0;
    double revolutions = (double)encoder_ticks / (double)ENCODER_TICKS_PER_REV;
    return (revolutions / dt) * 60.0;
}

static void set_motor_direction(int motor, int direction) {
    if (motor == 0) {
        gpioWrite(MOTOR_A_DIR_PIN, direction);
    } else if (motor == 1) {
        gpioWrite(MOTOR_B_DIR_PIN, direction);
    }
}

static void set_motor_pwm(int motor, int duty_cycle) {
    if (duty_cycle < MIN_DUTY_CYCLE) duty_cycle = MIN_DUTY_CYCLE;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;
    if (motor == 0) {
        gpioPWM(MOTOR_A_PWM_PIN, duty_cycle);
    } else if (motor == 1) {
        gpioPWM(MOTOR_B_PWM_PIN, duty_cycle);
    }
}

static void stop_motors(void) {
    gpioPWM(MOTOR_A_PWM_PIN, 0);
    gpioPWM(MOTOR_B_PWM_PIN, 0);
    gpioWrite(MOTOR_A_DIR_PIN, 0);
    gpioWrite(MOTOR_B_DIR_PIN, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler.\n");
    }

    /* Configure motor control pins */
    if (gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR_A_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR_A_DIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR_B_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR_B_DIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

