#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RELAY_GPIO 17
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define LUX_THRESHOLD_DUSK 50.0
#define LUX_THRESHOLD_DAWN 200.0
#define POLL_INTERVAL_SEC 5
#define BH1750_CMD_OT_HRES2 0x21
#define BH1750_CONV_TIME_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (pigpio error %d).\n",
                I2C_BUS, BH1750_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_bh1750(float *lux_out) {
    char cmd = BH1750_CMD_OT_HRES2;
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write BH1750 command 0x%02X.\n", cmd);
        return -1;
    }
    gpioDelay(BH1750_CONV_TIME_MS * 1000);
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read 2 bytes from BH1750.\n");
        return -1;
    }
    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write GPIO %d.\n", RELAY_GPIO);
        return -1;
    }
    return 0;
}

static void log_event(float lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen("chicken_coop_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    int relay_state = 0;
    int relay_set = 0;

    while (running) {
        float lux;
        if (read_bh1750(&lux) == 0) {
            log_event(lux, relay_state);

            if (lux < LUX_THRESHOLD_DUSK && !relay_set) {
                if (control_relay(1) == 0) {
                    relay_state = 1;
                    relay_set = 1;
                    log_event(lux, relay_state);
                }
            } else if (lux > LUX_THRESHOLD_DAWN && relay_set) {
                if (control_relay(0) == 0) {
                    relay_state = 0;
                    relay_set = 0;
                    log_event(lux, relay_state);
                }
            }
        } else {
            fprintf(stderr, "Error reading lux, turning off relay for safety.\n");
            if (relay_set) {
                control_relay(0);
                relay_state = 0;
                relay_set = 0;
                log_event(0.0f, relay_state);
            }
        }
        gpioDelay(POLL_INTERVAL_SEC * 1000000);
    }

    cleanup();
    return 0;
}

