#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000   /* 50 ms */
#define LOOP_SLEEP_US 10000        /* 10 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }

    printf("[%s] Relay is now %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(void) {
    int relay_state = 0;
    int last_touch_state = 0;
    int first_read = 1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay state on GPIO %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    relay_state = 0;
    log_relay_state(relay_state);

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not register SIGINT handler\n");
    }

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);

        if (touch_state < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (first_read) {
            last_touch_state = touch_state;
            first_read = 0;
        }

        if (touch_state == 1 && last_touch_state == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);

            if (gpioRead(TOUCH_SENSOR_PIN) == 1) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Error: failed to write GPIO %d\n", RELAY_PIN);
                    break;
                }
                log_relay_state(relay_state);
            }
        }

        last_touch_state = touch_state;
        gpioDelay(LOOP_SLEEP_US);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

