#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO    27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD    5.0
#define LPM_HYSTERESIS   0.5
#define LOG_FILE         "water_flow.log"
#define DEBOUNCE_US      1000000  /* 1 second */

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", ts, msg);
    fflush(log_file);
}

static void flow_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static double calculate_lpm(int pulses) {
    return ((double)pulses / PULSES_PER_LITER) * 60.0;
}

static void control_solenoid(double lpm) {
    static int solenoid_open = 1;
    if (lpm > LPM_THRESHOLD && solenoid_open) {
        if (gpioWrite(SOLENOID_GPIO, 0) == 0) {
            solenoid_open = 0;
            log_message("Solenoid closed (flow rate exceeded threshold)");
        } else {
            log_message("Failed to close solenoid");
        }
    } else if (lpm < (LPM_THRESHOLD - LPM_HYSTERESIS) && !solenoid_open) {
        if (gpioWrite(SOLENOID_GPIO, 1) == 0) {
            solenoid_open = 1;
            log_message("Solenoid opened (flow rate below threshold)");
        } else {
            log_message("Failed to open solenoid");
        }
    }
}

int main(void) {
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex init failed\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        pthread_mutex_destroy(&pulse_mutex);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flow sensor GPIO mode\n");
        gpioTerminate();
        pthread_mutex_destroy(&pulse_mutex);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid GPIO mode\n");
        gpioTerminate();
        pthread_mutex_destroy(&pulse_mutex);
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to set solenoid initial state\n");
        gpioTerminate();
        pthread_mutex_destroy(&pulse_mutex);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioWrite(SOLENOID_GPIO, 0);
        gpioTerminate();
        pthread_mutex_destroy(&pulse_mutex);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        fclose(log_file);
        gpioWrite(SOLENOID_GPIO, 0);
        gpioTerminate();
        pthread_mutex_destroy(&pulse_mutex);
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_US, flow_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR on flow sensor\n");
        fclose(log_file);
        gpioWrite(SOLENOID_GPIO, 0);
        gpioTerminate();
        pthread_mutex_destroy(&pulse_mutex);
        return EXIT_FAILURE;
    }

    log_message("System started");

    while (running) {
        time_sleep(1.0);
        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = calculate_lpm(pulses);
        char msg[128];
        snprintf(msg, sizeof(msg), "Flow rate: %.2f LPM", lpm);
        log_message(msg);
        control_solenoid(lpm);
    }

    log_message("Shutting down");
    gpioWrite(SOLENOID_GPIO, 1);
    fclose(log_file);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
    return EXIT_SUCCESS;
}

