#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18

#define DEFAULT_CALIBRATION_FACTOR 1000.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DEFAULT_DISPENSE_TIME 1
#define DEFAULT_LOG_FILE "dispensing_log.json"

#define HX711_TIMEOUT 1000
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_SETTLE_TIME 1000000

#define MAX_BUFFER_SIZE 1024

static volatile sig_atomic_t running = 1;
static volatile int keep_running = 1;
static int server_fd = -1;
static int client_fd = -1;
static int hx711_gain = 1;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static char server_ip[20] = DEFAULT_SERVER_IP;
static int server_port = DEFAULT_SERVER_PORT;
static char log_file[50] = DEFAULT_LOG_FILE;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
    keep_running = 0;
}

static void log_error(const char *message) {
    FILE *fp = fopen(log_file, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "{\"timestamp\":\"%04d-%02d-%02d %02d:%02d:%02d\", \"error\":\"%s\"}\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    }
}

static int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file %s: %s. Using defaults.\n", filename, strerror(errno));
        return 0;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        line[strcspn(line, "\n")] = 0;
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");
        if (!key || !value) continue;
        if (strcmp(key, "calibration_factor") == 0) {
            calibration_factor = atof(value);
        } else if (strcmp(key, "server_ip") == 0) {
            strncpy(server_ip, value, sizeof(server_ip) - 1);
            server_ip[sizeof(server_ip) - 1] = 0;
        } else if (strcmp(key, "server_port") == 0) {
            server_port = atoi(value);
        }
    }
    fclose(fp);
    printf("Config: calibration_factor=%.2f, server_ip=%s, server_port=%d\n", calibration_factor, server_ip, server_port);
    return 0;
}

static int hx711_read_raw(int *raw_value) {
    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) < 0) return -1;
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;

    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (++timeout > HX711_TIMEOUT) {
            log_error("HX711 timeout: sensor not ready or disconnected");
            return -1;
        }
        gpioDelay(1);
    }

    long value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK_PIN, 1) < 0) return -1;
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(HX711_DATA_PIN)) value |= 1;
        if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;
        gpioDelay(1);
    }

    if (gpioWrite(HX711_SCK_PIN, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioRead(HX711_DATA_PIN)) value |= 0x800000;
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;
    gpioDelay(1);

    *raw_value = (int)value;
    return 0;
}

static double hx711_read_scaled(void) {
    int raw;
    if (hx711_read_raw(&raw) < 0) return 0.0;
    return (double)raw / calibration_factor;
}

static int hx711_set_gain(int gain) {
    if (gain != 1 && gain != 128) return -1;
    hx711_gain = gain;
    return 0;
}

static int hx711_init(void) {
    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) < 0) return -1;
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;
    if (hx711_set_gain(1) < 0) return -1;
    return 0;
}

static int servo_set_pulse_width(int pulse_width) {
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        log_error("Failed to set servo pulse width");
        return -1;
    }
    gpioDelay(SERVO_SETTLE_TIME);
    return 0;
}

static int dispense_ingredient(double target_weight) {
    if (hx711_set_gain(128) < 0) {
        log_error("Failed to set HX711 gain to 128");
        return -1;
    }
    gpioDelay(100000);

    if (hx711_set_gain(1) < 0) {
        log_error("Failed to set HX711 gain to 1");
        return -1;
    }

    double actual_weight = hx711_read_scaled();
    printf("Target weight: %.2f g, Actual weight: %.2f g\n", target_weight, actual_weight);

    int pulse_width = (int)((actual_weight / target_weight) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH);
