}

static int send_response(int client_fd, const char *response) {
    size_t len = strlen(response);
    if (send(client_fd, response, len, 0) != (ssize_t)len) {
        log_error("Failed to send response");
        return -1;
    }
    return 0;
}

static int log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    FILE *fp = fopen(log_file, "a");
    if (!fp) {
        log_error("Failed to open log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "{\"timestamp\":\"%04d-%02d-%02d %02d:%02d:%02d\", \"target_weight\":%.2f, \"actual_weight\":%.2f, \"error\":\"%s\"}\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, target_weight, actual_weight, error_message);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (server_fd >= 0) close(server_fd);
    if (client_fd >= 0) close(client_fd);
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (hx711_init() < 0) {
        log_error("HX711 initialization failed");
        gpioTerminate();
        return 1;
    }

    read_config("config.ini");

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_error("Socket creation failed");
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_error("setsockopt failed");
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(server_port);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_error("Bind failed");
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        log_error("Listen failed");
        cleanup();
        return 1;
    }

    printf("Listening on %s:%d\n", server_ip, server_port);

    while (keep_running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
