            log_error("Accept failed");
            continue;
        }

        char buffer[MAX_BUFFER_SIZE];
        ssize_t bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = 0;
            double target_weight = atof(buffer);
            printf("Received target weight: %.2f g\n", target_weight);

            if (dispense_ingredient(target_weight) < 0) {
