            } else {
                double actual_weight = hx711_read_scaled();
                log_dispensing_event(target_weight, actual_weight, "");
            }

            char response[256];
            snprintf(response, sizeof(response), "{\"status\":\"ok\"}");
            send_response(client_fd, response);
        } else if (bytes_received == 0) {
            log_error("Client disconnected");
        } else {
            log_error("Failed to receive data");
        }

