#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DEFAULT_MS 50

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

static int set_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for relay pin %d\n", RELAY_PIN);
        return -1;
    }
    return 0;
}

static int debounce_touch(int pin, int *last_state, int debounce_ms) {
    int current_state = gpioRead(pin);
    if (current_state < 0) {
        fprintf(stderr, "Error: gpioRead failed for pin %d\n", pin);
        return -1;
    }
    if (current_state != *last_state) {
        gpioDelay(debounce_ms * 1000);
        int confirmed = gpioRead(pin);
        if (confirmed < 0) {
            fprintf(stderr, "Error: gpioRead failed for pin %d during debounce\n", pin);
            return -1;
        }
        if (confirmed == current_state) {
            *last_state = current_state;
            return 1;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEBOUNCE_DEFAULT_MS;
    int opt;

    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_ms = atoi(optarg);
                if (debounce_ms <= 0) {
                    fprintf(stderr, "Error: debounce delay must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d milliseconds]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for touch sensor pin %d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for relay pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_relay(0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        set_relay(0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed\n");
        set_relay(0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_state = gpioRead(TOUCH_SENSOR_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Error: initial gpioRead failed for touch sensor pin %d\n", TOUCH_SENSOR_PIN);
        set_relay(0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch-controlled desk lamp started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        if (debounce_touch(TOUCH_SENSOR_PIN, &last_state, debounce_ms) == 1) {
            int current_state = gpioRead(TOUCH_SENSOR_PIN);
            if (current_state < 0) {
                fprintf(stderr, "Error: gpioRead failed during toggle\n");
                continue;
            }
            if (current_state == 1) {
                if (set_relay(1) == 0) {
                    log_relay_state(1);
                }
            } else {
                if (set_relay(0) == 0) {
                    log_relay_state(0);
                }
            }
        }
        gpioDelay(10000);
    }

    set_relay(0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

