    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for relay pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_relay(0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        set_relay(0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed\n");
        set_relay(0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_state = gpioRead(TOUCH_SENSOR_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Error: initial gpioRead failed for touch sensor pin %d\n", TOUCH_SENSOR_PIN);
        set_relay(0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch-controlled desk lamp started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        if (debounce_touch(TOUCH_SENSOR_PIN, &last_state, debounce_ms) == 1) {
            int current_state = gpioRead(TOUCH_SENSOR_PIN);
            if (current_state < 0) {
                fprintf(stderr, "Error: gpioRead failed during toggle\n");
                continue;
            }
            if (current_state == 1) {
                if (set_relay(1) == 0) {
                    log_relay_state(1);
                }
            } else {
                if (set_relay(0) == 0) {
                    log_relay_state(0);
                }
            }
        }
        gpioDelay(10000);
    }

    set_relay(0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

