#define MAX_PULSE_US 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define DEFAULT_ANGLE 90
#define PWM_FREQ 50
#define PWM_RANGE 20000

static volatile sig_atomic_t g_running = 1;
static struct termios g_orig_termios;

static void restore_termios(void) {
    if (tcsetattr(STDIN_FILENO, TCSANOW, &g_orig_termios) != 0) {
        perror("tcsetattr");
    }
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_raw_mode(void) {
    struct termios raw;
    if (tcgetattr(STDIN_FILENO, &g_orig_termios) != 0) {
        perror("tcgetattr");
        return -1;
    }
    raw = g_orig_termios;
    raw.c_lflag &= ~(ICANON | ECHO);
    raw.c_cc[VMIN] = 1;
    raw.c_cc[VTIME] = 0;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static int angle_to_pulse_us(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return MIN_PULSE_US + (int)((long)angle * (MAX_PULSE_US - MIN_PULSE_US) / MAX_ANGLE);
}

static int pulse_us_to_angle(int pulse_us) {
    if (pulse_us < MIN_PULSE_US) pulse_us = MIN_PULSE_US;
    if (pulse_us > MAX_PULSE_US) pulse_us = MAX_PULSE_US;
    return (int)((long)(pulse_us - MIN_PULSE_US) * MAX_ANGLE / (MAX_PULSE_US - MIN_PULSE_US));
}

int main(void) {
    int angle = DEFAULT_ANGLE;
    int pulse_us = angle_to_pulse_us(angle);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (set_raw_mode() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SERVO_PIN);
        restore_termios();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Warning: could not set PWM frequency to %d Hz\n", PWM_FREQ);
    }
    if (gpioSetPWMrange(SERVO_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Warning: could not set PWM range to %d\n", PWM_RANGE);
    }

    if (gpioServo(SERVO_PIN, pulse_us) != 0) {
        fprintf(stderr, "Failed to start servo PWM on GPIO%d\n", SERVO_PIN);
        restore_termios();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        restore_termios();
        gpioServo(SERVO_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Servo control started on GPIO%d. Angle: %d°. Press '+' to increase, '-' to decrease, 'q' to quit.\n", SERVO_PIN, angle);
    printf("Current pulse width: %d µs\n", pulse_us);

    while (g_running) {
        int c = getchar();
        if (c == '+') {
            angle += 10;
            if (angle > MAX_ANGLE) angle = MAX_ANGLE;
            pulse_us = angle_to_pulse_us(angle);
            if (gpioServo(SERVO_PIN, pulse_us) != 0) {
                fprintf(stderr, "Failed to update servo PWM\n");
            } else {
                printf("Angle: %d° (pulse: %d µs)\n", angle, pulse_us);
            }
        } else if (c == '-') {
            angle -= 10;
            if (angle < MIN_ANGLE) angle = MIN_ANGLE;
            pulse_us = angle_to_pulse_us(angle);
            if (gpioServo(SERVO_PIN, pulse_us) != 0) {
                fprintf(stderr, "Failed to update servo PWM\n");
            } else {
                printf("Angle: %d° (pulse: %d µs)\n", angle, pulse_us);
            }
        } else if (c == 'q' || c == 'Q') {
            g_running = 0;
        } else if (c != EOF) {
            printf("Invalid input. Use '+' or '-'.\n");
        }
        usleep(10000);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    restore_termios();
    gpioTerminate();
    return EXIT_SUCCESS;
}

