#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE "motor_rpm.log"
#define SAMPLE_INTERVAL_SEC 5
#define DEBOUNCE_MS 2

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int log_rpm(float rpm) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, rpm) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    struct timespec last_event_time = {0, 0};
    struct timespec now;
    long long last_event_ns;
    long long current_ns;
    long long elapsed_ns;
    float rpm;
    int pulse_count = 0;
    int ret;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input_flags(line, "motor_rpm_monitor",
                                          GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret != 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input with pull-up: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring conveyor belt motor on GPIO %d (BCM). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    while (program_running) {
        struct timespec poll_timeout = {1, 0}; /* 1 second timeout per iteration */

        ret = gpiod_line_event_wait(line, &poll_timeout);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) {
            /* Timeout — no event, just loop again */
            continue;
        }

        struct gpiod_line_event event;
        ret = gpiod_line_event_read(line, &event);
        if (ret != 0) {
            fprintf(stderr, "Error reading GPIO event: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &now);
        long long now_ns = (long long)now.tv_sec * 1000000000LL + now.tv_nsec;

        if (last_event_time.tv_sec != 0 || last_event_time.tv_nsec != 0) {
            elapsed_ns = now_ns - last_event_ns;
            if (elapsed_ns > (long long)DEBOUNCE_MS * 1000000LL) {
                pulse_count++;
                last_event_ns = now_ns;
            }
        } else {
            pulse_count++;
            last_event_ns = now_ns;
        }

        last_event_time = now;

        if (now.tv_sec % SAMPLE_INTERVAL_SEC == 0) {
            rpm = ((float)pulse_count / SAMPLE_INTERVAL_SEC) * 60.0f;
            if (log_rpm(rpm) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
            printf("RPM: %.2f\n", rpm);
            pulse_count = 0;
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

