#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define POLL_INTERVAL_US 50000   /* 50 ms */
#define FAILSAFE_TIMEOUT 10      /* seconds */

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_touch_active = 0;
static volatile sig_atomic_t g_relay_state = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to turn off relay during cleanup\n");
    }
    gpioTerminate();
}

static void toggle_relay(void)
{
    g_relay_state = !g_relay_state;
    if (gpioWrite(RELAY_PIN, g_relay_state) < 0) {
        fprintf(stderr, "Error: failed to write relay pin %d\n", RELAY_PIN);
        return;
    }
    printf("Relay toggled to %s\n", g_relay_state ? "ON" : "OFF");
}

static void check_failsafe(void)
{
    static time_t last_touch_time = 0;
    time_t now = time(NULL);

    if (now == (time_t)-1) {
        perror("time()");
        return;
    }

    if (g_touch_active) {
        if (difftime(now, last_touch_time) > FAILSAFE_TIMEOUT) {
            fprintf(stderr, "Failsafe triggered: touch held > %d s; forcing relay OFF\n",
                    FAILSAFE_TIMEOUT);
            if (gpioWrite(RELAY_PIN, 0) < 0) {
                fprintf(stderr, "Error: failed to turn off relay on failsafe\n");
            }
