#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_PWM_PIN      18
#define VALVE_ENABLE_PIN   23
#define FLOW_SENSOR_PIN    24

#define PULSES_PER_LITER   450.0
#define PWM_RANGE          255
#define PWM_FREQ           1000
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define LOG_FILE_NAME      "flow_log.csv"

static volatile unsigned int pulse_count = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* ISR: increment pulse counter on every rising edge of the sensor     */
/* ------------------------------------------------------------------ */
static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; (void)level; (void)tick; (void)user;
    pulse_count++;
}

/* ------------------------------------------------------------------ */
/* Signal handler: request graceful shutdown                           */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Compute flow rate (L/min) from pulse count over the sample interval */
/* ------------------------------------------------------------------ */
static double calculate_flow_rate(unsigned int pulses, uint32_t interval_us)
{
    double liters = (double)pulses / PULSES_PER_LITER;
    double flow_rate = liters * 60.0;          /* L/min */
    double rate_per_us = flow_rate / (double)interval_us;
    return rate_per_us * (double)interval_us;  /* L/min */
}

/* ------------------------------------------------------------------ */
/* Proportional controller: compute duty cycle from error              */
/* ------------------------------------------------------------------ */
static int calculate_duty_cycle(double target_flow, double current_flow)
{
    double error = target_flow - current_flow;
    double duty = error * 10.0;                 /* Kp = 10 */

    if (duty < 0.0) duty = 0.0;
    if (duty > (double)PWM_RANGE) duty = (double)PWM_RANGE;

    return (int)duty;
}

/* ------------------------------------------------------------------ */
/* Log one CSV row: timestamp_ms, flow_rate, valve_position           */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, double flow_rate, int valve_position)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000L) + (ts.tv_nsec / 1000000L);

    fprintf(fp, "%ld,%.3f,%d\n", timestamp_ms, flow_rate, valve_position);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper: release all resources                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure valve is disabled before terminating pigpio */
    gpioWrite(VALVE_ENABLE_PIN, 0);
    gpioPWM(VALVE_PWM_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    double target_flow_rate = 0.0;

    /* ---- Parse command-line target flow rate ----------------------- */
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <target_flow_rate_L/min>\n", argv[0]);
        return EXIT_FAILURE;
    }
    target_flow_rate = atof(argv[1]);
    if (target_flow_rate <= 0.0) {
        fprintf(stderr, "Error: target flow rate must be positive.\n");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ----------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure valve PWM pin ----------------------------------- */
    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioPWM(VALVE_PWM_PIN, 0);  /* start with valve closed */

    /* ---- Configure valve enable pin -------------------------------- */
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", VALVE_ENABLE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(VALVE_ENABLE_PIN, 1);  /* enable valve driver */

    /* ---- Configure flow sensor pin --------------------------------- */
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO %d.\n", FLOW_SENSOR_PIN);
    }

    /* ---- Register ISR on rising edge -------------------------------- */
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0,
                         flow_sensor_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d.\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file --------------------------------------------- */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE_NAME);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Write CSV header if file is empty -------------------------- */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp_ms,flow_rate_L/min,valve_position\n");
        fflush(log_file);
    }

    /* ---- Install signal handlers ----------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install signal handlers.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow control system started. Target: %.2f L/min\n", target_flow_rate);
    printf("Logging to: %s\n", LOG_FILE_NAME);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main control loop ----------------------------------------- */
    while (running) {
        uint32_t start_tick = gpioTick();

        /* ---- Sample sensor pulses ----------------------------------- */
        unsigned int pulses = pulse_count;
        pulse_count = 0;

        /* ---- Compute current flow rate ------------------------------- */
        double current_flow = calculate_flow_rate(pulses, SAMPLE_INTERVAL_US);

        /* ---- Proportional controller --------------------------------- */
        int duty = calculate_duty_cycle(target_flow_rate, current_flow);
        gpioPWM(VALVE_PWM_PIN, duty);

        /* ---- Log data ------------------------------------------------ */
        int valve_position = gpioRead(VALVE_ENABLE_PIN);
        log_data(log_file, current_flow, valve_position);

        /* ---- Sleep for remainder of sample interval ------------------ */
        uint32_t elapsed = gpioTick() - start_tick;
        if (elapsed < SAMPLE_INTERVAL_US) {
            gpioDelay(SAMPLE_INTERVAL_US - elapsed);
        }
    }

    /* ---- Graceful shutdown ----------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Flow control system stopped.\n");
    return EXIT_SUCCESS;
}

