#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_1_PIN 17
#define LOCK_2_PIN 27
#define BUTTON_PIN 22
#define SPI_CHANNEL 0
#define SPI_SPEED 100000
#define LOG_FILE "/var/log/door_access.log"
#define LOCK_DISARM_TIME_US 5000000
#define DEBOUNCE_US 50000
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;
static int spi_handle = -1;

static const unsigned char valid_tag[10] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    if (!log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(log_fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(log_fp);
    }
}

static int read_rfid(unsigned char *data, int len) {
    if (!data || len < 10) return -1;
    char tx[10] = {0};
    char rx[10] = {0};
    int ret = spiXfer(spi_handle, tx, rx, len);
    if (ret != len) return -1;
    for (int i = 0; i < len; i++) data[i] = (unsigned char)rx[i];
    return 0;
}

static int disarm_locks(void) {
    if (gpioWrite(LOCK_1_PIN, 0) < 0) return -1;
    if (gpioWrite(LOCK_2_PIN, 0) < 0) return -1;
    log_event("Locks disarmed");
    return 0;
}

static int reengage_locks(void) {
    if (gpioWrite(LOCK_1_PIN, 1) < 0) return -1;
    if (gpioWrite(LOCK_2_PIN, 1) < 0) return -1;
    log_event("Locks re-engaged");
    return 0;
}

static int check_button(void) {
    int val = gpioRead(BUTTON_PIN);
    if (val < 0) return -1;
    if (val == 0) {
        gpioDelay(DEBOUNCE_US);
        val = gpioRead(BUTTON_PIN);
        if (val < 0) return -1;
        if (val == 0) return 1;
    }
    return 0;
}

static int authenticate(void) {
    unsigned char rfid[10];
    if (read_rfid(rfid, sizeof(rfid)) != 0) {
        log_event("RFID read failure");
        return -1;
    }
    if (memcmp(rfid, valid_tag, sizeof(valid_tag)) != 0) {
        log_event("Invalid RFID tag");
        return -1;
    }
    log_event("RFID authentication successful");
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
