#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <gpiod.h>
#include <unistd.h>
#include <errno.h>

/* Motor 1 */
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

/* Motor 2 */
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

/* Encoder 1 */
#define ENCODER1_A 5
#define ENCODER1_B 6

/* Encoder 2 */
#define ENCODER2_A 26
#define ENCODER2_B 19

#define KP 1.0
#define KI 0.1
#define KD 0.01
#define TARGET_RPM 60.0
#define ENCODER_PPR 600
#define PWM_FREQ 100
#define PWM_PERIOD_US (1000000 / PWM_FREQ)
#define SAMPLE_TIME_US 100000
#define LOG_FILE "motor_log.csv"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_lines[6] = {NULL};
static struct gpiod_line *encoder_lines[4] = {NULL};
static pthread_mutex_t encoder_mutex[2] = {PTHREAD_MUTEX_INITIALIZER};

static double integral = 0.0;
static double previous_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void stop_motors(void) {
    for (int i = 0; i < 6; i++) {
        if (motor_lines[i]) {
            gpiod_line_set_value(motor_lines[i], 0);
        }
    }
}

static void release_resources(void) {
    stop_motors();
    for (int i = 0; i < 6; i++) {
        if (motor_lines[i]) {
            gpiod_line_release(motor_lines[i]);
            motor_lines[i] = NULL;
        }
    }
    for (int i = 0; i < 4; i++) {
        if (encoder_lines[i]) {
            gpiod_line_release(encoder_lines[i]);
            encoder_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static double pid_control(double setpoint, double actual) {
    double error = setpoint - actual;
    integral += error;
    double derivative = error - previous_error;
    double output = KP * error + KI * integral + KD * derivative;
    previous_error = error;
    return output;
}

static void set_motor_speed(int motor, double speed) {
    int ena = (motor == 1) ? MOTOR1_ENA : MOTOR2_ENB;
    int in1 = (motor == 1) ? MOTOR1_IN1 : MOTOR2_IN3;
    int in2 = (motor == 1) ? MOTOR1_IN2 : MOTOR2_IN4;

    if (speed > 0.0) {
        gpiod_line_set_value(motor_lines[0], 1);
        gpiod_line_set_value(motor_lines[1], 1);
        gpiod_line_set_value(motor_lines[2], 0);
        gpiod_line_set_value(motor_lines[3], 0);
    } else if (speed < 0.0) {
        gpiod_line_set_value(motor_lines[0], 0);
        gpiod_line_set_value(motor_lines[1], 0);
        gpiod_line_set_value(motor_lines[2], 1);
        gpiod_line_set_value(motor_lines[3], 1);
    } else {
        gpiod_line_set_value(motor_lines[0], 0);
        gpiod_line_set_value(motor_lines[1], 0);
        gpiod_line_set_value(motor_lines[2], 0);
        gpiod_line_set_value(motor_lines[3], 0);
    }
}

static void *encoder_thread(void *arg) {
    int encoder_num = *(int *)arg;
    struct gpiod_line *a_line = encoder_lines[encoder_num * 2];
    struct gpiod_line *b_line = encoder_lines[encoder_num * 2 + 1];
    int last_a = gpiod_line_get_value(a_line);
    if (last_a < 0) {
        fprintf(stderr, "Error reading encoder A line: %s\n", strerror(errno));
        return NULL;
    }

    while (running) {
        struct timespec ts = {0, 10000000}; /* 10 ms */
        int ret = gpiod_line_event_wait(a_line, &ts);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error waiting for encoder event: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) continue;

        struct gpiod_line_event event;
        if (gpiod_line_event_read(a_line, &event) < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error reading encoder event: %s\n", strerror(errno));
            continue;
        }

        int current_a = gpiod_line_get_value(a_line);
        if (current_a < 0) {
            fprintf(stderr, "Error reading encoder A line: %s\n", strerror(errno));
            continue;
        }

        int current_b = gpiod_line_get_value(b_line);
        if (current_b < 0) {
            fprintf(stderr, "Error reading encoder B line: %s\n", strerror(errno));
            continue;
        }

        int direction;
        if (current_a == last_a) {
            direction = 0;
        } else if (current_a == 1 && current_b == 0) {
            direction = 1;
        } else if (current_a == 0 && current_b == 1) {
            direction = -1;
        } else {
            direction = 0;
        }

        if (direction != 0) {
            pthread_mutex_lock(&encoder_mutex[encoder_num]);
            static int count = 0;
            if (direction == 1) {
                count++;
            } else {
                count--;
            }
            pthread_mutex_unlock(&encoder_mutex[encoder_num]);
        }
        last_a = current_a;
    }
    return NULL;
}

static double calculate_speed(int encoder_num) {
    int count;
    pthread_mutex_lock(&encoder_mutex[encoder_num]);
    count = 0;
    pthread_mutex_unlock(&encoder_mutex[encoder_num]);
    return (double)count * 60.0 / (ENCODER_PPR * (SAMPLE_TIME_US / 1000000.0));
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }

    int motor_pins[6] = {MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2, MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4};
    for (int i = 0; i < 6; i++) {
        motor_lines[i] = gpiod_chip_get_line(chip, motor_pins[i]);
        if (!motor_lines[i]) {
            fprintf(stderr, "Failed to get motor line %d: %s\n", motor_pins[i], strerror(errno));
            release_resources();
            return 1;
        }
        if (gpiod_line_request_output(motor_lines[i], "motor_control", 0) < 0) {
            fprintf(stderr, "Failed to request motor line %d as output: %s\n", motor_pins[i], strerror(errno));
            release_resources();
            return 1;
        }
    }

    int encoder_pins[4] = {ENCODER1_A, ENCODER1_B, ENCODER2_A, ENCODER2_B};
    for (int i = 0; i < 4; i++) {
        encoder_lines[i] = gpiod_chip_get_line(chip, encoder_pins[i]);
        if (!encoder_lines[i]) {
            fprintf(stderr, "Failed to get encoder line %d: %s\n", encoder_pins[i], strerror(errno));
            release_resources();
            return 1;
        }
        if (gpiod_line_request_both_edges_events(encoder_lines[i], "encoder") < 0) {
            fprintf(stderr, "Failed to request encoder line %d events: %s\n", encoder_pins[i], strerror(errno));
            release_resources();
            return 1;
        }
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        release_resources();
        return 1;
    }
    fprintf(log_file, "Timestamp,Motor1_Speed_RPM,Motor2_Speed_RPM,PID_Output,PID_P,PID_I,PID_D\n");
    fflush(log_file);

    pthread_t encoder_thread1, encoder_thread2;
    int encoder_args[2] = {0, 1};

    if (pthread_create(&encoder_thread1, NULL, encoder_thread, &encoder_args[0]) != 0) {
        fprintf(stderr, "Failed to create encoder thread 1: %s\n", strerror(errno));
        release_resources();
        return 1;
    }
    if (pthread_create(&encoder_thread2, NULL, encoder_thread, &encoder_args[1]) != 0) {
        fprintf(stderr, "Failed to create encoder thread 2: %s\n", strerror(errno));
        running = 0;
        pthread_join(encoder_thread1, NULL);
        release_resources();
        return 1;
    }

    while (running) {
        double speed1 = calculate_speed(0);
        double speed2 = calculate_speed(1);

        double pid_output = pid_control(TARGET_RPM, speed1);
        double pid_p = KP * (TARGET_RPM - speed1);
        double pid_i = KI * integral;
        double pid_d = KD * (speed1 - previous_error);

        set_motor_speed(1, pid_output);
        set_motor_speed(2, pid_output);

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
                timestamp, speed1, speed2, pid_output, pid_p, pid_i, pid_d);
        fflush(log_file);

        usleep(SAMPLE_TIME_US);
    }

    running = 0;
    pthread_join(encoder_thread1, NULL);
    pthread_join(encoder_thread2, NULL);

    release_resources();
    return 0;
}

