    int motor_pins[6] = {MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2, MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4};
    for (int i = 0; i < 6; i++) {
        motor_lines[i] = gpiod_chip_get_line(chip, motor_pins[i]);
        if (!motor_lines[i]) {
            fprintf(stderr, "Failed to get motor line %d: %s\n", motor_pins[i], strerror(errno));
            release_resources();
            return 1;
        }
        if (gpiod_line_request_output(motor_lines[i], "motor_control", 0) < 0) {
            fprintf(stderr, "Failed to request motor line %d as output: %s\n", motor_pins[i], strerror(errno));
            release_resources();
            return 1;
        }
    }

    int encoder_pins[4] = {ENCODER1_A, ENCODER1_B, ENCODER2_A, ENCODER2_B};
    for (int i = 0; i < 4; i++) {
        encoder_lines[i] = gpiod_chip_get_line(chip, encoder_pins[i]);
        if (!encoder_lines[i]) {
            fprintf(stderr, "Failed to get encoder line %d: %s\n", encoder_pins[i], strerror(errno));
            release_resources();
            return 1;
        }
        if (gpiod_line_request_both_edges_events(encoder_lines[i], "encoder") < 0) {
            fprintf(stderr, "Failed to request encoder line %d events: %s\n", encoder_pins[i], strerror(errno));
            release_resources();
            return 1;
        }
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        release_resources();
        return 1;
    }
    fprintf(log_file, "Timestamp,Motor1_Speed_RPM,Motor2_Speed_RPM,PID_Output,PID_P,PID_I,PID_D\n");
    fflush(log_file);

    pthread_t encoder_thread1, encoder_thread2;
    int encoder_args[2] = {0, 1};

    if (pthread_create(&encoder_thread1, NULL, encoder_thread, &encoder_args[0]) != 0) {
        fprintf(stderr, "Failed to create encoder thread 1: %s\n", strerror(errno));
        release_resources();
        return 1;
    }
    if (pthread_create(&encoder_thread2, NULL, encoder_thread, &encoder_args[1]) != 0) {
        fprintf(stderr, "Failed to create encoder thread 2: %s\n", strerror(errno));
        running = 0;
        pthread_join(encoder_thread1, NULL);
        release_resources();
        return 1;
    }

    while (running) {
        double speed1 = calculate_speed(0);
        double speed2 = calculate_speed(1);

        double pid_output = pid_control(TARGET_RPM, speed1);
        double pid_p = KP * (TARGET_RPM - speed1);
        double pid_i = KI * integral;
        double pid_d = KD * (speed1 - previous_error);

        set_motor_speed(1, pid_output);
        set_motor_speed(2, pid_output);

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
                timestamp, speed1, speed2, pid_output, pid_p, pid_i, pid_d);
        fflush(log_file);

        usleep(SAMPLE_TIME_US);
    }

    running = 0;
    pthread_join(encoder_thread1, NULL);
    pthread_join(encoder_thread2, NULL);

    release_resources();
    return 0;
}

