#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1
#define POLL_DELAY_US 50000

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int mpr121_read(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
    }
    return rc;
}

static int mpr121_init(int handle) {
    if (mpr121_write(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write(handle, MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHDF, 0x05) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDLT, 0x00) < 0) return -1;

    if (mpr121_write(handle, MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(handle, MPR121_CONFIG2, 0x20) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (mpr121_write(handle, MPR121_E0TTH + (i * 2), 0x0F) < 0) return -1;
        if (mpr121_write(handle, MPR121_E0RTH + (i * 2), 0x0A) < 0) return -1;
    }

    if (mpr121_write(handle, MPR121_ECR, 0x8F) < 0) return -1;

    return 0;
}

static int read_touch_status(int handle) {
    int low = mpr121_read(handle, MPR121_TOUCHSTATUS_L);
    if (low < 0) return -1;
    int high = mpr121_read(handle, MPR121_TOUCHSTATUS_H);
    if (high < 0) return -1;
    return (high << 8) | low;
}

static void log_relay_state(int state) {
    FILE *fp = fopen("relay_log.txt", "a");
    if (!fp) {
        perror("Error opening relay_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Relay %s\n", timestamp, state ? "ON" : "OFF");
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;

    while (running) {
        int touch_status = read_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (touch_status > 0) {
            if (!relay_state) {
                gpioWrite(RELAY_GPIO, 1);
                relay_state = 1;
                log_relay_state(relay_state);
            }
        } else {
            if (relay_state) {
                gpioWrite(RELAY_GPIO, 0);
                relay_state = 0;
                log_relay_state(relay_state);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

