#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define LOG_FILE "valve_log.txt"
#define CHIP_NAME "gpiochip0"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }
    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (!valve1_line) {
        perror("gpiod_chip_get_line (valve1)");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!valve2_line) {
        perror("gpiod_chip_get_line (valve2)");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(valve1_line, "valve_control", 0) < 0) {
        perror("gpiod_line_request_output (valve1)");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(valve2_line, "valve_control", 0) < 0) {
        perror("gpiod_line_request_output (valve2)");
        gpiod_line_release(valve1_line);
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    if (valve1_line) {
        gpiod_line_set_value(valve1_line, 0);
        gpiod_line_release(valve1_line);
        valve1_line = NULL;
    }
    if (valve2_line) {
        gpiod_line_set_value(valve2_line, 0);
        gpiod_line_release(valve2_line);
        valve2_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void activate_valve(struct gpiod_line *line, const char *name, int duration_ms) {
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value (ON)");
        log_event("ERROR: Failed to activate valve");
        return;
    }
    log_event(name);
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value (OFF)");
        log_event("ERROR: Failed to deactivate valve");
        return;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log file");
        return 1;
    }

    if (init_gpio() < 0) {
        log_event("ERROR: GPIO initialization failed");
        fclose(log_file);
        return 1;
    }

    log_event("Greenhouse automation started");

    while (running) {
        activate_valve(valve1_line, "Valve 1 activated", 500);
        if (!running) break;
        activate_valve(valve2_line, "Valve 2 activated", 1000);
    }

    log_event("Greenhouse automation stopped");
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    return 0;
}

