        log_event("ERROR: Failed to activate valve");
        return;
    }
    log_event(name);
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value (OFF)");
        log_event("ERROR: Failed to deactivate valve");
        return;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log file");
        return 1;
    }

    if (init_gpio() < 0) {
        log_event("ERROR: GPIO initialization failed");
        fclose(log_file);
        return 1;
    }

    log_event("Greenhouse automation started");

    while (running) {
        activate_valve(valve1_line, "Valve 1 activated", 500);
        if (!running) break;
        activate_valve(valve2_line, "Valve 2 activated", 1000);
    }

    log_event("Greenhouse automation stopped");
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    return 0;
}

