        fprintf(stderr, "I2C read failed (L): %d\n", lo);
        return -1;
    }
    int hi = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (hi < 0) {
        fprintf(stderr, "I2C read failed (H): %d\n", hi);
        return -1;
    }
    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

