    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 touch relay control started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            gpioDelay(100000);
            continue;
        }

        if (touch_status > 0) {
            gpioWrite(RELAY_PIN, !gpioRead(RELAY_PIN));
            printf("Touch detected! Relay toggled. Status: 0x%04X\n", touch_status);
        }

        gpioDelay(100000);
    }

    gpioWrite(RELAY_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return 0;
}

