#define MIN_DUTY 0
#define MAX_DUTY 255
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200
#define MIN_PATTERN_LENGTH 5
#define MAX_PATTERN_LENGTH 15

typedef struct {
    int duty1;
    int duty2;
    int duration_ms;
} MotorStep;

static volatile sig_atomic_t shutdown_requested = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_requested = 1;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
    gpioTerminate();
}

static int generate_random_step(MotorStep *step) {
    step->duty1 = (rand() % (MAX_DUTY - MIN_DUTY + 1)) + MIN_DUTY;
    step->duty2 = (rand() % (MAX_DUTY - MIN_DUTY + 1)) + MIN_DUTY;
    step->duration_ms = (rand() % (MAX_DURATION_MS - MIN_DURATION_MS + 1)) + MIN_DURATION_MS;
    return 0;
}

static int play_pattern(const MotorStep *pattern, int length) {
    for (int i = 0; i < length; i++) {
        if (shutdown_requested) {
            return -1;
        }

        if (gpioPWM(MOTOR1_PIN, pattern[i].duty1) != 0) {
            fprintf(stderr, "Error: Failed to set PWM duty for motor 1.\n");
            return -1;
        }

        if (gpioPWM(MOTOR2_PIN, pattern[i].duty2) != 0) {
            fprintf(stderr, "Error: Failed to set PWM duty for motor 2.\n");
            return -1;
        }

        gpioDelay(pattern[i].duration_ms * 1000);
    }
    return 0;
}

int main(void) {
    srand(time(NULL));

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Failed to register signal handler.\n");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Haptic feedback generator started. Press Ctrl+C to exit.\n");

    while (!shutdown_requested) {
        int pattern_length = (rand() % (MAX_PATTERN_LENGTH - MIN_PATTERN_LENGTH + 1)) + MIN_PATTERN_LENGTH;
        MotorStep *pattern = (MotorStep *)malloc(pattern_length * sizeof(MotorStep));
        if (pattern == NULL) {
            fprintf(stderr, "Error: Memory allocation failed for pattern.\n");
            cleanup_gpio();
            return 1;
        }

        for (int i = 0; i < pattern_length; i++) {
            if (generate_random_step(&pattern[i]) != 0) {
                free(pattern);
                cleanup_gpio();
                return 1;
            }
        }

        if (play_pattern(pattern, pattern_length) != 0) {
            free(pattern);
            cleanup_gpio();
            return 1;
        }

        free(pattern);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    return 0;
}

