#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define WEIGHT_THRESHOLD 10.0
#define CALIBRATION_FILE "calibration.txt"
#define WEIGHT_LOG_FILE "weight_log.txt"
#define NUM_CALIBRATION_READINGS 100
#define HX711_TIMEOUT_US 500000

static volatile sig_atomic_t running = 1;
static FILE *weight_log_fp = NULL;
static FILE *calibration_fp = NULL;

static double scale_factor = 1.0;
static double offset = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin) {
    int value = 0;
    int timeout = 0;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);
    gpioWrite(clock_pin, 0);

    while (gpioRead(data_pin) == 1) {
        gpioDelay(100);
        timeout += 100;
        if (timeout >= HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout waiting for data pin low\n");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        value = value << 1;
        if (gpioRead(data_pin)) {
            value++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (value & 0x800000) {
        value |= ~0xFFFFFF;
    }

    return value;
}

static double convert_to_weight(int raw_value) {
    return (double)(raw_value - offset) / scale_factor;
}

static int calibrate_hx711(int data_pin, int clock_pin) {
    long sum = 0;
    int count = 0;

    printf("Calibrating HX711 (remove all weight)... Press Ctrl+C to abort.\n");

    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        int raw = read_hx711(data_pin, clock_pin);
        if (raw == -1) {
            fprintf(stderr, "Calibration read %d failed\n", i + 1);
            continue;
        }
        sum += raw;
        count++;
        gpioDelay(10000);
    }

    if (count == 0) {
        fprintf(stderr, "Calibration failed: no valid readings\n");
        return -1;
    }

    offset = (double)sum / count;
    printf("Calibration complete. Offset: %.2f\n", offset);
    return 0;
}

static int load_calibration_data(void) {
    calibration_fp = fopen(CALIBRATION_FILE, "r");
    if (calibration_fp == NULL) {
        fprintf(stderr, "Warning: cannot open %s: %s. Using defaults.\n", CALIBRATION_FILE, strerror(errno));
        return -1;
    }

    if (fscanf(calibration_fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Warning: invalid calibration data. Using defaults.\n");
        scale_factor = 1.0;
        offset = 0.0;
        fclose(calibration_fp);
        calibration_fp = NULL;
        return -1;
    }

    printf("Loaded calibration: scale=%.2f, offset=%.2f\n", scale_factor, offset);
    fclose(calibration_fp);
    calibration_fp = NULL;
    return 0;
}

static int save_calibration_data(void) {
    if (calibration_fp != NULL) {
        fprintf(calibration_fp, "%.2f %.2f\n", scale_factor, offset);
        fflush(calibration_fp);
        fclose(calibration_fp);
        calibration_fp = NULL;
        printf("Calibration data saved.\n");
        return 0;
    }
    return -1;
}

static void log_weight(double weight) {
    if (weight_log_fp == NULL) {
        weight_log_fp = fopen(WEIGHT_LOG_FILE, "a");
        if (weight_log_fp == NULL) {
            fprintf(stderr, "Warning: cannot open %s: %s\n", WEIGHT_LOG_FILE, strerror(errno));
            return;
        }
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(weight_log_fp, "%s, %.2f\n", timestamp, weight);
    fflush(weight_log_fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    if (load_calibration_data() != 0) {
        if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN) != 0) {
            fprintf(stderr, "Calibration failed. Exiting.\n");
            gpioTerminate();
            return 1;
        }
        save_calibration_data();
    }

    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0);

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw == -1) {
            gpioDelay(500000);
            continue;
        }

        double weight = convert_to_weight(raw);

        if (weight > WEIGHT_THRESHOLD) {
            gpioWrite(SOLENOID_PIN, 1);
            printf("Weight %.2f kg exceeds threshold. Lock engaged.\n", weight);
        } else {
            gpioWrite(SOLENOID_PIN, 0);
            printf("Weight %.2f kg below threshold. Lock released.\n", weight);
        }

        log_weight(weight);
        gpioDelay(500000);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    if (weight_log_fp != NULL) {
        fclose(weight_log_fp);
    }
    printf("Weight monitoring stopped.\n");
    return 0;
}

