#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17
#define THRESHOLD 100.0
#define POLL_INTERVAL 1.0
#define SOLENOID_DURATION 5.0
#define HX711_TIMEOUT_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int *out) {
    if (gpioSetMode(HX711_DT, PI_INPUT) < 0) return -1;
    if (gpioSetMode(HX711_SCK, PI_OUTPUT) < 0) return -1;

    uint32_t start = gpioTick();
    while (gpioRead(HX711_DT) == 1) {
        if (gpioTick() - start > HX711_TIMEOUT_US) return -2;
        gpioDelay(100);
    }

    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK, 1) < 0) return -1;
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(HX711_DT) == 1) value |= 1;
        if (gpioWrite(HX711_SCK, 0) < 0) return -1;
        gpioDelay(1);
    }

    int sign = (value & 0x800000) ? -1 : 1;
    value = (value & 0x7FFFFF) * sign;

    if (gpioWrite(HX711_SCK, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(HX711_SCK, 0) < 0) return -1;
    gpioDelay(1);

    *out = value;
    return 0;
}

static void log_event(const char *event) {
    FILE *fp = fopen("stock_events.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening stock_events.txt: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s: %s\n", ts, event);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(SOLENOID_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Kitchen Stock Monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw;
        int rc = read_hx711(&raw);
        if (rc == -2) {
            fprintf(stderr, "HX711 timeout: data line stuck high\n");
            log_event("Error: HX711 timeout");
        } else if (rc < 0) {
            fprintf(stderr, "HX711 read error: %s\n", pigpio_error(rc));
