#define LOG_FILE "security.log"
#define HX711_TIMEOUT_US 100000
#define HX711_SETTLE_US 1000
#define HX711_CLOCK_HALF_US 1

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static FILE *cal_file = NULL;

static double calibration_factor = 1.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int *out_raw) {
    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) < 0) return -1;
    if (gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) < 0) return -1;

    uint32_t start = gpioTick();
    while (gpioRead(HX711_DATA_PIN)) {
        if (gpioTick() - start > HX711_TIMEOUT_US) return -2;
        gpioDelay(HX711_CLOCK_HALF_US);
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(HX711_CLOCK_HALF_US);
        gpioWrite(HX711_CLOCK_PIN, 0);
    }

    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(HX711_CLOCK_HALF_US);
        value <<= 1;
        if (gpioRead(HX711_DATA_PIN)) value |= 1;
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(HX711_CLOCK_HALF_US);
    }

    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(HX711_CLOCK_HALF_US);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(HX711_CLOCK_HALF_US);

    if (value & 0x800000) value |= 0xFF000000;
    *out_raw = value;
    return 0;
}

static double read_weight(void) {
    int raw;
    if (read_hx711(&raw) != 0) return 0.0;
    return (double)raw / calibration_factor;
}

static int calibrate(void) {
    double known_weight;
    printf("Place a known weight on the load cell and enter its mass in kg: ");
    if (scanf("%lf", &known_weight) != 1 || known_weight <= 0.0) {
        fprintf(stderr, "Invalid input. Calibration failed.\n");
        return -1;
    }
    while (getchar() != '\n');

    int raw;
    if (read_hx711(&raw) != 0) {
        fprintf(stderr, "HX711 read error during calibration.\n");
        return -1;
    }

    calibration_factor = (double)raw / known_weight;
    printf("Calibration factor: %.2f\n", calibration_factor);

    if (cal_file) {
        fprintf(cal_file, "%.2f\n", calibration_factor);
        fflush(cal_file);
    }
    return 0;
}

static int log_event(double weight) {
