    if (gpioWrite(SOLENOID_PIN, 1) < 0) return;
    gpioDelay(5000000);
    if (gpioWrite(SOLENOID_PIN, 0) < 0) return;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return 1;
    }

    cal_file = fopen(CALIBRATION_FILE, "r");
    if (cal_file) {
        if (fscanf(cal_file, "%lf", &calibration_factor) == 1) {
            printf("Calibration factor loaded: %.2f\n", calibration_factor);
        } else {
            fprintf(stderr, "Invalid calibration file. Re-calibrating...\n");
            fclose(cal_file);
            cal_file = NULL;
        }
    }

    if (!cal_file) {
        cal_file = fopen(CALIBRATION_FILE, "w");
        if (!cal_file) {
            perror("fopen calibration");
            gpioTerminate();
            return 1;
        }
    }

    if (calibrate() != 0) {
        fprintf(stderr, "Calibration failed. Exiting.\n");
        fclose(cal_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set solenoid pin mode.\n");
        fclose(cal_file);
        gpioTerminate();
        return 1;
    }
    gpioWrite(SOLENOID_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Security system started. Press Ctrl+C to exit.\n");

    while (running) {
        double weight = read_weight();
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded! Unlocking solenoid.\n");
            unlock_solenoid();
            log_event(weight);
        }

        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_PIN, 0);
    if (log_file) fclose(log_file);
    if (cal_file) fclose(cal_file);
    gpioTerminate();
    return 0;
}

