#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* GPIO pin assignments */
#define SENSOR_LEFT   4
#define SENSOR_CENTER 17
#define SENSOR_RIGHT  27

#define MOTOR_LEFT_PWM  22
#define MOTOR_LEFT_DIR  23
#define MOTOR_RIGHT_PWM 24
#define MOTOR_RIGHT_DIR 25

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255
#define BASE_SPEED    150
#define TURN_SPEED    75
#define LOOP_DELAY_US 10000  /* 10 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_LEFT, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SENSOR_LEFT);
        return -1;
    }
    if (gpioSetMode(SENSOR_CENTER, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SENSOR_CENTER);
        return -1;
    }
    if (gpioSetMode(SENSOR_RIGHT, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SENSOR_RIGHT);
        return -1;
    }

    if (gpioSetMode(MOTOR_LEFT_PWM, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", MOTOR_LEFT_PWM);
        return -1;
    }
    if (gpioSetMode(MOTOR_LEFT_DIR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", MOTOR_LEFT_DIR);
        return -1;
    }
    if (gpioSetMode(MOTOR_RIGHT_PWM, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", MOTOR_RIGHT_PWM);
        return -1;
    }
    if (gpioSetMode(MOTOR_RIGHT_DIR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", MOTOR_RIGHT_DIR);
        return -1;
    }

    if (gpioSetPWMfrequency(MOTOR_LEFT_PWM, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d\n", MOTOR_LEFT_PWM);
        return -1;
    }
    if (gpioSetPWMfrequency(MOTOR_RIGHT_PWM, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d\n", MOTOR_RIGHT_PWM);
        return -1;
    }

    if (gpioSetPWMrange(MOTOR_LEFT_PWM, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d\n", MOTOR_LEFT_PWM);
        return -1;
    }
    if (gpioSetPWMrange(MOTOR_RIGHT_PWM, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d\n", MOTOR_RIGHT_PWM);
        return -1;
    }

    /* Ensure motors are stopped initially */
    if (gpioPWM(MOTOR_LEFT_PWM, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize PWM on GPIO%d\n", MOTOR_LEFT_PWM);
        return -1;
    }
    if (gpioPWM(MOTOR_RIGHT_PWM, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize PWM on GPIO%d\n", MOTOR_RIGHT_PWM);
        return -1;
    }
    if (gpioWrite(MOTOR_LEFT_DIR, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize direction on GPIO%d\n", MOTOR_LEFT_DIR);
        return -1;
    }
    if (gpioWrite(MOTOR_RIGHT_DIR, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize direction on GPIO%d\n", MOTOR_RIGHT_DIR);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    /* Stop motors and release GPIOs */
    gpioPWM(MOTOR_LEFT_PWM, 0);
    gpioPWM(MOTOR_RIGHT_PWM, 0);
    gpioWrite(MOTOR_LEFT_DIR, 0);
    gpioWrite(MOTOR_RIGHT_DIR, 0);

    gpioSetMode(SENSOR_LEFT, PI_INPUT);
    gpioSetMode(SENSOR_CENTER, PI_INPUT);
    gpioSetMode(SENSOR_RIGHT, PI_INPUT);
    gpioSetMode(MOTOR_LEFT_PWM, PI_INPUT);
