#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0f
#define MEASUREMENT_DELAY_US 180000
#define LOG_FILE "grow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char time_buf[32];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", time_buf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static int init_bh1750(void) {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        return -1;
    }
    if (i2cWriteByte(i2c_handle, 0x10) < 0) {
        fprintf(stderr, "Error setting BH1750 to continuous high-res mode: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_US);
    return 0;
}

static float read_lux(void) {
    if (i2c_handle < 0) return -1.0f;
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from BH1750: %s\n", strerror(errno));
        return -1.0f;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return (float)raw / 1.2f;
}

static void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    char msg[64];
    snprintf(msg, sizeof(msg), "Relay set to %s", state ? "ON" : "OFF");
    log_event(msg);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_bh1750() != 0) {
        fprintf(stderr, "BH1750 initialization failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    log_event("System started");

    while (running) {
        float lux = read_lux();
        if (lux < 0.0f) {
            log_event("Error reading lux value");
        } else {
            char msg[128];
            snprintf(msg, sizeof(msg), "Lux: %.2f", lux);
            log_event(msg);
            if (lux < LUX_THRESHOLD) {
                control_relay(1);
            } else {
                control_relay(0);
            }
        }
        gpioDelay(1000000);
    }

    control_relay(0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    log_event("System stopped");
    return 0;
}

