#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22

#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_LOCK_PULSE 1000
#define SERVO_UNLOCK_PULSE 2000
#define DEBOUNCE_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse(int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE || pulse_width > SERVO_MAX_PULSE) {
        fprintf(stderr, "Error: pulse width %d out of range [%d, %d]\n",
                pulse_width, SERVO_MIN_PULSE, SERVO_MAX_PULSE);
        return -1;
    }
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %d\n", pulse_width);
        return -1;
    }
    return 0;
}

static void lock_door(void) {
    printf("Locking door...\n");
    if (set_servo_pulse(SERVO_LOCK_PULSE) != 0) {
        fprintf(stderr, "Error: failed to set lock position\n");
    }
}

static void unlock_door(void) {
    printf("Unlocking door...\n");
    if (set_servo_pulse(SERVO_UNLOCK_PULSE) != 0) {
        fprintf(stderr, "Error: failed to set unlock position\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set lock button mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set unlock button mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set lock button pull-up\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set unlock button pull-up\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control ready. Press Ctrl+C to exit.\n");

    while (running) {
        int lock_state = gpioRead(LOCK_BUTTON);
        int unlock_state = gpioRead(UNLOCK_BUTTON);

        if (lock_state == 0) {
            lock_door();
            gpioDelay(DEBOUNCE_DELAY_US);
        }
        if (unlock_state == 0) {
            unlock_door();
            gpioDelay(DEBOUNCE_DELAY_US);
        }
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    set_servo_pulse(0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

