#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>
#include <zmq.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define ZMQ_ENDPOINT "tcp://*:5555"
#define ZMQ_TOPIC "SOUND_ALERTS"
#define POLL_INTERVAL_US 10000
#define ALARM_DURATION_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int init_gpio(struct gpiod_chip **chip, struct gpiod_line **sound_line, struct gpiod_line **led_line) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!*chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    *sound_line = gpiod_chip_get_line(*chip, SOUND_SENSOR_PIN);
    if (!*sound_line) {
        perror("gpiod_chip_get_line(sound)");
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    *led_line = gpiod_chip_get_line(*chip, ALARM_LED_PIN);
    if (!*led_line) {
        perror("gpiod_chip_get_line(led)");
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    if (gpiod_line_request_input(*sound_line, "sound_sensor") < 0) {
        perror("gpiod_line_request_input(sound)");
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(*led_line, "alarm_led", 0) < 0) {
        perror("gpiod_line_request_output(led)");
        gpiod_line_release(*sound_line);
        gpiod_chip_close(*chip);
        *chip = NULL;
        return -1;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *sound_line, struct gpiod_line *led_line) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (sound_line) {
        gpiod_line_release(sound_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static int init_zmq(void) {
    void *context = zmq_ctx_new();
    if (!context) {
        perror("zmq_ctx_new");
        return -1;
    }

    void *socket = zmq_socket(context, ZMQ_SUB);
    if (!socket) {
        perror("zmq_socket");
        zmq_ctx_destroy(context);
        return -1;
    }

    if (zmq_connect(socket, ZMQ_ENDPOINT) == -1) {
        perror("zmq_connect");
        zmq_close(socket);
        zmq_ctx_destroy(context);
        return -1;
    }

    if (zmq_setsockopt(socket, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC)) == -1) {
        perror("zmq_setsockopt");
        zmq_close(socket);
        zmq_ctx_destroy(context);
        return -1;
    }

    return (int)(long)socket;
}

static void cleanup_zmq(void *socket) {
    if (socket) {
        zmq_close((void *)(long)socket);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    if (strcmp(mode, "sound_sensor") != 0 && strcmp(mode, "alarm_node") != 0) {
        fprintf(stderr, "Invalid mode: %s (must be sound_sensor or alarm_node)\n", mode);
        return EXIT_FAILURE;
    }

    if (setup_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    if (strcmp(mode, "sound_sensor") == 0) {
        if (init_gpio(&chip, &sound_line, &led_line) != 0) {
            goto cleanup;
        }

        printf("Sound sensor mode started. Polling GPIO%d every %d us.\n", SOUND_SENSOR_PIN, POLL_INTERVAL_US);
        printf("Publishing alerts to %s on topic %s.\n", ZMQ_ENDPOINT, ZMQ_TOPIC);

        void *zmq_socket = init_zmq();
        if (!zmq_socket) {
            fprintf(stderr, "Failed to initialize ZeroMQ.\n");
            goto cleanup;
        }

        while (running) {
            int val = gpiod_line_get_value(sound_line);
            if (val < 0) {
                perror("gpiod_line_get_value");
                break;
            }

            if (val == 0) {
                char msg[64];
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                if (tm_info) {
                    strftime(msg, sizeof(msg), "%Y-%m-%d %H:%M:%S", tm_info);
                } else {
                    snprintf(msg, sizeof(msg), "unknown");
                }

                if (zmq_send(zmq_socket, msg, strlen(msg), 0) == -1) {
                    perror("zmq_send");
                    break;
                }
            }

            usleep(POLL_INTERVAL_US);
        }

        cleanup_zmq(zmq_socket);
        ret = EXIT_SUCCESS;
    } else {
        if (init_gpio(&chip, &sound_line, &led_line) != 0) {
            goto cleanup;
        }

        printf("Alarm node mode started. Subscribing to %s on topic %s.\n", ZMQ_ENDPOINT, ZMQ_TOPIC);

        void *zmq_socket = init_zmq();
        if (!zmq_socket) {
            fprintf(stderr, "Failed to initialize ZeroMQ.\n");
            goto cleanup;
        }

        while (running) {
            zmq_msg_t msg;
            int rc = zmq_msg_init(&msg);
            if (rc == -1) {
                perror("zmq_msg_init");
                break;
            }

            rc = zmq_recvmsg(zmq_socket, &msg, 0);
            if (rc == -1) {
                perror("zmq_recvmsg");
                break;
            }

            if (rc > 0) {
                printf("Alert received! Activating alarm LED for %d us.\n", ALARM_DURATION_US);
                if (gpiod_line_set_value(led_line, 1) < 0) {
                    perror("gpiod_line_set_value(led, 1)");
                    break;
                }
                usleep(ALARM_DURATION_US);
                if (gpiod_line_set_value(led_line, 0) < 0) {
                    perror("gpiod_line_set_value(led, 0)");
                    break;
                }
            }

            zmq_msg_close(&msg);
        }

        cleanup_zmq(zmq_socket);
        ret = EXIT_SUCCESS;
    }

cleanup:
    cleanup_gpio(chip, sound_line, led_line);
    return ret;
}

