static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_lengths[MAX_PULSES];
static volatile int pulse_count = 0;
static volatile int pulse_index = 0;
static MQTTClient mqtt_client = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int decode_nec(const uint32_t *pulses, int count, uint8_t *address, uint8_t *command) {
    if (count < 68) return -1;

    /* NEC frame: 9 ms mark + 4.5 ms space (header), then 32 bits of 560 us mark + 1690 us space (1) or 560 us mark + 560 us space (0) */
    if (pulses[0] < 8000 || pulses[0] > 10000) return -1;
    if (pulses[1] < 4000 || pulses[1] > 5000) return -1;

    uint32_t address_val = 0, command_val = 0;
    for (int i = 0; i < 32; i++) {
        int mark_idx = 2 + i * 2;
        int space_idx = mark_idx + 1;
        if (mark_idx >= count) return -1;
        if (space_idx >= count) return -1;

        if (pulses[mark_idx] < 400 || pulses[mark_idx] > 600) return -1;

        if (pulses[space_idx] > 1400) {
            if (pulses[space_idx] < 1800) {
                command_val |= (1u << i);
            } else {
                return -1;
            }
        } else {
            if (pulses[space_idx] > 1000) {
                address_val |= (1u << i);
            } else {
                return -1;
            }
        }
    }

    /* Validate checksum: (address | (address >> 8)) ^ command == 0xFF */
    uint8_t addr_lo = (uint8_t)(address_val & 0xFF);
    uint8_t addr_hi = (uint8_t)((address_val >> 8) & 0xFF);
    uint8_t sum = (uint8_t)((addr_lo + addr_hi) ^ command_val);
    if (sum != 0xFF) return -1;

    *address = (uint8_t)(address_val & 0xFF);
    *command = (uint8_t)command_val;
    return 0;
}

static void ir_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 0) {
        if (pulse_count < MAX_PULSES) {
            pulse_lengths[pulse_count++] = tick;
        } else {
            syslog(LOG_ERR, "IR pulse buffer overflow");
        }
    } else if (level == 1) {
        if (pulse_count > 0) {
            uint8_t address, command;
            if (decode_nec(pulse_lengths, pulse_count, &address, &command) == 0) {
                syslog(LOG_INFO, "Decoded NEC: Address=0x%02X, Command=0x%02X", address, command);

                char json[128];
                snprintf(json, sizeof(json),
                         "{\"address\":%u,\"command\":%u}",
                         address, command);

                MQTTClient_message pubmsg = MQTTClient_message_initializer;
                pubmsg.payload = json;
                pubmsg.payloadlen = (int)strlen(json);
                pubmsg.qos = 1;
                pubmsg.retained = 0;

                MQTTClient_deliveryToken token;
                int rc = MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &pubmsg, &token);
                if (rc != MQTTCLIENT_SUCCESS) {
                    syslog(LOG_ERR, "MQTT publish failed: %s", MQTTClient_strerror(rc));
                }
            }
            pulse_count = 0;
        }
    }
}

static int init_mqtt(void) {
    int rc = MQTTClient_create(&mqtt_client, MQTT_BROKER, "ir_decoder", MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTTClient_create failed: %s", MQTTClient_strerror(rc));
        return -1;
    }

    rc = MQTTClient_connect(mqtt_client);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTTClient_connect failed: %s", MQTTClient_strerror(rc));
        MQTTClient_destroy(&mqtt_client);
        return -1;
    }

    return 0;
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(IR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", IR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetPullUpDown(IR_GPIO, PI_PUD_UP) != 0) {
        syslog(LOG_ERR, "Failed to set pull-up on GPIO%d", IR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetAlertFuncEx(IR_GPIO, ir_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set alert function on GPIO%d", IR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (init_mqtt() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "IR decoder started on GPIO%d, MQTT broker %s", IR_GPIO, MQTT_BROKER);

    while (running) {
        MQTTClient_yield();
        gpioDelay(100000);
    }

    syslog(LOG_INFO, "Shutting down...");
    MQTTClient_destroy(&mqtt_client);
    gpioTerminate();
    closelog();
    return 0;
}

