#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <math.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define NUM_SENSORS     4
#define BH1750_ADDR_1  0x23
#define BH1750_ADDR_2  0x24
#define BH1750_ADDR_3  0x25
#define BH1750_ADDR_4  0x26
#define BH1750_CMD_OT_HRES 0x20
#define CONV_TIME_MS      180
#define SAMPLE_INTERVAL_S 1

static const int sensor_addresses[NUM_SENSORS] = {
    BH1750_ADDR_1, BH1750_ADDR_2, BH1750_ADDR_3, BH1750_ADDR_4
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_open_slave(int bus_fd, int addr) {
    if (ioctl(bus_fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int bus_fd, int addr, float *lux_out) {
    if (i2c_open_slave(bus_fd, addr) < 0)
        return -1;

    unsigned char cmd = BH1750_CMD_OT_HRES;
    if (write(bus_fd, &cmd, 1) != 1) {
        fprintf(stderr, "write command to 0x%02X failed: %s\n", addr, strerror(errno));
        return -1;
    }

    usleep(CONV_TIME_MS * 1000);

    unsigned char data[2];
    ssize_t n = read(bus_fd, data, 2);
    if (n != 2) {
        fprintf(stderr, "read from 0x%02X failed: got %zd bytes, %s\n",
                addr, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    unsigned int raw = ((unsigned int)data[0] << 8) | data[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int format_data(float lux[NUM_SENSORS], char *buf, size_t buflen) {
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (isnan(lux[i])) {
            snprintf(buf, buflen, "%s", "NaN");
        } else {
            snprintf(buf, buflen, "%d,%.1f", i + 1, lux[i]);
        }
        if (i < NUM_SENSORS - 1)
            strncat(buf, ";", buflen - strlen(buf) - 1);
    }
    return 0;
}

static int send_multicast(int sockfd, const char *data) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(sockfd, data, strlen(data), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "socket failed: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    char data_buf[128];

    while (g_running) {
        float lux[NUM_SENSORS];
        int error = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (bh1750_read_lux(i2c_fd, sensor_addresses[i], &lux[i]) < 0) {
                fprintf(stderr, "Sensor %d (0x%02X) read error\n", i + 1, sensor_addresses[i]);
                lux[i] = NAN;
                error = 1;
            }
        }

        if (error) {
            snprintf(data_buf, sizeof(data_buf), "ERROR");
        } else {
            format_data(lux, data_buf, sizeof(data_buf));
        }

        if (send_multicast(sockfd, data_buf) < 0) {
            fprintf(stderr, "Multicast send failed\n");
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    close(sockfd);
    close(i2c_fd);
    return 0;
}

