#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AWM7300V_ADDR  0x28
#define LOG_FILE       "airflow_log.txt"
#define SAMPLE_PERIOD  1
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_zero_length(int fd)
{
    /* Issue a zero-length I2C write to set the slave address and start a read */
    if (write(fd, NULL, 0) < 0) {
        if (errno == EREMOTEIO) {
            fprintf(stderr, "Error: sensor may be absent (ENXIO)\n");
            return -1;
        }
        if (errno == EIO) {
            fprintf(stderr, "Error: I/O error during write (EIO)\n");
            return -1;
        }
        fprintf(stderr, "Error: I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        if (errno == EIO) {
            fprintf(stderr, "Error: I/O error during read (EIO)\n");
            return -1;
        }
        fprintf(stderr, "Error: I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "Error: short read: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int read_airflow_data(int fd, float *flow_rate)
{
    uint8_t buf[2];
    int retries = 0;

