/*
 * AS7341 10-Channel Light/Color Sensor Logger for Raspberry Pi 3 Model B+
 * Uses the Linux i2c-dev kernel interface (no wiringPi).
 *
 * Wiring:
 *   AS7341 SDA -> GPIO2 (pin 3, I2C1 SDA)
 *   AS7341 SCL -> GPIO3 (pin 5, I2C1 SCL)
 *   AS7341 VDD -> 3.3 V
 *   AS7341 GND -> GND
 *
 * Build: gcc -O2 -Wall -o as7341_logger as7341_logger.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AS7341_ADDR    0x39
#define LOG_FILE       "spectral_log.csv"
#define SAMPLE_PERIOD  5  /* seconds */

/* AS7341 register addresses */
#define AS7341_ENABLE  0x80
#define AS7341_ID      0x24
#define AS7341_CFG6    0xAF
#define AS7341_CH0     0x60
#define AS7341_CH1     0x61
#define AS7341_CH2     0x62
#define AS7341_CH3     0x63
#define AS7341_CH4     0x64
#define AS7341_CH5     0x65
#define AS7341_CH6     0x66
#define AS7341_CH7     0x67
#define AS7341_CH8     0x68
#define AS7341_CLEAR   0x69
#define AS7341_NIR     0x6A

#define AS7341_ID_VAL  0x19

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8: read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int as7341_init(int fd)
{
    uint8_t id = 0;

    if (i2c_read_reg8(fd, AS7341_ID, &id) != 0)
        return -1;

    if (id != AS7341_ID_VAL) {
        fprintf(stderr, "AS7341 not detected (ID=0x%02X, expected 0x%02X)\n",
                id, AS7341_ID_VAL);
        return -1;
    }

    /* Power on */
    if (i2c_write_reg8(fd, AS7341_ENABLE, 0x01) != 0)
        return -1;
    usleep(10000);  /* 10 ms power-on delay */

    /* Configure SMUX for spectral readings (CFG6 = 0x00) */
    if (i2c_write_reg8(fd, AS7341_CFG6, 0x00) != 0)
        return -1;

    /* Enable spectral measurement (SP_EN = 1) */
    if (i2c_write_reg8(fd, AS7341_ENABLE, 0x20) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one 16-bit channel register                                    */
/* ------------------------------------------------------------------ */
static int read_channel(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t lo = 0, hi = 0;
    if (i2c_read_reg8(fd, reg, &lo) != 0)
        return -1;
    if (i2c_read_reg8(fd, reg + 1, &hi) != 0)
        return -1;
    *out = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Simplified lux approximation                                        */
/* ------------------------------------------------------------------ */
static float calculate_lux(uint16_t c, uint16_t n)
{
    /* Placeholder: replace with a proper AS7341 spectral-to-lux model */
    return (float)c + (float)n;
}

/* ------------------------------------------------------------------ */
/* Log one sample                                                      */
/* ------------------------------------------------------------------ */
static int log_sample(FILE *fp, uint16_t f1, uint16_t f2, uint16_t f3,
                      uint16_t f4, uint16_t f5, uint16_t f6,
                      uint16_t f7, uint16_t f8, uint16_t clear,
                      uint16_t nir, float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
                ts, f1, f2, f3, f4, f5, f6, f7, f8, clear, nir, lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                AS7341_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (as7341_init(g_i2c_fd) != 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
        fflush(g_log_fp);
    }

    printf("AS7341 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;
        float lux = 0.0f;

        if (read_channel(g_i2c_fd, AS7341_CH1, &f1) != 0 ||
            read_channel(g_i2c_fd, AS7341_CH2, &f2) != 0 ||
            read_channel(g_i2c_fd, AS7341_CH3, &f3) != 0 ||
            read_channel(g_i2c_fd, AS7341_CH4, &f4) != 0 ||
            read_channel(g_i2c_fd, AS7341_CH5, &f5) != 0 ||
            read_channel(g_i2c_fd, AS7341_CH6, &f6) != 0 ||
            read_channel(g_i2c_fd, AS7341_CH7, &f7) != 0 ||
            read_channel(g_i2c_fd, AS7341_CH8, &f8) != 0 ||
            read_channel(g_i2c_fd, AS7341_CLEAR, &clear) != 0 ||
            read_channel(g_i2c_fd, AS7341_NIR, &nir) != 0) {
            fprintf(stderr, "Sensor read error — continuing.\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        lux = calculate_lux(clear, nir);

        if (log_sample(g_log_fp, f1, f2, f3, f4, f5, f6, f7, f8,
                       clear, nir, lux) != 0) {
            fprintf(stderr, "Logging failed — continuing.\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

