#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define ACCEL_REG 0x28
#define ACCEL_LEN 6
#define SCALE_FACTOR 0.000244f
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *csv_fp = NULL;
static FILE *err_fp = NULL;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int interval = DEFAULT_INTERVAL;
static char filename[256] = DEFAULT_FILENAME;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    if (!err_fp) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(err_fp, "%s: %s (errno: %s)\n", ts, msg, strerror(errno));
    fflush(err_fp);
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t reg = ACCEL_REG;
    uint8_t buf[ACCEL_LEN];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_byte(fd, reg) < 0) {
            log_error("I2C write (register select) failed");
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        usleep(1000);
        if (i2c_read_bytes(fd, buf, ACCEL_LEN) < 0) {
            log_error("I2C read failed");
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
        int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
        int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
        *x = (float)raw_x * SCALE_FACTOR;
        *y = (float)raw_y * SCALE_FACTOR;
        *z = (float)raw_z * SCALE_FACTOR;
        return 0;
    }
    return -1;
}

static int log_data(FILE *fp, float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z) < 0) return -1;
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (csv_fp) { fclose(csv_fp); csv_fp = NULL; }
    if (err_fp) { fclose(err_fp); err_fp = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a': i2c_address = (int)strtol(optarg, NULL, 0); break;
            case 'i': interval = atoi(optarg); break;
            case 'f': strncpy(filename, optarg, sizeof(filename) - 1); filename[sizeof(filename) - 1] = '\0'; break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_addr] [-i interval] [-f filename]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    err_fp = fopen("seismic_error.log", "a");
    if (!err_fp) { perror("fopen error.log"); return EXIT_FAILURE; }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open /dev/i2c-1");
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        log_error("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    csv_fp = fopen(filename, "a");
    if (!csv_fp) {
        log_error("Failed to open CSV file");
        cleanup();
        return EXIT_FAILURE;
    }
    fseek(csv_fp, 0, SEEK_END);
    if (ftell(csv_fp) == 0) {
        fprintf(csv_fp, "timestamp,x_g,y_g,z_g\n");
        fflush(csv_fp);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float x, y, z;
    while (running) {
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            if (log_data(csv_fp, x, y, z) != 0) {
                log_error("Failed to write to CSV");
            }
        } else {
            log_error("Failed to read acceleration data after retries");
        }
        sleep(interval);
    }

    cleanup();
    return EXIT_SUCCESS;
}

