#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR 0x23
#define I2C_DEVICE "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define MULTICAST_TTL 1
#define BH1750_POWER_ON 0x01
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_MEASUREMENT_TIME_MS 180
#define POLL_INTERVAL_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, unsigned char byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, unsigned char *buf, int len) {
    int total = 0;
    while (total < len) {
        int n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read error: unexpected EOF\n");
            return -1;
        }
        total += n;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_POWER_ON) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, BH1750_CONTINUOUS_HIGH_RES_MODE) < 0) return -1;
    usleep(BH1750_MEASUREMENT_TIME_MS * 1000);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    unsigned char buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(float lux) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }
    int ttl = MULTICAST_TTL;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt IP_MULTICAST_TTL");
        close(sockfd);
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);
    char message[64];
    int len = snprintf(message, sizeof(message), "%.2f", lux);
    if (sendto(sockfd, message, len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        close(sockfd);
        return -1;
    }
    close(sockfd);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_DEVICE);
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }
    if (bh1750_init(fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed\n");
        close(fd);
        return 1;
    }
    printf("BH1750 initialized. Reading every %d ms. Press Ctrl+C to exit.\n", POLL_INTERVAL_MS);
    while (running) {
        float lux;
        if (bh1750_read_lux(fd, &lux) < 0) {
            fprintf(stderr, "Read failed, retrying in 1 s...\n");
            sleep(1);
            continue;
        }
        printf("Lux: %.2f\n", lux);
        if (send_multicast(lux) < 0) {
            fprintf(stderr, "Multicast send failed\n");
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }
    close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

