        perror("sendto");
        close(sockfd);
        return -1;
    }
    close(sockfd);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_DEVICE);
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }
    if (bh1750_init(fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed\n");
        close(fd);
        return 1;
    }
    printf("BH1750 initialized. Reading every %d ms. Press Ctrl+C to exit.\n", POLL_INTERVAL_MS);
    while (running) {
        float lux;
        if (bh1750_read_lux(fd, &lux) < 0) {
            fprintf(stderr, "Read failed, retrying in 1 s...\n");
            sleep(1);
            continue;
        }
        printf("Lux: %.2f\n", lux);
        if (send_multicast(lux) < 0) {
            fprintf(stderr, "Multicast send failed\n");
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }
    close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

