#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define CSV_FILE "radar_data.csv"
#define MAX_FRAME_SIZE 8192
#define MAGIC_WORD_SIZE 8
#define TLV_HEADER_SIZE 8
#define MAX_OBJECTS 100

static volatile sig_atomic_t terminate = 0;
static int uart_handle = -1;
static FILE *csv_file = NULL;

typedef struct {
    float range_m;
    float velocity_mps;
} RadarData;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int uart_init(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART %s: %d\n", UART_DEVICE, uart_handle);
        return -1;
    }
    return 0;
}

static int csv_init(void) {
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Error opening CSV file %s\n", CSV_FILE);
        return -1;
    }
    fseek(csv_file, 0, SEEK_END);
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }
    return 0;
}

static void uart_close(void) {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
}

static void csv_close(void) {
    if (csv_file) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
}

static int find_magic_word(const uint8_t *buf, int len) {
    if (len < MAGIC_WORD_SIZE) return -1;
    for (int i = 0; i <= len - MAGIC_WORD_SIZE; i++) {
        uint32_t word0 = (uint32_t)buf[i] | ((uint32_t)buf[i+1] << 8);
        uint32_t word1 = (uint32_t)buf[i+2] | ((uint32_t)buf[i+3] << 8);
        uint32_t word2 = (uint32_t)buf[i+4] | ((uint32_t)buf[i+5] << 8);
        uint32_t word3 = (uint32_t)buf[i+6] | ((uint32_t)buf[i+7] << 8);
        if (word0 == 0x02040306 && word1 == 0x08050709) {
            return i;
        }
    }
    return -1;
}

static int process_frame(const uint8_t *frame, int frame_len) {
    if (frame_len < TLV_HEADER_SIZE) {
        fprintf(stderr, "Frame too short for TLV header\n");
        return -1;
    }
    uint32_t total_packet_len = (uint32_t)frame[4] | ((uint32_t)frame[5] << 8) |
                                ((uint32_t)frame[6] << 16) | ((uint32_t)frame[7] << 24);
    if (total_packet_len > MAX_FRAME_SIZE) {
        fprintf(stderr, "Invalid total packet length %u\n", total_packet_len);
        return -1;
    }
    if (total_packet_len > frame_len) {
        fprintf(stderr, "Incomplete frame, need %u bytes\n", total_packet_len);
        return -1;
    }
    int num_detected_obj = (frame_len - TLV_HEADER_SIZE) / 16;
    if (num_detected_obj > MAX_OBJECTS) num_detected_obj = MAX_OBJECTS;
    for (int i = 0; i < num_detected_obj; i++) {
        int offset = TLV_HEADER_SIZE + i * 16;
        uint16_t range_idx = (uint16_t)frame[offset] | ((uint16_t)frame[offset+1] << 8);
        uint16_t doppler_idx = (uint16_t)frame[offset+2] | ((uint16_t)frame[offset+3] << 8);
        uint16_t peak_val = (uint16_t)frame[offset+4] | ((uint16_t)frame[offset+5] << 8);
        uint16_t x = (uint16_t)frame[offset+6] | ((uint16_t)frame[offset+7] << 8);
        uint16_t y = (uint16_t)frame[offset+8] | ((uint16_t)frame[offset+9] << 8);
        uint16_t z = (uint16_t)frame[offset+10] | ((uint16_t)frame[offset+11] << 8);
        uint16_t velocity = (uint16_t)frame[offset+12] | ((uint16_t)frame[offset+13] << 8);
        float range_m = (float)range_idx * 0.04f;
        float velocity_mps = (float)velocity * 0.04f;
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(csv_file, "%s,%d,%.2f,%.2f\n", ts, i, range_m, velocity_mps);
        fflush(csv_file);
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (uart_init() != 0) {
        gpioTerminate();
        return 1;
    }
    if (csv_init() != 0) {
        uart_close();
        gpioTerminate();
        return 1;
    }
    uint8_t *frame_buf = malloc(MAX_FRAME_SIZE);
    if (!frame_buf) {
        fprintf(stderr, "Memory allocation failed\n");
        uart_close();
        csv_close();
        gpioTerminate();
        return 1;
    }
    int frame_len = 0;
    while (!terminate) {
        int bytes_read = serRead(uart_handle, (char *)(frame_buf + frame_len), MAX_FRAME_SIZE - frame_len);
        if (bytes_read < 0) {
            fprintf(stderr, "UART read error\n");
            break;
        }
        if (bytes_read == 0) {
            gpioDelay(10000);
            continue;
        }
        frame_len += bytes_read;
        int mw_pos = find_magic_word(frame_buf, frame_len);
        if (mw_pos < 0) {
            if (frame_len > MAGIC_WORD_SIZE) {
                memmove(frame_buf, frame_buf + frame_len - MAGIC_WORD_SIZE, MAGIC_WORD_SIZE);
                frame_len = MAGIC_WORD_SIZE;
            }
            continue;
        }
        if (mw_pos > 0) {
            memmove(frame_buf, frame_buf + mw_pos, frame_len - mw_pos);
            frame_len -= mw_pos;
        }
        if (frame_len < MAGIC_WORD_SIZE) continue;
        uint32_t total_packet_len = (uint32_t)frame_buf[MAGIC_WORD_SIZE+4] |
                                    ((uint32_t)frame_buf[MAGIC_WORD_SIZE+5] << 8) |
                                    ((uint32_t)frame_buf[MAGIC_WORD_SIZE+6] << 16) |
                                    ((uint32_t)frame_buf[MAGIC_WORD_SIZE+7] << 24);
        if (total_packet_len > MAX_FRAME_SIZE) {
            fprintf(stderr, "Invalid total packet length %u\n", total_packet_len);
            frame_len = 0;
            continue;
        }
        if (frame_len < (int)total_packet_len) {
            int need = total_packet_len - frame_len;
            int r = serRead(uart_handle, (char *)(frame_buf + frame_len), need);
            if (r < 0) {
                fprintf(stderr, "UART read error during frame\n");
                break;
            }
            if (r == 0) {
                gpioDelay(10000);
                continue;
            }
            frame_len += r;
        }
        process_frame(frame_buf, total_packet_len);
        frame_len = 0;
    }
    free(frame_buf);
    uart_close();
    csv_close();
    gpioTerminate();
    return 0;
}

