        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5; /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int parse_timestamp(const char *raw, char *buf, size_t buf_size) {
    time_t rawtime = 0;
    if (sscanf(raw, "%ld", &rawtime) != 1) {
        return -1;
    }
    struct tm *timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }
    if (strftime(buf, buf_size, "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int parse_range(const char *raw, float *range) {
    char *endptr = NULL;
    float val = strtof(raw, &endptr);
    if (endptr == raw || *endptr != '\0') {
        return -1;
    }
    *range = val;
    return 0;
}

static void log_detection(const char *timestamp, float range) {
    printf("Timestamp: %s, Range: %.2f meters\n", timestamp, range);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    g_uart_fd = init_uart(UART_DEVICE);
    if (g_uart_fd < 0) {
        return EXIT_FAILURE;
    }

    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    char read_buf[READ_BUF_SIZE];

    while (g_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(g_uart_fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = READ_TIMEOUT_SEC;
        timeout.tv_usec = 0;

        int sel = select(g_uart_fd + 1, &readfds, NULL, NULL, &timeout);
        if (sel < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "select() error: %s\n", strerror(errno));
            break;
        }

        if (sel == 0) {
            continue;
        }

        if (FD_ISSET(g_uart_fd, &readfds)) {
            ssize_t n = read(g_uart_fd, read_buf, sizeof(read_buf) - 1);
            if (n < 0) {
                if (errno == EAGAIN || errno == EWOULDBLOCK) {
                    continue;
                }
                fprintf(stderr, "read() error: %s\n", strerror(errno));
                break;
            }
            if (n == 0) {
                fprintf(stderr, "UART closed by peer\n");
                break;
            }

            for (ssize_t i = 0; i < n; i++) {
                char c = read_buf[i];
                if (c == '\n') {
                    if (line_len > 0) {
                        line_buf[line_len] = '\0';
                        char *newline = strchr(line_buf, '\n');
                        if (newline) {
                            *newline = '\0';
                        }
                        char timestamp[TIMESTAMP_BUF_SIZE];
                        float range = 0.0f;
                        if (parse_timestamp(line_buf, timestamp, sizeof(timestamp)) == 0 &&
                            parse_range(line_buf, &range) == 0) {
                            log_detection(timestamp, range);
                        } else {
                            fprintf(stderr, "Invalid data: %s\n", line_buf);
                        }
                        line_len = 0;
                    }
                } else if (c != '\r') {
                    if (line_len < LINE_BUF_SIZE - 1) {
                        line_buf[line_len++] = c;
                    } else {
                        fprintf(stderr, "Line buffer overflow, discarding\n");
                        line_len = 0;
                    }
                }
            }
        }
    }

    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    return EXIT_SUCCESS;
}

