#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE 115200
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int serial_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", LEFT_SENSOR_PIN);
        return -1;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", MIDDLE_SENSOR_PIN);
        return -1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", RIGHT_SENSOR_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO%d.\n", LEFT_SENSOR_PIN);
    }
    if (gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO%d.\n", MIDDLE_SENSOR_PIN);
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO%d.\n", RIGHT_SENSOR_PIN);
    }

    return 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", pin);
        return -1;
    }
    return value;
}

static void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed.\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
    fflush(stdout);
}

static int send_emergency_stop(void) {
    const char *msg = "EMERGENCY STOP!\n";
    int bytes_written = write(serial_fd, msg, strlen(msg));
    if (bytes_written < 0) {
        perror("Error: write to serial port failed");
        return -1;
    }
    if (bytes_written != (int)strlen(msg)) {
        fprintf(stderr, "Warning: partial write to serial port (%d of %zu bytes).\n",
                bytes_written, strlen(msg));
    }
    return 0;
}

static void cleanup(void) {
    if (serial_fd >= 0) {
        close(serial_fd);
        serial_fd = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: failed to register SIGTERM handler");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    serial_fd = serOpen(SERIAL_PORT, BAUD_RATE, 0);
    if (serial_fd < 0) {
        fprintf(stderr, "Error: failed to open serial port %s.\n", SERIAL_PORT);
        gpioTerminate();
        return 1;
    }

    printf("Monitoring KY-033 3-Way Tracking Sensor on GPIO%d, GPIO%d, GPIO%d.\n",
           LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("Serial output on %s at %d baud. Press Ctrl+C to exit.\n",
           SERIAL_PORT, BAUD_RATE);
    fflush(stdout);

    while (running) {
        int left = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Error: sensor read failure, continuing.\n");
        } else {
            log_sensor_data(left, middle, right);

            if (left == 0 && middle == 0 && right == 0) {
                if (send_emergency_stop() != 0) {
                    fprintf(stderr, "Warning: failed to send emergency stop.\n");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

